CREATE POLICY runtime_artifact_source_installation ON control.runtime_artifact_source_verifier_key
 TO openpc_control_owner,openpc_control_key_governor USING(true) WITH CHECK(true);
DROP TRIGGER IF EXISTS runtime_artifact_source_installation ON control.runtime_artifact_source_verifier_key;
CREATE TRIGGER runtime_artifact_source_installation BEFORE INSERT OR UPDATE OR DELETE ON control.runtime_artifact_source_verifier_key
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_archive_installation();

CREATE OR REPLACE FUNCTION openpc.guard_runtime_artifact_source_installation()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF NEW.archive_custody IS NOT NULL AND (
  NEW.custody_root->>'consumer_profile' IS DISTINCT FROM 'openpc:local-runtime-source-consumers:v2'
  OR jsonb_typeof(NEW.archive_custody) IS DISTINCT FROM 'object'
  OR NEW.archive_custody IS DISTINCT FROM jsonb_build_object('database_role',NEW.archive_custody->'database_role','stream_id',NEW.archive_custody->'stream_id','keys',NEW.archive_custody->'keys')
  OR jsonb_typeof(NEW.archive_custody->'keys') IS DISTINCT FROM 'object'
  OR coalesce(NEW.archive_custody->>'stream_id','') !~ '^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
  OR NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname=NEW.archive_custody->>'database_role' AND r.rolcanlogin
   AND NOT r.rolsuper AND NOT r.rolbypassrls AND NOT r.rolcreaterole AND NOT r.rolcreatedb AND NOT r.rolreplication
   AND pg_has_role(r.oid,'openpc_control_worker','USAGE')
   AND shobj_description(r.oid,'pg_authid')::jsonb=jsonb_build_object('installation',jsonb_build_object('participant_id',NEW.participant_id::text,
 'privacy_domain_id',NEW.privacy_domain_id::text,'source_owner_id',NEW.source_owner_id::text,
 'source_file_binding',encode(NEW.source_file_binding,'hex')),'root',NEW.custody_root,'archive',NEW.archive_custody)))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-INSTALLATION-UNAVAILABLE'; END IF;
 IF NEW.custody_root IS NOT NULL AND (
  NEW.custody_root IS DISTINCT FROM jsonb_build_object(
   'generation_id',NEW.custody_root->>'generation_id',
   'journal_binding',NEW.custody_root->>'journal_binding',
   'retained_root_binding',NEW.custody_root->>'retained_root_binding',
   'consumer_profile',NEW.custody_root->>'consumer_profile') ||
   CASE WHEN NEW.custody_root->>'consumer_profile'='openpc:local-runtime-source-consumers:v2'
    THEN jsonb_build_object('database',openpc.runtime_artifact_database_identity()) ELSE '{}'::jsonb END
  OR coalesce(NEW.custody_root->>'consumer_profile','') NOT IN ('openpc:local-runtime-source-consumers:v1','openpc:local-runtime-source-consumers:v2')
  OR coalesce(NEW.custody_root->>'generation_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR coalesce(NEW.custody_root->>'journal_binding','') !~ '^[0-9a-f]{64}$'
  OR coalesce(NEW.custody_root->>'retained_root_binding','') !~ '^[0-9a-f]{64}$'
  OR NEW.custody_root->>'journal_binding'=NEW.custody_root->>'retained_root_binding')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 -- Rooted custody is installed with actual first trust. Existing scopes keep
 -- legacy custody; neither this birth pin nor an empty scope proves non-use.
 IF NEW.custody_root IS NOT NULL AND (
  NOT EXISTS(SELECT 1 FROM control.participant p WHERE p.participant_id=NEW.participant_id
    AND p.root_privacy_domain_id=NEW.privacy_domain_id AND p.xmin=pg_current_xact_id()::xid)
  OR NOT EXISTS(SELECT 1 FROM control.privacy_domain p WHERE p.participant_id=NEW.participant_id
    AND p.privacy_domain_id=NEW.privacy_domain_id AND p.xmin=pg_current_xact_id()::xid)
  OR EXISTS(SELECT 1 FROM control.runtime_artifact_source s WHERE s.participant_id=NEW.participant_id
    AND s.privacy_domain_id=NEW.privacy_domain_id))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-GENESIS-REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname=NEW.database_role AND r.rolcanlogin
  AND NOT r.rolsuper AND NOT r.rolbypassrls AND NOT r.rolcreaterole AND NOT r.rolcreatedb
  AND pg_has_role(r.oid,'openpc_control_worker','USAGE')
  AND NOT pg_has_role(r.oid,'openpc_control_runtime','MEMBER')
  AND NOT pg_has_role(r.oid,'openpc_control_owner','MEMBER')
  AND NOT pg_has_role(r.oid,'openpc_control_key_governor','MEMBER'))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS runtime_artifact_source_binding ON control.runtime_artifact_source;
CREATE TRIGGER runtime_artifact_source_binding BEFORE INSERT ON control.runtime_artifact_source
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_runtime_artifact_source_installation();

CREATE OR REPLACE FUNCTION openpc.lock_runtime_artifact_source_custody()
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
  OR current_setting('session_replication_role')<>'origin'
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND NOT rolsuper AND NOT rolbypassrls)
  OR NOT pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_READ_RESOURCE-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||openpc.current_participant_id()::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-release-catalog',0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('module-admission:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
END $$;

CREATE OR REPLACE FUNCTION openpc.runtime_artifact_source_admission(a control.runtime_artifact_source_disposition)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.runtime_artifact_source; receipt control.audit_occurrence;
BEGIN
 -- This assertion belongs to the governed mutation owner. Missing registration,
 -- grants or admission validation is an error, never an empty custody inventory.
 PERFORM openpc.assert_runtime_artifact_source_disposition_committed(a);
 SELECT * INTO STRICT s FROM control.runtime_artifact_source WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND source_owner_id=a.source_owner_id;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND operation_id=a.operation_id AND aggregate_id=a.disposition_id
  AND aggregate_type='runtime-artifact-disposition' AND profile_id='pc.control.runtime-artifact.disposition'
  AND catalog_operation_id='CFG-OP-DISPOSE-RUNTIME-ARTIFACT-SOURCE';
 RETURN jsonb_build_object('installation',jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex')),'disposition_id',a.disposition_id::text,
  'operation_id',a.operation_id::text,'input_id',a.runtime_configuration_input_id::text,
  'configuration_digest',encode(a.configuration_digest,'hex'),
  'admission_receipt_digest',encode(receipt.receipt_digest,'hex'),'selection_digest',encode(a.selection_digest,'hex'));
END $$;

CREATE OR REPLACE FUNCTION openpc.read_runtime_artifact_source_admissions(installation jsonb,public_key bytea)
RETURNS TABLE(admission jsonb,signed_denial bytea)
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.runtime_artifact_source; a control.runtime_artifact_source_disposition;
BEGIN
 PERFORM openpc.lock_runtime_artifact_source_custody();
 SELECT * INTO STRICT s FROM control.runtime_artifact_source
  WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id()
   AND source_owner_id=(installation->>'source_owner_id')::uuid;
 IF installation IS DISTINCT FROM jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex')) OR public_key IS DISTINCT FROM s.source_public_key
  OR session_user<>s.database_role OR NOT openpc.runtime_artifact_source_key_installed(s.source_owner_id)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF (SELECT count(*) FROM control.runtime_artifact_source_disposition WHERE participant_id=s.participant_id
  AND privacy_domain_id=s.privacy_domain_id AND source_owner_id=s.source_owner_id)>4096
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOR a IN SELECT d.* FROM control.runtime_artifact_source_disposition d WHERE d.participant_id=s.participant_id
  AND d.privacy_domain_id=s.privacy_domain_id AND d.source_owner_id=s.source_owner_id
  ORDER BY d.admitted_at,d.disposition_id LOOP
  IF EXISTS(SELECT 1 FROM control.runtime_artifact_source_disposition d WHERE d.disposition_id=a.disposition_id
    AND d.xmin=pg_current_xact_id()::xid)
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  admission:=openpc.runtime_artifact_source_admission(a);
  SELECT d.signed_denial INTO signed_denial FROM control.runtime_artifact_source_denial d
   WHERE d.participant_id=a.participant_id AND d.privacy_domain_id=a.privacy_domain_id AND d.disposition_id=a.disposition_id;
  RETURN NEXT;
 END LOOP;
END $$;

-- Installation key existence is visible through a scoped boolean only. The
-- secret never leaves the definer that verifies the native transaction MAC.
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_source_key_installed(source_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
 SELECT EXISTS(SELECT 1 FROM control.runtime_artifact_source_verifier_key k JOIN control.runtime_artifact_source s
  USING(participant_id,privacy_domain_id,source_owner_id) WHERE k.participant_id=openpc.current_participant_id()
  AND k.privacy_domain_id=openpc.current_privacy_domain_id() AND k.source_owner_id=source_id AND s.database_role=session_user)
$$;
ALTER FUNCTION openpc.runtime_artifact_source_key_installed(uuid) OWNER TO openpc_control_owner;

CREATE OR REPLACE FUNCTION openpc.verify_runtime_artifact_source_commit(source_id uuid,wire bytea,nonce bytea,mac bytea)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE secret bytea; expected bytea; different integer:=0;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF octet_length(nonce) IS DISTINCT FROM 32 OR octet_length(mac) IS DISTINCT FROM 32
  OR octet_length(wire) NOT BETWEEN 1 AND 8192 OR wire IS NULL
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_READ_RESOURCE-V1'
  OR NOT pg_has_role(session_user,'openpc_control_worker','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT k.verifier_secret INTO STRICT secret FROM control.runtime_artifact_source_verifier_key k
  JOIN control.runtime_artifact_source s USING(participant_id,privacy_domain_id,source_owner_id)
  WHERE k.participant_id=openpc.current_participant_id() AND k.privacy_domain_id=openpc.current_privacy_domain_id()
   AND k.source_owner_id=source_id AND s.database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_RUNTIME_ARTIFACT_SOURCE_DENIAL_COMMIT_V1'||pg_current_xact_id()::text
  ||encode(sha256(wire),'hex'),'UTF8')||nonce,secret,'sha256');
 FOR n IN 0..31 LOOP different:=different | (get_byte(expected,n) # get_byte(mac,n)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
END $$;
ALTER FUNCTION openpc.verify_runtime_artifact_source_commit(uuid,bytea,bytea,bytea) OWNER TO openpc_control_owner;


CREATE OR REPLACE FUNCTION openpc.assert_runtime_artifact_source_non_use(
 a control.runtime_artifact_source_disposition,proof jsonb)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE s control.runtime_artifact_source; input control.runtime_configuration_input; h text;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT s FROM control.runtime_artifact_source WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND source_owner_id=a.source_owner_id;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND runtime_configuration_input_id=a.runtime_configuration_input_id;
 IF a.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR a.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR s.database_role IS DISTINCT FROM session_user OR s.custody_root IS NULL
  OR s.custody_root->>'consumer_profile' IS DISTINCT FROM 'openpc:local-runtime-source-consumers:v2'
  OR input.configuration_digest IS DISTINCT FROM a.configuration_digest
  OR input.configuration_digest IS DISTINCT FROM sha256(input.configuration_cbor)
  OR proof IS DISTINCT FROM jsonb_build_object('profile','openpc:runtime-artifact-source-non-use:v1',
   'binding',s.custody_root,'input',jsonb_build_object('input_id',input.runtime_configuration_input_id::text,
    'module_installation_id',input.module_installation_id::text,
    'module_configuration_generation_id',input.module_configuration_generation_id::text,
    'configuration_digest',encode(input.configuration_digest,'hex')),
   'pending_digest',proof->'pending_digest','committed_digest',proof->'committed_digest',
   'history_sequence',proof->'history_sequence','history_head_digest',proof->'history_head_digest',
   'retained_head_digest',proof->'retained_head_digest','consumers',jsonb_build_array(
    'RuntimeTargetEffect','TargetDispositionIssuance','DispositionBootstrapRestore','CiglReconciliation',
    'SettledTransport','PriorBootstrapBinding','CiglInvalidation','NoEffectSuspension','TargetHandoff'))
  OR jsonb_typeof(proof->'history_sequence') IS DISTINCT FROM 'number'
  OR coalesce(proof->>'history_sequence','') !~ '^[0-9]{1,4}$'
  OR (proof->>'history_sequence')::integer NOT BETWEEN 2 AND 4096
  OR proof->>'pending_digest'=proof->>'committed_digest'
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-NON-USE-UNPROVEN'; END IF;
 FOREACH h IN ARRAY ARRAY['pending_digest','committed_digest','history_head_digest','retained_head_digest'] LOOP
  IF jsonb_typeof(proof->h) IS DISTINCT FROM 'string' OR coalesce(proof->>h,'') !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-NON-USE-UNPROVEN'; END IF;
 END LOOP;
END $$;
ALTER FUNCTION openpc.assert_runtime_artifact_source_non_use(control.runtime_artifact_source_disposition,jsonb) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.assert_runtime_artifact_source_non_use(control.runtime_artifact_source_disposition,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_runtime_artifact_source_non_use(control.runtime_artifact_source_disposition,jsonb) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.runtime_artifact_source_denial_claims_bytes(value jsonb)
RETURNS bytea LANGUAGE sql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT convert_to((CASE WHEN jsonb_typeof(value)='object' AND (value) ?& ARRAY['version','admission','sequence','previous_denial_digest','recovery','custody']::text[]
    AND (value)-ARRAY['version','admission','sequence','previous_denial_digest','recovery','custody']::text[]='{}'::jsonb THEN '{'||'"version":'||(CASE WHEN jsonb_typeof((value->'version'))='number' AND ((value->'version'))::text ~ '^(0|[1-9][0-9]{0,19})$'
      AND ((value->'version'))::numeric BETWEEN 0 AND 18446744073709551615 THEN ((value->'version'))::text END)||','||'"admission":'||(CASE WHEN jsonb_typeof((value->'admission'))='object' AND ((value->'admission')) ?& ARRAY['installation','disposition_id','operation_id','input_id','configuration_digest','admission_receipt_digest','selection_digest']::text[]
    AND ((value->'admission'))-ARRAY['installation','disposition_id','operation_id','input_id','configuration_digest','admission_receipt_digest','selection_digest']::text[]='{}'::jsonb THEN '{'||'"installation":'||(CASE WHEN jsonb_typeof(((value->'admission')->'installation'))='object' AND (((value->'admission')->'installation')) ?& ARRAY['participant_id','privacy_domain_id','source_owner_id','source_file_binding']::text[]
    AND (((value->'admission')->'installation'))-ARRAY['participant_id','privacy_domain_id','source_owner_id','source_file_binding']::text[]='{}'::jsonb THEN '{'||'"participant_id":'||(CASE WHEN jsonb_typeof((((value->'admission')->'installation')->'participant_id'))='string' THEN ((((value->'admission')->'installation')->'participant_id'))::text END)||','||'"privacy_domain_id":'||(CASE WHEN jsonb_typeof((((value->'admission')->'installation')->'privacy_domain_id'))='string' THEN ((((value->'admission')->'installation')->'privacy_domain_id'))::text END)||','||'"source_owner_id":'||(CASE WHEN jsonb_typeof((((value->'admission')->'installation')->'source_owner_id'))='string' THEN ((((value->'admission')->'installation')->'source_owner_id'))::text END)||','||'"source_file_binding":'||(CASE WHEN jsonb_typeof((((value->'admission')->'installation')->'source_file_binding'))='string' THEN ((((value->'admission')->'installation')->'source_file_binding'))::text END)||'}' END)||','||'"disposition_id":'||(CASE WHEN jsonb_typeof(((value->'admission')->'disposition_id'))='string' THEN (((value->'admission')->'disposition_id'))::text END)||','||'"operation_id":'||(CASE WHEN jsonb_typeof(((value->'admission')->'operation_id'))='string' THEN (((value->'admission')->'operation_id'))::text END)||','||'"input_id":'||(CASE WHEN jsonb_typeof(((value->'admission')->'input_id'))='string' THEN (((value->'admission')->'input_id'))::text END)||','||'"configuration_digest":'||(CASE WHEN jsonb_typeof(((value->'admission')->'configuration_digest'))='string' THEN (((value->'admission')->'configuration_digest'))::text END)||','||'"admission_receipt_digest":'||(CASE WHEN jsonb_typeof(((value->'admission')->'admission_receipt_digest'))='string' THEN (((value->'admission')->'admission_receipt_digest'))::text END)||','||'"selection_digest":'||(CASE WHEN jsonb_typeof(((value->'admission')->'selection_digest'))='string' THEN (((value->'admission')->'selection_digest'))::text END)||'}' END)||','||'"sequence":'||(CASE WHEN jsonb_typeof((value->'sequence'))='number' AND ((value->'sequence'))::text ~ '^(0|[1-9][0-9]{0,19})$'
      AND ((value->'sequence'))::numeric BETWEEN 0 AND 18446744073709551615 THEN ((value->'sequence'))::text END)||','||'"previous_denial_digest":'||(CASE WHEN (value->'previous_denial_digest')='null'::jsonb THEN 'null' ELSE (CASE WHEN jsonb_typeof((value->'previous_denial_digest'))='string' THEN ((value->'previous_denial_digest'))::text END) END)||','||'"recovery":'||(CASE WHEN jsonb_typeof((value->'recovery'))='string' THEN ((value->'recovery'))::text END)||','||'"custody":'||(CASE WHEN jsonb_typeof((value->'custody'))='object' AND ((value->'custody')) ?& ARRAY['profile','binding','input','pending_digest','committed_digest','history_sequence','history_head_digest','retained_head_digest','consumers']::text[]
    AND ((value->'custody'))-ARRAY['profile','binding','input','pending_digest','committed_digest','history_sequence','history_head_digest','retained_head_digest','consumers']::text[]='{}'::jsonb THEN '{'||'"profile":'||(CASE WHEN jsonb_typeof(((value->'custody')->'profile'))='string' THEN (((value->'custody')->'profile'))::text END)||','||'"binding":'||(CASE WHEN jsonb_typeof(((value->'custody')->'binding'))='object' AND (((value->'custody')->'binding')) ?& ARRAY['generation_id','journal_binding','retained_root_binding','consumer_profile','database']::text[]
    AND (((value->'custody')->'binding'))-ARRAY['generation_id','journal_binding','retained_root_binding','consumer_profile','database']::text[]='{}'::jsonb THEN '{'||'"generation_id":'||(CASE WHEN jsonb_typeof((((value->'custody')->'binding')->'generation_id'))='string' THEN ((((value->'custody')->'binding')->'generation_id'))::text END)||','||'"journal_binding":'||(CASE WHEN jsonb_typeof((((value->'custody')->'binding')->'journal_binding'))='string' THEN ((((value->'custody')->'binding')->'journal_binding'))::text END)||','||'"retained_root_binding":'||(CASE WHEN jsonb_typeof((((value->'custody')->'binding')->'retained_root_binding'))='string' THEN ((((value->'custody')->'binding')->'retained_root_binding'))::text END)||','||'"consumer_profile":'||(CASE WHEN jsonb_typeof((((value->'custody')->'binding')->'consumer_profile'))='string' THEN ((((value->'custody')->'binding')->'consumer_profile'))::text END)||','||'"database":'||(CASE WHEN jsonb_typeof((((value->'custody')->'binding')->'database'))='object' AND ((((value->'custody')->'binding')->'database')) ?& ARRAY['system_identifier','database_oid']::text[]
    AND ((((value->'custody')->'binding')->'database'))-ARRAY['system_identifier','database_oid']::text[]='{}'::jsonb THEN '{'||'"system_identifier":'||(CASE WHEN jsonb_typeof(((((value->'custody')->'binding')->'database')->'system_identifier'))='string' THEN (((((value->'custody')->'binding')->'database')->'system_identifier'))::text END)||','||'"database_oid":'||(CASE WHEN jsonb_typeof(((((value->'custody')->'binding')->'database')->'database_oid'))='string' THEN (((((value->'custody')->'binding')->'database')->'database_oid'))::text END)||'}' END)||'}' END)||','||'"input":'||(CASE WHEN jsonb_typeof(((value->'custody')->'input'))='object' AND (((value->'custody')->'input')) ?& ARRAY['input_id','module_installation_id','module_configuration_generation_id','configuration_digest']::text[]
    AND (((value->'custody')->'input'))-ARRAY['input_id','module_installation_id','module_configuration_generation_id','configuration_digest']::text[]='{}'::jsonb THEN '{'||'"input_id":'||(CASE WHEN jsonb_typeof((((value->'custody')->'input')->'input_id'))='string' THEN ((((value->'custody')->'input')->'input_id'))::text END)||','||'"module_installation_id":'||(CASE WHEN jsonb_typeof((((value->'custody')->'input')->'module_installation_id'))='string' THEN ((((value->'custody')->'input')->'module_installation_id'))::text END)||','||'"module_configuration_generation_id":'||(CASE WHEN jsonb_typeof((((value->'custody')->'input')->'module_configuration_generation_id'))='string' THEN ((((value->'custody')->'input')->'module_configuration_generation_id'))::text END)||','||'"configuration_digest":'||(CASE WHEN jsonb_typeof((((value->'custody')->'input')->'configuration_digest'))='string' THEN ((((value->'custody')->'input')->'configuration_digest'))::text END)||'}' END)||','||'"pending_digest":'||(CASE WHEN jsonb_typeof(((value->'custody')->'pending_digest'))='string' THEN (((value->'custody')->'pending_digest'))::text END)||','||'"committed_digest":'||(CASE WHEN jsonb_typeof(((value->'custody')->'committed_digest'))='string' THEN (((value->'custody')->'committed_digest'))::text END)||','||'"history_sequence":'||(CASE WHEN jsonb_typeof(((value->'custody')->'history_sequence'))='number' AND (((value->'custody')->'history_sequence'))::text ~ '^(0|[1-9][0-9]{0,19})$'
      AND (((value->'custody')->'history_sequence'))::numeric BETWEEN 0 AND 18446744073709551615 THEN (((value->'custody')->'history_sequence'))::text END)||','||'"history_head_digest":'||(CASE WHEN jsonb_typeof(((value->'custody')->'history_head_digest'))='string' THEN (((value->'custody')->'history_head_digest'))::text END)||','||'"retained_head_digest":'||(CASE WHEN jsonb_typeof(((value->'custody')->'retained_head_digest'))='string' THEN (((value->'custody')->'retained_head_digest'))::text END)||','||'"consumers":'||(CASE WHEN jsonb_typeof(((value->'custody')->'consumers'))='array' AND NOT EXISTS(
      SELECT 1 FROM jsonb_array_elements(((value->'custody')->'consumers')) item WHERE jsonb_typeof(item)<>'string')
      THEN openpc.signing_canonical_json(((value->'custody')->'consumers')) END)||'}' END)||'}' END),'UTF8')
$$;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_source_denial_claims_bytes(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_source_denial_claims_bytes(jsonb) TO openpc_control_worker;


