CREATE OR REPLACE FUNCTION openpc.guard_runtime_artifact_source_denial()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE a control.runtime_artifact_source_disposition; wire jsonb; claims jsonb; original jsonb;
 previous control.runtime_artifact_source_denial;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.lock_runtime_artifact_source_custody();
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.runtime_artifact_source_disposition WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND disposition_id=NEW.disposition_id AND source_owner_id=NEW.source_owner_id
  AND xmin<>pg_current_xact_id()::xid;
 original:=openpc.runtime_artifact_source_admission(a);
 PERFORM openpc.verify_runtime_artifact_source_commit(NEW.source_owner_id,NEW.signed_denial,NEW.verification_nonce,NEW.verification_mac);
 wire:=convert_from(NEW.signed_denial,'UTF8')::jsonb;
 claims:=wire->'claims';
 SELECT * INTO previous FROM control.runtime_artifact_source_denial WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND source_owner_id=NEW.source_owner_id ORDER BY sequence DESC LIMIT 1;
 IF NEW.sequence IS DISTINCT FROM coalesce(previous.sequence,0)+1
  OR NEW.previous_denial_digest IS DISTINCT FROM previous.denial_digest
  OR NEW.denial_digest IS DISTINCT FROM sha256(NEW.signed_denial)
  OR NEW.signed_denial IS DISTINCT FROM openpc.runtime_artifact_source_denial_envelope_bytes(wire)
  OR claims IS DISTINCT FROM jsonb_build_object('version',2,'admission',original,'sequence',NEW.sequence,
    'previous_denial_digest',encode(NEW.previous_denial_digest,'hex'),'recovery','ForwardOnly','custody',claims->'custody')
  OR wire IS DISTINCT FROM jsonb_build_object('purpose','openpc:runtime-artifact-source-denial:v1','claims',claims,
   'claims_digest',encode(sha256(openpc.runtime_artifact_source_denial_claims_bytes(claims)),'hex'),
   'signature_p1363_hex',wire->>'signature_p1363_hex')
  OR coalesce(wire->>'signature_p1363_hex','')!~'^[0-9a-f]{128}$'
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-CUSTODY'; END IF;
 PERFORM openpc.assert_runtime_artifact_source_non_use(a,claims->'custody');
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS runtime_artifact_source_denial_guard ON control.runtime_artifact_source_denial;
CREATE TRIGGER runtime_artifact_source_denial_guard BEFORE INSERT OR UPDATE OR DELETE ON control.runtime_artifact_source_denial
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_runtime_artifact_source_denial();

CREATE OR REPLACE FUNCTION openpc.commit_runtime_artifact_source_denial(wanted uuid,wire bytea,nonce bytea,mac bytea)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE a control.runtime_artifact_source_disposition; retained bytea; claims jsonb;
BEGIN
 PERFORM openpc.lock_runtime_artifact_source_custody();
 SELECT * INTO STRICT a FROM control.runtime_artifact_source_disposition WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND disposition_id=wanted AND xmin<>pg_current_xact_id()::xid;
 PERFORM openpc.runtime_artifact_source_admission(a);
 PERFORM openpc.verify_runtime_artifact_source_commit(a.source_owner_id,wire,nonce,mac);
 SELECT signed_denial INTO retained FROM control.runtime_artifact_source_denial WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND disposition_id=a.disposition_id;
 IF FOUND THEN
  IF retained IS DISTINCT FROM wire THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-CUSTODY'; END IF;
  RETURN;
 END IF;
 claims:=convert_from(wire,'UTF8')::jsonb->'claims';
 INSERT INTO control.runtime_artifact_source_denial(participant_id,privacy_domain_id,source_owner_id,disposition_id,
  sequence,previous_denial_digest,signed_denial,denial_digest,verification_nonce,verification_mac)
 VALUES(a.participant_id,a.privacy_domain_id,a.source_owner_id,a.disposition_id,(claims->>'sequence')::numeric,
  decode(claims->>'previous_denial_digest','hex'),wire,sha256(wire),nonce,mac);
END $$;

-- Admission grants and its exact receipt/eligibility owner arrive together.
-- Native readback cannot fabricate an admission in their absence.
CREATE OR REPLACE FUNCTION openpc.guard_runtime_artifact_source_disposition_immutable()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-ADMISSION-UNAVAILABLE';
END $$;
DROP TRIGGER IF EXISTS runtime_artifact_source_disposition_guard ON control.runtime_artifact_source_disposition;
CREATE TRIGGER runtime_artifact_source_disposition_guard BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE
 ON control.runtime_artifact_source_disposition FOR EACH STATEMENT EXECUTE FUNCTION openpc.guard_runtime_artifact_source_disposition_immutable();

REVOKE ALL ON FUNCTION openpc.guard_runtime_artifact_source_installation(),openpc.lock_runtime_artifact_source_custody(),
 openpc.runtime_artifact_source_admission(control.runtime_artifact_source_disposition),
 openpc.read_runtime_artifact_source_admissions(jsonb,bytea),openpc.runtime_artifact_source_key_installed(uuid),
 openpc.verify_runtime_artifact_source_commit(uuid,bytea,bytea,bytea),openpc.guard_runtime_artifact_source_denial(),
 openpc.commit_runtime_artifact_source_denial(uuid,bytea,bytea,bytea),openpc.guard_runtime_artifact_source_disposition_immutable() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.lock_runtime_artifact_source_custody(),
 openpc.runtime_artifact_source_admission(control.runtime_artifact_source_disposition),
 openpc.read_runtime_artifact_source_admissions(jsonb,bytea),openpc.runtime_artifact_source_key_installed(uuid),
 openpc.verify_runtime_artifact_source_commit(uuid,bytea,bytea,bytea),
 openpc.commit_runtime_artifact_source_denial(uuid,bytea,bytea,bytea) TO openpc_control_worker;
GRANT INSERT ON control.runtime_artifact_source_denial TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.assert_runtime_artifact_source_import(input control.runtime_configuration_input)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE s control.runtime_artifact_source; secret bytea; wire bytea; nonce bytea; mac bytea;
 expected bytea; different integer:=0; document jsonb; pending jsonb; root jsonb; installation jsonb;
 wire_text text:=current_setting('openpc.runtime_source_import_wire',true);
 nonce_text text:=current_setting('openpc.runtime_source_import_nonce',true);
 mac_text text:=current_setting('openpc.runtime_source_import_mac',true);
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF input.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR input.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.runtime_artifact_source WHERE participant_id=input.participant_id
  AND privacy_domain_id=input.privacy_domain_id AND custody_root IS NOT NULL) THEN RETURN; END IF;
 SELECT * INTO STRICT s FROM control.runtime_artifact_source WHERE participant_id=input.participant_id
  AND privacy_domain_id=input.privacy_domain_id;
 IF s.database_role<>session_user OR NOT pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR openpc.current_action_intent_id()<>'ACT-PROVIDER_PROFILES_READ_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed'
  OR current_setting('session_replication_role')<>'origin'
  OR coalesce(length(wire_text),0) NOT BETWEEN 2 AND 16384
  OR coalesce(nonce_text,'') !~ '^[0-9a-f]{64}$' OR coalesce(mac_text,'') !~ '^[0-9a-f]{64}$'
  OR wire_text !~ '^[0-9a-f]+$' OR length(wire_text)%2<>0
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 wire:=decode(wire_text,'hex'); nonce:=decode(nonce_text,'hex'); mac:=decode(mac_text,'hex');
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_artifact_source_verifier_key
  WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND source_owner_id=s.source_owner_id;
 expected:=public.hmac(convert_to('OPENPC_RUNTIME_ARTIFACT_SOURCE_IMPORT_V1'||pg_current_xact_id()::text
  ||encode(sha256(wire),'hex'),'UTF8')||nonce,secret,'sha256');
 FOR n IN 0..31 LOOP different:=different | (get_byte(expected,n) # get_byte(mac,n)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 document:=convert_from(wire,'UTF8')::jsonb;
 pending:=document->'pending'->'claims'; root:=document->'root'->'claims';
 installation:=jsonb_build_object('participant_id',s.participant_id::text,'privacy_domain_id',s.privacy_domain_id::text,
  'source_owner_id',s.source_owner_id::text,'source_file_binding',encode(s.source_file_binding,'hex'));
 IF document IS DISTINCT FROM jsonb_build_object('pending',document->'pending','root',document->'root')
  OR document->'pending'->>'purpose' IS DISTINCT FROM 'openpc:runtime-artifact-source-history:v1'
  OR document->'root'->>'purpose' IS DISTINCT FROM 'openpc:runtime-artifact-source-root:v1'
  OR pending->'installation' IS DISTINCT FROM installation OR root->'installation' IS DISTINCT FROM installation
  OR pending->'version' IS DISTINCT FROM '1'::jsonb OR root->'version' IS DISTINCT FROM '1'::jsonb
  OR root->'binding' IS DISTINCT FROM s.custody_root
  OR pending->'observation' IS DISTINCT FROM jsonb_build_object('ImportPending',jsonb_build_object(
   'input_id',input.runtime_configuration_input_id::text,'module_installation_id',input.module_installation_id::text,
   'module_configuration_generation_id',input.module_configuration_generation_id::text,
   'configuration_digest',encode(input.configuration_digest,'hex')))
  OR input.configuration_digest IS DISTINCT FROM sha256(input.configuration_cbor)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
END $$;
ALTER FUNCTION openpc.assert_runtime_artifact_source_import(control.runtime_configuration_input) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.assert_runtime_artifact_source_import(control.runtime_configuration_input) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_runtime_artifact_source_import(control.runtime_configuration_input) TO openpc_control_worker;



GRANT EXECUTE ON FUNCTION pg_catalog.pg_control_system() TO openpc_control_owner;
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_database_identity() RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
BEGIN
 RETURN (SELECT jsonb_build_object('system_identifier',s.system_identifier::text,'database_oid',d.oid::text)
  FROM pg_control_system() s,pg_database d WHERE d.datname=current_database());
END $$;
ALTER FUNCTION openpc.runtime_artifact_database_identity() OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_database_identity() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_database_identity() TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_materialization_source() RETURNS control.runtime_artifact_source
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE s control.runtime_artifact_source; marker text; pin jsonb; installed_role oid;
BEGIN
 PERFORM openpc.assert_request_context(true);
 marker:='openpc_rs_scope_'||rtrim(translate(encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_array(
  'openpc:runtime-source-scope:v1',openpc.current_participant_id()::text,openpc.current_privacy_domain_id()::text)),'UTF8')),
  'base64'),'+/','-_'),'=');
 SELECT oid INTO installed_role FROM pg_roles WHERE rolname=marker;
 IF (SELECT count(*) FROM control.runtime_artifact_source WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id())>1 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN'; END IF;
 SELECT * INTO s FROM control.runtime_artifact_source WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id();
 IF installed_role IS NULL THEN
  IF s.custody_root IS NOT NULL THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN'; END IF;
  RETURN s;
 END IF;
 pin:=shobj_description(installed_role,'pg_authid')::jsonb;
 IF s.source_owner_id IS NULL OR s.custody_root IS NULL
  OR pin->'version' IS DISTINCT FROM '1'::jsonb OR pin->'installation' IS DISTINCT FROM jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex'))
  OR pin->'root' IS DISTINCT FROM s.custody_root OR pin->>'database_role' IS DISTINCT FROM s.database_role
  OR pin->'archive_custody' IS DISTINCT FROM s.archive_custody
  OR NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.oid=installed_role AND NOT r.rolcanlogin AND NOT r.rolsuper
   AND NOT r.rolbypassrls AND NOT r.rolcreaterole AND NOT r.rolcreatedb AND NOT r.rolreplication)
  OR (SELECT count(*) FROM pg_auth_members WHERE roleid=installed_role)<>1
  OR NOT EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles member ON member.oid=m.member JOIN pg_roles grantor ON grantor.oid=m.grantor
   WHERE m.roleid=installed_role AND member.rolname=s.database_role AND grantor.rolsuper
    AND NOT m.admin_option AND NOT m.inherit_option AND NOT m.set_option)
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN'; END IF;
 RETURN s;
END $$;
ALTER FUNCTION openpc.runtime_artifact_materialization_source() OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_materialization_source() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_materialization_source() TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_input_information(input_id uuid) RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE input control.runtime_configuration_input;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT (EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user
 AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication
 AND NOT pg_has_role(oid,'openpc_control_owner','MEMBER')
 AND NOT pg_has_role(oid,'openpc_control_key_governor','MEMBER'))
 AND (pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR pg_has_role(session_user,'openpc_control_runtime','USAGE')
  OR pg_has_role(session_user,'openpc_control_reader','USAGE'))) THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND runtime_configuration_input_id=input_id;
 RETURN jsonb_build_object('bytesMatch',input.configuration_digest=sha256(input.configuration_cbor),
  'byteLength',octet_length(input.configuration_cbor)::text);
END $$;
ALTER FUNCTION openpc.runtime_artifact_input_information(uuid) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_input_information(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_input_information(uuid) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_materialization_challenge(input_id uuid) RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE input control.runtime_configuration_input; s control.runtime_artifact_source; wire bytea; secret bytea;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT (EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user
 AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication
 AND NOT pg_has_role(oid,'openpc_control_owner','MEMBER')
 AND NOT pg_has_role(oid,'openpc_control_key_governor','MEMBER'))
 AND (pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR pg_has_role(session_user,'openpc_control_runtime','USAGE')
  OR pg_has_role(session_user,'openpc_control_reader','USAGE'))) THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND runtime_configuration_input_id=input_id;
 s:=openpc.runtime_artifact_materialization_source();
 IF s.custody_root IS NULL OR s.custody_root->>'consumer_profile'='openpc:local-runtime-source-consumers:v1'
 THEN RETURN NULL; END IF;
 IF NOT openpc.runtime_artifact_new_use_allowed(input.participant_id,input.privacy_domain_id,input.configuration_digest)
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-DENIED'; END IF;
 PERFORM openpc.assert_runtime_artifact_materialization_boundary();
 IF s.custody_root->>'consumer_profile' IS DISTINCT FROM 'openpc:local-runtime-source-consumers:v2'
  OR s.custody_root->'database' IS DISTINCT FROM openpc.runtime_artifact_database_identity()
  OR input.configuration_digest IS DISTINCT FROM sha256(input.configuration_cbor)
  OR (SELECT count(*) FROM control.runtime_artifact_source WHERE participant_id=input.participant_id
    AND privacy_domain_id=input.privacy_domain_id)<>1
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN'; END IF;
 wire:=convert_to(jsonb_build_object('version',2,'installation',jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex')),'binding',s.custody_root,
  'materialization',jsonb_build_object('input',jsonb_build_object('input_id',input.runtime_configuration_input_id::text,
 'module_installation_id',input.module_installation_id::text,
 'module_configuration_generation_id',input.module_configuration_generation_id::text,
 'configuration_digest',encode(input.configuration_digest,'hex')),'reader_role',session_user::text,
   'transaction_id',pg_current_xact_id()::text,'backend_id',pg_backend_pid()::text||':'||extract(epoch FROM pg_postmaster_start_time())::text,'request_id',uuidv7()::text))::text,'UTF8');
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_artifact_source_verifier_key WHERE participant_id=s.participant_id
  AND privacy_domain_id=s.privacy_domain_id AND source_owner_id=s.source_owner_id;
 RETURN jsonb_build_object('wire',(SELECT jsonb_agg(get_byte(wire,n) ORDER BY n) FROM generate_series(0,octet_length(wire)-1) n),
  'mac',(SELECT jsonb_agg(get_byte(mac,n) ORDER BY n) FROM
   (SELECT public.hmac(convert_to('OPENPC_RUNTIME_ARTIFACT_MATERIALIZATION_REQUEST_V2','UTF8')||wire,secret,'sha256') mac) m,
   generate_series(0,31) n));
END $$;
ALTER FUNCTION openpc.runtime_artifact_materialization_challenge(uuid) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_materialization_challenge(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_materialization_challenge(uuid) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_input_payload(input_id uuid) RETURNS bytea
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE input control.runtime_configuration_input; s control.runtime_artifact_source; secret bytea;
 permits jsonb; permit jsonb; wire bytea; mac bytea; expected bytea; different integer:=0;
 document jsonb; challenge jsonb; materialization jsonb; observation jsonb; root jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT (EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user
 AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication
 AND NOT pg_has_role(oid,'openpc_control_owner','MEMBER')
 AND NOT pg_has_role(oid,'openpc_control_key_governor','MEMBER'))
 AND (pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR pg_has_role(session_user,'openpc_control_runtime','USAGE')
  OR pg_has_role(session_user,'openpc_control_reader','USAGE'))) THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND runtime_configuration_input_id=input_id;
 s:=openpc.runtime_artifact_materialization_source();
 IF s.custody_root IS NULL OR s.custody_root->>'consumer_profile'='openpc:local-runtime-source-consumers:v1'
 THEN RETURN input.configuration_cbor; END IF;
 IF NOT openpc.runtime_artifact_new_use_allowed(input.participant_id,input.privacy_domain_id,input.configuration_digest)
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-DENIED'; END IF;
 PERFORM openpc.assert_runtime_artifact_materialization_boundary();
 IF s.custody_root->>'consumer_profile' IS DISTINCT FROM 'openpc:local-runtime-source-consumers:v2'
  OR s.custody_root->'database' IS DISTINCT FROM openpc.runtime_artifact_database_identity()
  OR input.configuration_digest IS DISTINCT FROM sha256(input.configuration_cbor)
  OR (SELECT count(*) FROM control.runtime_artifact_source WHERE participant_id=input.participant_id
    AND privacy_domain_id=input.privacy_domain_id)<>1
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN'; END IF;
 IF coalesce(octet_length(current_setting('openpc.runtime_source_read_permits',true)),0) NOT BETWEEN 2 AND 1048576
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN'; END IF;
 permits:=current_setting('openpc.runtime_source_read_permits',true)::jsonb;
 permit:=permits->input_id::text;
 IF permit IS DISTINCT FROM jsonb_build_object('wire',permit->'wire','mac',permit->'mac')
  OR coalesce(length(permit->>'wire'),0) NOT BETWEEN 2 AND 32768
  OR coalesce(permit->>'wire','') !~ '^[0-9a-f]+$' OR length(permit->>'wire')%2<>0
  OR coalesce(permit->>'mac','') !~ '^[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN'; END IF;
 wire:=decode(permit->>'wire','hex'); mac:=decode(permit->>'mac','hex');
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_artifact_source_verifier_key WHERE participant_id=s.participant_id
  AND privacy_domain_id=s.privacy_domain_id AND source_owner_id=s.source_owner_id;
 expected:=public.hmac(convert_to('OPENPC_RUNTIME_ARTIFACT_MATERIALIZATION_RESPONSE_V2','UTF8')||wire,secret,'sha256');
 FOR n IN 0..31 LOOP different:=different | (get_byte(expected,n) # get_byte(mac,n)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN'; END IF;
 document:=convert_from(wire,'UTF8')::jsonb; challenge:=document->'challenge';
 materialization:=challenge->'materialization'; observation:=document->'observation'->'claims'; root:=document->'root'->'claims';
 IF document IS DISTINCT FROM jsonb_build_object('challenge',challenge,'observation',document->'observation','root',document->'root')
  OR challenge IS DISTINCT FROM jsonb_build_object('version',2,'installation',jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex')),'binding',s.custody_root,
   'materialization',jsonb_build_object('input',jsonb_build_object('input_id',input.runtime_configuration_input_id::text,
 'module_installation_id',input.module_installation_id::text,
 'module_configuration_generation_id',input.module_configuration_generation_id::text,
 'configuration_digest',encode(input.configuration_digest,'hex')),'reader_role',session_user::text,
    'transaction_id',pg_current_xact_id()::text,'backend_id',pg_backend_pid()::text||':'||extract(epoch FROM pg_postmaster_start_time())::text,'request_id',materialization->>'request_id'))
  OR coalesce(materialization->>'request_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR document->'observation'->>'purpose' IS DISTINCT FROM 'openpc:runtime-artifact-source-history:v1'
  OR observation->'version' IS DISTINCT FROM '1'::jsonb
  OR observation->'installation' IS DISTINCT FROM jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex'))
  OR observation->'observation' IS DISTINCT FROM jsonb_build_object('MaterializedOrUnknown',observation->'observation'->'MaterializedOrUnknown')
  OR observation->'observation'->'MaterializedOrUnknown'->'input' IS DISTINCT FROM jsonb_build_object('input_id',input.runtime_configuration_input_id::text,
 'module_installation_id',input.module_installation_id::text,
 'module_configuration_generation_id',input.module_configuration_generation_id::text,
 'configuration_digest',encode(input.configuration_digest,'hex'))
  OR document->'root'->>'purpose' IS DISTINCT FROM 'openpc:runtime-artifact-source-root:v1'
  OR root->'version' IS DISTINCT FROM '1'::jsonb OR root->'installation' IS DISTINCT FROM jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex'))
  OR root->'binding' IS DISTINCT FROM s.custody_root
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN'; END IF;
 RETURN input.configuration_cbor;
END $$;
ALTER FUNCTION openpc.runtime_artifact_input_payload(uuid) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_input_payload(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_input_payload(uuid) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_archive_owner(stream text) RETURNS control.runtime_artifact_source
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE s control.runtime_artifact_source; owner oid; pin jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 s:=openpc.runtime_artifact_materialization_source();
 IF NOT (EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user
 AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication
 AND NOT pg_has_role(oid,'openpc_control_owner','MEMBER')
 AND NOT pg_has_role(oid,'openpc_control_key_governor','MEMBER'))
 AND (pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR pg_has_role(session_user,'openpc_control_runtime','USAGE')
  OR pg_has_role(session_user,'openpc_control_reader','USAGE'))) OR current_user=session_user
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR current_setting('transaction_isolation')<>'read committed' OR current_setting('session_replication_role')<>'origin'
  OR s.custody_root->>'consumer_profile' IS DISTINCT FROM 'openpc:local-runtime-source-consumers:v2'
  OR s.custody_root->'database' IS DISTINCT FROM openpc.runtime_artifact_database_identity()
  OR s.archive_custody->>'stream_id' IS DISTINCT FROM stream
  OR s.archive_custody->>'database_role' IS DISTINCT FROM session_user
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-OWNER-UNAVAILABLE'; END IF;
 SELECT oid INTO STRICT owner FROM pg_roles WHERE rolname=session_user AND rolcanlogin;
 pin:=shobj_description(owner,'pg_authid')::jsonb;
 IF pin IS DISTINCT FROM jsonb_build_object('installation',jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex')),'root',s.custody_root,'archive',s.archive_custody)
  OR EXISTS(SELECT 1 FROM pg_auth_members WHERE roleid=owner)
  OR EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid JOIN pg_roles grantor ON grantor.oid=m.grantor
   WHERE m.member=owner AND (parent.rolname<>'openpc_control_worker' OR m.admin_option OR NOT grantor.rolsuper))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-OWNER-UNAVAILABLE'; END IF;
 PERFORM openpc.assert_runtime_artifact_materialization_boundary();
 RETURN s;
END $$;
ALTER FUNCTION openpc.runtime_artifact_archive_owner(text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_archive_owner(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_archive_owner(text) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_archive_challenge(input_id uuid,stream text) RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE s control.runtime_artifact_source; input control.runtime_configuration_input; wire bytea; secret bytea;
BEGIN
 s:=openpc.runtime_artifact_archive_owner(stream);
 SELECT * INTO STRICT input FROM control.runtime_configuration_input WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id
  AND runtime_configuration_input_id=input_id;
 IF NOT openpc.runtime_artifact_new_use_allowed(input.participant_id,input.privacy_domain_id,input.configuration_digest)
  OR input.configuration_digest IS DISTINCT FROM sha256(input.configuration_cbor)
  OR EXISTS(SELECT 1 FROM control.evidence_runtime_artifact_archive WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND runtime_configuration_input_id=input_id)
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-READ-DENIED'; END IF;
 wire:=convert_to(jsonb_build_object('version',1,'installation',jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex')),'binding',s.custody_root,
  'archive',jsonb_build_object('stream_id',stream,'materialization',jsonb_build_object('input',jsonb_build_object('input_id',input.runtime_configuration_input_id::text,
 'module_installation_id',input.module_installation_id::text,
 'module_configuration_generation_id',input.module_configuration_generation_id::text,
 'configuration_digest',encode(input.configuration_digest,'hex')),'reader_role',session_user::text,
   'transaction_id',pg_current_xact_id()::text,'backend_id',pg_backend_pid()::text||':'||extract(epoch FROM pg_postmaster_start_time())::text,'request_id',uuidv7()::text)))::text,'UTF8');
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_artifact_source_verifier_key WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND source_owner_id=s.source_owner_id;
 RETURN jsonb_build_object('wire',(SELECT jsonb_agg(get_byte(wire,n) ORDER BY n) FROM generate_series(0,octet_length(wire)-1) n),
  'mac',(SELECT jsonb_agg(get_byte(mac,n) ORDER BY n) FROM (SELECT public.hmac(convert_to('OPENPC_RUNTIME_ARTIFACT_ARCHIVE_REQUEST_V1','UTF8')||wire,secret,'sha256') mac) m,generate_series(0,31) n));
END $$;
ALTER FUNCTION openpc.runtime_artifact_archive_challenge(uuid,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_archive_challenge(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_archive_challenge(uuid,text) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_archive_permit(input_id uuid,stream text) RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE s control.runtime_artifact_source; input control.runtime_configuration_input; permit jsonb; wire bytea; mac bytea; expected bytea; secret bytea;
 document jsonb; challenge jsonb; pending jsonb; observation jsonb; root jsonb; difference integer:=0;
BEGIN
 s:=openpc.runtime_artifact_archive_owner(stream);
 SELECT * INTO STRICT input FROM control.runtime_configuration_input WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND runtime_configuration_input_id=input_id;
 IF NOT openpc.runtime_artifact_new_use_allowed(input.participant_id,input.privacy_domain_id,input.configuration_digest)
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-READ-DENIED'; END IF;
 IF coalesce(octet_length(current_setting('openpc.runtime_source_archive_permit',true)),0) NOT BETWEEN 2 AND 65536
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN'; END IF;
 permit:=current_setting('openpc.runtime_source_archive_permit',true)::jsonb;
 IF permit IS DISTINCT FROM jsonb_build_object('wire',permit->'wire','mac',permit->'mac')
  OR coalesce(permit->>'wire','') !~ '^[0-9a-f]+$' OR length(permit->>'wire')%2<>0
  OR coalesce(permit->>'mac','') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN'; END IF;
 wire:=decode(permit->>'wire','hex'); mac:=decode(permit->>'mac','hex');
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_artifact_source_verifier_key WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND source_owner_id=s.source_owner_id;
 expected:=public.hmac(convert_to('OPENPC_RUNTIME_ARTIFACT_ARCHIVE_RESPONSE_V1','UTF8')||wire,secret,'sha256');
 FOR n IN 0..31 LOOP difference:=difference | (get_byte(expected,n) # get_byte(mac,n)); END LOOP;
 IF difference<>0 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN'; END IF;
 document:=convert_from(wire,'UTF8')::jsonb; challenge:=document->'challenge'; pending:=challenge->'archive';
 observation:=document->'observation'->'claims'; root:=document->'root'->'claims';
 IF document IS DISTINCT FROM jsonb_build_object('challenge',challenge,'observation',document->'observation','root',document->'root','original',document->'original')
  OR challenge IS DISTINCT FROM jsonb_build_object('version',1,'installation',jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex')),'binding',s.custody_root,
   'archive',jsonb_build_object('stream_id',stream,'materialization',jsonb_build_object('input',jsonb_build_object('input_id',input.runtime_configuration_input_id::text,
 'module_installation_id',input.module_installation_id::text,
 'module_configuration_generation_id',input.module_configuration_generation_id::text,
 'configuration_digest',encode(input.configuration_digest,'hex')),'reader_role',session_user::text,
    'transaction_id',pg_current_xact_id()::text,'backend_id',pg_backend_pid()::text||':'||extract(epoch FROM pg_postmaster_start_time())::text,'request_id',pending->'materialization'->>'request_id')))
  OR coalesce(pending->'materialization'->>'request_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR document->'observation'->>'purpose' IS DISTINCT FROM 'openpc:runtime-artifact-source-history:v1'
  OR observation->'version' IS DISTINCT FROM '1'::jsonb OR observation->'installation' IS DISTINCT FROM jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex'))
  OR observation->'observation' IS DISTINCT FROM jsonb_build_object('ArchiveMaterializedOrUnknown',pending)
  OR document->'root'->>'purpose' IS DISTINCT FROM 'openpc:runtime-artifact-source-root:v1'
  OR root->'version' IS DISTINCT FROM '1'::jsonb OR root->'installation' IS DISTINCT FROM jsonb_build_object('participant_id',s.participant_id::text,
 'privacy_domain_id',s.privacy_domain_id::text,'source_owner_id',s.source_owner_id::text,
 'source_file_binding',encode(s.source_file_binding,'hex'))
  OR root->'binding' IS DISTINCT FROM s.custody_root THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN'; END IF;
 IF coalesce(document->>'original','') !~ '^[0-9a-f]+$' OR length(document->>'original') NOT BETWEEN 2 AND 16384 OR length(document->>'original')%2<>0
  THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN'; END IF;
 IF convert_from(decode(document->>'original','hex'),'UTF8')::jsonb IS DISTINCT FROM document->'observation'
  THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-READ-UNPROVEN'; END IF;
 RETURN jsonb_build_object('original',document->'original','observation',document->'observation');
END $$;
ALTER FUNCTION openpc.runtime_artifact_archive_permit(uuid,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_archive_permit(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_archive_permit(uuid,text) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_archive_payload(input_id uuid,stream text) RETURNS bytea
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE payload bytea;
BEGIN
 PERFORM openpc.runtime_artifact_archive_permit(input_id,stream);
 SELECT configuration_cbor INTO STRICT payload FROM control.runtime_configuration_input WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND runtime_configuration_input_id=input_id;
 RETURN payload;
END $$;
ALTER FUNCTION openpc.runtime_artifact_archive_payload(uuid,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_archive_payload(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_archive_payload(uuid,text) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.assert_runtime_artifact_materialization_boundary()
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 -- Traverse actual membership rather than superuser's implicit pg_has_role
 -- answer. A product login becoming an owner is a bypass, not an installer to
 -- exclude from the ordinary grant audit below.
 IF EXISTS(WITH RECURSIVE product_role(oid) AS (
  SELECT oid FROM pg_roles WHERE rolname IN ('openpc_control_runtime','openpc_control_worker','openpc_control_reader')
  UNION SELECT m.member FROM pg_auth_members m JOIN product_role p ON p.oid=m.roleid)
  SELECT 1 FROM product_role p JOIN pg_roles r ON r.oid=p.oid WHERE r.rolcanlogin AND (
   r.rolsuper OR r.rolbypassrls OR r.rolcreaterole OR r.rolcreatedb OR r.rolreplication
   OR pg_has_role(r.oid,'openpc_control_owner','MEMBER')
   OR pg_has_role(r.oid,'openpc_control_key_governor','MEMBER')))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-ROLE-UNAVAILABLE'; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles r WHERE NOT r.rolsuper
  AND NOT pg_has_role(r.oid,'openpc_control_owner','MEMBER')
  AND (r.rolcanlogin OR r.rolname IN ('openpc_control_runtime','openpc_control_worker','openpc_control_reader')
 OR EXISTS(SELECT 1 FROM pg_roles login WHERE login.rolcanlogin AND NOT login.rolsuper
  AND NOT pg_has_role(login.oid,'openpc_control_owner','MEMBER') AND pg_has_role(login.oid,r.oid,'SET'))) AND has_column_privilege(r.oid,'control.runtime_configuration_input','configuration_cbor','SELECT'))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-GRANT-UNAVAILABLE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_roles r ON r.oid=c.relowner
  WHERE c.oid='control.runtime_configuration_input'::regclass AND c.relkind='r' AND c.relrowsecurity
   AND NOT c.relispartition AND r.rolname='openpc_control_owner')
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-OWNER-UNAVAILABLE'; END IF;
 IF EXISTS(SELECT 1 FROM pg_depend d JOIN pg_rewrite rule ON rule.oid=d.objid
  JOIN pg_class view ON view.oid=rule.ev_class
  WHERE d.classid='pg_rewrite'::regclass AND d.refclassid='pg_class'::regclass
   AND d.refobjid='control.runtime_configuration_input'::regclass
   AND (view.oid<>'control.runtime_configuration_input_current_metadata'::regclass
    OR d.refobjsubid=(SELECT attnum FROM pg_attribute
     WHERE attrelid='control.runtime_configuration_input'::regclass AND attname='configuration_cbor')
    OR rule.ev_action::text LIKE '%:varattno 0 %'
    OR NOT coalesce(view.reloptions @> ARRAY['security_invoker=true']::text[],false))
   AND view.relkind IN ('v','m') AND EXISTS(SELECT 1 FROM pg_roles r WHERE NOT r.rolsuper
    AND NOT pg_has_role(r.oid,'openpc_control_owner','MEMBER')
    AND (r.rolcanlogin OR r.rolname IN ('openpc_control_runtime','openpc_control_worker','openpc_control_reader')
 OR EXISTS(SELECT 1 FROM pg_roles login WHERE login.rolcanlogin AND NOT login.rolsuper
  AND NOT pg_has_role(login.oid,'openpc_control_owner','MEMBER') AND pg_has_role(login.oid,r.oid,'SET'))) AND has_any_column_privilege(r.oid,view.oid,'SELECT')))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-SOURCE-READ-PROJECTION-UNAVAILABLE'; END IF;
 IF EXISTS(SELECT 1 FROM (VALUES ('openpc.runtime_artifact_database_identity()','
BEGIN
 RETURN (SELECT jsonb_build_object(''system_identifier'',s.system_identifier::text,''database_oid'',d.oid::text)
  FROM pg_control_system() s,pg_database d WHERE d.datname=current_database());
END '),('openpc.runtime_artifact_materialization_source()','
DECLARE s control.runtime_artifact_source; marker text; pin jsonb; installed_role oid;
BEGIN
 PERFORM openpc.assert_request_context(true);
 marker:=''openpc_rs_scope_''||rtrim(translate(encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_array(
  ''openpc:runtime-source-scope:v1'',openpc.current_participant_id()::text,openpc.current_privacy_domain_id()::text)),''UTF8'')),
  ''base64''),''+/'',''-_''),''='');
 SELECT oid INTO installed_role FROM pg_roles WHERE rolname=marker;
 IF (SELECT count(*) FROM control.runtime_artifact_source WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id())>1 THEN RAISE EXCEPTION ''RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN''; END IF;
 SELECT * INTO s FROM control.runtime_artifact_source WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id();
 IF installed_role IS NULL THEN
  IF s.custody_root IS NOT NULL THEN RAISE EXCEPTION ''RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN''; END IF;
  RETURN s;
 END IF;
 pin:=shobj_description(installed_role,''pg_authid'')::jsonb;
 IF s.source_owner_id IS NULL OR s.custody_root IS NULL
  OR pin->''version'' IS DISTINCT FROM ''1''::jsonb OR pin->''installation'' IS DISTINCT FROM jsonb_build_object(''participant_id'',s.participant_id::text,
 ''privacy_domain_id'',s.privacy_domain_id::text,''source_owner_id'',s.source_owner_id::text,
 ''source_file_binding'',encode(s.source_file_binding,''hex''))
  OR pin->''root'' IS DISTINCT FROM s.custody_root OR pin->>''database_role'' IS DISTINCT FROM s.database_role
  OR pin->''archive_custody'' IS DISTINCT FROM s.archive_custody
  OR NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.oid=installed_role AND NOT r.rolcanlogin AND NOT r.rolsuper
   AND NOT r.rolbypassrls AND NOT r.rolcreaterole AND NOT r.rolcreatedb AND NOT r.rolreplication)
  OR (SELECT count(*) FROM pg_auth_members WHERE roleid=installed_role)<>1
  OR NOT EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles member ON member.oid=m.member JOIN pg_roles grantor ON grantor.oid=m.grantor
   WHERE m.roleid=installed_role AND member.rolname=s.database_role AND grantor.rolsuper
    AND NOT m.admin_option AND NOT m.inherit_option AND NOT m.set_option)
 THEN RAISE EXCEPTION ''RUNTIME-ARTIFACT-SOURCE-READ-UNPROVEN''; END IF;
 RETURN s;
END '),('openpc.runtime_artifact_input_information(uuid)','
