-- This typed assertion checks only the supplied terminal-result shape. It
-- neither reads nor grants current execution/admission authority. The trigger
-- below obtains real rows under locks and separately closes all effect/evidence
-- dependencies; detached caller values can never bypass those owners.
CREATE OR REPLACE FUNCTION openpc.runtime_generation_retry_failure_payload(
 prior control.runtime_configuration_generation, work control.configuration_work)
RETURNS bytea LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE payload bytea;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF prior.runtime_configuration_generation_id IS NULL OR work.configuration_work_id IS NULL
  OR prior.runtime_target_id IS NULL OR prior.generation_digest IS NULL
  OR prior.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR prior.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR prior.state IS DISTINCT FROM 'FAILED' OR prior.activated_at IS NOT NULL OR prior.cigl_profile_selection IS NOT NULL
  OR work.participant_id IS DISTINCT FROM prior.participant_id
  OR work.privacy_domain_id IS DISTINCT FROM prior.privacy_domain_id
  OR work.runtime_configuration_generation_id IS DISTINCT FROM prior.runtime_configuration_generation_id
  OR work.operation_id IS NULL OR work.last_error_code IS NULL
  OR work.state IS DISTINCT FROM 'FAILED' OR work.work_kind IS DISTINCT FROM 'RUNTIME_ACTIVATION'
  OR work.runtime_target_id IS DISTINCT FROM prior.runtime_target_id OR work.resource_id IS DISTINCT FROM prior.runtime_target_id
  OR work.generation_digest IS DISTINCT FROM prior.generation_digest
  OR work.predecessor_digest IS DISTINCT FROM prior.predecessor_digest
  OR work.execution_started_at IS NOT NULL OR work.execution_attempt_id IS NOT NULL
  OR work.lease_owner IS NOT NULL OR work.lease_until IS NOT NULL OR work.reconcile_after IS NOT NULL
  OR work.completed_at IS NULL OR work.result_event_id IS NULL
  OR work.result_receipt IS DISTINCT FROM jsonb_build_object('errorCode',work.last_error_code,
    'resourceId',work.resource_id::text,'terminal',true,'workKind','RUNTIME_ACTIVATION')
 THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 payload:=convert_to(openpc.signing_canonical_json(work.result_receipt),'UTF8');
 IF work.result_receipt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(payload),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 RETURN payload;
END $$;
REVOKE ALL ON FUNCTION openpc.runtime_generation_retry_failure_payload(control.runtime_configuration_generation,control.configuration_work) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_generation_retry_failure_payload(control.runtime_configuration_generation,control.configuration_work) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.guard_runtime_generation_retry()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE prior control.runtime_configuration_generation; work control.configuration_work;
 target control.runtime_target; payload bytea;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.runtime_configuration_generation g
  WHERE g.runtime_target_id=NEW.runtime_target_id AND g.generation_digest=NEW.generation_digest
   AND g.predecessor_digest IS NOT DISTINCT FROM NEW.predecessor_digest AND g.state='FAILED')
 THEN RETURN NEW; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR openpc.current_action_intent_id()<>'ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'serializable'
  OR NEW.state<>'ACTIVATING' OR NEW.revision<>1 OR NEW.activated_at IS NOT NULL
  OR NEW.cigl_profile_selection IS NOT NULL
 THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 -- Reentrant with the shared BEFORE STATEMENT reference fence. Never reverse-wait.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='PC-DATA-6007'; END IF;
 SELECT * INTO STRICT target FROM control.runtime_target t
  WHERE t.participant_id=NEW.participant_id AND t.privacy_domain_id=NEW.privacy_domain_id
   AND t.runtime_target_id=NEW.runtime_target_id FOR UPDATE NOWAIT;
 -- Public activation still checks current discovery and expected revision;
 -- this guard only proves the old attempt cannot have dispatched an effect.
 IF target.state<>'FAILED' OR target.active_generation_digest IS DISTINCT FROM NEW.predecessor_digest
 THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 FOR prior IN SELECT g.* FROM control.runtime_configuration_generation g
  WHERE g.runtime_target_id=NEW.runtime_target_id AND g.generation_digest=NEW.generation_digest
   AND g.predecessor_digest IS NOT DISTINCT FROM NEW.predecessor_digest
  ORDER BY g.runtime_configuration_generation_id FOR SHARE NOWAIT
 LOOP
  IF prior.participant_id<>NEW.participant_id OR prior.privacy_domain_id<>NEW.privacy_domain_id
   OR prior.state<>'FAILED' OR prior.activated_at IS NOT NULL OR prior.cigl_profile_selection IS NOT NULL
  THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
  SELECT * INTO STRICT work FROM control.configuration_work w
   WHERE w.participant_id=prior.participant_id AND w.privacy_domain_id=prior.privacy_domain_id
    AND w.runtime_configuration_generation_id=prior.runtime_configuration_generation_id FOR SHARE NOWAIT;
  payload:=openpc.runtime_generation_retry_failure_payload(prior,work);
  -- This is the existing configuration-result owner's canonical failure payload
  -- bound to its original committed authorization signature, not a new signature
  -- over a fabricated result or a new permission to execute.
  IF NOT EXISTS(SELECT 1 FROM control.outbox_event e JOIN control.mutation_evidence a
    ON a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id
     AND a.operation_id=work.operation_id AND a.aggregate_id=work.resource_id
     AND a.action_intent_id='ACT-RUNTIME_TARGETS_UPDATE_RESOURCE-V1'
     AND a.catalog_operation_id='CFG-OP-UPDATE-RUNTIME-TARGET'
    JOIN control.idempotency_record i ON i.participant_id=a.participant_id AND i.privacy_domain_id=a.privacy_domain_id
     AND i.operation_id=a.operation_id AND i.input_digest=a.candidate_digest
     AND i.terminal_state='COMMITTED' AND i.result_payload->>'state'='FAILED'
     AND i.result_payload->>'truthState'='FAILED'
    WHERE e.participant_id=work.participant_id AND e.privacy_domain_id=work.privacy_domain_id
     AND e.event_id=work.result_event_id AND e.aggregate_id=work.resource_id
     AND e.aggregate_type='runtime-targets' AND e.event_type='runtime-target.activation-failed.v1'
     AND e.payload_cbor=payload AND e.payload_digest=sha256(payload)
     AND e.cose_sign1=a.cose_sign1 AND octet_length(a.cose_sign1)>0
     AND a.evidence_digest=sha256(a.evidence_cbor))
   OR EXISTS(SELECT 1 FROM control.runtime_activation_observation o
    WHERE o.runtime_configuration_generation_id=prior.runtime_configuration_generation_id
     OR o.configuration_work_id=work.configuration_work_id)
   OR EXISTS(SELECT 1 FROM control.policy_activation_occurrence_target o
    WHERE o.runtime_configuration_generation_id=prior.runtime_configuration_generation_id
     OR o.configuration_work_id=work.configuration_work_id)
   OR EXISTS(SELECT 1 FROM control.runtime_target_disposition_admission a
    WHERE a.runtime_target_id=prior.runtime_target_id AND (
     a.binding->'cause'->>'work_id'=work.configuration_work_id::text
     OR a.binding->'source'->>'original_work_id'=work.configuration_work_id::text
     OR a.binding->'source'->>'runtime_configuration_generation_id'=prior.runtime_configuration_generation_id::text))
  THEN RAISE EXCEPTION 'PC-DATA-6007-RUNTIME-RETRY'; END IF;
 END LOOP;
 RETURN NEW;
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='PC-DATA-6007';
END $$;
REVOKE ALL ON FUNCTION openpc.guard_runtime_generation_retry() FROM PUBLIC;
DROP TRIGGER IF EXISTS runtime_generation_retry_guard ON control.runtime_configuration_generation;
CREATE TRIGGER runtime_generation_retry_guard BEFORE INSERT ON control.runtime_configuration_generation
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_runtime_generation_retry();


CREATE OR REPLACE FUNCTION openpc.observe_runtime_artifact_references(p_input uuid,p_digest text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE lock_key text; expected_mode text;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
 OR current_setting('session_replication_role')<>'origin' OR openpc.current_participant_id() IS NULL OR openpc.current_privacy_domain_id() IS NULL
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 OR (p_digest ~ '^sha256:[0-9a-f]{64}$') IS DISTINCT FROM true OR p_input IS NULL
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-OBSERVATION-CONTEXT'; END IF;
 -- Exactly the existing lockModuleLifecycleReferences order; the application
 -- obtains these before this read. Never upgrade/acquire after owner row locks.
 FOREACH lock_key IN ARRAY ARRAY['evidence-lifecycle:'||openpc.current_participant_id()::text,'module-release-catalog','module-admission:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,
 'openpc-policy-generations:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text] LOOP
  expected_mode:=case when lock_key like 'module-admission:%' or lock_key like 'evidence-lifecycle:%' then 'ExclusiveLock' else 'ShareLock' end;
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode=expected_mode
   AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND l.classid=((hashtextextended(lock_key,0)>>32)&4294967295)::oid
   AND l.objid=(hashtextextended(lock_key,0)&4294967295)::oid AND l.objsubid=1)
  THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-OBSERVATION-FENCE'; END IF;
 END LOOP;
 -- All branches use one SQL statement snapshot and original tables, including
 -- terminal rows. The cap produces unresolved coverage, never an empty proof.
 RETURN (select jsonb_build_object('participantId',openpc.current_participant_id()::text,'privacyDomainId',openpc.current_privacy_domain_id()::text,
 'root', (select jsonb_build_object('kind','INPUT','id',(runtime_configuration_input_id)::text,'participantId',participant_id::text,'privacyDomainId',privacy_domain_id::text,'revision',null,'state',case when selected then 'SELECTED' else 'RETAINED' end,'digests',jsonb_build_object('configuration','sha256:'||encode(configuration_digest,'hex'),'bindings','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(resource_bindings),'UTF8')),'hex')),'references',((select coalesce(jsonb_agg(value),'[]'::jsonb) from jsonb_array_elements(jsonb_build_array(case when module_configuration_generation_id is null then null else jsonb_build_object('kind','MODULE_CONFIGURATION','id',(module_configuration_generation_id)::text,'required',true) end,case when module_installation_id is null then null else jsonb_build_object('kind','MODULE_INSTALLATION','id',(module_installation_id)::text,'required',true) end)) where value<>'null'::jsonb)||(select coalesce(jsonb_agg(jsonb_build_object('kind',case binding->>'kind' when 'ProviderProfile' then 'PROVIDER' when 'ClientIndexerProfile' then 'INDEXER' when 'ProjectionPlan' then 'PROJECTION' when 'CiglSettings' then 'CIGL_SETTINGS' else null end,'id',binding->>'id','required',true)),'[]'::jsonb)
 from jsonb_array_elements(resource_bindings) binding where (case binding->>'kind' when 'ProviderProfile' then 'PROVIDER' when 'ClientIndexerProfile' then 'INDEXER' when 'ProjectionPlan' then 'PROJECTION' when 'CiglSettings' then 'CIGL_SETTINGS' else null end) is not null)),'tokens',(select coalesce(jsonb_agg(value),'[]'::jsonb) from jsonb_array_elements(jsonb_build_array(case when 'sha256:'||encode(configuration_digest,'hex') is null then null else jsonb_build_object('kind','CONFIGURATION','digest','sha256:'||encode(configuration_digest,'hex')) end)) where value<>'null'::jsonb),'checks',jsonb_build_object('bytesMatch',(openpc.runtime_artifact_input_information(runtime_configuration_input_id)->>'bytesMatch')::boolean,'bindingsKnown',not exists(select 1 from jsonb_array_elements(resource_bindings) binding where (case binding->>'kind' when 'ProviderProfile' then 'PROVIDER' when 'ClientIndexerProfile' then 'INDEXER' when 'ProjectionPlan' then 'PROJECTION' when 'CiglSettings' then 'CIGL_SETTINGS' else null end) is null)),'details',jsonb_build_object('byteLength',openpc.runtime_artifact_input_information(runtime_configuration_input_id)->>'byteLength','createdAt',to_char(created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))) from control.runtime_configuration_input where participant_id=openpc.current_participant_id()
  and privacy_domain_id=openpc.current_privacy_domain_id() and runtime_configuration_input_id=p_input and configuration_digest=decode(substr(p_digest,8),'hex')),
 'runtimeProducerFencesObserved',not exists(select 1 from unnest(array['runtime_configuration_input','configuration_work','runtime_configuration_generation','runtime_target','policy_activation_occurrence','policy_activation_occurrence_target','runtime_activation_observation','runtime_target_connection','runtime_route_publication','provider_probe_observation','runtime_target_disposition_admission','runtime_target_disposition_delivery','runtime_target_disposition_acknowledgement']) expected(table_name)
 where not exists(select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid
 join pg_namespace n on n.oid=c.relnamespace join pg_roles co on co.oid=c.relowner
 join pg_proc p on p.oid=t.tgfoid join pg_namespace pn on pn.oid=p.pronamespace
 join pg_roles po on po.oid=p.proowner join pg_language lang on lang.oid=p.prolang
 where n.nspname='control' and c.relname=expected.table_name and co.rolname='openpc_control_owner'
 and c.relkind='r' and c.relrowsecurity and not c.relispartition
 and not exists(select 1 from pg_inherits i where i.inhparent=c.oid or i.inhrelid=c.oid)
 and t.tgname='artifact_lifecycle_fence' and t.tgtype=62 and t.tgenabled in ('O','A') and not t.tgisinternal
 and t.tgconstraint=0 and t.tgparentid=0 and not t.tgdeferrable and not t.tginitdeferred
 and t.tgnargs=0 and octet_length(t.tgargs)=0 and t.tgattr::text='' and t.tgqual is null
 and t.tgoldtable is null and t.tgnewtable is null
 and pn.nspname='openpc' and po.rolname='openpc_control_owner' and p.proname='guard_runtime_artifact_lifecycle_fence'
 and lang.lanname='plpgsql' and p.prokind='f' and p.provolatile='v' and not p.prosecdef and not p.proisstrict
 and not p.proleakproof and p.proparallel='u' and not p.proretset and p.prosupport=0
 and p.prorettype='pg_catalog.trigger'::regtype and p.pronargs=0 and p.pronargdefaults=0 and p.provariadic=0 and p.proargmodes is null
 and p.proconfig=array['search_path=pg_catalog']::text[] and p.prosrc='
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_participant_id() IS NULL OR openpc.current_privacy_domain_id() IS NULL
   OR TG_OP=''TRUNCATE'' OR current_setting(''session_replication_role'')<>''origin''
 THEN RAISE EXCEPTION USING ERRCODE=''P0001'',MESSAGE=''PC-DATA-6004''; END IF;
 -- Producers can already own module, policy, target or occurrence locks.
 -- Never wait in the reverse order. Use the exclusive lock also used by
 -- evidence publication, avoiding shared-to-exclusive upgrade deadlocks.
 IF NOT pg_try_advisory_xact_lock(hashtextextended(''evidence-lifecycle:''||
   openpc.current_participant_id()::text,0))
 -- This is a definite statement/transaction abort, not an unknown effect.
 -- Serializable public owners may retry their same operation after rollback.
 THEN RAISE EXCEPTION USING ERRCODE=''40001'',MESSAGE=''PC-DATA-6007''; END IF;
 RETURN NULL;
END ')),
 'dependencyProducerFencesObserved',not exists(select 1 from unnest(array['module_configuration_generation','module_installation','policy_activation','policy_activation_prerequisite','policy_generation','provider_profile','indexer_profile','cigl_settings','projection_plan']) expected(table_name)
 where not exists(select 1 from pg_trigger t join pg_class c on c.oid=t.tgrelid
 join pg_namespace n on n.oid=c.relnamespace join pg_roles co on co.oid=c.relowner
 join pg_proc p on p.oid=t.tgfoid join pg_namespace pn on pn.oid=p.pronamespace
 join pg_roles po on po.oid=p.proowner join pg_language lang on lang.oid=p.prolang
 where n.nspname='control' and c.relname=expected.table_name and co.rolname='openpc_control_owner'
 and c.relkind='r' and c.relrowsecurity and not c.relispartition
 and not exists(select 1 from pg_inherits i where i.inhparent=c.oid or i.inhrelid=c.oid)
 and t.tgname='artifact_lifecycle_fence' and t.tgtype=62 and t.tgenabled in ('O','A') and not t.tgisinternal
 and t.tgconstraint=0 and t.tgparentid=0 and not t.tgdeferrable and not t.tginitdeferred
 and t.tgnargs=0 and octet_length(t.tgargs)=0 and t.tgattr::text='' and t.tgqual is null
 and t.tgoldtable is null and t.tgnewtable is null
 and pn.nspname='openpc' and po.rolname='openpc_control_owner' and p.proname='guard_runtime_artifact_lifecycle_fence'
 and lang.lanname='plpgsql' and p.prokind='f' and p.provolatile='v' and not p.prosecdef and not p.proisstrict
 and not p.proleakproof and p.proparallel='u' and not p.proretset and p.prosupport=0
 and p.prorettype='pg_catalog.trigger'::regtype and p.pronargs=0 and p.pronargdefaults=0 and p.provariadic=0 and p.proargmodes is null
 and p.proconfig=array['search_path=pg_catalog']::text[] and p.prosrc='
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_participant_id() IS NULL OR openpc.current_privacy_domain_id() IS NULL
   OR TG_OP=''TRUNCATE'' OR current_setting(''session_replication_role'')<>''origin''
 THEN RAISE EXCEPTION USING ERRCODE=''P0001'',MESSAGE=''PC-DATA-6004''; END IF;
 -- Producers can already own module, policy, target or occurrence locks.
 -- Never wait in the reverse order. Use the exclusive lock also used by
 -- evidence publication, avoiding shared-to-exclusive upgrade deadlocks.
 IF NOT pg_try_advisory_xact_lock(hashtextextended(''evidence-lifecycle:''||
   openpc.current_participant_id()::text,0))
 -- This is a definite statement/transaction abort, not an unknown effect.
 -- Serializable public owners may retry their same operation after rollback.
 THEN RAISE EXCEPTION USING ERRCODE=''40001'',MESSAGE=''PC-DATA-6007''; END IF;
