CREATE OR REPLACE FUNCTION openpc.guard_evidence_export_selection()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE actual jsonb; v_first_sequence numeric; v_last_sequence numeric;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORTS_CREATE_RESOURCE-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 v_first_sequence:=(NEW.selection->'range'->>'fromSequence')::numeric;
 v_last_sequence:=(NEW.selection->'range'->>'throughSequence')::numeric;
 IF v_first_sequence IS NULL OR v_last_sequence IS NULL OR v_first_sequence<1 OR v_last_sequence<v_first_sequence
  OR v_last_sequence>18446744073709551615 OR v_last_sequence-v_first_sequence>=128
 THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 SELECT jsonb_agg(jsonb_build_object('evidenceId','urn:openpc:resource:'||c.evidence_id::text,
  'sourceRecordId',c.record_id,'segmentId',c.segment_id::text,'objectDigest',s.object_digest,
  'sequence',c.sequence::text,'evidenceClass',c.evidence_class,'recordDigest',c.receipt_digest,
  'occurredAt',to_char(c.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) ORDER BY c.sequence)
 INTO actual FROM control.evidence_catalogue c JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
 WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id
  AND c.sequence BETWEEN v_first_sequence AND v_last_sequence;
 IF actual IS NULL OR jsonb_array_length(actual)<>v_last_sequence-v_first_sequence+1 OR
  NEW.selection IS DISTINCT FROM jsonb_build_object('version','OPENPC_EVIDENCE_EXPORT_SELECTION_V1',
   'participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,
   'range',jsonb_build_object('streamId',NEW.stream_id,'fromSequence',v_first_sequence::text,
    'throughSequence',v_last_sequence::text,'redactionProfileId','pc.evidence.minimized-audit.v1'),'records',actual)
  OR NEW.request_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.selection),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_export_selection_guard ON control.evidence_export_selection;
CREATE TRIGGER evidence_export_selection_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_export_selection
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_export_selection();

CREATE OR REPLACE FUNCTION openpc.guard_evidence_export_request()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE action text; operation uuid; v_through_sequence numeric;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 action:=current_setting('openpc.action_intent_id'); operation:=current_setting('openpc.operation_id')::uuid;
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF action<>'ACT-EVIDENCE_EXPORTS_CREATE_RESOURCE-V1' OR NEW.creation_operation_id<>operation
   OR NEW.last_operation_id<>operation OR NEW.state<>'REQUESTED' OR NEW.start_operation_id IS NOT NULL
   OR NEW.revision<>1 OR NEW.checkpoint<>0 OR NEW.output_digest IS NOT NULL OR NEW.last_error_code IS NOT NULL
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.created_at:=clock_timestamp(); NEW.updated_at:=NEW.created_at;
 ELSE
  IF NEW.revision<>OLD.revision+1 OR NEW.participant_id<>OLD.participant_id OR NEW.privacy_domain_id<>OLD.privacy_domain_id
   OR NEW.evidence_export_id<>OLD.evidence_export_id OR NEW.created_at<>OLD.created_at OR NEW.creation_operation_id<>OLD.creation_operation_id
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF action='ACT-EVIDENCE_EXPORTS_UPDATE_RESOURCE-V1' THEN
   IF OLD.state<>'REQUESTED' OR NEW.state<>'REQUESTED' OR NEW.request_digest=OLD.request_digest
    OR NEW.last_operation_id<>operation OR NEW.last_error_code IS NOT NULL
    OR (to_jsonb(NEW)-ARRAY['request_digest','stream_id','revision','updated_at','last_operation_id']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['request_digest','stream_id','revision','updated_at','last_operation_id'])
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSIF action='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND OLD.state='REQUESTED' THEN
   IF NEW.state<>'RUNNING' OR NEW.last_operation_id<>operation OR NEW.start_operation_id<>operation
    OR (to_jsonb(NEW)-ARRAY['state','revision','updated_at','last_operation_id','start_operation_id']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['state','revision','updated_at','last_operation_id','start_operation_id'])
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSIF action='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND pg_has_role(current_user,'openpc_control_worker','USAGE') THEN
   IF OLD.state NOT IN ('RUNNING','BACKLOGGED') OR NEW.state NOT IN ('SUCCEEDED','FAILED','BACKLOGGED')
    OR operation<>OLD.start_operation_id OR
    (to_jsonb(NEW)-ARRAY['state','revision','updated_at','checkpoint','output_digest','last_error_code']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['state','revision','updated_at','checkpoint','output_digest','last_error_code'])
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   IF NEW.state='SUCCEEDED' THEN
    SELECT (selection->'range'->>'throughSequence')::numeric INTO v_through_sequence FROM control.evidence_export_selection
     WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND request_digest=NEW.request_digest;
    IF NEW.checkpoint IS DISTINCT FROM v_through_sequence OR NEW.last_error_code IS NOT NULL OR NOT EXISTS
     (SELECT 1 FROM control.evidence_export_output WHERE evidence_export_id=NEW.evidence_export_id
       AND participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND output_digest=NEW.output_digest)
    THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   ELSIF NEW.last_error_code IS DISTINCT FROM 'PC-OPS-9002' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSE RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  NEW.updated_at:=clock_timestamp();
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_export_request_guard ON control.evidence_export_request;
CREATE TRIGGER evidence_export_request_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_export_request
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_export_request();

CREATE OR REPLACE FUNCTION openpc.require_evidence_export_command()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE action text; catalog text; expected numeric;
BEGIN
 IF TG_OP='UPDATE' AND OLD.state<>'REQUESTED' THEN RETURN NULL; END IF;
 IF TG_OP='INSERT' THEN action:='ACT-EVIDENCE_EXPORTS_CREATE_RESOURCE-V1';catalog:='CFG-OP-CREATE-EVIDENCE-EXPORT';expected:=0;
 ELSIF NEW.state='REQUESTED' THEN action:='ACT-EVIDENCE_EXPORTS_UPDATE_RESOURCE-V1';catalog:='CFG-OP-UPDATE-EVIDENCE-EXPORT';expected:=OLD.revision;
 ELSE action:='ACT-EVIDENCE_EXPORT_RECORDS-V1';catalog:='CFG-OP-START-EVIDENCE-EXPORT';expected:=OLD.revision; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.mutation_evidence e JOIN control.idempotency_record i
  ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id AND i.operation_id=e.operation_id
   AND i.catalog_operation_id=e.catalog_operation_id AND i.input_digest=e.candidate_digest
  WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND e.operation_id=NEW.last_operation_id AND e.aggregate_type='evidence-export' AND e.aggregate_id=NEW.evidence_export_id
   AND e.catalog_operation_id=catalog AND e.action_intent_id=action AND i.terminal_state='COMMITTED'
   AND i.expected_aggregate_version=expected AND i.result_payload->>'resourceRef'='urn:openpc:resource:'||NEW.evidence_export_id::text
   AND EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=e.participant_id
    AND event.privacy_domain_id=e.privacy_domain_id AND event.aggregate_type=e.aggregate_type AND event.aggregate_id=e.aggregate_id
    AND event.event_type=CASE catalog WHEN 'CFG-OP-CREATE-EVIDENCE-EXPORT' THEN 'openpc.evidence.export.requested.v1'
      WHEN 'CFG-OP-UPDATE-EVIDENCE-EXPORT' THEN 'openpc.evidence.export.updated.v1' ELSE 'openpc.evidence.export.started.v1' END
    AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'candidateDigest'='sha256:'||encode(e.candidate_digest,'hex')
    AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'revision'=NEW.revision::text
    AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'authorizationEvidenceDigest'='sha256:'||encode(e.evidence_digest,'hex')
    AND event.payload_digest=sha256(event.payload_cbor))
   AND (NEW.state<>'RUNNING' OR EXISTS(SELECT 1 FROM control.mutation_candidate c
    WHERE c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id
     AND c.consumed_operation_id=e.operation_id AND c.candidate_digest=e.candidate_digest
     AND c.action_intent_id=action AND c.catalog_operation_id=catalog AND c.operation_class='EXPORT'
     AND c.state='CONSUMED' AND c.candidate_document->>'inputDigest'=NEW.request_digest)))
 THEN RAISE EXCEPTION 'PC-AUTH-0002-EVIDENCE-EXPORT-PROVENANCE'; END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS evidence_export_command_required ON control.evidence_export_request;
CREATE CONSTRAINT TRIGGER evidence_export_command_required AFTER INSERT OR UPDATE ON control.evidence_export_request
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_evidence_export_command();

CREATE OR REPLACE FUNCTION openpc.guard_evidence_export_output()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE request control.evidence_export_request%ROWTYPE; v_selection jsonb; records jsonb; artifact jsonb; assurance text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT request FROM control.evidence_export_request WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND evidence_export_id=NEW.evidence_export_id FOR UPDATE;
 IF request.state NOT IN ('RUNNING','BACKLOGGED') OR request.start_operation_id<>current_setting('openpc.operation_id')::uuid
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT s.selection INTO STRICT v_selection FROM control.evidence_export_selection s WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND request_digest=request.request_digest;
 assurance:=CASE WHEN EXISTS(SELECT 1 FROM control.evidence_archive_trust t WHERE t.participant_id=NEW.participant_id
   AND t.privacy_domain_id=NEW.privacy_domain_id AND t.sink_id=NEW.sink_id)
   THEN 'REMOTE_INTERFACE_VERIFIED' ELSE 'LOCAL_FSYNC_READBACK' END;
 IF assurance='REMOTE_INTERFACE_VERIFIED' THEN
  PERFORM openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),NEW.stream_id);
 END IF;
 SELECT jsonb_agg(jsonb_build_object('evidenceId',r->>'evidenceId','sequence',r->>'sequence',
   'evidenceClass',r->>'evidenceClass','recordDigest',r->>'recordDigest','occurredAt',r->>'occurredAt',
   'segmentDigest',r->>'objectDigest','checkpointDigest',c.checkpoint_digest) ORDER BY (r->>'sequence')::numeric)
 INTO records FROM jsonb_array_elements(v_selection->'records') r JOIN control.evidence_checkpoint c
   ON c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id
    AND c.segment_id=(r->>'segmentId')::uuid AND c.object_digest=r->>'objectDigest' AND c.sink_id=NEW.sink_id
    AND c.receipt->>'assurance'=assurance
    AND (assurance='LOCAL_FSYNC_READBACK' OR (c.receipt->>'kind'='SIGNED_REMOTE_ARCHIVE_V1'
      AND openpc.remote_archive_covers(c.participant_id,c.privacy_domain_id,c.stream_id,c.segment_id,c.sink_id)
      AND EXISTS(SELECT 1 FROM control.evidence_archive_receipt ar JOIN control.evidence_archive_outbox ao
       USING(participant_id,privacy_domain_id,receipt_id) WHERE ar.participant_id=c.participant_id
        AND ar.privacy_domain_id=c.privacy_domain_id AND ar.receipt_digest=c.receipt_digest
        AND ar.receipt_id::text=c.receipt->>'receiptId' AND ar.profile_digest=c.receipt->>'profileDigest')));
 IF records IS NULL OR jsonb_array_length(records)<>jsonb_array_length(v_selection->'records')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 artifact:=jsonb_build_object('version','OPENPC_EVIDENCE_REDACTED_EXPORT_V1',
  'evidenceExportId','urn:openpc:resource:'||NEW.evidence_export_id::text,
  'participantId','urn:openpc:participant:'||NEW.participant_id::text,
  'privacyDomainId','urn:openpc:privacy-domain:'||NEW.privacy_domain_id::text,
  'requestDigest',request.request_digest,'range',v_selection->'range','sinkId',NEW.sink_id,
  'assurance',assurance,'records',records);
 IF assurance='REMOTE_INTERFACE_VERIFIED' THEN artifact:=artifact||jsonb_build_object('providerQualification','NOT_ESTABLISHED'); END IF;
 IF NEW.artifact<>convert_to(openpc.signing_canonical_json(artifact),'UTF8')
  OR NEW.output_digest<>'sha256:'||encode(sha256(NEW.artifact),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_export_output_guard ON control.evidence_export_output;
CREATE TRIGGER evidence_export_output_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_export_output
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_export_output();

CREATE OR REPLACE FUNCTION openpc.require_evidence_export_completion()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.evidence_export_request r WHERE r.participant_id=NEW.participant_id
  AND r.privacy_domain_id=NEW.privacy_domain_id AND r.stream_id=NEW.stream_id AND r.evidence_export_id=NEW.evidence_export_id
  AND r.state='SUCCEEDED' AND r.output_digest=NEW.output_digest)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS evidence_export_completion_required ON control.evidence_export_output;
CREATE CONSTRAINT TRIGGER evidence_export_completion_required AFTER INSERT ON control.evidence_export_output
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_evidence_export_completion();

-- Read the real producer boundary, including the exact original governed start
-- and immutable output. No caller-supplied success, digest or event can replace
-- this join. Historical start evidence is an input, not a new LEGACY event.
CREATE OR REPLACE FUNCTION openpc.evidence_export_completion_source(export_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE source jsonb;
BEGIN
 PERFORM openpc.assert_request_context(false);
 SELECT jsonb_build_object('participantId',r.participant_id::text,'privacyDomainId',r.privacy_domain_id::text,
  'streamId',r.stream_id,'evidenceExportId',r.evidence_export_id::text,'startOperationId',r.start_operation_id::text,
  'causationId',event.event_id::text,'requestDigest',r.request_digest,'checkpoint',r.checkpoint::text,
  'outputDigest',o.output_digest,'recordCount',jsonb_array_length(s.selection->'records')::text)
 INTO STRICT source
 FROM control.evidence_export_request r
 JOIN control.evidence_export_output o USING(participant_id,privacy_domain_id,stream_id,evidence_export_id)
 JOIN control.evidence_export_selection s USING(participant_id,privacy_domain_id,stream_id,request_digest)
 JOIN control.mutation_evidence e ON e.participant_id=r.participant_id AND e.privacy_domain_id=r.privacy_domain_id
  AND e.operation_id=r.start_operation_id AND e.aggregate_id=r.evidence_export_id AND e.aggregate_type='evidence-export'
  AND e.action_intent_id='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND e.catalog_operation_id='CFG-OP-START-EVIDENCE-EXPORT'
 JOIN control.idempotency_record i ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id
  AND i.operation_id=e.operation_id AND i.catalog_operation_id=e.catalog_operation_id AND i.action_intent_id=e.action_intent_id
  AND i.input_digest=e.candidate_digest AND i.terminal_state='COMMITTED'
 JOIN control.mutation_candidate c ON c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id
  AND c.consumed_operation_id=e.operation_id AND c.candidate_digest=e.candidate_digest
  AND c.action_intent_id=e.action_intent_id AND c.catalog_operation_id=e.catalog_operation_id
  AND c.operation_class='EXPORT' AND c.state='CONSUMED' AND c.candidate_document->>'inputDigest'=r.request_digest
 JOIN control.outbox_event event ON event.participant_id=e.participant_id AND event.privacy_domain_id=e.privacy_domain_id
  AND event.aggregate_type=e.aggregate_type AND event.aggregate_id=e.aggregate_id
  AND event.event_type='openpc.evidence.export.started.v1'
  AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'candidateDigest'='sha256:'||encode(e.candidate_digest,'hex')
  AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'revision'=(i.expected_aggregate_version+1)::text
  AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'authorizationEvidenceDigest'='sha256:'||encode(e.evidence_digest,'hex')
  AND event.payload_digest=sha256(event.payload_cbor)
 WHERE r.participant_id=current_setting('openpc.participant_id')::uuid
  AND r.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid AND r.evidence_export_id=export_id
  AND r.state='SUCCEEDED' AND r.output_digest=o.output_digest
  AND r.checkpoint=(s.selection->'range'->>'throughSequence')::numeric
  AND i.result_payload->>'resourceRef'='urn:openpc:resource:'||r.evidence_export_id::text
  AND r.request_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(s.selection),'UTF8')),'hex')
  AND o.output_digest='sha256:'||encode(sha256(o.artifact),'hex')
  AND jsonb_array_length(convert_from(o.artifact,'UTF8')::jsonb->'records')=jsonb_array_length(s.selection->'records');
 RETURN source;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'PC-DATA-6007-EVIDENCE-EXPORT-COMPLETION-SOURCE';
END $$;
REVOKE ALL ON FUNCTION openpc.evidence_export_completion_source(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_export_completion_source(uuid) TO openpc_control_worker,openpc_control_reader;



ALTER TABLE control.evidence_export_producer_installation FORCE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE ON control.evidence_export_producer_installation TO openpc_control_owner;
DROP POLICY IF EXISTS evidence_export_producer_installer ON control.evidence_export_producer_installation;
CREATE POLICY evidence_export_producer_installer ON control.evidence_export_producer_installation
 TO openpc_control_owner USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id))
 WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id));
REVOKE ALL ON control.evidence_export_producer_installation FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.evidence_export_producer_installation TO openpc_control_worker,openpc_control_runtime;

-- The non-superuser installation owner verifies only the scoped initial
-- credential tuple. Runtime principals receive no enrollment or Identity writes.
DROP POLICY IF EXISTS export_producer_installation_identity_read ON control.credential;
CREATE POLICY export_producer_installation_identity_read ON control.credential FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.current_action_intent_id()='ACT-EVIDENCE_EXPORT_RECORDS-V1');

CREATE OR REPLACE FUNCTION openpc.evidence_export_producer_authority(wanted text)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE installed control.evidence_export_producer_installation; authority jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO STRICT installed FROM control.evidence_export_producer_installation
 WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id()
 AND trust_digest=wanted AND state='ACTIVE';
select jsonb_build_object('schema','pc.evidence-export.producer-authority.v1',
      'installationDigest',(installed.trust_digest)::text,'participantEpoch',p.authority_epoch::text,'principalEpoch',a.authority_epoch::text,
      'workloadEpoch',c.credential_epoch::text,'workloadCredentialId',c.credential_id::text,
      'participantId',p.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,
      'principalId',a.principal_id::text,'workloadId',c.audience,'certificateFingerprint',c.secret_fingerprint,
      'keyDigest','sha256:'||encode(c.public_key_digest,'hex'),
      'participantVersion',p.row_version::text,'privacyVersion',d.row_version::text,
      'principalVersion',a.row_version::text,'credentialVersion',c.row_version::text,
      'subject',c.subject,'validFrom',c.valid_from::text,'validUntil',c.valid_until::text) authority
      INTO STRICT authority
      from control.participant p join control.privacy_domain d on d.participant_id=p.participant_id
      join control.principal a on a.participant_id=p.participant_id
      join control.credential c on c.participant_id=a.participant_id and c.principal_id=a.principal_id
      where p.participant_id=(installed.participant_id) and d.privacy_domain_id=(installed.privacy_domain_id) and a.principal_id=(installed.principal_id) and c.credential_id=(installed.workload_credential_id)
      and p.state='ACTIVE' and d.state='ACTIVE' and a.state='ACTIVE' and a.kind='WORKLOAD'
      and c.kind='WORKLOAD_MTLS' and c.state='ACTIVE' and c.credential_epoch=(installed.workload_epoch) and c.audience=(installed.trust->>'workloadId')
      and c.valid_from<=clock_timestamp() and c.valid_until>clock_timestamp()
      and c.public_key_digest<>decode(substring((installed.signer_id)::text from 8),'hex')
      and floor(extract(epoch from clock_timestamp())*1000000)*1000 between (installed.trust->>'validFromNs')::numeric and (installed.trust->>'validUntilNs')::numeric-1 FOR SHARE OF p,d,a,c;
 RETURN authority;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'PC-AUTH-0005-EXPORT-PRODUCER';
END $$;
REVOKE ALL ON FUNCTION openpc.evidence_export_producer_authority(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_export_producer_authority(text) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.guard_evidence_export_producer_installation() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE t jsonb;
BEGIN
 IF NOT pg_has_role(current_user,'openpc_control_owner','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-EXPORT-PRODUCER-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
   OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
   OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 -- A direct UPDATE already has its row lock. Do not wait in reverse order.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-export-producer:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF TG_OP='UPDATE' THEN
   IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state'
   THEN RAISE EXCEPTION 'DATA-6020-EXPORT-PRODUCER-IMMUTABLE'; END IF;
   RETURN NEW;
 END IF;
 t:=NEW.trust;
 IF NEW.state<>'ACTIVE' OR jsonb_typeof(t) IS DISTINCT FROM 'object'
   OR t - ARRAY['schema','schemaDefinitionDigest','owner','purpose','environmentId','participantId','privacyDomainId','sourceId','principalId','workloadCredentialId','workloadEpoch','workloadId','secretClass','secretReference','secretVersion','publicKeySpkiHex','keyEpoch','validFromNs','validUntilNs','installationReference','signerKeyId'] IS DISTINCT FROM '{}'::jsonb
   OR (SELECT count(*) FROM jsonb_object_keys(t))<>21
   OR t->>'schema' IS DISTINCT FROM 'pc.evidence-export.producer-trust.v1'
   OR t->>'schemaDefinitionDigest' IS DISTINCT FROM 'sha256:ee72df3cca5024c26c52c5983b15087426b4faabeb511cace227b92a04d2eb8f'
   OR t->>'owner' IS DISTINCT FROM 'LS-EVIDENCE-EXPORT'
   OR t->>'purpose' IS DISTINCT FROM 'pc.cose.evidence-export-completion-receipt.v1'
   OR t->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY'
   OR t->>'participantId' IS DISTINCT FROM NEW.participant_id::text
   OR t->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
   OR t->>'sourceId' IS DISTINCT FROM NEW.source_id::text
   OR t->>'principalId' IS DISTINCT FROM NEW.principal_id::text
   OR t->>'workloadCredentialId' IS DISTINCT FROM NEW.workload_credential_id::text
   OR t->>'workloadEpoch' IS DISTINCT FROM NEW.workload_epoch::text
   OR t->>'environmentId' IS DISTINCT FROM NEW.environment_id
   OR t->>'signerKeyId' IS DISTINCT FROM NEW.signer_id
   OR EXISTS(SELECT 1 FROM jsonb_each(t) e WHERE jsonb_typeof(e.value)<>'string' OR e.value#>>'{}'<>btrim(e.value#>>'{}'))
   OR NOT coalesce(t->>'environmentId' ~ '^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$',false)
   OR NOT coalesce(t->>'secretReference' ~ '^secret://[a-z][a-z0-9-]{1,31}/[A-Za-z0-9._/-]{1,192}#[A-Za-z0-9._-]{1,96}$',false)
   OR split_part(t->>'secretReference','#',2) IS DISTINCT FROM t->>'secretVersion'
   OR lower(t->>'secretVersion') IN ('latest','current')
   OR length(t->>'workloadId') NOT BETWEEN 1 AND 160 OR length(t->>'installationReference') NOT BETWEEN 1 AND 256
   OR NEW.trust_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(t),'UTF8')
   OR NEW.signer_id IS DISTINCT FROM 'sha256:'||encode(sha256(decode(t->>'publicKeySpkiHex','hex')),'hex')
   OR NOT coalesce(t->>'publicKeySpkiHex' ~ '^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$',false)
   OR NOT coalesce(t->>'keyEpoch' ~ '^[1-9][0-9]{0,19}$',false)
   OR NOT coalesce(t->>'validFromNs' ~ '^(0|[1-9][0-9]{0,19})$',false)
   OR NOT coalesce(t->>'validUntilNs' ~ '^[1-9][0-9]{0,19}$',false)
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-PRODUCER-TRUST'; END IF;
 IF (t->>'keyEpoch')::numeric>18446744073709551615 OR (t->>'validUntilNs')::numeric>18446744073709551615
   OR (t->>'validFromNs')::numeric>=(t->>'validUntilNs')::numeric
   OR mod((t->>'validFromNs')::numeric,1000)<>0 OR mod((t->>'validUntilNs')::numeric,1000)<>0
   OR NOT EXISTS(SELECT 1 FROM control.credential c WHERE c.participant_id=NEW.participant_id
      AND c.credential_id=NEW.workload_credential_id AND c.principal_id=NEW.principal_id
      AND c.kind='WORKLOAD_MTLS' AND c.audience=t->>'workloadId'
      AND c.credential_epoch=NEW.workload_epoch
      AND c.public_key_digest<>decode(substr(NEW.signer_id,8),'hex'))
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-PRODUCER-IDENTITY'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_export_producer_installation_guard ON control.evidence_export_producer_installation;
CREATE TRIGGER evidence_export_producer_installation_guard BEFORE INSERT OR UPDATE OR DELETE
 ON control.evidence_export_producer_installation FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_export_producer_installation();


ALTER TABLE control.evidence_export_completion FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_export_completion FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.evidence_export_completion TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT INSERT ON control.evidence_export_completion TO openpc_control_runtime;
GRANT UPDATE(state,cose_sign1) ON control.evidence_export_completion TO openpc_control_runtime;
GRANT EXECUTE ON FUNCTION openpc.archive_cose_binding(bytea,bytea,text,integer,integer) TO openpc_control_runtime;
GRANT EXECUTE ON FUNCTION openpc.evidence_export_completion_source(uuid) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.guard_evidence_export_completion_preparation() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE c jsonb; source jsonb; installed control.evidence_export_producer_installation; expected jsonb; now_ns numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='UPDATE' THEN
  IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
   OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
   OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
   OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
   OR NOT ((OLD.state='PREPARED' AND NEW.state='OBSERVED' AND OLD.cose_sign1 IS NULL AND NEW.cose_sign1 IS NOT NULL)
    OR (OLD.state='OBSERVED' AND NEW.state='PUBLISHED' AND OLD.cose_sign1 IS NOT NULL AND NEW.cose_sign1=OLD.cose_sign1))
   OR to_jsonb(NEW)-ARRAY['state','cose_sign1'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','cose_sign1']
  THEN RAISE EXCEPTION 'DATA-6020-EXPORT-COMPLETION-IMMUTABLE'; END IF;
  -- A direct UPDATE already owns a row lock. Never wait in reverse order.
  IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('evidence-export-producer:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF NEW.authority_snapshot IS DISTINCT FROM convert_to(openpc.signing_canonical_json(openpc.evidence_export_producer_authority(NEW.trust_digest)),'UTF8')
  THEN RAISE EXCEPTION 'PC-AUTH-0005-EXPORT-COMPLETION-AUTHORITY'; END IF;
  source:=openpc.evidence_export_completion_source(NEW.evidence_export_id);
  IF source->>'streamId' IS DISTINCT FROM NEW.stream_id OR
   source-'streamId' IS DISTINCT FROM NEW.claims-ARRAY['environmentId','eventId','sourceId','sequence','recordedAtNs','dataDigest','authoritySnapshotDigest','signerTrustSnapshotDigest','signerKeyId']
  THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-BINDING'; END IF;
  PERFORM openpc.archive_cose_binding(NEW.receipt_payload,NEW.cose_sign1,NEW.claims->>'signerKeyId',24013,350);
  RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-EXPORT-COMPLETION-IMMUTABLE'; END IF;
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 OR NEW.state<>'PREPARED' OR NEW.cose_sign1 IS NOT NULL
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('evidence-export-producer:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT installed FROM control.evidence_export_producer_installation
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND trust_digest=NEW.trust_digest AND state='ACTIVE';
 IF NEW.authority_snapshot IS DISTINCT FROM convert_to(openpc.signing_canonical_json(openpc.evidence_export_producer_authority(NEW.trust_digest)),'UTF8')
 THEN RAISE EXCEPTION 'PC-AUTH-0005-EXPORT-COMPLETION-AUTHORITY'; END IF;
 source:=openpc.evidence_export_completion_source(NEW.evidence_export_id);
 c:=NEW.claims;
 expected:=(source-'streamId')||jsonb_build_object(
  'environmentId',installed.environment_id,'eventId',NEW.event_id::text,'sourceId',installed.source_id::text,
  'sequence','1','recordedAtNs',c->>'recordedAtNs','dataDigest','sha256:'||encode(sha256(NEW.source_data),'hex'),
  'authoritySnapshotDigest','sha256:'||encode(sha256(NEW.authority_snapshot),'hex'),
  'signerTrustSnapshotDigest',installed.trust_digest,'signerKeyId',installed.signer_id);
 IF c IS DISTINCT FROM expected OR source->>'streamId' IS DISTINCT FROM NEW.stream_id
 OR coalesce(c->>'recordedAtNs','')!~'^[1-9][0-9]{0,19}$'
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-BINDING'; END IF;
 now_ns:=floor(extract(epoch from clock_timestamp())*1000000)*1000;
 IF (c->>'recordedAtNs')::numeric>now_ns OR (c->>'recordedAtNs')::numeric<now_ns-5000000000
 OR mod((c->>'recordedAtNs')::numeric,1000)<>0
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-TIME'; END IF;
 IF openpc.business_cbor(NEW.source_data) IS DISTINCT FROM jsonb_build_object(
  '0','urn:openpc:resource:'||NEW.evidence_export_id::text,'1',(source->>'checkpoint')::numeric,
  '2',openpc.business_bytes(decode(substr(source->>'outputDigest',8),'hex')),'3',(source->>'recordCount')::numeric)
 OR openpc.business_cbor(NEW.receipt_payload) IS DISTINCT FROM jsonb_build_object('0',openpc.business_bytes(decode('ee72df3cca5024c26c52c5983b15087426b4faabeb511cace227b92a04d2eb8f','hex')),'1',c->>'environmentId','2',openpc.business_uuid((c->>'participantId')::uuid),'3',openpc.business_uuid((c->>'privacyDomainId')::uuid),'4',openpc.business_uuid((c->>'eventId')::uuid),'5',openpc.business_uuid((c->>'sourceId')::uuid),'6',openpc.business_uuid((c->>'evidenceExportId')::uuid),'7',openpc.business_uuid((c->>'startOperationId')::uuid),'8',openpc.business_uuid((c->>'causationId')::uuid),'9',(c->>'sequence')::numeric,'10',(c->>'recordedAtNs')::numeric,'11',openpc.business_bytes(decode(substr(c->>'requestDigest',8),'hex')),'12',(c->>'checkpoint')::numeric,'13',openpc.business_bytes(decode(substr(c->>'outputDigest',8),'hex')),'14',(c->>'recordCount')::numeric,'15',openpc.business_bytes(decode(substr(c->>'dataDigest',8),'hex')),'16',openpc.business_bytes(decode(substr(c->>'authoritySnapshotDigest',8),'hex')),'17',openpc.business_bytes(decode(substr(c->>'signerTrustSnapshotDigest',8),'hex')),'18',c->>'signerKeyId')
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-PAYLOAD'; END IF;
 expected:=jsonb_build_object('specversion','1.0','id',NEW.event_id::text,'source','urn:openpc:service:'||installed.source_id::text,
  'type','io.openpc.evidence.export.completed.v1','subject','urn:openpc:resource:'||NEW.evidence_export_id::text,
  'time',to_char(to_timestamp(floor((c->>'recordedAtNs')::numeric/1000000000)::double precision) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS')||'.'||lpad(mod((c->>'recordedAtNs')::numeric/1000,1000000)::bigint::text,6,'0')||'Z',
  'datacontenttype','application/json','dataschema','https://schemas.openpc.local/event-payloads.schema.json#/$defs/EvidenceExportCompleted',
  'participantid','urn:openpc:participant:'||NEW.participant_id::text,'privacydomainid','urn:openpc:privacy-domain:'||NEW.privacy_domain_id::text,
  'correlationid',source->>'startOperationId','causationid',source->>'causationId','sequence','1','datadigest',c->>'dataDigest',
  'data',jsonb_build_object('evidenceExportId','urn:openpc:resource:'||NEW.evidence_export_id::text,'checkpoint',source->>'checkpoint','outputDigest',source->>'outputDigest','recordCount',source->>'recordCount'));
 IF NEW.event_payload IS DISTINCT FROM convert_to(openpc.signing_canonical_json(expected),'UTF8')
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-EVENT'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_evidence_export_completion_preparation() FROM PUBLIC;
DROP TRIGGER IF EXISTS evidence_export_completion_preparation ON control.evidence_export_completion;
CREATE TRIGGER evidence_export_completion_preparation BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_export_completion
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_export_completion_preparation();


CREATE OR REPLACE FUNCTION openpc.check_evidence_export_completion_event(event control.outbox_event)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE completion control.evidence_export_completion%ROWTYPE; claims jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
  OR event.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR event.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT completion FROM control.evidence_export_completion
 WHERE participant_id=event.participant_id AND privacy_domain_id=event.privacy_domain_id AND event_id=event.event_id;
 claims:=completion.claims;
 IF completion.state NOT IN ('OBSERVED','PUBLISHED') OR completion.cose_sign1 IS NULL
  OR event.proof_kind<>'EVIDENCE_EXPORT_COMPLETION_REFERENCE'
  OR event.sequence_namespace<>'EVIDENCE_EXPORT_COMPLETION_V1'
  OR event.aggregate_type<>'evidence-export' OR event.aggregate_id<>completion.evidence_export_id
  OR event.aggregate_sequence IS NOT NULL OR event.business_sequence IS DISTINCT FROM 1::numeric
  OR event.receipt_id IS NOT NULL OR event.cose_sign1 IS NOT NULL
  OR event.authority_generation IS NOT NULL OR event.webauthn_assertion_binding_digest IS NOT NULL
  OR event.event_type<>'io.openpc.evidence.export.completed.v1'
  OR event.data_schema_uri IS DISTINCT FROM 'https://schemas.openpc.local/event-payloads.schema.json#/$defs/EvidenceExportCompleted'
  OR event.source IS DISTINCT FROM 'urn:openpc:service:'||(claims->>'sourceId')
  OR event.subject IS DISTINCT FROM 'urn:openpc:resource:'||completion.evidence_export_id::text
  OR event.correlation_id::text IS DISTINCT FROM claims->>'startOperationId'
  OR event.causation_id::text IS DISTINCT FROM claims->>'causationId'
  OR floor(extract(epoch from event.occurred_at)*1000000)*1000 IS DISTINCT FROM (claims->>'recordedAtNs')::numeric
  OR event.payload_cbor IS DISTINCT FROM completion.source_data
  OR event.payload_digest IS DISTINCT FROM sha256(completion.source_data)
 THEN RAISE EXCEPTION 'DATA-6021-EXPORT-COMPLETION-OUTBOX'; END IF;
 PERFORM openpc.archive_cose_binding(completion.receipt_payload,completion.cose_sign1,claims->>'signerKeyId',24013,350);
END $$;
REVOKE ALL ON FUNCTION openpc.check_evidence_export_completion_event(control.outbox_event) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.check_evidence_export_completion_event(control.outbox_event) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.check_evidence_export_publication_pair()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE completion control.evidence_export_completion%ROWTYPE; event control.outbox_event%ROWTYPE;
BEGIN
 SELECT * INTO STRICT completion FROM control.evidence_export_completion
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 SELECT * INTO STRICT event FROM control.outbox_event
 WHERE participant_id=completion.participant_id AND privacy_domain_id=completion.privacy_domain_id AND event_id=completion.event_id;
 IF completion.state<>'PUBLISHED' THEN RAISE EXCEPTION 'DATA-6021-EXPORT-PUBLICATION-INCOMPLETE'; END IF;
 PERFORM openpc.check_evidence_export_completion_event(event);
 RETURN NULL;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'DATA-6021-EXPORT-PUBLICATION-INCOMPLETE';
END $$;
REVOKE ALL ON FUNCTION openpc.check_evidence_export_publication_pair() FROM PUBLIC;
DROP TRIGGER IF EXISTS evidence_export_publication_pair ON control.evidence_export_completion;
CREATE CONSTRAINT TRIGGER evidence_export_publication_pair AFTER UPDATE ON control.evidence_export_completion
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.state='PUBLISHED')
 EXECUTE FUNCTION openpc.check_evidence_export_publication_pair();
DROP TRIGGER IF EXISTS evidence_export_outbox_pair ON control.outbox_event;
CREATE CONSTRAINT TRIGGER evidence_export_outbox_pair AFTER INSERT ON control.outbox_event
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.proof_kind='EVIDENCE_EXPORT_COMPLETION_REFERENCE')
 EXECUTE FUNCTION openpc.check_evidence_export_publication_pair();


ALTER TABLE control.evidence_kms_installation FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_kms_installation FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.evidence_kms_installation TO openpc_control_runtime;
GRANT SELECT,INSERT,UPDATE ON control.evidence_kms_installation TO openpc_control_owner;
DROP POLICY IF EXISTS evidence_kms_installer ON control.evidence_kms_installation;
CREATE POLICY evidence_kms_installer ON control.evidence_kms_installation TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id))
 WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id));

CREATE OR REPLACE FUNCTION openpc.guard_evidence_kms_installation() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p jsonb; allowed text[]; item text;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_owner','USAGE')
 OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-kms-installation:'||NEW.participant_id::text||':'||
 NEW.privacy_domain_id::text||':'||NEW.installation_id::text,0)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF TG_OP='UPDATE' THEN
   IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED'
   OR to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state'
   THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
   RETURN NEW;
 END IF;
 p:=NEW.pins;
 allowed:=ARRAY['owner','secretClass','environmentId','participantId','privacyDomainId','installationId',
 'producerTrustDigest','reference','version','keyEpoch','providerId','providerOrigin','providerTlsSpkiDigest',
 'profileIssuerSpkiHex','providerReceiptSpkiHex','recoveryAuthoritySpkiHex','providerKeyId','providerKeyVersion','wrapProfileDigest',
 'policyDigest','recoveryProfileDigest','profileDigest','permissions','validFromMs','validUntilMs'];
 IF NEW.state<>'ACTIVE' OR jsonb_typeof(p) IS DISTINCT FROM 'object'
 OR p-allowed IS DISTINCT FROM '{}'::jsonb OR NOT p ?& allowed
 OR p->>'owner' IS DISTINCT FROM 'LS-EVIDENCE-EXPORT'
 OR p->>'secretClass' IS DISTINCT FROM 'SECRET-EVIDENCE-VAULT'
 OR p->>'participantId' IS DISTINCT FROM NEW.participant_id::text
 OR p->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
 OR p->>'installationId' IS DISTINCT FROM NEW.installation_id::text
 OR p->>'producerTrustDigest' IS DISTINCT FROM NEW.producer_trust_digest
 OR NEW.pins_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(p),'UTF8')
 OR NEW.installation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.pins_bytes),'hex')
 OR EXISTS(SELECT 1 FROM jsonb_each(p-ARRAY['permissions','validFromMs','validUntilMs']) e
   WHERE jsonb_typeof(e.value)<>'string' OR e.value#>>'{}'<>btrim(e.value#>>'{}')
   OR e.value#>>'{}' ~ '[[:cntrl:]]')
 OR NOT coalesce(p->>'reference' ~ '^secret://[a-z][a-z0-9-]{1,31}/[A-Za-z0-9._/-]{1,192}#[A-Za-z0-9._-]{1,96}$',false)
 OR split_part(p->>'reference','#',2) IS DISTINCT FROM p->>'version'
 OR split_part(p->>'reference','/',3) IS DISTINCT FROM p->>'providerId'
 OR p->>'reference' ~ '/(\.|\.\.)/' OR p->>'reference' ~ '/(\.|\.\.)#'
 OR p->>'reference' ~ '^secret://[^/]+//|^secret://[^/]+/[^#]*//'
 OR lower(p->>'version') IN ('latest','current')
 OR lower(p->>'providerKeyVersion') IN ('latest','current')
 OR NOT coalesce(p->>'providerOrigin' ~ '^https://[a-z0-9.-]+(:[1-9][0-9]{0,4})?$',false)
 OR NOT coalesce(p->>'environmentId' ~ '^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$',false)
 OR length(p->>'providerKeyId') NOT BETWEEN 1 AND 256
 OR length(p->>'providerKeyVersion') NOT BETWEEN 1 AND 96
 OR length(p->>'providerOrigin') NOT BETWEEN 1 AND 512
 OR jsonb_typeof(p->'permissions') IS DISTINCT FROM 'array'
 OR NOT coalesce(p->'permissions' IN ('["ENCRYPT"]'::jsonb,'["DECRYPT"]'::jsonb,'["DECRYPT","ENCRYPT"]'::jsonb),false)
 OR NOT coalesce(p->>'keyEpoch' ~ '^[1-9][0-9]{0,19}$',false)
 OR jsonb_typeof(p->'validFromMs') IS DISTINCT FROM 'number'
 OR jsonb_typeof(p->'validUntilMs') IS DISTINCT FROM 'number'
 OR NOT coalesce(p->>'validFromMs' ~ '^(0|[1-9][0-9]{0,15})$',false)
 OR NOT coalesce(p->>'validUntilMs' ~ '^[1-9][0-9]{0,15}$',false)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-INSTALLATION'; END IF;
 FOREACH item IN ARRAY ARRAY['producerTrustDigest','providerTlsSpkiDigest','wrapProfileDigest','policyDigest','recoveryProfileDigest','profileDigest'] LOOP
  IF NOT coalesce(p->>item ~ '^sha256:[0-9a-f]{64}$',false) THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-DIGEST'; END IF;
 END LOOP;
 FOREACH item IN ARRAY ARRAY['profileIssuerSpkiHex','providerReceiptSpkiHex','recoveryAuthoritySpkiHex'] LOOP
  IF NOT coalesce(p->>item ~ '^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$',false)
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-TRUST'; END IF;
 END LOOP;
 IF p->>'profileIssuerSpkiHex' IN (p->>'providerReceiptSpkiHex',p->>'recoveryAuthoritySpkiHex')
 OR p->>'providerReceiptSpkiHex'=p->>'recoveryAuthoritySpkiHex'
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ROLE-SEPARATION'; END IF;
 IF (p->>'keyEpoch')::numeric>18446744073709551615
 OR (p->>'validUntilMs')::numeric>9007199254740991
 OR (p->>'validFromMs')::numeric>=(p->>'validUntilMs')::numeric
 OR NOT EXISTS(SELECT 1 FROM control.evidence_export_producer_installation e
   WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND e.trust_digest=NEW.producer_trust_digest AND e.state='ACTIVE'
   AND e.environment_id=p->>'environmentId')
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PRODUCER'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_kms_installation_guard ON control.evidence_kms_installation;
CREATE TRIGGER evidence_kms_installation_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_kms_installation
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_kms_installation();


ALTER TABLE control.evidence_kms_attempt FORCE ROW LEVEL SECURITY;
ALTER TABLE control.evidence_wrapped_key FORCE ROW LEVEL SECURITY;
ALTER TABLE control.evidence_kms_exchange FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_kms_attempt,control.evidence_wrapped_key,control.evidence_kms_exchange
 FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader,openpc_control_owner;
-- This migration runs as the table owner. Restore only its DDL privilege while
-- replacing triggers; the complete receipt tail revokes it again before commit.
GRANT TRIGGER ON control.evidence_kms_attempt,control.evidence_wrapped_key,control.evidence_kms_exchange TO openpc_control_owner;
GRANT SELECT,INSERT,UPDATE ON control.evidence_kms_attempt TO openpc_control_runtime;
GRANT SELECT ON control.evidence_wrapped_key,control.evidence_kms_exchange TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.guard_evidence_kms_attempt() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE installed control.evidence_kms_installation; r jsonb; o jsonb; authority jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR current_setting('openpc.action_intent_id')<>'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT installed FROM control.evidence_kms_installation
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
 AND installation_digest=NEW.installation_digest;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('evidence-kms-installation:'||NEW.participant_id::text||':'||
 NEW.privacy_domain_id::text||':'||installed.installation_id::text,0));
 SELECT * INTO STRICT installed FROM control.evidence_kms_installation
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
 AND installation_digest=NEW.installation_digest;
 -- Current Identity authority is necessary; it does not authenticate a peer or
 -- replace the application owner using its actual TLS socket.
 authority:=openpc.evidence_export_producer_authority(installed.producer_trust_digest);
 IF TG_OP='UPDATE' THEN
  IF NEW.state IN ('PROVED','REJECTED') THEN
   IF OLD.state NOT IN ('DISPATCHED','UNKNOWN') OR
     to_jsonb(OLD)-ARRAY['state','result_receipt_bytes','result_receipt_digest'] IS DISTINCT FROM
     to_jsonb(NEW)-ARRAY['state','result_receipt_bytes','result_receipt_digest'] OR
     NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=NEW.participant_id
       AND e.privacy_domain_id=NEW.privacy_domain_id AND e.attempt_id=NEW.attempt_id AND e.state='PROVED'
       AND e.kind IN ('PREPARE','READ_ATTEMPT') AND e.receipt_bytes=NEW.result_receipt_bytes
       AND e.receipt_digest=NEW.result_receipt_digest
       AND openpc.evidence_kms_stored_outcome(e.receipt_bytes)=CASE WHEN NEW.state='PROVED' THEN '1' ELSE '2' END)
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RESULT-BINDING'; END IF;
   IF NEW.state='PROVED' AND NOT EXISTS(SELECT 1 FROM control.evidence_wrapped_key k
     WHERE k.participant_id=NEW.participant_id AND k.privacy_domain_id=NEW.privacy_domain_id AND k.attempt_id=NEW.attempt_id)
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD-MISSING'; END IF;
   RETURN NEW;
  END IF;
  IF to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state'
    OR NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED')
      OR (OLD.state IN ('DISPATCHED','UNKNOWN') AND NEW.state='UNKNOWN'))
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-TRANSITION'; END IF;
  IF NEW.state='UNKNOWN' THEN RETURN NEW; END IF;
 ELSE
  IF NEW.state<>'PREPARED' OR NEW.result_receipt_bytes IS NOT NULL OR NEW.result_receipt_digest IS NOT NULL
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PREPARE'; END IF;
 END IF;
 IF installed.state<>'ACTIVE' OR NOT installed.pins->'permissions' ? 'ENCRYPT'
 OR floor(extract(epoch from clock_timestamp())*1000)<(installed.pins->>'validFromMs')::numeric
 OR floor(extract(epoch from clock_timestamp())*1000)>=(installed.pins->>'validUntilMs')::numeric
 THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
 IF TG_OP='UPDATE' THEN RETURN NEW; END IF;
 IF NEW.authority_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(authority),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-AUTHORITY'; END IF;
 r:=NEW.request; o:=r->'objectIntent';
 IF jsonb_typeof(r) IS DISTINCT FROM 'object'
 OR r-ARRAY['operation','recipient','attemptId','objectIntent','challenge'] IS DISTINCT FROM '{}'::jsonb
 OR NOT r ?& ARRAY['operation','recipient','attemptId','objectIntent','challenge']
 OR r->>'operation' IS DISTINCT FROM 'PREPARE'
 OR r->'recipient' IS DISTINCT FROM jsonb_build_object('participantId',NEW.participant_id::text,
   'privacyDomainId',NEW.privacy_domain_id::text,'installationDigest',NEW.installation_digest,
   'producerTrustDigest',installed.producer_trust_digest)
 OR r->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
 OR NOT coalesce(r->>'challenge' ~ '^[0-9a-f]{64}$',false)
 OR jsonb_typeof(o) IS DISTINCT FROM 'object'
 OR o-ARRAY['environmentId','participantId','privacyDomainId','payloadObjectId','objectVersion',
   'notificationOccurrenceRef','routingProfileDigest','templateDigest','recipientSetDigest',
   'redactionProfileDigest','preferenceGeneration','payloadDigest'] IS DISTINCT FROM '{}'::jsonb
 OR NOT o ?& ARRAY['environmentId','participantId','privacyDomainId','payloadObjectId','objectVersion',
   'notificationOccurrenceRef','routingProfileDigest','templateDigest','recipientSetDigest',
   'redactionProfileDigest','preferenceGeneration','payloadDigest']
 OR o->>'environmentId' IS DISTINCT FROM installed.pins->>'environmentId'
 OR o->>'participantId' IS DISTINCT FROM NEW.participant_id::text
 OR o->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
 OR o->>'payloadObjectId' IS DISTINCT FROM NEW.object_id::text
 OR o->>'objectVersion' IS DISTINCT FROM NEW.object_version
 OR NEW.object_intent_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(o),'UTF8')),'hex')
 OR NEW.request_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(r),'UTF8')
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-REQUEST'; END IF;
 RETURN NEW;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'PC-AUTH-0005';
END $$;
DROP TRIGGER IF EXISTS evidence_kms_attempt_guard ON control.evidence_kms_attempt;
CREATE TRIGGER evidence_kms_attempt_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_kms_attempt
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_kms_attempt();


CREATE OR REPLACE FUNCTION openpc.evidence_kms_cose_binding(payload bytea,cose bytea,family text,signer text)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE m jsonb; c jsonb; h jsonb; parsed jsonb; wanted_schema integer; wanted_purpose integer; wanted_digest text; wanted_fields integer;
BEGIN
 CASE family
 WHEN 'EvidenceKmsProfileV1' THEN wanted_schema:=24015; wanted_purpose:=352; wanted_digest:='0c1c466ce7dc697f151bfb0d574a8837d11ae52b6c94d7f454b29120546376fe'; wanted_fields:=28;
WHEN 'EvidenceWrappedKeyRecordV1' THEN wanted_schema:=24016; wanted_purpose:=353; wanted_digest:='b69bd016306d45d700e68aea1ce41225a774556df3070dbfea71d762cde3b700'; wanted_fields:=20;
WHEN 'EvidenceKmsReceiptV1' THEN wanted_schema:=24017; wanted_purpose:=354; wanted_digest:='2de3abbbc13222bd7473f0aa11d9dcbfb1bb9b538f0e426259d276c17b5d8ad2'; wanted_fields:=31;
 ELSE RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-FAMILY'; END CASE;
 IF octet_length(payload) NOT BETWEEN 1 AND 65536 OR octet_length(cose) NOT BETWEEN 1 AND 131072 OR get_byte(cose,0)<>210
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-COSE'; END IF;
 parsed:=openpc.business_cbor_item(cose,1,0); c:=parsed->'value';
 IF (parsed->>'next')::integer<>octet_length(cose) OR jsonb_typeof(c) IS DISTINCT FROM 'array'
 OR jsonb_array_length(c)<>4 OR c->1 IS DISTINCT FROM '{}'::jsonb
 OR c->2 IS DISTINCT FROM jsonb_build_object('bytes',encode(payload,'hex'))
 OR length(c->3->>'bytes') IS DISTINCT FROM 128 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-COSE'; END IF;
 h:=openpc.business_cbor(decode(c->0->>'bytes','hex'));
 IF h IS DISTINCT FROM jsonb_build_object('1',-7,'2',jsonb_build_array(100,101,102,103),'3','application/pc+cbor',
 '4',jsonb_build_object('bytes',encode(convert_to(signer,'UTF8'),'hex')),'100',wanted_schema,'101',1,'102',wanted_purpose,'103',2)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ROLE'; END IF;
 m:=openpc.business_cbor(payload);
 IF jsonb_typeof(m) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(m))<>wanted_fields
 OR m->'0' IS DISTINCT FROM jsonb_build_object('bytes',wanted_digest)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-DEFINITION'; END IF;
 CASE family
 WHEN 'EvidenceKmsProfileV1' THEN RETURN jsonb_build_object('environmentId',m->>'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'profileId',(m->'4'->>'bytes')::uuid::text,'revision',m->>'5','producerTrustDigest','sha256:'||(m->'6'->>'bytes'),'owner',m->>'7','secretClass',m->>'8','providerId',m->>'9','reference',m->>'10','version',m->>'11','providerKeyId',m->>'12','providerKeyVersion',m->>'13','keyEpoch',m->>'14','wrapProfileDigest','sha256:'||(m->'15'->>'bytes'),'policyDigest','sha256:'||(m->'16'->>'bytes'),'recoveryProfileDigest','sha256:'||(m->'17'->>'bytes'),'providerOrigin',m->>'18','providerTlsSpkiDigest','sha256:'||(m->'19'->>'bytes'),'receiptKeyId','sha256:'||(m->'20'->>'bytes'),'recoveryKeyId','sha256:'||(m->'21'->>'bytes'),'permissions',m->>'22','kekExportPolicy',m->>'23','recoveryMode',m->>'24','validFromMs',m->>'25','validUntilMs',m->>'26','issuerKeyId','sha256:'||(m->'27'->>'bytes'));
WHEN 'EvidenceWrappedKeyRecordV1' THEN RETURN jsonb_build_object('environmentId',m->>'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'attemptId',(m->'4'->>'bytes')::uuid::text,'originalRequestDigest','sha256:'||(m->'5'->>'bytes'),'objectIntentDigest','sha256:'||(m->'6'->>'bytes'),'profileDigest','sha256:'||(m->'7'->>'bytes'),'providerId',m->>'8','reference',m->>'9','version',m->>'10','providerKeyId',m->>'11','providerKeyVersion',m->>'12','keyEpoch',m->>'13','wrapProfileDigest','sha256:'||(m->'14'->>'bytes'),'policyDigest','sha256:'||(m->'15'->>'bytes'),'recoveryProfileDigest','sha256:'||(m->'16'->>'bytes'),'wrappedKey',m->'17'->>'bytes','createdAtMs',m->>'18','signerKeyId','sha256:'||(m->'19'->>'bytes'));
WHEN 'EvidenceKmsReceiptV1' THEN RETURN jsonb_build_object('environmentId',m->>'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'receiptId',(m->'4'->>'bytes')::uuid::text,'profileDigest','sha256:'||(m->'5'->>'bytes'),'operation',m->>'6','attemptId',(m->'7'->>'bytes')::uuid::text,'exchangeId',(m->'8'->>'bytes')::uuid::text,'requestDigest','sha256:'||(m->'9'->>'bytes'),'challenge',m->'10'->>'bytes','objectIntentDigest','sha256:'||(m->'11'->>'bytes'),'keyId','sha256:'||(m->'12'->>'bytes'),'keyUse',m->>'13','providerId',m->>'14','reference',m->>'15','version',m->>'16','providerKeyId',m->>'17','providerKeyVersion',m->>'18','keyEpoch',m->>'19','wrapProfileDigest','sha256:'||(m->'20'->>'bytes'),'policyDigest','sha256:'||(m->'21'->>'bytes'),'recoveryProfileDigest','sha256:'||(m->'22'->>'bytes'),'outcome',m->>'23','keyState',m->>'24','providerSequence',m->>'25','recoveryFloor',m->>'26','materialDigest','sha256:'||(m->'27'->>'bytes'),'observedAtMs',m->>'28','validUntilMs',m->>'29','signerKeyId','sha256:'||(m->'30'->>'bytes'));
 END CASE;
END $$;
CREATE OR REPLACE FUNCTION openpc.evidence_kms_stored_outcome(pack bytea)
RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p jsonb; m jsonb;
BEGIN
 p:=convert_from(pack,'UTF8')::jsonb;
 m:=openpc.business_cbor(decode(p->'receipt'->>'payloadHex','hex'));
 RETURN m->>'23';
END $$;

GRANT INSERT,UPDATE ON control.evidence_kms_exchange TO openpc_control_runtime;
GRANT INSERT ON control.evidence_wrapped_key TO openpc_control_runtime;
CREATE OR REPLACE FUNCTION openpc.guard_evidence_kms_exchange() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE a control.evidence_kms_attempt; i control.evidence_kms_installation; request jsonb; pack jsonb;
 p jsonb; r jsonb; f jsonb; k jsonb; item text; now_ms numeric; original_key text; original_use text; fields text[];
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR current_setting('openpc.action_intent_id')<>'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id() THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.evidence_kms_attempt WHERE participant_id=NEW.participant_id
 AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id FOR UPDATE;
 SELECT * INTO STRICT i FROM control.evidence_kms_installation WHERE participant_id=a.participant_id
 AND privacy_domain_id=a.privacy_domain_id AND installation_digest=a.installation_digest;
 PERFORM openpc.evidence_export_producer_authority(i.producer_trust_digest);
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('evidence-kms-installation:'||NEW.participant_id::text||':'||
 NEW.privacy_domain_id::text||':'||i.installation_id::text,0));
 SELECT * INTO STRICT i FROM control.evidence_kms_installation WHERE participant_id=a.participant_id
 AND privacy_domain_id=a.privacy_domain_id AND installation_digest=a.installation_digest;
 request:=convert_from(NEW.request_bytes,'UTF8')::jsonb;
 IF NEW.request_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(request),'UTF8')
 OR request->>'operation' IS DISTINCT FROM NEW.kind OR request->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text
 OR request->>'challenge' IS DISTINCT FROM NEW.challenge
 OR request->'recipient' IS DISTINCT FROM jsonb_build_object('participantId',a.participant_id::text,
 'privacyDomainId',a.privacy_domain_id::text,'installationDigest',a.installation_digest,'producerTrustDigest',i.producer_trust_digest)
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE'; END IF;
 IF NEW.kind='PREPARE' THEN
  IF NEW.exchange_id<>NEW.attempt_id OR NEW.request_bytes<>a.request_bytes THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ORIGINAL'; END IF;
  original_key:='sha256:'||repeat('0',64); original_use:='NONE';
 ELSE
  fields:=ARRAY['operation','exchangeId','attemptId','recipient','originalRequestDigest','objectIntentDigest','keyId','keyUse','challenge'];
  IF NEW.kind='READ_ATTEMPT' THEN fields:=fields||ARRAY['readExchangeId','readRequestDigest']; END IF;
  IF jsonb_typeof(request) IS DISTINCT FROM 'object' OR request-fields IS DISTINCT FROM '{}'::jsonb OR NOT request ?& fields
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE-SHAPE'; END IF;
  IF request->>'exchangeId' IS DISTINCT FROM NEW.exchange_id::text
  OR request->>'originalRequestDigest' IS DISTINCT FROM a.request_digest
  OR request->>'objectIntentDigest' IS DISTINCT FROM a.object_intent_digest
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-ORIGINAL'; END IF;
  original_key:=request->>'keyId'; original_use:=request->>'keyUse';
  IF NEW.kind='READ_ATTEMPT' AND NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange target
   WHERE target.participant_id=a.participant_id AND target.privacy_domain_id=a.privacy_domain_id
   AND target.attempt_id=a.attempt_id AND target.exchange_id::text=request->>'readExchangeId'
   AND target.request_digest=request->>'readRequestDigest' AND target.kind IN ('PREPARE','UNWRAP'))
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-READBACK-TARGET'; END IF;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' OR NEW.receipt_bytes IS NOT NULL THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE'; END IF;
  IF NEW.kind='UNWRAP' THEN
   IF a.state<>'PROVED' OR original_use NOT IN ('ENCRYPT','DECRYPT') OR NOT EXISTS(SELECT 1 FROM control.evidence_wrapped_key
    WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND attempt_id=a.attempt_id AND key_id=original_key)
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-UNWRAP'; END IF;
   IF original_use='ENCRYPT' AND EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=a.participant_id
     AND e.privacy_domain_id=a.privacy_domain_id AND e.attempt_id=a.attempt_id AND e.kind='UNWRAP'
     AND convert_from(e.request_bytes,'UTF8')::jsonb->>'keyUse'='ENCRYPT')
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-NO-RESEAL'; END IF;
   IF EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=a.participant_id
    AND e.privacy_domain_id=a.privacy_domain_id AND e.attempt_id=a.attempt_id AND e.kind='UNWRAP'
    AND e.state IN ('PREPARED','DISPATCHED','UNKNOWN') AND NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange done
      WHERE done.participant_id=e.participant_id AND done.privacy_domain_id=e.privacy_domain_id AND done.attempt_id=e.attempt_id
      AND done.kind='READ_ATTEMPT' AND done.state='PROVED' AND openpc.evidence_kms_stored_outcome(done.receipt_bytes) IN ('1','2')
      AND convert_from(done.request_bytes,'UTF8')::jsonb->>'readExchangeId'=e.exchange_id::text
      AND convert_from(done.request_bytes,'UTF8')::jsonb->>'readRequestDigest'=e.request_digest))
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-UNKNOWN'; END IF;
  ELSIF original_use IS DISTINCT FROM 'NONE' THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-KEY-USE'; END IF;
  IF NEW.kind<>'READ_ATTEMPT' AND (i.state<>'ACTIVE' OR NOT i.pins->'permissions' ? CASE WHEN original_use='DECRYPT' THEN 'DECRYPT' ELSE 'ENCRYPT' END)
  THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
  RETURN NEW;
 END IF;
 IF to_jsonb(OLD)-ARRAY['state','receipt_bytes','receipt_digest','provider_sequence','recovery_floor'] IS DISTINCT FROM
 to_jsonb(NEW)-ARRAY['state','receipt_bytes','receipt_digest','provider_sequence','recovery_floor']
 THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NEW.state IN ('DISPATCHED','UNKNOWN') THEN
  IF NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED') OR (OLD.state IN ('DISPATCHED','UNKNOWN') AND NEW.state='UNKNOWN'))
  OR NEW.receipt_bytes IS NOT NULL OR NEW.provider_sequence IS NOT NULL OR NEW.recovery_floor IS NOT NULL
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE-TRANSITION'; END IF;
  IF NEW.state='DISPATCHED' AND NEW.kind<>'READ_ATTEMPT' AND (i.state<>'ACTIVE'
   OR NOT i.pins->'permissions' ? CASE WHEN original_use='DECRYPT' THEN 'DECRYPT' ELSE 'ENCRYPT' END
   OR floor(extract(epoch from clock_timestamp())*1000)<(i.pins->>'validFromMs')::numeric
   OR floor(extract(epoch from clock_timestamp())*1000)>=(i.pins->>'validUntilMs')::numeric)
   THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
  RETURN NEW;
 END IF;
 IF OLD.state NOT IN ('DISPATCHED','UNKNOWN') OR NEW.state<>'PROVED' THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-EXCHANGE-TRANSITION'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-kms-provider-key:'||jsonb_build_array(
  NEW.participant_id,NEW.privacy_domain_id,i.pins->>'providerId',i.pins->>'providerKeyId',i.pins->>'providerKeyVersion')::text,0));
 IF EXISTS(SELECT 1 FROM control.evidence_kms_exchange e
   JOIN control.evidence_kms_attempt prior USING(participant_id,privacy_domain_id,attempt_id)
   JOIN control.evidence_kms_installation prior_i USING(participant_id,privacy_domain_id,installation_digest)
   WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND prior_i.pins->>'providerId'=i.pins->>'providerId' AND prior_i.pins->>'providerKeyId'=i.pins->>'providerKeyId'
   AND prior_i.pins->>'providerKeyVersion'=i.pins->>'providerKeyVersion'
   AND (e.provider_sequence>NEW.provider_sequence OR e.recovery_floor>NEW.recovery_floor))
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECOVERY-FLOOR'; END IF;
 pack:=convert_from(NEW.receipt_bytes,'UTF8')::jsonb;
 IF jsonb_typeof(pack) IS DISTINCT FROM 'object' OR pack-ARRAY['profile','receipt','record','recovery'] IS DISTINCT FROM '{}'::jsonb
 OR NOT pack ?& ARRAY['profile','receipt','record','recovery']
 OR NEW.receipt_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(pack),'UTF8') THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PACK'; END IF;
 FOREACH item IN ARRAY ARRAY['profile','receipt','record','recovery'] LOOP
  IF jsonb_typeof(pack->item) IS DISTINCT FROM 'object' OR (pack->item)-ARRAY['payloadHex','coseHex'] IS DISTINCT FROM '{}'::jsonb
  OR NOT (pack->item) ?& ARRAY['payloadHex','coseHex']
  OR NOT coalesce(pack->item->>'payloadHex' ~ '^([0-9a-f]{2})*$',false)
  OR NOT coalesce(pack->item->>'coseHex' ~ '^([0-9a-f]{2})*$',false) THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PACK'; END IF;
 END LOOP;
 p:=openpc.evidence_kms_cose_binding(decode(pack->'profile'->>'payloadHex','hex'),decode(pack->'profile'->>'coseHex','hex'),
 'EvidenceKmsProfileV1','sha256:'||encode(sha256(decode(i.pins->>'profileIssuerSpkiHex','hex')),'hex'));
 IF 'sha256:'||encode(sha256(decode(pack->'profile'->>'coseHex','hex')),'hex') IS DISTINCT FROM i.pins->>'profileDigest'
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-PROFILE'; END IF;
 r:=openpc.evidence_kms_cose_binding(decode(pack->'receipt'->>'payloadHex','hex'),decode(pack->'receipt'->>'coseHex','hex'),
 'EvidenceKmsReceiptV1','sha256:'||encode(sha256(decode(i.pins->>'providerReceiptSpkiHex','hex')),'hex'));
 f:=openpc.evidence_kms_cose_binding(decode(pack->'recovery'->>'payloadHex','hex'),decode(pack->'recovery'->>'coseHex','hex'),
 'EvidenceKmsReceiptV1','sha256:'||encode(sha256(decode(i.pins->>'recoveryAuthoritySpkiHex','hex')),'hex'));
 FOREACH item IN ARRAY ARRAY['environmentId','participantId','privacyDomainId','providerId','reference','version','providerKeyId','providerKeyVersion','keyEpoch','wrapProfileDigest','policyDigest','recoveryProfileDigest'] LOOP
  IF r->>item IS DISTINCT FROM i.pins->>item OR f->>item IS DISTINCT FROM i.pins->>item OR p->>item IS DISTINCT FROM i.pins->>item
  THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-SCOPE'; END IF;
 END LOOP;
 IF r->>'operation' IS DISTINCT FROM (CASE NEW.kind WHEN 'PREPARE' THEN '1' WHEN 'READ_ATTEMPT' THEN '2' WHEN 'STATUS' THEN '3' WHEN 'UNWRAP' THEN '4' END)
 OR r->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text OR r->>'exchangeId' IS DISTINCT FROM NEW.exchange_id::text
 OR r->>'requestDigest' IS DISTINCT FROM NEW.request_digest OR r->>'challenge' IS DISTINCT FROM NEW.challenge
 OR r->>'objectIntentDigest' IS DISTINCT FROM a.object_intent_digest OR r->>'profileDigest' IS DISTINCT FROM i.pins->>'profileDigest'
 OR r->>'keyUse' IS DISTINCT FROM (CASE original_use WHEN 'NONE' THEN '1' WHEN 'ENCRYPT' THEN '2' WHEN 'DECRYPT' THEN '3' END)
 OR r->>'providerSequence' IS DISTINCT FROM NEW.provider_sequence::text OR r->>'recoveryFloor' IS DISTINCT FROM NEW.recovery_floor::text
 OR f->>'operation' IS DISTINCT FROM '5' OR f->>'keyUse' IS DISTINCT FROM '1' OR f->>'outcome' IS DISTINCT FROM '1'
 OR f-ARRAY['operation','keyUse','outcome','materialDigest','receiptId','signerKeyId','observedAtMs','validUntilMs'] IS DISTINCT FROM
 r-ARRAY['operation','keyUse','outcome','materialDigest','receiptId','signerKeyId','observedAtMs','validUntilMs']
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECEIPT'; END IF;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF (r->>'observedAtMs')::numeric>now_ms OR (r->>'observedAtMs')::numeric<now_ms-5000 OR (r->>'validUntilMs')::numeric<=now_ms
 OR (r->>'validUntilMs')::numeric-(r->>'observedAtMs')::numeric NOT BETWEEN 1 AND 5000
 OR (f->>'observedAtMs')::numeric>now_ms OR (f->>'observedAtMs')::numeric<now_ms-5000 OR (f->>'validUntilMs')::numeric<=now_ms
 OR (f->>'validUntilMs')::numeric-(f->>'observedAtMs')::numeric NOT BETWEEN 1 AND 5000
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-STALE'; END IF;
 IF original_key<>'sha256:'||repeat('0',64) AND r->>'keyId' IS DISTINCT FROM original_key THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-KEY'; END IF;
 IF NEW.kind='UNWRAP' AND r->>'outcome'='1' THEN
  IF i.state<>'ACTIVE' OR NOT i.pins->'permissions' ? original_use OR r->>'keyState' NOT IN ('1','2')
  OR (original_use='ENCRYPT' AND r->>'keyState'<>'1') OR now_ms<(i.pins->>'validFromMs')::numeric
  OR now_ms>=(i.pins->>'validUntilMs')::numeric OR r->>'materialDigest'='sha256:'||repeat('0',64)
  THEN RAISE EXCEPTION 'OPS_SECRET_REVOKED'; END IF;
 ELSIF r->>'materialDigest' IS DISTINCT FROM 'sha256:'||repeat('0',64) THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-MATERIAL'; END IF;
 IF pack->'record'->>'payloadHex'<>'' THEN
  k:=openpc.evidence_kms_cose_binding(decode(pack->'record'->>'payloadHex','hex'),decode(pack->'record'->>'coseHex','hex'),
   'EvidenceWrappedKeyRecordV1','sha256:'||encode(sha256(decode(i.pins->>'providerReceiptSpkiHex','hex')),'hex'));
  FOREACH item IN ARRAY ARRAY['environmentId','participantId','privacyDomainId','providerId','reference','version','providerKeyId','providerKeyVersion','keyEpoch','wrapProfileDigest','policyDigest','recoveryProfileDigest'] LOOP
   IF k->>item IS DISTINCT FROM i.pins->>item THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD-SCOPE'; END IF;
  END LOOP;
  IF k->>'attemptId' IS DISTINCT FROM a.attempt_id::text OR k->>'originalRequestDigest' IS DISTINCT FROM a.request_digest
   OR k->>'objectIntentDigest' IS DISTINCT FROM a.object_intent_digest OR k->>'profileDigest' IS DISTINCT FROM i.pins->>'profileDigest'
   OR r->>'keyId' IS DISTINCT FROM 'sha256:'||encode(sha256(decode(pack->'record'->>'payloadHex','hex')),'hex')
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD'; END IF;
 ELSE
  IF pack->'record'->>'coseHex'<>'' OR (NEW.kind IN ('PREPARE','READ_ATTEMPT','UNWRAP') AND r->>'outcome'='1')
   THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD'; END IF;
 END IF;
 RETURN NEW;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'PC-AUTH-0005';
END $$;
DROP TRIGGER IF EXISTS evidence_kms_exchange_guard ON control.evidence_kms_exchange;
CREATE TRIGGER evidence_kms_exchange_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_kms_exchange
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_kms_exchange();

CREATE OR REPLACE FUNCTION openpc.guard_evidence_wrapped_key() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-EVIDENCE-KMS-IMMUTABLE'; END IF;
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE') OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=NEW.participant_id
 AND e.privacy_domain_id=NEW.privacy_domain_id AND e.attempt_id=NEW.attempt_id AND e.state='PROVED' AND e.kind IN ('PREPARE','READ_ATTEMPT')
 AND openpc.evidence_kms_stored_outcome(e.receipt_bytes)='1'
 AND convert_from(e.receipt_bytes,'UTF8')::jsonb->'record' IS NOT DISTINCT FROM
 jsonb_build_object('payloadHex',encode(NEW.record_bytes,'hex'),'coseHex',encode(NEW.record_cose,'hex')))
 THEN RAISE EXCEPTION 'DATA-6021-EVIDENCE-KMS-RECORD-BINDING'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_wrapped_key_guard ON control.evidence_wrapped_key;
CREATE TRIGGER evidence_wrapped_key_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_wrapped_key
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_wrapped_key();
REVOKE ALL ON control.evidence_kms_attempt,control.evidence_wrapped_key,control.evidence_kms_exchange FROM openpc_control_owner;
-- PostgreSQL checks the exchange/wrapped-record foreign keys as the referenced
-- table owner with FOR KEY SHARE, requiring SELECT and an UPDATE column privilege.
-- FORCE RLS still denies direct owner reads/updates without a matching policy;
-- the attempt/wrapped-record guards also reject owner runtime mutations.
GRANT SELECT ON control.evidence_kms_attempt TO openpc_control_owner;
GRANT UPDATE(attempt_id) ON control.evidence_kms_attempt TO openpc_control_owner;
GRANT SELECT ON control.evidence_wrapped_key TO openpc_control_owner;
GRANT UPDATE(key_id) ON control.evidence_wrapped_key TO openpc_control_owner;


DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='control'
  AND table_name='evidence_segment' AND column_name='encrypted_segment') THEN
  ALTER TABLE control.evidence_segment NO FORCE ROW LEVEL SECURITY;
  EXECUTE 'INSERT INTO control.evidence_segment_payload(participant_id,privacy_domain_id,stream_id,segment_id,encrypted_segment)
   SELECT participant_id,privacy_domain_id,stream_id,segment_id,encrypted_segment FROM control.evidence_segment
   ON CONFLICT DO NOTHING';
  IF EXISTS(SELECT 1 FROM control.evidence_segment s LEFT JOIN control.evidence_segment_payload p
   USING(participant_id,privacy_domain_id,stream_id,segment_id)
   WHERE p.segment_id IS NULL OR s.encrypted_segment IS DISTINCT FROM p.encrypted_segment OR s.object_digest<>'sha256:'||encode(sha256(p.encrypted_segment),'hex')) THEN
   RAISE EXCEPTION 'PC-DATA-6004-PAYLOAD-MIGRATION';
  END IF;
  ALTER TABLE control.evidence_segment FORCE ROW LEVEL SECURITY;
 END IF;
END $$;
ALTER TABLE control.evidence_segment_payload FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_segment_payload FROM PUBLIC,openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT SELECT,INSERT ON control.evidence_segment_payload TO openpc_control_worker;
CREATE OR REPLACE FUNCTION openpc.guard_evidence_payload()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE segment control.evidence_segment%ROWTYPE; envelope jsonb; expected jsonb; head numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN
  PERFORM openpc.record_evidence_payload_deletion(OLD);
  RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT segment FROM control.evidence_segment s WHERE s.participant_id=NEW.participant_id
  AND s.privacy_domain_id=NEW.privacy_domain_id AND s.stream_id=NEW.stream_id AND s.segment_id=NEW.segment_id;
 SELECT last_sequence INTO STRICT head FROM control.evidence_stream WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id FOR UPDATE;
 IF segment.first_sequence<=head THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF segment.object_digest<>'sha256:'||encode(sha256(NEW.encrypted_segment),'hex') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 envelope:=convert_from(NEW.encrypted_segment,'UTF8')::jsonb;
 expected:=jsonb_build_object('version','OPENPC_EVIDENCE_SEGMENT_V1','participantId',segment.participant_id::text,
  'privacyDomainId',segment.privacy_domain_id::text,'streamId',segment.stream_id,'segmentId',segment.segment_id::text,
  'firstSequence',segment.first_sequence::text,'throughSequence',segment.through_sequence::text,'previousSegmentDigest',segment.previous_segment_digest,
  'keyId',segment.key_id,'retentionUntil',to_char(segment.retention_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 IF envelope->'header' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_payload_guard ON control.evidence_segment_payload;
CREATE TRIGGER evidence_payload_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_segment_payload
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_payload();

DROP TRIGGER IF EXISTS evidence_payload_mirror ON control.evidence_segment;
DROP FUNCTION IF EXISTS openpc.mirror_legacy_evidence_payload();
CREATE OR REPLACE FUNCTION openpc.require_evidence_payload()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.evidence_segment_payload p WHERE p.participant_id=NEW.participant_id
  AND p.privacy_domain_id=NEW.privacy_domain_id AND p.stream_id=NEW.stream_id AND p.segment_id=NEW.segment_id
  AND NEW.object_digest='sha256:'||encode(sha256(p.encrypted_segment),'hex')) THEN
  RAISE EXCEPTION 'PC-DATA-6004-EVIDENCE-PAYLOAD';
 END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS evidence_payload_required ON control.evidence_segment;
CREATE CONSTRAINT TRIGGER evidence_payload_required AFTER INSERT ON control.evidence_segment
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_evidence_payload();


ALTER TABLE control.evidence_deployment_lineage FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_deployment_lineage FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.evidence_deployment_lineage TO openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT INSERT ON control.evidence_deployment_lineage TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.evidence_deployment_lineage_projection(source control.evidence_catalogue)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE r record; claims jsonb; occurrence jsonb; invalidation jsonb; historical jsonb;
BEGIN
 IF (source).evidence_class<>'EFFECT' OR (source).source_format<>'PC-DEPLOYMENT-JOURNAL-PROJECTION-1'
  OR (source).record_id!~'^deployment:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:[1-9][0-9]{0,19}$' THEN RETURN NULL; END IF;
 SELECT d.signed_bytes,d.result_digest,d.sequence,a.* INTO r
  FROM control.deployment_result d JOIN control.deployment_address_reservation a
   ON a.participant_id=d.participant_id AND a.privacy_domain_id=d.privacy_domain_id AND a.command_id=d.command_id
  WHERE d.participant_id=(source).participant_id AND d.privacy_domain_id=(source).privacy_domain_id
   AND d.command_id=split_part((source).record_id,':',2)::uuid AND d.sequence=split_part((source).record_id,':',3)::numeric
   AND d.result_digest=(source).receipt_digest AND d.result_digest='sha256:'||encode(sha256(d.signed_bytes),'hex')
   AND a.state='HANDOFF';
 IF NOT FOUND THEN RETURN NULL; END IF;
 claims:=convert_from(r.signed_bytes,'UTF8')::jsonb;
 IF claims->>'purpose' IS DISTINCT FROM 'openpc:deployment-journal-projection:v1' THEN RETURN NULL; END IF;
 claims:=claims->'claims';
 IF claims->>'schema' IS DISTINCT FROM (source).source_format
  OR claims->>'sequence' IS DISTINCT FROM r.sequence::text
  OR (regexp_replace(claims->>'observedAt','([.][0-9]{6})[0-9]+',chr(92)||'1'))::timestamptz IS DISTINCT FROM (source).occurred_at
  OR claims->'owner'->>'participant_id' IS DISTINCT FROM (source).participant_id::text
  OR claims->'owner'->>'privacy_domain_id' IS DISTINCT FROM (source).privacy_domain_id::text
  OR claims->'status'->>'operationId' IS DISTINCT FROM 'urn:openpc:operation:'||r.command_id::text
  OR claims->'status'->>'attemptId' IS DISTINCT FROM r.attempt_id::text
  OR claims->>'targetRuntimeId' IS DISTINCT FROM replace(r.target_runtime_id,'urn:openpc:resource:','')
  OR claims->>'intentDigest' IS DISTINCT FROM substring(r.intent_digest from 8)
  OR claims->>'preparationDigest' IS DISTINCT FROM substring(r.prepared_record_digest from 8)
  OR claims->>'chainId' IS DISTINCT FROM r.chain_id
  OR claims->>'genesisDigest' IS DISTINCT FROM substring(r.genesis_digest from 8)
  OR claims->'status'->>'signedTransactionHash' IS DISTINCT FROM r.transaction_hash THEN RETURN NULL; END IF;
 occurrence:=claims->'outcome'->'occurrence'; invalidation:=claims->'outcome'->'invalidation';
 historical:=jsonb_build_object('sourceVersion',r.sequence::text,'receiptDigest',r.result_digest,
  'observedAt',claims->>'observedAt','state',claims->'status'->>'state','truthState',claims->'status'->>'truthState',
  'journalEvidenceDigest',claims->'status'->>'evidenceDigest',
  'finality',CASE WHEN invalidation<>'null'::jsonb THEN CASE WHEN invalidation->>'reason'='REORG' THEN 'REORG' ELSE 'INVALIDATED' END
    WHEN occurrence<>'null'::jsonb THEN 'FINALIZED' ELSE 'NOT_ESTABLISHED' END,
  'occurrence',CASE WHEN occurrence='null'::jsonb THEN 'null'::jsonb ELSE jsonb_build_object(
   'occurrenceId',occurrence->>'occurrenceId','occurrenceDigest','sha256:'||(occurrence->>'semanticDigest'),
   'blockHash','sha256:'||(occurrence->>'blockHash'),'blockNumber',occurrence->>'blockNumber','reorgStatus',occurrence->>'reorgStatus') END,
  'invalidation',CASE WHEN invalidation='null'::jsonb THEN 'null'::jsonb ELSE jsonb_build_object(
   'occurrenceId',invalidation->>'occurrenceId','occurrenceDigest','sha256:'||(invalidation->>'occurrenceDigest'),
   'observationDigest','sha256:'||(invalidation->>'observationDigest'),'reason',invalidation->>'reason') END);
 RETURN jsonb_build_object('chainId',r.chain_id,'genesisDigest',r.genesis_digest,'historical',historical);
EXCEPTION WHEN insufficient_privilege OR invalid_text_representation OR datetime_field_overflow THEN RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.evidence_deployment_lineage_projection(control.evidence_catalogue) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_deployment_lineage_projection(control.evidence_catalogue) TO openpc_control_worker,openpc_control_runtime,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.guard_evidence_deployment_lineage()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT openpc.evidence_deployment_lineage_projection(c) INTO expected FROM control.evidence_catalogue c
  WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id AND c.record_id=NEW.record_id;
 IF expected IS NULL OR NEW.projection IS DISTINCT FROM expected
  OR NEW.projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_deployment_lineage_guard ON control.evidence_deployment_lineage;
CREATE TRIGGER evidence_deployment_lineage_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_deployment_lineage
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_deployment_lineage();


ALTER TABLE control.evidence_deployment_provenance FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_deployment_provenance FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.evidence_deployment_provenance TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT INSERT ON control.evidence_deployment_provenance TO openpc_control_worker;
-- PostgreSQL requires UPDATE on at least one column for FOR SHARE. This
-- immutable key is sufficient for locking; the existing reservation guard
-- rejects key changes and no state/effect column is granted to the reader.
GRANT UPDATE(command_id) ON control.deployment_address_reservation TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.evidence_deployment_projection(source control.evidence_catalogue)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE lineage jsonb; r record;
BEGIN
 lineage:=openpc.evidence_deployment_lineage_projection(source);
 IF lineage IS NULL THEN RETURN NULL; END IF;
 SELECT a.*,i.deployment_intent_id,i.execution_principal_id,i.execution_workload_id INTO r
 FROM control.deployment_address_reservation a JOIN control.deployment_intent i
  ON i.participant_id=a.participant_id AND i.privacy_domain_id=a.privacy_domain_id
   AND i.preparation_digest=a.prepared_record_digest AND i.intent_digest=a.intent_digest
   AND 'urn:openpc:resource:'||i.runtime_target_id::text=a.target_runtime_id
 WHERE a.participant_id=(source).participant_id AND a.privacy_domain_id=(source).privacy_domain_id
  AND a.command_id=split_part((source).record_id,':',2)::uuid AND a.state='HANDOFF';
 IF NOT FOUND THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('integrity','VERIFIED_PURPOSE_SIGNATURE','authority','OBSERVATION_ONLY',
  'operationId','urn:openpc:operation:'||r.command_id::text,'attemptId',r.attempt_id::text,
  'deploymentIntentId','urn:openpc:resource:'||r.deployment_intent_id::text,'targetRuntimeId',r.target_runtime_id,
  'executionPrincipalId',r.execution_principal_id::text,'workloadId',r.execution_workload_id,
  'intentDigest',r.intent_digest,'preparationDigest',r.prepared_record_digest,
  'chainId',r.chain_id,'genesisDigest',r.genesis_digest,'transactionHash',r.transaction_hash,
  'historical',lineage->'historical');
END $$;
REVOKE ALL ON FUNCTION openpc.evidence_deployment_projection(control.evidence_catalogue) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_deployment_projection(control.evidence_catalogue)
 TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.guard_evidence_deployment_provenance()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE source control.evidence_catalogue; expected jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN
  SELECT * INTO STRICT source FROM control.evidence_catalogue WHERE participant_id=OLD.participant_id
   AND privacy_domain_id=OLD.privacy_domain_id AND stream_id=OLD.stream_id AND record_id=OLD.record_id;
  PERFORM openpc.record_projection_deletion(source,'NORMALIZED_JSON_PROJECTION',OLD.projection);RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF EXISTS(SELECT 1 FROM control.evidence_projection_retirement r WHERE r.participant_id=NEW.participant_id
  AND r.privacy_domain_id=NEW.privacy_domain_id AND r.stream_id=NEW.stream_id AND r.record_id=NEW.record_id
  AND r.data_class='NORMALIZED_JSON_PROJECTION') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT source FROM control.evidence_catalogue WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND record_id=NEW.record_id;
 expected:=openpc.evidence_deployment_projection(source);
 IF expected IS NULL OR NEW.projection IS DISTINCT FROM expected
  OR NEW.projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_deployment_provenance_guard ON control.evidence_deployment_provenance;
CREATE TRIGGER evidence_deployment_provenance_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_deployment_provenance
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_deployment_provenance();

-- The real result writer locks this same reservation FOR UPDATE before every
-- new observation, including reorg. Hold its shared row lock through deletion,
-- receipt/outbox and commit; historical age never supplies current closure.
CREATE OR REPLACE FUNCTION openpc.deployment_projection_retirement_blockers(source control.evidence_catalogue,p jsonb)
RETURNS text[] LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE reservation control.deployment_address_reservation; latest control.deployment_result;
 claims jsonb; occurrence jsonb; blockers text[]:=ARRAY[]::text[];
BEGIN
 IF current_setting('openpc.action_intent_id')='ACT-EVIDENCE_DELETIONS_CREATE_PROJECTION_BATCH-V1' THEN
  SELECT * INTO reservation FROM control.deployment_address_reservation r
  WHERE r.participant_id=(source).participant_id AND r.privacy_domain_id=(source).privacy_domain_id
   AND r.command_id=split_part((source).record_id,':',2)::uuid FOR SHARE;
 ELSE
  SELECT * INTO reservation FROM control.deployment_address_reservation r
  WHERE r.participant_id=(source).participant_id AND r.privacy_domain_id=(source).privacy_domain_id
   AND r.command_id=split_part((source).record_id,':',2)::uuid;
 END IF;
 IF NOT FOUND OR reservation.state<>'HANDOFF' THEN RETURN ARRAY['UNRESOLVED_OPERATION']; END IF;
 SELECT * INTO latest FROM control.deployment_result r WHERE r.participant_id=reservation.participant_id
  AND r.privacy_domain_id=reservation.privacy_domain_id AND r.command_id=reservation.command_id
 ORDER BY r.sequence DESC LIMIT 1;
 IF NOT FOUND THEN RETURN ARRAY['UNRESOLVED_OPERATION']; END IF;
 claims:=convert_from(latest.signed_bytes,'UTF8')::jsonb->'claims'; occurrence:=claims->'outcome'->'occurrence';
 IF claims->'outcome'->'invalidation' IS DISTINCT FROM 'null'::jsonb
  OR claims->'status'->>'state'='REORG' OR p->'historical'->>'finality' IN ('REORG','INVALIDATED')
 THEN blockers:=array_append(blockers,'REORG_FENCED'); END IF;
 IF claims->'status'->>'state' IS DISTINCT FROM 'CONFIRMED'
  OR claims->'status'->>'truthState' IS DISTINCT FROM 'SUCCESS'
  OR occurrence->>'finality' IS DISTINCT FROM 'FINALIZED'
  OR occurrence->>'reorgStatus' IS DISTINCT FROM 'CANONICAL'
  OR occurrence->>'receiptStatus' IS DISTINCT FROM '1'
  OR occurrence->>'creationGraphComplete' IS DISTINCT FROM 'true'
  OR occurrence->>'runtimeCodePresent' IS DISTINCT FROM 'true'
  OR occurrence->>'internalNativeTransfers' IS DISTINCT FROM '0'
  OR p->'historical'->>'state' IS DISTINCT FROM 'CONFIRMED'
  OR p->'historical'->>'truthState' IS DISTINCT FROM 'SUCCESS'
  OR p->'historical'->>'finality' IS DISTINCT FROM 'FINALIZED'
 THEN blockers:=array_append(blockers,'UNRESOLVED_OPERATION'); END IF;
 IF latest.sequence::text IS DISTINCT FROM p->'historical'->>'sourceVersion'
  OR latest.result_digest IS DISTINCT FROM (source).receipt_digest
  OR latest.result_digest IS DISTINCT FROM 'sha256:'||encode(sha256(latest.signed_bytes),'hex')
  OR p IS DISTINCT FROM openpc.evidence_deployment_projection(source)
  OR EXISTS(SELECT 1 FROM control.deployment_address_reservation successor
   WHERE successor.participant_id=reservation.participant_id AND successor.privacy_domain_id=reservation.privacy_domain_id
    AND successor.predecessor_command_id=reservation.command_id)
 THEN blockers:=array_append(blockers,'REFERENCES'); END IF;
 RETURN blockers;
END $$;
REVOKE ALL ON FUNCTION openpc.deployment_projection_retirement_blockers(control.evidence_catalogue,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.deployment_projection_retirement_blockers(control.evidence_catalogue,jsonb) TO openpc_control_runtime;


ALTER TABLE control.evidence_remote_archive_intent FORCE ROW LEVEL SECURITY;
ALTER TABLE control.evidence_remote_archive_attempt FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_remote_archive_intent,control.evidence_remote_archive_attempt FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.evidence_remote_archive_intent,control.evidence_remote_archive_attempt TO openpc_control_worker,openpc_control_runtime,openpc_control_reader;
GRANT INSERT ON control.evidence_remote_archive_intent TO openpc_control_worker;
GRANT INSERT,UPDATE ON control.evidence_remote_archive_attempt TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.remote_archive_rules(pid uuid,privacy uuid,stream text,segment uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('holdId',h.retention_hold_id::text,
  'selectorDigest',h.selector_digest,'creationOperationId',h.creation_operation_id::text,
  'releaseOperationId',h.release_operation_id::text,'state',h.state,'revision',h.revision::text)
  ORDER BY h.retention_hold_id),'[]'::jsonb)
 FROM control.retention_hold h WHERE h.participant_id=pid
  AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=privacy)
  AND openpc.evidence_hold_requires_coverage(h,stream,segment)
$$;
REVOKE ALL ON FUNCTION openpc.remote_archive_rules(uuid,uuid,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.remote_archive_rules(uuid,uuid,text,uuid) TO openpc_control_worker,openpc_control_runtime,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.remote_archive_rules(s control.evidence_segment)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT openpc.remote_archive_rules((s).participant_id,(s).privacy_domain_id,(s).stream_id,(s).segment_id)
$$;
REVOKE ALL ON FUNCTION openpc.remote_archive_rules(control.evidence_segment) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.remote_archive_rules(control.evidence_segment) TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.guard_remote_archive_intent()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.evidence_segment; payload bytea; object jsonb; expected jsonb; rules jsonb; p jsonb; admitted record; facts jsonb; payload_digest text; payload_size integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 p:=NEW.profile;
 admitted:=openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),NEW.stream_id);
 IF admitted.transport_digest IS DISTINCT FROM NEW.profile_digest OR admitted.transport IS DISTINCT FROM p
  OR admitted.sink_id IS DISTINCT FROM NEW.sink_id
  OR coalesce(admitted.claims->>'sourceKind','SEGMENT') IS DISTINCT FROM NEW.source_kind THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 expected:=jsonb_build_object('profileId',p->>'profileId','sinkId',NEW.sink_id,
  'endpoint',p->>'endpoint','transport',p->>'transport','region',p->>'region',
  'bucket',p->>'bucket','expectedBucketOwner',p->>'expectedBucketOwner','prefix',p->>'prefix',
  'lockMode','COMPLIANCE','requestTimeoutMs',p->'requestTimeoutMs','maxVersionPages',p->'maxVersionPages');
 IF p IS DISTINCT FROM expected
  OR NEW.profile_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
  OR coalesce(p->>'profileId','')!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
  OR NEW.sink_id!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
  OR coalesce(p->>'region','')!~'^[a-z0-9-]{1,63}$'
  OR coalesce(p->>'bucket','')!~'^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$'
  OR coalesce(p->>'prefix','')!~'^[a-zA-Z0-9_-]{1,64}$'
  OR coalesce(p->>'expectedBucketOwner','')!~'^[0-9]{12}$'
  OR jsonb_typeof(p->'requestTimeoutMs') IS DISTINCT FROM 'number'
  OR jsonb_typeof(p->'maxVersionPages') IS DISTINCT FROM 'number'
  OR coalesce(p->>'requestTimeoutMs','')!~'^[0-9]+$'
  OR coalesce(p->>'maxVersionPages','')!~'^[0-9]+$'
  OR (p->>'requestTimeoutMs')::numeric NOT BETWEEN 100 AND 30000
  OR (p->>'maxVersionPages')::numeric NOT BETWEEN 1 AND 32
  OR NOT coalesce((p->>'transport'='HTTPS' AND p->>'endpoint'~'^https://[^/@?#[:space:]]+/?$')
   OR (p->>'transport'='LOOPBACK_TEST' AND p->>'endpoint'~'^http://127[.]0[.]0[.]1(:[0-9]{1,5})?/?$'),false)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 IF NEW.source_kind='SEGMENT' THEN
 SELECT * INTO STRICT s FROM control.evidence_segment WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND segment_id=NEW.segment_id;
 SELECT encrypted_segment INTO STRICT payload FROM control.evidence_segment_payload
  WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id
   AND stream_id=s.stream_id AND segment_id=s.segment_id;
 rules:=openpc.remote_archive_rules(s);
 IF jsonb_array_length(rules)>1024 OR s.object_digest<>'sha256:'||encode(sha256(payload),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 object:=jsonb_build_object('sinkId',NEW.sink_id,'participantId',s.participant_id::text,
  'privacyDomainId',s.privacy_domain_id::text,'streamId',s.stream_id,'segmentId',s.segment_id::text,
  'firstSequence',s.first_sequence::text,'throughSequence',s.through_sequence::text,
  'previousSegmentDigest',s.previous_segment_digest,'objectDigest',s.object_digest,'keyId',s.key_id,
  'retentionUntil',to_char(s.retention_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  payload_digest:=s.object_digest; payload_size:=octet_length(payload);
 ELSIF NEW.source_kind='PROTECTED_PROOF' THEN
  facts:=openpc.protected_remote_archive_source(NEW.participant_id,NEW.privacy_domain_id,NEW.protected_object_id,NEW.sink_id);
  IF facts->>'state' IS DISTINCT FROM 'BOUND' OR facts->'packet'='null'::jsonb
   OR facts->'lineage'->>'streamId' IS DISTINCT FROM NEW.stream_id
   OR (facts->'object'->>'retainUntil')::timestamptz<=clock_timestamp()
   OR (facts->'object'->>'objectVersion')::numeric IS DISTINCT FROM NEW.protected_object_version
   OR facts->'object'->>'objectDigest' IS DISTINCT FROM NEW.protected_object_digest
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  object:=facts->'object'; rules:=facts->'rules';
  payload_digest:=object->>'payloadDigest'; payload_size:=(facts->>'payloadBytes')::integer;
 ELSE RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object('intentId',NEW.intent_id::text,'profileDigest',NEW.profile_digest,
  'source',jsonb_build_object('kind',NEW.source_kind,'object',object),'payloadDigest',payload_digest,
  'payloadBytes',payload_size,'initialProtection',jsonb_build_object('revision','1','rules',rules));
 IF NEW.intent IS DISTINCT FROM expected
  OR NEW.intent_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp(); RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_remote_archive_intent_guard ON control.evidence_remote_archive_intent;
CREATE TRIGGER evidence_remote_archive_intent_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_remote_archive_intent
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_remote_archive_intent();

CREATE OR REPLACE FUNCTION openpc.guard_remote_archive_attempt()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE i control.evidence_remote_archive_intent; s control.evidence_segment;
 expected jsonb; prior jsonb; rules jsonb; protection jsonb; locator jsonb; observation jsonb;
 object_key text; legal_hold text; deadline text; version_id text; admitted record; facts jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT i FROM control.evidence_remote_archive_intent WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND intent_id=NEW.intent_id;
 admitted:=openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),i.stream_id);
 IF admitted.transport_digest IS DISTINCT FROM i.profile_digest OR admitted.transport IS DISTINCT FROM i.profile
  OR admitted.sink_id IS DISTINCT FROM i.sink_id
  OR coalesce(admitted.claims->>'sourceKind','SEGMENT') IS DISTINCT FROM i.source_kind THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'STARTED' OR NEW.observation IS NOT NULL OR NEW.observation_digest IS NOT NULL
   OR EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt a WHERE a.participant_id=i.participant_id
    AND a.privacy_domain_id=i.privacy_domain_id AND a.intent_id=i.intent_id AND a.state IN ('STARTED','AMBIGUOUS'))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF i.source_kind='SEGMENT' THEN
  SELECT * INTO STRICT s FROM control.evidence_segment WHERE participant_id=i.participant_id
   AND privacy_domain_id=i.privacy_domain_id AND stream_id=i.stream_id AND segment_id=i.segment_id;
  rules:=openpc.remote_archive_rules(s);
  ELSE
   facts:=openpc.protected_remote_archive_source(i.participant_id,i.privacy_domain_id,i.protected_object_id,i.sink_id,i.intent_id);
   IF facts->>'state' IS DISTINCT FROM 'BOUND' OR facts->'object' IS DISTINCT FROM i.intent->'source'->'object'
    OR facts->'lineage'->>'streamId' IS DISTINCT FROM i.stream_id
    OR (NEW.action='PUT' AND (facts->'packet'='null'::jsonb OR (facts->'object'->>'retainUntil')::timestamptz<=clock_timestamp()))
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   rules:=facts->'rules';
  END IF;
  IF jsonb_array_length(rules)>1024 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT a.binding->'protection' INTO prior FROM control.evidence_remote_archive_attempt a
   WHERE a.participant_id=i.participant_id AND a.privacy_domain_id=i.privacy_domain_id AND a.intent_id=i.intent_id
   ORDER BY (a.binding->'protection'->>'revision')::numeric DESC,a.attempt_id DESC LIMIT 1;
  prior:=coalesce(prior,i.intent->'initialProtection');
  protection:=jsonb_build_object('revision',CASE WHEN rules=prior->'rules' THEN prior->>'revision'
   ELSE ((prior->>'revision')::numeric+1)::text END,'rules',rules);
  IF (protection->>'revision')::numeric NOT BETWEEN 1 AND 18446744073709551615
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF NEW.action='PUT' THEN
   locator:='null'::jsonb;
   IF protection IS DISTINCT FROM i.intent->'initialProtection'
    OR EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt a WHERE a.participant_id=i.participant_id
     AND a.privacy_domain_id=i.privacy_domain_id AND a.intent_id=i.intent_id)
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSIF NEW.action='PROTECTION' THEN
   SELECT a.observation->'locator' INTO locator FROM control.evidence_remote_archive_attempt a
    WHERE a.participant_id=i.participant_id AND a.privacy_domain_id=i.privacy_domain_id
     AND a.intent_id=i.intent_id AND a.action='PUT' AND a.state='OBSERVED';
   IF locator IS NULL OR locator='null'::jsonb THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSE RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  expected:=jsonb_build_object('attemptId',NEW.attempt_id::text,'intent',i.intent,'intentDigest',i.intent_digest,
   'action',NEW.action,'locator',locator,'protection',protection,
   'protectionDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(protection),'UTF8')),'hex'));
  IF NEW.binding IS DISTINCT FROM expected OR NEW.protection_digest IS DISTINCT FROM expected->>'protectionDigest'
   OR NEW.binding_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex')
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.started_at:=clock_timestamp();
 ELSE
  IF OLD.state='OBSERVED' OR OLD.state NOT IN ('STARTED','AMBIGUOUS')
   OR NEW.state NOT IN ('AMBIGUOUS','OBSERVED')
   OR (to_jsonb(NEW)-ARRAY['state','observation','observation_digest','updated_at'])
      IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','observation','observation_digest','updated_at'])
  THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 END IF;
 IF NEW.state='OBSERVED' THEN
  observation:=NEW.observation;
  version_id:=observation->'locator'->>'versionId';
  deadline:=observation->'observedRetention'->>'retainUntil';
  IF coalesce(length(version_id),0) NOT BETWEEN 1 AND 1024 OR version_id='null'
   OR version_id~'[[:cntrl:][:space:]]'
   OR coalesce(deadline,'')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?Z$'
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  IF i.source_kind='SEGMENT' THEN
  IF deadline::timestamptz < (i.intent->'source'->'object'->>'retentionUntil')::timestamptz
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  object_key:=(i.profile->>'prefix')||'/segment/'||encode(sha256(convert_to(openpc.signing_canonical_json(
   jsonb_build_object('sinkId',i.sink_id,'participantId',i.participant_id::text,
    'privacyDomainId',i.privacy_domain_id::text,'streamId',i.stream_id,'segmentId',i.segment_id::text)),'UTF8')),'hex');
  ELSE
   IF deadline::timestamptz IS DISTINCT FROM (i.intent->'source'->'object'->>'retainUntil')::timestamptz
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
   object_key:=(i.profile->>'prefix')||'/proof/'||encode(sha256(convert_to(openpc.signing_canonical_json(
    jsonb_build_object('sinkId',i.sink_id,'participantId',i.participant_id::text,
     'privacyDomainId',i.privacy_domain_id::text,'objectRef','urn:openpc:resource:'||i.protected_object_id::text,
     'objectVersion',i.protected_object_version::text)),'UTF8')),'hex');
  END IF;
  locator:=jsonb_build_object('sinkId',i.sink_id,'profileDigest',i.profile_digest,
   'bucket',i.profile->>'bucket','key',object_key,'versionId',version_id);
  SELECT CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.binding->'protection'->'rules') rule
   WHERE rule->>'state'='ACTIVE') THEN 'ON' ELSE 'OFF' END INTO legal_hold;
  expected:=jsonb_build_object('version','OPENPC_REMOTE_ARCHIVE_RECEIPT_V1',
   'intent',i.intent,'intentDigest',i.intent_digest,'locator',locator,
   'assurance','REMOTE_INTERFACE_VERIFIED','providerQualification','NOT_ESTABLISHED',
   'observedRetention',jsonb_build_object('mode','COMPLIANCE','retainUntil',deadline),
   'protection',NEW.binding->'protection','protectionDigest',NEW.protection_digest,
   'observedLegalHold',legal_hold);
  expected:=expected||jsonb_build_object('receiptDigest',
   'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex'));
  IF observation IS DISTINCT FROM expected
   OR NEW.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(observation),'UTF8')),'hex')
   OR (NEW.binding->'locator'<>'null'::jsonb AND observation->'locator' IS DISTINCT FROM NEW.binding->'locator')
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END IF;
 NEW.updated_at:=clock_timestamp(); RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_remote_archive_attempt_guard ON control.evidence_remote_archive_attempt;
CREATE TRIGGER evidence_remote_archive_attempt_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_remote_archive_attempt
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_remote_archive_attempt();


CREATE OR REPLACE FUNCTION openpc.evidence_hold_selector_encoding(selector jsonb,participant uuid,privacy uuid)
RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE kind text:=selector->>'type'; expected jsonb:=jsonb_build_object('type',kind);
 encoded jsonb:=jsonb_build_object('0','pc.evidence.hold-selector.v1','1',openpc.business_uuid(participant),
 '2',openpc.business_uuid(privacy),'3',kind); first_value numeric; last_value numeric; generation jsonb;
 resource_pattern text:='^urn:openpc:resource:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
 profile_pattern text:=replace(resource_pattern,':resource:',':fact-profile:');
BEGIN
 IF participant IS NULL OR privacy IS NULL OR jsonb_typeof(selector) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF kind='SEQUENCE_RANGE' THEN
  IF coalesce(selector->>'streamId','')!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
   OR coalesce(selector->>'fromSequence','')!~'^[1-9][0-9]{0,19}$' OR NOT(selector ? 'throughSequence') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  first_value:=(selector->>'fromSequence')::numeric;
  encoded:=encoded||jsonb_build_object('4',selector->>'streamId','5',first_value,'6',CASE WHEN selector->'throughSequence'='null'::jsonb THEN 0 ELSE 1 END);
  IF selector->'throughSequence'<>'null'::jsonb THEN
   IF coalesce(selector->>'throughSequence','')!~'^[1-9][0-9]{0,19}$' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   last_value:=(selector->>'throughSequence')::numeric; encoded:=encoded||jsonb_build_object('7',last_value);
  END IF;
  expected:=expected||jsonb_build_object('streamId',selector->>'streamId','fromSequence',first_value::text,'throughSequence',last_value::text);
 ELSIF kind='DIGEST' THEN
  IF coalesce(selector->>'recordDigest','')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('recordDigest',selector->>'recordDigest');
  encoded:=encoded||jsonb_build_object('4',openpc.business_bytes(decode(substring(selector->>'recordDigest' from 8),'hex')));
 ELSIF kind='PROJECTION' THEN
  IF coalesce(selector->>'projectionId','')!~resource_pattern THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('projectionId',selector->>'projectionId');
  encoded:=encoded||jsonb_build_object('4',openpc.business_uuid(right(selector->>'projectionId',36)::uuid));
 ELSIF kind='FACT_TYPE_KEY' THEN
  IF coalesce(selector->>'factType','') NOT IN ('CONTRACT_STATE_CALL','RELATIONSHIP','EXTERNAL_DECISION')
   OR coalesce(selector->>'factProfileId','')!~profile_pattern OR NOT(selector ? 'factKeyDigest')
   OR (selector->'factKeyDigest'<>'null'::jsonb AND coalesce(selector->>'factKeyDigest','')!~'^sha256:[0-9a-f]{64}$') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('factType',selector->>'factType','factProfileId',selector->>'factProfileId','factKeyDigest',selector->'factKeyDigest');
  encoded:=encoded||jsonb_build_object('4',selector->>'factType','5',selector->>'factProfileId','6',CASE WHEN selector->'factKeyDigest'='null'::jsonb THEN 0 ELSE 1 END);
  IF selector->'factKeyDigest'<>'null'::jsonb THEN encoded:=encoded||jsonb_build_object('7',openpc.business_bytes(decode(substring(selector->>'factKeyDigest' from 8),'hex'))); END IF;
 ELSIF kind='BLOCK_RANGE' THEN
  IF coalesce(selector->>'chainId','')!~'^(0|[1-9][0-9]{0,77})$' OR (selector->>'chainId')::numeric>=power(2::numeric,256)
   OR coalesce(selector->>'genesisDigest','')!~'^sha256:[0-9a-f]{64}$'
   OR coalesce(selector->>'fromBlock','')!~'^(0|[1-9][0-9]{0,19})$' OR NOT(selector ? 'throughBlock') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  first_value:=(selector->>'fromBlock')::numeric;
  encoded:=encoded||jsonb_build_object('4',selector->>'chainId','5',openpc.business_bytes(decode(substring(selector->>'genesisDigest' from 8),'hex')),
   '6',first_value,'7',CASE WHEN selector->'throughBlock'='null'::jsonb THEN 0 ELSE 1 END);
  IF selector->'throughBlock'<>'null'::jsonb THEN
   IF coalesce(selector->>'throughBlock','')!~'^(0|[1-9][0-9]{0,19})$' THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   last_value:=(selector->>'throughBlock')::numeric; encoded:=encoded||jsonb_build_object('8',last_value);
  END IF;
  expected:=expected||jsonb_build_object('chainId',selector->>'chainId','genesisDigest',selector->>'genesisDigest','fromBlock',first_value::text,'throughBlock',last_value::text);
 ELSIF kind='GENERATION' THEN
  generation:=selector->'generation';
  IF generation->>'kind'='RUNTIME_CONFIGURATION' THEN
   IF coalesce(generation->>'generationId','')!~resource_pattern OR generation IS DISTINCT FROM jsonb_build_object('kind','RUNTIME_CONFIGURATION','generationId',generation->>'generationId') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   encoded:=encoded||jsonb_build_object('4','RUNTIME_CONFIGURATION','5',openpc.business_uuid(right(generation->>'generationId',36)::uuid));
  ELSIF generation->>'kind'='CANONICAL_FACT' THEN
   IF coalesce(generation->>'factProfileId','')!~profile_pattern OR coalesce(generation->>'canonicalGeneration','')!~'^[1-9][0-9]{0,19}$'
    OR (generation->>'canonicalGeneration')::numeric>18446744073709551615
    OR generation IS DISTINCT FROM jsonb_build_object('kind','CANONICAL_FACT','factProfileId',generation->>'factProfileId','canonicalGeneration',generation->>'canonicalGeneration') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
   encoded:=encoded||jsonb_build_object('4','CANONICAL_FACT','5',generation->>'factProfileId','6',(generation->>'canonicalGeneration')::numeric);
  ELSE RAISE EXCEPTION 'PC-DATA-6004'; END IF;
  expected:=expected||jsonb_build_object('generation',generation);
 ELSIF kind NOT IN ('PARTICIPANT','PRIVACY_DOMAIN') OR kind IS NULL THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF first_value>18446744073709551615 OR last_value>18446744073709551615 OR last_value<first_value
  OR selector IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 RETURN encoded;
END $$;
REVOKE ALL ON FUNCTION openpc.evidence_hold_selector_encoding(jsonb,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_hold_selector_encoding(jsonb,uuid,uuid) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

-- The descriptor is assembled by the owning source adapter, never accepted from
-- the public hold/deletion request. Missing knowledge remains NULL per dimension.
CREATE OR REPLACE FUNCTION openpc.evidence_hold_source_match(selector jsonb,metadata jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE entries jsonb; dimension text; entry jsonb; check_selector jsonb; matched boolean;
BEGIN
 IF metadata ? 'unresolvedReferences' AND jsonb_typeof(metadata->'unresolvedReferences') IS DISTINCT FROM 'boolean' THEN RETURN NULL; END IF;
 dimension:=CASE selector->>'type' WHEN 'PROJECTION' THEN 'projections' WHEN 'FACT_TYPE_KEY' THEN 'facts'
  WHEN 'BLOCK_RANGE' THEN 'blocks' WHEN 'GENERATION' THEN 'generations' END;
 -- Generation namespaces have independent completeness. A known runtime UUID
 -- never proves that a record references no canonical Fact generation.
 entries:=CASE WHEN dimension='generations' THEN metadata->dimension->(selector->'generation'->>'kind') ELSE metadata->dimension END;
 IF dimension IS NULL OR jsonb_typeof(entries) IS DISTINCT FROM 'array' THEN RETURN NULL; END IF;
 -- Validate every source item before proving absence. A malformed sibling must
 -- not silently become a non-match, even when another item is well formed.
 FOR entry IN SELECT value FROM jsonb_array_elements(entries) LOOP
  IF dimension='projections' THEN
   check_selector:=jsonb_build_object('type','PROJECTION','projectionId',entry);
  ELSIF dimension='facts' THEN
   IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR entry->'factKeyDigest' IS NOT DISTINCT FROM 'null'::jsonb THEN RETURN NULL; END IF;
   check_selector:=entry||jsonb_build_object('type','FACT_TYPE_KEY');
  ELSIF dimension='blocks' THEN
   IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR entry-ARRAY['chainId','genesisDigest','blockNumber']<>'{}'::jsonb THEN RETURN NULL; END IF;
   check_selector:=jsonb_build_object('type','BLOCK_RANGE','chainId',entry->'chainId','genesisDigest',entry->'genesisDigest',
    'fromBlock',entry->'blockNumber','throughBlock',entry->'blockNumber');
  ELSE
   IF entry->>'kind' IS DISTINCT FROM selector->'generation'->>'kind' THEN RETURN NULL; END IF;
   check_selector:=jsonb_build_object('type','GENERATION','generation',entry);
  END IF;
  BEGIN
   PERFORM openpc.evidence_hold_selector_encoding(check_selector,'00000000-0000-0000-0000-000000000000'::uuid,'00000000-0000-0000-0000-000000000000'::uuid);
  EXCEPTION WHEN raise_exception OR invalid_text_representation OR numeric_value_out_of_range THEN RETURN NULL;
  END;
 END LOOP;
 SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(entries) e WHERE
  (dimension='projections' AND e=selector->'projectionId')
  OR (dimension='facts' AND e->>'factType'=selector->>'factType' AND e->>'factProfileId'=selector->>'factProfileId'
   AND (selector->'factKeyDigest'='null'::jsonb OR e->>'factKeyDigest'=selector->>'factKeyDigest'))
  OR (dimension='blocks' AND e->>'chainId'=selector->>'chainId' AND e->>'genesisDigest'=selector->>'genesisDigest'
   AND (e->>'blockNumber')::numeric>=(selector->>'fromBlock')::numeric
   AND (selector->'throughBlock'='null'::jsonb OR (e->>'blockNumber')::numeric<=(selector->>'throughBlock')::numeric))
  OR (dimension='generations' AND e=selector->'generation')) INTO matched;
 -- A verified positive remains a preservation duty. Missing reference closure
 -- prevents a negative result from being used as permission to delete.
 IF NOT matched AND metadata->'unresolvedReferences'='true'::jsonb THEN RETURN NULL; END IF;
 RETURN matched;
END $$;
REVOKE ALL ON FUNCTION openpc.evidence_hold_source_match(jsonb,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_hold_source_match(jsonb,jsonb) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;


CREATE OR REPLACE FUNCTION openpc.retention_policy_receipt_hold_metadata(source control.evidence_catalogue)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF (source).evidence_class<>'BUSINESS_TRANSITION' THEN RETURN NULL; END IF;
  -- A retention policy governs a class and references only its own policy,
  -- approval and operation identities. It does not name a Fact, projection,
  -- block or runtime generation. This statement is specific to these two
  -- admitted profiles; other business families retain UNKNOWN lineage.
  IF EXISTS(SELECT 1 FROM control.evidence_record e
   JOIN control.audit_occurrence a ON a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id
    AND a.receipt_id=e.receipt_id AND a.receipt_digest=e.receipt_digest
   JOIN control.idempotency_record i ON i.participant_id=a.participant_id AND i.privacy_domain_id=a.privacy_domain_id
    AND i.idempotency_record_id=a.idempotency_record_id AND i.operation_id=a.operation_id
   JOIN control.retention_policy p ON p.participant_id=a.participant_id AND p.privacy_domain_id=a.privacy_domain_id
    AND p.retention_policy_id=a.aggregate_id
   WHERE e.participant_id=(source).participant_id AND e.privacy_domain_id=(source).privacy_domain_id
    AND e.evidence_record_id::text=(source).record_id AND e.evidence_role='BUSINESS_TRANSITION_RECEIPT'
    AND e.custody='CONTROL_STORE' AND e.evidence_format=(source).source_format
    AND (source).receipt_digest='sha256:'||encode(sha256(a.cose_sign1),'hex')
    AND a.receipt_digest=sha256(a.receipt_cbor)
    AND floor(a.recorded_at_ns/1000)=extract(epoch FROM (source).occurred_at)*1000000
    AND a.aggregate_type='retention-policy' AND a.profile_version=1
    AND ((a.profile_id='pc.control.retention-policy.activate' AND a.catalog_operation_id='CFG-OP-ACTIVATE-RETENTION-POLICY'
      AND a.action_intent_id='ACT-RETENTION_POLICIES_CREATE_RESOURCE-V1' AND a.operation_id=p.activation_operation_id)
     OR (a.profile_id='pc.control.retention-policy.retire' AND a.catalog_operation_id='CFG-OP-RETIRE-RETENTION-POLICY'
      AND a.action_intent_id='ACT-RETENTION_POLICIES_RETIRE_RESOURCE-V1' AND a.operation_id=p.retirement_operation_id))
    AND i.terminal_state='COMMITTED' AND i.input_digest=a.candidate_digest
    AND i.action_intent_id=a.action_intent_id AND i.catalog_operation_id=a.catalog_operation_id
    AND sha256(a.before_state_preimage)=a.before_state_digest AND sha256(a.after_state_preimage)=a.after_state_digest
    AND sha256(a.authority_snapshot)=a.pre_commit_authority_digest) THEN
   RETURN jsonb_build_object('projections','[]'::jsonb,'facts','[]'::jsonb,'blocks','[]'::jsonb,
    'generations',jsonb_build_object('RUNTIME_CONFIGURATION','[]'::jsonb,'CANONICAL_FACT','[]'::jsonb));
  END IF;
 RETURN NULL;
EXCEPTION WHEN insufficient_privilege OR no_data_found OR too_many_rows THEN RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.retention_policy_receipt_hold_metadata(control.evidence_catalogue) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.retention_policy_receipt_hold_metadata(control.evidence_catalogue) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.evidence_hold_record_metadata(source control.evidence_catalogue)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE metadata jsonb; binding record; occurrence jsonb; invalidation jsonb;
BEGIN
 IF (source).source_format='OPENPC_AUTHENTICATION_OCCURRENCE_V1' THEN
  IF EXISTS(SELECT 1 FROM control.authentication_occurrence a WHERE a.participant_id=(source).participant_id
   AND a.privacy_domain_id=(source).privacy_domain_id AND a.occurrence_id::text=(source).record_id
   AND (source).receipt_digest='sha256:'||encode(a.receipt_digest,'hex') AND a.receipt_digest=sha256(a.receipt)
   AND a.occurred_at=(source).occurred_at) THEN
   RETURN jsonb_build_object('projections','[]'::jsonb,'facts','[]'::jsonb,'blocks','[]'::jsonb,'generations',jsonb_build_object('RUNTIME_CONFIGURATION','[]'::jsonb,'CANONICAL_FACT','[]'::jsonb));
  END IF;
 ELSIF (source).evidence_class='BUSINESS_TRANSITION' THEN
  RETURN openpc.retention_policy_receipt_hold_metadata(source);
 ELSIF (source).source_format='OPENPC_CANONICAL_FACT_V1' THEN
  RETURN openpc.evidence_fact_hold_metadata(source);
 ELSIF (source).source_format IN ('OPENPC_CANDIDATE_PROJECTION_CHUNK_V1','OPENPC_CANDIDATE_PROJECTION_MANIFEST_V1') THEN
  RETURN openpc.candidate_archive_hold_metadata(source);
 ELSIF (source).source_format IN ('OPENPC_RUNTIME_ARTIFACT_CHUNK_V1','OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1') THEN
  RETURN openpc.runtime_artifact_archive_hold_metadata(source);
 ELSIF (source).source_format='PC-DEPLOYMENT-JOURNAL-PROJECTION-1' THEN
  SELECT p.projection INTO metadata FROM control.evidence_deployment_lineage p
   WHERE p.participant_id=(source).participant_id AND p.privacy_domain_id=(source).privacy_domain_id
    AND p.stream_id=(source).stream_id AND p.record_id=(source).record_id
    AND (source).evidence_class='EFFECT'
    AND p.projection=openpc.evidence_deployment_lineage_projection(source)
    AND p.projection->'historical'->>'receiptDigest'=(source).receipt_digest
    AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex');
  IF NOT FOUND THEN RETURN NULL; END IF;
  occurrence:=metadata->'historical'->'occurrence';
  invalidation:=metadata->'historical'->'invalidation';
  IF invalidation<>'null'::jsonb THEN
   -- A reorg invalidates authority, not the preservation duty for its original
   -- block. Require one exact, previously verified occurrence reference.
   SELECT p.projection->'historical'->'occurrence' INTO STRICT occurrence
    FROM control.evidence_deployment_lineage p
    WHERE p.participant_id=(source).participant_id AND p.privacy_domain_id=(source).privacy_domain_id
     AND p.stream_id=(source).stream_id AND split_part(p.record_id,':',2)=split_part((source).record_id,':',2)
     AND (p.projection->'historical'->>'sourceVersion')::numeric<(metadata->'historical'->>'sourceVersion')::numeric
     AND p.projection->>'chainId'=metadata->>'chainId' AND p.projection->>'genesisDigest'=metadata->>'genesisDigest'
     AND p.projection->'historical'->'occurrence'->>'occurrenceId'=invalidation->>'occurrenceId'
     AND p.projection->'historical'->'occurrence'->>'occurrenceDigest'=invalidation->>'occurrenceDigest'
     AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex')
    GROUP BY p.projection->'historical'->'occurrence';
   IF NOT FOUND THEN RETURN NULL; END IF;
  END IF;
  IF occurrence IS NULL OR occurrence='null'::jsonb THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('blocks',jsonb_build_array(jsonb_build_object('chainId',metadata->>'chainId',
   'genesisDigest',metadata->>'genesisDigest','blockNumber',occurrence->>'blockNumber')));
 ELSIF (source).source_format='OPENPC_RPC_DECISION_TRANSITION_V1' THEN
  SELECT r.preservation_metadata INTO metadata FROM control.evidence_projection_retirement r
   JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
   WHERE r.participant_id=(source).participant_id AND r.privacy_domain_id=(source).privacy_domain_id
    AND r.evidence_id=(source).evidence_id AND r.stream_id=(source).stream_id AND r.record_id=(source).record_id
    AND r.data_class='NORMALIZED_JSON_PROJECTION' AND r.source_receipt_digest=(source).receipt_digest
    AND r.retirement_digest=openpc.projection_retirement_digest(r) AND j.state='SUCCEEDED';
  IF FOUND THEN RETURN metadata; END IF;
  SELECT p.projection,g.projection_plan_id,g.runtime_configuration_generation_id INTO binding
   FROM control.evidence_rpc_provenance p JOIN control.runtime_configuration_generation g
    ON g.participant_id=p.participant_id AND g.privacy_domain_id=p.privacy_domain_id
     AND g.runtime_configuration_generation_id::text=p.projection->'activation'->>'generationId'
     AND g.generation_digest=p.projection->'activation'->>'generationDigest'
   WHERE p.participant_id=(source).participant_id AND p.privacy_domain_id=(source).privacy_domain_id
    AND p.stream_id=(source).stream_id AND p.record_id=(source).record_id
    AND (source).evidence_class='EFFECT' AND p.projection->>'sourceDigest'=(source).receipt_digest
    AND p.projection->>'sourceSequence'=(source).sequence::text
    AND extract(epoch FROM (source).occurred_at)*1000000=floor((p.projection->>'occurredAtNs')::numeric/1000)
    AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex');
  IF FOUND THEN
   RETURN jsonb_build_object('projections',jsonb_build_array('urn:openpc:resource:'||binding.projection_plan_id::text),
    'generations',jsonb_build_object('RUNTIME_CONFIGURATION',jsonb_build_array(jsonb_build_object('kind','RUNTIME_CONFIGURATION',
      'generationId','urn:openpc:resource:'||binding.runtime_configuration_generation_id::text))));
  END IF;
 END IF;
 RETURN NULL;
EXCEPTION WHEN insufficient_privilege OR no_data_found OR too_many_rows THEN RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.evidence_hold_record_metadata(control.evidence_catalogue) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_hold_record_metadata(control.evidence_catalogue) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.evidence_hold_match_state(selector jsonb,participant uuid,privacy uuid,stream text,segment uuid)
RETURNS text LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT CASE WHEN bool_or(matched) THEN 'MATCH' WHEN count(*)=0 OR bool_or(matched IS NULL) THEN 'UNKNOWN' ELSE 'NON_MATCH' END
 FROM (SELECT CASE selector->>'type'
  WHEN 'PARTICIPANT' THEN true WHEN 'PRIVACY_DOMAIN' THEN true
  WHEN 'SEQUENCE_RANGE' THEN selector->>'streamId'=c.stream_id AND c.sequence>=(selector->>'fromSequence')::numeric
   AND (selector->'throughSequence'='null'::jsonb OR c.sequence<=(selector->>'throughSequence')::numeric)
  WHEN 'DIGEST' THEN selector->>'recordDigest'=c.receipt_digest
  ELSE openpc.evidence_hold_source_match(selector,openpc.evidence_hold_record_metadata(c)) END matched
  FROM control.evidence_catalogue c WHERE c.participant_id=participant AND c.privacy_domain_id=privacy
   AND c.stream_id=stream AND c.segment_id=segment
  UNION ALL SELECT CASE selector->>'type'
   WHEN 'PARTICIPANT' THEN true WHEN 'PRIVACY_DOMAIN' THEN true
   WHEN 'SEQUENCE_RANGE' THEN selector->>'streamId'=r.stream_id AND r.sequence>=(selector->>'fromSequence')::numeric
    AND (selector->'throughSequence'='null'::jsonb OR r.sequence<=(selector->>'throughSequence')::numeric)
   WHEN 'DIGEST' THEN selector->>'recordDigest'=r.source_receipt_digest
   ELSE openpc.evidence_hold_source_match(selector,r.preservation_metadata) END
  FROM control.evidence_projection_retirement r JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
   WHERE r.participant_id=participant AND r.privacy_domain_id=privacy AND r.stream_id=stream AND r.segment_id=segment
    AND r.data_class='SEARCH_PROJECTION' AND j.state='SUCCEEDED'
    AND r.retirement_digest=openpc.projection_retirement_digest(r)) matches
$$;
REVOKE ALL ON FUNCTION openpc.evidence_hold_match_state(jsonb,uuid,uuid,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_hold_match_state(jsonb,uuid,uuid,text,uuid) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;


