CREATE POLICY archive_nonce_verifier ON control.evidence_archive_commit_nonce TO openpc_control_owner,openpc_control_key_governor USING(true) WITH CHECK(true);
ALTER TABLE control.evidence_archive_commit_nonce ALTER CONSTRAINT evidence_archive_commit_nonce_receipt_fk DEFERRABLE INITIALLY DEFERRED;
GRANT USAGE ON SCHEMA openpc,control,public TO openpc_control_key_governor;

/** The worker login cannot read the verifier secret or write the nonce table.
 * The MAC binds the actual signed bytes. A deferred FK and receipt completion
 * check prevent consuming it without committing the exact receipt and outbox. */
CREATE OR REPLACE FUNCTION openpc.consume_archive_commit(p control.evidence_archive_profile,a control.evidence_remote_archive_attempt,v control.evidence_archive_receipt)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE secret bytea; expected bytea; different integer:=0;
BEGIN
 IF session_user IS DISTINCT FROM p.claims->>'databaseRole'
  OR v.participant_id<>p.participant_id OR v.privacy_domain_id<>p.privacy_domain_id
  OR a.participant_id<>v.participant_id OR a.privacy_domain_id<>v.privacy_domain_id
  OR a.attempt_id<>v.attempt_id OR v.profile_digest<>p.profile_digest
  OR v.receipt_digest<>'sha256:'||encode(sha256(v.cose),'hex')
  OR octet_length(v.commit_nonce)<>32 OR octet_length(v.commit_mac)<>32
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.evidence_archive_commit_key
  WHERE participant_id=p.participant_id AND privacy_domain_id=p.privacy_domain_id
   AND environment_id=p.environment_id AND sink_id=p.sink_id;
 expected:=public.hmac(convert_to('OPENPC_REMOTE_ARCHIVE_CUSTODY_COMMIT_V1','UTF8')
  ||uuid_send(v.participant_id)||uuid_send(v.privacy_domain_id)||sha256(v.cose)||sha256(v.payload)
  ||decode(substring(p.profile_digest from 8),'hex')||decode(substring(a.binding_digest from 8),'hex')||v.commit_nonce,secret,'sha256');
 FOR n IN 0..31 LOOP different:=different | (get_byte(expected,n) # get_byte(v.commit_mac,n)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 INSERT INTO control.evidence_archive_commit_nonce(participant_id,privacy_domain_id,nonce,receipt_id,receipt_digest)
  VALUES(v.participant_id,v.privacy_domain_id,v.commit_nonce,v.receipt_id,v.receipt_digest);
END $$;
ALTER FUNCTION openpc.consume_archive_commit(control.evidence_archive_profile,control.evidence_remote_archive_attempt,control.evidence_archive_receipt) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.consume_archive_commit(control.evidence_archive_profile,control.evidence_remote_archive_attempt,control.evidence_archive_receipt) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.consume_archive_commit(control.evidence_archive_profile,control.evidence_remote_archive_attempt,control.evidence_archive_receipt) TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.guard_archive_receipt()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p control.evidence_archive_profile; a control.evidence_remote_archive_attempt; i control.evidence_remote_archive_intent;
 s control.evidence_segment; previous control.evidence_archive_receipt; actual jsonb; expected jsonb; recorded numeric; signer text; facts jsonb; object jsonb; protected_source boolean;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT a FROM control.evidence_remote_archive_attempt WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.attempt_id AND intent_id=NEW.intent_id AND state='OBSERVED';
 SELECT * INTO STRICT i FROM control.evidence_remote_archive_intent WHERE participant_id=a.participant_id
  AND privacy_domain_id=a.privacy_domain_id AND intent_id=a.intent_id;
 p:=openpc.require_archive_profile(NEW.profile_digest,i.stream_id);
 protected_source:=i.source_kind='PROTECTED_PROOF';
 IF coalesce(p.claims->>'sourceKind','SEGMENT') IS DISTINCT FROM i.source_kind THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF protected_source THEN
  facts:=openpc.protected_remote_archive_source(i.participant_id,i.privacy_domain_id,i.protected_object_id,i.sink_id,i.intent_id);
  IF facts->>'state' IS DISTINCT FROM 'BOUND' OR facts->'object' IS DISTINCT FROM i.intent->'source'->'object'
   OR facts->'lineage'->>'streamId' IS DISTINCT FROM i.stream_id
   OR (a.observation->'observedRetention'->>'retainUntil')::timestamptz IS DISTINCT FROM (facts->'object'->>'retainUntil')::timestamptz
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  object:=facts->'object';
 ELSE
  SELECT * INTO STRICT s FROM control.evidence_segment WHERE participant_id=i.participant_id
   AND privacy_domain_id=i.privacy_domain_id AND stream_id=i.stream_id AND segment_id=i.segment_id;
 END IF;
 recorded:=floor(extract(epoch FROM NEW.recorded_at)*1000000);
 signer:='sha256:'||encode(sha256(decode(p.claims->>'receiptSignerSpki','hex')),'hex');
 IF i.profile_digest<>p.transport_digest OR i.profile IS DISTINCT FROM p.transport OR i.sink_id<>p.sink_id
  OR p.participant_id<>NEW.participant_id OR p.privacy_domain_id<>NEW.privacy_domain_id
  OR recorded<(p.claims->>'validFromMs')::numeric*1000 OR recorded>=(p.claims->>'validUntilMs')::numeric*1000
  OR NEW.recorded_at<a.updated_at
  OR NEW.recorded_at>clock_timestamp() OR NEW.recorded_at<clock_timestamp()-interval '30 seconds'
  OR NEW.receipt_id::text!~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO previous FROM control.evidence_archive_receipt prior WHERE prior.participant_id=i.participant_id
  AND prior.privacy_domain_id=i.privacy_domain_id AND prior.intent_id=i.intent_id
  ORDER BY (openpc.business_cbor(prior.payload)->>'13')::numeric DESC LIMIT 1;
 IF (a.action='PUT' AND (previous.receipt_id IS NOT NULL OR NEW.previous_receipt_digest IS NOT NULL))
  OR (a.action='PROTECTION' AND (previous.receipt_id IS NULL OR NEW.previous_receipt_digest IS DISTINCT FROM previous.receipt_digest
   OR (openpc.business_cbor(previous.payload)->>'13')::numeric>=(a.binding->'protection'->>'revision')::numeric))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 actual:=openpc.business_cbor(NEW.payload);
 expected:=jsonb_build_object('0',openpc.business_bytes(decode(CASE WHEN protected_source THEN 'd935f1479b41f87578a183d4cd7024371faae089e338f2abf1aa2c39a4b4445b' ELSE '6f1409ec49a98e1416adccd37517e0ed9b402b0e673f398cef40878bb8ea65fc' END,'hex')),
  '1',p.environment_id,'2',openpc.business_uuid(i.participant_id),'3',openpc.business_uuid(i.privacy_domain_id),
  '4',openpc.business_uuid(NEW.receipt_id),'5',openpc.business_uuid(i.intent_id),'6',openpc.business_uuid(a.attempt_id),
  '7',openpc.business_bytes(decode(substring(p.profile_digest from 8),'hex')),
  '8',openpc.business_bytes(decode(substring(a.observation_digest from 8),'hex')),
  '9',openpc.business_bytes(decode(substring(a.binding_digest from 8),'hex')),
  '10',openpc.business_bytes(decode(substring(CASE WHEN protected_source THEN object->>'objectDigest' ELSE s.object_digest END from 8),'hex')),
  '11',openpc.business_bytes(sha256(convert_to(openpc.signing_canonical_json(a.observation->'locator'),'UTF8'))),
  '12',openpc.business_bytes(decode(substring(a.protection_digest from 8),'hex')),
  '13',(a.binding->'protection'->>'revision')::numeric,
  '14',floor(extract(epoch FROM (a.observation->'observedRetention'->>'retainUntil')::timestamptz)*1000000),
  '15',recorded,'16',openpc.business_bytes(coalesce(decode(substring(NEW.previous_receipt_digest from 8),'hex'),''::bytea)),
  '17',CASE a.action WHEN 'PUT' THEN 1 ELSE 2 END,'18',openpc.business_bytes(decode(substring(signer from 8),'hex')),
  '19',i.stream_id,'22',1,'23',0);
 IF protected_source THEN
  expected:=expected||jsonb_build_object('20',openpc.business_uuid(i.protected_object_id),'21',i.protected_object_version,
   '24',openpc.business_bytes(decode(substring(object->>'payloadDigest' from 8),'hex')),
   '25',openpc.business_bytes(sha256(convert_to(openpc.signing_canonical_json(object->'source'),'UTF8'))),
   '26',floor(extract(epoch FROM (object->>'retainUntil')::timestamptz)*1000000));
 ELSE expected:=expected||jsonb_build_object('20',openpc.business_uuid(i.segment_id),'21',s.through_sequence); END IF;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.archive_cose_binding(NEW.payload,NEW.cose,signer,CASE WHEN protected_source THEN 24005 ELSE 24003 END,CASE WHEN protected_source THEN 342 ELSE 340 END);
 PERFORM openpc.consume_archive_commit(p,a,NEW);
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION openpc.guard_archive_outbox()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE receipt control.evidence_archive_receipt; actual jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 SELECT * INTO STRICT receipt FROM control.evidence_archive_receipt WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.receipt_id;
 actual:=openpc.business_cbor(NEW.event);
 IF actual IS DISTINCT FROM jsonb_build_object('0','pc.evidence.remote-custody.v1',
  '1',openpc.business_uuid(receipt.participant_id),'2',openpc.business_uuid(receipt.privacy_domain_id),
  '3',openpc.business_uuid(receipt.receipt_id),'4',openpc.business_bytes(decode(substring(receipt.receipt_digest from 8),'hex')),
  '5',openpc.business_bytes(decode(substring(receipt.profile_digest from 8),'hex')),'6',openpc.business_uuid(receipt.attempt_id))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp(); RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION openpc.require_archive_commit_nonce(receipt control.evidence_archive_receipt)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.evidence_archive_commit_nonce n WHERE n.participant_id=receipt.participant_id
   AND n.privacy_domain_id=receipt.privacy_domain_id AND n.receipt_id=receipt.receipt_id
   AND n.receipt_digest=receipt.receipt_digest AND n.nonce=receipt.commit_nonce)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
END $$;
ALTER FUNCTION openpc.require_archive_commit_nonce(control.evidence_archive_receipt) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.require_archive_commit_nonce(control.evidence_archive_receipt) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.require_archive_commit_nonce(control.evidence_archive_receipt) TO openpc_control_worker;
CREATE OR REPLACE FUNCTION openpc.complete_archive_receipt()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE receipt control.evidence_archive_receipt;
BEGIN
 SELECT * INTO STRICT receipt FROM control.evidence_archive_receipt WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.receipt_id;
 PERFORM openpc.require_archive_profile(receipt.profile_digest,openpc.business_cbor(receipt.payload)->>'19');
 PERFORM openpc.require_archive_commit_nonce(receipt);
 IF NOT EXISTS(SELECT 1 FROM control.evidence_archive_outbox o WHERE o.participant_id=receipt.participant_id
  AND o.privacy_domain_id=receipt.privacy_domain_id AND o.receipt_id=receipt.receipt_id)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.complete_archive_receipt() FROM PUBLIC;
CREATE OR REPLACE FUNCTION openpc.complete_archive_nonce()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.evidence_archive_receipt r JOIN control.evidence_archive_outbox o
  USING(participant_id,privacy_domain_id,receipt_id) WHERE r.participant_id=NEW.participant_id
   AND r.privacy_domain_id=NEW.privacy_domain_id AND r.receipt_id=NEW.receipt_id
   AND r.commit_nonce=NEW.nonce AND r.receipt_digest=NEW.receipt_digest)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NULL;
END $$;
ALTER FUNCTION openpc.complete_archive_nonce() OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.complete_archive_nonce() FROM PUBLIC;

ALTER TABLE control.evidence_archive_receipt FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_archive_receipt FROM PUBLIC,openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT SELECT ON control.evidence_archive_receipt TO openpc_control_runtime,openpc_control_reader,openpc_control_owner,openpc_control_key_governor;
GRANT SELECT,INSERT ON control.evidence_archive_receipt TO openpc_control_worker;
DROP POLICY IF EXISTS archive_completion ON control.evidence_archive_receipt;
CREATE POLICY archive_completion ON control.evidence_archive_receipt FOR SELECT TO openpc_control_owner,openpc_control_key_governor USING(true);
DROP TRIGGER IF EXISTS archive_receipt ON control.evidence_archive_receipt;
CREATE TRIGGER archive_receipt BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_archive_receipt
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_archive_receipt();

ALTER TABLE control.evidence_archive_outbox FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_archive_outbox FROM PUBLIC,openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT SELECT ON control.evidence_archive_outbox TO openpc_control_runtime,openpc_control_reader,openpc_control_owner,openpc_control_key_governor;
GRANT SELECT,INSERT ON control.evidence_archive_outbox TO openpc_control_worker;
DROP POLICY IF EXISTS archive_completion ON control.evidence_archive_outbox;
CREATE POLICY archive_completion ON control.evidence_archive_outbox FOR SELECT TO openpc_control_owner,openpc_control_key_governor USING(true);
DROP TRIGGER IF EXISTS archive_outbox ON control.evidence_archive_outbox;
CREATE TRIGGER archive_outbox BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_archive_outbox
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_archive_outbox();
DROP TRIGGER IF EXISTS archive_receipt_complete ON control.evidence_archive_receipt;
CREATE CONSTRAINT TRIGGER archive_receipt_complete AFTER INSERT ON control.evidence_archive_receipt
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.complete_archive_receipt();
DROP TRIGGER IF EXISTS archive_nonce_complete ON control.evidence_archive_commit_nonce;
CREATE CONSTRAINT TRIGGER archive_nonce_complete AFTER INSERT ON control.evidence_archive_commit_nonce
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.complete_archive_nonce();

CREATE OR REPLACE FUNCTION openpc.remote_archive_covers(pid uuid,privacy uuid,stream text,segment uuid,sink text)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM control.evidence_remote_archive_intent i
  JOIN control.evidence_remote_archive_attempt a USING(participant_id,privacy_domain_id,intent_id)
  JOIN control.evidence_archive_receipt r USING(participant_id,privacy_domain_id,attempt_id)
  JOIN control.evidence_archive_outbox o USING(participant_id,privacy_domain_id,receipt_id)
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
   AND i.stream_id=stream AND i.segment_id=segment AND i.sink_id=sink
   AND a.state='OBSERVED' AND a.binding->'protection'->'rules'=openpc.remote_archive_rules(pid,privacy,stream,segment)
   AND NOT EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt newer
    WHERE newer.participant_id=i.participant_id AND newer.privacy_domain_id=i.privacy_domain_id
     AND newer.intent_id=i.intent_id AND (newer.binding->'protection'->>'revision')::numeric>(a.binding->'protection'->>'revision')::numeric))
$$;
REVOKE ALL ON FUNCTION openpc.remote_archive_covers(uuid,uuid,text,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.remote_archive_covers(uuid,uuid,text,uuid,text)
 TO openpc_control_worker,openpc_control_runtime,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.assert_remote_archive_checkpoint(v control.evidence_checkpoint)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE r control.evidence_archive_receipt; a control.evidence_remote_archive_attempt;
 i control.evidence_remote_archive_intent; p control.evidence_archive_profile; s control.evidence_segment; expected jsonb;
BEGIN
 p:=openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),(v).stream_id);
 SELECT * INTO STRICT r FROM control.evidence_archive_receipt WHERE participant_id=(v).participant_id
  AND privacy_domain_id=(v).privacy_domain_id AND receipt_digest=(v).receipt_digest;
 SELECT * INTO STRICT a FROM control.evidence_remote_archive_attempt WHERE participant_id=r.participant_id
  AND privacy_domain_id=r.privacy_domain_id AND attempt_id=r.attempt_id AND intent_id=r.intent_id AND state='OBSERVED';
 SELECT * INTO STRICT i FROM control.evidence_remote_archive_intent WHERE participant_id=r.participant_id
  AND privacy_domain_id=r.privacy_domain_id AND intent_id=r.intent_id;
 SELECT * INTO STRICT s FROM control.evidence_segment WHERE participant_id=i.participant_id
  AND privacy_domain_id=i.privacy_domain_id AND stream_id=i.stream_id AND segment_id=i.segment_id;
 expected:=jsonb_build_object('kind','SIGNED_REMOTE_ARCHIVE_V1','receiptId',r.receipt_id::text,
  'receiptDigest',r.receipt_digest,'profileDigest',r.profile_digest,'assurance','REMOTE_INTERFACE_VERIFIED',
  'providerQualification','NOT_ESTABLISHED');
 IF (v).receipt IS DISTINCT FROM expected OR (v).sink_id<>i.sink_id OR (v).stream_id<>i.stream_id
  OR (v).segment_id<>i.segment_id OR (v).object_digest<>s.object_digest OR (v).through_sequence<>s.through_sequence
  OR i.profile_digest<>p.transport_digest OR i.profile IS DISTINCT FROM p.transport OR i.sink_id<>p.sink_id
  OR a.binding->'protection'->'rules' IS DISTINCT FROM openpc.remote_archive_rules(s)
  OR NOT openpc.remote_archive_covers(s.participant_id,s.privacy_domain_id,s.stream_id,s.segment_id,i.sink_id)
  OR EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt newer WHERE newer.participant_id=i.participant_id
   AND newer.privacy_domain_id=i.privacy_domain_id AND newer.intent_id=i.intent_id
   AND (newer.binding->'protection'->>'revision')::numeric>(a.binding->'protection'->>'revision')::numeric)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.require_archive_commit_nonce(r);
END $$;
REVOKE ALL ON FUNCTION openpc.assert_remote_archive_checkpoint(control.evidence_checkpoint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_remote_archive_checkpoint(control.evidence_checkpoint) TO openpc_control_worker;



ALTER TABLE control.evidence_fact_provenance FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_fact_provenance FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.evidence_fact_provenance TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT INSERT ON control.evidence_fact_provenance TO openpc_control_worker;
CREATE OR REPLACE FUNCTION openpc.guard_evidence_fact_provenance()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p jsonb:=NEW.projection; l jsonb:=p->'lineage'; field text; deleted_source control.evidence_catalogue;
 resource_pattern text:='^urn:openpc:fact:[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN
  SELECT * INTO STRICT deleted_source FROM control.evidence_catalogue WHERE participant_id=OLD.participant_id AND privacy_domain_id=OLD.privacy_domain_id
   AND stream_id=OLD.stream_id AND record_id=OLD.record_id;
  PERFORM openpc.record_projection_deletion(deleted_source,'NORMALIZED_JSON_PROJECTION',OLD.projection);RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF EXISTS(SELECT 1 FROM control.evidence_projection_retirement r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
  AND r.data_class='NORMALIZED_JSON_PROJECTION' AND r.stream_id=NEW.stream_id AND r.record_id=NEW.record_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR jsonb_typeof(l) IS DISTINCT FROM 'object'
  OR p-ARRAY['candidateId','sourceSequence','receiptDigest','admittedAt','lineage','integrity','authority','currentReadiness','sourceProfileId','verificationKeyId','verificationKeyDigest']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(p))<>11
  OR l-ARRAY['factId','factDigest','factType','factProfileId','factKeyDigest','canonicalGeneration','projectionId','chainId','genesisDigest','blockNumber','blockHash','predecessorDigest','relationshipPredecessorDigest','reorgReplacementOf']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(l))<>14
  OR EXISTS(SELECT 1 FROM jsonb_each(p) e WHERE e.key<>'lineage' AND jsonb_typeof(e.value)<>'string')
  OR EXISTS(SELECT 1 FROM jsonb_each(l) e WHERE jsonb_typeof(e.value)<>'string'
   AND NOT(e.key IN ('predecessorDigest','relationshipPredecessorDigest','reorgReplacementOf') AND e.value='null'::jsonb))
  OR p->>'integrity' IS DISTINCT FROM 'FACT_COSE_VERIFIED_AT_CUSTODY'
  OR p->>'authority' IS DISTINCT FROM 'NONE' OR p->>'currentReadiness' IS DISTINCT FROM 'NOT_ESTABLISHED'
  OR coalesce(l->>'factId','')!~resource_pattern
  OR coalesce('urn:openpc:fact:'||(p->>'candidateId'),'')!~resource_pattern
  OR coalesce('urn:openpc:fact:'||(p->>'sourceProfileId'),'')!~resource_pattern
  OR coalesce(p->>'sourceSequence','')!~'^[1-9][0-9]{0,18}$'
  OR (p->>'sourceSequence')::numeric>9223372036854775807
  OR NEW.projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
  OR NEW.record_id<>'fact:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_array(NEW.participant_id::text,NEW.privacy_domain_id::text,p->>'sourceProfileId')),'UTF8')),'hex')||':'||(p->>'sourceSequence')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOREACH field IN ARRAY ARRAY['verificationKeyId','verificationKeyDigest','receiptDigest'] LOOP
  IF coalesce(p->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['factDigest','blockHash'] LOOP
  IF coalesce(l->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['predecessorDigest','relationshipPredecessorDigest'] LOOP
  IF l->field<>'null'::jsonb AND coalesce(l->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 IF l->'reorgReplacementOf'<>'null'::jsonb AND coalesce(l->>'reorgReplacementOf','')!~resource_pattern THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','FACT_TYPE_KEY','factType',l->>'factType','factProfileId',l->>'factProfileId','factKeyDigest',l->>'factKeyDigest'),NEW.participant_id,NEW.privacy_domain_id);
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','PROJECTION','projectionId',l->>'projectionId'),NEW.participant_id,NEW.privacy_domain_id);
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','GENERATION','generation',jsonb_build_object('kind','CANONICAL_FACT','factProfileId',l->>'factProfileId','canonicalGeneration',l->>'canonicalGeneration')),NEW.participant_id,NEW.privacy_domain_id);
 PERFORM openpc.evidence_hold_selector_encoding(jsonb_build_object('type','BLOCK_RANGE','chainId',l->>'chainId','genesisDigest',l->>'genesisDigest','fromBlock',l->>'blockNumber','throughBlock',l->>'blockNumber'),NEW.participant_id,NEW.privacy_domain_id);
 IF NOT EXISTS(SELECT 1 FROM control.evidence_catalogue c WHERE c.participant_id=NEW.participant_id
  AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id AND c.record_id=NEW.record_id
  AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.evidence_class='EFFECT'
  AND c.receipt_digest=p->>'receiptDigest' AND c.sequence::text=p->>'sourceSequence'
  AND c.occurred_at=(p->>'admittedAt')::timestamptz) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_fact_provenance_guard ON control.evidence_fact_provenance;
CREATE TRIGGER evidence_fact_provenance_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_fact_provenance
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_evidence_fact_provenance();

-- The direct immutable lineage is the preservation minimum. Reference closure
-- is resolved afresh across retained projections and signed retirements, so a
-- later hold can still cover an ancestor without retaining the whole projection.
CREATE OR REPLACE FUNCTION openpc.evidence_fact_lineages(participant uuid,privacy uuid)
RETURNS TABLE(stream_id text,record_id text,lineage jsonb)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT p.stream_id,p.record_id,p.projection->'lineage'
 FROM control.evidence_fact_provenance p JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
 WHERE p.participant_id=participant AND p.privacy_domain_id=privacy
  AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.evidence_class='EFFECT'
  AND p.projection->>'receiptDigest'=c.receipt_digest AND p.projection->>'sourceSequence'=c.sequence::text
  AND (p.projection->>'admittedAt')::timestamptz=c.occurred_at
  AND p.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p.projection),'UTF8')),'hex')
 UNION ALL
 SELECT r.stream_id,r.record_id,r.preservation_metadata->'factLineage'
 FROM control.evidence_projection_retirement r JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
 JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
 WHERE r.participant_id=participant AND r.privacy_domain_id=privacy AND r.data_class='NORMALIZED_JSON_PROJECTION'
  AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.evidence_class='EFFECT'
  AND r.evidence_id=c.evidence_id AND r.source_receipt_digest=c.receipt_digest AND r.sequence=c.sequence AND r.segment_id=c.segment_id
  AND j.state='SUCCEEDED' AND j.selection->>'sourceKind'='FACT_PROVENANCE'
  AND j.selection->>'projectionDigest'=r.projection_digest AND j.selection->>'sourceReceiptDigest'=r.source_receipt_digest
  AND r.retirement_digest=openpc.projection_retirement_digest(r)
  AND jsonb_typeof(r.preservation_metadata->'factLineage')='object'
$$;
REVOKE ALL ON FUNCTION openpc.evidence_fact_lineages(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_fact_lineages(uuid,uuid) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.evidence_fact_hold_metadata(source control.evidence_catalogue)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE original jsonb; queue jsonb; item jsonb; lineage jsonb; reference jsonb; candidates jsonb;
 seen text[]:=ARRAY[]::text[]; unresolved boolean:=false; steps integer:=0;
 projections jsonb:='[]'; facts jsonb:='[]'; blocks jsonb:='[]'; generations jsonb:='[]';
BEGIN
 -- The closure resolver reloads authoritative ancestors. First bind the caller's
 -- starting record itself, so a modified class/digest/sequence cannot borrow the
 -- lineage of an otherwise valid catalogue identity.
 IF (source).source_format IS DISTINCT FROM 'OPENPC_CANONICAL_FACT_V1'
  OR (source).evidence_class IS DISTINCT FROM 'EFFECT'
  OR NOT EXISTS(SELECT 1 FROM control.evidence_catalogue c
   WHERE c.participant_id=(source).participant_id AND c.privacy_domain_id=(source).privacy_domain_id
    AND c.stream_id=(source).stream_id AND c.record_id=(source).record_id
    AND c IS NOT DISTINCT FROM source) THEN RETURN NULL; END IF;
 SELECT jsonb_agg(DISTINCT p.lineage) INTO candidates FROM openpc.evidence_fact_lineages((source).participant_id,(source).privacy_domain_id) p
  WHERE p.stream_id=(source).stream_id AND p.record_id=(source).record_id;
 IF candidates IS NULL OR jsonb_array_length(candidates)<>1 THEN RETURN NULL; END IF;
 original:=candidates->0;
 queue:=jsonb_build_array(jsonb_build_object('lineage',original,'path','[]'::jsonb));
 WHILE jsonb_array_length(queue)>0 AND steps<64 LOOP
  item:=queue->0; queue:=queue-0; lineage:=item->'lineage'; steps:=steps+1;
  IF item->'path' ? (lineage->>'factDigest') THEN unresolved:=true; CONTINUE; END IF;
  IF lineage->>'factDigest'=ANY(seen) THEN CONTINUE; END IF;
  seen:=array_append(seen,lineage->>'factDigest');
  projections:=projections||jsonb_build_array(lineage->>'projectionId');
  facts:=facts||jsonb_build_array(jsonb_build_object('factType',lineage->>'factType','factProfileId',lineage->>'factProfileId','factKeyDigest',lineage->>'factKeyDigest'));
  blocks:=blocks||jsonb_build_array(jsonb_build_object('chainId',lineage->>'chainId','genesisDigest',lineage->>'genesisDigest','blockNumber',lineage->>'blockNumber'));
  generations:=generations||jsonb_build_array(jsonb_build_object('kind','CANONICAL_FACT','factProfileId',lineage->>'factProfileId','canonicalGeneration',lineage->>'canonicalGeneration'));
  FOR reference IN SELECT value FROM jsonb_array_elements(jsonb_build_array(lineage->'predecessorDigest',lineage->'relationshipPredecessorDigest',lineage->'reorgReplacementOf')) WHERE value<>'null'::jsonb LOOP
   SELECT jsonb_agg(DISTINCT p.lineage) INTO candidates
    FROM openpc.evidence_fact_lineages((source).participant_id,(source).privacy_domain_id) p
    WHERE p.lineage->'factDigest'=reference OR p.lineage->'factId'=reference;
   IF candidates IS NULL OR jsonb_array_length(candidates)<>1 THEN unresolved:=true;
   -- Visit descendants before queued siblings. Breadth-first de-duplication can
   -- mark both ends of a shared-reference cycle seen before either back edge
   -- reaches its ancestor path, incorrectly reporting complete closure.
   ELSE queue:=jsonb_build_array(jsonb_build_object('lineage',candidates->0,'path',(item->'path')||jsonb_build_array(lineage->>'factDigest')))||queue; END IF;
  END LOOP;
 END LOOP;
 RETURN jsonb_build_object('projections',projections,'facts',facts,'blocks',blocks,
  'generations',jsonb_build_object('CANONICAL_FACT',generations),'unresolvedReferences',unresolved OR jsonb_array_length(queue)>0);
EXCEPTION WHEN insufficient_privilege THEN RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.evidence_fact_hold_metadata(control.evidence_catalogue) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_fact_hold_metadata(control.evidence_catalogue) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;


ALTER TABLE control.evidence_fact_admission_inbox FORCE ROW LEVEL SECURITY;
ALTER TABLE control.evidence_fact_admission_cursor FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_fact_admission_inbox,control.evidence_fact_admission_cursor
 FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.evidence_fact_admission_inbox,control.evidence_fact_admission_cursor
 TO openpc_control_worker,openpc_control_reader;
GRANT INSERT ON control.evidence_fact_admission_inbox TO openpc_control_worker;
GRANT INSERT,UPDATE ON control.evidence_fact_admission_cursor TO openpc_control_worker;
CREATE OR REPLACE FUNCTION openpc.guard_fact_admission_inbox()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE e jsonb:=NEW.envelope; d jsonb:=e->'data'; p jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT f.projection INTO p FROM control.evidence_fact_provenance f
  JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  JOIN control.evidence_segment_payload b USING(participant_id,privacy_domain_id,stream_id,segment_id)
  WHERE f.participant_id=NEW.participant_id AND f.privacy_domain_id=NEW.privacy_domain_id
   AND f.stream_id=NEW.stream_id AND f.record_id=NEW.record_id
   AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.receipt_digest=NEW.source_receipt_digest;
 IF p IS NULL THEN
  p:=nullif(current_setting('openpc.fact_delivery_source_projection',true),'')::jsonb;
  IF p IS NULL OR octet_length(p::text)>4096 OR NOT EXISTS(
   SELECT 1 FROM control.evidence_projection_retirement r
    JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
    JOIN control.evidence_catalogue c ON c.participant_id=r.participant_id AND c.privacy_domain_id=r.privacy_domain_id
      AND c.stream_id=r.stream_id AND c.record_id=r.record_id AND c.segment_id=r.segment_id
    JOIN control.evidence_segment_payload b ON b.participant_id=c.participant_id AND b.privacy_domain_id=c.privacy_domain_id
      AND b.stream_id=c.stream_id AND b.segment_id=c.segment_id
   WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
    AND r.stream_id=NEW.stream_id AND r.record_id=NEW.record_id
    AND r.data_class='NORMALIZED_JSON_PROJECTION' AND j.state='SUCCEEDED'
    AND j.selection->>'sourceKind'='FACT_PROVENANCE'
    AND r.retirement_digest=openpc.projection_retirement_digest(r)
    AND r.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
    AND r.source_receipt_digest=NEW.source_receipt_digest
    AND r.preservation_metadata=jsonb_build_object('factLineage',p->'lineage')
    AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.receipt_digest=NEW.source_receipt_digest
    AND c.sequence::text=p->>'sourceSequence' AND c.occurred_at=(p->>'admittedAt')::timestamptz
  ) THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-CUSTODY-BINDING'; END IF;
 END IF;
 IF p->>'candidateId' IS DISTINCT FROM NEW.candidate_id::text
  OR p->>'receiptDigest' IS DISTINCT FROM NEW.source_receipt_digest
  OR p->'lineage'->>'factId' IS DISTINCT FROM 'urn:openpc:fact:'||NEW.event_id::text
  OR p->'lineage'->>'factType' IS DISTINCT FROM NEW.fact_type
  OR e IS DISTINCT FROM jsonb_build_object(
   'specversion','1.0','id',NEW.event_id::text,'source','urn:openpc:service:LS-FACT-BRIDGE',
   'type','io.openpc.fact.candidate.admitted.v1','subject','urn:openpc:resource:'||NEW.candidate_id::text,
   'time',e->>'time','datacontenttype','application/json',
   'dataschema','https://schemas.openpc.local/event-payloads.schema.json#/$defs/FactCandidateAdmitted',
   'participantid','urn:openpc:participant:'||NEW.participant_id::text,
   'privacydomainid','urn:openpc:privacy-domain:'||NEW.privacy_domain_id::text,
   'correlationid',NEW.candidate_id::text,'authoritygeneration',e->>'authoritygeneration',
   'sequence',NEW.sequence::text,'datadigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(d),'UTF8')),'hex'),
   'data',d)
  OR d IS DISTINCT FROM jsonb_build_object('candidateId','urn:openpc:resource:'||NEW.candidate_id::text,
   'factArtifactId','urn:openpc:resource:'||NEW.candidate_id::text,'artifactDigest',d->>'artifactDigest',
   'sourceProfileDigest',d->>'sourceProfileDigest','sourceNeutral',true)
  OR coalesce(d->>'artifactDigest','')!~'^sha256:[0-9a-f]{64}$'
  OR coalesce(d->>'sourceProfileDigest','')!~'^sha256:[0-9a-f]{64}$'
  OR coalesce(e->>'authoritygeneration','')!~'^sha256:[0-9a-f]{64}$'
  OR coalesce(e->>'time','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
  OR NEW.envelope_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(e),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-CUSTODY-BINDING'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS fact_admission_inbox_guard ON control.evidence_fact_admission_inbox;
CREATE TRIGGER fact_admission_inbox_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_fact_admission_inbox
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_fact_admission_inbox();
CREATE OR REPLACE FUNCTION openpc.guard_fact_admission_cursor()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE amount bigint;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.sequence<>0 THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-CURSOR'; END IF;
 ELSE
  IF row(NEW.participant_id,NEW.privacy_domain_id,NEW.fact_type) IS DISTINCT FROM row(OLD.participant_id,OLD.privacy_domain_id,OLD.fact_type)
   OR NEW.sequence<=OLD.sequence OR NEW.sequence>OLD.sequence+256 THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-CURSOR'; END IF;
  SELECT count(*) INTO amount FROM control.evidence_fact_admission_inbox i WHERE i.participant_id=NEW.participant_id
   AND i.privacy_domain_id=NEW.privacy_domain_id AND i.fact_type=NEW.fact_type AND i.sequence>OLD.sequence AND i.sequence<=NEW.sequence;
  IF amount<>NEW.sequence-OLD.sequence THEN RAISE EXCEPTION 'DATA-6021-FACT-INBOX-GAP'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS fact_admission_cursor_guard ON control.evidence_fact_admission_cursor;
CREATE TRIGGER fact_admission_cursor_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_fact_admission_cursor
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_fact_admission_cursor();
REVOKE ALL ON FUNCTION openpc.guard_fact_admission_inbox(),openpc.guard_fact_admission_cursor() FROM PUBLIC;


ALTER TABLE control.evidence_candidate_archive FORCE ROW LEVEL SECURITY;
ALTER TABLE control.evidence_candidate_archive_part FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_candidate_archive,control.evidence_candidate_archive_part
 FROM PUBLIC,openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT SELECT ON control.evidence_candidate_archive,control.evidence_candidate_archive_part
 TO openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT INSERT ON control.evidence_candidate_archive,control.evidence_candidate_archive_part TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.guard_candidate_archive()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE m jsonb:=NEW.manifest; i jsonb:=m->'identity'; b jsonb:=i->'block'; entry jsonb;
 prefix text; expected_id text; expected_digest text; expected_format text; index integer:=0;
 total integer; part_count integer; previous_sequence numeric:=0; original control.evidence_catalogue;
 field text; block_field text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR NOT pg_has_role(current_user,'openpc_control_worker','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 IF m IS DISTINCT FROM jsonb_build_object('version','OPENPC_CANDIDATE_PROJECTION_MANIFEST_V1',
  'class','CANDIDATE_PROJECTION','store','openpc_candidate_index','authority','NONE',
  'currentReadiness','NOT_ESTABLISHED','identity',i,'identityDigest',m->'identityDigest','chunks',m->'chunks')
  OR jsonb_typeof(i) IS DISTINCT FROM 'object' OR jsonb_typeof(b) IS DISTINCT FROM 'object'
  OR i-ARRAY['participantId','privacyDomainId','sourceProfileId','generationId','partitionId','candidateId',
   'publicationDigest','sourceProfileDigest','partitionDigest','projectionId','mappingDigest','nativeRecordId',
   'recordKind','recordSequence','candidateFeedSequence','observedEventId','observedEventDigest','payloadDigest',
   'payloadBytes','schemaDigest','evidenceDigest','checkpointDigest','occurredAt','chainId','genesisDigest','block']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(i))<>26
  OR b-ARRAY['number','hash','parentHash','finalityKind','finalityEvidenceDigest','headNumber','headHash']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(b))<>7
  OR jsonb_typeof(m->'chunks') IS DISTINCT FROM 'array'
  OR jsonb_array_length(m->'chunks') NOT BETWEEN 1 AND 16
  OR i->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR i->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR i->>'candidateId' IS DISTINCT FROM NEW.candidate_id::text
  OR NEW.manifest_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(m),'UTF8')),'hex')
  OR m->>'identityDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(i),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOR field IN SELECT jsonb_object_keys(i) LOOP
  IF field NOT IN ('payloadBytes','block') AND jsonb_typeof(i->field) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOR field IN SELECT jsonb_object_keys(b) LOOP
  IF jsonb_typeof(b->field) IS DISTINCT FROM 'string'
   AND NOT(field IN ('headNumber','headHash') AND b->field='null'::jsonb)
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['participantId','privacyDomainId','sourceProfileId','generationId','partitionId','candidateId','projectionId','observedEventId'] LOOP
  IF coalesce(i->>field,'')!~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['publicationDigest','sourceProfileDigest','partitionDigest','mappingDigest','observedEventDigest',
  'payloadDigest','schemaDigest','evidenceDigest','checkpointDigest','genesisDigest'] LOOP
  IF coalesce(i->>field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 FOREACH block_field IN ARRAY ARRAY['hash','parentHash','finalityEvidenceDigest'] LOOP
  IF coalesce(b->>block_field,'')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END LOOP;
 IF coalesce(i->>'recordKind','') NOT IN ('EVENT_LOG','STATE_CALL','TRANSACTION_RECEIPT','BLOCK_HEADER','FULL_BLOCK_TRANSACTIONS','EXTERNAL_OBSERVATION')
  OR length(i->>'nativeRecordId') NOT BETWEEN 1 AND 256
  OR coalesce(i->>'recordSequence','')!~'^(0|[1-9][0-9]{0,19})$' OR (i->>'recordSequence')::numeric>18446744073709551615
  OR coalesce(i->>'candidateFeedSequence','')!~'^[1-9][0-9]{0,18}$' OR (i->>'candidateFeedSequence')::numeric>9223372036854775807
  OR coalesce(i->>'chainId','')!~'^(0|[1-9][0-9]{0,77})$' OR (i->>'chainId')::numeric>=power(2::numeric,256)
  OR coalesce(b->>'number','')!~'^(0|[1-9][0-9]{0,19})$' OR (b->>'number')::numeric>18446744073709551615
  OR coalesce(b->>'finalityKind','') NOT IN ('SAFE_TAG','FINALIZED_TAG','CONFIRMATIONS')
  OR ((b->>'finalityKind'='CONFIRMATIONS') IS DISTINCT FROM (b->'headNumber'<>'null'::jsonb AND b->'headHash'<>'null'::jsonb))
  OR ((b->'headNumber'='null'::jsonb) IS DISTINCT FROM (b->'headHash'='null'::jsonb))
  OR (b->'headNumber'<>'null'::jsonb AND (coalesce(b->>'headNumber','')!~'^(0|[1-9][0-9]{0,19})$'
    OR (b->>'headNumber')::numeric>18446744073709551615 OR coalesce(b->>'headHash','')!~'^sha256:[0-9a-f]{64}$'))
  OR jsonb_typeof(i->'payloadBytes') IS DISTINCT FROM 'number'
  OR coalesce(i->>'payloadBytes','')!~'^[1-9][0-9]{0,6}$' OR (i->>'payloadBytes')::integer NOT BETWEEN 1 AND 1048576
  OR coalesce(i->>'occurredAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}Z$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 total:=(i->>'payloadBytes')::integer; part_count:=jsonb_array_length(m->'chunks');
 prefix:='candidate:'||substring(m->>'identityDigest' from 8);
 IF part_count<>(total+65535)/65536 OR NEW.record_id<>prefix||':manifest' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(m->'chunks') LOOP
  IF entry IS DISTINCT FROM jsonb_build_object('index',index,'offset',index*65536,
    'bytes',least(65536,total-index*65536),'recordId',prefix||':chunk:'||index::text,'digest',entry->'digest')
    OR coalesce(entry->>'digest','')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  index:=index+1;
 END LOOP;
 -- Every chunk precedes the final manifest. Native feed sequence is independent
 -- of the catalogue's contiguous archive sequence and is never used as its cursor.
 FOR index IN 0..part_count LOOP
  expected_id:=CASE WHEN index=part_count THEN NEW.record_id ELSE m->'chunks'->index->>'recordId' END;
  expected_digest:=CASE WHEN index=part_count THEN NEW.manifest_digest ELSE m->'chunks'->index->>'digest' END;
  expected_format:=CASE WHEN index=part_count THEN 'OPENPC_CANDIDATE_PROJECTION_MANIFEST_V1' ELSE 'OPENPC_CANDIDATE_PROJECTION_CHUNK_V1' END;
  SELECT c.* INTO STRICT original FROM control.evidence_catalogue c
   JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
   JOIN control.evidence_segment_payload body USING(participant_id,privacy_domain_id,stream_id,segment_id)
   WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
    AND c.stream_id=NEW.stream_id AND c.record_id=expected_id
    AND c.evidence_class='EFFECT' AND c.source_format=expected_format AND c.receipt_digest=expected_digest
    AND c.occurred_at=(i->>'occurredAt')::timestamptz AND c.sequence BETWEEN s.first_sequence AND s.through_sequence
    AND s.object_digest='sha256:'||encode(sha256(body.encrypted_segment),'hex');
  IF original.sequence<=previous_sequence THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  previous_sequence:=original.sequence;
 END LOOP;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS candidate_archive_guard ON control.evidence_candidate_archive;
CREATE TRIGGER candidate_archive_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_candidate_archive
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_candidate_archive();
REVOKE ALL ON FUNCTION openpc.guard_candidate_archive() FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.index_candidate_archive_parts()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE item jsonb; index integer:=0;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements(NEW.manifest->'chunks') LOOP
  INSERT INTO control.evidence_candidate_archive_part(participant_id,privacy_domain_id,stream_id,manifest_record_id,ordinal,record_id)
   VALUES(NEW.participant_id,NEW.privacy_domain_id,NEW.stream_id,NEW.record_id,index,item->>'recordId');
  index:=index+1;
 END LOOP;
 INSERT INTO control.evidence_candidate_archive_part(participant_id,privacy_domain_id,stream_id,manifest_record_id,ordinal,record_id)
  VALUES(NEW.participant_id,NEW.privacy_domain_id,NEW.stream_id,NEW.record_id,index,NEW.record_id);
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.index_candidate_archive_parts() FROM PUBLIC;
DROP TRIGGER IF EXISTS candidate_archive_parts ON control.evidence_candidate_archive;
CREATE TRIGGER candidate_archive_parts AFTER INSERT ON control.evidence_candidate_archive
 FOR EACH ROW EXECUTE FUNCTION openpc.index_candidate_archive_parts();
CREATE OR REPLACE FUNCTION openpc.guard_candidate_archive_part()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE parent control.evidence_candidate_archive; expected text; count_parts integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT parent FROM control.evidence_candidate_archive WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND record_id=NEW.manifest_record_id;
 count_parts:=jsonb_array_length(parent.manifest->'chunks');
 expected:=CASE WHEN NEW.ordinal=count_parts THEN parent.record_id ELSE parent.manifest->'chunks'->NEW.ordinal->>'recordId' END;
 IF expected IS NULL OR NEW.record_id IS DISTINCT FROM expected OR NEW.ordinal<0 OR NEW.ordinal>count_parts THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_candidate_archive_part() FROM PUBLIC;
DROP TRIGGER IF EXISTS candidate_archive_part_guard ON control.evidence_candidate_archive_part;
CREATE TRIGGER candidate_archive_part_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_candidate_archive_part
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_candidate_archive_part();

CREATE OR REPLACE FUNCTION openpc.candidate_archive_hold_metadata(source control.evidence_catalogue)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE identity jsonb;
BEGIN
 SELECT a.manifest->'identity' INTO STRICT identity FROM control.evidence_candidate_archive a
  JOIN control.evidence_candidate_archive_part part ON part.participant_id=a.participant_id AND part.privacy_domain_id=a.privacy_domain_id
   AND part.stream_id=a.stream_id AND part.manifest_record_id=a.record_id
  JOIN control.evidence_catalogue c ON c.participant_id=part.participant_id AND c.privacy_domain_id=part.privacy_domain_id
   AND c.stream_id=part.stream_id AND c.record_id=part.record_id
  WHERE c IS NOT DISTINCT FROM source AND a.manifest_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(a.manifest),'UTF8')),'hex');
 -- This owner proves only its direct projection/block. Missing cross-store
 -- ancestry stays UNKNOWN; candidate generation is not canonical Fact generation.
 RETURN jsonb_build_object('projections',jsonb_build_array('urn:openpc:resource:'||(identity->>'projectionId')),
  'blocks',jsonb_build_array(jsonb_build_object('chainId',identity->>'chainId','genesisDigest',identity->>'genesisDigest',
   'blockNumber',identity->'block'->>'number')),'unresolvedReferences',true);
EXCEPTION WHEN no_data_found OR too_many_rows OR insufficient_privilege THEN RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.candidate_archive_hold_metadata(control.evidence_catalogue) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.candidate_archive_hold_metadata(control.evidence_catalogue)
 TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.candidate_archive_coverage(pid uuid,privacy uuid,stream text,record_ref text,sinks text[])
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE a control.evidence_candidate_archive; object record; checkpoint control.evidence_checkpoint;
 sink text; receipts jsonb; objects jsonb:='[]'; original_count integer; pending jsonb;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF pid IS DISTINCT FROM openpc.current_participant_id() OR privacy IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR sinks IS NULL OR cardinality(sinks) NOT BETWEEN 1 AND 8 OR array_position(sinks,NULL) IS NOT NULL
  OR cardinality(sinks)<>(SELECT count(DISTINCT value) FROM unnest(sinks) value)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.evidence_candidate_archive WHERE participant_id=pid
  AND privacy_domain_id=privacy AND stream_id=stream AND record_id=record_ref;
 pending:=jsonb_build_object('state','PENDING','authority','NONE','manifestDigest',a.manifest_digest);
 SELECT count(*) INTO original_count FROM control.evidence_candidate_archive_part part
  JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  WHERE part.participant_id=pid AND part.privacy_domain_id=privacy AND part.stream_id=stream AND part.manifest_record_id=record_ref;
 IF original_count<>jsonb_array_length(a.manifest->'chunks')+1 THEN RETURN pending; END IF;
 FOR object IN SELECT DISTINCT s.segment_id,s.object_digest,s.first_sequence,s.through_sequence
  FROM control.evidence_candidate_archive_part part JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
  WHERE part.participant_id=pid AND part.privacy_domain_id=privacy AND part.stream_id=stream AND part.manifest_record_id=record_ref
  ORDER BY s.first_sequence LOOP
  receipts:='[]';
  FOREACH sink IN ARRAY sinks LOOP
   SELECT * INTO checkpoint FROM control.evidence_checkpoint c WHERE c.participant_id=pid AND c.privacy_domain_id=privacy
    AND c.stream_id=stream AND c.segment_id=object.segment_id AND c.object_digest=object.object_digest
    AND c.through_sequence=object.through_sequence AND c.sink_id=sink;
   IF NOT FOUND THEN RETURN pending; END IF;
   IF checkpoint.receipt->>'kind'='SIGNED_REMOTE_ARCHIVE_V1' THEN
    IF NOT openpc.remote_archive_covers(pid,privacy,stream,object.segment_id,sink) THEN RETURN pending; END IF;
   ELSIF EXISTS(SELECT 1 FROM control.retention_hold h WHERE h.participant_id=pid
     AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=privacy)
     AND openpc.evidence_hold_requires_coverage(h,stream,object.segment_id)
     AND NOT EXISTS(SELECT 1 FROM control.evidence_hold_coverage c WHERE c.participant_id=pid AND c.privacy_domain_id=privacy
       AND c.retention_hold_id=h.retention_hold_id AND c.hold_revision=h.revision AND c.stream_id=stream
       AND c.segment_id=object.segment_id AND c.object_digest=object.object_digest AND c.sink_id=sink))
   THEN RETURN pending; END IF;
   receipts:=receipts||jsonb_build_array(jsonb_build_object('sinkId',sink,'checkpointDigest',checkpoint.checkpoint_digest,'receiptDigest',checkpoint.receipt_digest));
  END LOOP;
  objects:=objects||jsonb_build_array(jsonb_build_object('segmentId',object.segment_id::text,'objectDigest',object.object_digest,
   'firstSequence',object.first_sequence::text,'throughSequence',object.through_sequence::text,'sinkReceipts',receipts));
 END LOOP;
 IF jsonb_array_length(objects)=0 THEN RETURN pending; END IF;
 RETURN jsonb_build_object('state','COMPLETE','authority','NONE','manifestDigest',a.manifest_digest,'segments',objects);
END $$;
REVOKE ALL ON FUNCTION openpc.candidate_archive_coverage(uuid,uuid,text,text,text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.candidate_archive_coverage(uuid,uuid,text,text,text[])
 TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;


