CREATE OR REPLACE FUNCTION openpc.runtime_artifact_archive_payloads_match(input_id uuid)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE s control.runtime_artifact_source; a control.evidence_runtime_artifact_archive; input record;
 p uuid:=openpc.current_participant_id(); d uuid:=openpc.current_privacy_domain_id();
 lock_key text; expected_mode text; part_count integer;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF (EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user
 AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication
 AND NOT pg_has_role(oid,'openpc_control_owner','MEMBER')
 AND NOT pg_has_role(oid,'openpc_control_key_governor','MEMBER'))
 AND pg_has_role(session_user,'openpc_control_runtime','USAGE')
 AND openpc.current_action_intent_id() IN
 ('ACT-EVIDENCE_DELETIONS_READ_RUNTIME_SOURCE-V1','ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1',
  'ACT-EVIDENCE_DELETIONS_READ_RESOURCE-V1','ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1')) IS DISTINCT FROM true
  OR current_setting('transaction_isolation')<>'read committed' OR current_setting('session_replication_role')<>'origin'
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND NOT rolsuper AND NOT rolbypassrls)
  OR (current_setting('role')<>'none' AND NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_setting('role')
   AND NOT rolsuper AND NOT rolbypassrls AND pg_has_role(oid,'openpc_control_runtime','USAGE')))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 -- SECURITY DEFINER changes current_user. Inspect the actual session and the
 -- existing producer fences; never call the invoker role-checking lock owner.
 FOREACH lock_key IN ARRAY ARRAY['evidence-lifecycle:'||p::text,'module-release-catalog',
  'module-admission:'||p::text||':'||d::text,'openpc-policy-generations:'||p::text||':'||d::text] LOOP
  expected_mode:=CASE WHEN lock_key LIKE 'module-admission:%' OR lock_key LIKE 'evidence-lifecycle:%' THEN 'ExclusiveLock' ELSE 'ShareLock' END;
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode=expected_mode
   AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended(lock_key,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_key,0)&4294967295)::oid AND l.objsubid=1)
  THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-OBSERVATION-FENCE'; END IF;
 END LOOP;
 IF input_id IS NULL THEN RETURN false; END IF;
 s:=openpc.runtime_artifact_materialization_source();
 IF s.custody_root->>'consumer_profile' IS DISTINCT FROM 'openpc:local-runtime-source-consumers:v2' OR s.archive_custody IS NULL
 THEN RETURN false; END IF;
 SELECT runtime_configuration_input_id,module_installation_id,module_configuration_generation_id,configuration_digest,resource_bindings,created_at,
  openpc.runtime_artifact_input_information(runtime_configuration_input_id) info INTO STRICT input
  FROM control.runtime_configuration_input WHERE participant_id=p AND privacy_domain_id=d AND runtime_configuration_input_id=input_id;
 SELECT * INTO STRICT a FROM control.evidence_runtime_artifact_archive WHERE participant_id=p AND privacy_domain_id=d
  AND runtime_configuration_input_id=input_id AND stream_id=s.archive_custody->>'stream_id';
 IF a.source_pending_original IS NULL OR input.info->'bytesMatch' IS DISTINCT FROM 'true'::jsonb
  OR jsonb_typeof(a.manifest->'chunks') IS DISTINCT FROM 'array'
  OR a.manifest->>'version' IS DISTINCT FROM 'OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1'
  OR a.manifest_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(a.manifest),'UTF8')),'hex')
  OR a.manifest->'identity' IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,
   'runtimeConfigurationInputId',input_id::text,'moduleInstallationId',input.module_installation_id::text,
   'moduleConfigurationGenerationId',input.module_configuration_generation_id::text,'configurationDigest','sha256:'||encode(input.configuration_digest,'hex'),
   'configurationBytes',(input.info->>'byteLength')::integer,'resourceBindingsDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(input.resource_bindings),'UTF8')),'hex'),
   'createdAt',to_char(input.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
 THEN RETURN false; END IF;
 part_count:=jsonb_array_length(a.manifest->'chunks');
 IF part_count NOT BETWEEN 1 AND 64 OR
  (SELECT count(*) FROM control.evidence_runtime_artifact_archive_part entry WHERE entry.participant_id=p AND entry.privacy_domain_id=d
   AND entry.stream_id=a.stream_id AND entry.manifest_record_id=a.record_id)<>part_count+1
 THEN RETURN false; END IF;
 -- Only stored hashes and complete stored membership are compared. There is no
 -- caller-selected segment or expected digest, and no payload leaves this owner.
 RETURN (SELECT count(*) FROM control.evidence_runtime_artifact_archive_part entry
  JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  JOIN control.evidence_segment seg USING(participant_id,privacy_domain_id,stream_id,segment_id)
  JOIN control.evidence_segment_payload payload USING(participant_id,privacy_domain_id,stream_id,segment_id)
  WHERE entry.participant_id=p AND entry.privacy_domain_id=d AND entry.stream_id=a.stream_id AND entry.manifest_record_id=a.record_id
   AND entry.ordinal BETWEEN 0 AND part_count
   AND entry.record_id=CASE WHEN entry.ordinal=part_count THEN a.record_id ELSE a.manifest->'chunks'->entry.ordinal->>'recordId' END
   AND c.receipt_digest=CASE WHEN entry.ordinal=part_count THEN a.manifest_digest ELSE a.manifest->'chunks'->entry.ordinal->>'digest' END
   AND c.evidence_class='EFFECT' AND c.source_format=CASE WHEN entry.ordinal=part_count
    THEN 'OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1' ELSE 'OPENPC_RUNTIME_ARTIFACT_CHUNK_V1' END
   AND c.occurred_at=input.created_at AND c.sequence BETWEEN seg.first_sequence AND seg.through_sequence
   AND seg.object_digest='sha256:'||encode(sha256(payload.encrypted_segment),'hex'))=part_count+1;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RETURN false;
END $$;
ALTER FUNCTION openpc.runtime_artifact_archive_payloads_match(uuid) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_archive_payloads_match(uuid) FROM PUBLIC,openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_archive_payloads_match(uuid) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.guard_runtime_artifact_archive()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE m jsonb:=NEW.manifest; i jsonb:=m->'identity'; entry jsonb;
 prefix text; expected_id text; expected_digest text; expected_format text; index integer:=0;
 total integer; part_count integer; previous_sequence numeric:=0; original control.evidence_catalogue;
 native control.runtime_configuration_input; source control.runtime_artifact_source; pending jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR NOT pg_has_role(session_user,'openpc_control_worker','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 -- Direct SQL may arrive after other row locks; never reverse-wait. The
 -- ordinary custody owner already acquired this same lock before stream rows.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT native FROM control.runtime_configuration_input WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND runtime_configuration_input_id=NEW.runtime_configuration_input_id FOR SHARE;
 IF i IS DISTINCT FROM jsonb_build_object('participantId',native.participant_id::text,
  'privacyDomainId',native.privacy_domain_id::text,'runtimeConfigurationInputId',native.runtime_configuration_input_id::text,
  'moduleInstallationId',native.module_installation_id::text,'moduleConfigurationGenerationId',native.module_configuration_generation_id::text,
  'configurationDigest','sha256:'||encode(native.configuration_digest,'hex'),'configurationBytes',octet_length(native.configuration_cbor),
  'resourceBindingsDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(native.resource_bindings),'UTF8')),'hex'),
  'createdAt',to_char(native.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
  OR sha256(native.configuration_cbor) IS DISTINCT FROM native.configuration_digest
  OR octet_length(native.configuration_cbor) NOT BETWEEN 1 AND 4194304
  OR m IS DISTINCT FROM jsonb_build_object('version','OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1',
   'class','RUNTIME_ARTIFACT','store','openpc_control','authority','NONE','currentReadiness','NOT_ESTABLISHED',
   'identity',i,'identityDigest',m->'identityDigest','chunks',m->'chunks')
  OR jsonb_typeof(m->'chunks') IS DISTINCT FROM 'array'
  OR jsonb_array_length(m->'chunks') NOT BETWEEN 1 AND 64
  OR NEW.manifest_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(m),'UTF8')),'hex')
  OR m->>'identityDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
   jsonb_build_object('domain','pc.runtime-artifact.archive-identity.v1','identity',i)),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO source FROM control.runtime_artifact_source WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id;
 IF source.custody_root->>'consumer_profile'='openpc:local-runtime-source-consumers:v2' THEN
  pending:=openpc.runtime_artifact_archive_permit(NEW.runtime_configuration_input_id,NEW.stream_id);
  IF NEW.source_pending_original IS DISTINCT FROM decode(pending->>'original','hex')
   THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-ORIGINAL-UNAVAILABLE'; END IF;
 ELSIF NEW.source_pending_original IS NOT NULL THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-ARCHIVE-ORIGINAL-UNAVAILABLE'; END IF;
 total:=octet_length(native.configuration_cbor); part_count:=jsonb_array_length(m->'chunks');
 prefix:='runtime-artifact:'||substring(m->>'identityDigest' from 8);
 IF part_count<>(total+65535)/65536 OR NEW.record_id<>prefix||':manifest' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(m->'chunks') LOOP
  IF entry IS DISTINCT FROM jsonb_build_object('index',index,'offset',index*65536,
    'bytes',least(65536,total-index*65536),'recordId',prefix||':chunk:'||index::text,'digest',entry->'digest')
    OR entry->>'digest' IS DISTINCT FROM 'sha256:'||encode(sha256(substring(native.configuration_cbor from index*65536+1 for least(65536,total-index*65536))),'hex') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  index:=index+1;
 END LOOP;
 -- Every chunk precedes the final manifest. The native input identity never
 -- substitutes for the catalogue's contiguous archive sequence.
 FOR index IN 0..part_count LOOP
  expected_id:=CASE WHEN index=part_count THEN NEW.record_id ELSE m->'chunks'->index->>'recordId' END;
  expected_digest:=CASE WHEN index=part_count THEN NEW.manifest_digest ELSE m->'chunks'->index->>'digest' END;
  expected_format:=CASE WHEN index=part_count THEN 'OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1' ELSE 'OPENPC_RUNTIME_ARTIFACT_CHUNK_V1' END;
  SELECT c.* INTO STRICT original FROM control.evidence_catalogue c
   JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
   JOIN control.evidence_segment_payload body USING(participant_id,privacy_domain_id,stream_id,segment_id)
   WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
    AND c.stream_id=NEW.stream_id AND c.record_id=expected_id
    AND c.evidence_class='EFFECT' AND c.source_format=expected_format AND c.receipt_digest=expected_digest
    AND c.occurred_at=native.created_at AND c.sequence BETWEEN s.first_sequence AND s.through_sequence
    AND s.object_digest='sha256:'||encode(sha256(body.encrypted_segment),'hex')
    AND (NEW.source_pending_original IS NULL OR (c.xmin=pg_current_xact_id()::xid AND s.xmin=pg_current_xact_id()::xid AND body.xmin=pg_current_xact_id()::xid));
  IF original.sequence<=previous_sequence THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  previous_sequence:=original.sequence;
 END LOOP;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS runtime_artifact_archive_guard ON control.evidence_runtime_artifact_archive;
CREATE TRIGGER runtime_artifact_archive_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_runtime_artifact_archive
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_runtime_artifact_archive();
REVOKE ALL ON FUNCTION openpc.guard_runtime_artifact_archive() FROM PUBLIC;
ALTER FUNCTION openpc.guard_runtime_artifact_archive() OWNER TO openpc_control_owner;

CREATE OR REPLACE FUNCTION openpc.index_runtime_artifact_archive_parts()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE item jsonb; index integer:=0;
BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements(NEW.manifest->'chunks') LOOP
  INSERT INTO control.evidence_runtime_artifact_archive_part(participant_id,privacy_domain_id,stream_id,manifest_record_id,ordinal,record_id)
   VALUES(NEW.participant_id,NEW.privacy_domain_id,NEW.stream_id,NEW.record_id,index,item->>'recordId');
  index:=index+1;
 END LOOP;
 INSERT INTO control.evidence_runtime_artifact_archive_part(participant_id,privacy_domain_id,stream_id,manifest_record_id,ordinal,record_id)
  VALUES(NEW.participant_id,NEW.privacy_domain_id,NEW.stream_id,NEW.record_id,index,NEW.record_id);
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.index_runtime_artifact_archive_parts() FROM PUBLIC;
DROP TRIGGER IF EXISTS runtime_artifact_archive_parts ON control.evidence_runtime_artifact_archive;
CREATE TRIGGER runtime_artifact_archive_parts AFTER INSERT ON control.evidence_runtime_artifact_archive
 FOR EACH ROW EXECUTE FUNCTION openpc.index_runtime_artifact_archive_parts();
CREATE OR REPLACE FUNCTION openpc.guard_runtime_artifact_archive_part()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE parent control.evidence_runtime_artifact_archive; expected text; count_parts integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-EVIDENCE_EXPORT_RECORDS-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT parent FROM control.evidence_runtime_artifact_archive WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND stream_id=NEW.stream_id AND record_id=NEW.manifest_record_id;
 count_parts:=jsonb_array_length(parent.manifest->'chunks');
 expected:=CASE WHEN NEW.ordinal=count_parts THEN parent.record_id ELSE parent.manifest->'chunks'->NEW.ordinal->>'recordId' END;
 IF expected IS NULL OR NEW.record_id IS DISTINCT FROM expected OR NEW.ordinal<0 OR NEW.ordinal>count_parts THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_runtime_artifact_archive_part() FROM PUBLIC;
DROP TRIGGER IF EXISTS runtime_artifact_archive_part_guard ON control.evidence_runtime_artifact_archive_part;
CREATE TRIGGER runtime_artifact_archive_part_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_runtime_artifact_archive_part
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_runtime_artifact_archive_part();

CREATE OR REPLACE FUNCTION openpc.runtime_artifact_archive_hold_metadata(source control.evidence_catalogue)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE identity jsonb;
BEGIN
 SELECT a.manifest->'identity' INTO STRICT identity FROM control.evidence_runtime_artifact_archive a
  JOIN control.evidence_runtime_artifact_archive_part part ON part.participant_id=a.participant_id AND part.privacy_domain_id=a.privacy_domain_id
   AND part.stream_id=a.stream_id AND part.manifest_record_id=a.record_id
  JOIN control.evidence_catalogue c ON c.participant_id=part.participant_id AND c.privacy_domain_id=part.privacy_domain_id
   AND c.stream_id=part.stream_id AND c.record_id=part.record_id
  WHERE c IS NOT DISTINCT FROM source AND a.manifest_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(a.manifest),'UTF8')),'hex');
 -- Module configuration is not a runtime generation. Preserve unknown
 -- cross-owner lineage; metadata cannot declare those references absent.
 RETURN jsonb_build_object('unresolvedReferences',true);
EXCEPTION WHEN no_data_found OR too_many_rows OR insufficient_privilege THEN RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_archive_hold_metadata(control.evidence_catalogue) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_archive_hold_metadata(control.evidence_catalogue)
 TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.runtime_artifact_archive_coverage(pid uuid,privacy uuid,stream text,record_ref text,sinks text[])
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE a control.evidence_runtime_artifact_archive; object record; checkpoint control.evidence_checkpoint;
 sink text; receipts jsonb; objects jsonb:='[]'; original_count integer; pending jsonb;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF pid IS DISTINCT FROM openpc.current_participant_id() OR privacy IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR sinks IS NULL OR cardinality(sinks) NOT BETWEEN 1 AND 8 OR array_position(sinks,NULL) IS NOT NULL
  OR cardinality(sinks)<>(SELECT count(DISTINCT value) FROM unnest(sinks) value)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.evidence_runtime_artifact_archive WHERE participant_id=pid
  AND privacy_domain_id=privacy AND stream_id=stream AND record_id=record_ref;
 pending:=jsonb_build_object('state','PENDING','authority','NONE','manifestDigest',a.manifest_digest);
 SELECT count(*) INTO original_count FROM control.evidence_runtime_artifact_archive_part part
  JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  WHERE part.participant_id=pid AND part.privacy_domain_id=privacy AND part.stream_id=stream AND part.manifest_record_id=record_ref;
 IF original_count<>jsonb_array_length(a.manifest->'chunks')+1 THEN RETURN pending; END IF;
 FOR object IN SELECT DISTINCT s.segment_id,s.object_digest,s.first_sequence,s.through_sequence
  FROM control.evidence_runtime_artifact_archive_part part JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
  WHERE part.participant_id=pid AND part.privacy_domain_id=privacy AND part.stream_id=stream AND part.manifest_record_id=record_ref
  ORDER BY s.first_sequence LOOP
  receipts:='[]';
  FOREACH sink IN ARRAY sinks LOOP
   SELECT * INTO checkpoint FROM control.evidence_checkpoint c WHERE c.participant_id=pid AND c.privacy_domain_id=privacy
    AND c.stream_id=stream AND c.segment_id=object.segment_id AND c.object_digest=object.object_digest
    AND c.through_sequence=object.through_sequence AND c.sink_id=sink;
   IF NOT FOUND THEN RETURN pending; END IF;
   IF checkpoint.receipt->>'kind'='SIGNED_REMOTE_ARCHIVE_V1' THEN
    IF NOT openpc.remote_archive_covers(pid,privacy,stream,object.segment_id,sink) THEN RETURN pending; END IF;
   ELSIF EXISTS(SELECT 1 FROM control.retention_hold h WHERE h.participant_id=pid
     AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=privacy)
     AND openpc.evidence_hold_requires_coverage(h,stream,object.segment_id)
     AND NOT EXISTS(SELECT 1 FROM control.evidence_hold_coverage c WHERE c.participant_id=pid AND c.privacy_domain_id=privacy
       AND c.retention_hold_id=h.retention_hold_id AND c.hold_revision=h.revision AND c.stream_id=stream
       AND c.segment_id=object.segment_id AND c.object_digest=object.object_digest AND c.sink_id=sink))
   THEN RETURN pending; END IF;
   receipts:=receipts||jsonb_build_array(jsonb_build_object('sinkId',sink,'checkpointDigest',checkpoint.checkpoint_digest,'receiptDigest',checkpoint.receipt_digest));
  END LOOP;
  objects:=objects||jsonb_build_array(jsonb_build_object('segmentId',object.segment_id::text,'objectDigest',object.object_digest,
   'firstSequence',object.first_sequence::text,'throughSequence',object.through_sequence::text,'sinkReceipts',receipts));
 END LOOP;
 IF jsonb_array_length(objects)=0 THEN RETURN pending; END IF;
 RETURN jsonb_build_object('state','COMPLETE','authority','NONE','manifestDigest',a.manifest_digest,'segments',objects);
END $$;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_archive_coverage(uuid,uuid,text,text,text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_archive_coverage(uuid,uuid,text,text,text[])
 TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;


ALTER TABLE control.fleet_fact_admission_inbox FORCE ROW LEVEL SECURITY;
ALTER TABLE control.fleet_fact_admission_cursor FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.fleet_fact_admission_key,control.fleet_fact_admission_inbox,control.fleet_fact_admission_cursor
 FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.fleet_fact_admission_inbox,control.fleet_fact_admission_cursor TO openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.fleet_fact_admission_key TO openpc_control_owner;
GRANT SELECT,INSERT ON control.fleet_fact_admission_inbox TO openpc_control_owner;
GRANT SELECT,INSERT,UPDATE ON control.fleet_fact_admission_cursor TO openpc_control_owner;
DROP POLICY IF EXISTS fleet_fact_native_owner ON control.fleet_fact_admission_inbox;
CREATE POLICY fleet_fact_native_owner ON control.fleet_fact_admission_inbox TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id))
 WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id));
DROP POLICY IF EXISTS fleet_fact_native_owner ON control.fleet_fact_admission_cursor;
CREATE POLICY fleet_fact_native_owner ON control.fleet_fact_admission_cursor TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id))
 WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id));


CREATE OR REPLACE FUNCTION openpc.commit_fleet_fact_admission(material bytea,nonce bytea,mac bytea)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE m jsonb; e jsonb; p uuid; d uuid; c uuid; g uuid; event uuid; kind text; n numeric;
 secret bytea; expected bytea; different integer:=0; prior bytea; head numeric;

BEGIN
 PERFORM openpc.assert_request_context(true);
 IF material IS NULL OR nonce IS NULL OR mac IS NULL
  OR current_setting('openpc.action_intent_id')<>'ACT-OPERATIONS_READ_OPERATION-V1'
  OR octet_length(material) NOT BETWEEN 1 AND 16384 OR octet_length(nonce)<>32 OR octet_length(mac)<>32

 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.fleet_fact_admission_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_FLEET_FACT_ADMISSION_V1','UTF8')||sha256(material)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 m:=convert_from(material,'UTF8')::jsonb;
 p:=(m->>'participantId')::uuid; d:=(m->>'privacyDomainId')::uuid;
 c:=(m->>'candidateId')::uuid; g:=(m->>'generationId')::uuid;
 e:=m->'envelope'; event:=(e->>'id')::uuid; kind:=m->>'factType'; n:=(m->>'sequence')::numeric;
 IF p IS DISTINCT FROM openpc.current_participant_id() OR d IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR m IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,
    'candidateId',c::text,'generationId',g::text,'factType',kind,'sequence',n::text,'envelope',e,
    'factDigest',m->>'factDigest','signedFactDigest',m->>'signedFactDigest','consumerId','LS-FLEET-CONTROL')
  OR convert_from(material,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(m)
  OR e->>'subject' IS DISTINCT FROM 'urn:openpc:resource:'||c::text
  OR e->>'participantid' IS DISTINCT FROM 'urn:openpc:participant:'||p::text
  OR e->>'privacydomainid' IS DISTINCT FROM 'urn:openpc:privacy-domain:'||d::text
  OR e->>'source' IS DISTINCT FROM 'urn:openpc:service:LS-FACT-BRIDGE'
  OR e->>'type' IS DISTINCT FROM 'io.openpc.fact.candidate.admitted.v1'
  OR e->>'sequence' IS DISTINCT FROM n::text
 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-BINDING'; END IF;

 INSERT INTO control.fleet_fact_admission_cursor(participant_id,privacy_domain_id,fact_type)
  VALUES(p,d,kind) ON CONFLICT DO NOTHING;
 SELECT sequence INTO STRICT head FROM control.fleet_fact_admission_cursor
  WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind FOR UPDATE;
 SELECT i.material INTO prior FROM control.fleet_fact_admission_inbox i
  WHERE i.participant_id=p AND i.privacy_domain_id=d AND i.event_id=event;
 IF FOUND THEN
  IF prior<>material THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-CONFLICT'; END IF;
  RETURN false;
 END IF;
 RAISE EXCEPTION 'PC-AUTH-0005'; -- V1 remains exact historical replay only.
 IF n<>head+1 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-GAP'; END IF;
 INSERT INTO control.fleet_fact_admission_inbox(participant_id,privacy_domain_id,event_id,candidate_id,generation_id,
  fact_type,sequence,fact_digest,signed_fact_digest,material,material_digest,commit_nonce,consumer_profile_digest)
 VALUES(p,d,event,c,g,kind,n,m->>'factDigest',m->>'signedFactDigest',material,sha256(material),nonce,NULL);
 UPDATE control.fleet_fact_admission_cursor SET sequence=n WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind;
 RETURN true;
END $$;
ALTER FUNCTION openpc.commit_fleet_fact_admission(bytea,bytea,bytea) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.commit_fleet_fact_admission(bytea,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.commit_fleet_fact_admission(bytea,bytea,bytea) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.commit_fleet_fact_admission_v2(material bytea,nonce bytea,mac bytea,wanted_profile text)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE m jsonb; e jsonb; p uuid; d uuid; c uuid; g uuid; event uuid; kind text; n numeric;
 secret bytea; expected bytea; different integer:=0; prior bytea; head numeric;
 installed control.fact_consumer_profile; pending control.fleet_fact_delivery; expected_pending jsonb; lease uuid;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF material IS NULL OR nonce IS NULL OR mac IS NULL
  OR current_setting('openpc.action_intent_id')<>'ACT-OPERATIONS_READ_OPERATION-V1'
  OR octet_length(material) NOT BETWEEN 1 AND 16384 OR octet_length(nonce)<>32 OR octet_length(mac)<>32
  OR coalesce(wanted_profile,'')!~'^sha256:[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.fleet_fact_admission_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_FLEET_FACT_ADMISSION_V2','UTF8')||decode(substring(wanted_profile from 8),'hex')||sha256(material)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 m:=convert_from(material,'UTF8')::jsonb;
 p:=(m->>'participantId')::uuid; d:=(m->>'privacyDomainId')::uuid;
 c:=(m->>'candidateId')::uuid; g:=(m->>'generationId')::uuid;
 e:=m->'envelope'; event:=(e->>'id')::uuid; kind:=m->>'factType'; n:=(m->>'sequence')::numeric;
 IF p IS DISTINCT FROM openpc.current_participant_id() OR d IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR m IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,
    'candidateId',c::text,'generationId',g::text,'factType',kind,'sequence',n::text,'envelope',e,
    'factDigest',m->>'factDigest','signedFactDigest',m->>'signedFactDigest','consumerId','LS-FLEET-CONTROL')
  OR convert_from(material,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(m)
  OR e->>'subject' IS DISTINCT FROM 'urn:openpc:resource:'||c::text
  OR e->>'participantid' IS DISTINCT FROM 'urn:openpc:participant:'||p::text
  OR e->>'privacydomainid' IS DISTINCT FROM 'urn:openpc:privacy-domain:'||d::text
  OR e->>'source' IS DISTINCT FROM 'urn:openpc:service:LS-FACT-BRIDGE'
  OR e->>'type' IS DISTINCT FROM 'io.openpc.fact.candidate.admitted.v1'
  OR e->>'sequence' IS DISTINCT FROM n::text
 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-BINDING'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('fact-consumer-profile:'||p::text||':'||d::text||':LS-FLEET-CONTROL',0));
 INSERT INTO control.fleet_fact_admission_cursor(participant_id,privacy_domain_id,fact_type)
  VALUES(p,d,kind) ON CONFLICT DO NOTHING;
 SELECT sequence INTO STRICT head FROM control.fleet_fact_admission_cursor
  WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind FOR UPDATE;
 SELECT i.material INTO prior FROM control.fleet_fact_admission_inbox i
  WHERE i.participant_id=p AND i.privacy_domain_id=d AND i.event_id=event;
 IF FOUND THEN
  IF prior<>material THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-CONFLICT'; END IF;
  RETURN false;
 END IF;
 installed:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 IF installed.profile_digest IS DISTINCT FROM wanted_profile THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 lease:=encode(substring(nonce from 1 for 16),'hex')::uuid;
 SELECT * INTO STRICT pending FROM control.fleet_fact_delivery WHERE participant_id=p AND privacy_domain_id=d AND event_id=event FOR UPDATE;
 expected_pending:=jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,'eventId',event::text,
  'candidateId',c::text,'generationId',g::text,'factType',kind,'sequence',n::text,'consumerId','LS-FLEET-CONTROL',
  'envelope',e,'envelopeDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(e),'UTF8')),'hex'),
  'dataDigest',e->>'datadigest');
 IF pending.state<>'LEASED' OR pending.lease_id IS DISTINCT FROM lease
  OR convert_from(pending.material,'UTF8')::jsonb IS DISTINCT FROM expected_pending
  OR NOT EXISTS(SELECT 1 FROM control.fleet_fact_delivery_attempt a WHERE a.participant_id=p AND a.privacy_domain_id=d
   AND a.event_id=event AND a.lease_id=lease AND a.profile_digest=wanted_profile AND a.outcome='ACTIVE')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.close_fleet_delivery_lease(event,lease,'COMMITTED',NULL);
 IF n<>head+1 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-GAP'; END IF;
 INSERT INTO control.fleet_fact_admission_inbox(participant_id,privacy_domain_id,event_id,candidate_id,generation_id,
  fact_type,sequence,fact_digest,signed_fact_digest,material,material_digest,commit_nonce,consumer_profile_digest)
 VALUES(p,d,event,c,g,kind,n,m->>'factDigest',m->>'signedFactDigest',material,sha256(material),nonce,wanted_profile);
 UPDATE control.fleet_fact_admission_cursor SET sequence=n WHERE participant_id=p AND privacy_domain_id=d AND fact_type=kind;
 RETURN true;
END $$;
ALTER FUNCTION openpc.commit_fleet_fact_admission_v2(bytea,bytea,bytea,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.commit_fleet_fact_admission_v2(bytea,bytea,bytea,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.commit_fleet_fact_admission_v2(bytea,bytea,bytea,text) TO openpc_control_worker;



CREATE OR REPLACE FUNCTION openpc.guard_fact_consumer_profile()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE c jsonb; expected jsonb; previous control.fact_consumer_profile; issuer text;
BEGIN
 IF TG_OP<>'INSERT' OR NOT (current_user='openpc_control_owner' OR pg_has_role(current_user,'openpc_control_key_governor','USAGE'))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('fact-consumer-profile:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text||':'||NEW.consumer_id,0));
 SELECT * INTO previous FROM control.fact_consumer_profile WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND consumer_id=NEW.consumer_id ORDER BY revision DESC LIMIT 1;
 IF NEW.revision<>coalesce(previous.revision,0)+1 OR (previous.revision IS NOT NULL AND
   (NEW.profile_id IS DISTINCT FROM previous.profile_id OR NEW.claims->>'environmentId' IS DISTINCT FROM previous.claims->>'environmentId'))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 c:=NEW.claims; issuer:='sha256:'||encode(sha256(NEW.issuer_spki),'hex');
 expected:=jsonb_build_object('environmentId',c->'environmentId','participantId',NEW.participant_id::text,
  'privacyDomainId',NEW.privacy_domain_id::text,'profileId',NEW.profile_id,'revision',NEW.revision::text,
  'consumerId',NEW.consumer_id,'subscriptionId',CASE NEW.consumer_id WHEN 'LS-CONTROL-WORK' THEN 'SUB-FACTCANDIDATEADMITTED-CONTROL_WORK-V1' WHEN 'LS-FLEET-CONTROL' THEN 'SUB-FACTCANDIDATEADMITTED-FLEET_CONTROL-V1' END,
  'validFromMs',c->'validFromMs','validUntilMs',c->'validUntilMs','issuerKeyId',issuer,
  'workloadCredentialId',NEW.workload_credential_id::text,'workloadCredentialEpoch',NEW.workload_credential_epoch::text,
  'databaseRole',NEW.database_role,'maximumAttempts',c->'maximumAttempts','initialBackoffMs',c->'initialBackoffMs','maximumBackoffMs',c->'maximumBackoffMs');
 IF c IS DISTINCT FROM expected OR jsonb_typeof(c->'environmentId') IS DISTINCT FROM 'string'
  OR coalesce(c->>'environmentId','')!~'^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
  OR NEW.profile_id!~'^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
  OR NOT (NEW.database_role~'^[a-z_][a-z0-9_]{0,62}$' OR (
    NEW.participant_id::text~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    AND NEW.privacy_domain_id::text~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    AND NEW.database_role='openpc_rs_login_'||translate(rtrim(encode(sha256(convert_to(
      '["openpc:runtime-source-scope:v1","'||NEW.participant_id::text||'","'||NEW.privacy_domain_id::text||'"]',
      'UTF8')),'base64'),'='),'+/','-_')))
  OR encode(NEW.issuer_spki,'hex')!~'^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$'
  OR substring(NEW.workload_credential_id::text from 15 for 1)<>'7'
  OR EXISTS(SELECT 1 FROM jsonb_each(c) e WHERE e.key IN ('validFromMs','validUntilMs','maximumAttempts','initialBackoffMs','maximumBackoffMs')
    AND (jsonb_typeof(e.value)<>'number' OR (e.value#>>'{}')!~'^(0|[1-9][0-9]*)$'))
  OR (c->>'validFromMs')::numeric<0 OR (c->>'validUntilMs')::numeric>9007199254740991
  OR (c->>'validUntilMs')::numeric<=(c->>'validFromMs')::numeric
  OR (c->>'maximumAttempts')::numeric NOT BETWEEN 1 AND 1000
  OR (c->>'initialBackoffMs')::numeric NOT BETWEEN 1 AND 3600000
  OR (c->>'maximumBackoffMs')::numeric NOT BETWEEN (c->>'initialBackoffMs')::numeric AND 3600000
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object('0',openpc.business_bytes(decode('60c93313ff9d2ead84868b1af9d8d2b469b97f3b4eabbed3d6df6a5f4bd5395d','hex')),
  '1',c->'environmentId','2',openpc.business_uuid(NEW.participant_id),'3',openpc.business_uuid(NEW.privacy_domain_id),
  '4',NEW.profile_id,'5',NEW.revision,'6',NEW.consumer_id,'7',c->'subscriptionId',
  '8',(c->>'validFromMs')::numeric,'9',(c->>'validUntilMs')::numeric,'10',openpc.business_bytes(sha256(NEW.issuer_spki)),
  '11',openpc.business_uuid(NEW.workload_credential_id),'12',NEW.workload_credential_epoch,
  '13',NEW.database_role,'14',(c->>'maximumAttempts')::numeric,'15',(c->>'initialBackoffMs')::numeric,'16',(c->>'maximumBackoffMs')::numeric);
 IF openpc.business_cbor(NEW.payload) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.archive_cose_binding(NEW.payload,NEW.cose,issuer,24006,343);
 PERFORM 1 FROM pg_catalog.pg_roles WHERE rolname=NEW.database_role AND rolcanlogin AND NOT rolsuper AND NOT rolbypassrls
  AND pg_has_role(rolname,'openpc_control_worker','USAGE');
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 NEW.admitted_at:=clock_timestamp(); RETURN NEW;
END $$;
ALTER TABLE control.fact_consumer_profile FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.fact_consumer_profile FROM PUBLIC,openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT SELECT,INSERT ON control.fact_consumer_profile TO openpc_control_owner,openpc_control_key_governor;
GRANT SELECT ON control.fact_consumer_profile TO openpc_control_worker;
DROP POLICY IF EXISTS fact_consumer_installation ON control.fact_consumer_profile;
CREATE POLICY fact_consumer_installation ON control.fact_consumer_profile TO openpc_control_owner,openpc_control_key_governor USING(true) WITH CHECK(true);
DROP TRIGGER IF EXISTS fact_consumer_installation ON control.fact_consumer_profile;
CREATE TRIGGER fact_consumer_installation BEFORE INSERT OR UPDATE OR DELETE ON control.fact_consumer_profile
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_fact_consumer_profile();

CREATE OR REPLACE FUNCTION openpc.require_fact_consumer_profile(wanted_consumer text)
RETURNS control.fact_consumer_profile LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE p control.fact_consumer_profile; now_ms numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR openpc.current_action_intent_id()<>'ACT-OPERATIONS_READ_OPERATION-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('fact-consumer-profile:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text||':'||wanted_consumer,0));
 SELECT * INTO STRICT p FROM control.fact_consumer_profile WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND consumer_id=wanted_consumer ORDER BY revision DESC LIMIT 1;
 now_ms:=floor(extract(epoch FROM clock_timestamp())*1000);
 IF session_user<>p.database_role OR now_ms<(p.claims->>'validFromMs')::numeric OR now_ms>=(p.claims->>'validUntilMs')::numeric
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.participant v WHERE v.participant_id=p.participant_id AND v.state='ACTIVE' AND v.archived_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.privacy_domain v WHERE v.participant_id=p.participant_id AND v.privacy_domain_id=p.privacy_domain_id AND v.state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.credential c JOIN control.principal w USING(participant_id,principal_id)
  WHERE c.participant_id=p.participant_id AND c.credential_id=p.workload_credential_id AND c.credential_epoch=p.workload_credential_epoch
   AND c.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC') AND c.state='ACTIVE' AND w.kind='WORKLOAD' AND w.state='ACTIVE'
   AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
   AND c.public_key_digest IS DISTINCT FROM sha256(p.issuer_spki) FOR SHARE OF c,w;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN p;
END $$;
ALTER FUNCTION openpc.require_fact_consumer_profile(text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.require_fact_consumer_profile(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.require_fact_consumer_profile(text) TO openpc_control_worker;

DROP POLICY IF EXISTS fact_consumer_workload_fence ON control.participant;
CREATE POLICY fact_consumer_workload_fence ON control.participant FOR ALL TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.current_action_intent_id()='ACT-OPERATIONS_READ_OPERATION-V1') WITH CHECK(false);

DROP POLICY IF EXISTS fact_consumer_workload_fence ON control.privacy_domain;
CREATE POLICY fact_consumer_workload_fence ON control.privacy_domain FOR ALL TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.current_action_intent_id()='ACT-OPERATIONS_READ_OPERATION-V1') WITH CHECK(false);

DROP POLICY IF EXISTS fact_consumer_workload_fence ON control.principal;
CREATE POLICY fact_consumer_workload_fence ON control.principal FOR ALL TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.current_action_intent_id()='ACT-OPERATIONS_READ_OPERATION-V1') WITH CHECK(false);

DROP POLICY IF EXISTS fact_consumer_workload_fence ON control.credential;
CREATE POLICY fact_consumer_workload_fence ON control.credential FOR ALL TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.current_action_intent_id()='ACT-OPERATIONS_READ_OPERATION-V1') WITH CHECK(false);


CREATE OR REPLACE FUNCTION openpc.verify_fleet_delivery_capability(material bytea,nonce bytea,mac bytea,profile_digest text,purpose text)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE secret bytea; expected bytea; difference integer:=0; value jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF material IS NULL OR nonce IS NULL OR mac IS NULL OR octet_length(material) NOT BETWEEN 1 AND 65536
  OR octet_length(nonce)<>32 OR octet_length(mac)<>32 OR coalesce(profile_digest,'')!~'^sha256:[0-9a-f]{64}$'
  OR openpc.current_action_intent_id()<>'ACT-OPERATIONS_READ_OPERATION-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.fleet_fact_admission_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to(purpose,'UTF8')||decode(substring(profile_digest from 8),'hex')||sha256(material)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP difference:=difference | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF difference<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 value:=convert_from(material,'UTF8')::jsonb;
 IF convert_from(material,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(value)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN value;
END $$;
ALTER FUNCTION openpc.verify_fleet_delivery_capability(bytea,bytea,bytea,text,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.verify_fleet_delivery_capability(bytea,bytea,bytea,text,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.fleet_delivery_retry_delay(failures integer,initial_ms integer,maximum_ms integer)
RETURNS bigint LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT least(maximum_ms::bigint,initial_ms::bigint*(1::bigint<<least(greatest(failures-1,0),32)))
$$;

CREATE OR REPLACE FUNCTION openpc.close_fleet_delivery_lease(wanted_event uuid,wanted_lease uuid,result text,problem text)
RETURNS text LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE d control.fleet_fact_delivery; a control.fleet_fact_delivery_attempt; now_ms numeric; failures integer; next_state text;
BEGIN
 SELECT * INTO STRICT d FROM control.fleet_fact_delivery WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=wanted_event FOR UPDATE;
 SELECT * INTO STRICT a FROM control.fleet_fact_delivery_attempt WHERE participant_id=d.participant_id
  AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id AND lease_id=wanted_lease;
 IF a.outcome<>'ACTIVE' THEN
  IF a.outcome IS DISTINCT FROM result OR a.problem IS DISTINCT FROM problem THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  RETURN d.state;
 END IF;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF d.state<>'LEASED' OR d.lease_id IS DISTINCT FROM wanted_lease
  OR result NOT IN ('FAILED','LEASE_EXPIRED','CAPACITY_RELEASE','UNAVAILABLE_RELEASE','COMMITTED')
  OR (result='LEASE_EXPIRED' AND d.lease_until_ms>now_ms)
  OR (result<>'LEASE_EXPIRED' AND d.lease_until_ms<=now_ms)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 failures:=d.failed_attempts+CASE WHEN result IN ('FAILED','LEASE_EXPIRED') THEN 1 ELSE 0 END;
 next_state:=CASE WHEN result='COMMITTED' THEN 'COMMITTED' WHEN failures>=d.maximum_attempts THEN 'EXHAUSTED' ELSE 'WAITING' END;
 UPDATE control.fleet_fact_delivery_attempt SET outcome=result,ended_at_ms=now_ms,problem=close_fleet_delivery_lease.problem
  WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id AND lease_id=wanted_lease;
 UPDATE control.fleet_fact_delivery SET failed_attempts=failures,state=next_state,lease_id=NULL,lease_until_ms=NULL,
  next_attempt_ms=now_ms+openpc.fleet_delivery_retry_delay(failures,d.initial_backoff_ms,d.maximum_backoff_ms),last_problem=problem
  WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id;
 RETURN next_state;
END $$;
ALTER FUNCTION openpc.close_fleet_delivery_lease(uuid,uuid,text,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.close_fleet_delivery_lease(uuid,uuid,text,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.begin_fleet_fact_delivery(material bytea,nonce bytea,mac bytea,wanted_profile text)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE request jsonb; e jsonb; p uuid; v uuid; event uuid; candidate uuid; generation uuid; lease uuid; kind text;
 n numeric; head numeric; now_ms numeric; until_ms numeric; original bytea;
 profile control.fact_consumer_profile; d control.fleet_fact_delivery;
BEGIN
 request:=openpc.verify_fleet_delivery_capability(material,nonce,mac,wanted_profile,'OPENPC_FLEET_FACT_DELIVERY_BEGIN_V1');
 e:=request->'event'; lease:=(request->>'leaseId')::uuid;
 p:=(e->>'participantId')::uuid; v:=(e->>'privacyDomainId')::uuid; event:=(e->>'eventId')::uuid;
 candidate:=(e->>'candidateId')::uuid; generation:=(e->>'generationId')::uuid;
 kind:=e->>'factType'; n:=(e->>'sequence')::numeric;
 IF request IS DISTINCT FROM jsonb_build_object('event',e,'leaseId',lease::text)
  OR p IS DISTINCT FROM openpc.current_participant_id() OR v IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR e IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',v::text,'eventId',event::text,
    'candidateId',candidate::text,'generationId',generation::text,'factType',kind,'sequence',n::text,
    'consumerId','LS-FLEET-CONTROL','envelope',e->'envelope','envelopeDigest',e->>'envelopeDigest','dataDigest',e->>'dataDigest')
  OR lease IS NULL OR substring(lease::text from 15 for 1)<>'7'
  OR kind NOT IN ('CONTRACT_STATE_CALL','RELATIONSHIP','EXTERNAL_DECISION') OR n<1 OR n>9223372036854775807
  OR e->>'envelopeDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(e->'envelope'),'UTF8')),'hex')
  OR coalesce(e->>'dataDigest','')!~'^sha256:[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 IF profile.profile_digest IS DISTINCT FROM wanted_profile THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 INSERT INTO control.fleet_fact_admission_cursor(participant_id,privacy_domain_id,fact_type) VALUES(p,v,kind) ON CONFLICT DO NOTHING;
 SELECT sequence INTO STRICT head FROM control.fleet_fact_admission_cursor WHERE participant_id=p AND privacy_domain_id=v AND fact_type=kind FOR UPDATE;
 IF n<=head THEN
  IF EXISTS(SELECT 1 FROM control.fleet_fact_admission_inbox i WHERE i.participant_id=p AND i.privacy_domain_id=v
    AND i.event_id=event AND i.candidate_id=candidate AND i.generation_id=generation AND i.fact_type=kind AND i.sequence=n
    AND convert_from(i.material,'UTF8')::jsonb->'envelope'=e->'envelope')
  THEN RETURN jsonb_build_object('state','COMMITTED'); END IF;
  RAISE EXCEPTION 'PC-DATA-6007';
 END IF;
 IF n<>head+1 THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-GAP'; END IF;
 original:=convert_to(openpc.signing_canonical_json(e),'UTF8');
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 INSERT INTO control.fleet_fact_delivery(participant_id,privacy_domain_id,event_id,candidate_id,generation_id,fact_type,sequence,
  material,material_digest,initial_profile_digest,maximum_attempts,initial_backoff_ms,maximum_backoff_ms,next_attempt_ms)
 VALUES(p,v,event,candidate,generation,kind,n,original,sha256(original),wanted_profile,
  (profile.claims->>'maximumAttempts')::integer,(profile.claims->>'initialBackoffMs')::integer,
  (profile.claims->>'maximumBackoffMs')::integer,now_ms) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT d FROM control.fleet_fact_delivery WHERE participant_id=p AND privacy_domain_id=v AND event_id=event FOR UPDATE;
 IF d.material IS DISTINCT FROM original THEN RAISE EXCEPTION 'DATA-6021-FLEET-FACT-CONFLICT'; END IF;
 IF d.state='LEASED' THEN
  IF d.lease_until_ms<=now_ms THEN
   PERFORM openpc.close_fleet_delivery_lease(event,d.lease_id,'LEASE_EXPIRED','PC-DATA-6005');
   SELECT * INTO STRICT d FROM control.fleet_fact_delivery WHERE participant_id=p AND privacy_domain_id=v AND event_id=event;
  ELSIF d.lease_id=lease THEN
   RETURN jsonb_build_object('state','LEASED','leaseId',lease::text,'leaseUntilMs',d.lease_until_ms::text);
  ELSE RETURN jsonb_build_object('state','BUSY'); END IF;
 END IF;
 IF d.state='WAITING' AND (profile.claims->>'maximumAttempts')::integer<d.maximum_attempts THEN
  UPDATE control.fleet_fact_delivery SET maximum_attempts=greatest(d.failed_attempts,(profile.claims->>'maximumAttempts')::integer),
   state=CASE WHEN d.failed_attempts>=(profile.claims->>'maximumAttempts')::integer THEN 'EXHAUSTED' ELSE 'WAITING' END
   WHERE participant_id=p AND privacy_domain_id=v AND event_id=event;
  SELECT * INTO STRICT d FROM control.fleet_fact_delivery WHERE participant_id=p AND privacy_domain_id=v AND event_id=event;
 END IF;
 IF d.state IN ('EXHAUSTED','QUARANTINED','COMMITTED') THEN RETURN jsonb_build_object('state',d.state); END IF;
 IF d.next_attempt_ms>now_ms THEN RETURN jsonb_build_object('state','WAITING','nextAttemptMs',d.next_attempt_ms::text); END IF;
 until_ms:=least(now_ms+30000,(profile.claims->>'validUntilMs')::numeric);
 INSERT INTO control.fleet_fact_delivery_attempt(participant_id,privacy_domain_id,event_id,lease_generation,lease_id,profile_digest,started_at_ms,lease_until_ms)
 VALUES(p,v,event,d.lease_generation+1,lease,wanted_profile,now_ms,until_ms);
 UPDATE control.fleet_fact_delivery SET state='LEASED',lease_id=lease,lease_until_ms=until_ms,lease_generation=d.lease_generation+1
 WHERE participant_id=p AND privacy_domain_id=v AND event_id=event;
 RETURN jsonb_build_object('state','LEASED','leaseId',lease::text,'leaseUntilMs',until_ms::text);
END $$;
ALTER FUNCTION openpc.begin_fleet_fact_delivery(bytea,bytea,bytea,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.begin_fleet_fact_delivery(bytea,bytea,bytea,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.begin_fleet_fact_delivery(bytea,bytea,bytea,text) TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.fail_fleet_fact_delivery(material bytea,nonce bytea,mac bytea,wanted_profile text)
RETURNS text LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE request jsonb; p uuid; v uuid; event uuid; lease uuid; result text; problem text; profile control.fact_consumer_profile;
BEGIN
 request:=openpc.verify_fleet_delivery_capability(material,nonce,mac,wanted_profile,'OPENPC_FLEET_FACT_DELIVERY_FAIL_V1');
 p:=(request->>'participantId')::uuid; v:=(request->>'privacyDomainId')::uuid;
 event:=(request->>'eventId')::uuid; lease:=(request->>'leaseId')::uuid;
 result:=request->>'outcome'; problem:=request->>'problem';
 IF request IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',v::text,'eventId',event::text,'leaseId',lease::text,'outcome',result,'problem',problem)
  OR p IS DISTINCT FROM openpc.current_participant_id() OR v IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR result IS NULL OR problem IS NULL OR result NOT IN ('FAILED','CAPACITY_RELEASE','UNAVAILABLE_RELEASE') OR problem<>'PC-DATA-6005'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 IF profile.profile_digest IS DISTINCT FROM wanted_profile THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.fleet_fact_delivery_attempt WHERE participant_id=p AND privacy_domain_id=v AND event_id=event
  AND lease_id=lease AND profile_digest=wanted_profile;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN openpc.close_fleet_delivery_lease(event,lease,result,problem);
END $$;
ALTER FUNCTION openpc.fail_fleet_fact_delivery(bytea,bytea,bytea,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.fail_fleet_fact_delivery(bytea,bytea,bytea,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.fail_fleet_fact_delivery(bytea,bytea,bytea,text) TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.guard_fleet_delivery_history()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF TG_OP='UPDATE' THEN
  IF TG_TABLE_NAME='fleet_fact_delivery_attempt' THEN
   IF OLD.outcome<>'ACTIVE' OR NEW.outcome='ACTIVE'
    OR to_jsonb(NEW)-ARRAY['outcome','ended_at_ms','problem'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['outcome','ended_at_ms','problem']
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  ELSE
   IF to_jsonb(NEW)-ARRAY['failed_attempts','lease_generation','state','lease_id','lease_until_ms','next_attempt_ms','last_problem','maximum_attempts']
    IS DISTINCT FROM to_jsonb(OLD)-ARRAY['failed_attempts','lease_generation','state','lease_id','lease_until_ms','next_attempt_ms','last_problem','maximum_attempts']
    OR NEW.maximum_attempts>OLD.maximum_attempts
    OR NEW.failed_attempts NOT BETWEEN OLD.failed_attempts AND OLD.failed_attempts+1
    OR NEW.lease_generation NOT BETWEEN OLD.lease_generation AND OLD.lease_generation+1
    OR OLD.state IN ('QUARANTINED','COMMITTED')
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER TABLE control.fleet_fact_delivery FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.fleet_fact_delivery FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.fleet_fact_delivery TO openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT,UPDATE ON control.fleet_fact_delivery TO openpc_control_owner;
DROP POLICY IF EXISTS fleet_delivery_owner ON control.fleet_fact_delivery;
CREATE POLICY fleet_delivery_owner ON control.fleet_fact_delivery TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id))
 WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id));
DROP TRIGGER IF EXISTS fleet_delivery_history ON control.fleet_fact_delivery;
CREATE TRIGGER fleet_delivery_history BEFORE UPDATE OR DELETE ON control.fleet_fact_delivery
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_fleet_delivery_history();


ALTER TABLE control.fleet_fact_delivery_attempt FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.fleet_fact_delivery_attempt FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.fleet_fact_delivery_attempt TO openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT,UPDATE ON control.fleet_fact_delivery_attempt TO openpc_control_owner;
DROP POLICY IF EXISTS fleet_delivery_owner ON control.fleet_fact_delivery_attempt;
CREATE POLICY fleet_delivery_owner ON control.fleet_fact_delivery_attempt TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id))
 WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id));
DROP TRIGGER IF EXISTS fleet_delivery_history ON control.fleet_fact_delivery_attempt;
CREATE TRIGGER fleet_delivery_history BEFORE UPDATE OR DELETE ON control.fleet_fact_delivery_attempt
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_fleet_delivery_history();



CREATE OR REPLACE FUNCTION openpc.guard_fact_failure_signer()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF NOT (current_user='openpc_control_owner' OR pg_has_role(current_user,'openpc_control_key_governor','USAGE'))
  OR TG_OP='DELETE' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED'
   OR to_jsonb(NEW)-'state' IS DISTINCT FROM to_jsonb(OLD)-'state'
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSE
  IF NEW.state<>'ACTIVE' OR NOT (NEW.database_role~'^[a-z_][a-z0-9_]{0,62}$' OR (
    NEW.participant_id::text~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    AND NEW.privacy_domain_id::text~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    AND NEW.database_role='openpc_rs_login_'||translate(rtrim(encode(sha256(convert_to(
      '["openpc:runtime-source-scope:v1","'||NEW.participant_id::text||'","'||NEW.privacy_domain_id::text||'"]',
      'UTF8')),'base64'),'='),'+/','-_')))
   OR NEW.environment_id!~'^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$'
   OR substring(NEW.workload_credential_id::text from 15 for 1)<>'7'
   OR encode(NEW.public_key_spki,'hex')!~'^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$'
   OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname=NEW.database_role AND r.rolcanlogin
     AND NOT r.rolsuper AND NOT r.rolbypassrls AND NOT r.rolcreaterole
     AND pg_has_role(r.rolname,'openpc_control_worker','USAGE')
     AND NOT pg_has_role(r.rolname,'openpc_control_owner','MEMBER')
     AND NOT pg_has_role(r.rolname,'openpc_control_key_governor','MEMBER'))
   OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal w USING(participant_id,principal_id)
     WHERE c.participant_id=NEW.participant_id AND c.credential_id=NEW.workload_credential_id
      AND c.credential_epoch=NEW.workload_credential_epoch AND c.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC')
      AND c.state='ACTIVE' AND w.state='ACTIVE' AND w.kind='WORKLOAD'
      AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
      AND c.public_key_digest IS DISTINCT FROM sha256(NEW.public_key_spki))
   OR EXISTS(SELECT 1 FROM control.fact_consumer_profile p WHERE p.participant_id=NEW.participant_id
     AND p.privacy_domain_id=NEW.privacy_domain_id AND p.issuer_spki=NEW.public_key_spki)
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END IF;
 RETURN NEW;
END $$;
ALTER TABLE control.fact_consumer_failure_signer FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.fact_consumer_failure_signer FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT,UPDATE ON control.fact_consumer_failure_signer TO openpc_control_owner,openpc_control_key_governor;
GRANT SELECT ON control.fact_consumer_failure_signer TO openpc_control_worker;
DROP POLICY IF EXISTS fact_failure_signer_installation ON control.fact_consumer_failure_signer;
CREATE POLICY fact_failure_signer_installation ON control.fact_consumer_failure_signer TO openpc_control_owner,openpc_control_key_governor USING(true) WITH CHECK(true);
DROP TRIGGER IF EXISTS fact_failure_signer_installation ON control.fact_consumer_failure_signer;
CREATE TRIGGER fact_failure_signer_installation BEFORE INSERT OR UPDATE OR DELETE ON control.fact_consumer_failure_signer
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_fact_failure_signer();

CREATE OR REPLACE FUNCTION openpc.require_fact_failure_signer(p control.fact_consumer_profile,wanted_signer text)
RETURNS control.fact_consumer_failure_signer LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE s control.fact_consumer_failure_signer; now_ms numeric;
BEGIN
 SELECT * INTO s FROM control.fact_consumer_failure_signer WHERE participant_id=p.participant_id
  AND privacy_domain_id=p.privacy_domain_id AND consumer_id=p.consumer_id AND state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF s.signer_key_id IS DISTINCT FROM wanted_signer OR s.environment_id IS DISTINCT FROM p.claims->>'environmentId'
  OR s.database_role IS DISTINCT FROM session_user OR s.database_role IS DISTINCT FROM p.database_role
  OR s.workload_credential_id IS DISTINCT FROM p.workload_credential_id OR s.workload_credential_epoch IS DISTINCT FROM p.workload_credential_epoch
  OR s.signer_role<>'FACT_CONSUMER_FAILURE' OR s.purpose_code<>344
  OR now_ms<s.valid_from_ms OR now_ms>=s.valid_until_ms OR s.public_key_spki=p.issuer_spki
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN s;
END $$;
ALTER FUNCTION openpc.require_fact_failure_signer(control.fact_consumer_profile,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.require_fact_failure_signer(control.fact_consumer_profile,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.prepare_fleet_fact_quarantine(material bytea,nonce bytea,mac bytea,wanted_profile text)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE request jsonb; d control.fleet_fact_delivery; q control.fleet_fact_quarantine;
 profile control.fact_consumer_profile; signer control.fact_consumer_failure_signer;
 actor uuid; now_ms numeric; claims jsonb; original jsonb;
BEGIN
 request:=openpc.verify_fleet_delivery_capability(material,nonce,mac,wanted_profile,'OPENPC_FLEET_FACT_FAILURE_PREPARE_V1');
 IF request IS DISTINCT FROM jsonb_build_object('participantId',openpc.current_participant_id()::text,
  'privacyDomainId',openpc.current_privacy_domain_id()::text,'eventId',(request->>'eventId')::uuid::text,'signerKeyId',request->>'signerKeyId')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 IF profile.profile_digest IS DISTINCT FROM wanted_profile THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO d FROM control.fleet_fact_delivery WHERE participant_id=profile.participant_id
  AND privacy_domain_id=profile.privacy_domain_id AND event_id=(request->>'eventId')::uuid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO q FROM control.fleet_fact_quarantine WHERE participant_id=d.participant_id
  AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id FOR UPDATE;
 IF q.state='COMMITTED' THEN
  IF d.state<>'QUARANTINED' OR q.material_digest<>d.material_digest THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  RETURN jsonb_build_object('state','COMMITTED','receiptId',q.receipt_id,'workItemId',q.work_item_id,
    'payload',encode(q.payload,'hex'),'cose',encode(q.cose,'hex'),'receiptDigest',q.receipt_digest);
 END IF;
 IF q.event_id IS NOT NULL OR d.state<>'EXHAUSTED' OR d.failed_attempts<>d.maximum_attempts
  OR d.last_problem IS DISTINCT FROM 'PC-DATA-6005' OR d.lease_id IS NOT NULL
  OR EXISTS(SELECT 1 FROM control.fleet_fact_delivery_attempt a WHERE a.participant_id=d.participant_id
    AND a.privacy_domain_id=d.privacy_domain_id AND a.event_id=d.event_id AND a.outcome='ACTIVE')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 signer:=openpc.require_fact_failure_signer(profile,request->>'signerKeyId');
 SELECT principal_id INTO STRICT actor FROM control.credential WHERE participant_id=d.participant_id AND credential_id=profile.workload_credential_id;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000); original:=convert_from(d.material,'UTF8')::jsonb;
 claims:=jsonb_build_object('environmentId',profile.claims->'environmentId','participantId',d.participant_id::text,
  'privacyDomainId',d.privacy_domain_id::text,'consumerId','LS-FLEET-CONTROL',
  'subscriptionId','SUB-FACTCANDIDATEADMITTED-FLEET_CONTROL-V1','eventId',d.event_id::text,
  'candidateId',d.candidate_id::text,'generationId',d.generation_id::text,'factType',d.fact_type,'sequence',d.sequence::text,
  'envelopeDigest',original->'envelopeDigest','dataDigest',original->'dataDigest',
  'materialDigest','sha256:'||encode(d.material_digest,'hex'),'initialProfileDigest',d.initial_profile_digest,
  'currentProfileDigest',wanted_profile,'failedAttempts',d.failed_attempts,'maximumAttempts',d.maximum_attempts,
  'leaseGeneration',d.lease_generation::text,'workloadCredentialId',profile.workload_credential_id::text,
  'workloadCredentialEpoch',profile.workload_credential_epoch::text,'workloadPrincipalId',actor::text,
  'workItemId',uuidv7()::text,'problem','PC-DATA-6005','recordedAtMs',now_ms,'signerKeyId',signer.signer_key_id,'receiptId',uuidv7()::text);
 INSERT INTO control.fleet_fact_quarantine(participant_id,privacy_domain_id,event_id,receipt_id,work_item_id,material_digest,claims)
 VALUES(d.participant_id,d.privacy_domain_id,d.event_id,(claims->>'receiptId')::uuid,(claims->>'workItemId')::uuid,d.material_digest,claims);
 RETURN jsonb_build_object('state','PREPARED','claims',claims,'signerSpki',encode(signer.public_key_spki,'hex'));
END $$;
ALTER FUNCTION openpc.prepare_fleet_fact_quarantine(bytea,bytea,bytea,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.prepare_fleet_fact_quarantine(bytea,bytea,bytea,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.prepare_fleet_fact_quarantine(bytea,bytea,bytea,text) TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.commit_fleet_fact_quarantine(material bytea,nonce bytea,mac bytea,wanted_profile text)
RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE request jsonb; q control.fleet_fact_quarantine; d control.fleet_fact_delivery;
 profile control.fact_consumer_profile; signer control.fact_consumer_failure_signer;
 c jsonb; expected jsonb; signed_payload bytea; signed_cose bytea; now_ms numeric;
BEGIN
 request:=openpc.verify_fleet_delivery_capability(material,nonce,mac,wanted_profile,'OPENPC_FLEET_FACT_FAILURE_COMMIT_V1');
 IF request IS DISTINCT FROM jsonb_build_object('participantId',openpc.current_participant_id()::text,
  'privacyDomainId',openpc.current_privacy_domain_id()::text,'eventId',(request->>'eventId')::uuid::text,
  'payload',request->>'payload','cose',request->>'cose')
  OR coalesce(request->>'payload','')!~'^[0-9a-f]+$' OR coalesce(request->>'cose','')!~'^[0-9a-f]+$'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 signed_payload:=decode(request->>'payload','hex'); signed_cose:=decode(request->>'cose','hex');
 SELECT * INTO d FROM control.fleet_fact_delivery WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=(request->>'eventId')::uuid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO q FROM control.fleet_fact_quarantine WHERE participant_id=d.participant_id
  AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF q.state='COMMITTED' THEN
  IF d.state<>'QUARANTINED' OR q.payload IS DISTINCT FROM signed_payload OR q.cose IS DISTINCT FROM signed_cose
   OR q.claims->>'currentProfileDigest' IS DISTINCT FROM wanted_profile
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  RETURN q.work_item_id;
 END IF;
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 c:=q.claims; signer:=openpc.require_fact_failure_signer(profile,c->>'signerKeyId');
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF q.state<>'PREPARED' OR d.state<>'EXHAUSTED' OR q.material_digest<>d.material_digest
  OR profile.profile_digest IS DISTINCT FROM wanted_profile OR c->>'currentProfileDigest' IS DISTINCT FROM wanted_profile
  OR c->>'workloadCredentialId' IS DISTINCT FROM profile.workload_credential_id::text
  OR c->>'workloadCredentialEpoch' IS DISTINCT FROM profile.workload_credential_epoch::text
  OR c->>'failedAttempts' IS DISTINCT FROM d.failed_attempts::text OR c->>'maximumAttempts' IS DISTINCT FROM d.maximum_attempts::text
  OR c->>'leaseGeneration' IS DISTINCT FROM d.lease_generation::text OR d.lease_id IS NOT NULL
  OR d.failed_attempts<>d.maximum_attempts OR d.last_problem IS DISTINCT FROM 'PC-DATA-6005'
  OR (c->>'recordedAtMs')::numeric>now_ms OR now_ms-(c->>'recordedAtMs')::numeric>30000
  OR (c->>'recordedAtMs')::numeric<signer.valid_from_ms
  OR EXISTS(SELECT 1 FROM control.fleet_fact_delivery_attempt a WHERE a.participant_id=d.participant_id
   AND a.privacy_domain_id=d.privacy_domain_id AND a.event_id=d.event_id AND a.outcome='ACTIVE')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object(
  '0',openpc.business_bytes(decode('b9d6f05813ff518d1cbc05ff0cd9a55c9729035bce9f9f8446a914d2098bfbea','hex')),
  '1',c->'environmentId',
  '2',openpc.business_uuid(q.participant_id),
  '3',openpc.business_uuid(q.privacy_domain_id),
  '4',c->'consumerId',
  '5',c->'subscriptionId',
  '6',openpc.business_uuid((c->>'eventId')::uuid),
  '7',openpc.business_uuid((c->>'candidateId')::uuid),
  '8',openpc.business_uuid((c->>'generationId')::uuid),
  '9',c->'factType',
  '10',(c->>'sequence')::numeric,
  '11',openpc.business_bytes(decode(substring(c->>'envelopeDigest' from 8),'hex')),
  '12',openpc.business_bytes(decode(substring(c->>'dataDigest' from 8),'hex')),
  '13',openpc.business_bytes(decode(substring(c->>'materialDigest' from 8),'hex')),
  '14',openpc.business_bytes(decode(substring(c->>'initialProfileDigest' from 8),'hex')),
  '15',openpc.business_bytes(decode(substring(c->>'currentProfileDigest' from 8),'hex')),
  '16',(c->>'failedAttempts')::numeric,
  '17',(c->>'maximumAttempts')::numeric,
  '18',(c->>'leaseGeneration')::numeric,
  '19',openpc.business_uuid((c->>'workloadCredentialId')::uuid),
  '20',(c->>'workloadCredentialEpoch')::numeric,
  '21',openpc.business_uuid((c->>'workloadPrincipalId')::uuid),
  '22',openpc.business_uuid(q.work_item_id),
  '23','PC-DATA-6005',
  '24',(c->>'recordedAtMs')::numeric,
  '25',openpc.business_bytes(sha256(signer.public_key_spki)),
  '26',openpc.business_uuid(q.receipt_id));
 IF openpc.business_cbor(signed_payload) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.archive_cose_binding(signed_payload,signed_cose,signer.signer_key_id,24007,344);
 INSERT INTO control.work_item(work_item_id,participant_id,privacy_domain_id,kind,state,resource_ref,payload_digest,reason,created_by_principal_id,row_version)
 VALUES(q.work_item_id,q.participant_id,q.privacy_domain_id,'FLEET_FAILURE','OPEN','urn:openpc:resource:'||d.candidate_id::text,
   d.material_digest,'Fact delivery quarantined (PC-DATA-6005).',(c->>'workloadPrincipalId')::uuid,1);
 UPDATE control.fleet_fact_quarantine SET state='COMMITTED',payload=signed_payload,
  cose=signed_cose,receipt_digest='sha256:'||encode(sha256(signed_cose),'hex'),
  signer_key_id=signer.signer_key_id,committed_at_ms=now_ms
 WHERE participant_id=q.participant_id AND privacy_domain_id=q.privacy_domain_id AND event_id=q.event_id;
 INSERT INTO control.fleet_fact_failure_outbox(participant_id,privacy_domain_id,receipt_id,receipt_digest)
 VALUES(q.participant_id,q.privacy_domain_id,q.receipt_id,'sha256:'||encode(sha256(signed_cose),'hex'));
 UPDATE control.fleet_fact_delivery SET state='QUARANTINED' WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id;
 -- Time can expire while signing; the same current workload/profile and signer
 -- are checked after effects and before this atomic transaction can succeed.
 profile:=openpc.require_fact_consumer_profile('LS-FLEET-CONTROL');
 PERFORM openpc.require_fact_failure_signer(profile,signer.signer_key_id);
 RETURN q.work_item_id;
END $$;
ALTER FUNCTION openpc.commit_fleet_fact_quarantine(bytea,bytea,bytea,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.commit_fleet_fact_quarantine(bytea,bytea,bytea,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.commit_fleet_fact_quarantine(bytea,bytea,bytea,text) TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.guard_fleet_quarantine_history()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP='DELETE' OR TG_TABLE_NAME='fleet_fact_failure_outbox' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF OLD.state<>'PREPARED' OR NEW.state<>'COMMITTED'
  OR to_jsonb(NEW)-ARRAY['state','payload','cose','receipt_digest','signer_key_id','committed_at_ms']
    IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','payload','cose','receipt_digest','signer_key_id','committed_at_ms']
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.assert_fleet_quarantine_atomic()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.fleet_fact_quarantine q
   JOIN control.fleet_fact_delivery d USING(participant_id,privacy_domain_id,event_id)
   JOIN control.fleet_fact_failure_outbox o USING(participant_id,privacy_domain_id,receipt_id)
   JOIN control.work_item w ON w.participant_id=q.participant_id AND w.privacy_domain_id=q.privacy_domain_id AND w.work_item_id=q.work_item_id
   WHERE q.participant_id=NEW.participant_id AND q.privacy_domain_id=NEW.privacy_domain_id AND q.event_id=NEW.event_id
    AND q.state='COMMITTED' AND d.state='QUARANTINED' AND q.material_digest=d.material_digest
    AND o.receipt_digest=q.receipt_digest AND w.kind='FLEET_FAILURE' AND w.state='OPEN' AND w.row_version=1
    AND w.resource_ref='urn:openpc:resource:'||d.candidate_id::text AND w.payload_digest=d.material_digest
    AND w.reason='Fact delivery quarantined (PC-DATA-6005).' AND w.created_by_principal_id=(q.claims->>'workloadPrincipalId')::uuid
    AND w.assignee_principal_id IS NULL AND w.claimed_by_principal_id IS NULL AND w.completed_by_principal_id IS NULL)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NULL;
END $$;

ALTER TABLE control.fleet_fact_quarantine FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.fleet_fact_quarantine FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.fleet_fact_quarantine TO openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT,UPDATE ON control.fleet_fact_quarantine TO openpc_control_owner;
DROP POLICY IF EXISTS fleet_failure_owner ON control.fleet_fact_quarantine;
CREATE POLICY fleet_failure_owner ON control.fleet_fact_quarantine TO openpc_control_owner USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id)) WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id));
DROP TRIGGER IF EXISTS fleet_failure_history ON control.fleet_fact_quarantine;
CREATE TRIGGER fleet_failure_history BEFORE UPDATE OR DELETE ON control.fleet_fact_quarantine FOR EACH ROW EXECUTE FUNCTION openpc.guard_fleet_quarantine_history();


ALTER TABLE control.fleet_fact_failure_outbox FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.fleet_fact_failure_outbox FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.fleet_fact_failure_outbox TO openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT,UPDATE ON control.fleet_fact_failure_outbox TO openpc_control_owner;
DROP POLICY IF EXISTS fleet_failure_owner ON control.fleet_fact_failure_outbox;
CREATE POLICY fleet_failure_owner ON control.fleet_fact_failure_outbox TO openpc_control_owner USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id)) WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id));
DROP TRIGGER IF EXISTS fleet_failure_history ON control.fleet_fact_failure_outbox;
CREATE TRIGGER fleet_failure_history BEFORE UPDATE OR DELETE ON control.fleet_fact_failure_outbox FOR EACH ROW EXECUTE FUNCTION openpc.guard_fleet_quarantine_history();

ALTER FUNCTION openpc.assert_fleet_quarantine_atomic() OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.assert_fleet_quarantine_atomic() FROM PUBLIC;
GRANT SELECT,INSERT ON control.work_item TO openpc_control_owner;
DROP POLICY IF EXISTS fleet_failure_work_item ON control.work_item;
CREATE POLICY fleet_failure_work_item ON control.work_item TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND openpc.current_action_intent_id()='ACT-OPERATIONS_READ_OPERATION-V1')
 WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND openpc.current_action_intent_id()='ACT-OPERATIONS_READ_OPERATION-V1' AND kind='FLEET_FAILURE');
DROP TRIGGER IF EXISTS fleet_quarantine_atomic ON control.fleet_fact_quarantine;
CREATE CONSTRAINT TRIGGER fleet_quarantine_atomic AFTER INSERT OR UPDATE ON control.fleet_fact_quarantine
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.assert_fleet_quarantine_atomic();


ALTER TABLE control.notification FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT,UPDATE ON control.notification TO openpc_control_runtime;
GRANT SELECT ON control.notification TO openpc_control_reader;
CREATE OR REPLACE FUNCTION openpc.notification_business_projection(item control.notification)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('0',(item).severity,'1',(item).state,'2',(item).message_key,
  '3',CASE WHEN (item).resource_ref IS NULL THEN 0 ELSE 1 END,
  '5',openpc.business_bytes(decode(substr((item).candidate_digest,8),'hex')))
  || CASE WHEN (item).resource_ref IS NULL THEN '{}'::jsonb
     ELSE jsonb_build_object('4',(item).resource_ref) END
$$;
CREATE OR REPLACE FUNCTION openpc.assert_notification_receipt(receipt control.audit_occurrence)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE item control.notification%ROWTYPE; before_projection jsonb; after_projection jsonb;
BEGIN
 IF receipt.profile_version<>1 OR receipt.catalog_operation_id NOT IN
  ('CFG-OP-CREATE-NOTIFICATION','CFG-OP-ACKNOWLEDGE-NOTIFICATION')
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-PROFILE'; END IF;
 SELECT * INTO STRICT item FROM control.notification n WHERE n.participant_id=receipt.participant_id
  AND n.privacy_domain_id=receipt.privacy_domain_id AND n.notification_id=receipt.aggregate_id;
 before_projection:=openpc.business_cbor(receipt.before_state_preimage)->8;
 after_projection:=openpc.business_cbor(receipt.after_state_preimage)->8;
 IF receipt.after_existence<>1 OR receipt.after_revision<>item.revision
  OR after_projection IS DISTINCT FROM openpc.notification_business_projection(item)
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ACTUAL-STATE'; END IF;
 IF receipt.catalog_operation_id='CFG-OP-CREATE-NOTIFICATION' THEN
  IF receipt.before_existence<>0 OR receipt.before_revision<>0 OR receipt.after_revision<>1
   OR item.state<>'UNREAD' OR item.candidate_digest IS DISTINCT FROM 'sha256:'||encode(receipt.candidate_digest,'hex')
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-CREATE'; END IF;
 ELSE
  IF receipt.before_existence<>1 OR receipt.after_revision<>receipt.before_revision+1
   OR before_projection->>'1' NOT IN ('UNREAD','READ') OR item.state<>'ACKNOWLEDGED'
   OR before_projection-'1' IS DISTINCT FROM after_projection-'1'
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ACKNOWLEDGE'; END IF;
 END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_mutation()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF current_setting('openpc.action_intent_id')='ACT-EVIDENCE_EXPORT_RECORDS-V1' THEN
   PERFORM openpc.admit_notification_occurrence_metadata(NEW);
   RETURN NEW;
  END IF;
  IF current_setting('openpc.action_intent_id')<>'ACT-NOTIFICATIONS_CREATE_RESOURCE-V1'
   OR NEW.state<>'UNREAD' OR NEW.revision<>1
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-CREATE'; END IF;
 ELSE
  IF current_setting('openpc.action_intent_id')<>'ACT-NOTIFICATION_UPDATE_ACKNOWLEDGE-V1'
   OR OLD.state NOT IN ('UNREAD','READ') OR NEW.state<>'ACKNOWLEDGED' OR NEW.revision<>OLD.revision+1
   OR ROW(NEW.participant_id,NEW.privacy_domain_id,NEW.notification_id,NEW.severity,NEW.resource_ref,
     NEW.message_key,NEW.candidate_digest,NEW.created_at) IS DISTINCT FROM
      ROW(OLD.participant_id,OLD.privacy_domain_id,OLD.notification_id,OLD.severity,OLD.resource_ref,
     OLD.message_key,OLD.candidate_digest,OLD.created_at)
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ACKNOWLEDGE'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_mutation_guard ON control.notification;
CREATE TRIGGER notification_mutation_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_mutation();
CREATE OR REPLACE FUNCTION openpc.check_notification_effect_receipt()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE receipt control.audit_occurrence%ROWTYPE; before_projection jsonb;
BEGIN
 -- A signed occurrence reserves its exact notification identity. This selects
 -- the proof family only; the full checker below still requires both originals,
 -- exact metadata and every payload/inbox/cursor/outbox effect. No GUC selects
 -- or skips this deferred admission, and a malformed pair never falls back.
 IF TG_OP='INSERT' AND EXISTS(
  SELECT 1 FROM control.notification_occurrence_preparation p
  JOIN control.notification_occurrence_observation o USING(participant_id,privacy_domain_id,preparation_id)
  WHERE p.participant_id=NEW.participant_id AND p.privacy_domain_id=NEW.privacy_domain_id
   AND p.family='NotificationOccurrenceReceiptV1'
   AND openpc.business_cbor(o.receipt_payload)->'6'=openpc.business_uuid(NEW.notification_id)
 ) THEN
  PERFORM openpc.check_notification_occurrence_metadata_effect(NEW);
  RETURN NEW;
 END IF;
 -- Ordinary public CREATE/ACK keeps its unconditional audit receipt check.
 SELECT * INTO STRICT receipt FROM control.audit_occurrence r WHERE r.participant_id=NEW.participant_id
  AND r.privacy_domain_id=NEW.privacy_domain_id AND r.aggregate_type='notification'
  AND r.aggregate_id=NEW.notification_id AND r.after_revision=NEW.revision
  AND r.catalog_operation_id=(CASE WHEN TG_OP='INSERT' THEN 'CFG-OP-CREATE-NOTIFICATION'
    ELSE 'CFG-OP-ACKNOWLEDGE-NOTIFICATION' END);
 IF TG_OP='INSERT' THEN before_projection:='{}'::jsonb;
 ELSE before_projection:=openpc.notification_business_projection(OLD); END IF;
 IF openpc.business_cbor(receipt.before_state_preimage)->8 IS DISTINCT FROM before_projection
  OR openpc.business_cbor(receipt.after_state_preimage)->8 IS DISTINCT FROM openpc.notification_business_projection(NEW)
  OR receipt.before_revision IS DISTINCT FROM (CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.revision END)
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-EFFECT-RECEIPT'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_effect_receipt ON control.notification;
CREATE CONSTRAINT TRIGGER notification_effect_receipt AFTER INSERT OR UPDATE ON control.notification
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.check_notification_effect_receipt();
REVOKE ALL ON FUNCTION openpc.notification_business_projection(control.notification),
 openpc.assert_notification_receipt(control.audit_occurrence),openpc.guard_notification_mutation(),
 openpc.check_notification_effect_receipt() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.notification_business_projection(control.notification),
 openpc.assert_notification_receipt(control.audit_occurrence) TO openpc_control_runtime;


ALTER TABLE control.installed_notification_channel FORCE ROW LEVEL SECURITY;
ALTER TABLE control.notification_endpoint_candidate FORCE ROW LEVEL SECURITY;
ALTER TABLE control.notification_verification_attempt FORCE ROW LEVEL SECURITY;
ALTER TABLE control.notification_endpoint FORCE ROW LEVEL SECURITY;
ALTER TABLE control.notification_endpoint_verification FORCE ROW LEVEL SECURITY;
ALTER TABLE control.notification_verification_attempt ALTER CONSTRAINT notification_verification_attachment_operation_fk DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE control.notification_endpoint_verification ALTER CONSTRAINT notification_verification_operation_fk DEFERRABLE INITIALLY DEFERRED;

CREATE OR REPLACE FUNCTION openpc.guard_notification_channel_installation() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF NOT pg_has_role(current_user,'openpc_control_owner','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND (OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED'
    OR to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state'))
 THEN RAISE EXCEPTION 'DATA-6020-NOTIFICATION-INSTALLATION-IMMUTABLE'; END IF;
 -- A direct UPDATE may already own its row lock. Never wait in this reversed
 -- order: deny and roll back before effects if an admitted reader holds the fence.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('notification-installation:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_channel_installation_guard ON control.installed_notification_channel;
CREATE TRIGGER notification_channel_installation_guard BEFORE INSERT OR UPDATE OR DELETE ON control.installed_notification_channel
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_channel_installation();

CREATE OR REPLACE FUNCTION openpc.guard_notification_candidate() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-NOTIFICATION-CANDIDATE-IMMUTABLE'; END IF;
 IF NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
   OR current_setting('openpc.action_intent_id')<>'ACT-NOTIFICATION_ENDPOINTS_UPDATE_RESOURCE-V1'
   OR NEW.predecessor->>'endpointId'<>NEW.endpoint_id::text
   OR NEW.predecessor->>'participantId'<>NEW.participant_id::text
   OR NEW.predecessor->>'privacyDomainId'<>NEW.privacy_domain_id::text
   OR NEW.construction->'binding'->>'endpointId'<>NEW.endpoint_id::text
   OR (NEW.construction->'binding'->>'revision')::numeric<>(NEW.predecessor->>'revision')::numeric+1
   OR NEW.replacement_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
      jsonb_build_object('domain','pc.notification-endpoint.replacement.v1','predecessor',NEW.predecessor,
        'replacement',NEW.construction->'binding','credential',jsonb_build_object(
          'reference',NEW.construction->'credential'->>'reference','version',NEW.construction->'credential'->>'version',
          'fingerprint',NEW.construction->'credential'->>'fingerprint','epoch',NEW.construction->'credential'->>'epoch'))),'UTF8')),'hex')
   OR NEW.expires_at_ms<=floor(extract(epoch from clock_timestamp())*1000)
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_candidate_guard ON control.notification_endpoint_candidate;
CREATE TRIGGER notification_candidate_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_endpoint_candidate
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_candidate();

CREATE OR REPLACE FUNCTION openpc.guard_notification_verification_attempt() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE c jsonb; signed jsonb; payload bytea; cose bytea; claims jsonb; outer_item jsonb; fields jsonb; header jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-NOTIFICATION-ATTEMPT-IMMUTABLE'; END IF;
 IF NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id()
  OR current_setting('openpc.action_intent_id')<>'ACT-NOTIFICATION_UPDATE_VERIFY-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 c:=convert_from(NEW.challenge_bytes,'UTF8')::jsonb->'challenge';
 IF NEW.challenge_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(jsonb_build_object('challenge',c)),'UTF8')
  OR c IS NULL OR c->>'challengeId'<>NEW.attempt_id::text OR c->>'principalId'<>NEW.principal_id::text
   OR c->'predecessor'->>'participantId'<>NEW.participant_id::text
   OR c->'predecessor'->>'privacyDomainId'<>NEW.privacy_domain_id::text
   OR c->'predecessor'->>'endpointId'<>NEW.endpoint_id::text
   OR (c->'predecessor'->>'revision')::numeric<>NEW.predecessor_revision
   OR c->>'businessIdempotencyDigest'<>NEW.business_idempotency_digest
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ATTEMPT-BINDING'; END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.state<>'PREPARED' OR (c->>'expiresAtMs')::numeric<=floor(extract(epoch from clock_timestamp())*1000)
   THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ATTEMPT-PREPARE'; END IF;
 ELSE
   IF (to_jsonb(OLD)-ARRAY['state','response_bytes','verified_at_ms','receipt_digest','attached_operation_id']) IS DISTINCT FROM
      (to_jsonb(NEW)-ARRAY['state','response_bytes','verified_at_ms','receipt_digest','attached_operation_id'])
   THEN RAISE EXCEPTION 'DATA-6020-NOTIFICATION-ATTEMPT-IMMUTABLE'; END IF;
   IF NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED')
     OR (OLD.state='DISPATCHED' AND NEW.state IN ('UNKNOWN','PROVED','REJECTED'))
     OR (OLD.state='PROVED' AND NEW.state='ATTACHED'
       AND ROW(OLD.response_bytes,OLD.verified_at_ms,OLD.receipt_digest) IS NOT DISTINCT FROM ROW(NEW.response_bytes,NEW.verified_at_ms,NEW.receipt_digest)
       AND NEW.attached_operation_id::text=current_setting('openpc.operation_id')
       AND (c->>'expiresAtMs')::numeric>floor(extract(epoch from clock_timestamp())*1000)))
   THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ATTEMPT-TRANSITION'; END IF;
 END IF;
 IF NEW.response_bytes IS NOT NULL THEN
  signed:=convert_from(NEW.response_bytes,'UTF8')::jsonb;
  IF NEW.response_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(signed),'UTF8')
   OR (SELECT count(*) FROM jsonb_object_keys(signed))<>2
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-OBSERVATION-WIRE'; END IF;
  payload:=decode(signed->>'payloadHex','hex'); cose:=decode(signed->>'coseHex','hex');
  claims:=openpc.business_cbor(payload);
  IF get_byte(cose,0) IS DISTINCT FROM 210 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-OBSERVATION-COSE'; END IF;
  outer_item:=openpc.business_cbor_item(cose,1,0); fields:=outer_item->'value';
  IF (outer_item->>'next')::integer IS DISTINCT FROM octet_length(cose)
   OR jsonb_typeof(fields) IS DISTINCT FROM 'array' OR jsonb_array_length(fields)<>4
   OR fields->1 IS DISTINCT FROM '{}'::jsonb OR fields->2 IS DISTINCT FROM openpc.business_bytes(payload)
   OR length(fields->3->>'bytes') IS DISTINCT FROM 128
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-OBSERVATION-COSE'; END IF;
  header:=openpc.business_cbor(decode(fields->0->>'bytes','hex'));
  IF (SELECT count(*) FROM jsonb_object_keys(claims))<>11 OR NEW.verified_at_ms>floor(extract(epoch from clock_timestamp())*1000)
   OR header IS DISTINCT FROM jsonb_build_object('1',-7,'2',jsonb_build_array(100,101,102,103),'3','application/pc+cbor',
     '4',openpc.business_bytes(convert_to('sha256:'||(claims->'10'->>'bytes'),'UTF8')),
     '100',24012,'101',1,'102',349,'103',2)
   OR claims->'0' IS DISTINCT FROM openpc.business_bytes(decode('8a795d0fababedbd97790f52ddcd71628c0e35a70e46bf8bfa31419308ff1bd5','hex'))
   OR claims->>'1' IS DISTINCT FROM c->>'environmentId'
   OR claims->'2' IS DISTINCT FROM openpc.business_bytes(uuid_send(NEW.participant_id))
   OR claims->'3' IS DISTINCT FROM openpc.business_bytes(uuid_send(NEW.privacy_domain_id))
   OR claims->'5' IS DISTINCT FROM openpc.business_bytes(decode(substr(c->>'signedVerificationProfileDigest',8),'hex'))
   OR claims->'6' IS DISTINCT FROM openpc.business_bytes(sha256(convert_to(openpc.signing_canonical_json(c),'UTF8')))
   OR (claims->>'7')::integer IS DISTINCT FROM (CASE WHEN NEW.state='REJECTED' THEN 2 ELSE 1 END)
   OR (claims->>'8')::numeric<(c->>'issuedAtMs')::numeric OR (claims->>'8')::numeric>NEW.verified_at_ms
   OR (claims->>'9')::numeric<=NEW.verified_at_ms OR (claims->>'9')::numeric>(c->>'expiresAtMs')::numeric
   OR NEW.receipt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(cose),'hex')
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-OBSERVATION-BINDING'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_verification_attempt_guard ON control.notification_verification_attempt;
CREATE TRIGGER notification_verification_attempt_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_verification_attempt
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_verification_attempt();

CREATE OR REPLACE FUNCTION openpc.guard_notification_verification_row() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE a control.notification_verification_attempt%ROWTYPE; c jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-NOTIFICATION-VERIFICATION-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
   OR NEW.operation_id::text IS DISTINCT FROM current_setting('openpc.operation_id')
   OR current_setting('openpc.action_intent_id')<>'ACT-NOTIFICATION_UPDATE_VERIFY-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT a FROM control.notification_verification_attempt WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.verification_id AND state='ATTACHED'
   AND attached_operation_id=NEW.operation_id AND endpoint_id=NEW.endpoint_id;
 c:=convert_from(a.challenge_bytes,'UTF8')::jsonb->'challenge';
 IF NEW.endpoint_revision IS DISTINCT FROM (c->>'resultRevision')::numeric
   OR NEW.channel IS DISTINCT FROM c->'predecessor'->>'channel'
   OR NEW.destination_ref IS DISTINCT FROM c->'predecessor'->>'destinationRef'
   OR NEW.channel_profile_digest IS DISTINCT FROM c->'predecessor'->>'channelProfileDigest'
   OR NEW.credential_ref IS DISTINCT FROM c->'predecessor'->>'credentialRef'
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-VERIFICATION-BINDING'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_verification_row_guard ON control.notification_endpoint_verification;
CREATE TRIGGER notification_verification_row_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_endpoint_verification
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_verification_row();

CREATE OR REPLACE FUNCTION openpc.notification_endpoint_business_projection(item control.notification_endpoint)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('0',(item).channel,'1',(item).state,'2',(item).destination_ref,
   '3',openpc.business_bytes(decode(substr((item).channel_profile_digest,8),'hex')),'4',(item).credential_ref,
   '5',0,'6',openpc.business_bytes(decode(substr((item).candidate_digest,8),'hex')),
   '7',CASE WHEN (item).verification_id IS NULL THEN 0 ELSE 1 END)
   || CASE WHEN (item).verification_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('8',(item).verification_id::text) END
$$;
CREATE OR REPLACE FUNCTION openpc.assert_notification_endpoint_receipt(receipt control.audit_occurrence)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE item control.notification_endpoint%ROWTYPE; before_projection jsonb; after_projection jsonb; registration control.installed_notification_channel%ROWTYPE;
BEGIN
 IF receipt.profile_version<>1 OR receipt.aggregate_type<>'notification-endpoint' OR receipt.catalog_operation_id NOT IN
  ('CFG-OP-CREATE-NOTIFICATION-ENDPOINT','CFG-OP-UPDATE-NOTIFICATION-ENDPOINT','CFG-OP-VERIFY-NOTIFICATION-ENDPOINT')
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-PROFILE'; END IF;
 SELECT * INTO STRICT item FROM control.notification_endpoint WHERE participant_id=receipt.participant_id
  AND privacy_domain_id=receipt.privacy_domain_id AND endpoint_id=receipt.aggregate_id;
 -- The repository retains this scope fence before its SERIALIZABLE snapshot.
 -- Reacquire nonblocking through COMMIT; do not request runtime UPDATE privilege.
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('notification-installation:'||item.participant_id::text||':'||item.privacy_domain_id::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT registration FROM control.installed_notification_channel n
   WHERE n.participant_id=item.participant_id AND n.privacy_domain_id=item.privacy_domain_id
    AND n.credential_ref=item.credential_ref AND n.channel=item.channel AND n.destination_ref=item.destination_ref
    AND n.channel_profile_digest=item.channel_profile_digest AND n.state='ACTIVE';
 IF (openpc.business_cbor(decode(registration.channel_signed->>'payloadHex','hex'))->>'6')::numeric>floor(extract(epoch from clock_timestamp())*1000)
   OR (openpc.business_cbor(decode(registration.channel_signed->>'payloadHex','hex'))->>'7')::numeric<=floor(extract(epoch from clock_timestamp())*1000)
   OR registration.credential->>'state' IS DISTINCT FROM 'ACTIVE'
   OR (registration.credential->>'validFromMs')::numeric>floor(extract(epoch from clock_timestamp())*1000)
   OR (registration.credential->>'validUntilMs')::numeric<=floor(extract(epoch from clock_timestamp())*1000)
   OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal p ON p.participant_id=c.participant_id AND p.principal_id=c.principal_id
     WHERE c.participant_id=item.participant_id AND c.credential_id=registration.workload_credential_id
       AND c.principal_id=registration.principal_id AND c.credential_epoch=registration.workload_epoch
       AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.audience=registration.workload_id
       AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp() AND p.state='ACTIVE' AND p.kind='WORKLOAD')
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-CURRENT-REGISTRATION'; END IF;
 before_projection:=openpc.business_cbor(receipt.before_state_preimage)->8;
 after_projection:=openpc.business_cbor(receipt.after_state_preimage)->8;
 IF receipt.after_existence<>1 OR receipt.after_revision<>item.revision OR item.arbitrary_egress
  OR after_projection IS DISTINCT FROM openpc.notification_endpoint_business_projection(item)
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-ACTUAL-STATE'; END IF;
 IF receipt.catalog_operation_id='CFG-OP-CREATE-NOTIFICATION-ENDPOINT' THEN
  IF receipt.before_existence<>0 OR receipt.before_revision<>0 OR receipt.after_revision<>1
    OR item.state<>'DISABLED' OR item.verification_id IS NOT NULL
    OR item.candidate_digest IS DISTINCT FROM 'sha256:'||encode(receipt.candidate_digest,'hex')
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-CREATE'; END IF;
 ELSE
  IF receipt.before_existence<>1 OR receipt.after_revision<>receipt.before_revision+1 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-REVISION'; END IF;
  IF receipt.catalog_operation_id='CFG-OP-UPDATE-NOTIFICATION-ENDPOINT' THEN
   IF before_projection->>'1'='RETIRED' OR item.verification_id IS NOT NULL
     OR item.state IS DISTINCT FROM (CASE WHEN before_projection->>'1'='QUARANTINED' THEN 'QUARANTINED' ELSE 'DISABLED' END)
   THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-REPLACEMENT'; END IF;
   IF NOT EXISTS(SELECT 1 FROM control.notification_endpoint_candidate c
     JOIN control.idempotency_record i ON i.participant_id=c.participant_id AND i.privacy_domain_id=c.privacy_domain_id AND i.principal_id=c.principal_id
     WHERE c.participant_id=item.participant_id AND c.privacy_domain_id=item.privacy_domain_id AND c.endpoint_id=item.endpoint_id
       AND c.replacement_digest=item.candidate_digest AND i.operation_id=receipt.operation_id
       AND c.expires_at_ms>floor(extract(epoch from clock_timestamp())*1000)
       AND (c.predecessor->>'revision')::numeric=receipt.before_revision
       AND c.predecessor->>'channel'=before_projection->>'0'
       AND c.predecessor->>'destinationRef'=before_projection->>'2'
       AND openpc.business_bytes(decode(substr(c.predecessor->>'channelProfileDigest',8),'hex'))=before_projection->'3'
       AND c.predecessor->>'credentialRef'=before_projection->>'4'
       AND c.construction->'credential'=registration.credential
       AND c.construction->'binding'=jsonb_build_object('participantId',item.participant_id,'privacyDomainId',item.privacy_domain_id,
         'endpointId',item.endpoint_id,'revision',item.revision::text,'channel',item.channel,'destinationRef',item.destination_ref,
         'channelProfileDigest',item.channel_profile_digest,'credentialRef',item.credential_ref))
   THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-REPLACEMENT-ADMISSION'; END IF;
  ELSE
   IF before_projection->>'1' NOT IN ('ACTIVE','DISABLED') OR item.state<>'ACTIVE'
     OR before_projection-ARRAY['1','7','8'] IS DISTINCT FROM after_projection-ARRAY['1','7','8']
     OR NOT EXISTS (SELECT 1 FROM control.notification_verification_attempt a
       JOIN control.notification_endpoint_verification v ON v.participant_id=a.participant_id AND v.privacy_domain_id=a.privacy_domain_id AND v.verification_id=a.attempt_id
       WHERE a.participant_id=receipt.participant_id AND a.privacy_domain_id=receipt.privacy_domain_id AND a.endpoint_id=item.endpoint_id
        AND a.attempt_id=item.verification_id AND a.state='ATTACHED' AND a.attached_operation_id=receipt.operation_id
        AND v.operation_id=receipt.operation_id AND v.endpoint_revision=item.revision)
   THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-VERIFY'; END IF;
  END IF;
 END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_endpoint_mutation() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE action text:=current_setting('openpc.action_intent_id');
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-NOTIFICATION-ENDPOINT-IMMUTABLE'; END IF;
 IF NEW.participant_id<>openpc.current_participant_id() OR NEW.privacy_domain_id<>openpc.current_privacy_domain_id() OR NEW.arbitrary_egress
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='INSERT' THEN
  IF action<>'ACT-NOTIFICATION_ENDPOINTS_CREATE_RESOURCE-V1' OR NEW.revision<>1 OR NEW.state<>'DISABLED' OR NEW.verification_id IS NOT NULL
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-CREATE'; END IF;
 ELSE
  IF NEW.revision<>OLD.revision+1 OR ROW(NEW.participant_id,NEW.privacy_domain_id,NEW.endpoint_id,NEW.created_at) IS DISTINCT FROM ROW(OLD.participant_id,OLD.privacy_domain_id,OLD.endpoint_id,OLD.created_at)
  THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-REVISION'; END IF;
  IF action='ACT-NOTIFICATION_ENDPOINTS_UPDATE_RESOURCE-V1' THEN
   IF OLD.state='RETIRED' OR NEW.verification_id IS NOT NULL OR NEW.state IS DISTINCT FROM (CASE WHEN OLD.state='QUARANTINED' THEN 'QUARANTINED' ELSE 'DISABLED' END)
   THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-REPLACEMENT'; END IF;
  ELSIF action='ACT-NOTIFICATION_UPDATE_VERIFY-V1' THEN
   IF OLD.state NOT IN ('DISABLED','ACTIVE') OR NEW.state<>'ACTIVE' OR NEW.verification_id IS NULL
    OR ROW(NEW.channel,NEW.destination_ref,NEW.channel_profile_digest,NEW.credential_ref,NEW.candidate_digest) IS DISTINCT FROM ROW(OLD.channel,OLD.destination_ref,OLD.channel_profile_digest,OLD.credential_ref,OLD.candidate_digest)
   THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-VERIFY'; END IF;
  ELSE RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_endpoint_mutation_guard ON control.notification_endpoint;
CREATE TRIGGER notification_endpoint_mutation_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_endpoint
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_endpoint_mutation();
CREATE OR REPLACE FUNCTION openpc.check_notification_endpoint_effect_receipt() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE receipt control.audit_occurrence%ROWTYPE; prior jsonb;
BEGIN
 SELECT * INTO STRICT receipt FROM control.audit_occurrence r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
  AND r.aggregate_type='notification-endpoint' AND r.aggregate_id=NEW.endpoint_id AND r.after_revision=NEW.revision;
 IF TG_OP='INSERT' THEN prior:='{}'::jsonb; ELSE prior:=openpc.notification_endpoint_business_projection(OLD); END IF;
 IF openpc.business_cbor(receipt.before_state_preimage)->8 IS DISTINCT FROM prior
  OR openpc.business_cbor(receipt.after_state_preimage)->8 IS DISTINCT FROM openpc.notification_endpoint_business_projection(NEW)
  OR receipt.before_revision IS DISTINCT FROM (CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.revision END)
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ENDPOINT-EFFECT-RECEIPT'; END IF;
 PERFORM openpc.assert_notification_endpoint_receipt(receipt);
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_endpoint_effect_receipt ON control.notification_endpoint;
CREATE CONSTRAINT TRIGGER notification_endpoint_effect_receipt AFTER INSERT OR UPDATE ON control.notification_endpoint
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.check_notification_endpoint_effect_receipt();

CREATE OR REPLACE FUNCTION openpc.check_notification_verification_attachment() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE receipt control.audit_occurrence%ROWTYPE;
BEGIN
 IF NEW.state<>'ATTACHED' THEN RETURN NEW; END IF;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
   AND r.operation_id=NEW.attached_operation_id AND r.aggregate_id=NEW.endpoint_id AND r.catalog_operation_id='CFG-OP-VERIFY-NOTIFICATION-ENDPOINT';
 IF NOT EXISTS(SELECT 1 FROM control.notification_endpoint e WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id
   AND e.endpoint_id=NEW.endpoint_id AND e.verification_id=NEW.attempt_id AND e.state='ACTIVE' AND e.revision=NEW.predecessor_revision+1)
 THEN RAISE EXCEPTION 'DATA-6021-NOTIFICATION-ATTACHMENT-EFFECT'; END IF;
 PERFORM openpc.assert_notification_endpoint_receipt(receipt);
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_verification_attachment ON control.notification_verification_attempt;
CREATE CONSTRAINT TRIGGER notification_verification_attachment AFTER UPDATE ON control.notification_verification_attempt
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.check_notification_verification_attachment();


DROP POLICY IF EXISTS notification_channel_installer ON control.installed_notification_channel;
CREATE POLICY notification_channel_installer ON control.installed_notification_channel TO openpc_control_owner USING(true) WITH CHECK(true);
REVOKE ALL ON control.installed_notification_channel,control.notification_endpoint_candidate,control.notification_verification_attempt,
 control.notification_endpoint,control.notification_endpoint_verification FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.installed_notification_channel TO openpc_control_runtime;
GRANT SELECT,INSERT ON control.notification_endpoint_candidate TO openpc_control_runtime;
GRANT SELECT,INSERT,UPDATE ON control.notification_verification_attempt,control.notification_endpoint TO openpc_control_runtime;
GRANT SELECT,INSERT ON control.notification_endpoint_verification TO openpc_control_runtime;
GRANT SELECT ON control.notification_endpoint TO openpc_control_reader;
REVOKE ALL ON FUNCTION openpc.guard_notification_channel_installation(),openpc.guard_notification_candidate(),
 openpc.guard_notification_verification_attempt(),openpc.guard_notification_verification_row(),openpc.notification_endpoint_business_projection(control.notification_endpoint),
 openpc.assert_notification_endpoint_receipt(control.audit_occurrence),openpc.guard_notification_endpoint_mutation(),
 openpc.check_notification_endpoint_effect_receipt(),openpc.check_notification_verification_attachment() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.notification_endpoint_business_projection(control.notification_endpoint),
 openpc.assert_notification_endpoint_receipt(control.audit_occurrence) TO openpc_control_runtime;


CREATE OR REPLACE FUNCTION openpc.assert_notification_endpoint_persistence(p_operation text,p_profile bytea)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE required record; admitted control.business_transition_profile%ROWTYPE;
BEGIN
 IF p_operation NOT IN ('CFG-OP-CREATE-NOTIFICATION-ENDPOINT','CFG-OP-UPDATE-NOTIFICATION-ENDPOINT','CFG-OP-VERIFY-NOTIFICATION-ENDPOINT')
  OR NOT pg_has_role(current_user,'openpc_control_runtime','MEMBER')
  OR has_table_privilege(current_user,'control.installed_notification_channel','INSERT,UPDATE,DELETE')
 THEN RAISE EXCEPTION 'PC-INTEGRATION-5001'; END IF;
 SELECT * INTO STRICT admitted FROM control.business_transition_profile WHERE catalog_operation_id=p_operation AND profile_version=1
  AND profile_digest=p_profile AND aggregate_type='notification-endpoint' AND action_intent_id=current_setting('openpc.action_intent_id');
 IF admitted.profile_digest<>sha256(admitted.definition_canonical_json) THEN RAISE EXCEPTION 'PC-INTEGRATION-5001'; END IF;
 FOR required IN SELECT * FROM (VALUES
  ('control.notification_endpoint','notification_endpoint_mutation_guard','openpc.guard_notification_endpoint_mutation()',false),
  ('control.notification_endpoint','notification_endpoint_effect_receipt','openpc.check_notification_endpoint_effect_receipt()',true),
  ('control.installed_notification_channel','notification_channel_installation_guard','openpc.guard_notification_channel_installation()',false),
  ('control.audit_occurrence','business_receipt_typed','openpc.guard_business_receipt()',false),
  ('control.audit_occurrence','business_receipt_complete','openpc.check_business_receipt_completion()',true),
  ('control.outbox_event','business_outbox_payload','openpc.guard_business_outbox()',false)
 ) v(table_name,trigger_name,function_name,deferred)
 LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_proc f ON f.oid=t.tgfoid
   WHERE c.oid=to_regclass(required.table_name) AND t.tgname=required.trigger_name AND t.tgenabled IN ('O','A')
    AND f.oid=to_regprocedure(required.function_name) AND t.tgdeferrable=required.deferred AND t.tginitdeferred=required.deferred
    AND c.relrowsecurity AND c.relforcerowsecurity AND NOT f.prosecdef)
  THEN RAISE EXCEPTION 'PC-INTEGRATION-5001'; END IF;
 END LOOP;
 IF p_operation='CFG-OP-UPDATE-NOTIFICATION-ENDPOINT' AND NOT EXISTS (
  SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_endpoint_candidate'::regclass
    AND tgname='notification_candidate_guard' AND tgfoid='openpc.guard_notification_candidate()'::regprocedure AND tgenabled IN ('O','A'))
 THEN RAISE EXCEPTION 'PC-INTEGRATION-5001'; END IF;
 IF p_operation='CFG-OP-VERIFY-NOTIFICATION-ENDPOINT' THEN
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_verification_attempt'::regclass
      AND tgname='notification_verification_attempt_guard' AND tgfoid='openpc.guard_notification_verification_attempt()'::regprocedure AND tgenabled IN ('O','A'))
    OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_verification_attempt'::regclass
      AND tgname='notification_verification_attachment' AND tgfoid='openpc.check_notification_verification_attachment()'::regprocedure AND tgenabled IN ('O','A') AND tgdeferrable AND tginitdeferred)
    OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_endpoint_verification'::regclass
      AND tgname='notification_verification_row_guard' AND tgfoid='openpc.guard_notification_verification_row()'::regprocedure AND tgenabled IN ('O','A'))
    OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='control.notification_verification_attempt'::regclass
      AND conname='notification_verification_attachment_operation_fk' AND condeferrable AND condeferred AND convalidated)
  THEN RAISE EXCEPTION 'PC-INTEGRATION-5001'; END IF;
 END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.assert_notification_endpoint_persistence(text,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_notification_endpoint_persistence(text,bytea) TO openpc_control_runtime;


ALTER TABLE control.installed_notification_routing FORCE ROW LEVEL SECURITY;
GRANT EXECUTE ON FUNCTION openpc.evidence_export_producer_authority(text) TO openpc_control_owner;
GRANT SELECT ON control.notification_endpoint,control.notification_endpoint_verification,control.installed_notification_channel TO openpc_control_owner;
DROP POLICY IF EXISTS notification_routing_installer_endpoint ON control.notification_endpoint;
CREATE POLICY notification_routing_installer_endpoint ON control.notification_endpoint FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND openpc.current_action_intent_id()='ACT-EVIDENCE_EXPORT_RECORDS-V1');
DROP POLICY IF EXISTS notification_routing_installer_verification ON control.notification_endpoint_verification;
CREATE POLICY notification_routing_installer_verification ON control.notification_endpoint_verification FOR SELECT TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND openpc.current_action_intent_id()='ACT-EVIDENCE_EXPORT_RECORDS-V1');
REVOKE ALL ON control.installed_notification_routing FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.installed_notification_routing TO openpc_control_runtime;
GRANT SELECT,INSERT,UPDATE ON control.installed_notification_routing TO openpc_control_owner;
DROP POLICY IF EXISTS notification_routing_installer ON control.installed_notification_routing;
CREATE POLICY notification_routing_installer ON control.installed_notification_routing TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id))
 WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id));
CREATE OR REPLACE FUNCTION openpc.guard_notification_routing_installation() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_owner','USAGE')
  OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND (OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state'))
  OR (TG_OP='INSERT' AND NEW.state<>'ACTIVE') THEN RAISE EXCEPTION 'DATA-6020-NOTIFICATION-ROUTING-IMMUTABLE'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('notification-routing:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text||':'||NEW.profile_id::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF convert_from(NEW.installation_bytes,'UTF8') IS DISTINCT FROM openpc.signing_canonical_json(NEW.installation)
  OR NEW.installation->'trust'->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR NEW.installation->'trust'->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR NEW.installation->'trust'->>'signedProfileDigest' IS DISTINCT FROM NEW.signed_profile_digest
  OR NEW.installation->>'producerTrustDigest' IS DISTINCT FROM NEW.producer_trust_digest
  OR NEW.installation->'recipientSet'->>'endpointId' IS DISTINCT FROM NEW.endpoint_id::text
 THEN RAISE EXCEPTION 'DATA-6020-NOTIFICATION-ROUTING-BINDING'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_routing_installation_guard ON control.installed_notification_routing;
CREATE TRIGGER notification_routing_installation_guard BEFORE INSERT OR UPDATE OR DELETE ON control.installed_notification_routing
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_routing_installation();


ALTER TABLE control.notification_key_preparation FORCE ROW LEVEL SECURITY;
ALTER TABLE control.notification_key_ciphertext FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification_key_preparation,control.notification_key_ciphertext FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT ON control.notification_key_preparation,control.notification_key_ciphertext TO openpc_control_runtime;
CREATE OR REPLACE FUNCTION openpc.guard_notification_key_custody() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p jsonb; i jsonb; o jsonb; source control.evidence_export_completion%ROWTYPE;
 route control.installed_notification_routing%ROWTYPE; kms control.evidence_kms_installation%ROWTYPE;
 prep control.notification_key_preparation%ROWTYPE; attempt control.evidence_kms_attempt%ROWTYPE;
 exchange control.evidence_kms_exchange%ROWTYPE; allowed text[];
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'NOTIFICATION-KEY-IMMUTABLE'; END IF;
 IF NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 IF TG_TABLE_NAME='notification_key_preparation' THEN
  p:=NEW.preparation; i:=p->'input'; o:=p->'objectIntent';
  allowed:=ARRAY['purpose','preparationId','occurrenceId','input','sourceEventId','sourceDataDigest',
    'sourceReceiptDigest','routingInstallationDigest','kms','objectIntent'];
  IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR p-allowed IS DISTINCT FROM '{}'::jsonb OR NOT p ?& allowed
  OR jsonb_typeof(i) IS DISTINCT FROM 'object'
  OR i-ARRAY['scope','evidenceExportId','producerTrustDigest','kmsInstallationDigest','routing'] IS DISTINCT FROM '{}'::jsonb
  OR NOT i ?& ARRAY['scope','evidenceExportId','producerTrustDigest','kmsInstallationDigest','routing']
  OR jsonb_typeof(i->'scope') IS DISTINCT FROM 'object'
  OR (i->'scope')-ARRAY['participantId','privacyDomainId','streamId'] IS DISTINCT FROM '{}'::jsonb
  OR NOT (i->'scope') ?& ARRAY['participantId','privacyDomainId','streamId']
  OR jsonb_typeof(i->'routing') IS DISTINCT FROM 'object'
  OR (i->'routing')-ARRAY['profileId','revision','signedProfileDigest'] IS DISTINCT FROM '{}'::jsonb
  OR NOT (i->'routing') ?& ARRAY['profileId','revision','signedProfileDigest']
  OR jsonb_typeof(o) IS DISTINCT FROM 'object'
  OR o-ARRAY['environmentId','participantId','privacyDomainId','payloadObjectId','objectVersion',
    'notificationOccurrenceRef','routingProfileDigest','templateDigest','recipientSetDigest',
    'redactionProfileDigest','preferenceGeneration','payloadDigest'] IS DISTINCT FROM '{}'::jsonb
  OR NOT o ?& ARRAY['environmentId','participantId','privacyDomainId','payloadObjectId','objectVersion',
    'notificationOccurrenceRef','routingProfileDigest','templateDigest','recipientSetDigest',
    'redactionProfileDigest','preferenceGeneration','payloadDigest']
  OR p->>'purpose' IS DISTINCT FROM 'NOTIFICATION_PAYLOAD'
  OR p->>'preparationId' IS DISTINCT FROM NEW.preparation_id::text
  OR p->>'occurrenceId' IS DISTINCT FROM NEW.occurrence_id::text
  OR p->>'sourceEventId' IS DISTINCT FROM NEW.source_event_id::text
  OR i->'scope'->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR i->'scope'->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR i->'routing'->>'profileId' IS DISTINCT FROM NEW.routing_profile_id::text
  OR i->>'kmsInstallationDigest' IS DISTINCT FROM NEW.kms_installation_digest
  OR o->>'payloadObjectId' IS DISTINCT FROM NEW.payload_object_id::text
  OR o->>'objectVersion' IS DISTINCT FROM '1'
  OR o->>'participantId' IS DISTINCT FROM NEW.participant_id::text
  OR o->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
  OR o->>'notificationOccurrenceRef' IS DISTINCT FROM 'urn:openpc:notification-occurrence:'||NEW.occurrence_id::text
  OR o->>'routingProfileDigest' IS DISTINCT FROM i->'routing'->>'signedProfileDigest'
  OR NEW.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(p),'UTF8')
  THEN RAISE EXCEPTION 'NOTIFICATION-KEY-BINDING'; END IF;
  SELECT * INTO source FROM control.evidence_export_completion WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.source_event_id;
  IF NOT FOUND OR source.evidence_export_id::text IS DISTINCT FROM i->>'evidenceExportId'
   OR source.stream_id IS DISTINCT FROM i->'scope'->>'streamId'
   OR source.trust_digest IS DISTINCT FROM i->>'producerTrustDigest'
   OR source.receipt_payload_digest IS DISTINCT FROM p->>'sourceReceiptDigest'
   OR source.claims->>'dataDigest' IS DISTINCT FROM p->>'sourceDataDigest'
  THEN RAISE EXCEPTION 'NOTIFICATION-KEY-SOURCE'; END IF;
  SELECT * INTO kms FROM control.evidence_kms_installation WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND installation_digest=NEW.kms_installation_digest;
  IF NOT FOUND OR kms.state<>'ACTIVE' OR kms.pins IS DISTINCT FROM p->'kms'
   OR kms.producer_trust_digest IS DISTINCT FROM i->>'producerTrustDigest'
   OR kms.pins->>'environmentId' IS DISTINCT FROM o->>'environmentId'
   OR NOT kms.pins->'permissions' ? 'ENCRYPT'
   OR floor(extract(epoch from clock_timestamp())*1000) NOT BETWEEN (kms.pins->>'validFromMs')::numeric AND (kms.pins->>'validUntilMs')::numeric-1
  THEN RAISE EXCEPTION 'NOTIFICATION-KEY-KMS'; END IF;
  SELECT * INTO route FROM control.installed_notification_routing WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND profile_id=NEW.routing_profile_id;
  IF NOT FOUND OR route.state<>'ACTIVE' OR route.installation_digest IS DISTINCT FROM p->>'routingInstallationDigest'
   OR route.signed_profile_digest IS DISTINCT FROM i->'routing'->>'signedProfileDigest'
   OR route.revision::text IS DISTINCT FROM i->'routing'->>'revision'
   OR route.producer_trust_digest IS DISTINCT FROM i->>'producerTrustDigest'
   OR openpc.business_cbor(decode(route.installation->'signed'->>'payloadHex','hex'))->'17'
      IS DISTINCT FROM jsonb_build_object('bytes',substring(kms.pins->>'policyDigest' from 8))
   OR route.installation->'trust'->>'environmentId' IS DISTINCT FROM o->>'environmentId'
   OR o->>'templateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(route.installation->'template'),'UTF8')),'hex')
   OR o->>'recipientSetDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(route.installation->'recipientSet'),'UTF8')),'hex')
   OR o->>'redactionProfileDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(route.installation->'redaction'),'UTF8')),'hex')
  THEN RAISE EXCEPTION 'NOTIFICATION-KEY-ROUTING'; END IF;
 ELSE
  SELECT * INTO prep FROM control.notification_key_preparation WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND preparation_id=NEW.preparation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOTIFICATION-KEY-PREPARATION'; END IF;
  SELECT * INTO attempt FROM control.evidence_kms_attempt WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.preparation_id;
  IF NOT FOUND OR attempt.state<>'PROVED' OR attempt.installation_digest<>prep.kms_installation_digest
   OR attempt.request->'objectIntent' IS DISTINCT FROM prep.preparation->'objectIntent'
   OR NOT EXISTS(SELECT 1 FROM control.evidence_wrapped_key k WHERE k.participant_id=NEW.participant_id
    AND k.privacy_domain_id=NEW.privacy_domain_id AND k.attempt_id=NEW.preparation_id AND k.key_id=NEW.key_id)
  THEN RAISE EXCEPTION 'NOTIFICATION-KEY-ORIGINAL'; END IF;
  SELECT * INTO exchange FROM control.evidence_kms_exchange WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND attempt_id=NEW.preparation_id AND exchange_id=NEW.encryption_exchange_id;
  IF NOT FOUND OR exchange.kind<>'UNWRAP'
   OR convert_from(exchange.request_bytes,'UTF8')::jsonb->>'keyUse'<>'ENCRYPT'
   OR convert_from(exchange.request_bytes,'UTF8')::jsonb->>'keyId'<>NEW.key_id
   OR NOT ((exchange.state='PROVED' AND openpc.evidence_kms_stored_outcome(exchange.receipt_bytes)='1') OR
    EXISTS(SELECT 1 FROM control.evidence_kms_exchange r WHERE r.participant_id=NEW.participant_id
     AND r.privacy_domain_id=NEW.privacy_domain_id AND r.attempt_id=NEW.preparation_id AND r.kind='READ_ATTEMPT'
     AND r.state='PROVED' AND openpc.evidence_kms_stored_outcome(r.receipt_bytes)='1'
     AND convert_from(r.request_bytes,'UTF8')::jsonb->>'readExchangeId'=exchange.exchange_id::text
     AND convert_from(r.request_bytes,'UTF8')::jsonb->>'readRequestDigest'=exchange.request_digest))
  THEN RAISE EXCEPTION 'NOTIFICATION-KEY-UNKNOWN'; END IF;
 END IF;
 RETURN NEW;
END $$;
