CREATE OR REPLACE FUNCTION openpc.check_runtime_target_fact_proof(proof jsonb)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE custody jsonb;
BEGIN
 IF proof->>'sourceMode'='FACT_FREE' THEN
  IF proof ? 'factCustody' THEN RAISE EXCEPTION 'TARGET-DISPOSITION-FACT-PROOF'; END IF;
  RETURN;
 END IF;
 custody:=proof->'factCustody';
 IF proof->>'sourceMode' IS DISTINCT FROM 'FACT_BOUND'
  OR jsonb_typeof(custody) IS DISTINCT FROM 'object'
  OR custody IS DISTINCT FROM jsonb_build_object('version',1,'capsuleDigest',custody->'capsuleDigest',
   'factStateDigest',custody->'factStateDigest','dependencyDigest',custody->'dependencyDigest',
   'originalRecordsDigest',custody->'originalRecordsDigest','validUntilNs',custody->'validUntilNs')
  OR custody->'capsuleDigest' IS DISTINCT FROM proof->'capsuleDigest'
  OR EXISTS(SELECT 1 FROM (VALUES('capsuleDigest'),('factStateDigest'),('dependencyDigest'),('originalRecordsDigest')) f(name)
   WHERE jsonb_typeof(custody->f.name) IS DISTINCT FROM 'string' OR coalesce(custody->>f.name,'') !~ '^[0-9a-f]{64}$')
  OR jsonb_typeof(custody->'validUntilNs') IS DISTINCT FROM 'string'
  OR coalesce(custody->>'validUntilNs','') !~ '^[1-9][0-9]{0,19}$'
  OR jsonb_typeof(proof->'capsuleValidUntilNs') IS DISTINCT FROM 'string'
  OR coalesce(proof->>'capsuleValidUntilNs','') !~ '^[1-9][0-9]{0,19}$'
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-FACT-PROOF'; END IF;
 IF (custody->>'validUntilNs')::numeric>18446744073709551615
  OR (proof->>'capsuleValidUntilNs')::numeric>18446744073709551615
  OR (custody->>'validUntilNs')::numeric<=extract(epoch from clock_timestamp())*1000000000
  OR (custody->>'validUntilNs')::numeric>(proof->>'capsuleValidUntilNs')::numeric
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-FACT-EXPIRY'; END IF;
END $$;
ALTER FUNCTION openpc.check_runtime_target_fact_proof(jsonb) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.check_runtime_target_fact_proof(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.check_runtime_target_fact_proof(jsonb) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.begin_runtime_target_withdrawal(
 target uuid,cause_work uuid,worker text,certificate text,wanted_previous bigint)
RETURNS TABLE(binding jsonb,admission_digest text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE pid uuid; privacy uuid; principal uuid; identity record; current_target control.runtime_target;
 cause control.configuration_work; original control.configuration_work;
 observation control.runtime_activation_observation; input control.runtime_configuration_input;
 head control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 original_inputs uuid[]; material jsonb; digest text; next_revision bigint;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR target IS NULL OR cause_work IS NULL OR coalesce(worker,'')='' OR wanted_previous IS NULL OR wanted_previous<0
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT identity FROM openpc.lock_runtime_discovery_authority(target,certificate);
 -- lock_runtime_discovery_authority holds this exact credential and its actual
 -- principal through commit. Bind the association, not merely equal epochs.
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=identity.credential_id;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-admission:'||pid::text||':'||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||pid::text||':'||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||pid::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT current_target FROM control.runtime_target t
  WHERE t.participant_id=pid AND t.privacy_domain_id=privacy AND t.runtime_target_id=target FOR SHARE;
 SELECT * INTO STRICT cause FROM control.configuration_work w
  WHERE w.participant_id=pid AND w.privacy_domain_id=privacy AND w.configuration_work_id=cause_work
   AND w.runtime_target_id=target AND w.work_kind='RUNTIME_ACTIVATION' FOR SHARE;
 -- This owner performs no provider effect and never fabricates a new attempt.
 IF cause.state<>'LEASED' OR cause.lease_owner IS DISTINCT FROM worker OR cause.lease_until<=clock_timestamp()
  OR cause.execution_started_at IS NOT NULL OR cause.execution_attempt_id IS NOT NULL
  OR cause.predecessor_digest IS NULL OR cause.predecessor_digest IS DISTINCT FROM current_target.active_generation_digest
  OR current_target.desired_generation_digest IS DISTINCT FROM cause.generation_digest
  OR current_target.state<>'STAGING'
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAUSE-UNAVAILABLE'; END IF;
 SELECT * INTO head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
  ORDER BY a.revision DESC LIMIT 1;
 IF FOUND AND head.binding->>'action'='Withdraw'
  AND head.binding->'cause'=jsonb_build_object('kind','Activation','work_id',cause.configuration_work_id::text,
   'operation_id',cause.operation_id::text,'execution_attempt_id',NULL)
 THEN
  -- Retry returns the original admission; it does not rotate identity/epochs or
  -- replace a pending delivery after a lost commit response.
  IF wanted_previous<>head.revision-1 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAS'; END IF;
  RETURN QUERY SELECT head.binding,head.admission_digest;
  RETURN;
 END IF;
 IF coalesce(head.revision,0)<>wanted_previous THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAS'; END IF;
 IF head.revision IS NOT NULL THEN
  SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d
   WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=head.revision;
  IF NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement a
   WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
    AND a.delivery_digest=delivery.delivery_digest)
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACK-PENDING'; END IF;
 END IF;
 SELECT * INTO STRICT observation FROM control.runtime_activation_observation o
  WHERE o.participant_id=pid AND o.privacy_domain_id=privacy AND o.runtime_target_id=target
   AND o.capsule_digest=current_target.active_generation_digest;
 SELECT * INTO STRICT original FROM control.configuration_work w
  WHERE w.participant_id=pid AND w.privacy_domain_id=privacy AND w.configuration_work_id=observation.configuration_work_id
   AND w.runtime_target_id=target AND w.runtime_configuration_generation_id=observation.runtime_configuration_generation_id
   AND w.operation_id=observation.operation_id AND w.execution_attempt_id=observation.execution_attempt_id
   AND w.execution_started_at IS NOT NULL AND w.work_kind='RUNTIME_ACTIVATION'
   AND w.generation_digest=observation.generation_digest AND w.xds_version_digest=observation.xds_version_digest
   AND w.state='COMPLETED' AND w.result_receipt_digest=observation.activation_receipt_digest FOR SHARE;
 SELECT array_agg(i.runtime_configuration_input_id) INTO original_inputs FROM control.runtime_configuration_input i
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
   AND i.configuration_digest=decode(substring(original.configuration_digest from 8),'hex');
 IF coalesce(cardinality(original_inputs),0)<>1 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-INPUT-CARDINALITY'; END IF;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input i
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy AND i.runtime_configuration_input_id=original_inputs[1] FOR SHARE;
 next_revision:=wanted_previous+1;
 material:=jsonb_build_object('version',1,'action','Withdraw','revision',next_revision,
  'previous_revision',wanted_previous,'previous_delivery_digest',substring(delivery.delivery_digest from 8),
  'target',jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,'target_id',target::text,
   'credential_id',identity.credential_id::text,'principal_id',principal::text,'credential_epoch',identity.credential_epoch,
   'principal_epoch',identity.principal_epoch,'certificate_digest',substring(certificate from 8)),
  'source',jsonb_build_object('runtime_configuration_input_id',input.runtime_configuration_input_id::text,
   'configuration_digest',encode(input.configuration_digest,'hex'),'module_installation_id',input.module_installation_id::text,
   'module_configuration_generation_id',input.module_configuration_generation_id::text,
   'runtime_configuration_generation_id',original.runtime_configuration_generation_id::text,
   'capsule_digest',substring(observation.capsule_digest from 8),'xds_version_digest',substring(observation.xds_version_digest from 8),
   'predecessor_capsule_digest',substring(original.predecessor_digest from 8),
   'original_work_id',original.configuration_work_id::text,'original_operation_id',original.operation_id::text,
   'original_execution_attempt_id',original.execution_attempt_id::text),
  'cause',jsonb_build_object('kind','Activation','work_id',cause.configuration_work_id::text,
   'operation_id',cause.operation_id::text,'execution_attempt_id',NULL));
 digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(material),'UTF8')),'hex');
 INSERT INTO control.runtime_target_disposition_admission(participant_id,privacy_domain_id,runtime_target_id,revision,binding,admission_digest)
 VALUES(pid,privacy,target,next_revision,material,digest);
 RETURN QUERY SELECT material,digest;
END $$;
ALTER FUNCTION openpc.begin_runtime_target_withdrawal(uuid,uuid,text,text,bigint) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.begin_runtime_target_withdrawal(uuid,uuid,text,text,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.begin_runtime_target_withdrawal(uuid,uuid,text,text,bigint) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.commit_runtime_target_disposition(
 kind text,wire bytea,nonce bytea,mac bytea)
RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE envelope jsonb; receipt_claims jsonb; identity jsonb; pid uuid; privacy uuid; target uuid; principal uuid;
 secret bytea; expected bytea; different integer:=0; wire_digest text; prior bytea; wanted_revision bigint;
 head control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 authority record; previous_sequence numeric;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR kind IS NULL OR kind NOT IN ('DELIVERY','ACK') OR wire IS NULL OR octet_length(wire) NOT BETWEEN 1 AND 16384
  OR nonce IS NULL OR octet_length(nonce)<>32 OR mac IS NULL OR octet_length(mac)<>32
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_target_disposition_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_TARGET_DISPOSITION_'||kind||'_V1','UTF8')||sha256(wire)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 envelope:=convert_from(wire,'UTF8')::jsonb; receipt_claims:=envelope->'claims'; identity:=receipt_claims->'target';
 IF envelope->>'purpose' IS DISTINCT FROM (CASE kind WHEN 'DELIVERY' THEN 'openpc:target-disposition-delivery:v1'
   ELSE 'openpc:target-disposition-acknowledgement:v1' END)
  OR envelope IS DISTINCT FROM jsonb_build_object('purpose',envelope->'purpose','claims',receipt_claims,
   'claims_digest',envelope->'claims_digest','signature_p1363_hex',envelope->'signature_p1363_hex')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 pid:=(identity->>'participant_id')::uuid; privacy:=(identity->>'privacy_domain_id')::uuid; target:=(identity->>'target_id')::uuid;
 IF pid IS DISTINCT FROM openpc.current_participant_id() OR privacy IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR target IS NULL THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,'sha256:'||(identity->>'certificate_digest'));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 IF identity IS DISTINCT FROM jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,'target_id',target::text,
  'credential_id',authority.credential_id::text,'principal_id',principal::text,'credential_epoch',authority.credential_epoch,
  'principal_epoch',authority.principal_epoch,'certificate_digest',identity->>'certificate_digest')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 wire_digest:='sha256:'||encode(sha256(wire),'hex');
 SELECT * INTO STRICT head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF kind='DELIVERY' THEN
  wanted_revision:=(receipt_claims->>'revision')::bigint;
  SELECT d.signed_delivery INTO prior FROM control.runtime_target_disposition_delivery d
   WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=wanted_revision;
  IF FOUND THEN
   IF prior IS DISTINCT FROM wire THEN RAISE EXCEPTION 'TARGET-DISPOSITION-REPLAY-CONFLICT'; END IF;
   RETURN false;
  END IF;
  IF wanted_revision<>head.revision OR receipt_claims IS DISTINCT FROM
   head.binding||jsonb_build_object('committed_admission_digest',substring(head.admission_digest from 8))
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ADMISSION'; END IF;
  INSERT INTO control.runtime_target_disposition_delivery(participant_id,privacy_domain_id,runtime_target_id,revision,
   predecessor_digest,claims,signed_delivery,delivery_digest)
  VALUES(pid,privacy,target,wanted_revision,CASE WHEN receipt_claims->>'previous_delivery_digest' IS NULL THEN NULL
   ELSE 'sha256:'||(receipt_claims->>'previous_delivery_digest') END,receipt_claims,wire,wire_digest);
 ELSE
  wanted_revision:=(receipt_claims->>'disposition_revision')::bigint;
  SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d
   WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target
    AND d.delivery_digest='sha256:'||(receipt_claims->>'delivery_digest') AND d.revision=wanted_revision;
  IF receipt_claims IS DISTINCT FROM jsonb_build_object('version',1,'target',delivery.claims->'target',
   'delivery_digest',substring(delivery.delivery_digest from 8),'disposition_revision',delivery.revision,
   'journal_sequence',receipt_claims->'journal_sequence','installed_state',(CASE delivery.claims->>'action'
    WHEN 'Withdraw' THEN 'NewUseDenied' WHEN 'Restore' THEN 'SuspensionCleared' WHEN 'ConfirmActivation' THEN 'ActivationConfirmed' END))
   OR jsonb_typeof(receipt_claims->'journal_sequence') IS DISTINCT FROM 'number'
   OR (receipt_claims->>'journal_sequence')::numeric NOT BETWEEN 1 AND 9223372036854775807
   OR (receipt_claims->>'journal_sequence')::numeric<>trunc((receipt_claims->>'journal_sequence')::numeric)
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACK-BINDING'; END IF;
  SELECT a.signed_acknowledgement INTO prior FROM control.runtime_target_disposition_acknowledgement a
   WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
    AND a.delivery_digest=delivery.delivery_digest;
  IF FOUND THEN
   IF prior IS DISTINCT FROM wire THEN RAISE EXCEPTION 'TARGET-DISPOSITION-REPLAY-CONFLICT'; END IF;
   RETURN false;
  END IF;
  IF wanted_revision<>head.revision THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAS'; END IF;
  SELECT max((a.claims->>'journal_sequence')::numeric) INTO previous_sequence
   FROM control.runtime_target_disposition_acknowledgement a
   WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target;
  IF (receipt_claims->>'journal_sequence')::numeric<=coalesce(previous_sequence,0)
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-JOURNAL-ROLLBACK'; END IF;
  INSERT INTO control.runtime_target_disposition_acknowledgement(participant_id,privacy_domain_id,runtime_target_id,
   delivery_digest,claims,signed_acknowledgement,acknowledgement_digest)
  VALUES(pid,privacy,target,delivery.delivery_digest,receipt_claims,wire,wire_digest);
 END IF;
 RETURN true;
END $$;
ALTER FUNCTION openpc.commit_runtime_target_disposition(text,bytea,bytea,bytea) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.commit_runtime_target_disposition(text,bytea,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.commit_runtime_target_disposition(text,bytea,bytea,bytea) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.lock_runtime_target_current_sources(
 target uuid,expected_source jsonb,proof jsonb,operation text)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE pid uuid; privacy uuid; original control.configuration_work;
 input control.runtime_configuration_input; binding jsonb; current_identity_expiry numeric;
 workload_principals uuid[]; workload_principal uuid; current_policy control.policy_generation;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed' OR target IS NULL
  OR jsonb_typeof(expected_source) IS DISTINCT FROM 'object' OR jsonb_typeof(proof) IS DISTINCT FROM 'object'
  OR operation IS NULL OR operation NOT IN ('RESTORE','CONFIRM')
  OR proof->>'targetId' IS DISTINCT FROM target::text
  OR proof->>'sourceMode' IS NULL OR proof->>'sourceMode' NOT IN ('FACT_FREE','FACT_BOUND')
  OR coalesce(proof->>'capsuleValidUntilNs','') !~ '^[1-9][0-9]{0,19}$'
  OR (proof->>'capsuleValidUntilNs')::numeric>18446744073709551615
  OR (proof->>'capsuleValidUntilNs')::numeric<=extract(epoch from clock_timestamp())*1000000000
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-SOURCE-CONTEXT'; END IF;
 PERFORM openpc.check_runtime_target_fact_proof(proof);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 -- All advisory fences are fail-fast before row locks. A held competing owner
 -- produces retryable contention, never an ordinary business failure or wait cycle.
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-admission:'||pid::text||':'||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||pid::text||':'||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||pid::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 -- The policy workload and the target transport are different identities.
 -- Revalidate the actual policy workload; the authenticated request still needs
 -- its own concrete credential/authority checks at the runtime decision owner.
 SELECT array_agg(DISTINCT c.principal_id ORDER BY c.principal_id) INTO workload_principals
  FROM control.credential c WHERE c.participant_id=pid AND c.kind='WORKLOAD_MTLS'
   AND c.audience=proof->>'workloadId' AND c.state='ACTIVE' AND c.credential_epoch>0
   AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp();
 IF coalesce(cardinality(workload_principals),0)<>1 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-WORKLOAD-AMBIGUOUS'; END IF;
 workload_principal:=workload_principals[1];
 PERFORM 1 FROM control.principal p WHERE p.participant_id=pid AND p.principal_id=workload_principal
  AND p.kind='WORKLOAD' AND p.state='ACTIVE' AND p.authority_epoch>0 FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-WORKLOAD-WITHDRAWN'; END IF;
 PERFORM 1 FROM control.credential c WHERE c.participant_id=pid AND c.principal_id=workload_principal
  AND c.kind='WORKLOAD_MTLS' AND c.audience=proof->>'workloadId' AND c.state='ACTIVE'
  AND c.credential_epoch>0 AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
  AND c.certificate_der IS NOT NULL AND sha256(c.certificate_der)=c.secret_fingerprint
  ORDER BY c.credential_id FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-WORKLOAD-CREDENTIAL'; END IF;
 SELECT * INTO STRICT original FROM control.configuration_work w
  WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.configuration_work_id=(expected_source->>'original_work_id')::uuid
   AND w.operation_id::text=expected_source->>'original_operation_id'
   AND w.execution_attempt_id::text=expected_source->>'original_execution_attempt_id'
   AND w.runtime_target_id=target AND w.work_kind='RUNTIME_ACTIVATION'
   AND (w.state='COMPLETED' OR (operation='CONFIRM' AND w.state IN ('LEASED','RECONCILING')))
   AND w.execution_started_at IS NOT NULL
   AND w.runtime_configuration_generation_id::text=expected_source->>'runtime_configuration_generation_id'
   AND w.configuration_digest='sha256:'||(expected_source->>'configuration_digest')
   AND w.xds_version_digest='sha256:'||(expected_source->>'xds_version_digest')
   AND w.predecessor_digest IS NOT DISTINCT FROM 'sha256:'||(expected_source->>'predecessor_capsule_digest')
   AND w.policy_generation_digest='sha256:'||(proof->>'policyGenerationDigest') FOR SHARE NOWAIT;
 PERFORM 1 FROM control.runtime_activation_observation o
  WHERE o.participant_id=pid AND o.privacy_domain_id=privacy AND o.configuration_work_id=original.configuration_work_id
   AND o.operation_id=original.operation_id AND o.execution_attempt_id=original.execution_attempt_id
   AND o.runtime_target_id=target AND o.runtime_configuration_generation_id=original.runtime_configuration_generation_id
   AND o.generation_digest=original.generation_digest AND o.xds_version_digest=original.xds_version_digest
   AND (original.state<>'COMPLETED' OR o.activation_receipt_digest=original.result_receipt_digest)
   AND encode(sha256(decode(o.activation_receipt->>'activationReceiptCoseHex','hex')),'hex')=proof->>'originalReceiptDigest'
   AND o.capsule_digest='sha256:'||(expected_source->>'capsule_digest')
   AND o.capsule_digest='sha256:'||(proof->>'capsuleDigest');
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-SOURCE-OBSERVATION'; END IF;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input i
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
   AND i.runtime_configuration_input_id=(expected_source->>'runtime_configuration_input_id')::uuid
   AND i.configuration_digest=decode(expected_source->>'configuration_digest','hex')
   AND i.module_installation_id::text=expected_source->>'module_installation_id'
   AND i.module_configuration_generation_id::text=expected_source->>'module_configuration_generation_id'
   AND i.selected FOR SHARE NOWAIT;
 -- Lock each mutable source before re-evaluating the shared canonical view.
 -- A source's signature/digest alone does not establish its current admission.
 FOR binding IN SELECT value FROM jsonb_array_elements(input.resource_bindings) ORDER BY value->>'kind',value->>'id' LOOP
  CASE binding->>'kind'
   WHEN 'ProviderProfile' THEN
    PERFORM 1 FROM control.provider_profile p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.provider_profile_id=(binding->>'id')::uuid AND p.behavior_fingerprint=binding->>'digest'
     AND p.chain_id=binding->>'chainId' AND p.state<>'RETIRED' FOR SHARE NOWAIT;
   WHEN 'ClientIndexerProfile' THEN
    PERFORM 1 FROM control.indexer_profile p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.indexer_profile_id=(binding->>'id')::uuid AND p.method_profile_digest=binding->>'digest'
     AND p.engine_version=binding->>'engineVersion' AND p.state<>'RETIRED' FOR SHARE NOWAIT;
   WHEN 'ProjectionPlan' THEN
    PERFORM 1 FROM control.projection_plan p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.projection_plan_id=(binding->>'id')::uuid AND p.plan_digest=binding->>'digest'
     AND p.state<>'RETIRED' FOR SHARE NOWAIT;
   WHEN 'CiglSettings' THEN
    PERFORM 1 FROM control.cigl_settings p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.cigl_settings_id=(binding->>'id')::uuid;
   ELSE RAISE EXCEPTION 'TARGET-DISPOSITION-SOURCE-KIND';
  END CASE;
  IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-SOURCE-RESTRICTED'; END IF;
 END LOOP;
 PERFORM 1 FROM control.runtime_configuration_input_current_metadata i
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
   AND i.runtime_configuration_input_id=input.runtime_configuration_input_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'TARGET-DISPOSITION-SOURCE-WITHDRAWN'; END IF;
 SELECT g.* INTO STRICT current_policy FROM control.policy_generation g JOIN control.policy_version v
  ON v.participant_id=g.participant_id AND v.privacy_domain_id=g.privacy_domain_id AND v.policy_version_id=g.policy_version_id
  JOIN control.policy_artifact a ON a.participant_id=g.participant_id AND a.privacy_domain_id=g.privacy_domain_id
   AND a.semantic_digest=v.semantic_digest AND a.payload_digest=g.artifact_digest
  WHERE g.participant_id=pid AND g.privacy_domain_id=privacy
   AND ((g.active AND g.state='ACTIVE') OR (operation='CONFIRM' AND EXISTS(
    SELECT 1 FROM control.policy_activation_occurrence_target ot
     JOIN control.policy_activation_occurrence oc ON oc.participant_id=ot.participant_id
      AND oc.privacy_domain_id=ot.privacy_domain_id AND oc.activation_occurrence_id=ot.activation_occurrence_id
     JOIN control.policy_activation a ON a.participant_id=oc.participant_id
      AND a.privacy_domain_id=oc.privacy_domain_id AND a.policy_activation_id=oc.activation_occurrence_id
    WHERE ot.participant_id=pid AND ot.privacy_domain_id=privacy AND ot.configuration_work_id=original.configuration_work_id
     AND ((ot.phase='FORWARD' AND oc.policy_generation_id=g.policy_generation_id AND g.state='PREPARED')
       OR (ot.phase='ROLLBACK' AND a.state='ACTIVE' AND a.prior_generation_digest=g.generation_digest AND g.state='RETIRED')))))
   AND g.generation_digest=decode(proof->>'policyGenerationDigest','hex') FOR SHARE OF g NOWAIT;
 SELECT s.expires_at_ns INTO STRICT current_identity_expiry FROM control.identity_runtime_snapshot_head h
  JOIN control.identity_runtime_snapshot s ON s.snapshot_id=h.snapshot_id AND s.participant_id=h.participant_id
   AND s.privacy_domain_id=h.privacy_domain_id AND s.target_runtime_id=h.target_runtime_id
  WHERE h.participant_id=pid AND h.privacy_domain_id=privacy AND h.target_runtime_id=target
   AND s.manifest_digest=decode(proof->>'identityManifestDigest','hex')
   AND s.expires_at_ns>extract(epoch from clock_timestamp())*1000000000 FOR SHARE OF h NOWAIT;
 -- The proof may shorten, never extend, the original Identity publication.
 IF (proof->>'capsuleValidUntilNs')::numeric>current_identity_expiry
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY-EXPIRY'; END IF;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'PC-DATA-6007';
END $$;
ALTER FUNCTION openpc.lock_runtime_target_current_sources(uuid,jsonb,jsonb,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.lock_runtime_target_current_sources(uuid,jsonb,jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.lock_runtime_target_current_sources(uuid,jsonb,jsonb,text) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.lock_runtime_target_restore_sources(
 target uuid,expected_source jsonb,proof jsonb)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
BEGIN
 PERFORM openpc.lock_runtime_target_current_sources(target,expected_source,proof,'RESTORE');
END $$;
ALTER FUNCTION openpc.lock_runtime_target_restore_sources(uuid,jsonb,jsonb) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.lock_runtime_target_restore_sources(uuid,jsonb,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.lock_runtime_target_restore_sources(uuid,jsonb,jsonb) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.begin_runtime_target_activation_confirmation(
 proof_wire bytea,nonce bytea,mac bytea)
RETURNS TABLE(binding jsonb,admission_digest text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE proof jsonb; secret bytea; expected bytea; different integer:=0; pid uuid; privacy uuid; target uuid;
 head control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 original control.configuration_work; input control.runtime_configuration_input;
 current_target control.runtime_target; source jsonb; identity jsonb; authority record; principal uuid;
 material jsonb; digest text; next_revision bigint; previous_digest text; occurrence uuid;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR proof_wire IS NULL OR octet_length(proof_wire) NOT BETWEEN 1 AND 8192
  OR nonce IS NULL OR octet_length(nonce)<>32 OR mac IS NULL OR octet_length(mac)<>32
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_target_disposition_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_TARGET_DISPOSITION_ACTIVATION_ADMISSION_V1','UTF8')||sha256(proof_wire)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 proof:=convert_from(proof_wire,'UTF8')::jsonb;
 IF proof IS DISTINCT FROM (jsonb_build_object('version',1,'transactionId',pg_current_xact_id()::text,
  'targetId',proof->'targetId','source',proof->'source','target',proof->'target',
  'capsuleDigest',proof->'capsuleDigest','capsuleValidUntilNs',proof->'capsuleValidUntilNs',
  'policyGenerationDigest',proof->'policyGenerationDigest','workloadId',proof->'workloadId',
  'identityManifestDigest',proof->'identityManifestDigest','sourceMode',proof->'sourceMode',
  'originalReceiptDigest',proof->'originalReceiptDigest','originalTokenDigest',proof->'originalTokenDigest',
  'occurrenceId',proof->'occurrenceId') || CASE WHEN proof->>'sourceMode'='FACT_BOUND'
   THEN jsonb_build_object('factCustody',proof->'factCustody') ELSE '{}'::jsonb END)
  OR jsonb_typeof(proof->'source') IS DISTINCT FROM 'object'
  OR jsonb_typeof(proof->'target') IS DISTINCT FROM 'object'
  OR coalesce(proof->>'workloadId','') !~ '^urn:openpc:workload:[A-Za-z0-9:._-]{1,140}$'
  OR coalesce(proof->>'capsuleValidUntilNs','') !~ '^[1-9][0-9]{0,19}$'
  OR (proof->>'capsuleValidUntilNs')::numeric>18446744073709551615
  OR (proof->>'capsuleValidUntilNs')::numeric<=extract(epoch from clock_timestamp())*1000000000
  OR EXISTS(SELECT 1 FROM (VALUES('capsuleDigest'),('policyGenerationDigest'),('identityManifestDigest'),
   ('originalReceiptDigest'),('originalTokenDigest')) f(name)
   WHERE jsonb_typeof(proof->f.name) IS DISTINCT FROM 'string' OR coalesce(proof->>f.name,'') !~ '^[0-9a-f]{64}$')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-PROOF'; END IF;
 PERFORM openpc.check_runtime_target_fact_proof(proof);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id(); target:=(proof->>'targetId')::uuid;
 source:=proof->'source'; identity:=proof->'target';
 PERFORM openpc.lock_runtime_target_current_sources(target,source,proof,'CONFIRM');
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,'sha256:'||(identity->>'certificate_digest'));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 IF identity IS DISTINCT FROM jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,
  'target_id',target::text,'credential_id',authority.credential_id::text,'principal_id',principal::text,
  'credential_epoch',authority.credential_epoch,'principal_epoch',authority.principal_epoch,
  'certificate_digest',identity->>'certificate_digest')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY'; END IF;
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=(source->>'original_work_id')::uuid AND w.runtime_target_id=target FOR SHARE NOWAIT;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input i WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
  AND i.runtime_configuration_input_id=(source->>'runtime_configuration_input_id')::uuid FOR SHARE NOWAIT;
 IF source IS DISTINCT FROM jsonb_build_object('runtime_configuration_input_id',input.runtime_configuration_input_id::text,
  'configuration_digest',encode(input.configuration_digest,'hex'),'module_installation_id',input.module_installation_id::text,
  'module_configuration_generation_id',input.module_configuration_generation_id::text,
  'runtime_configuration_generation_id',original.runtime_configuration_generation_id::text,
  'capsule_digest',proof->>'capsuleDigest','xds_version_digest',substring(original.xds_version_digest from 8),
  'predecessor_capsule_digest',substring(original.predecessor_digest from 8),'original_work_id',original.configuration_work_id::text,
  'original_operation_id',original.operation_id::text,'original_execution_attempt_id',original.execution_attempt_id::text)
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-SOURCE'; END IF;
 SELECT ot.activation_occurrence_id INTO occurrence FROM control.policy_activation_occurrence_target ot
  WHERE ot.participant_id=pid AND ot.privacy_domain_id=privacy AND ot.configuration_work_id=original.configuration_work_id;
 IF proof->>'occurrenceId' IS DISTINCT FROM coalesce(occurrence,original.configuration_work_id)::text
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-OCCURRENCE'; END IF;
 SELECT * INTO STRICT current_target FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target FOR SHARE NOWAIT;
 IF NOT coalesce(((original.state='COMPLETED' AND current_target.active_generation_digest='sha256:'||(proof->>'capsuleDigest'))
  OR (original.state IN ('LEASED','RECONCILING') AND current_target.active_generation_digest IS NOT DISTINCT FROM original.predecessor_digest
   AND current_target.desired_generation_digest=original.generation_digest)),false)
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-TARGET'; END IF;
 SELECT * INTO head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF NOT FOUND THEN
  IF original.predecessor_digest IS NOT NULL THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-PREDECESSOR'; END IF;
  next_revision:=1; previous_digest:=NULL;
 ELSE
  IF head.binding->>'action' IS DISTINCT FROM 'Withdraw'
   OR head.binding->'cause'->>'kind' IS DISTINCT FROM 'Activation'
   OR head.binding->'cause'->>'work_id' IS DISTINCT FROM original.configuration_work_id::text
   OR head.binding->'cause'->>'operation_id' IS DISTINCT FROM original.operation_id::text
   OR (head.binding->'cause'->>'execution_attempt_id' IS NOT NULL
    AND head.binding->'cause'->>'execution_attempt_id' IS DISTINCT FROM original.execution_attempt_id::text)
   OR original.predecessor_digest IS DISTINCT FROM 'sha256:'||(head.binding->'source'->>'capsule_digest')
   OR head.binding->'source'->>'capsule_digest' IS NOT DISTINCT FROM proof->>'capsuleDigest'
   OR head.binding->'source'->>'original_work_id' IS NOT DISTINCT FROM original.configuration_work_id::text
   OR head.binding->'target' IS DISTINCT FROM identity
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-PREDECESSOR'; END IF;
  SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d
   WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=head.revision;
  IF NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement a
   WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
    AND a.delivery_digest=delivery.delivery_digest AND a.claims->>'installed_state'='NewUseDenied')
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACK-PENDING'; END IF;
  next_revision:=head.revision+1; previous_digest:=substring(delivery.delivery_digest from 8);
 END IF;
 material:=jsonb_build_object('version',1,'target',identity,'source',source,'action','ConfirmActivation',
  'cause',jsonb_build_object('kind','Activation','work_id',original.configuration_work_id::text,
   'operation_id',original.operation_id::text,'execution_attempt_id',original.execution_attempt_id::text),
  'revision',next_revision,'previous_revision',next_revision-1,'previous_delivery_digest',previous_digest);
 digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object('binding',material,'activationProof',proof)),'UTF8')),'hex');
 INSERT INTO control.runtime_target_disposition_admission(participant_id,privacy_domain_id,runtime_target_id,revision,binding,activation_proof,admission_digest)
 VALUES(pid,privacy,target,next_revision,material,proof,digest);
 RETURN QUERY SELECT material,digest;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'PC-DATA-6007';
END $$;
ALTER FUNCTION openpc.begin_runtime_target_activation_confirmation(bytea,bytea,bytea) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.begin_runtime_target_activation_confirmation(bytea,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.begin_runtime_target_activation_confirmation(bytea,bytea,bytea) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.begin_runtime_target_unstarted_restore(
 proof_wire bytea,nonce bytea,mac bytea)
RETURNS TABLE(binding jsonb,admission_digest text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE proof jsonb; secret bytea; expected bytea; different integer:=0; pid uuid; privacy uuid; target uuid;
 head control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 cause control.configuration_work; original control.configuration_work; current_target control.runtime_target;
 material jsonb; digest text; identity record; principal uuid;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR proof_wire IS NULL OR octet_length(proof_wire) NOT BETWEEN 1 AND 8192
  OR nonce IS NULL OR octet_length(nonce)<>32 OR mac IS NULL OR octet_length(mac)<>32
  OR current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_target_disposition_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to('OPENPC_TARGET_DISPOSITION_RESTORE_ADMISSION_V1','UTF8')||sha256(proof_wire)||nonce,secret,'sha256');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 proof:=convert_from(proof_wire,'UTF8')::jsonb;
 IF proof IS DISTINCT FROM (jsonb_build_object('version',1,'transactionId',pg_current_xact_id()::text,
  'targetId',proof->'targetId','withdrawalDigest',proof->'withdrawalDigest',
  'capsuleDigest',proof->'capsuleDigest','capsuleValidUntilNs',proof->'capsuleValidUntilNs',
  'policyGenerationDigest',proof->'policyGenerationDigest','workloadId',proof->'workloadId',
  'identityManifestDigest',proof->'identityManifestDigest','sourceMode',proof->'sourceMode',
  'originalReceiptDigest',proof->'originalReceiptDigest','originalTokenDigest',proof->'originalTokenDigest') || CASE WHEN proof->>'sourceMode'='FACT_BOUND'
   THEN jsonb_build_object('factCustody',proof->'factCustody') ELSE '{}'::jsonb END)
  OR jsonb_typeof(proof->'targetId') IS DISTINCT FROM 'string'
  OR jsonb_typeof(proof->'workloadId') IS DISTINCT FROM 'string'
  OR coalesce(proof->>'workloadId','') !~ '^urn:openpc:workload:[A-Za-z0-9:._-]{1,140}$'
  OR jsonb_typeof(proof->'capsuleValidUntilNs') IS DISTINCT FROM 'string'
  OR coalesce(proof->>'capsuleValidUntilNs','') !~ '^[1-9][0-9]{0,19}$'
  OR (proof->>'capsuleValidUntilNs')::numeric>18446744073709551615
  OR (proof->>'capsuleValidUntilNs')::numeric<=extract(epoch from clock_timestamp())*1000000000
  OR EXISTS(SELECT 1 FROM (VALUES('withdrawalDigest'),('capsuleDigest'),('policyGenerationDigest'),
    ('identityManifestDigest'),('originalReceiptDigest'),('originalTokenDigest')) f(name)
    WHERE jsonb_typeof(proof->f.name) IS DISTINCT FROM 'string' OR coalesce(proof->>f.name,'') !~ '^[0-9a-f]{64}$')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-RESTORE-PROOF'; END IF;
 PERFORM openpc.check_runtime_target_fact_proof(proof);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id(); target:=(proof->>'targetId')::uuid;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF head.binding->>'action'<>'Withdraw' OR head.binding->'cause'->>'kind'<>'Activation'
  OR head.binding->'source'->>'capsule_digest' IS DISTINCT FROM proof->>'capsuleDigest'
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-RESTORE-HEAD'; END IF;
 SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d
  WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target
   AND d.revision=head.revision AND d.delivery_digest='sha256:'||(proof->>'withdrawalDigest');
 IF NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
   AND a.delivery_digest=delivery.delivery_digest AND a.claims->>'installed_state'='NewUseDenied')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACK-PENDING'; END IF;
 SELECT * INTO STRICT identity FROM openpc.lock_runtime_discovery_authority(target,
  'sha256:'||(head.binding->'target'->>'certificate_digest'));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c WHERE c.participant_id=pid AND c.credential_id=identity.credential_id;
 IF head.binding->'target' IS DISTINCT FROM jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,
  'target_id',target::text,'credential_id',identity.credential_id::text,'principal_id',principal::text,
  'credential_epoch',identity.credential_epoch,'principal_epoch',identity.principal_epoch,
  'certificate_digest',head.binding->'target'->>'certificate_digest')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY'; END IF;
 SELECT * INTO STRICT cause FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=(head.binding->'cause'->>'work_id')::uuid AND w.runtime_target_id=target FOR SHARE;
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=(head.binding->'source'->>'original_work_id')::uuid AND w.runtime_target_id=target FOR SHARE;
 SELECT * INTO STRICT current_target FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target FOR SHARE;
 IF cause.state<>'FAILED' OR cause.execution_started_at IS NOT NULL OR cause.execution_attempt_id IS NOT NULL
  OR cause.work_kind<>'RUNTIME_ACTIVATION' OR cause.completed_at IS NULL
  OR cause.operation_id::text IS DISTINCT FROM head.binding->'cause'->>'operation_id'
  OR head.binding->'cause'->'execution_attempt_id' IS DISTINCT FROM 'null'::jsonb
  OR original.state<>'COMPLETED' OR original.work_kind<>'RUNTIME_ACTIVATION'
  OR original.policy_generation_digest IS DISTINCT FROM 'sha256:'||(proof->>'policyGenerationDigest')
  OR original.result_receipt->>'activationReceiptCoseHex' IS NULL
  OR encode(sha256(decode(original.result_receipt->>'activationReceiptCoseHex','hex')),'hex') IS DISTINCT FROM proof->>'originalReceiptDigest'
  OR current_target.active_generation_digest IS DISTINCT FROM 'sha256:'||(proof->>'capsuleDigest')
  OR current_target.desired_generation_digest IS DISTINCT FROM cause.generation_digest OR current_target.state<>'FAILED'
  OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.runtime_target_id=target AND w.work_kind='RUNTIME_ACTIVATION' AND w.state IN ('PENDING','LEASED','RECONCILING'))
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-RESTORE-CAUSE'; END IF;
 PERFORM openpc.lock_runtime_target_restore_sources(target,head.binding->'source',proof);
 material:=head.binding||jsonb_build_object('action','Restore','revision',head.revision+1,
  'previous_revision',head.revision,'previous_delivery_digest',substring(delivery.delivery_digest from 8));
 digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object('binding',material,'restorationProof',proof)),'UTF8')),'hex');
 INSERT INTO control.runtime_target_disposition_admission(participant_id,privacy_domain_id,runtime_target_id,revision,binding,restoration_proof,admission_digest)
 VALUES(pid,privacy,target,head.revision+1,material,proof,digest);
 RETURN QUERY SELECT material,digest;
END $$;
ALTER FUNCTION openpc.begin_runtime_target_unstarted_restore(bytea,bytea,bytea) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.begin_runtime_target_unstarted_restore(bytea,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.begin_runtime_target_unstarted_restore(bytea,bytea,bytea) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.lock_runtime_target_disposition_issuance(
 target uuid,wanted_revision bigint,wanted_digest text,worker text)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE pid uuid; privacy uuid; head control.runtime_target_disposition_admission; latest text;
 original control.configuration_work; cause control.configuration_work; current_target control.runtime_target;
 authority record; principal uuid; proof jsonb; action text;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>'ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1'
  OR current_setting('transaction_isolation')<>'read committed' OR target IS NULL
  OR wanted_revision IS NULL OR wanted_revision<1 OR wanted_digest IS NULL
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-CONTEXT'; END IF;
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
  ORDER BY a.revision DESC LIMIT 1;
 IF head.revision IS DISTINCT FROM wanted_revision OR head.admission_digest IS DISTINCT FROM wanted_digest
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-HEAD'; END IF;
 action:=head.binding->>'action';
 IF action IN ('ConfirmActivation','Restore') THEN
  IF worker IS NOT NULL THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-CONTEXT'; END IF;
  proof:=CASE action WHEN 'ConfirmActivation' THEN head.activation_proof ELSE head.restoration_proof END;
  PERFORM openpc.lock_runtime_target_current_sources(target,head.binding->'source',proof,
   CASE action WHEN 'ConfirmActivation' THEN 'CONFIRM' ELSE 'RESTORE' END);
 ELSIF action='Withdraw' THEN
  IF coalesce(worker,'')='' THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-CONTEXT'; END IF;
  IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-admission:'||pid::text||':'||privacy::text,0))
   OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||pid::text||':'||privacy::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||pid::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended('runtime-target-disposition:'||pid::text||':'||privacy::text||':'||target::text,0))
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSE RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-ACTION'; END IF;
 -- Re-read only after the original Control fences have been reacquired.
 SELECT admission_digest INTO STRICT latest FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
  ORDER BY a.revision DESC LIMIT 1;
 IF latest IS DISTINCT FROM wanted_digest THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-HEAD'; END IF;
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,
  'sha256:'||(head.binding->'target'->>'certificate_digest'));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 IF head.binding->'target' IS DISTINCT FROM jsonb_build_object('participant_id',pid::text,'privacy_domain_id',privacy::text,
  'target_id',target::text,'credential_id',authority.credential_id::text,'principal_id',principal::text,
  'credential_epoch',authority.credential_epoch,'principal_epoch',authority.principal_epoch,
  'certificate_digest',head.binding->'target'->>'certificate_digest')
 THEN RAISE EXCEPTION 'TARGET-DISPOSITION-IDENTITY'; END IF;
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.runtime_target_id=target AND w.configuration_work_id=(head.binding->'source'->>'original_work_id')::uuid FOR SHARE NOWAIT;
 SELECT * INTO STRICT current_target FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target FOR SHARE NOWAIT;
 IF action='ConfirmActivation' THEN
  IF NOT coalesce(((original.state='COMPLETED' AND current_target.active_generation_digest='sha256:'||(proof->>'capsuleDigest'))
   OR (original.state IN ('LEASED','RECONCILING') AND current_target.active_generation_digest IS NOT DISTINCT FROM original.predecessor_digest
    AND current_target.desired_generation_digest=original.generation_digest)),false)
   OR head.binding->'cause' IS DISTINCT FROM jsonb_build_object('kind','Activation','work_id',original.configuration_work_id::text,
    'operation_id',original.operation_id::text,'execution_attempt_id',original.execution_attempt_id::text)
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ACTIVATION-TARGET'; END IF;
 ELSE
  SELECT * INTO STRICT cause FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.runtime_target_id=target AND w.configuration_work_id=(head.binding->'cause'->>'work_id')::uuid FOR SHARE NOWAIT;
  IF cause.work_kind<>'RUNTIME_ACTIVATION' OR cause.execution_started_at IS NOT NULL OR cause.execution_attempt_id IS NOT NULL
   OR cause.operation_id::text IS DISTINCT FROM head.binding->'cause'->>'operation_id'
   OR head.binding->'cause'->>'kind' IS DISTINCT FROM 'Activation'
   OR head.binding->'cause'->'execution_attempt_id' IS DISTINCT FROM 'null'::jsonb
   OR original.state<>'COMPLETED' OR original.work_kind<>'RUNTIME_ACTIVATION'
   OR original.operation_id::text IS DISTINCT FROM head.binding->'source'->>'original_operation_id'
   OR original.execution_attempt_id::text IS DISTINCT FROM head.binding->'source'->>'original_execution_attempt_id'
   OR current_target.active_generation_digest IS DISTINCT FROM 'sha256:'||(head.binding->'source'->>'capsule_digest')
   OR current_target.desired_generation_digest IS DISTINCT FROM cause.generation_digest
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-ISSUANCE-CAUSE'; END IF;
  IF action='Restore' THEN
   IF cause.state<>'FAILED' OR cause.completed_at IS NULL OR current_target.state<>'FAILED'
    OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
     AND w.runtime_target_id=target AND w.work_kind='RUNTIME_ACTIVATION' AND w.state IN ('PENDING','LEASED','RECONCILING'))
   THEN RAISE EXCEPTION 'TARGET-DISPOSITION-RESTORE-CAUSE'; END IF;
  ELSIF cause.state<>'LEASED' OR cause.lease_owner IS DISTINCT FROM worker OR cause.lease_until<=clock_timestamp()
   OR cause.predecessor_digest IS DISTINCT FROM current_target.active_generation_digest OR current_target.state<>'STAGING'
  THEN RAISE EXCEPTION 'TARGET-DISPOSITION-CAUSE-UNAVAILABLE'; END IF;
 END IF;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'PC-DATA-6007';
END $$;
ALTER FUNCTION openpc.lock_runtime_target_disposition_issuance(uuid,bigint,text,text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.lock_runtime_target_disposition_issuance(uuid,bigint,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.lock_runtime_target_disposition_issuance(uuid,bigint,text,text) TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.assert_runtime_target_disposition_owner() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF current_setting('session_replication_role')<>'origin' OR current_setting('row_security')<>'on'
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.lock_runtime_target_disposition_issuance(uuid,bigint,text,text)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']
   AND p.prosrc='
DECLARE pid uuid; privacy uuid; head control.runtime_target_disposition_admission; latest text;
 original control.configuration_work; cause control.configuration_work; current_target control.runtime_target;
 authority record; principal uuid; proof jsonb; action text;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>''ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1''
  OR current_setting(''transaction_isolation'')<>''read committed'' OR target IS NULL
  OR wanted_revision IS NULL OR wanted_revision<1 OR wanted_digest IS NULL
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-CONTEXT''; END IF;
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 SELECT * INTO STRICT head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
  ORDER BY a.revision DESC LIMIT 1;
 IF head.revision IS DISTINCT FROM wanted_revision OR head.admission_digest IS DISTINCT FROM wanted_digest
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-HEAD''; END IF;
 action:=head.binding->>''action'';
 IF action IN (''ConfirmActivation'',''Restore'') THEN
  IF worker IS NOT NULL THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-CONTEXT''; END IF;
  proof:=CASE action WHEN ''ConfirmActivation'' THEN head.activation_proof ELSE head.restoration_proof END;
  PERFORM openpc.lock_runtime_target_current_sources(target,head.binding->''source'',proof,
   CASE action WHEN ''ConfirmActivation'' THEN ''CONFIRM'' ELSE ''RESTORE'' END);
 ELSIF action=''Withdraw'' THEN
  IF coalesce(worker,'''')='''' THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-CONTEXT''; END IF;
  IF NOT pg_try_advisory_xact_lock_shared(hashtextextended(''module-admission:''||pid::text||'':''||privacy::text,0))
   OR NOT pg_try_advisory_xact_lock_shared(hashtextextended(''openpc-policy-generations:''||pid::text||'':''||privacy::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended(''evidence-lifecycle:''||pid::text,0))
   OR NOT pg_try_advisory_xact_lock(hashtextextended(''runtime-target-disposition:''||pid::text||'':''||privacy::text||'':''||target::text,0))
  THEN RAISE EXCEPTION ''PC-DATA-6007''; END IF;
 ELSE RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-ACTION''; END IF;
 -- Re-read only after the original Control fences have been reacquired.
 SELECT admission_digest INTO STRICT latest FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
  ORDER BY a.revision DESC LIMIT 1;
 IF latest IS DISTINCT FROM wanted_digest THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-HEAD''; END IF;
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,
  ''sha256:''||(head.binding->''target''->>''certificate_digest''));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c
  WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 IF head.binding->''target'' IS DISTINCT FROM jsonb_build_object(''participant_id'',pid::text,''privacy_domain_id'',privacy::text,
  ''target_id'',target::text,''credential_id'',authority.credential_id::text,''principal_id'',principal::text,
  ''credential_epoch'',authority.credential_epoch,''principal_epoch'',authority.principal_epoch,
  ''certificate_digest'',head.binding->''target''->>''certificate_digest'')
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-IDENTITY''; END IF;
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.runtime_target_id=target AND w.configuration_work_id=(head.binding->''source''->>''original_work_id'')::uuid FOR SHARE NOWAIT;
 SELECT * INTO STRICT current_target FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target FOR SHARE NOWAIT;
 IF action=''ConfirmActivation'' THEN
  IF NOT coalesce(((original.state=''COMPLETED'' AND current_target.active_generation_digest=''sha256:''||(proof->>''capsuleDigest''))
   OR (original.state IN (''LEASED'',''RECONCILING'') AND current_target.active_generation_digest IS NOT DISTINCT FROM original.predecessor_digest
    AND current_target.desired_generation_digest=original.generation_digest)),false)
   OR head.binding->''cause'' IS DISTINCT FROM jsonb_build_object(''kind'',''Activation'',''work_id'',original.configuration_work_id::text,
    ''operation_id'',original.operation_id::text,''execution_attempt_id'',original.execution_attempt_id::text)
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACTIVATION-TARGET''; END IF;
 ELSE
  SELECT * INTO STRICT cause FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.runtime_target_id=target AND w.configuration_work_id=(head.binding->''cause''->>''work_id'')::uuid FOR SHARE NOWAIT;
  IF cause.work_kind<>''RUNTIME_ACTIVATION'' OR cause.execution_started_at IS NOT NULL OR cause.execution_attempt_id IS NOT NULL
   OR cause.operation_id::text IS DISTINCT FROM head.binding->''cause''->>''operation_id''
   OR head.binding->''cause''->>''kind'' IS DISTINCT FROM ''Activation''
   OR head.binding->''cause''->''execution_attempt_id'' IS DISTINCT FROM ''null''::jsonb
   OR original.state<>''COMPLETED'' OR original.work_kind<>''RUNTIME_ACTIVATION''
   OR original.operation_id::text IS DISTINCT FROM head.binding->''source''->>''original_operation_id''
   OR original.execution_attempt_id::text IS DISTINCT FROM head.binding->''source''->>''original_execution_attempt_id''
   OR current_target.active_generation_digest IS DISTINCT FROM ''sha256:''||(head.binding->''source''->>''capsule_digest'')
   OR current_target.desired_generation_digest IS DISTINCT FROM cause.generation_digest
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ISSUANCE-CAUSE''; END IF;
  IF action=''Restore'' THEN
   IF cause.state<>''FAILED'' OR cause.completed_at IS NULL OR current_target.state<>''FAILED''
    OR EXISTS(SELECT 1 FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
     AND w.runtime_target_id=target AND w.work_kind=''RUNTIME_ACTIVATION'' AND w.state IN (''PENDING'',''LEASED'',''RECONCILING''))
   THEN RAISE EXCEPTION ''TARGET-DISPOSITION-RESTORE-CAUSE''; END IF;
  ELSIF cause.state<>''LEASED'' OR cause.lease_owner IS DISTINCT FROM worker OR cause.lease_until<=clock_timestamp()
   OR cause.predecessor_digest IS DISTINCT FROM current_target.active_generation_digest OR current_target.state<>''STAGING''
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-CAUSE-UNAVAILABLE''; END IF;
 END IF;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION ''PC-DATA-6007'';
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.check_runtime_target_fact_proof(jsonb)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=false
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog']
   AND p.prosrc='
DECLARE custody jsonb;
BEGIN
 IF proof->>''sourceMode''=''FACT_FREE'' THEN
  IF proof ? ''factCustody'' THEN RAISE EXCEPTION ''TARGET-DISPOSITION-FACT-PROOF''; END IF;
  RETURN;
 END IF;
 custody:=proof->''factCustody'';
 IF proof->>''sourceMode'' IS DISTINCT FROM ''FACT_BOUND''
  OR jsonb_typeof(custody) IS DISTINCT FROM ''object''
  OR custody IS DISTINCT FROM jsonb_build_object(''version'',1,''capsuleDigest'',custody->''capsuleDigest'',
   ''factStateDigest'',custody->''factStateDigest'',''dependencyDigest'',custody->''dependencyDigest'',
   ''originalRecordsDigest'',custody->''originalRecordsDigest'',''validUntilNs'',custody->''validUntilNs'')
  OR custody->''capsuleDigest'' IS DISTINCT FROM proof->''capsuleDigest''
  OR EXISTS(SELECT 1 FROM (VALUES(''capsuleDigest''),(''factStateDigest''),(''dependencyDigest''),(''originalRecordsDigest'')) f(name)
   WHERE jsonb_typeof(custody->f.name) IS DISTINCT FROM ''string'' OR coalesce(custody->>f.name,'''') !~ ''^[0-9a-f]{64}$'')
  OR jsonb_typeof(custody->''validUntilNs'') IS DISTINCT FROM ''string''
  OR coalesce(custody->>''validUntilNs'','''') !~ ''^[1-9][0-9]{0,19}$''
  OR jsonb_typeof(proof->''capsuleValidUntilNs'') IS DISTINCT FROM ''string''
  OR coalesce(proof->>''capsuleValidUntilNs'','''') !~ ''^[1-9][0-9]{0,19}$''
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-FACT-PROOF''; END IF;
 IF (custody->>''validUntilNs'')::numeric>18446744073709551615
  OR (proof->>''capsuleValidUntilNs'')::numeric>18446744073709551615
  OR (custody->>''validUntilNs'')::numeric<=extract(epoch from clock_timestamp())*1000000000
  OR (custody->>''validUntilNs'')::numeric>(proof->>''capsuleValidUntilNs'')::numeric
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-FACT-EXPIRY''; END IF;
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.begin_runtime_target_activation_confirmation(bytea,bytea,bytea)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']
   AND p.prosrc='
DECLARE proof jsonb; secret bytea; expected bytea; different integer:=0; pid uuid; privacy uuid; target uuid;
 head control.runtime_target_disposition_admission; delivery control.runtime_target_disposition_delivery;
 original control.configuration_work; input control.runtime_configuration_input;
 current_target control.runtime_target; source jsonb; identity jsonb; authority record; principal uuid;
 material jsonb; digest text; next_revision bigint; previous_digest text; occurrence uuid;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>''ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1''
  OR proof_wire IS NULL OR octet_length(proof_wire) NOT BETWEEN 1 AND 8192
  OR nonce IS NULL OR octet_length(nonce)<>32 OR mac IS NULL OR octet_length(mac)<>32
  OR current_setting(''transaction_isolation'')<>''read committed''
 THEN RAISE EXCEPTION ''PC-AUTH-0005''; END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.runtime_target_disposition_key WHERE database_role=session_user;
 expected:=public.hmac(convert_to(''OPENPC_TARGET_DISPOSITION_ACTIVATION_ADMISSION_V1'',''UTF8'')||sha256(proof_wire)||nonce,secret,''sha256'');
 FOR i IN 0..31 LOOP different:=different | (get_byte(expected,i) # get_byte(mac,i)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION ''PC-AUTH-0005''; END IF;
 proof:=convert_from(proof_wire,''UTF8'')::jsonb;
 IF proof IS DISTINCT FROM (jsonb_build_object(''version'',1,''transactionId'',pg_current_xact_id()::text,
  ''targetId'',proof->''targetId'',''source'',proof->''source'',''target'',proof->''target'',
  ''capsuleDigest'',proof->''capsuleDigest'',''capsuleValidUntilNs'',proof->''capsuleValidUntilNs'',
  ''policyGenerationDigest'',proof->''policyGenerationDigest'',''workloadId'',proof->''workloadId'',
  ''identityManifestDigest'',proof->''identityManifestDigest'',''sourceMode'',proof->''sourceMode'',
  ''originalReceiptDigest'',proof->''originalReceiptDigest'',''originalTokenDigest'',proof->''originalTokenDigest'',
  ''occurrenceId'',proof->''occurrenceId'') || CASE WHEN proof->>''sourceMode''=''FACT_BOUND''
   THEN jsonb_build_object(''factCustody'',proof->''factCustody'') ELSE ''{}''::jsonb END)
  OR jsonb_typeof(proof->''source'') IS DISTINCT FROM ''object''
  OR jsonb_typeof(proof->''target'') IS DISTINCT FROM ''object''
  OR coalesce(proof->>''workloadId'','''') !~ ''^urn:openpc:workload:[A-Za-z0-9:._-]{1,140}$''
  OR coalesce(proof->>''capsuleValidUntilNs'','''') !~ ''^[1-9][0-9]{0,19}$''
  OR (proof->>''capsuleValidUntilNs'')::numeric>18446744073709551615
  OR (proof->>''capsuleValidUntilNs'')::numeric<=extract(epoch from clock_timestamp())*1000000000
  OR EXISTS(SELECT 1 FROM (VALUES(''capsuleDigest''),(''policyGenerationDigest''),(''identityManifestDigest''),
   (''originalReceiptDigest''),(''originalTokenDigest'')) f(name)
   WHERE jsonb_typeof(proof->f.name) IS DISTINCT FROM ''string'' OR coalesce(proof->>f.name,'''') !~ ''^[0-9a-f]{64}$'')
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACTIVATION-PROOF''; END IF;
 PERFORM openpc.check_runtime_target_fact_proof(proof);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id(); target:=(proof->>''targetId'')::uuid;
 source:=proof->''source''; identity:=proof->''target'';
 PERFORM openpc.lock_runtime_target_current_sources(target,source,proof,''CONFIRM'');
 SELECT * INTO STRICT authority FROM openpc.lock_runtime_discovery_authority(target,''sha256:''||(identity->>''certificate_digest''));
 SELECT c.principal_id INTO STRICT principal FROM control.credential c WHERE c.participant_id=pid AND c.credential_id=authority.credential_id;
 IF identity IS DISTINCT FROM jsonb_build_object(''participant_id'',pid::text,''privacy_domain_id'',privacy::text,
  ''target_id'',target::text,''credential_id'',authority.credential_id::text,''principal_id'',principal::text,
  ''credential_epoch'',authority.credential_epoch,''principal_epoch'',authority.principal_epoch,
  ''certificate_digest'',identity->>''certificate_digest'')
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-IDENTITY''; END IF;
 SELECT * INTO STRICT original FROM control.configuration_work w WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
  AND w.configuration_work_id=(source->>''original_work_id'')::uuid AND w.runtime_target_id=target FOR SHARE NOWAIT;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input i WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
  AND i.runtime_configuration_input_id=(source->>''runtime_configuration_input_id'')::uuid FOR SHARE NOWAIT;
 IF source IS DISTINCT FROM jsonb_build_object(''runtime_configuration_input_id'',input.runtime_configuration_input_id::text,
  ''configuration_digest'',encode(input.configuration_digest,''hex''),''module_installation_id'',input.module_installation_id::text,
  ''module_configuration_generation_id'',input.module_configuration_generation_id::text,
  ''runtime_configuration_generation_id'',original.runtime_configuration_generation_id::text,
  ''capsule_digest'',proof->>''capsuleDigest'',''xds_version_digest'',substring(original.xds_version_digest from 8),
  ''predecessor_capsule_digest'',substring(original.predecessor_digest from 8),''original_work_id'',original.configuration_work_id::text,
  ''original_operation_id'',original.operation_id::text,''original_execution_attempt_id'',original.execution_attempt_id::text)
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACTIVATION-SOURCE''; END IF;
 SELECT ot.activation_occurrence_id INTO occurrence FROM control.policy_activation_occurrence_target ot
  WHERE ot.participant_id=pid AND ot.privacy_domain_id=privacy AND ot.configuration_work_id=original.configuration_work_id;
 IF proof->>''occurrenceId'' IS DISTINCT FROM coalesce(occurrence,original.configuration_work_id)::text
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACTIVATION-OCCURRENCE''; END IF;
 SELECT * INTO STRICT current_target FROM control.runtime_target t WHERE t.participant_id=pid AND t.privacy_domain_id=privacy
  AND t.runtime_target_id=target FOR SHARE NOWAIT;
 IF NOT coalesce(((original.state=''COMPLETED'' AND current_target.active_generation_digest=''sha256:''||(proof->>''capsuleDigest''))
  OR (original.state IN (''LEASED'',''RECONCILING'') AND current_target.active_generation_digest IS NOT DISTINCT FROM original.predecessor_digest
   AND current_target.desired_generation_digest=original.generation_digest)),false)
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACTIVATION-TARGET''; END IF;
 SELECT * INTO head FROM control.runtime_target_disposition_admission a
  WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target ORDER BY a.revision DESC LIMIT 1;
 IF NOT FOUND THEN
  IF original.predecessor_digest IS NOT NULL THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACTIVATION-PREDECESSOR''; END IF;
  next_revision:=1; previous_digest:=NULL;
 ELSE
  IF head.binding->>''action'' IS DISTINCT FROM ''Withdraw''
   OR head.binding->''cause''->>''kind'' IS DISTINCT FROM ''Activation''
   OR head.binding->''cause''->>''work_id'' IS DISTINCT FROM original.configuration_work_id::text
   OR head.binding->''cause''->>''operation_id'' IS DISTINCT FROM original.operation_id::text
   OR (head.binding->''cause''->>''execution_attempt_id'' IS NOT NULL
    AND head.binding->''cause''->>''execution_attempt_id'' IS DISTINCT FROM original.execution_attempt_id::text)
   OR original.predecessor_digest IS DISTINCT FROM ''sha256:''||(head.binding->''source''->>''capsule_digest'')
   OR head.binding->''source''->>''capsule_digest'' IS NOT DISTINCT FROM proof->>''capsuleDigest''
   OR head.binding->''source''->>''original_work_id'' IS NOT DISTINCT FROM original.configuration_work_id::text
   OR head.binding->''target'' IS DISTINCT FROM identity
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACTIVATION-PREDECESSOR''; END IF;
  SELECT * INTO STRICT delivery FROM control.runtime_target_disposition_delivery d
   WHERE d.participant_id=pid AND d.privacy_domain_id=privacy AND d.runtime_target_id=target AND d.revision=head.revision;
  IF NOT EXISTS(SELECT 1 FROM control.runtime_target_disposition_acknowledgement a
   WHERE a.participant_id=pid AND a.privacy_domain_id=privacy AND a.runtime_target_id=target
    AND a.delivery_digest=delivery.delivery_digest AND a.claims->>''installed_state''=''NewUseDenied'')
  THEN RAISE EXCEPTION ''TARGET-DISPOSITION-ACK-PENDING''; END IF;
  next_revision:=head.revision+1; previous_digest:=substring(delivery.delivery_digest from 8);
 END IF;
 material:=jsonb_build_object(''version'',1,''target'',identity,''source'',source,''action'',''ConfirmActivation'',
  ''cause'',jsonb_build_object(''kind'',''Activation'',''work_id'',original.configuration_work_id::text,
   ''operation_id'',original.operation_id::text,''execution_attempt_id'',original.execution_attempt_id::text),
  ''revision'',next_revision,''previous_revision'',next_revision-1,''previous_delivery_digest'',previous_digest);
 digest:=''sha256:''||encode(sha256(convert_to(openpc.signing_canonical_json(
  jsonb_build_object(''binding'',material,''activationProof'',proof)),''UTF8'')),''hex'');
 INSERT INTO control.runtime_target_disposition_admission(participant_id,privacy_domain_id,runtime_target_id,revision,binding,activation_proof,admission_digest)
 VALUES(pid,privacy,target,next_revision,material,proof,digest);
 RETURN QUERY SELECT material,digest;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION ''PC-DATA-6007'';
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.lock_runtime_target_current_sources(uuid,jsonb,jsonb,text)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
   AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog','row_security=on']
   AND p.prosrc='
DECLARE pid uuid; privacy uuid; original control.configuration_work;
 input control.runtime_configuration_input; binding jsonb; current_identity_expiry numeric;
 workload_principals uuid[]; workload_principal uuid; current_policy control.policy_generation;
BEGIN
 PERFORM openpc.assert_runtime_target_disposition_owner();
 PERFORM openpc.assert_request_context(true);
 IF openpc.current_action_intent_id()<>''ACT-RUNTIME_CONFIGURATION_GENERATIONS_ACTIVATE_RESOURCE-V1''
  OR current_setting(''transaction_isolation'')<>''read committed'' OR target IS NULL
  OR jsonb_typeof(expected_source) IS DISTINCT FROM ''object'' OR jsonb_typeof(proof) IS DISTINCT FROM ''object''
  OR operation IS NULL OR operation NOT IN (''RESTORE'',''CONFIRM'')
  OR proof->>''targetId'' IS DISTINCT FROM target::text
  OR proof->>''sourceMode'' IS NULL OR proof->>''sourceMode'' NOT IN (''FACT_FREE'',''FACT_BOUND'')
  OR coalesce(proof->>''capsuleValidUntilNs'','''') !~ ''^[1-9][0-9]{0,19}$''
  OR (proof->>''capsuleValidUntilNs'')::numeric>18446744073709551615
  OR (proof->>''capsuleValidUntilNs'')::numeric<=extract(epoch from clock_timestamp())*1000000000
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-SOURCE-CONTEXT''; END IF;
 PERFORM openpc.check_runtime_target_fact_proof(proof);
 pid:=openpc.current_participant_id(); privacy:=openpc.current_privacy_domain_id();
 -- All advisory fences are fail-fast before row locks. A held competing owner
 -- produces retryable contention, never an ordinary business failure or wait cycle.
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended(''module-admission:''||pid::text||'':''||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended(''openpc-policy-generations:''||pid::text||'':''||privacy::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended(''evidence-lifecycle:''||pid::text,0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended(''runtime-target-disposition:''||pid::text||'':''||privacy::text||'':''||target::text,0))
 THEN RAISE EXCEPTION ''PC-DATA-6007''; END IF;
 -- The policy workload and the target transport are different identities.
 -- Revalidate the actual policy workload; the authenticated request still needs
 -- its own concrete credential/authority checks at the runtime decision owner.
 SELECT array_agg(DISTINCT c.principal_id ORDER BY c.principal_id) INTO workload_principals
  FROM control.credential c WHERE c.participant_id=pid AND c.kind=''WORKLOAD_MTLS''
   AND c.audience=proof->>''workloadId'' AND c.state=''ACTIVE'' AND c.credential_epoch>0
   AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp();
 IF coalesce(cardinality(workload_principals),0)<>1 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-WORKLOAD-AMBIGUOUS''; END IF;
 workload_principal:=workload_principals[1];
 PERFORM 1 FROM control.principal p WHERE p.participant_id=pid AND p.principal_id=workload_principal
  AND p.kind=''WORKLOAD'' AND p.state=''ACTIVE'' AND p.authority_epoch>0 FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION ''TARGET-DISPOSITION-WORKLOAD-WITHDRAWN''; END IF;
 PERFORM 1 FROM control.credential c WHERE c.participant_id=pid AND c.principal_id=workload_principal
  AND c.kind=''WORKLOAD_MTLS'' AND c.audience=proof->>''workloadId'' AND c.state=''ACTIVE''
  AND c.credential_epoch>0 AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
  AND c.certificate_der IS NOT NULL AND sha256(c.certificate_der)=c.secret_fingerprint
  ORDER BY c.credential_id FOR SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION ''TARGET-DISPOSITION-WORKLOAD-CREDENTIAL''; END IF;
 SELECT * INTO STRICT original FROM control.configuration_work w
  WHERE w.participant_id=pid AND w.privacy_domain_id=privacy
   AND w.configuration_work_id=(expected_source->>''original_work_id'')::uuid
   AND w.operation_id::text=expected_source->>''original_operation_id''
   AND w.execution_attempt_id::text=expected_source->>''original_execution_attempt_id''
   AND w.runtime_target_id=target AND w.work_kind=''RUNTIME_ACTIVATION''
   AND (w.state=''COMPLETED'' OR (operation=''CONFIRM'' AND w.state IN (''LEASED'',''RECONCILING'')))
   AND w.execution_started_at IS NOT NULL
   AND w.runtime_configuration_generation_id::text=expected_source->>''runtime_configuration_generation_id''
   AND w.configuration_digest=''sha256:''||(expected_source->>''configuration_digest'')
   AND w.xds_version_digest=''sha256:''||(expected_source->>''xds_version_digest'')
   AND w.predecessor_digest IS NOT DISTINCT FROM ''sha256:''||(expected_source->>''predecessor_capsule_digest'')
   AND w.policy_generation_digest=''sha256:''||(proof->>''policyGenerationDigest'') FOR SHARE NOWAIT;
 PERFORM 1 FROM control.runtime_activation_observation o
  WHERE o.participant_id=pid AND o.privacy_domain_id=privacy AND o.configuration_work_id=original.configuration_work_id
   AND o.operation_id=original.operation_id AND o.execution_attempt_id=original.execution_attempt_id
   AND o.runtime_target_id=target AND o.runtime_configuration_generation_id=original.runtime_configuration_generation_id
   AND o.generation_digest=original.generation_digest AND o.xds_version_digest=original.xds_version_digest
   AND (original.state<>''COMPLETED'' OR o.activation_receipt_digest=original.result_receipt_digest)
   AND encode(sha256(decode(o.activation_receipt->>''activationReceiptCoseHex'',''hex'')),''hex'')=proof->>''originalReceiptDigest''
   AND o.capsule_digest=''sha256:''||(expected_source->>''capsule_digest'')
   AND o.capsule_digest=''sha256:''||(proof->>''capsuleDigest'');
 IF NOT FOUND THEN RAISE EXCEPTION ''TARGET-DISPOSITION-SOURCE-OBSERVATION''; END IF;
 SELECT * INTO STRICT input FROM control.runtime_configuration_input i
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
   AND i.runtime_configuration_input_id=(expected_source->>''runtime_configuration_input_id'')::uuid
   AND i.configuration_digest=decode(expected_source->>''configuration_digest'',''hex'')
   AND i.module_installation_id::text=expected_source->>''module_installation_id''
   AND i.module_configuration_generation_id::text=expected_source->>''module_configuration_generation_id''
   AND i.selected FOR SHARE NOWAIT;
 -- Lock each mutable source before re-evaluating the shared canonical view.
 -- A source''s signature/digest alone does not establish its current admission.
 FOR binding IN SELECT value FROM jsonb_array_elements(input.resource_bindings) ORDER BY value->>''kind'',value->>''id'' LOOP
  CASE binding->>''kind''
   WHEN ''ProviderProfile'' THEN
    PERFORM 1 FROM control.provider_profile p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.provider_profile_id=(binding->>''id'')::uuid AND p.behavior_fingerprint=binding->>''digest''
     AND p.chain_id=binding->>''chainId'' AND p.state<>''RETIRED'' FOR SHARE NOWAIT;
   WHEN ''ClientIndexerProfile'' THEN
    PERFORM 1 FROM control.indexer_profile p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.indexer_profile_id=(binding->>''id'')::uuid AND p.method_profile_digest=binding->>''digest''
     AND p.engine_version=binding->>''engineVersion'' AND p.state<>''RETIRED'' FOR SHARE NOWAIT;
   WHEN ''ProjectionPlan'' THEN
    PERFORM 1 FROM control.projection_plan p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.projection_plan_id=(binding->>''id'')::uuid AND p.plan_digest=binding->>''digest''
     AND p.state<>''RETIRED'' FOR SHARE NOWAIT;
   WHEN ''CiglSettings'' THEN
    PERFORM 1 FROM control.cigl_settings p WHERE p.participant_id=pid AND p.privacy_domain_id=privacy
     AND p.cigl_settings_id=(binding->>''id'')::uuid;
   ELSE RAISE EXCEPTION ''TARGET-DISPOSITION-SOURCE-KIND'';
  END CASE;
  IF NOT FOUND THEN RAISE EXCEPTION ''TARGET-DISPOSITION-SOURCE-RESTRICTED''; END IF;
 END LOOP;
 PERFORM 1 FROM control.runtime_configuration_input_current_metadata i
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy
   AND i.runtime_configuration_input_id=input.runtime_configuration_input_id;
 IF NOT FOUND THEN RAISE EXCEPTION ''TARGET-DISPOSITION-SOURCE-WITHDRAWN''; END IF;
 SELECT g.* INTO STRICT current_policy FROM control.policy_generation g JOIN control.policy_version v
  ON v.participant_id=g.participant_id AND v.privacy_domain_id=g.privacy_domain_id AND v.policy_version_id=g.policy_version_id
  JOIN control.policy_artifact a ON a.participant_id=g.participant_id AND a.privacy_domain_id=g.privacy_domain_id
   AND a.semantic_digest=v.semantic_digest AND a.payload_digest=g.artifact_digest
  WHERE g.participant_id=pid AND g.privacy_domain_id=privacy
   AND ((g.active AND g.state=''ACTIVE'') OR (operation=''CONFIRM'' AND EXISTS(
    SELECT 1 FROM control.policy_activation_occurrence_target ot
     JOIN control.policy_activation_occurrence oc ON oc.participant_id=ot.participant_id
      AND oc.privacy_domain_id=ot.privacy_domain_id AND oc.activation_occurrence_id=ot.activation_occurrence_id
     JOIN control.policy_activation a ON a.participant_id=oc.participant_id
      AND a.privacy_domain_id=oc.privacy_domain_id AND a.policy_activation_id=oc.activation_occurrence_id
    WHERE ot.participant_id=pid AND ot.privacy_domain_id=privacy AND ot.configuration_work_id=original.configuration_work_id
     AND ((ot.phase=''FORWARD'' AND oc.policy_generation_id=g.policy_generation_id AND g.state=''PREPARED'')
       OR (ot.phase=''ROLLBACK'' AND a.state=''ACTIVE'' AND a.prior_generation_digest=g.generation_digest AND g.state=''RETIRED'')))))
   AND g.generation_digest=decode(proof->>''policyGenerationDigest'',''hex'') FOR SHARE OF g NOWAIT;
 SELECT s.expires_at_ns INTO STRICT current_identity_expiry FROM control.identity_runtime_snapshot_head h
  JOIN control.identity_runtime_snapshot s ON s.snapshot_id=h.snapshot_id AND s.participant_id=h.participant_id
   AND s.privacy_domain_id=h.privacy_domain_id AND s.target_runtime_id=h.target_runtime_id
  WHERE h.participant_id=pid AND h.privacy_domain_id=privacy AND h.target_runtime_id=target
   AND s.manifest_digest=decode(proof->>''identityManifestDigest'',''hex'')
   AND s.expires_at_ns>extract(epoch from clock_timestamp())*1000000000 FOR SHARE OF h NOWAIT;
 -- The proof may shorten, never extend, the original Identity publication.
 IF (proof->>''capsuleValidUntilNs'')::numeric>current_identity_expiry
 THEN RAISE EXCEPTION ''TARGET-DISPOSITION-IDENTITY-EXPIRY''; END IF;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION ''PC-DATA-6007'';
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('openpc.begin_runtime_target_withdrawal(uuid,uuid,text,text,bigint)')
   AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND p.prosecdef=true
