DROP TRIGGER IF EXISTS notification_payload_effect_guard ON control.notification_payload;
CREATE TRIGGER notification_payload_effect_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_payload FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_occurrence_effect();
DROP TRIGGER IF EXISTS notification_payload_effect_pair ON control.notification_payload;
CREATE CONSTRAINT TRIGGER notification_payload_effect_pair AFTER INSERT ON control.notification_payload DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.check_notification_occurrence_effect_pair();
DROP TRIGGER IF EXISTS notification_payload_truncate_guard ON control.notification_payload;
