CREATE TRIGGER notification_source_inbox_effect_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_source_inbox FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_occurrence_effect();
DROP TRIGGER IF EXISTS notification_source_inbox_effect_pair ON control.notification_source_inbox;
CREATE CONSTRAINT TRIGGER notification_source_inbox_effect_pair AFTER INSERT OR UPDATE ON control.notification_source_inbox DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.check_notification_occurrence_effect_pair();
DROP TRIGGER IF EXISTS notification_source_inbox_truncate_guard ON control.notification_source_inbox;
CREATE TRIGGER notification_source_inbox_truncate_guard BEFORE TRUNCATE ON control.notification_source_inbox FOR EACH STATEMENT EXECUTE FUNCTION openpc.guard_notification_occurrence_truncate();

ALTER TABLE control.notification_occurrence FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification_occurrence FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT ON control.notification_occurrence TO openpc_control_runtime;
DROP TRIGGER IF EXISTS notification_occurrence_effect_guard ON control.notification_occurrence;
CREATE TRIGGER notification_occurrence_effect_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_occurrence FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_occurrence_effect();
DROP TRIGGER IF EXISTS notification_occurrence_effect_pair ON control.notification_occurrence;
CREATE CONSTRAINT TRIGGER notification_occurrence_effect_pair AFTER INSERT ON control.notification_occurrence DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.check_notification_occurrence_effect_pair();
DROP TRIGGER IF EXISTS notification_occurrence_truncate_guard ON control.notification_occurrence;
