ALTER TABLE control.notification_source_cursor FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification_source_cursor FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT ON control.notification_source_cursor TO openpc_control_runtime;
DROP TRIGGER IF EXISTS notification_source_cursor_effect_guard ON control.notification_source_cursor;
CREATE TRIGGER notification_source_cursor_effect_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_source_cursor FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_occurrence_effect();
DROP TRIGGER IF EXISTS notification_source_cursor_effect_pair ON control.notification_source_cursor;
CREATE CONSTRAINT TRIGGER notification_source_cursor_effect_pair AFTER INSERT OR UPDATE ON control.notification_source_cursor DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.check_notification_occurrence_effect_pair();
DROP TRIGGER IF EXISTS notification_source_cursor_truncate_guard ON control.notification_source_cursor;
CREATE TRIGGER notification_source_cursor_truncate_guard BEFORE TRUNCATE ON control.notification_source_cursor FOR EACH STATEMENT EXECUTE FUNCTION openpc.guard_notification_occurrence_truncate();
REVOKE ALL ON FUNCTION openpc.guard_notification_occurrence_effect(),openpc.check_notification_occurrence_effect_pair() FROM PUBLIC;
REVOKE ALL ON FUNCTION openpc.check_notification_delivery_requested_event(control.outbox_event) FROM PUBLIC;
