CREATE OR REPLACE FUNCTION openpc.protected_proof_binding(o control.protected_proof_object)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('objectRef','urn:openpc:resource:'||(o).object_id::text,
  'objectVersion',(o).object_version::text,'objectDigest',(o).object_digest,'source',(o).source)
$$;

CREATE OR REPLACE FUNCTION openpc.guard_protected_proof_object()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE a record; e record; expected jsonb; payload jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-PROTECTED_PROOFS_CREATE_RESOURCE-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR NEW.creation_operation_id<>current_setting('openpc.operation_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT occurrence.* INTO a FROM control.evidence_catalogue c JOIN control.authentication_occurrence occurrence
  ON occurrence.participant_id=c.participant_id AND occurrence.privacy_domain_id=c.privacy_domain_id
   AND occurrence.occurrence_id::text=c.record_id AND c.evidence_class='AUTHENTICATION'
   AND c.receipt_digest='sha256:'||encode(occurrence.receipt_digest,'hex')
  WHERE c.participant_id=NEW.participant_id AND c.privacy_domain_id=NEW.privacy_domain_id
   AND 'urn:openpc:resource:'||c.evidence_id::text=NEW.source->>'evidenceId' AND occurrence.method='WEBAUTHN_ASSERTION';
 SELECT proof.* INTO e FROM control.mutation_evidence proof JOIN control.idempotency_record i
  ON i.participant_id=proof.participant_id AND i.privacy_domain_id=proof.privacy_domain_id
   AND i.operation_id=proof.operation_id AND i.terminal_state='COMMITTED' AND i.input_digest=proof.candidate_digest
  WHERE proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id
   AND proof.operation_id=a.operation_id AND proof.principal_id=a.principal_id AND proof.aggregate_id=a.session_id
   AND proof.mfa_challenge_id=a.source_id AND proof.signer_credential_id=a.credential_id
   AND proof.webauthn_assertion_binding_digest=a.proof_digest AND proof.catalog_operation_id='ID-OP-WEBAUTHN-VERIFY';
 IF a.occurrence_id IS NULL OR e.operation_id IS NULL OR e.evidence_digest<>sha256(e.evidence_cbor)
  OR coalesce(NEW.source->>'signerKeyDigest','')!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 expected:=jsonb_build_object('evidenceId',NEW.source->>'evidenceId','occurrenceId',a.occurrence_id::text,
  'operationId',a.operation_id::text,'sourceReceiptDigest','sha256:'||encode(a.receipt_digest,'hex'),
  'proofDigest','sha256:'||encode(a.proof_digest,'hex'),'assertionDigest','sha256:'||encode(e.evidence_digest,'hex'),
  'signatureDigest','sha256:'||encode(sha256(e.cose_sign1),'hex'),'signerKeyDigest',NEW.source->>'signerKeyDigest',
  'occurredAt',to_char(a.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'materialType','IDENTITY_SIGNED_AUTHORIZATION_ASSERTION','evidenceClass','AUTHENTICATION',
  'sourceFormat','IDENTITY_RUNTIME_ASSERTION_3002_2_13','occurrenceIntegrity','CONTROL_DATABASE_IMMUTABLE',
  'proofIntegrity','IDENTITY_COSE_ED25519','finality','NOT_APPLICABLE','authorityEffect','NONE');
 payload:=jsonb_build_object('version','OPENPC_PROTECTED_IDENTITY_PROOF_V1','participantId',NEW.participant_id::text,
  'privacyDomainId',NEW.privacy_domain_id::text,'source',expected,
  'assertionBase64',replace(encode(e.evidence_cbor,'base64'),chr(10),''),'coseSign1Base64',replace(encode(e.cose_sign1,'base64'),chr(10),''));
 IF NEW.source IS DISTINCT FROM expected OR NEW.object_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(payload),'UTF8')),'hex')
  OR NEW.object_version<>1 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.created_at:=clock_timestamp(); NEW.updated_at:=NEW.created_at;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_protected_proof_payload()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE used bigint;
BEGIN
 IF TG_OP='DELETE' THEN
  PERFORM openpc.record_raw_proof_payload_deletion(OLD);
  RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NOT EXISTS(SELECT 1 FROM control.protected_proof_object o WHERE o.object_id=NEW.object_id
  AND o.participant_id=NEW.participant_id AND o.privacy_domain_id=NEW.privacy_domain_id
  AND o.creation_operation_id=current_setting('openpc.operation_id')::uuid)
  OR current_setting('openpc.action_intent_id')<>'ACT-PROTECTED_PROOFS_CREATE_RESOURCE-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 PERFORM pg_advisory_xact_lock(hashtextextended('protected-proof-capacity:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0));
 SELECT coalesce(sum(octet_length(ciphertext)),0) INTO used FROM control.protected_proof_payload
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id;
 IF used+octet_length(NEW.ciphertext)>16777216 THEN RAISE EXCEPTION 'PC-OPS-9002'; END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION openpc.guard_protected_proof_access()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE o control.protected_proof_object; expected jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO o FROM control.protected_proof_object WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND object_id=NEW.object_id;
 IF o.object_id IS NULL OR o.retain_until<=clock_timestamp() OR NEW.expires_at>o.retain_until
  OR NEW.object_binding IS DISTINCT FROM openpc.protected_proof_binding(o)
  OR NEW.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF TG_OP='INSERT' THEN
  IF current_setting('openpc.action_intent_id')<>'ACT-PROTECTED_PROOF_ACCESS_CREATE_RESOURCE-V1'
   OR NEW.creation_operation_id<>current_setting('openpc.operation_id')::uuid OR NEW.revision<>1
   OR NEW.consumed_at IS NOT NULL OR NEW.consumption_operation_id IS NOT NULL OR NEW.consumption_request IS NOT NULL
   THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  NEW.created_at:=clock_timestamp(); NEW.updated_at:=NEW.created_at;
 ELSE
  IF current_setting('openpc.action_intent_id')<>'ACT-PROTECTED_PROOF_ACCESS_CONSUME_RESOURCE-V1'
   OR OLD.revision<>1 OR NEW.revision<>2 OR NEW.consumption_operation_id<>current_setting('openpc.operation_id')::uuid
   OR (to_jsonb(NEW)-ARRAY['revision','consumption_operation_id','consumed_at','updated_at','consumption_request']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['revision','consumption_operation_id','consumed_at','updated_at','consumption_request'])
   THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  expected:=jsonb_build_object('targetRef','urn:openpc:resource:'||NEW.access_id::text,'expectedRevision','1',
   'object',NEW.object_binding,'purpose',NEW.purpose,'caseReference',NEW.case_reference,
   'recipientPrincipalId',NEW.recipient_principal_id::text,'expiresAt',to_char(NEW.expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  IF NEW.consumption_request-ARRAY['reason','actionIntentId','actionIntentDigest'] IS DISTINCT FROM expected
   OR NEW.consumption_request->>'actionIntentId'<>'ACT-PROTECTED_PROOF_ACCESS_CONSUME_RESOURCE-V1'
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  NEW.consumed_at:=clock_timestamp(); NEW.updated_at:=NEW.consumed_at;
 END IF;
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION openpc.require_protected_proof_command()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE op uuid; rid uuid; action text; catalog text; aggregate text; document jsonb; expected numeric;
 e control.mutation_evidence; c control.mutation_candidate; original control.mutation_evidence;
BEGIN
 IF TG_TABLE_NAME='protected_proof_object' THEN
  op:=NEW.creation_operation_id;rid:=NEW.object_id;action:='ACT-PROTECTED_PROOFS_CREATE_RESOURCE-V1';
  catalog:='CFG-OP-RETAIN-PROTECTED-PROOF';aggregate:='protected-proof';expected:=0;
  document:=jsonb_build_object('source',NEW.source,'purpose',NEW.purpose,'caseReference',NEW.case_reference,
   'retainUntil',to_char(NEW.retain_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  IF NOT EXISTS(SELECT 1 FROM control.protected_proof_payload WHERE object_id=rid AND participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSIF TG_OP='INSERT' THEN
  op:=NEW.creation_operation_id;rid:=NEW.access_id;action:='ACT-PROTECTED_PROOF_ACCESS_CREATE_RESOURCE-V1';
  catalog:='CFG-OP-REQUEST-PROTECTED-ACCESS';aggregate:='protected-proof-access';expected:=0;
  document:=jsonb_build_object('object',NEW.object_binding,'purpose',NEW.purpose,'caseReference',NEW.case_reference,
   'recipientPrincipalId',NEW.recipient_principal_id::text,'expiresAt',to_char(NEW.expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 ELSE
  op:=NEW.consumption_operation_id;rid:=NEW.access_id;action:='ACT-PROTECTED_PROOF_ACCESS_CONSUME_RESOURCE-V1';
  catalog:='CFG-OP-CONSUME-PROTECTED-ACCESS';aggregate:='protected-proof-access';expected:=1;document:=NEW.consumption_request;
 END IF;
 SELECT proof.* INTO e FROM control.mutation_evidence proof JOIN control.idempotency_record i
  ON i.participant_id=proof.participant_id AND i.privacy_domain_id=proof.privacy_domain_id AND i.operation_id=proof.operation_id
   AND i.principal_id=proof.principal_id AND i.action_intent_id=proof.action_intent_id AND i.catalog_operation_id=proof.catalog_operation_id
   AND i.input_digest=proof.candidate_digest AND i.terminal_state='COMMITTED' AND i.expected_aggregate_version=expected
   AND i.result_payload->>'resourceRef'='urn:openpc:resource:'||rid::text
  WHERE proof.participant_id=NEW.participant_id AND proof.privacy_domain_id=NEW.privacy_domain_id
   AND proof.operation_id=op AND proof.action_intent_id=action AND proof.catalog_operation_id=catalog
   AND proof.aggregate_type=aggregate AND proof.aggregate_id=rid;
 IF e.operation_id IS NULL OR NOT EXISTS(SELECT 1 FROM control.outbox_event event WHERE event.participant_id=e.participant_id
  AND event.privacy_domain_id=e.privacy_domain_id AND event.aggregate_type=aggregate AND event.aggregate_id=rid
  AND event.event_type=CASE catalog WHEN 'CFG-OP-RETAIN-PROTECTED-PROOF' THEN 'openpc.evidence.protected.retained.v1'
   WHEN 'CFG-OP-REQUEST-PROTECTED-ACCESS' THEN 'openpc.evidence.protected.access-requested.v1' ELSE 'openpc.evidence.protected.consumed.v1' END
  AND event.payload_digest=sha256(event.payload_cbor)
  AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'candidateDigest'='sha256:'||encode(e.candidate_digest,'hex')
  AND convert_from(event.payload_cbor,'UTF8')::jsonb->>'authorizationEvidenceDigest'='sha256:'||encode(e.evidence_digest,'hex'))
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF expected=0 THEN
  SELECT candidate.* INTO c FROM control.mutation_candidate candidate JOIN control.approval_request a
   ON a.participant_id=candidate.participant_id AND a.privacy_domain_id=candidate.privacy_domain_id
    AND a.subject_id=candidate.mutation_candidate_id AND a.approval_request_id=e.approval_request_id
   WHERE candidate.participant_id=e.participant_id AND candidate.privacy_domain_id=e.privacy_domain_id
    AND candidate.consumed_operation_id=op AND candidate.state='CONSUMED' AND candidate.candidate_digest=e.candidate_digest
    AND candidate.action_intent_id=action AND candidate.catalog_operation_id=catalog AND candidate.resource_id=rid
    AND candidate.maker_principal_id=e.principal_id AND candidate.expected_revision=0;
  IF c.mutation_candidate_id IS NULL OR e.checker_principal_id IS NULL OR e.checker_principal_id=e.principal_id
   OR NEW.approval_request_id IS DISTINCT FROM e.approval_request_id
   OR c.candidate_document-ARRAY['participantId','actionIntentId','actionIntentDigest','reason'] IS DISTINCT FROM document
   OR NOT EXISTS(SELECT 1 FROM control.mfa_challenge m WHERE m.participant_id=e.participant_id AND m.mfa_challenge_id=e.mfa_challenge_id
    AND m.principal_id=e.principal_id AND m.used_operation_id=op AND m.action_intent_id=action AND m.resource_digest=e.candidate_digest
    AND m.consumed_at>clock_timestamp()-interval '5 minutes') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 ELSE
  IF e.candidate_digest<>sha256(convert_to(openpc.signing_canonical_json(document),'UTF8')) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO original FROM control.mutation_evidence WHERE participant_id=NEW.participant_id
   AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.creation_operation_id;
  IF original.operation_id IS NULL OR (original.principal_id,original.bound_participant_epoch,original.bound_principal_epoch,
    original.bound_authority_envelope_id,original.bound_envelope_epoch,original.bound_assignment_id) IS DISTINCT FROM
   (e.principal_id,e.bound_participant_epoch,e.bound_principal_epoch,e.bound_authority_envelope_id,e.bound_envelope_epoch,e.bound_assignment_id)
   THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END IF;
 IF TG_TABLE_NAME='protected_proof_access' THEN
  IF NEW.recipient_principal_id<>e.principal_id OR NOT EXISTS(SELECT 1 FROM control.session s
   WHERE s.participant_id=NEW.participant_id AND s.session_id=NEW.sender_session_id AND s.principal_id=e.principal_id
    AND s.privacy_domain_id=NEW.privacy_domain_id AND s.state='ACTIVE' AND s.absolute_expires_at>clock_timestamp()
    AND s.idle_expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
  IF expected=0 AND NOT EXISTS(SELECT 1 FROM control.mfa_challenge m WHERE m.participant_id=e.participant_id
   AND m.mfa_challenge_id=e.mfa_challenge_id AND m.session_id=NEW.sender_session_id) THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 END IF;
 RETURN NULL;
END $$;

DROP TRIGGER IF EXISTS protected_proof_object_guard ON control.protected_proof_object;
CREATE TRIGGER protected_proof_object_guard BEFORE INSERT OR UPDATE OR DELETE ON control.protected_proof_object
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_protected_proof_object();

DROP TRIGGER IF EXISTS protected_proof_payload_guard ON control.protected_proof_payload;
CREATE TRIGGER protected_proof_payload_guard BEFORE INSERT OR UPDATE OR DELETE ON control.protected_proof_payload
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_protected_proof_payload();

DROP TRIGGER IF EXISTS protected_proof_access_guard ON control.protected_proof_access;
CREATE TRIGGER protected_proof_access_guard BEFORE INSERT OR UPDATE OR DELETE ON control.protected_proof_access
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_protected_proof_access();

DROP TRIGGER IF EXISTS protected_proof_object_command ON control.protected_proof_object;
CREATE CONSTRAINT TRIGGER protected_proof_object_command AFTER INSERT OR UPDATE ON control.protected_proof_object
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_protected_proof_command();

DROP TRIGGER IF EXISTS protected_proof_access_command ON control.protected_proof_access;
CREATE CONSTRAINT TRIGGER protected_proof_access_command AFTER INSERT OR UPDATE ON control.protected_proof_access
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_protected_proof_command();
REVOKE ALL ON FUNCTION openpc.protected_proof_binding(control.protected_proof_object),openpc.guard_protected_proof_object(),
 openpc.guard_protected_proof_payload(),openpc.guard_protected_proof_access(),openpc.require_protected_proof_command() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.protected_proof_binding(control.protected_proof_object),openpc.guard_protected_proof_object(),
 openpc.guard_protected_proof_payload(),openpc.guard_protected_proof_access(),openpc.require_protected_proof_command() TO openpc_control_runtime;


ALTER TABLE control.protected_proof_checkpoint FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.protected_proof_checkpoint FROM PUBLIC,openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT SELECT ON control.protected_proof_checkpoint TO openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT INSERT ON control.protected_proof_checkpoint TO openpc_control_worker;
GRANT SELECT ON control.protected_proof_object,control.protected_proof_payload TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.protected_proof_payload_digest(payload control.protected_proof_payload)
RETURNS text LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
  'keyId',(payload).key_id,'nonceBase64',replace(encode((payload).nonce,'base64'),chr(10),''),
  'ciphertextBase64',replace(encode((payload).ciphertext,'base64'),chr(10),''))),'UTF8')),'hex')
$$;
REVOKE ALL ON FUNCTION openpc.protected_proof_payload_digest(control.protected_proof_payload) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.protected_proof_payload_digest(control.protected_proof_payload) TO openpc_control_runtime,openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.guard_protected_proof_checkpoint()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE object control.protected_proof_object; payload control.protected_proof_payload; expected jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 SELECT * INTO STRICT object FROM control.protected_proof_object
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND object_id=NEW.object_id;
 SELECT * INTO STRICT payload FROM control.protected_proof_payload
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND object_id=NEW.object_id;
 IF NEW.payload_digest IS DISTINCT FROM openpc.protected_proof_payload_digest(payload)
  OR NEW.ciphertext_bytes<>octet_length(payload.ciphertext) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF NEW.receipt->>'kind'='SIGNED_REMOTE_PROTECTED_ARCHIVE_V1' THEN
  PERFORM openpc.assert_protected_remote_checkpoint(NEW);
 ELSE
 expected:=jsonb_build_object('object',openpc.protected_proof_binding(object)||jsonb_build_object(
  'dataClass','RAW_SOURCE_BODY','participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,
  'sinkId',NEW.sink_id,'payloadDigest',NEW.payload_digest,'ciphertextBytes',NEW.ciphertext_bytes,
  'retainUntil',to_char(object.retain_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),
  'versionId',NEW.payload_digest,'assurance','LOCAL_FSYNC_READBACK');
 IF NEW.receipt-'receiptDigest' IS DISTINCT FROM expected OR NEW.receipt->>'receiptDigest' IS DISTINCT FROM NEW.receipt_digest
  OR NEW.receipt_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END IF;
 expected:=jsonb_build_object('domain','pc.evidence.protected-checkpoint.v1','participantId',NEW.participant_id::text,
  'privacyDomainId',NEW.privacy_domain_id::text,'objectRef','urn:openpc:resource:'||NEW.object_id::text,
  'objectVersion',object.object_version::text,'sinkId',NEW.sink_id,'payloadDigest',NEW.payload_digest,'receiptDigest',NEW.receipt_digest);
 IF NEW.checkpoint_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.acknowledged_at:=clock_timestamp();
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_protected_proof_checkpoint() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.guard_protected_proof_checkpoint() TO openpc_control_worker;
DROP TRIGGER IF EXISTS protected_proof_checkpoint_guard ON control.protected_proof_checkpoint;
CREATE TRIGGER protected_proof_checkpoint_guard BEFORE INSERT OR UPDATE OR DELETE ON control.protected_proof_checkpoint
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_protected_proof_checkpoint();
GRANT EXECUTE ON FUNCTION openpc.protected_proof_binding(control.protected_proof_object) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.protected_remote_archive_source(
 participant uuid,privacy uuid,proof uuid,sink text,original_intent uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE o control.protected_proof_object; p control.protected_proof_payload;
 c control.evidence_catalogue; h control.retention_hold; metadata jsonb;
 packet jsonb; object jsonb; packet_digest text; observed timestamptz;
 matched boolean; rules jsonb:='[]'::jsonb; retained control.evidence_remote_archive_intent; payload_size integer; cipher_size integer;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_worker','USAGE')
  OR current_setting('openpc.action_intent_id',true) IS DISTINCT FROM 'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR participant IS DISTINCT FROM current_setting('openpc.participant_id',true)::uuid
  OR privacy IS DISTINCT FROM current_setting('openpc.privacy_domain_id',true)::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF proof IS NULL OR proof::text!~'^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  OR sink IS NULL OR sink!~'^[a-zA-Z0-9][a-zA-Z0-9:._-]{0,159}$'
 THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 -- The common caller owns its lifecycle fence across this read, STARTED commit
 -- and I/O. No lock or transaction is manufactured by these source predicates.
 SELECT * INTO o FROM control.protected_proof_object candidate
  WHERE candidate.participant_id=participant AND candidate.privacy_domain_id=privacy AND candidate.object_id=proof;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','UNKNOWN','reason','OBJECT_UNAVAILABLE'); END IF;
 SELECT * INTO p FROM control.protected_proof_payload payload
  WHERE payload.participant_id=participant AND payload.privacy_domain_id=privacy AND payload.object_id=proof;
 IF NOT FOUND THEN
  -- A missing local packet is usable only for reconciliation of its original
  -- admitted journal identity, never as authority to recreate or resend bytes.
  SELECT * INTO retained FROM control.evidence_remote_archive_intent i
   WHERE i.participant_id=participant AND i.privacy_domain_id=privacy AND i.intent_id=original_intent
    AND i.source_kind='PROTECTED_PROOF' AND i.protected_object_id=proof
    AND i.protected_object_version=o.object_version AND i.protected_object_digest=o.object_digest AND i.sink_id=sink;
  IF NOT FOUND THEN RETURN jsonb_build_object('state','UNKNOWN','reason','PAYLOAD_UNAVAILABLE'); END IF;
 END IF;
 -- Only the already-governed immutable Identity proof copy qualifies. Catalogue
 -- identity alone cannot substitute for its authenticated occurrence lineage.
 SELECT catalogue.* INTO c FROM control.evidence_catalogue catalogue
  JOIN control.authentication_occurrence a ON a.participant_id=catalogue.participant_id
   AND a.privacy_domain_id=catalogue.privacy_domain_id AND a.occurrence_id::text=catalogue.record_id
   AND a.receipt_digest=sha256(a.receipt) AND a.occurred_at=catalogue.occurred_at
   AND catalogue.receipt_digest='sha256:'||encode(a.receipt_digest,'hex')
  WHERE catalogue.participant_id=participant AND catalogue.privacy_domain_id=privacy
   AND 'urn:openpc:resource:'||catalogue.evidence_id::text=o.source->>'evidenceId'
   AND catalogue.record_id=o.source->>'occurrenceId'
   AND catalogue.receipt_digest=o.source->>'sourceReceiptDigest'
   AND catalogue.evidence_class='AUTHENTICATION' AND catalogue.source_format='OPENPC_AUTHENTICATION_OCCURRENCE_V1'
   AND a.method='WEBAUTHN_ASSERTION' AND a.operation_id::text=o.source->>'operationId'
   AND 'sha256:'||encode(a.proof_digest,'hex')=o.source->>'proofDigest'
   AND to_char(a.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')=o.source->>'occurredAt'
   AND o.source->>'materialType'='IDENTITY_SIGNED_AUTHORIZATION_ASSERTION'
   AND o.source->>'evidenceClass'='AUTHENTICATION'
   AND o.source->>'sourceFormat'='IDENTITY_RUNTIME_ASSERTION_3002_2_13'
   AND o.source->>'occurrenceIntegrity'='CONTROL_DATABASE_IMMUTABLE'
   AND o.source->>'proofIntegrity'='IDENTITY_COSE_ED25519'
   AND o.source->>'finality'='NOT_APPLICABLE' AND o.source->>'authorityEffect'='NONE';
 IF NOT FOUND THEN RETURN jsonb_build_object('state','UNKNOWN','reason','LINEAGE_UNAVAILABLE'); END IF;
 metadata:=openpc.evidence_hold_record_metadata(c);
 IF metadata IS NULL THEN RETURN jsonb_build_object('state','UNKNOWN','reason','HOLD_LINEAGE_UNAVAILABLE'); END IF;
 IF p.object_id IS NOT NULL THEN
  packet:=jsonb_build_object('keyId',p.key_id,
   'nonceBase64',replace(encode(p.nonce,'base64'),chr(10),''),
   'ciphertextBase64',replace(encode(p.ciphertext,'base64'),chr(10),''));
  packet_digest:=openpc.protected_proof_payload_digest(p);
  payload_size:=octet_length(convert_to(openpc.signing_canonical_json(packet),'UTF8'));
  cipher_size:=octet_length(p.ciphertext);
 ELSE
  packet_digest:=retained.intent->>'payloadDigest';
  payload_size:=(retained.intent->>'payloadBytes')::integer;
  cipher_size:=(retained.intent->'source'->'object'->>'ciphertextBytes')::integer;
 END IF;
 object:=openpc.protected_proof_binding(o)||jsonb_build_object('dataClass','RAW_SOURCE_BODY',
  'participantId',participant::text,'privacyDomainId',privacy::text,'sinkId',sink,
  'payloadDigest',packet_digest,'ciphertextBytes',cipher_size,
  'retainUntil',to_char(o.retain_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 IF retained.intent_id IS NOT NULL AND (retained.intent->'source'->'object' IS DISTINCT FROM object
  OR retained.stream_id IS DISTINCT FROM c.stream_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 FOR h IN SELECT candidate.* FROM control.retention_hold candidate
  WHERE candidate.participant_id=participant AND (candidate.selector_type='PARTICIPANT' OR candidate.privacy_domain_id=privacy)
   AND (candidate.state='ACTIVE' OR o.created_at<=candidate.updated_at)
  ORDER BY candidate.retention_hold_id LOOP
  -- A proof created after terminal release did not exist during that rule's
  -- lifetime, even if its original authentication segment is much older.
  matched:=CASE h.selector_type
   WHEN 'PARTICIPANT' THEN true WHEN 'PRIVACY_DOMAIN' THEN true
   WHEN 'DIGEST' THEN h.selector->>'recordDigest' IN (o.object_digest,packet_digest,c.receipt_digest)
   WHEN 'SEQUENCE_RANGE' THEN h.selector->>'streamId'=c.stream_id
    AND c.sequence>=(h.selector->>'fromSequence')::numeric
    AND (h.selector->'throughSequence'='null'::jsonb OR c.sequence<=(h.selector->>'throughSequence')::numeric)
   ELSE openpc.evidence_hold_source_match(h.selector,metadata) END;
  IF matched IS NULL THEN
   RETURN jsonb_build_object('state','UNKNOWN','reason','HOLD_LINEAGE_UNAVAILABLE');
  END IF;
  IF matched THEN
   IF jsonb_array_length(rules)=1024 THEN
    RETURN jsonb_build_object('state','UNKNOWN','reason','TOO_MANY_HOLDS');
   END IF;
   rules:=rules||jsonb_build_array(jsonb_build_object('holdId',h.retention_hold_id::text,
    'selectorDigest',h.selector_digest,'creationOperationId',h.creation_operation_id::text,
    'releaseOperationId',h.release_operation_id::text,'state',h.state,'revision',h.revision::text));
  END IF;
 END LOOP;
 observed:=clock_timestamp();
 RETURN jsonb_build_object('state','BOUND','object',object,'packet',packet,
  'payloadBytes',payload_size,
  'proofCreatedAt',to_char(o.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'observedAt',to_char(observed at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'lineage',jsonb_build_object('evidenceId','urn:openpc:resource:'||c.evidence_id::text,
   'streamId',c.stream_id,'sequence',c.sequence::text,'sourceReceiptDigest',c.receipt_digest),
  'retention',jsonb_build_object('state','UNKNOWN','reason',CASE WHEN o.retain_until<=observed
   THEN 'PROOF_DEADLINE_ELAPSED' ELSE 'PROFILE_NOT_ADMITTED' END),'rules',rules);
END $$;
REVOKE ALL ON FUNCTION openpc.protected_remote_archive_source(uuid,uuid,uuid,text,uuid) FROM PUBLIC,
 openpc_control_runtime,openpc_control_reader;
GRANT EXECUTE ON FUNCTION openpc.protected_remote_archive_source(uuid,uuid,uuid,text,uuid) TO openpc_control_worker;
CREATE OR REPLACE FUNCTION openpc.protected_remote_archive_source(participant uuid,privacy uuid,proof uuid,sink text)
RETURNS jsonb LANGUAGE sql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT openpc.protected_remote_archive_source(participant,privacy,proof,sink,NULL::uuid)
$$;
REVOKE ALL ON FUNCTION openpc.protected_remote_archive_source(uuid,uuid,uuid,text) FROM PUBLIC,
 openpc_control_runtime,openpc_control_reader;
GRANT EXECUTE ON FUNCTION openpc.protected_remote_archive_source(uuid,uuid,uuid,text) TO openpc_control_worker;


CREATE OR REPLACE FUNCTION openpc.protected_remote_archive_rules(pid uuid,privacy uuid,proof uuid,sink text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE i control.evidence_remote_archive_intent; c control.evidence_catalogue; created timestamptz;
 h control.retention_hold; metadata jsonb; matched boolean; rules jsonb:='[]'::jsonb;
BEGIN
 SELECT * INTO i FROM control.evidence_remote_archive_intent candidate WHERE candidate.participant_id=pid
  AND candidate.privacy_domain_id=privacy AND candidate.protected_object_id=proof AND candidate.sink_id=sink
  AND candidate.source_kind='PROTECTED_PROOF';
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT o.created_at INTO created FROM control.protected_proof_object o WHERE o.participant_id=pid
  AND o.privacy_domain_id=privacy AND o.object_id=proof AND o.object_version=i.protected_object_version
  AND o.object_digest=i.protected_object_digest;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO c FROM control.evidence_catalogue candidate WHERE candidate.participant_id=pid
  AND candidate.privacy_domain_id=privacy AND candidate.stream_id=i.stream_id
  AND 'urn:openpc:resource:'||candidate.evidence_id::text=i.intent->'source'->'object'->'source'->>'evidenceId'
  AND candidate.receipt_digest=i.intent->'source'->'object'->'source'->>'sourceReceiptDigest';
 IF NOT FOUND THEN RETURN NULL; END IF;
 metadata:=openpc.evidence_hold_record_metadata(c);
 IF metadata IS NULL THEN RETURN NULL; END IF;
 FOR h IN SELECT candidate.* FROM control.retention_hold candidate WHERE candidate.participant_id=pid
  AND (candidate.selector_type='PARTICIPANT' OR candidate.privacy_domain_id=privacy)
  AND (candidate.state='ACTIVE' OR created<=candidate.updated_at) ORDER BY candidate.retention_hold_id LOOP
  matched:=CASE h.selector_type
   WHEN 'PARTICIPANT' THEN true WHEN 'PRIVACY_DOMAIN' THEN true
   WHEN 'DIGEST' THEN h.selector->>'recordDigest' IN (i.protected_object_digest,i.intent->>'payloadDigest',c.receipt_digest)
   WHEN 'SEQUENCE_RANGE' THEN h.selector->>'streamId'=c.stream_id AND c.sequence>=(h.selector->>'fromSequence')::numeric
    AND (h.selector->'throughSequence'='null'::jsonb OR c.sequence<=(h.selector->>'throughSequence')::numeric)
   ELSE openpc.evidence_hold_source_match(h.selector,metadata) END;
  IF matched IS NULL THEN RETURN NULL; END IF;
  IF matched THEN
   IF jsonb_array_length(rules)=1024 THEN RETURN NULL; END IF;
   rules:=rules||jsonb_build_array(jsonb_build_object('holdId',h.retention_hold_id::text,
    'selectorDigest',h.selector_digest,'creationOperationId',h.creation_operation_id::text,
    'releaseOperationId',h.release_operation_id::text,'state',h.state,'revision',h.revision::text));
  END IF;
 END LOOP;
 RETURN rules;
END $$;
REVOKE ALL ON FUNCTION openpc.protected_remote_archive_rules(uuid,uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.protected_remote_archive_rules(uuid,uuid,uuid,text)
 TO openpc_control_worker,openpc_control_runtime,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.protected_remote_archive_covers(pid uuid,privacy uuid,proof uuid,sink text)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM control.evidence_remote_archive_intent i
  JOIN control.evidence_remote_archive_attempt a USING(participant_id,privacy_domain_id,intent_id)
  JOIN control.evidence_archive_receipt r USING(participant_id,privacy_domain_id,attempt_id)
  JOIN control.evidence_archive_outbox o USING(participant_id,privacy_domain_id,receipt_id)
  WHERE i.participant_id=pid AND i.privacy_domain_id=privacy AND i.protected_object_id=proof
   AND i.sink_id=sink AND i.source_kind='PROTECTED_PROOF' AND a.state='OBSERVED'
   AND a.binding->'protection'->'rules'=openpc.protected_remote_archive_rules(pid,privacy,proof,sink)
   AND NOT EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt newer WHERE newer.participant_id=pid
    AND newer.privacy_domain_id=privacy AND newer.intent_id=i.intent_id
    AND (newer.binding->'protection'->>'revision')::numeric>(a.binding->'protection'->>'revision')::numeric))
$$;
REVOKE ALL ON FUNCTION openpc.protected_remote_archive_covers(uuid,uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.protected_remote_archive_covers(uuid,uuid,uuid,text)
 TO openpc_control_worker,openpc_control_runtime,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.protected_remote_checkpoint_valid(v control.protected_proof_checkpoint)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM control.evidence_remote_archive_intent i
  JOIN control.evidence_remote_archive_attempt a USING(participant_id,privacy_domain_id,intent_id)
  JOIN control.evidence_archive_receipt r USING(participant_id,privacy_domain_id,attempt_id)
  JOIN control.evidence_archive_outbox o USING(participant_id,privacy_domain_id,receipt_id)
  WHERE i.participant_id=(v).participant_id AND i.privacy_domain_id=(v).privacy_domain_id
   AND i.protected_object_id=(v).object_id AND i.sink_id=(v).sink_id AND i.source_kind='PROTECTED_PROOF'
   AND i.intent->>'payloadDigest'=(v).payload_digest AND (i.intent->'source'->'object'->>'ciphertextBytes')::integer=(v).ciphertext_bytes
   AND r.receipt_digest=(v).receipt_digest AND a.state='OBSERVED'
   AND (v).receipt=jsonb_build_object('kind','SIGNED_REMOTE_PROTECTED_ARCHIVE_V1','receiptId',r.receipt_id::text,
    'receiptDigest',r.receipt_digest,'profileDigest',r.profile_digest,'assurance','REMOTE_INTERFACE_VERIFIED',
    'providerQualification','NOT_ESTABLISHED'))
$$;
REVOKE ALL ON FUNCTION openpc.protected_remote_checkpoint_valid(control.protected_proof_checkpoint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.protected_remote_checkpoint_valid(control.protected_proof_checkpoint)
 TO openpc_control_worker,openpc_control_runtime,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.assert_protected_remote_checkpoint(v control.protected_proof_checkpoint)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE i control.evidence_remote_archive_intent; p control.evidence_archive_profile; r control.evidence_archive_receipt;
BEGIN
 SELECT * INTO STRICT i FROM control.evidence_remote_archive_intent WHERE participant_id=(v).participant_id
  AND privacy_domain_id=(v).privacy_domain_id AND protected_object_id=(v).object_id AND sink_id=(v).sink_id AND source_kind='PROTECTED_PROOF';
 p:=openpc.require_archive_profile(current_setting('openpc.archive_profile_digest',true),i.stream_id);
 IF p.claims->>'sourceKind' IS DISTINCT FROM 'PROTECTED_PROOF' OR p.transport IS DISTINCT FROM i.profile
  OR p.transport_digest IS DISTINCT FROM i.profile_digest OR p.sink_id IS DISTINCT FROM i.sink_id
  OR NOT openpc.protected_remote_checkpoint_valid(v)
  OR NOT openpc.protected_remote_archive_covers(i.participant_id,i.privacy_domain_id,i.protected_object_id,i.sink_id)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT r FROM control.evidence_archive_receipt WHERE participant_id=(v).participant_id
  AND privacy_domain_id=(v).privacy_domain_id AND receipt_digest=(v).receipt_digest;
 IF EXISTS(SELECT 1 FROM control.evidence_remote_archive_attempt newer WHERE newer.participant_id=i.participant_id
  AND newer.privacy_domain_id=i.privacy_domain_id AND newer.intent_id=i.intent_id
  AND (newer.binding->'protection'->>'revision')::numeric>(openpc.business_cbor(r.payload)->>'13')::numeric)
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 PERFORM openpc.require_archive_commit_nonce(r);
END $$;
REVOKE ALL ON FUNCTION openpc.assert_protected_remote_checkpoint(control.protected_proof_checkpoint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_protected_remote_checkpoint(control.protected_proof_checkpoint) TO openpc_control_worker;



CREATE OR REPLACE FUNCTION openpc.raw_proof_deletion_object_plan(object_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE object control.protected_proof_object; payload control.protected_proof_payload;
 source control.evidence_catalogue; rule control.retention_policy; receipts jsonb; selection jsonb;
 blockers text[]:=ARRAY[]::text[]; expected_payload_digest text; before_digest text; eligible_micros numeric;
 quorum_micros numeric; source_micros numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT * INTO object FROM control.protected_proof_object o
  WHERE o.participant_id=current_setting('openpc.participant_id')::uuid
   AND o.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid AND o.object_id=raw_proof_deletion_object_plan.object_id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO payload FROM control.protected_proof_payload p WHERE p.participant_id=object.participant_id
  AND p.privacy_domain_id=object.privacy_domain_id AND p.object_id=object.object_id;
 IF NOT FOUND THEN
  IF NOT EXISTS(SELECT 1 FROM control.deletion_job j JOIN control.evidence_deletion_item i
   USING(participant_id,privacy_domain_id,deletion_job_id) WHERE j.participant_id=object.participant_id
    AND j.privacy_domain_id=object.privacy_domain_id AND j.protected_object_id=object.object_id
    AND i.protected_object_id=object.object_id AND j.target_data_class='RAW_SOURCE_BODY' AND j.state='SUCCEEDED')
   THEN RAISE EXCEPTION 'PC-DATA-6004-RAW-PAYLOAD'; END IF;
  RETURN jsonb_build_object('objectRef','urn:openpc:resource:'||object.object_id::text,
   'localPayload','DELETED','eligible',false,'blockers',jsonb_build_array('ALREADY_DELETED'),'selection',null,'beforeDigest',null);
 END IF;
 expected_payload_digest:=openpc.protected_proof_payload_digest(payload);
 SELECT c.* INTO source FROM control.evidence_catalogue c JOIN control.authentication_occurrence a
  ON a.participant_id=c.participant_id AND a.privacy_domain_id=c.privacy_domain_id
   AND a.occurrence_id::text=c.record_id AND c.receipt_digest='sha256:'||encode(a.receipt_digest,'hex')
   AND a.receipt_digest=sha256(a.receipt) AND a.occurred_at=c.occurred_at AND a.method='WEBAUTHN_ASSERTION'
  WHERE c.participant_id=object.participant_id AND c.privacy_domain_id=object.privacy_domain_id
   AND 'urn:openpc:resource:'||c.evidence_id::text=object.source->>'evidenceId'
   AND c.record_id=object.source->>'occurrenceId' AND c.receipt_digest=object.source->>'sourceReceiptDigest'
   AND c.evidence_class='AUTHENTICATION' AND c.source_format='OPENPC_AUTHENTICATION_OCCURRENCE_V1'
   AND object.source->>'materialType'='IDENTITY_SIGNED_AUTHORIZATION_ASSERTION'
   AND object.source->>'finality'='NOT_APPLICABLE' AND object.source->>'authorityEffect'='NONE';
 IF NOT FOUND THEN blockers:=array_append(blockers,'UNSUPPORTED_SOURCE'); END IF;
 -- These immutable local authentication sources have no chain finality/reorg
 -- dimension. Missing source lineage is a blocker, never a no-gap assertion.
 IF source.evidence_id IS NULL OR NOT EXISTS(SELECT 1 FROM control.protected_proof_checkpoint c
  WHERE c.participant_id=object.participant_id AND c.privacy_domain_id=object.privacy_domain_id
   AND c.object_id=object.object_id AND c.payload_digest=expected_payload_digest
   AND c.ciphertext_bytes=octet_length(payload.ciphertext)
   AND ((c.receipt->'object'->>'objectDigest'=object.object_digest
   AND c.receipt->'object'->>'objectVersion'=object.object_version::text
   AND c.receipt->'object'->'source'=object.source
   AND c.receipt->>'versionId'=expected_payload_digest AND c.receipt->>'receiptDigest'=c.receipt_digest) OR (openpc.protected_remote_checkpoint_valid(c)
    AND openpc.protected_remote_archive_covers(object.participant_id,object.privacy_domain_id,object.object_id,c.sink_id)))) THEN
  blockers:=array_append(blockers,'INCOMPLETE_CHECKPOINT');
 END IF;
 IF EXISTS(SELECT 1 FROM control.retention_hold h WHERE h.participant_id=object.participant_id
  AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=object.privacy_domain_id) AND h.state='ACTIVE'
  AND (CASE h.selector_type
   WHEN 'PARTICIPANT' THEN true WHEN 'PRIVACY_DOMAIN' THEN true
   WHEN 'DIGEST' THEN (h.selector->>'recordDigest' IN (object.object_digest,expected_payload_digest,source.receipt_digest))
   WHEN 'SEQUENCE_RANGE' THEN h.selector->>'streamId'=source.stream_id
    AND source.sequence>=(h.selector->>'fromSequence')::numeric
    AND (h.selector->'throughSequence'='null'::jsonb OR source.sequence<=(h.selector->>'throughSequence')::numeric)
   ELSE openpc.evidence_hold_source_match(h.selector,openpc.evidence_hold_record_metadata(source))
  END) IS DISTINCT FROM false) THEN blockers:=array_append(blockers,'ACTIVE_HOLD'); END IF;
 -- References to immutable object metadata remain valid; a live disclosure
 -- depends on the payload and must finish/expire. Unknown future physical FKs
 -- require their owning clearance protocol before this adapter can resume.
 IF EXISTS(SELECT 1 FROM control.protected_proof_access a WHERE a.participant_id=object.participant_id
  AND a.privacy_domain_id=object.privacy_domain_id AND a.object_id=object.object_id
  AND a.consumed_at IS NULL AND a.expires_at>clock_timestamp())
  OR EXISTS(SELECT 1 FROM control.evidence_remote_archive_intent i WHERE i.participant_id=object.participant_id
   AND i.privacy_domain_id=object.privacy_domain_id AND i.protected_object_id=object.object_id AND i.source_kind='PROTECTED_PROOF'
   AND (NOT openpc.protected_remote_archive_covers(object.participant_id,object.privacy_domain_id,object.object_id,i.sink_id)
    OR NOT EXISTS(SELECT 1 FROM control.protected_proof_checkpoint c WHERE c.participant_id=object.participant_id
     AND c.privacy_domain_id=object.privacy_domain_id AND c.object_id=object.object_id AND c.sink_id=i.sink_id
     AND openpc.protected_remote_checkpoint_valid(c))))
  OR EXISTS(SELECT 1 FROM pg_constraint WHERE contype='f' AND confrelid='control.protected_proof_payload'::regclass)
 THEN blockers:=array_append(blockers,'REFERENCES'); END IF;
 SELECT * INTO rule FROM control.retention_policy p WHERE p.participant_id=object.participant_id
  AND p.privacy_domain_id=object.privacy_domain_id AND p.data_class='RAW_SOURCE_BODY' AND p.active_until IS NULL;
 IF NOT FOUND THEN blockers:=array_append(blockers,'NO_ACTIVE_POLICY');
 ELSE
  IF rule.deletion_mode<>'ROW_DELETE' THEN blockers:=array_append(blockers,'UNSUPPORTED_MODE'); END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('sinkId',chosen.sink_id,'checkpointDigest',chosen.checkpoint_digest,
   'receiptDigest',chosen.receipt_digest,'acknowledgedAtMicros',chosen.ack_micros::text)
   ORDER BY chosen.ack_micros,chosen.sink_id),'[]'::jsonb),max(chosen.ack_micros)
   INTO receipts,quorum_micros FROM (
    SELECT c.sink_id,c.checkpoint_digest,c.receipt_digest,floor(extract(epoch from c.acknowledged_at)*1000000) ack_micros
    FROM control.protected_proof_checkpoint c WHERE c.participant_id=object.participant_id
     AND c.privacy_domain_id=object.privacy_domain_id AND c.object_id=object.object_id
     AND c.payload_digest=expected_payload_digest AND c.ciphertext_bytes=octet_length(payload.ciphertext)
     AND ((c.receipt->'object'->>'objectDigest'=object.object_digest AND c.receipt->'object'->'source'=object.source
     AND c.receipt->>'versionId'=expected_payload_digest AND c.receipt->>'receiptDigest'=c.receipt_digest) OR (openpc.protected_remote_checkpoint_valid(c)
      AND openpc.protected_remote_archive_covers(object.participant_id,object.privacy_domain_id,object.object_id,c.sink_id)))
    ORDER BY c.acknowledged_at,c.sink_id LIMIT rule.sink_quorum) chosen;
  IF jsonb_array_length(receipts)<>rule.sink_quorum THEN blockers:=array_append(blockers,'SINK_QUORUM'); END IF;
  source_micros:=floor(extract(epoch from source.occurred_at)*1000000);
  eligible_micros:=greatest(source_micros+rule.retention_period_ms*1000,
   coalesce(quorum_micros,floor(extract(epoch from object.created_at)*1000000))+rule.local_grace_ms*1000,
   floor(extract(epoch from object.retain_until)*1000000));
  IF eligible_micros>floor(extract(epoch from clock_timestamp())*1000000) THEN blockers:=array_append(blockers,'RETENTION_NOT_ELAPSED'); END IF;
  selection:=jsonb_build_object('version','OPENPC_RAW_PROOF_DELETION_BATCH_V1',
   'participantId','urn:openpc:participant:'||object.participant_id::text,'privacyDomainId',object.privacy_domain_id::text,
   'retentionPolicyId','urn:openpc:resource:'||rule.retention_policy_id::text,'policyDigest',rule.policy_digest,
   'targetDatabase','openpc_control','dataClass','RAW_SOURCE_BODY','deletionMode','ROW_DELETE',
   'objectRef','urn:openpc:resource:'||object.object_id::text,'objectVersion',object.object_version::text,
   'objectDigest',object.object_digest,'payloadDigest',expected_payload_digest,'ciphertextBytes',octet_length(payload.ciphertext),
   'source',object.source,'eligibleAfterMicros',eligible_micros::text,'sinkReceipts',receipts);
  before_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
   'domain','pc.evidence.raw-proof-before.v1','participantId',object.participant_id::text,'privacyDomainId',object.privacy_domain_id::text,
   'objectRef',selection->'objectRef','objectVersion',selection->'objectVersion','objectDigest',object.object_digest,
   'payloadDigest',expected_payload_digest,'ciphertextBytes',octet_length(payload.ciphertext))),'UTF8')),'hex');
 END IF;
 RETURN jsonb_build_object('objectRef','urn:openpc:resource:'||object.object_id::text,'localPayload','RETAINED',
  'eligible',cardinality(blockers)=0,'blockers',to_jsonb(blockers),'selection',selection,'beforeDigest',before_digest);
END $$;
REVOKE ALL ON FUNCTION openpc.raw_proof_deletion_object_plan(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.raw_proof_deletion_object_plan(uuid) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.raw_proof_deletion_target(plan jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('objectRef',plan->'selection'->'objectRef','objectVersion',plan->'selection'->'objectVersion',
  'objectDigest',plan->'selection'->'objectDigest','payloadDigest',plan->'selection'->'payloadDigest',
  'ciphertextBytes',plan->'selection'->'ciphertextBytes','beforeDigest',plan->'beforeDigest')
$$;

CREATE OR REPLACE FUNCTION openpc.raw_proof_deletion_batch_plan(anchor uuid,previous uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE plan jsonb; selected jsonb; targets jsonb:='[]'::jsonb; target jsonb; candidate record;
 prior control.deletion_job; receipt_digest text; next_job uuid; position integer:=0;
 cursor jsonb:='null'::jsonb; prior_policy jsonb; blockers jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF (anchor IS NULL)=(previous IS NULL) THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF previous IS NOT NULL THEN
  SELECT * INTO prior FROM control.deletion_job j WHERE j.participant_id=current_setting('openpc.participant_id')::uuid
   AND j.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid AND j.deletion_job_id=previous;
  IF NOT FOUND OR prior.state<>'SUCCEEDED' OR prior.selection->>'version'<>'OPENPC_RAW_PROOF_DELETION_BATCH_V1' THEN RETURN NULL; END IF;
  SELECT 'sha256:'||encode(a.receipt_digest,'hex') INTO receipt_digest FROM control.audit_occurrence a
   WHERE a.participant_id=prior.participant_id AND a.privacy_domain_id=prior.privacy_domain_id
    AND a.aggregate_type='evidence-deletion' AND a.aggregate_id=prior.deletion_job_id AND a.operation_id=prior.operation_id
    AND a.profile_id='pc.control.evidence-deletion.raw-proof' AND a.catalog_operation_id='CFG-OP-DELETE-RAW-PROOF-BATCH';
  IF receipt_digest IS NULL THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  targets:=prior.selection->'targets';position:=(prior.selection->>'batchIndex')::integer+1;
  cursor:=jsonb_build_object('deletionJobId','urn:openpc:resource:'||previous::text,'receiptDigest',receipt_digest);
  SELECT deletion_job_id INTO next_job FROM control.deletion_job j WHERE j.participant_id=prior.participant_id
   AND j.privacy_domain_id=prior.privacy_domain_id AND j.previous_deletion_job_id=previous AND j.state='SUCCEEDED';
  IF next_job IS NOT NULL OR position=jsonb_array_length(targets) THEN
   RETURN jsonb_build_object('objectRef',prior.selection->'objectRef','localPayload','DELETED','eligible',false,
    'blockers','[]'::jsonb,'selection',null,'beforeDigest',null,
    'continuationState',CASE WHEN next_job IS NULL THEN 'COMPLETE' ELSE 'ADVANCED' END,
    'nextDeletionJobId',CASE WHEN next_job IS NULL THEN NULL ELSE 'urn:openpc:resource:'||next_job::text END);
  END IF;
  target:=targets->position;
  prior_policy:=jsonb_build_array(prior.selection->'retentionPolicyId',prior.selection->'policyDigest');
  plan:=openpc.raw_proof_deletion_object_plan(right(target->>'objectRef',36)::uuid);
 ELSE
  plan:=openpc.raw_proof_deletion_object_plan(anchor);
  IF plan IS NULL THEN RETURN NULL; END IF;
  IF plan->'selection'='null'::jsonb THEN RETURN plan||jsonb_build_object('continuationState','BLOCKED','nextDeletionJobId',null); END IF;
  FOR candidate IN SELECT o.object_id FROM control.protected_proof_object o
   JOIN control.protected_proof_payload p USING(participant_id,privacy_domain_id,object_id)
   WHERE o.participant_id=current_setting('openpc.participant_id')::uuid AND o.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid
    AND o.object_id>=anchor ORDER BY o.object_id LIMIT 16 LOOP
   selected:=openpc.raw_proof_deletion_object_plan(candidate.object_id);
   IF selected->'selection'='null'::jsonb THEN RETURN selected||jsonb_build_object('continuationState','BLOCKED','nextDeletionJobId',null); END IF;
   targets:=targets||jsonb_build_array(openpc.raw_proof_deletion_target(selected));
  END LOOP;
  target:=targets->0;
 END IF;
 IF plan IS NULL OR target IS NULL THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 blockers:=plan->'blockers';
 IF plan->'selection'='null'::jsonb THEN RETURN plan||jsonb_build_object('continuationState','BLOCKED','nextDeletionJobId',null); END IF;
 IF openpc.raw_proof_deletion_target(plan) IS DISTINCT FROM target OR
  (prior_policy IS NOT NULL AND prior_policy IS DISTINCT FROM jsonb_build_array(plan->'selection'->'retentionPolicyId',plan->'selection'->'policyDigest'))
 THEN blockers:=blockers||jsonb_build_array('STALE_SELECTION'); END IF;
 selected:=(plan->'selection')||jsonb_build_object('targets',targets,'batchIndex',position,'priorCursor',cursor);
 RETURN plan||jsonb_build_object('eligible',jsonb_array_length(blockers)=0,'blockers',blockers,
  'selection',CASE WHEN blockers ? 'STALE_SELECTION' THEN NULL ELSE selected END,
  'continuationState',CASE WHEN jsonb_array_length(blockers)=0 THEN 'READY' ELSE 'BLOCKED' END,'nextDeletionJobId',null);
END $$;
REVOKE ALL ON FUNCTION openpc.raw_proof_deletion_target(jsonb),openpc.raw_proof_deletion_batch_plan(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.raw_proof_deletion_target(jsonb),openpc.raw_proof_deletion_batch_plan(uuid,uuid) TO openpc_control_runtime;

GRANT DELETE ON control.protected_proof_payload TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.raw_proof_deletion_selector_digest(selection jsonb)
RETURNS text LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
  'domain','pc.evidence.raw-proof-selector.v1','participantId',selection->'participantId',
  'privacyDomainId',selection->'privacyDomainId','objectRef',selection->'objectRef','objectVersion',selection->'objectVersion')),'UTF8')),'hex')
$$;

CREATE OR REPLACE FUNCTION openpc.guard_raw_proof_deletion_job(operation text,old_job control.deletion_job,new_job control.deletion_job)
RETURNS control.deletion_job LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE plan jsonb; item control.evidence_deletion_item; current_bytes integer;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF operation NOT IN ('INSERT','UPDATE') OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_DELETIONS_CREATE_RAW_BATCH-V1'
  OR new_job.participant_id<>current_setting('openpc.participant_id')::uuid
  OR new_job.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR new_job.operation_id<>current_setting('openpc.operation_id')::uuid
  OR new_job.target_data_class<>'RAW_SOURCE_BODY' OR new_job.target_database<>'openpc_control'
  OR new_job.selection->>'version'<>'OPENPC_RAW_PROOF_DELETION_BATCH_V1'
  OR new_job.stream_id IS NOT NULL OR new_job.segment_id IS NOT NULL
  OR new_job.protected_object_id IS DISTINCT FROM right(new_job.selection->>'objectRef',36)::uuid
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||new_job.participant_id::text,0));
 SELECT coalesce(sum(octet_length(ciphertext)),0)::integer INTO current_bytes FROM control.protected_proof_payload
  WHERE participant_id=new_job.participant_id AND privacy_domain_id=new_job.privacy_domain_id;
 IF operation='INSERT' THEN
  new_job.previous_deletion_job_id:=right(new_job.selection->'priorCursor'->>'deletionJobId',36)::uuid;
  IF new_job.previous_deletion_job_id IS NOT NULL THEN
   PERFORM 1 FROM control.deletion_job WHERE participant_id=new_job.participant_id AND privacy_domain_id=new_job.privacy_domain_id
    AND deletion_job_id=new_job.previous_deletion_job_id FOR UPDATE;
  END IF;
  plan:=openpc.evidence_deletion_selection_plan(new_job.selection);
  IF plan IS NULL OR NOT (plan->>'eligible')::boolean OR plan->'selection' IS DISTINCT FROM new_job.selection
   OR plan->>'beforeDigest' IS DISTINCT FROM new_job.before_digest OR new_job.state<>'EXECUTING' OR new_job.revision<>0
   OR new_job.retention_policy_id IS DISTINCT FROM right(new_job.selection->>'retentionPolicyId',36)::uuid
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  new_job.target_selector_digest:=openpc.raw_proof_deletion_selector_digest(new_job.selection);
  new_job.eligibility_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(new_job.selection),'UTF8')),'hex');
  new_job.before_used_bytes:=current_bytes;new_job.after_used_bytes:=NULL;
  new_job.started_at:=clock_timestamp();new_job.created_at:=new_job.started_at;
 ELSE
  IF old_job.target_data_class<>'RAW_SOURCE_BODY' OR old_job.state<>'EXECUTING' OR new_job.state<>'SUCCEEDED'
   OR old_job.revision<>0 OR new_job.revision<>1
   OR (to_jsonb(new_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at']) IS DISTINCT FROM
      (to_jsonb(old_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at'])
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO STRICT item FROM control.evidence_deletion_item WHERE participant_id=new_job.participant_id
   AND privacy_domain_id=new_job.privacy_domain_id AND deletion_job_id=new_job.deletion_job_id;
  IF item.protected_object_id IS DISTINCT FROM new_job.protected_object_id OR item.object_digest<>new_job.selection->>'payloadDigest'
   OR current_bytes<>new_job.before_used_bytes-item.ciphertext_bytes
   OR EXISTS(SELECT 1 FROM control.protected_proof_payload WHERE participant_id=new_job.participant_id
    AND privacy_domain_id=new_job.privacy_domain_id AND object_id=new_job.protected_object_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  new_job.deleted_count:=1;new_job.deleted_bytes:=item.ciphertext_bytes;new_job.after_used_bytes:=current_bytes;
  new_job.after_digest:=openpc.evidence_deletion_after_digest(new_job.target_selector_digest);
  new_job.completed_at:=clock_timestamp();
 END IF;
 new_job.updated_at:=clock_timestamp();RETURN new_job;
END $$;

CREATE OR REPLACE FUNCTION openpc.record_raw_proof_payload_deletion(payload control.protected_proof_payload)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE job control.deletion_job; plan jsonb;
BEGIN
 IF pg_trigger_depth()<>1 OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_DELETIONS_CREATE_RAW_BATCH-V1'
  OR payload.participant_id<>current_setting('openpc.participant_id')::uuid
  OR payload.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||payload.participant_id::text,0));
 SELECT * INTO STRICT job FROM control.deletion_job WHERE participant_id=payload.participant_id
  AND privacy_domain_id=payload.privacy_domain_id AND operation_id=current_setting('openpc.operation_id')::uuid
  AND target_data_class='RAW_SOURCE_BODY' AND state='EXECUTING' AND revision=0 AND protected_object_id=payload.object_id FOR UPDATE;
 plan:=openpc.evidence_deletion_selection_plan(job.selection);
 IF plan IS NULL OR NOT (plan->>'eligible')::boolean OR plan->'selection' IS DISTINCT FROM job.selection
  OR plan->>'beforeDigest' IS DISTINCT FROM job.before_digest
  OR octet_length(payload.ciphertext)<>(job.selection->>'ciphertextBytes')::integer
  OR openpc.protected_proof_payload_digest(payload)<>job.selection->>'payloadDigest' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 INSERT INTO control.evidence_deletion_item(participant_id,privacy_domain_id,deletion_job_id,protected_object_id,object_digest,ciphertext_bytes)
 VALUES(payload.participant_id,payload.privacy_domain_id,job.deletion_job_id,payload.object_id,job.selection->>'payloadDigest',octet_length(payload.ciphertext));
END $$;

CREATE OR REPLACE FUNCTION openpc.raw_proof_deletion_item_matches(item control.evidence_deletion_item)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM control.deletion_job j JOIN control.protected_proof_payload p
  ON p.participant_id=j.participant_id AND p.privacy_domain_id=j.privacy_domain_id AND p.object_id=j.protected_object_id
  WHERE j.participant_id=(item).participant_id AND j.privacy_domain_id=(item).privacy_domain_id AND j.deletion_job_id=(item).deletion_job_id
   AND j.operation_id=current_setting('openpc.operation_id')::uuid AND j.state='EXECUTING' AND j.target_data_class='RAW_SOURCE_BODY'
   AND j.protected_object_id=(item).protected_object_id AND (item).segment_id IS NULL
   AND j.selection->>'payloadDigest'=(item).object_digest AND openpc.protected_proof_payload_digest(p)=(item).object_digest
   AND octet_length(p.ciphertext)=(item).ciphertext_bytes)
$$;

CREATE OR REPLACE FUNCTION openpc.raw_proof_deletion_effect_matches(job control.deletion_job,item control.evidence_deletion_item)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT (job).target_data_class='RAW_SOURCE_BODY' AND (job).protected_object_id=(item).protected_object_id
  AND (job).selection->>'payloadDigest'=(item).object_digest AND (job).segment_id IS NULL AND (item).segment_id IS NULL
  AND NOT EXISTS(SELECT 1 FROM control.protected_proof_payload p WHERE p.participant_id=(job).participant_id
   AND p.privacy_domain_id=(job).privacy_domain_id AND p.object_id=(job).protected_object_id)
  AND (SELECT coalesce(sum(octet_length(p.ciphertext)),0) FROM control.protected_proof_payload p
   WHERE p.participant_id=(job).participant_id AND p.privacy_domain_id=(job).privacy_domain_id)=(job).after_used_bytes
$$;
REVOKE ALL ON FUNCTION openpc.raw_proof_deletion_selector_digest(jsonb),
 openpc.guard_raw_proof_deletion_job(text,control.deletion_job,control.deletion_job),
 openpc.record_raw_proof_payload_deletion(control.protected_proof_payload),
 openpc.raw_proof_deletion_item_matches(control.evidence_deletion_item),
 openpc.raw_proof_deletion_effect_matches(control.deletion_job,control.evidence_deletion_item) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.raw_proof_deletion_selector_digest(jsonb),
 openpc.guard_raw_proof_deletion_job(text,control.deletion_job,control.deletion_job),
 openpc.record_raw_proof_payload_deletion(control.protected_proof_payload),
 openpc.raw_proof_deletion_item_matches(control.evidence_deletion_item),
 openpc.raw_proof_deletion_effect_matches(control.deletion_job,control.evidence_deletion_item) TO openpc_control_runtime;


ALTER TABLE control.evidence_rpc_provenance FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.evidence_rpc_provenance FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT ON control.evidence_rpc_provenance TO openpc_control_runtime,openpc_control_reader,openpc_control_worker;
GRANT INSERT ON control.evidence_rpc_provenance TO openpc_control_worker;
CREATE OR REPLACE FUNCTION openpc.guard_rpc_provenance()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p jsonb:=NEW.projection; a jsonb:=p->'activation'; t jsonb:=p->'transition'; deleted_source control.evidence_catalogue;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF TG_OP='DELETE' THEN
  SELECT * INTO STRICT deleted_source FROM control.evidence_catalogue WHERE participant_id=OLD.participant_id AND privacy_domain_id=OLD.privacy_domain_id
   AND stream_id=OLD.stream_id AND record_id=OLD.record_id;
  PERFORM openpc.record_projection_deletion(deleted_source,'NORMALIZED_JSON_PROJECTION',OLD.projection);RETURN OLD;
 END IF;
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 IF EXISTS(SELECT 1 FROM control.evidence_projection_retirement r WHERE r.participant_id=NEW.participant_id AND r.privacy_domain_id=NEW.privacy_domain_id
  AND r.data_class='NORMALIZED_JSON_PROJECTION' AND r.stream_id=NEW.stream_id AND r.record_id=NEW.record_id) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_EXPORT_RECORDS-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid
  OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF p-ARRAY['integrity','activationIntegrity','authority','currentAuthority','providerEffect','chainFinality',
  'decisionId','targetRuntimeId','spoolId','sourceSequence','sourceDigest','capsuleDigest','reservedAtNs','occurredAtNs','transition','activation']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(p))<>16
  OR a-ARRAY['operationId','attemptId','configurationWorkId','generationId','generationDigest','receiptDigest','signerId','verificationKeyDigest']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(a))<>8
  OR t-ARRAY['phase','traceId','requestDigest','decisionDigest','responseDigest','authorityBindingDigest','sourceScopeDigest','operationId',
   'pcCode','decisionEffect','boundary','sourceSegmentId','sourceRecordDigest','admittedAtNs']<>'{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(t))<>14
  OR p->>'integrity' IS DISTINCT FROM 'AEAD_CHAIN_VERIFIED_AT_CUSTODY'
  OR p->>'activationIntegrity' IS DISTINCT FROM 'ACTIVATION_COSE_VERIFIED_AT_CUSTODY'
  OR p->>'authority' IS DISTINCT FROM 'NONE' OR p->>'currentAuthority' IS DISTINCT FROM 'NOT_ESTABLISHED'
  OR p->>'providerEffect' IS DISTINCT FROM 'NOT_ESTABLISHED' OR p->>'chainFinality' IS DISTINCT FROM 'NOT_ESTABLISHED'
  OR NEW.projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
  OR NEW.record_id<>'rpc:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_array(p->>'targetRuntimeId',p->>'spoolId')),'UTF8')),'hex')||':'||(p->>'sourceSequence')
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.evidence_catalogue c WHERE c.participant_id=NEW.participant_id
  AND c.privacy_domain_id=NEW.privacy_domain_id AND c.stream_id=NEW.stream_id AND c.record_id=NEW.record_id
  AND c.evidence_class='EFFECT' AND c.source_format='OPENPC_RPC_DECISION_TRANSITION_V1'
  AND c.receipt_digest=p->>'sourceDigest' AND c.sequence::text=p->>'sourceSequence'
  AND extract(epoch FROM c.occurred_at)*1000000=floor((p->>'occurredAtNs')::numeric/1000)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF NOT EXISTS(SELECT 1 FROM control.runtime_activation_observation o JOIN control.configuration_work w
  ON w.participant_id=o.participant_id AND w.privacy_domain_id=o.privacy_domain_id AND w.configuration_work_id=o.configuration_work_id
   AND w.runtime_target_id=o.runtime_target_id AND w.runtime_configuration_generation_id=o.runtime_configuration_generation_id
   AND w.operation_id=o.operation_id AND w.execution_attempt_id=o.execution_attempt_id AND w.generation_digest=o.generation_digest AND w.state='COMPLETED'
  WHERE o.participant_id=NEW.participant_id AND o.privacy_domain_id=NEW.privacy_domain_id
   AND o.runtime_target_id::text=p->>'targetRuntimeId' AND o.capsule_digest=p->>'capsuleDigest'
   AND o.operation_id::text=a->>'operationId' AND o.execution_attempt_id::text=a->>'attemptId'
   AND o.configuration_work_id::text=a->>'configurationWorkId' AND o.runtime_configuration_generation_id::text=a->>'generationId'
   AND o.generation_digest=a->>'generationDigest'
   AND 'sha256:'||encode(sha256(decode(o.activation_receipt->>'activationReceiptCoseHex','hex')),'hex')=a->>'receiptDigest') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_rpc_provenance_guard ON control.evidence_rpc_provenance;
CREATE TRIGGER evidence_rpc_provenance_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_rpc_provenance
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_rpc_provenance();




CREATE OR REPLACE FUNCTION openpc.rpc_retirement_identity(p jsonb)
RETURNS text LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_array(
  p->'decisionId',p->'targetRuntimeId',p->'spoolId',p->'capsuleDigest',p->'reservedAtNs',
  p->'transition'->'requestDigest',p->'activation')),'UTF8')),'hex')
$$;
CREATE OR REPLACE FUNCTION openpc.rpc_retirement_terminal(p jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT coalesce(p->'transition'->>'phase' IN ('INTERRUPTED','RELEASED','SOURCE_READ_RELEASED')
  OR (p->'transition'->>'phase'='COMMITTED' AND p->'transition'->>'decisionEffect'
   IN ('DENY_TERMINAL','AUTHORIZED_EMPTY','WITHHOLD_STALE')),false)
$$;
CREATE OR REPLACE FUNCTION openpc.rpc_retirement_witness(c control.evidence_catalogue,p jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('identityDigest',openpc.rpc_retirement_identity(p),
  'terminalEvidenceId','urn:openpc:resource:'||(c).evidence_id::text,'terminalRecordId',(c).record_id,
  'terminalSequence',(c).sequence::text,'terminalSourceDigest',(c).receipt_digest,
  'terminalProjectionDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex'),
  'terminalOccurredAtNs',p->'occurredAtNs','terminalPhase',p->'transition'->'phase',
  'terminalEffect',p->'transition'->'decisionEffect','terminalDecisionDigest',p->'transition'->'decisionDigest',
  'sourceScopeDigest',p->'transition'->'sourceScopeDigest','authorityBindingDigest',p->'transition'->'authorityBindingDigest')
$$;
CREATE OR REPLACE FUNCTION openpc.rpc_projection_closed_by(p jsonb,w jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT coalesce(w->>'identityDigest'=openpc.rpc_retirement_identity(p)
  AND (w->>'terminalSequence')::numeric>=(p->>'sourceSequence')::numeric
  AND (w->>'terminalOccurredAtNs')::numeric>=(p->>'occurredAtNs')::numeric
  AND CASE p->'transition'->>'phase'
   WHEN 'RESERVED' THEN w->>'terminalPhase' IN ('INTERRUPTED','RELEASED')
    OR (w->>'terminalPhase'='COMMITTED' AND w->>'terminalEffect' IN ('DENY_TERMINAL','AUTHORIZED_EMPTY','WITHHOLD_STALE'))
   WHEN 'SOURCE_READ_STARTED' THEN w->>'terminalPhase'='SOURCE_READ_RELEASED'
    AND w->'sourceScopeDigest'=p->'transition'->'sourceScopeDigest'
    AND w->'authorityBindingDigest'=p->'transition'->'authorityBindingDigest'
   WHEN 'COMMITTED' THEN CASE WHEN p->'transition'->>'decisionEffect'='ALLOW_FORWARD'
    THEN w->>'terminalPhase'='RELEASED' AND w->'terminalDecisionDigest'=p->'transition'->'decisionDigest'
    ELSE openpc.rpc_retirement_terminal(p) AND w->>'terminalSourceDigest'=p->>'sourceDigest'
     AND w->>'terminalPhase'=p->'transition'->>'phase' AND w->'terminalEffect'=p->'transition'->'decisionEffect'
     AND w->>'terminalSequence'=p->>'sourceSequence'
     AND w->>'terminalProjectionDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex') END
   ELSE openpc.rpc_retirement_terminal(p) AND w->>'terminalSourceDigest'=p->>'sourceDigest'
    AND w->>'terminalPhase'=p->'transition'->>'phase' AND w->>'terminalSequence'=p->>'sourceSequence'
    AND w->>'terminalProjectionDigest'='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex') END,false)
$$;
CREATE OR REPLACE FUNCTION openpc.rpc_projection_retirement_witness(c control.evidence_catalogue,p jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE witnesses jsonb;
BEGIN
 -- Custody authenticates the contiguous original journal. Both live witnesses
 -- and intentionally retired witnesses retain the original catalogue anchor.
 -- A missing/corrupt projection cannot masquerade as a successful retirement.
 SELECT jsonb_agg(DISTINCT witness) INTO witnesses FROM (
  SELECT openpc.rpc_retirement_witness(s,r.projection) witness
   FROM control.evidence_rpc_provenance r JOIN control.evidence_catalogue s USING(participant_id,privacy_domain_id,stream_id,record_id)
   WHERE r.participant_id=(c).participant_id AND r.privacy_domain_id=(c).privacy_domain_id AND r.stream_id=(c).stream_id
    AND r.projection->>'decisionId'=p->>'decisionId' AND openpc.rpc_retirement_terminal(r.projection)
    AND r.projection->>'sourceSequence'=s.sequence::text AND r.projection->>'sourceDigest'=s.receipt_digest
    AND s.source_format='OPENPC_RPC_DECISION_TRANSITION_V1'
    AND r.projection_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(r.projection),'UTF8')),'hex')
  UNION ALL
  SELECT (j.selection->'rpcClosure')-'archive' FROM control.evidence_projection_retirement r
   JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
   JOIN control.evidence_catalogue s ON s.participant_id=r.participant_id AND s.privacy_domain_id=r.privacy_domain_id
    AND s.stream_id=r.stream_id AND s.record_id=r.record_id
   WHERE r.participant_id=(c).participant_id AND r.privacy_domain_id=(c).privacy_domain_id AND r.stream_id=(c).stream_id
    AND r.data_class='NORMALIZED_JSON_PROJECTION' AND j.state='SUCCEEDED'
    AND j.selection->>'sourceKind'='RPC_CLOSED_TRANSITION'
    AND j.selection->'rpcClosure'->>'terminalRecordId'=r.record_id
    AND j.selection->'rpcClosure'->>'terminalSourceDigest'=r.source_receipt_digest AND s.receipt_digest=r.source_receipt_digest
    AND j.selection->'rpcClosure'->>'terminalProjectionDigest'=r.projection_digest
    AND r.retirement_digest=openpc.projection_retirement_digest(r)
 ) candidates WHERE openpc.rpc_projection_closed_by(p,witness);
 IF jsonb_array_length(witnesses)<>1 THEN RETURN NULL; END IF;
 RETURN witnesses->0;
END $$;
REVOKE ALL ON FUNCTION openpc.rpc_retirement_identity(jsonb),openpc.rpc_retirement_terminal(jsonb),
 openpc.rpc_retirement_witness(control.evidence_catalogue,jsonb),openpc.rpc_projection_closed_by(jsonb,jsonb),
 openpc.rpc_projection_retirement_witness(control.evidence_catalogue,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.rpc_retirement_identity(jsonb),openpc.rpc_retirement_terminal(jsonb),
 openpc.rpc_retirement_witness(control.evidence_catalogue,jsonb),openpc.rpc_projection_closed_by(jsonb,jsonb),
 openpc.rpc_projection_retirement_witness(control.evidence_catalogue,jsonb) TO openpc_control_runtime,openpc_control_reader;


CREATE OR REPLACE FUNCTION openpc.rpc_retired_catalogue_proof(source control.evidence_catalogue)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE proof jsonb;
BEGIN
 IF (source).evidence_class<>'EFFECT' OR (source).source_format<>'OPENPC_RPC_DECISION_TRANSITION_V1' THEN RETURN NULL; END IF;
 SELECT jsonb_build_object('recordId',e.evidence_record_id::text,'recordDigest','sha256:'||encode(sha256(a.cose_sign1),'hex'),
  'recordedAtNs',a.recorded_at_ns::text,'sourceEvidenceId','urn:openpc:resource:'||(source).evidence_id::text,
  'sourceRecordId',(source).record_id,'sourceReceiptDigest',(source).receipt_digest,'retirementDigest',r.retirement_digest,
  'sourceFormat',e.evidence_format,'deletionJobId',j.deletion_job_id::text,'operationId',j.operation_id::text,
  'sourceKind',j.selection->>'sourceKind','identityDigest',j.selection->'rpcClosure'->>'identityDigest') INTO STRICT proof
 FROM control.evidence_projection_retirement r
 JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
 JOIN control.audit_occurrence a ON a.participant_id=j.participant_id AND a.privacy_domain_id=j.privacy_domain_id
  AND a.operation_id=j.operation_id AND a.aggregate_id=j.deletion_job_id AND a.aggregate_type='evidence-deletion'
 JOIN control.evidence_record e ON e.participant_id=a.participant_id AND e.privacy_domain_id=a.privacy_domain_id
  AND e.receipt_id=a.receipt_id AND e.receipt_digest=a.receipt_digest AND e.evidence_role='BUSINESS_TRANSITION_RECEIPT' AND e.custody='CONTROL_STORE'
 JOIN control.mutation_candidate candidate ON candidate.participant_id=j.participant_id AND candidate.privacy_domain_id=j.privacy_domain_id
  AND candidate.resource_id=j.deletion_job_id AND candidate.consumed_operation_id=j.operation_id AND candidate.candidate_digest=a.candidate_digest
 WHERE r.participant_id=(source).participant_id AND r.privacy_domain_id=(source).privacy_domain_id
  AND r.evidence_id=(source).evidence_id AND r.stream_id=(source).stream_id AND r.record_id=(source).record_id
  AND r.segment_id=(source).segment_id AND r.sequence=(source).sequence AND r.source_receipt_digest=(source).receipt_digest
  AND r.data_class='NORMALIZED_JSON_PROJECTION' AND r.retirement_digest=openpc.projection_retirement_digest(r)
  AND j.state='SUCCEEDED' AND j.revision=1 AND j.target_data_class='NORMALIZED_JSON_PROJECTION'
  AND ((j.selection->>'sourceKind'='RPC_CLOSED_TRANSITION'
    AND j.selection->'rpcClosure'->>'identityDigest' ~ '^sha256:[0-9a-f]{64}$')
   OR (j.selection->>'sourceKind'='RPC_PRE_ADMISSION_DENIAL' AND NOT j.selection ? 'rpcClosure'))
  AND openpc.projection_deletion_effect_matches(j,r)
  AND candidate.state='CONSUMED' AND candidate.candidate_document->'selection'=j.selection
  AND candidate.candidate_document->>'beforeDigest'=j.before_digest
  AND a.profile_id='pc.control.evidence-deletion.projection' AND a.profile_version=1
  AND a.action_intent_id='ACT-EVIDENCE_DELETIONS_CREATE_PROJECTION_BATCH-V1' AND a.catalog_operation_id='CFG-OP-DELETE-PROJECTION-BATCH'
  AND a.before_existence=0 AND a.before_revision=0 AND a.after_existence=1 AND a.after_revision=1
  AND openpc.business_cbor(a.after_state_preimage)->8=openpc.evidence_deletion_state_projection(j)
  AND sha256(a.receipt_cbor)=a.receipt_digest AND sha256(a.after_state_preimage)=a.after_state_digest;
 RETURN proof;
EXCEPTION WHEN insufficient_privilege OR no_data_found OR too_many_rows THEN RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION openpc.rpc_retired_catalogue_proof(control.evidence_catalogue) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.rpc_retired_catalogue_proof(control.evidence_catalogue) TO openpc_control_runtime,openpc_control_reader,openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.rpc_retired_catalogue_has_references(source control.evidence_catalogue)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE proof jsonb;
BEGIN
 proof:=openpc.rpc_retired_catalogue_proof(source);
 IF proof IS NULL THEN RETURN true; END IF;
 -- A pre-admission denial had no admitted request or terminal successor. Its
 -- governed normalized-retirement owner already verified that exact phase and
 -- null request/response. Do not fabricate a closed-transition identity/witness.
 -- Preserve any still-live exact projection; the common search owner separately
 -- checks custody, export, protected-object and catalogue references.
 IF proof->>'sourceKind'='RPC_PRE_ADMISSION_DENIAL' THEN
  RETURN EXISTS(SELECT 1 FROM control.evidence_rpc_provenance sibling
   WHERE sibling.participant_id=(source).participant_id AND sibling.privacy_domain_id=(source).privacy_domain_id
    AND sibling.stream_id=(source).stream_id AND sibling.record_id=(source).record_id);
 END IF;
 RETURN EXISTS(SELECT 1 FROM control.evidence_rpc_provenance sibling WHERE sibling.participant_id=(source).participant_id
  AND sibling.privacy_domain_id=(source).privacy_domain_id AND sibling.stream_id=(source).stream_id
  AND openpc.rpc_retirement_identity(sibling.projection)=proof->>'identityDigest');
EXCEPTION WHEN insufficient_privilege THEN RETURN true;
END $$;
REVOKE ALL ON FUNCTION openpc.rpc_retired_catalogue_has_references(control.evidence_catalogue) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.rpc_retired_catalogue_has_references(control.evidence_catalogue) TO openpc_control_runtime,openpc_control_reader,openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.rpc_local_payload_retirements(stream text,segment uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE source control.evidence_catalogue; proof jsonb; proofs jsonb:='[]'::jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 FOR source IN SELECT c.* FROM control.evidence_catalogue c
  WHERE c.participant_id=current_setting('openpc.participant_id')::uuid AND c.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid
   AND c.stream_id=stream AND c.segment_id=segment AND c.evidence_class='EFFECT' AND c.source_format='OPENPC_RPC_DECISION_TRANSITION_V1'
  ORDER BY c.record_id
 LOOP
  proof:=openpc.rpc_retired_catalogue_proof(source);
  IF proof IS NULL OR openpc.rpc_retired_catalogue_has_references(source) THEN RETURN NULL; END IF;
  proofs:=proofs||jsonb_build_array(jsonb_build_object('evidenceId',proof->>'sourceEvidenceId',
   'recordId',proof->>'sourceRecordId','sourceReceiptDigest',proof->>'sourceReceiptDigest',
   'retirementJobId','urn:openpc:resource:'||(proof->>'deletionJobId'),
   'retirementReceiptDigest',proof->>'recordDigest','retirementDigest',proof->>'retirementDigest'));
 END LOOP;
 RETURN proofs;
END $$;
REVOKE ALL ON FUNCTION openpc.rpc_local_payload_retirements(text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.rpc_local_payload_retirements(text,uuid) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.evidence_catalogue_projection(c control.evidence_catalogue)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('evidenceId',(c).evidence_id::text,'participantId',(c).participant_id::text,
  'privacyDomainId',(c).privacy_domain_id::text,'streamId',(c).stream_id,'recordId',(c).record_id,
  'segmentId',(c).segment_id::text,'sequence',(c).sequence::text,'evidenceClass',(c).evidence_class,
  'sourceFormat',(c).source_format,'receiptDigest',(c).receipt_digest,
  'occurredAt',to_char((c).occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'createdAt',to_char((c).created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
$$;

CREATE OR REPLACE FUNCTION openpc.projection_deletion_object_plan(record uuid,data_class text)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE c control.evidence_catalogue; s record; rule control.retention_policy;
 p jsonb; projection_digest text; projection_bytes integer; metadata jsonb; source_kind text;
 selection jsonb; before_digest text; receipts jsonb; quorum_micros numeric; eligible_micros numeric;
 blockers text[]:=ARRAY[]::text[]; closure jsonb; retired_rpc jsonb; terminal control.evidence_catalogue;
 terminal_segment record; terminal_receipts jsonb; terminal_quorum numeric;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF data_class NOT IN ('NORMALIZED_JSON_PROJECTION','SEARCH_PROJECTION') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 SELECT * INTO c FROM control.evidence_catalogue WHERE evidence_id=record
  AND participant_id=current_setting('openpc.participant_id')::uuid AND privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid;
 IF EXISTS(SELECT 1 FROM control.evidence_projection_retirement r JOIN control.deletion_job j USING(participant_id,privacy_domain_id,deletion_job_id)
  WHERE r.participant_id=current_setting('openpc.participant_id')::uuid AND r.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid
   AND r.evidence_id=record AND r.data_class=projection_deletion_object_plan.data_class AND j.state='SUCCEEDED') THEN
  RETURN jsonb_build_object('evidenceId','urn:openpc:resource:'||record::text,'dataClass',data_class,
   'projectionState','RETIRED','eligible',false,'blockers',jsonb_build_array('ALREADY_DELETED'),'selection',null,'beforeDigest',null);
 END IF;
 IF c.evidence_id IS NULL THEN RETURN NULL; END IF;
 SELECT first_sequence,through_sequence,object_digest,admitted_at INTO STRICT s FROM control.evidence_segment WHERE participant_id=c.participant_id AND privacy_domain_id=c.privacy_domain_id
  AND stream_id=c.stream_id AND segment_id=c.segment_id;
 metadata:=openpc.evidence_hold_record_metadata(c);
 IF data_class='SEARCH_PROJECTION' THEN
  p:=openpc.evidence_catalogue_projection(c); source_kind:='AUTHENTICATION_CATALOGUE';
  IF c.evidence_class='BUSINESS_TRANSITION' AND openpc.retention_policy_receipt_hold_metadata(c) IS NOT NULL THEN
   source_kind:='RETENTION_POLICY_CATALOGUE';
  ELSIF c.evidence_class='EFFECT' AND c.source_format='OPENPC_RPC_DECISION_TRANSITION_V1' THEN
   source_kind:='RPC_RETIRED_CATALOGUE'; retired_rpc:=openpc.rpc_retired_catalogue_proof(c);
   IF retired_rpc IS NULL OR metadata IS NULL THEN blockers:=array_append(blockers,'UNSUPPORTED_SOURCE');
   ELSIF openpc.rpc_retired_catalogue_has_references(c)
   THEN blockers:=array_append(blockers,'REFERENCES'); END IF;
  ELSIF c.evidence_class<>'AUTHENTICATION' OR c.source_format<>'OPENPC_AUTHENTICATION_OCCURRENCE_V1' OR metadata IS NULL THEN
   blockers:=array_append(blockers,'UNSUPPORTED_SOURCE');
  END IF;
  -- The catalogue is still a recovery/reference dependency of local ciphertext.
  -- Its period is never borrowed from AUDIT_EVIDENCE; this is reference clearance.
  IF EXISTS(SELECT 1 FROM control.evidence_segment_payload e WHERE e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
    AND e.stream_id=c.stream_id AND e.segment_id=c.segment_id)
   OR NOT EXISTS(SELECT 1 FROM control.deletion_job j JOIN control.audit_occurrence a
    ON a.participant_id=j.participant_id AND a.privacy_domain_id=j.privacy_domain_id AND a.operation_id=j.operation_id
     AND a.aggregate_type='evidence-deletion' AND a.aggregate_id=j.deletion_job_id
    WHERE j.participant_id=c.participant_id AND j.privacy_domain_id=c.privacy_domain_id AND j.stream_id=c.stream_id
     AND j.segment_id=c.segment_id AND j.target_data_class='AUDIT_EVIDENCE' AND j.state='SUCCEEDED')
   OR EXISTS(SELECT 1 FROM control.protected_proof_object o WHERE o.participant_id=c.participant_id AND o.privacy_domain_id=c.privacy_domain_id
    AND o.source->>'evidenceId'='urn:openpc:resource:'||c.evidence_id::text)
   OR EXISTS(SELECT 1 FROM control.evidence_export_selection e WHERE e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
    AND EXISTS(SELECT 1 FROM jsonb_array_elements(e.selection->'records') r WHERE r->>'evidenceId'='urn:openpc:resource:'||c.evidence_id::text))
   OR EXISTS(SELECT 1 FROM control.evidence_rpc_provenance r WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id)
   OR EXISTS(SELECT 1 FROM control.evidence_fact_provenance r WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id)
   OR EXISTS(SELECT 1 FROM control.evidence_deployment_lineage r WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id)
   OR EXISTS(SELECT 1 FROM control.evidence_deployment_provenance r WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id)
   OR EXISTS(SELECT 1 FROM control.evidence_candidate_archive r WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id)
   OR EXISTS(SELECT 1 FROM control.evidence_candidate_archive_part r WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id)
   OR EXISTS(SELECT 1 FROM control.evidence_runtime_artifact_archive r WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id)
   OR EXISTS(SELECT 1 FROM control.evidence_runtime_artifact_archive_part r WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id)
   OR EXISTS(SELECT 1 FROM pg_constraint WHERE contype='f' AND confrelid='control.evidence_catalogue'::regclass
    AND conname NOT IN ('evidence_rpc_provenance_source_fk','evidence_fact_provenance_source_fk','evidence_deployment_lineage_source_fk','evidence_deployment_provenance_source_fk')
    AND NOT (conname='candidate_archive_manifest_fk' AND conrelid='control.evidence_candidate_archive'::regclass)
    AND NOT (conname='candidate_archive_part_catalogue_fk' AND conrelid='control.evidence_candidate_archive_part'::regclass)
    AND NOT (conname='runtime_artifact_archive_manifest_fk' AND conrelid='control.evidence_runtime_artifact_archive'::regclass)
    AND NOT (conname='runtime_artifact_archive_part_catalogue_fk' AND conrelid='control.evidence_runtime_artifact_archive_part'::regclass))
  THEN blockers:=array_append(blockers,'REFERENCES'); END IF;
 ELSIF c.source_format='PC-DEPLOYMENT-JOURNAL-PROJECTION-1' THEN
  source_kind:='DEPLOYMENT_PROVENANCE';
  SELECT r.projection,r.projection_digest INTO p,projection_digest FROM control.evidence_deployment_provenance r
   WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id;
  IF p IS NULL OR c.evidence_class<>'EFFECT' OR metadata IS NULL
   OR p IS DISTINCT FROM openpc.evidence_deployment_projection(c)
   OR projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
  THEN blockers:=array_append(blockers,'UNSUPPORTED_SOURCE');
  ELSE blockers:=blockers||openpc.deployment_projection_retirement_blockers(c,p); END IF;
  IF EXISTS(SELECT 1 FROM pg_constraint WHERE contype='f' AND confrelid='control.evidence_deployment_provenance'::regclass)
  THEN blockers:=array_append(blockers,'REFERENCES'); END IF;
 ELSIF c.source_format='OPENPC_CANONICAL_FACT_V1' THEN
  source_kind:='FACT_PROVENANCE';
  SELECT r.projection,r.projection_digest INTO p,projection_digest FROM control.evidence_fact_provenance r
   WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id;
  IF p IS NULL OR c.evidence_class<>'EFFECT' OR p->>'receiptDigest'<>c.receipt_digest
   OR p->>'sourceSequence'<>c.sequence::text OR (p->>'admittedAt')::timestamptz<>c.occurred_at OR metadata IS NULL
   OR projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
  THEN blockers:=array_append(blockers,'UNSUPPORTED_SOURCE'); END IF;
  IF metadata->'unresolvedReferences' IS DISTINCT FROM 'false'::jsonb
   OR EXISTS(SELECT 1 FROM pg_constraint WHERE contype='f' AND confrelid='control.evidence_fact_provenance'::regclass)
  THEN blockers:=array_append(blockers,'REFERENCES'); END IF;
 ELSE
  source_kind:='RPC_PRE_ADMISSION_DENIAL';
  SELECT r.projection,r.projection_digest INTO p,projection_digest FROM control.evidence_rpc_provenance r
   WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id;
  IF p IS NULL OR c.evidence_class<>'EFFECT' OR c.source_format<>'OPENPC_RPC_DECISION_TRANSITION_V1'
   OR p->>'sourceDigest'<>c.receipt_digest
   OR p->>'sourceSequence'<>c.sequence::text OR metadata IS NULL
   OR projection_digest<>'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
  THEN blockers:=array_append(blockers,'UNSUPPORTED_SOURCE'); END IF;
  IF p->'transition'->>'phase'<>'PRE_ADMISSION_DENIAL' THEN
   source_kind:='RPC_CLOSED_TRANSITION'; closure:=openpc.rpc_projection_retirement_witness(c,p);
   IF closure IS NULL THEN
    blockers:=array_append(blockers,CASE WHEN p->'transition'->>'phase'='OPERATION_STATUS_RELEASED' THEN 'UNRESOLVED_OPERATION'
     WHEN p->'transition'->>'decisionEffect'='WRITE_AMBIGUITY' THEN 'WRITE_AMBIGUITY' ELSE 'UNRESOLVED_TRANSITION' END);
   ELSE
    SELECT * INTO terminal FROM control.evidence_catalogue t WHERE t.participant_id=c.participant_id AND t.privacy_domain_id=c.privacy_domain_id
     AND t.stream_id=c.stream_id AND t.evidence_id=right(closure->>'terminalEvidenceId',36)::uuid
     AND t.record_id=closure->>'terminalRecordId' AND t.receipt_digest=closure->>'terminalSourceDigest'
     AND t.sequence::text=closure->>'terminalSequence';
    IF NOT FOUND THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
    SELECT first_sequence,through_sequence,object_digest,admitted_at INTO STRICT terminal_segment FROM control.evidence_segment t
     WHERE t.participant_id=c.participant_id AND t.privacy_domain_id=c.privacy_domain_id AND t.stream_id=c.stream_id AND t.segment_id=terminal.segment_id;
    IF terminal.sequence NOT BETWEEN terminal_segment.first_sequence AND terminal_segment.through_sequence
     OR NOT EXISTS(SELECT 1 FROM control.evidence_stream h WHERE h.participant_id=c.participant_id AND h.privacy_domain_id=c.privacy_domain_id
      AND h.stream_id=c.stream_id AND h.last_sequence>=terminal_segment.through_sequence) THEN blockers:=array_append(blockers,'INCOMPLETE_CHECKPOINT'); END IF;
    IF EXISTS(SELECT 1 FROM control.retention_hold h WHERE h.participant_id=c.participant_id
     AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=c.privacy_domain_id) AND h.state='ACTIVE'
     AND openpc.evidence_hold_matches(h.selector,c.participant_id,c.privacy_domain_id,c.stream_id,terminal.segment_id))
    THEN blockers:=array_append(blockers,'ACTIVE_HOLD'); END IF;
   END IF;
  ELSIF p->'transition'->'requestDigest'<>'null'::jsonb OR p->'transition'->'responseDigest'<>'null'::jsonb THEN
   blockers:=array_append(blockers,'UNSUPPORTED_SOURCE');
  END IF;
  IF EXISTS(SELECT 1 FROM pg_constraint WHERE contype='f' AND confrelid='control.evidence_rpc_provenance'::regclass)
  THEN blockers:=array_append(blockers,'REFERENCES'); END IF;
 END IF;
 IF c.sequence NOT BETWEEN s.first_sequence AND s.through_sequence
  OR NOT EXISTS(SELECT 1 FROM control.evidence_stream h WHERE h.participant_id=c.participant_id AND h.privacy_domain_id=c.privacy_domain_id
   AND h.stream_id=c.stream_id AND h.last_sequence>=s.through_sequence)
  OR NOT EXISTS(SELECT 1 FROM control.evidence_checkpoint e WHERE e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id
   AND e.stream_id=c.stream_id AND e.segment_id=c.segment_id AND e.object_digest=s.object_digest AND e.through_sequence=s.through_sequence)
 THEN blockers:=array_append(blockers,'INCOMPLETE_CHECKPOINT'); END IF;
 IF EXISTS(SELECT 1 FROM control.retention_hold h WHERE h.participant_id=c.participant_id
  AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=c.privacy_domain_id) AND h.state='ACTIVE'
  AND openpc.evidence_hold_matches(h.selector,c.participant_id,c.privacy_domain_id,c.stream_id,c.segment_id))
 THEN blockers:=array_append(blockers,'ACTIVE_HOLD'); END IF;
 SELECT * INTO rule FROM control.retention_policy r WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id
  AND r.data_class=projection_deletion_object_plan.data_class AND r.active_until IS NULL;
 IF NOT FOUND THEN blockers:=array_append(blockers,'NO_ACTIVE_POLICY');
 ELSE
  IF rule.deletion_mode<>'PROJECTION_DELETE' THEN blockers:=array_append(blockers,'UNSUPPORTED_MODE'); END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('sinkId',q.sink_id,'checkpointDigest',q.checkpoint_digest,
   'receiptDigest',q.receipt_digest,'acknowledgedAtMicros',q.ack_micros::text) ORDER BY q.ack_micros,q.sink_id),'[]'::jsonb),max(q.ack_micros)
   INTO receipts,quorum_micros FROM (
    SELECT e.sink_id,e.checkpoint_digest,e.receipt_digest,floor(extract(epoch from e.acknowledged_at)*1000000) ack_micros
    FROM control.evidence_checkpoint e WHERE e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id AND e.stream_id=c.stream_id
     AND e.segment_id=c.segment_id AND e.object_digest=s.object_digest AND e.through_sequence=s.through_sequence
     AND e.receipt->>'receiptDigest'=e.receipt_digest AND e.receipt->'object'->>'objectDigest'=s.object_digest
    ORDER BY e.acknowledged_at,e.sink_id LIMIT rule.sink_quorum) q;
  IF jsonb_array_length(receipts)<>rule.sink_quorum THEN blockers:=array_append(blockers,'SINK_QUORUM'); END IF;
  eligible_micros:=greatest(floor(extract(epoch from c.occurred_at)*1000000)+rule.retention_period_ms*1000,
   coalesce(quorum_micros,floor(extract(epoch from s.admitted_at)*1000000))+rule.local_grace_ms*1000);
  IF closure IS NOT NULL THEN
   SELECT coalesce(jsonb_agg(jsonb_build_object('sinkId',q.sink_id,'checkpointDigest',q.checkpoint_digest,
    'receiptDigest',q.receipt_digest,'acknowledgedAtMicros',q.ack_micros::text) ORDER BY q.ack_micros,q.sink_id),'[]'::jsonb),max(q.ack_micros)
    INTO terminal_receipts,terminal_quorum FROM (
     SELECT e.sink_id,e.checkpoint_digest,e.receipt_digest,floor(extract(epoch from e.acknowledged_at)*1000000) ack_micros
     FROM control.evidence_checkpoint e WHERE e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id AND e.stream_id=c.stream_id
      AND e.segment_id=terminal.segment_id AND e.object_digest=terminal_segment.object_digest AND e.through_sequence=terminal_segment.through_sequence
      AND e.receipt->>'receiptDigest'=e.receipt_digest AND e.receipt->'object'->>'objectDigest'=terminal_segment.object_digest
     ORDER BY e.acknowledged_at,e.sink_id LIMIT rule.sink_quorum) q;
   IF jsonb_array_length(terminal_receipts)<>rule.sink_quorum THEN blockers:=array_append(blockers,'SINK_QUORUM'); END IF;
   eligible_micros:=greatest(eligible_micros,floor(extract(epoch from terminal.occurred_at)*1000000)+rule.retention_period_ms*1000,
    coalesce(terminal_quorum,floor(extract(epoch from terminal_segment.admitted_at)*1000000))+rule.local_grace_ms*1000);
   closure:=closure||jsonb_build_object('archive',jsonb_build_object('segmentId',terminal.segment_id::text,
    'objectDigest',terminal_segment.object_digest,'sinkReceipts',terminal_receipts));
  END IF;
  IF eligible_micros>floor(extract(epoch from clock_timestamp())*1000000) THEN blockers:=array_append(blockers,'RETENTION_NOT_ELAPSED'); END IF;
  IF p IS NOT NULL THEN
   projection_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex');
   projection_bytes:=octet_length(convert_to(openpc.signing_canonical_json(p),'UTF8'));
   selection:=jsonb_build_object('version','OPENPC_PROJECTION_DELETION_BATCH_V1','participantId','urn:openpc:participant:'||c.participant_id::text,
    'privacyDomainId',c.privacy_domain_id::text,'retentionPolicyId','urn:openpc:resource:'||rule.retention_policy_id::text,'policyDigest',rule.policy_digest,
    'targetDatabase','openpc_control','dataClass',data_class,'deletionMode','PROJECTION_DELETE','sourceKind',source_kind,
    'streamId',c.stream_id,'segmentId',c.segment_id::text,'sequence',c.sequence::text,'evidenceId','urn:openpc:resource:'||c.evidence_id::text,
    'recordId',c.record_id,'projectionDigest',projection_digest,'projectionBytes',projection_bytes,'sourceReceiptDigest',c.receipt_digest,
    'archiveObjectDigest',s.object_digest,'eligibleAfterMicros',eligible_micros::text,'sinkReceipts',receipts);
   IF closure IS NOT NULL THEN selection:=selection||jsonb_build_object('rpcClosure',closure); END IF;
   before_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
    'domain','pc.evidence.projection-before.v1','participantId',c.participant_id::text,'privacyDomainId',c.privacy_domain_id::text,
    'dataClass',data_class,'evidenceId',c.evidence_id::text,'projectionDigest',projection_digest,'projectionBytes',projection_bytes,
    'sourceReceiptDigest',c.receipt_digest)),'UTF8')),'hex');
  END IF;
 END IF;
 -- Unsupported producers have no executable selection. In particular, their
 -- record must never be replaced by a later supported keyset member.
 IF blockers && ARRAY['UNSUPPORTED_SOURCE','UNRESOLVED_TRANSITION','UNRESOLVED_OPERATION','WRITE_AMBIGUITY','REORG_FENCED'] THEN selection:=NULL; before_digest:=NULL; END IF;
 -- The selected transition and its terminal witness may share a segment.
 -- Report each failed obligation once even when both anchors fail it.
 blockers:=ARRAY(SELECT DISTINCT b FROM unnest(blockers) b ORDER BY b);
 RETURN jsonb_build_object('evidenceId','urn:openpc:resource:'||record::text,'dataClass',data_class,
  'projectionState',CASE WHEN p IS NULL THEN 'UNAVAILABLE' ELSE 'RETAINED' END,'eligible',cardinality(blockers)=0,
  'blockers',to_jsonb(blockers),'selection',selection,'beforeDigest',before_digest);
END $$;

CREATE OR REPLACE FUNCTION openpc.projection_deletion_target(plan jsonb)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('evidenceId',plan->'selection'->'evidenceId','recordId',plan->'selection'->'recordId',
  'projectionDigest',plan->'selection'->'projectionDigest','projectionBytes',plan->'selection'->'projectionBytes',
  'sourceReceiptDigest',plan->'selection'->'sourceReceiptDigest','beforeDigest',plan->'beforeDigest')
$$;

CREATE OR REPLACE FUNCTION openpc.projection_deletion_batch_plan(record uuid,previous uuid,data_class text)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE plan jsonb; selected jsonb; targets jsonb:='[]'::jsonb; target jsonb; candidate record;
 prior control.deletion_job; receipt_digest text; next_job uuid; position integer:=0;
 cursor jsonb:='null'::jsonb; prior_policy jsonb; blockers jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF (record IS NULL)=(previous IS NULL) OR data_class NOT IN ('NORMALIZED_JSON_PROJECTION','SEARCH_PROJECTION') THEN RAISE EXCEPTION 'PC-DATA-6004'; END IF;
 IF previous IS NOT NULL THEN
  SELECT * INTO prior FROM control.deletion_job j WHERE j.participant_id=current_setting('openpc.participant_id')::uuid
   AND j.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid AND j.deletion_job_id=previous;
  IF NOT FOUND OR prior.state<>'SUCCEEDED' OR prior.selection->>'version'<>'OPENPC_PROJECTION_DELETION_BATCH_V1'
   OR prior.target_data_class<>data_class THEN RETURN NULL; END IF;
  SELECT 'sha256:'||encode(a.receipt_digest,'hex') INTO receipt_digest FROM control.audit_occurrence a
   WHERE a.participant_id=prior.participant_id AND a.privacy_domain_id=prior.privacy_domain_id AND a.operation_id=prior.operation_id
    AND a.aggregate_type='evidence-deletion' AND a.aggregate_id=prior.deletion_job_id AND a.profile_id='pc.control.evidence-deletion.projection'
    AND a.catalog_operation_id='CFG-OP-DELETE-PROJECTION-BATCH';
  IF receipt_digest IS NULL THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  targets:=prior.selection->'targets'; position:=(prior.selection->>'batchIndex')::integer+1;
  cursor:=jsonb_build_object('deletionJobId','urn:openpc:resource:'||previous::text,'receiptDigest',receipt_digest);
  SELECT deletion_job_id INTO next_job FROM control.deletion_job j WHERE j.participant_id=prior.participant_id
   AND j.privacy_domain_id=prior.privacy_domain_id AND j.previous_deletion_job_id=previous AND j.state='SUCCEEDED';
  IF next_job IS NOT NULL OR position=jsonb_array_length(targets) THEN
   RETURN jsonb_build_object('evidenceId',prior.selection->'evidenceId','dataClass',data_class,'projectionState','RETIRED',
    'eligible',false,'blockers','[]'::jsonb,'selection',null,'beforeDigest',null,
    'continuationState',CASE WHEN next_job IS NULL THEN 'COMPLETE' ELSE 'ADVANCED' END,
    'nextDeletionJobId',CASE WHEN next_job IS NULL THEN NULL ELSE 'urn:openpc:resource:'||next_job::text END);
  END IF;
  target:=targets->position; prior_policy:=jsonb_build_array(prior.selection->'retentionPolicyId',prior.selection->'policyDigest');
  plan:=openpc.projection_deletion_object_plan(right(target->>'evidenceId',36)::uuid,data_class);
 ELSE
  plan:=openpc.projection_deletion_object_plan(record,data_class);
  IF plan IS NULL THEN RETURN NULL; END IF;
  IF plan->'selection'='null'::jsonb THEN RETURN plan||jsonb_build_object('continuationState','BLOCKED','nextDeletionJobId',null); END IF;
  -- Indexed primary-key keyset within the exact stream and producer. A blocked
  -- member remains in the selection; the next batch must clear its own gates.
  FOR candidate IN SELECT c.evidence_id FROM control.evidence_catalogue c
   WHERE c.participant_id=current_setting('openpc.participant_id')::uuid AND c.privacy_domain_id=current_setting('openpc.privacy_domain_id')::uuid
    AND c.stream_id=plan->'selection'->>'streamId' AND c.record_id>=plan->'selection'->>'recordId'
    AND ((data_class='SEARCH_PROJECTION' AND plan->'selection'->>'sourceKind'='AUTHENTICATION_CATALOGUE'
      AND c.source_format='OPENPC_AUTHENTICATION_OCCURRENCE_V1' AND c.evidence_class='AUTHENTICATION')
     OR (data_class='SEARCH_PROJECTION' AND plan->'selection'->>'sourceKind'='RETENTION_POLICY_CATALOGUE'
      AND c.evidence_class='BUSINESS_TRANSITION' AND EXISTS(SELECT 1 FROM control.evidence_record e
       JOIN control.audit_occurrence a ON a.participant_id=e.participant_id AND a.privacy_domain_id=e.privacy_domain_id AND a.receipt_id=e.receipt_id
       WHERE e.participant_id=c.participant_id AND e.privacy_domain_id=c.privacy_domain_id AND e.evidence_record_id::text=c.record_id
        AND a.aggregate_type='retention-policy' AND a.profile_id IN ('pc.control.retention-policy.activate','pc.control.retention-policy.retire')))
     OR (data_class='SEARCH_PROJECTION' AND plan->'selection'->>'sourceKind'='RPC_RETIRED_CATALOGUE'
      AND c.evidence_class='EFFECT' AND c.source_format='OPENPC_RPC_DECISION_TRANSITION_V1'
      AND openpc.rpc_retired_catalogue_proof(c) IS NOT NULL)
     OR (data_class='NORMALIZED_JSON_PROJECTION' AND plan->'selection'->>'sourceKind'='DEPLOYMENT_PROVENANCE'
      AND c.source_format='PC-DEPLOYMENT-JOURNAL-PROJECTION-1' AND EXISTS(SELECT 1 FROM control.evidence_deployment_provenance d
       WHERE d.participant_id=c.participant_id AND d.privacy_domain_id=c.privacy_domain_id AND d.stream_id=c.stream_id AND d.record_id=c.record_id
        AND cardinality(openpc.deployment_projection_retirement_blockers(c,d.projection))=0))
     OR (data_class='NORMALIZED_JSON_PROJECTION' AND plan->'selection'->>'sourceKind'='FACT_PROVENANCE'
      AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND EXISTS(SELECT 1 FROM control.evidence_fact_provenance f
       WHERE f.participant_id=c.participant_id AND f.privacy_domain_id=c.privacy_domain_id AND f.stream_id=c.stream_id AND f.record_id=c.record_id))
     OR (data_class='NORMALIZED_JSON_PROJECTION' AND plan->'selection'->>'sourceKind' IN ('RPC_PRE_ADMISSION_DENIAL','RPC_CLOSED_TRANSITION')
      AND EXISTS(SELECT 1 FROM control.evidence_rpc_provenance r
      WHERE r.participant_id=c.participant_id AND r.privacy_domain_id=c.privacy_domain_id AND r.stream_id=c.stream_id AND r.record_id=c.record_id
       AND CASE WHEN plan->'selection'->>'sourceKind'='RPC_PRE_ADMISSION_DENIAL'
        THEN r.projection->'transition'->>'phase'='PRE_ADMISSION_DENIAL'
        ELSE r.projection->'transition'->>'phase'<>'PRE_ADMISSION_DENIAL'
         AND openpc.rpc_projection_retirement_witness(c,r.projection) IS NOT NULL END)))
   ORDER BY c.record_id LIMIT 16 LOOP
   selected:=openpc.projection_deletion_object_plan(candidate.evidence_id,data_class);
   IF selected->'selection'='null'::jsonb THEN RETURN selected||jsonb_build_object('continuationState','BLOCKED','nextDeletionJobId',null); END IF;
   targets:=targets||jsonb_build_array(openpc.projection_deletion_target(selected));
  END LOOP;
  target:=targets->0;
 END IF;
 IF plan IS NULL OR target IS NULL THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 blockers:=plan->'blockers';
 IF plan->'selection'='null'::jsonb THEN RETURN plan||jsonb_build_object('continuationState','BLOCKED','nextDeletionJobId',null); END IF;
 IF openpc.projection_deletion_target(plan) IS DISTINCT FROM target OR
  (prior_policy IS NOT NULL AND prior_policy IS DISTINCT FROM jsonb_build_array(plan->'selection'->'retentionPolicyId',plan->'selection'->'policyDigest'))
 THEN blockers:=blockers||jsonb_build_array('STALE_SELECTION'); END IF;
 RETURN plan||jsonb_build_object('selection',plan->'selection'||jsonb_build_object('priorCursor',cursor,'targets',targets,'batchIndex',position),
  'blockers',blockers,'eligible',jsonb_array_length(blockers)=0,'continuationState',CASE WHEN jsonb_array_length(blockers)=0 THEN 'READY' ELSE 'BLOCKED' END,'nextDeletionJobId',null);
END $$;
REVOKE ALL ON FUNCTION openpc.evidence_catalogue_projection(control.evidence_catalogue),openpc.projection_deletion_object_plan(uuid,text),
 openpc.projection_deletion_target(jsonb),openpc.projection_deletion_batch_plan(uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.evidence_catalogue_projection(control.evidence_catalogue),openpc.projection_deletion_object_plan(uuid,text),
 openpc.projection_deletion_target(jsonb),openpc.projection_deletion_batch_plan(uuid,uuid,text) TO openpc_control_runtime,openpc_control_reader;

-- Apply after the source owners reset their grants. Their immutable-row guards
-- remain the only admission path for the narrowly governed physical deletion.
GRANT DELETE ON control.evidence_catalogue,control.evidence_rpc_provenance,control.evidence_fact_provenance,control.evidence_deployment_provenance TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.projection_preservation_metadata(c control.evidence_catalogue)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT CASE WHEN (c).source_format='OPENPC_CANONICAL_FACT_V1' THEN
  (SELECT jsonb_build_object('factLineage',p.projection->'lineage') FROM control.evidence_fact_provenance p
   WHERE p.participant_id=(c).participant_id AND p.privacy_domain_id=(c).privacy_domain_id AND p.stream_id=(c).stream_id AND p.record_id=(c).record_id)
 ELSE openpc.evidence_hold_record_metadata(c) END
$$;
REVOKE ALL ON FUNCTION openpc.projection_preservation_metadata(control.evidence_catalogue) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.projection_preservation_metadata(control.evidence_catalogue) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.projection_deletion_after_digest(r control.evidence_projection_retirement)
RETURNS text LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
  'domain','pc.evidence.projection-after.v1','projectionState','RETIRED','retirementDigest',openpc.projection_retirement_digest(r))),'UTF8')),'hex')
$$;
CREATE OR REPLACE FUNCTION openpc.projection_deletion_effect_matches(j control.deletion_job,r control.evidence_projection_retirement)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT (j).target_data_class=(r).data_class AND (j).selection->>'projectionDigest'=(r).projection_digest
  AND (j).selection->>'recordId'=(r).record_id AND (j).selection->>'evidenceId'='urn:openpc:resource:'||(r).evidence_id::text
  AND (j).deleted_bytes=(r).projection_bytes AND (j).before_used_bytes=(r).projection_bytes AND (j).after_used_bytes=0
  AND (r).retirement_digest=openpc.projection_retirement_digest(r) AND (j).after_digest=openpc.projection_deletion_after_digest(r)
  AND CASE (r).data_class WHEN 'SEARCH_PROJECTION' THEN NOT EXISTS(SELECT 1 FROM control.evidence_catalogue c
   WHERE c.participant_id=(r).participant_id AND c.privacy_domain_id=(r).privacy_domain_id AND c.stream_id=(r).stream_id AND c.record_id=(r).record_id)
  WHEN 'NORMALIZED_JSON_PROJECTION' THEN CASE (j).selection->>'sourceKind'
   WHEN 'DEPLOYMENT_PROVENANCE' THEN NOT EXISTS(SELECT 1 FROM control.evidence_deployment_provenance p
    WHERE p.participant_id=(r).participant_id AND p.privacy_domain_id=(r).privacy_domain_id AND p.stream_id=(r).stream_id AND p.record_id=(r).record_id)
   WHEN 'FACT_PROVENANCE' THEN NOT EXISTS(SELECT 1 FROM control.evidence_fact_provenance p
    WHERE p.participant_id=(r).participant_id AND p.privacy_domain_id=(r).privacy_domain_id AND p.stream_id=(r).stream_id AND p.record_id=(r).record_id)
   WHEN 'RPC_PRE_ADMISSION_DENIAL' THEN NOT EXISTS(SELECT 1 FROM control.evidence_rpc_provenance p
    WHERE p.participant_id=(r).participant_id AND p.privacy_domain_id=(r).privacy_domain_id AND p.stream_id=(r).stream_id AND p.record_id=(r).record_id)
   WHEN 'RPC_CLOSED_TRANSITION' THEN NOT EXISTS(SELECT 1 FROM control.evidence_rpc_provenance p
    WHERE p.participant_id=(r).participant_id AND p.privacy_domain_id=(r).privacy_domain_id AND p.stream_id=(r).stream_id AND p.record_id=(r).record_id)
   ELSE false END
  ELSE false END
$$;

CREATE OR REPLACE FUNCTION openpc.guard_projection_deletion_job(operation text,old_job control.deletion_job,new_job control.deletion_job)
RETURNS control.deletion_job LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE plan jsonb; item control.evidence_projection_retirement;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF operation NOT IN ('INSERT','UPDATE') OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_DELETIONS_CREATE_PROJECTION_BATCH-V1'
  OR new_job.participant_id<>current_setting('openpc.participant_id')::uuid OR new_job.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR new_job.operation_id<>current_setting('openpc.operation_id')::uuid
  OR new_job.target_data_class NOT IN ('NORMALIZED_JSON_PROJECTION','SEARCH_PROJECTION') OR new_job.target_database<>'openpc_control'
  OR new_job.selection->>'version'<>'OPENPC_PROJECTION_DELETION_BATCH_V1' OR new_job.selection->>'dataClass'<>new_job.target_data_class
  OR new_job.stream_id IS DISTINCT FROM new_job.selection->>'streamId' OR new_job.segment_id IS DISTINCT FROM (new_job.selection->>'segmentId')::uuid
  OR new_job.protected_object_id IS NOT NULL THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||new_job.participant_id::text,0));
 IF operation='INSERT' THEN
  new_job.previous_deletion_job_id:=right(new_job.selection->'priorCursor'->>'deletionJobId',36)::uuid;
  IF new_job.previous_deletion_job_id IS NOT NULL THEN
   PERFORM 1 FROM control.deletion_job WHERE participant_id=new_job.participant_id AND privacy_domain_id=new_job.privacy_domain_id
    AND deletion_job_id=new_job.previous_deletion_job_id FOR UPDATE;
  END IF;
  plan:=openpc.evidence_deletion_selection_plan(new_job.selection);
  IF plan IS NULL OR NOT (plan->>'eligible')::boolean OR plan->'selection' IS DISTINCT FROM new_job.selection
   OR plan->>'beforeDigest' IS DISTINCT FROM new_job.before_digest OR new_job.state<>'EXECUTING' OR new_job.revision<>0
   OR new_job.retention_policy_id IS DISTINCT FROM right(new_job.selection->>'retentionPolicyId',36)::uuid THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  new_job.target_selector_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
   'domain','pc.evidence.projection-selector.v1','participantId',new_job.participant_id::text,'privacyDomainId',new_job.privacy_domain_id::text,
   'dataClass',new_job.target_data_class,'streamId',new_job.stream_id,'recordId',new_job.selection->>'recordId')),'UTF8')),'hex');
  new_job.eligibility_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(new_job.selection),'UTF8')),'hex');
  new_job.before_used_bytes:=(new_job.selection->>'projectionBytes')::integer; new_job.after_used_bytes:=NULL;
  new_job.started_at:=clock_timestamp();new_job.created_at:=new_job.started_at;
 ELSE
  IF old_job.state<>'EXECUTING' OR new_job.state<>'SUCCEEDED' OR old_job.revision<>0 OR new_job.revision<>1
   OR (to_jsonb(new_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at']) IS DISTINCT FROM
    (to_jsonb(old_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at'])
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO STRICT item FROM control.evidence_projection_retirement WHERE participant_id=new_job.participant_id
   AND privacy_domain_id=new_job.privacy_domain_id AND deletion_job_id=new_job.deletion_job_id;
  new_job.deleted_count:=1;new_job.deleted_bytes:=item.projection_bytes;new_job.after_used_bytes:=0;
  new_job.after_digest:=openpc.projection_deletion_after_digest(item);
  IF NOT coalesce(openpc.projection_deletion_effect_matches(new_job,item),false) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  new_job.completed_at:=clock_timestamp();
 END IF;
 new_job.updated_at:=clock_timestamp();RETURN new_job;
END $$;

CREATE OR REPLACE FUNCTION openpc.guard_projection_retirement()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE c control.evidence_catalogue; job control.deletion_job; plan jsonb; metadata jsonb;
BEGIN
 IF TG_OP<>'INSERT' OR pg_trigger_depth()<>2 THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_DELETIONS_CREATE_PROJECTION_BATCH-V1'
  OR NEW.participant_id<>current_setting('openpc.participant_id')::uuid OR NEW.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT c FROM control.evidence_catalogue WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
  AND stream_id=NEW.stream_id AND record_id=NEW.record_id;
 SELECT * INTO STRICT job FROM control.deletion_job WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
  AND deletion_job_id=NEW.deletion_job_id AND operation_id=current_setting('openpc.operation_id')::uuid AND state='EXECUTING';
 plan:=openpc.evidence_deletion_selection_plan(job.selection); metadata:=openpc.projection_preservation_metadata(c);
 IF plan IS NULL OR NOT (plan->>'eligible')::boolean OR plan->'selection' IS DISTINCT FROM job.selection
  OR metadata IS NULL OR NEW.preservation_metadata IS DISTINCT FROM metadata OR NEW.evidence_id<>c.evidence_id OR NEW.segment_id<>c.segment_id
  OR NEW.sequence<>c.sequence OR NEW.source_receipt_digest<>c.receipt_digest OR NEW.data_class<>job.target_data_class
  OR NEW.projection_digest<>job.selection->>'projectionDigest' OR NEW.projection_bytes<>(job.selection->>'projectionBytes')::integer
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 NEW.retirement_digest:=openpc.projection_retirement_digest(NEW);RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS evidence_projection_retirement_guard ON control.evidence_projection_retirement;
CREATE TRIGGER evidence_projection_retirement_guard BEFORE INSERT OR UPDATE OR DELETE ON control.evidence_projection_retirement
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_projection_retirement();

CREATE OR REPLACE FUNCTION openpc.record_projection_deletion(c control.evidence_catalogue,data_class text,projection jsonb)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE job control.deletion_job; plan jsonb; bytes integer; digest text;
BEGIN
 IF pg_trigger_depth()<>1 OR current_setting('openpc.action_intent_id')<>'ACT-EVIDENCE_DELETIONS_CREATE_PROJECTION_BATCH-V1'
  OR c.participant_id<>current_setting('openpc.participant_id')::uuid OR c.privacy_domain_id<>current_setting('openpc.privacy_domain_id')::uuid
  OR data_class NOT IN ('NORMALIZED_JSON_PROJECTION','SEARCH_PROJECTION') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||c.participant_id::text,0));
 SELECT * INTO STRICT job FROM control.deletion_job WHERE participant_id=c.participant_id AND privacy_domain_id=c.privacy_domain_id
  AND operation_id=current_setting('openpc.operation_id')::uuid AND state='EXECUTING' AND revision=0
  AND target_data_class=data_class AND selection->>'evidenceId'='urn:openpc:resource:'||c.evidence_id::text FOR UPDATE;
 plan:=openpc.evidence_deletion_selection_plan(job.selection);
 bytes:=octet_length(convert_to(openpc.signing_canonical_json(projection),'UTF8'));
 digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(projection),'UTF8')),'hex');
 IF plan IS NULL OR NOT (plan->>'eligible')::boolean OR plan->'selection' IS DISTINCT FROM job.selection
  OR plan->>'beforeDigest' IS DISTINCT FROM job.before_digest OR bytes<>(job.selection->>'projectionBytes')::integer
  OR digest<>job.selection->>'projectionDigest' THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 INSERT INTO control.evidence_projection_retirement(deletion_job_id,participant_id,privacy_domain_id,data_class,evidence_id,
  stream_id,segment_id,record_id,sequence,source_receipt_digest,projection_digest,projection_bytes,preservation_metadata,retirement_digest)
 VALUES(job.deletion_job_id,c.participant_id,c.privacy_domain_id,data_class,c.evidence_id,c.stream_id,c.segment_id,c.record_id,c.sequence,
  c.receipt_digest,digest,bytes,openpc.projection_preservation_metadata(c),'');
END $$;
REVOKE ALL ON FUNCTION openpc.projection_retirement_digest(control.evidence_projection_retirement),
 openpc.projection_deletion_after_digest(control.evidence_projection_retirement),
 openpc.projection_deletion_effect_matches(control.deletion_job,control.evidence_projection_retirement),
 openpc.guard_projection_deletion_job(text,control.deletion_job,control.deletion_job),
 openpc.record_projection_deletion(control.evidence_catalogue,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.projection_retirement_digest(control.evidence_projection_retirement),
 openpc.projection_deletion_after_digest(control.evidence_projection_retirement),
 openpc.projection_deletion_effect_matches(control.deletion_job,control.evidence_projection_retirement),
 openpc.guard_projection_deletion_job(text,control.deletion_job,control.deletion_job),
 openpc.record_projection_deletion(control.evidence_catalogue,text,jsonb) TO openpc_control_runtime;
GRANT EXECUTE ON FUNCTION openpc.projection_retirement_digest(control.evidence_projection_retirement) TO openpc_control_worker,openpc_control_reader;


