CREATE OR REPLACE FUNCTION openpc.lock_store_retirement_workload(host text)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $$
DECLARE t control.store_retirement_host; now_ms numeric:=floor(extract(epoch from clock_timestamp())*1000);
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(session_user,'openpc_control_worker','USAGE')
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_RECONCILE_STORE_BATCH-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT t FROM control.store_retirement_host WHERE host_digest=host
  AND participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id();
 IF session_user<>t.database_role OR now_ms<t.valid_from_ms OR now_ms>=t.valid_until_ms THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.participant p WHERE p.participant_id=t.participant_id AND p.state='ACTIVE' AND p.archived_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.privacy_domain p WHERE p.participant_id=t.participant_id AND p.privacy_domain_id=t.privacy_domain_id AND p.state='ACTIVE' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM 1 FROM control.credential c JOIN control.principal w USING(participant_id,principal_id)
  WHERE c.participant_id=t.participant_id AND c.credential_id=t.workload_credential_id
   AND c.credential_epoch=t.workload_credential_epoch AND c.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC')
   AND c.state='ACTIVE' AND w.kind='WORKLOAD' AND w.state='ACTIVE'
   AND c.valid_from<=clock_timestamp() AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
   AND c.public_key_digest IS DISTINCT FROM sha256(t.control_spki) AND c.public_key_digest IS DISTINCT FROM sha256(t.target_spki)
  FOR SHARE OF c,w;
 IF NOT FOUND THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
END $$;
ALTER FUNCTION openpc.lock_store_retirement_workload(text) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.lock_store_retirement_workload(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.lock_store_retirement_workload(text) TO openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.verify_store_retirement_commit(p uuid,d uuid,host text,
 domain text,binding bytea,nonce bytea,mac bytea)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE secret bytea; expected bytea; different integer:=0;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF p IS DISTINCT FROM current_setting('openpc.participant_id')::uuid
  OR d IS DISTINCT FROM current_setting('openpc.privacy_domain_id')::uuid
  OR domain NOT IN ('SOURCE','DELIVERY','OUTCOME') OR domain IS NULL
  OR octet_length(nonce) IS DISTINCT FROM 32 OR octet_length(mac) IS DISTINCT FROM 32
  OR octet_length(binding) IS DISTINCT FROM 32 OR host!~'^[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF domain='SOURCE' THEN
  IF NOT pg_has_role(session_user,'openpc_control_runtime','USAGE')
   OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_ADMIT_STORE_BATCH-V1' THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 ELSE PERFORM openpc.lock_store_retirement_workload(host); END IF;
 SELECT verifier_secret INTO STRICT secret FROM control.store_retirement_verifier_key
  WHERE participant_id=p AND privacy_domain_id=d AND host_digest=host;
 expected:=public.hmac(convert_to('OPENPC_STORE_RETIREMENT_'||domain||'_COMMIT_V1','UTF8')
  ||uuid_send(p)||uuid_send(d)||decode(host,'hex')||binding||nonce,secret,'sha256');
 FOR n IN 0..31 LOOP different:=different | (get_byte(expected,n) # get_byte(mac,n)); END LOOP;
 IF different<>0 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
END $$;
ALTER FUNCTION openpc.verify_store_retirement_commit(uuid,uuid,text,text,bytea,bytea,bytea) OWNER TO openpc_control_owner;
REVOKE ALL ON FUNCTION openpc.verify_store_retirement_commit(uuid,uuid,text,text,bytea,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.verify_store_retirement_commit(uuid,uuid,text,text,bytea,bytea,bytea) TO openpc_control_runtime,openpc_control_worker;

-- Both existing mutable owners take the same participant lifecycle fence. Their
-- immutable versions/revisions form a monotonic scoped generation; deleted or
-- caller-supplied epoch rows cannot reset it. Root Participant holds remain visible.
CREATE OR REPLACE FUNCTION openpc.store_retirement_lifecycle_revision(p uuid,d uuid)
RETURNS numeric LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT 1+coalesce((SELECT sum(revision) FROM control.retention_hold
  WHERE participant_id=p AND (selector_type='PARTICIPANT' OR privacy_domain_id=d)),0)
  +coalesce((SELECT sum(revision) FROM control.retention_policy WHERE participant_id=p AND privacy_domain_id=d),0)
$$;
REVOKE ALL ON FUNCTION openpc.store_retirement_lifecycle_revision(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.store_retirement_lifecycle_revision(uuid,uuid) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.store_retirement_state_projection(a control.store_retirement_admission)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('0',openpc.business_bytes(decode((a).host_digest,'hex')),
  '1',openpc.business_bytes(decode((a).attempt_digest,'hex')),
  '2',openpc.business_bytes(decode((a).selection_digest,'hex')),
  '3',openpc.business_bytes(decode(substring((a).source_binding_digest from 8),'hex')),
  '4',openpc.business_uuid((a).retention_policy_id),'5',openpc.business_uuid((a).approval_request_id),
  '6',openpc.business_uuid((a).operation_id),'7',openpc.business_uuid((a).retirement_id),
  '8',CASE WHEN (a).previous_attempt_id IS NULL THEN openpc.business_bytes(''::bytea) ELSE openpc.business_uuid((a).previous_attempt_id) END,
  '9',(a).lifecycle_revision,'10',floor(extract(epoch from (a).admitted_at)*1000000)*1000,
  '11',(a).dispatch_not_after_ms)
$$;
REVOKE ALL ON FUNCTION openpc.store_retirement_state_projection(control.store_retirement_admission) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.store_retirement_state_projection(control.store_retirement_admission) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.assert_store_retirement_receipt(receipt control.audit_occurrence)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF receipt.profile_id<>'pc.control.store-retirement.admit' OR receipt.catalog_operation_id<>'CFG-OP-ADMIT-STORE-RETIREMENT'
  OR receipt.before_existence<>0 OR receipt.before_revision<>0 OR receipt.after_existence<>1 OR receipt.after_revision<>1
  OR openpc.business_cbor(receipt.before_state_preimage)->8 IS DISTINCT FROM '{}'::jsonb
  OR NOT EXISTS(SELECT 1 FROM control.store_retirement_admission a WHERE a.participant_id=receipt.participant_id
    AND a.privacy_domain_id=receipt.privacy_domain_id AND a.attempt_id=receipt.aggregate_id AND a.operation_id=receipt.operation_id
    AND openpc.business_cbor(receipt.after_state_preimage)->8=openpc.store_retirement_state_projection(a))
 THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-ACTUAL-STORE-ADMISSION'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.assert_store_retirement_receipt(control.audit_occurrence) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_store_retirement_receipt(control.audit_occurrence) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.require_store_retirement_command()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE matched integer;
BEGIN
 SELECT count(*) INTO matched FROM control.mutation_evidence e JOIN control.mutation_candidate c
  ON c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id
   AND c.resource_id=e.aggregate_id AND c.consumed_operation_id=e.operation_id AND c.candidate_digest=e.candidate_digest
  JOIN control.audit_occurrence receipt ON receipt.participant_id=e.participant_id AND receipt.privacy_domain_id=e.privacy_domain_id
   AND receipt.operation_id=e.operation_id AND receipt.aggregate_id=e.aggregate_id AND receipt.aggregate_type='store-retirement'
  JOIN control.idempotency_record i ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id
   AND i.operation_id=e.operation_id AND i.catalog_operation_id=e.catalog_operation_id AND i.input_digest=e.candidate_digest
 WHERE e.participant_id=NEW.participant_id AND e.privacy_domain_id=NEW.privacy_domain_id AND e.operation_id=NEW.operation_id
  AND e.approval_request_id=NEW.approval_request_id AND e.aggregate_type='store-retirement' AND e.aggregate_id=NEW.attempt_id
  AND e.catalog_operation_id='CFG-OP-ADMIT-STORE-RETIREMENT' AND e.action_intent_id='ACT-EVIDENCE_DELETIONS_ADMIT_STORE_BATCH-V1'
  AND c.catalog_operation_id=e.catalog_operation_id AND c.action_intent_id=e.action_intent_id AND c.state='CONSUMED' AND c.expected_revision=0
  AND c.candidate_document->'sourceBinding'=NEW.source_binding AND c.candidate_document->>'hostDigest'=NEW.host_digest
  AND c.candidate_document->>'retentionPolicyId'='urn:openpc:resource:'||NEW.retention_policy_id::text
  AND c.candidate_document->'previousAttemptId'=coalesce(to_jsonb('urn:openpc:resource:'||NEW.previous_attempt_id::text),'null'::jsonb)
  AND i.terminal_state='COMMITTED' AND i.expected_aggregate_version=0
  AND receipt.profile_id='pc.control.store-retirement.admit' AND receipt.catalog_operation_id=e.catalog_operation_id
  AND receipt.action_intent_id=e.action_intent_id AND receipt.before_existence=0 AND receipt.before_revision=0
  AND receipt.after_existence=1 AND receipt.after_revision=1
  AND openpc.business_cbor(receipt.before_state_preimage)->8='{}'::jsonb
  AND openpc.business_cbor(receipt.after_state_preimage)->8=openpc.store_retirement_state_projection(NEW)
  AND (SELECT count(*) FROM control.outbox_event event WHERE event.participant_id=receipt.participant_id
    AND event.privacy_domain_id=receipt.privacy_domain_id AND event.receipt_id=receipt.receipt_id
    AND event.aggregate_type=receipt.aggregate_type AND event.aggregate_id=receipt.aggregate_id
    AND event.event_type='io.openpc.control.command.committed.v1' AND event.proof_kind='BUSINESS_RECEIPT_REFERENCE'
    AND event.sequence_namespace='CONTROL_BUSINESS_TRANSITION_V1' AND event.payload_digest=sha256(event.payload_cbor))=1;
 IF matched<>1 THEN RAISE EXCEPTION 'PC-AUTH-0002-STORE-RETIREMENT-SIGNED-ADMISSION'; END IF;
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS store_retirement_command_required ON control.store_retirement_admission;
CREATE CONSTRAINT TRIGGER store_retirement_command_required AFTER INSERT ON control.store_retirement_admission
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_store_retirement_command();


CREATE OR REPLACE FUNCTION openpc.candidate_retirement_source_binding(policy_id uuid,selection_wire bytea,record_refs jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p uuid:=openpc.current_participant_id(); d uuid:=openpc.current_privacy_domain_id();
 rule control.retention_policy; selection jsonb; selected jsonb; ref jsonb; a control.evidence_candidate_archive;
 actual record; archived record; checkpoint record; identity jsonb; sinks jsonb; chosen text[];
 refs jsonb:='[]'; manifest jsonb:='[]'; acknowledgements jsonb:='[]';
 row_index integer:=0; eligible_ms numeric:=0; ack_ms numeric; latest numeric;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF octet_length(selection_wire) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 selection:=convert_from(selection_wire,'UTF8')::jsonb;
 IF selection->>'class' IS DISTINCT FROM 'CANDIDATE_PROJECTION'
  OR jsonb_typeof(selection->'rows') IS DISTINCT FROM 'array'
  OR jsonb_array_length(selection->'rows') NOT BETWEEN 1 AND 256
  OR jsonb_typeof(record_refs) IS DISTINCT FROM 'array'
  OR jsonb_array_length(record_refs)<>jsonb_array_length(selection->'rows') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT rule FROM control.retention_policy WHERE participant_id=p AND privacy_domain_id=d
  AND retention_policy_id=policy_id AND data_class='CANDIDATE_PROJECTION' AND deletion_mode='PROJECTION_DELETE' AND active_until IS NULL;
 FOR selected IN SELECT value FROM jsonb_array_elements(selection->'rows') LOOP
  ref:=record_refs->row_index;
  IF ref IS DISTINCT FROM jsonb_build_object('candidateId',selected->>'candidate_id','evidenceId',ref->>'evidenceId')
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT c.evidence_id,c.stream_id,c.record_id,c.sequence,c.receipt_digest,c.occurred_at,
   s.segment_id,s.object_digest,s.first_sequence,s.through_sequence,s.admitted_at INTO STRICT actual
   FROM control.evidence_catalogue c JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
   JOIN control.evidence_stream h USING(participant_id,privacy_domain_id,stream_id)
   WHERE c.participant_id=p AND c.privacy_domain_id=d AND c.evidence_id=(ref->>'evidenceId')::uuid
    AND c.source_format='OPENPC_CANDIDATE_PROJECTION_MANIFEST_V1' AND c.evidence_class='EFFECT'
    AND c.sequence BETWEEN s.first_sequence AND s.through_sequence AND h.last_sequence>=s.through_sequence;
  SELECT * INTO STRICT a FROM control.evidence_candidate_archive WHERE participant_id=p AND privacy_domain_id=d
   AND stream_id=actual.stream_id AND record_id=actual.record_id AND candidate_id=(selected->>'candidate_id')::uuid;
  identity:=a.manifest->'identity';
  IF actual.receipt_digest IS DISTINCT FROM a.manifest_digest
   OR a.manifest_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(a.manifest),'UTF8')),'hex')
   OR identity->>'participantId' IS DISTINCT FROM p::text OR identity->>'privacyDomainId' IS DISTINCT FROM d::text
   OR identity->>'candidateId' IS DISTINCT FROM selected->>'candidate_id'
   OR identity->>'sourceProfileId' IS DISTINCT FROM selection#>>'{source,profile_id}'
   OR identity->>'generationId' IS DISTINCT FROM selection#>>'{source,generation_id}'
   OR identity->>'partitionId' IS DISTINCT FROM selection#>>'{source,partition_id}'
   OR identity->>'publicationDigest' IS DISTINCT FROM 'sha256:'||(selection#>>'{source,identity_digest}')
   OR identity->>'candidateFeedSequence' IS DISTINCT FROM selected->>'candidate_feed_sequence'
   OR identity->>'payloadDigest' IS DISTINCT FROM 'sha256:'||(selected->>'payload_digest')
   OR identity->>'payloadBytes' IS DISTINCT FROM selected->>'payload_bytes'
   OR identity->>'checkpointDigest' IS DISTINCT FROM 'sha256:'||(selected->>'checkpoint_digest')
  THEN RAISE EXCEPTION 'PC-DATA-6007-SOURCE'; END IF;
  -- Zero remote quorum still requires a complete original archive checkpoint
  -- chain, just as the Fact owner requires its original checkpoint. No storage
  -- retention deadline is shortened by retiring the native projection.
  chosen:=ARRAY[]::text[]; sinks:='[]';
  FOR checkpoint IN SELECT c.* FROM control.evidence_checkpoint c WHERE c.participant_id=p AND c.privacy_domain_id=d
   AND c.stream_id=actual.stream_id AND c.segment_id=actual.segment_id AND c.object_digest=actual.object_digest
   AND c.through_sequence=actual.through_sequence ORDER BY c.acknowledged_at,c.sink_id LOOP
   IF openpc.candidate_archive_coverage(p,d,actual.stream_id,actual.record_id,ARRAY[checkpoint.sink_id])->>'state'='COMPLETE' THEN
    chosen:=array_append(chosen,checkpoint.sink_id);
    sinks:=sinks||jsonb_build_array(jsonb_build_object('sinkId',checkpoint.sink_id,'checkpointDigest',checkpoint.checkpoint_digest,
     'receiptDigest',checkpoint.receipt_digest,'acknowledgedAtMicros',floor(extract(epoch from checkpoint.acknowledged_at)*1000000)::text));
    EXIT WHEN cardinality(chosen)=greatest(1,rule.sink_quorum);
   END IF;
  END LOOP;
  IF cardinality(chosen)<>greatest(1,rule.sink_quorum) THEN RAISE EXCEPTION 'PC-DATA-6007-SINK-QUORUM'; END IF;
  FOR archived IN SELECT DISTINCT c.occurred_at,s.segment_id,s.object_digest,s.through_sequence,s.admitted_at
   FROM control.evidence_candidate_archive_part part JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
   JOIN control.evidence_segment s USING(participant_id,privacy_domain_id,stream_id,segment_id)
   WHERE part.participant_id=p AND part.privacy_domain_id=d AND part.stream_id=actual.stream_id AND part.manifest_record_id=actual.record_id LOOP
   IF EXISTS(SELECT 1 FROM control.retention_hold hold WHERE hold.participant_id=p
    AND (hold.selector_type='PARTICIPANT' OR hold.privacy_domain_id=d) AND hold.state='ACTIVE'
    AND openpc.evidence_hold_matches(hold.selector,p,d,actual.stream_id,archived.segment_id))
    THEN RAISE EXCEPTION 'PC-DATA-6007-ACTIVE-HOLD'; END IF;
   SELECT max(ceil(extract(epoch from c.acknowledged_at)*1000)) INTO ack_ms FROM control.evidence_checkpoint c
    WHERE c.participant_id=p AND c.privacy_domain_id=d AND c.stream_id=actual.stream_id
     AND c.segment_id=archived.segment_id AND c.object_digest=archived.object_digest AND c.through_sequence=archived.through_sequence
     AND c.sink_id=ANY(chosen);
   latest:=greatest(ceil(extract(epoch from archived.occurred_at)*1000)+rule.retention_period_ms,
    greatest(ack_ms,ceil(extract(epoch from archived.admitted_at)*1000))+rule.local_grace_ms);
   eligible_ms:=greatest(eligible_ms,latest);
  END LOOP;
  refs:=refs||jsonb_build_array(ref);
  manifest:=manifest||jsonb_build_array(jsonb_build_object('candidateId',selected->>'candidate_id',
   'evidenceId',actual.evidence_id::text,'streamId',actual.stream_id,'recordId',actual.record_id,
   'sequence',actual.sequence::text,'recordDigest',actual.receipt_digest,'segmentId',actual.segment_id::text,'objectDigest',actual.object_digest));
  acknowledgements:=acknowledgements||jsonb_build_array(jsonb_build_object('candidateId',selected->>'candidate_id','sinkReceipts',sinks));
  row_index:=row_index+1;
 END LOOP;
 IF eligible_ms>floor(extract(epoch from clock_timestamp())*1000) OR eligible_ms>9223372036854775807
  THEN RAISE EXCEPTION 'PC-DATA-6007-RETENTION'; END IF;
 RETURN jsonb_build_object('version','OPENPC_STORE_RETIREMENT_SOURCE_V1','selectionWireHex',encode(selection_wire,'hex'),
  'recordRefs',refs,'manifest',manifest,'acknowledgements',acknowledgements,
  'archiveManifestDigest',encode(sha256(convert_to(openpc.signing_canonical_json(manifest),'UTF8')),'hex'),
  'archiveAcknowledgementDigest',encode(sha256(convert_to(openpc.signing_canonical_json(acknowledgements),'UTF8')),'hex'),
  'retentionNotBeforeMs',eligible_ms::text,'lifecycleRevision',openpc.store_retirement_lifecycle_revision(p,d)::text);
END $$;
REVOKE ALL ON FUNCTION openpc.candidate_retirement_source_binding(uuid,bytea,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.candidate_retirement_source_binding(uuid,bytea,jsonb) TO openpc_control_runtime,openpc_control_worker;

CREATE OR REPLACE FUNCTION openpc.store_retirement_source_binding(policy_id uuid,selection_wire bytea,record_refs jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p uuid:=openpc.current_participant_id(); d uuid:=openpc.current_privacy_domain_id();
 rule control.retention_policy; selection jsonb; refs jsonb:='[]'::jsonb; manifest jsonb:='[]'::jsonb;
 acknowledgements jsonb:='[]'::jsonb; selected jsonb; ref jsonb; actual record; sinks jsonb;
 ack_ms numeric; eligible_ms numeric:=0; row_index integer:=0; latest numeric;
BEGIN
 PERFORM openpc.assert_request_context(false);
 IF octet_length(selection_wire) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 selection:=convert_from(selection_wire,'UTF8')::jsonb;
 IF selection->>'class'='CANDIDATE_PROJECTION' THEN
  RETURN openpc.candidate_retirement_source_binding(policy_id,selection_wire,record_refs);
 END IF;
 IF selection->>'class' IS DISTINCT FROM 'ADMITTED_FACT' THEN RAISE EXCEPTION 'PC-DATA-6007-UNSUPPORTED-SOURCE'; END IF;
 IF jsonb_typeof(selection->'rows') IS DISTINCT FROM 'array'
  OR jsonb_array_length(selection->'rows') NOT BETWEEN 1 AND 256
  OR jsonb_typeof(record_refs) IS DISTINCT FROM 'array'
  OR jsonb_array_length(record_refs)<>jsonb_array_length(selection->'rows') THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT rule FROM control.retention_policy WHERE participant_id=p AND privacy_domain_id=d
  AND retention_policy_id=policy_id AND data_class='ADMITTED_FACT' AND deletion_mode='ROW_DELETE' AND active_until IS NULL;
 FOR selected IN SELECT value FROM jsonb_array_elements(selection->'rows') LOOP
  ref:=record_refs->row_index;
  IF ref IS DISTINCT FROM jsonb_build_object('candidateId',selected->>'candidate_id','evidenceId',ref->>'evidenceId')
   THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT c.evidence_id,c.stream_id,c.record_id,c.sequence,c.receipt_digest,c.occurred_at,
   s.segment_id,s.object_digest,s.first_sequence,s.through_sequence,s.admitted_at
  INTO STRICT actual FROM control.evidence_catalogue c JOIN control.evidence_segment s
   USING(participant_id,privacy_domain_id,stream_id,segment_id)
   JOIN control.evidence_stream h USING(participant_id,privacy_domain_id,stream_id)
  WHERE c.participant_id=p AND c.privacy_domain_id=d AND c.evidence_id=(ref->>'evidenceId')::uuid
   AND c.source_format='OPENPC_CANONICAL_FACT_V1' AND c.evidence_class='EFFECT'
   AND c.receipt_digest='sha256:'||(selected->>'signed_fact_digest')
   AND c.sequence BETWEEN s.first_sequence AND s.through_sequence AND h.last_sequence>=s.through_sequence;
  IF EXISTS(SELECT 1 FROM control.retention_hold hold WHERE hold.participant_id=p
   AND (hold.selector_type='PARTICIPANT' OR hold.privacy_domain_id=d) AND hold.state='ACTIVE'
   AND openpc.evidence_hold_matches(hold.selector,p,d,actual.stream_id,actual.segment_id))
   THEN RAISE EXCEPTION 'PC-DATA-6007-ACTIVE-HOLD'; END IF;
  -- A complete original checkpoint remains required even for a zero-quorum
  -- policy. This never changes the independent archive's retention deadline.
  IF NOT EXISTS(SELECT 1 FROM control.evidence_checkpoint c WHERE c.participant_id=p AND c.privacy_domain_id=d
   AND c.stream_id=actual.stream_id AND c.segment_id=actual.segment_id AND c.object_digest=actual.object_digest
   AND c.through_sequence=actual.through_sequence) THEN RAISE EXCEPTION 'PC-DATA-6007-CHECKPOINT'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('sinkId',s.sink_id,'checkpointDigest',s.checkpoint_digest,
   'receiptDigest',s.receipt_digest,'acknowledgedAtMicros',s.ack_micros::text) ORDER BY s.ack_micros,s.sink_id),'[]'::jsonb),
   max(ceil(s.ack_micros/1000)) INTO sinks,ack_ms FROM (
    SELECT c.sink_id,c.checkpoint_digest,c.receipt_digest,floor(extract(epoch from c.acknowledged_at)*1000000) ack_micros
     FROM control.evidence_checkpoint c WHERE c.participant_id=p AND c.privacy_domain_id=d
      AND c.stream_id=actual.stream_id AND c.segment_id=actual.segment_id AND c.object_digest=actual.object_digest
      AND c.through_sequence=actual.through_sequence AND c.receipt->>'receiptDigest'=c.receipt_digest
      AND c.receipt->'object'->>'objectDigest'=actual.object_digest
     ORDER BY c.acknowledged_at,c.sink_id LIMIT rule.sink_quorum
   ) s;
  IF jsonb_array_length(sinks)<>rule.sink_quorum THEN RAISE EXCEPTION 'PC-DATA-6007-SINK-QUORUM'; END IF;
  latest:=greatest(ceil(extract(epoch from actual.occurred_at)*1000)+rule.retention_period_ms,
    coalesce(ack_ms,ceil(extract(epoch from actual.admitted_at)*1000))+rule.local_grace_ms);
  eligible_ms:=greatest(eligible_ms,latest);
  refs:=refs||jsonb_build_array(ref);
  manifest:=manifest||jsonb_build_array(jsonb_build_object('candidateId',selected->>'candidate_id',
    'evidenceId',actual.evidence_id::text,'streamId',actual.stream_id,'recordId',actual.record_id,
    'sequence',actual.sequence::text,'recordDigest',actual.receipt_digest,'segmentId',actual.segment_id::text,
    'objectDigest',actual.object_digest));
  acknowledgements:=acknowledgements||jsonb_build_array(jsonb_build_object('candidateId',selected->>'candidate_id','sinkReceipts',sinks));
  row_index:=row_index+1;
 END LOOP;
 IF eligible_ms>floor(extract(epoch from clock_timestamp())*1000) OR eligible_ms>9223372036854775807
  THEN RAISE EXCEPTION 'PC-DATA-6007-RETENTION'; END IF;
 RETURN jsonb_build_object('version','OPENPC_STORE_RETIREMENT_SOURCE_V1','selectionWireHex',encode(selection_wire,'hex'),
  'recordRefs',refs,'manifest',manifest,'acknowledgements',acknowledgements,
  'archiveManifestDigest',encode(sha256(convert_to(openpc.signing_canonical_json(manifest),'UTF8')),'hex'),
  'archiveAcknowledgementDigest',encode(sha256(convert_to(openpc.signing_canonical_json(acknowledgements),'UTF8')),'hex'),
  'retentionNotBeforeMs',eligible_ms::text,'lifecycleRevision',openpc.store_retirement_lifecycle_revision(p,d)::text);
END $$;
REVOKE ALL ON FUNCTION openpc.store_retirement_source_binding(uuid,bytea,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.store_retirement_source_binding(uuid,bytea,jsonb) TO openpc_control_runtime,openpc_control_worker;


INSERT INTO control.action_intent(action_intent_id,resource_type,operation_class,risk_class,maker_checker_required,step_up_required,idempotency_required,existence_disclosure,payload_disclosure,evidence_class)
 VALUES('ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1','evidence-deletions','CREATE','HIGH',true,true,true,'AUTHORIZED_ONLY','REDACTED','RUNTIME_ARTIFACT_SOURCE_DISPOSITION'),
 ('ACT-EVIDENCE_DELETIONS_READ_RUNTIME_SOURCE-V1','evidence-deletions','READ','STANDARD',false,false,false,'AUTHORIZED_ONLY','AUTHORIZED_FULL','RUNTIME_ARTIFACT_SOURCE_DISPOSITION_READ')
 ON CONFLICT DO NOTHING;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM control.action_intent WHERE action_intent_id='ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1' AND resource_type='evidence-deletions'
  AND operation_class='CREATE' AND risk_class='HIGH' AND maker_checker_required AND step_up_required AND idempotency_required
  AND existence_disclosure='AUTHORIZED_ONLY' AND payload_disclosure='REDACTED' AND evidence_class='RUNTIME_ARTIFACT_SOURCE_DISPOSITION')
 OR NOT EXISTS(SELECT 1 FROM control.action_intent WHERE action_intent_id='ACT-EVIDENCE_DELETIONS_READ_RUNTIME_SOURCE-V1'
  AND resource_type='evidence-deletions' AND operation_class='READ' AND risk_class='STANDARD' AND NOT maker_checker_required
  AND NOT step_up_required AND NOT idempotency_required AND existence_disclosure='AUTHORIZED_ONLY' AND payload_disclosure='AUTHORIZED_FULL')
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-ACTION-UNAVAILABLE'; END IF;
END $$;

-- API admission and installed-worker reconciliation have distinct role/action
-- gates. They serialize through the same producer locks, in the same order.
CREATE OR REPLACE FUNCTION openpc.lock_runtime_artifact_disposition()
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
  OR current_setting('session_replication_role')<>'origin'
  OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND NOT rolsuper AND NOT rolbypassrls)
  OR NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
  OR NOT pg_has_role(session_user,'openpc_control_runtime','USAGE')
  OR openpc.current_action_intent_id() NOT IN
   ('ACT-EVIDENCE_DELETIONS_READ_RUNTIME_SOURCE-V1','ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1',
    'ACT-EVIDENCE_DELETIONS_READ_RESOURCE-V1','ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||openpc.current_participant_id()::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('module-release-catalog',0))
  OR NOT pg_try_advisory_xact_lock(hashtextextended('module-admission:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0))
  OR NOT pg_try_advisory_xact_lock_shared(hashtextextended('openpc-policy-generations:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0))
 THEN RAISE EXCEPTION USING ERRCODE='55P03',MESSAGE='RUNTIME-DISPOSITION-PRODUCER-CONTENTION'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.lock_runtime_artifact_disposition() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.lock_runtime_artifact_disposition() TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.assert_runtime_artifact_unused_references(observed jsonb,input_id uuid)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE related jsonb; node jsonb; reference jsonb; parent_configuration text; parent_installation text;
BEGIN
 IF observed->'runtimeProducerFencesObserved' IS DISTINCT FROM 'true'::jsonb
  OR observed->'dependencyProducerFencesObserved' IS DISTINCT FROM 'true'::jsonb
  OR observed->'root'->>'id' IS DISTINCT FROM input_id::text
  OR observed->'root'->>'kind' IS DISTINCT FROM 'INPUT'
  OR EXISTS(SELECT 1 FROM jsonb_each(observed->'owners') branch WHERE branch.value->'overflow' IS DISTINCT FROM 'false'::jsonb)
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-INCOMPLETE_REFERENCES'; END IF;
 SELECT min(r->>'id') FILTER(WHERE r->>'kind'='MODULE_CONFIGURATION'),
   min(r->>'id') FILTER(WHERE r->>'kind'='MODULE_INSTALLATION')
 INTO parent_configuration,parent_installation FROM jsonb_array_elements(observed->'root'->'references') r;
 IF parent_configuration IS NULL OR parent_installation IS NULL
  OR (SELECT count(*) FROM jsonb_array_elements(observed->'root'->'references') r WHERE r->>'kind'='MODULE_CONFIGURATION')<>1
  OR (SELECT count(*) FROM jsonb_array_elements(observed->'root'->'references') r WHERE r->>'kind'='MODULE_INSTALLATION')<>1
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-INCOMPLETE_REFERENCES'; END IF;
 -- Consume the existing owner's typed graph, including downstream original
 -- references. Shared parents alone do not connect unrelated inputs.
 WITH RECURSIVE nodes AS (
  SELECT entry.value body,entry.value->>'kind'||':'||(entry.value->>'id') id
   FROM jsonb_each(observed->'owners') branch CROSS JOIN LATERAL jsonb_array_elements(branch.value->'rows') entry
 ), refs AS (
  SELECT n.id src,r.value->>'kind'||':'||(r.value->>'id') dst,r.value->>'kind' target_kind
   FROM nodes n CROSS JOIN LATERAL jsonb_array_elements(n.body->'references') r
 ), tokens AS (
  SELECT n.id,t.value->>'kind'||':'||(t.value->>'digest') token FROM nodes n
   CROSS JOIN LATERAL jsonb_array_elements(n.body->'tokens') t
 ), token_heads AS (SELECT token,min(id) head FROM tokens GROUP BY token),
 edges AS (
  SELECT src,dst FROM refs UNION SELECT dst,src FROM refs WHERE target_kind IN
   ('WORK','RUNTIME_GENERATION','TARGET','PROBE','POLICY_OCCURRENCE','POLICY_AUTHORIZATION','TARGET_DISPOSITION_ADMISSION','TARGET_DISPOSITION_DELIVERY')
  UNION SELECT t.id,h.head FROM tokens t JOIN token_heads h USING(token)
  UNION SELECT h.head,t.id FROM tokens t JOIN token_heads h USING(token)
 ), reached(id) AS (
  SELECT 'INPUT:'||input_id::text UNION SELECT e.dst FROM reached r JOIN edges e ON e.src=r.id
 ) SELECT coalesce(jsonb_agg(n.body ORDER BY n.id),'[]'::jsonb) INTO related FROM reached r JOIN nodes n USING(id);
 IF jsonb_array_length(related)=0 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-INCOMPLETE_REFERENCES'; END IF;
 FOR node IN SELECT value FROM jsonb_array_elements(related) LOOP
  IF node->>'kind' NOT IN ('INPUT','MODULE_CONFIGURATION','MODULE_INSTALLATION','PROVIDER','INDEXER','PROJECTION','CIGL_SETTINGS')
   OR EXISTS(SELECT 1 FROM jsonb_each(node->'checks') c WHERE c.value='false'::jsonb)
   OR (node->>'kind'='INPUT' AND (node->>'id'<>input_id::text OR node->>'state'<>'RETAINED'
    OR node->'checks'->'bytesMatch' IS DISTINCT FROM 'true'::jsonb OR node->'checks'->'bindingsKnown' IS DISTINCT FROM 'true'::jsonb))
   -- Module parents record where import occurred. They do not themselves use
   -- every historical input imported under that generation. Keep their exact
   -- identities in the observation, and reject an actual retained copy of the
   -- same bytes. Incoming consumers/rollback history remain forbidden above.
   OR (node->>'kind'='MODULE_CONFIGURATION' AND (
    node->>'id' IS DISTINCT FROM parent_configuration
    OR coalesce(node->>'state','') NOT IN ('ACTIVE','INACTIVE')
    OR coalesce(node->'digests'->>'configuration','') !~ '^sha256:[0-9a-f]{64}$'
    OR node->'digests'->>'configuration'=observed->'root'->'digests'->>'configuration'
    OR node->'references' IS DISTINCT FROM jsonb_build_array(jsonb_build_object('kind','MODULE_INSTALLATION','id',parent_installation,'required',true))))
   OR (node->>'kind'='MODULE_INSTALLATION' AND (
    node->>'id' IS DISTINCT FROM parent_installation
    OR coalesce(node->>'state','') NOT IN ('ENABLED','INSTALLED_DISABLED')
    OR coalesce(node->'digests'->>'lifecycle','') !~ '^sha256:[0-9a-f]{64}$'
    OR coalesce(node->'details'->>'lifecycleOperationId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'))
  THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-REFERENCES'; END IF;
  FOR reference IN SELECT value FROM jsonb_array_elements(node->'references') LOOP
   IF reference->'required'='true'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(related) target
    WHERE target->>'kind'=reference->>'kind' AND target->>'id'=reference->>'id')
   THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-INCOMPLETE_REFERENCES'; END IF;
  END LOOP;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(related) c JOIN jsonb_array_elements(related) i
   ON i->>'kind'='MODULE_INSTALLATION' AND i->>'id'=parent_installation
   WHERE c->>'kind'='MODULE_CONFIGURATION' AND c->>'id'=parent_configuration
    AND ((c->>'state'='ACTIVE' AND i->>'state'='ENABLED' AND i->'digests'->>'manifest' ~ '^sha256:[0-9a-f]{64}$')
      OR (c->>'state'='INACTIVE' AND i->>'state'='INSTALLED_DISABLED' AND i->'digests'->'manifest'='null'::jsonb)))
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-INCOMPLETE_REFERENCES'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.assert_runtime_artifact_unused_references(jsonb,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_runtime_artifact_unused_references(jsonb,uuid) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.runtime_artifact_source_observation(input_id uuid,policy_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.runtime_artifact_source; a control.evidence_runtime_artifact_archive; rule control.retention_policy;
 input record; part record; observed jsonb; segments jsonb:='[]'::jsonb; sinks jsonb; ack_micros numeric;
 eligible numeric; p uuid:=openpc.current_participant_id(); d uuid:=openpc.current_privacy_domain_id();
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
  OR current_setting('session_replication_role')<>'origin' OR NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.lock_runtime_artifact_disposition();
 s:=openpc.runtime_artifact_materialization_source();
 IF s.custody_root->>'consumer_profile' IS DISTINCT FROM 'openpc:local-runtime-source-consumers:v2' OR s.archive_custody IS NULL
  THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-SOURCE_UNPROVEN'; END IF;
 PERFORM openpc.assert_runtime_artifact_materialization_boundary();
 SELECT runtime_configuration_input_id,module_installation_id,module_configuration_generation_id,configuration_digest,resource_bindings,selected,created_at,
  openpc.runtime_artifact_input_information(runtime_configuration_input_id) info INTO STRICT input
  FROM control.runtime_configuration_input WHERE participant_id=p AND privacy_domain_id=d AND runtime_configuration_input_id=input_id;
 IF input.selected OR input.info->'bytesMatch' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-SELECTED_INPUT'; END IF;
 observed:=openpc.observe_runtime_artifact_references(input_id,'sha256:'||encode(input.configuration_digest,'hex'));
 PERFORM openpc.assert_runtime_artifact_unused_references(observed,input_id);
 SELECT * INTO STRICT a FROM control.evidence_runtime_artifact_archive WHERE participant_id=p AND privacy_domain_id=d
  AND runtime_configuration_input_id=input_id AND stream_id=s.archive_custody->>'stream_id';
 IF a.source_pending_original IS NULL OR a.manifest_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(a.manifest),'UTF8')),'hex')
  OR a.manifest->'identity' IS DISTINCT FROM jsonb_build_object('participantId',p::text,'privacyDomainId',d::text,
   'runtimeConfigurationInputId',input_id::text,'moduleInstallationId',input.module_installation_id::text,
   'moduleConfigurationGenerationId',input.module_configuration_generation_id::text,'configurationDigest','sha256:'||encode(input.configuration_digest,'hex'),
   'configurationBytes',(input.info->>'byteLength')::integer,'resourceBindingsDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(input.resource_bindings),'UTF8')),'hex'),
   'createdAt',to_char(input.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))
  OR (SELECT count(*) FROM control.evidence_runtime_artifact_archive_part entry
   JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
   JOIN control.evidence_segment seg USING(participant_id,privacy_domain_id,stream_id,segment_id)
   WHERE entry.participant_id=p AND entry.privacy_domain_id=d AND entry.stream_id=a.stream_id AND entry.manifest_record_id=a.record_id
    AND entry.ordinal BETWEEN 0 AND jsonb_array_length(a.manifest->'chunks')
    AND entry.record_id=CASE WHEN entry.ordinal=jsonb_array_length(a.manifest->'chunks') THEN a.record_id
     ELSE a.manifest->'chunks'->entry.ordinal->>'recordId' END
    AND c.receipt_digest=CASE WHEN entry.ordinal=jsonb_array_length(a.manifest->'chunks') THEN a.manifest_digest
     ELSE a.manifest->'chunks'->entry.ordinal->>'digest' END
    AND c.evidence_class='EFFECT' AND c.source_format=CASE WHEN entry.ordinal=jsonb_array_length(a.manifest->'chunks')
     THEN 'OPENPC_RUNTIME_ARTIFACT_MANIFEST_V1' ELSE 'OPENPC_RUNTIME_ARTIFACT_CHUNK_V1' END
    AND c.occurred_at=input.created_at AND c.sequence BETWEEN seg.first_sequence AND seg.through_sequence) IS DISTINCT FROM jsonb_array_length(a.manifest->'chunks')+1
  OR openpc.runtime_artifact_archive_payloads_match(input_id) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-ARCHIVE_UNPROVEN'; END IF;
 SELECT * INTO STRICT rule FROM control.retention_policy WHERE participant_id=p AND privacy_domain_id=d AND retention_policy_id=policy_id
  AND data_class='RUNTIME_ARTIFACT' AND deletion_mode='ROW_DELETE' AND active_until IS NULL;
 eligible:=floor(extract(epoch from input.created_at)*1000000)+rule.retention_period_ms*1000;
 FOR part IN SELECT DISTINCT seg.segment_id,seg.object_digest,seg.first_sequence,seg.through_sequence,seg.admitted_at
  FROM control.evidence_runtime_artifact_archive_part entry JOIN control.evidence_catalogue c USING(participant_id,privacy_domain_id,stream_id,record_id)
  JOIN control.evidence_segment seg USING(participant_id,privacy_domain_id,stream_id,segment_id)
  WHERE entry.participant_id=p AND entry.privacy_domain_id=d AND entry.stream_id=a.stream_id AND entry.manifest_record_id=a.record_id
  ORDER BY seg.first_sequence LOOP
  IF EXISTS(SELECT 1 FROM control.retention_hold h WHERE h.participant_id=p AND (h.selector_type='PARTICIPANT' OR h.privacy_domain_id=d)
   AND h.state='ACTIVE' AND openpc.evidence_hold_matches(h.selector,p,d,a.stream_id,part.segment_id))
   THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-ACTIVE_HOLD'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('sinkId',ack.sink_id,'checkpointDigest',ack.checkpoint_digest,
    'receiptDigest',ack.receipt_digest,'acknowledgedAtMicros',ack.micros::text) ORDER BY ack.micros,ack.sink_id),'[]'::jsonb),max(ack.micros)
   INTO sinks,ack_micros FROM (SELECT c.sink_id,c.checkpoint_digest,c.receipt_digest,floor(extract(epoch from c.acknowledged_at)*1000000) micros
    FROM control.evidence_checkpoint c WHERE c.participant_id=p AND c.privacy_domain_id=d AND c.stream_id=a.stream_id
     AND c.segment_id=part.segment_id AND c.object_digest=part.object_digest AND c.through_sequence=part.through_sequence
     AND c.receipt->>'receiptDigest'=c.receipt_digest
     AND ((NOT c.receipt ? 'kind' AND c.receipt->>'assurance'='LOCAL_FSYNC_READBACK'
       AND c.receipt->'object'->>'objectDigest'=part.object_digest
       AND c.receipt_digest='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(c.receipt-'receiptDigest'),'UTF8')),'hex'))
      OR (c.receipt->>'kind'='SIGNED_REMOTE_ARCHIVE_V1'
       AND openpc.remote_archive_covers(p,d,a.stream_id,part.segment_id,c.sink_id)))
    ORDER BY c.acknowledged_at,c.sink_id LIMIT greatest(1,rule.sink_quorum)) ack;
  IF jsonb_array_length(sinks)<>greatest(1,rule.sink_quorum) THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-SINK_QUORUM'; END IF;
  eligible:=greatest(eligible,ack_micros+rule.local_grace_ms*1000);
  segments:=segments||jsonb_build_array(jsonb_build_object('segmentId',part.segment_id::text,'objectDigest',part.object_digest,
   'firstSequence',part.first_sequence::text,'throughSequence',part.through_sequence::text,'sinkReceipts',sinks));
 END LOOP;
 IF jsonb_array_length(segments) NOT BETWEEN 1 AND 65 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-ARCHIVE_UNPROVEN'; END IF;
 IF eligible>floor(extract(epoch from clock_timestamp())*1000000) THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-RETENTION_NOT_ELAPSED'; END IF;
 RETURN jsonb_build_object('version','OPENPC_RUNTIME_ARTIFACT_SOURCE_DISPOSITION_V1','sourceOwnerId',s.source_owner_id::text,
  'sourceRootDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(s.custody_root),'UTF8')),'hex'),
  'archivePendingDigest','sha256:'||encode(sha256(a.source_pending_original),'hex'),
  'observation',jsonb_build_object('version','OPENPC_RUNTIME_ARTIFACT_DELETION_BATCH_V1','participantId','urn:openpc:participant:'||p::text,
   'privacyDomainId',d::text,'retentionPolicyId','urn:openpc:resource:'||policy_id::text,'policyDigest',rule.policy_digest,
   'targetDatabase','openpc_control','dataClass','RUNTIME_ARTIFACT','deletionMode','ROW_DELETE','source',a.manifest->'identity',
   'streamId',a.stream_id,'manifestRecordId',a.record_id,'manifestDigest',a.manifest_digest,'archiveSegments',segments,
   'referenceObservationDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(observed),'UTF8')),'hex'),
   'eligibleAfterMicros',eligible::text,'priorCursor',null));
END $$;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_source_observation(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_source_observation(uuid,uuid) TO openpc_control_runtime;

-- Withdrawal admits only new disposition. Physical retirement instead consumes
-- this observation with a committed native denial and its own live governance.
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_disposition_selection(input_id uuid,policy_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE configuration bytea;
BEGIN
 PERFORM openpc.lock_runtime_artifact_disposition();
 IF openpc.current_action_intent_id() NOT IN
  ('ACT-EVIDENCE_DELETIONS_READ_RUNTIME_SOURCE-V1','ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT configuration_digest INTO STRICT configuration FROM control.runtime_configuration_input
  WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id()
   AND runtime_configuration_input_id=input_id;
 IF NOT openpc.runtime_artifact_new_use_allowed(openpc.current_participant_id(),openpc.current_privacy_domain_id(),configuration)
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-ALREADY_DISPOSED'; END IF;
 RETURN openpc.runtime_artifact_source_observation(input_id,policy_id);
END $$;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_disposition_selection(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_disposition_selection(uuid,uuid) TO openpc_control_runtime;

GRANT INSERT ON control.runtime_artifact_source_disposition TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.runtime_artifact_disposition_state(a control.runtime_artifact_source_disposition)
RETURNS jsonb LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('0',openpc.business_uuid((a).source_owner_id),'1',openpc.business_uuid((a).runtime_configuration_input_id),
  '2',openpc.business_bytes((a).configuration_digest),'3',openpc.business_bytes((a).selection_digest),
  '4',openpc.business_uuid((a).approval_request_id),'5',openpc.business_uuid((a).operation_id),
  '6',floor(extract(epoch from (a).admitted_at)*1000000)*1000)
$$;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_disposition_state(control.runtime_artifact_source_disposition) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_disposition_state(control.runtime_artifact_source_disposition) TO openpc_control_runtime,openpc_control_worker,openpc_control_reader;

CREATE OR REPLACE FUNCTION openpc.guard_runtime_artifact_source_disposition_immutable()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP<>'INSERT' OR openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 PERFORM openpc.lock_runtime_artifact_disposition();
 RETURN NULL;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_runtime_artifact_disposition_row()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE actual jsonb;
BEGIN
 IF TG_OP<>'INSERT' OR pg_trigger_depth()<>1 OR openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1'
  OR NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR NEW.operation_id IS DISTINCT FROM openpc.current_operation_id() OR NEW.revision<>1
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 actual:=openpc.runtime_artifact_disposition_selection(NEW.runtime_configuration_input_id,right(NEW.selection->'observation'->>'retentionPolicyId',36)::uuid);
 IF actual IS DISTINCT FROM NEW.selection OR NEW.source_owner_id IS DISTINCT FROM (actual->>'sourceOwnerId')::uuid
  OR NEW.configuration_digest IS DISTINCT FROM decode(substring(actual->'observation'->'source'->>'configurationDigest' from 8),'hex')
  OR NEW.selection_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(actual),'UTF8'))
 THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-STALE_SELECTION'; END IF;
 NEW.admitted_at:=clock_timestamp();
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS runtime_artifact_disposition_row ON control.runtime_artifact_source_disposition;
CREATE TRIGGER runtime_artifact_disposition_row BEFORE INSERT OR UPDATE OR DELETE ON control.runtime_artifact_source_disposition
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_runtime_artifact_disposition_row();

CREATE OR REPLACE FUNCTION openpc.assert_runtime_artifact_disposition_receipt(receipt control.audit_occurrence)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF receipt.profile_id<>'pc.control.runtime-artifact.disposition' OR receipt.profile_version<>1 OR receipt.catalog_operation_id<>'CFG-OP-DISPOSE-RUNTIME-ARTIFACT-SOURCE'
  OR receipt.action_intent_id<>'ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1' OR receipt.aggregate_type<>'runtime-artifact-disposition'
  OR receipt.before_existence<>0 OR receipt.before_revision<>0 OR receipt.after_existence<>1 OR receipt.after_revision<>1
  OR openpc.business_cbor(receipt.before_state_preimage)->8 IS DISTINCT FROM '{}'::jsonb
  OR NOT EXISTS(SELECT 1 FROM control.runtime_artifact_source_disposition a WHERE a.participant_id=receipt.participant_id
   AND a.privacy_domain_id=receipt.privacy_domain_id AND a.disposition_id=receipt.aggregate_id AND a.operation_id=receipt.operation_id
   AND openpc.business_cbor(receipt.after_state_preimage)->8=openpc.runtime_artifact_disposition_state(a))
 THEN RAISE EXCEPTION 'DATA-6021-RECEIPT-ACTUAL-SOURCE-DISPOSITION'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.assert_runtime_artifact_source_disposition_committed(a control.runtime_artifact_source_disposition)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE matched integer; receipt control.audit_occurrence;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF a.participant_id IS DISTINCT FROM openpc.current_participant_id() OR a.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR a.revision<>1 OR a.selection_digest IS DISTINCT FROM sha256(convert_to(openpc.signing_canonical_json(a.selection),'UTF8'))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id
  AND aggregate_id=a.disposition_id AND aggregate_type='runtime-artifact-disposition' AND operation_id=a.operation_id;
 PERFORM openpc.assert_runtime_artifact_disposition_receipt(receipt);
 SELECT count(*) INTO matched FROM control.mutation_evidence e JOIN control.mutation_candidate c
  ON c.participant_id=e.participant_id AND c.privacy_domain_id=e.privacy_domain_id AND c.resource_id=e.aggregate_id
   AND c.consumed_operation_id=e.operation_id AND c.candidate_digest=e.candidate_digest
  JOIN control.idempotency_record i ON i.participant_id=e.participant_id AND i.privacy_domain_id=e.privacy_domain_id
   AND i.operation_id=e.operation_id AND i.catalog_operation_id=e.catalog_operation_id AND i.input_digest=e.candidate_digest
 WHERE e.participant_id=a.participant_id AND e.privacy_domain_id=a.privacy_domain_id AND e.operation_id=a.operation_id
  AND e.approval_request_id=a.approval_request_id AND e.aggregate_type='runtime-artifact-disposition' AND e.aggregate_id=a.disposition_id
  AND e.catalog_operation_id='CFG-OP-DISPOSE-RUNTIME-ARTIFACT-SOURCE' AND e.action_intent_id='ACT-EVIDENCE_DELETIONS_DISPOSE_RUNTIME_SOURCE-V1'
  AND c.catalog_operation_id=e.catalog_operation_id AND c.action_intent_id=e.action_intent_id AND c.state='CONSUMED' AND c.expected_revision=0
  AND c.candidate_document->'selection'=a.selection AND i.terminal_state='COMMITTED' AND i.expected_aggregate_version=0
  AND receipt.candidate_digest=e.candidate_digest AND receipt.idempotency_record_id=i.idempotency_record_id
  AND receipt.receipt_digest=sha256(receipt.receipt_cbor)
  AND (SELECT count(*) FROM control.outbox_event event WHERE event.participant_id=receipt.participant_id
   AND event.privacy_domain_id=receipt.privacy_domain_id AND event.receipt_id=receipt.receipt_id
   AND event.aggregate_type=receipt.aggregate_type AND event.aggregate_id=receipt.aggregate_id
   AND event.event_type='io.openpc.control.command.committed.v1' AND event.proof_kind='BUSINESS_RECEIPT_REFERENCE'
   AND event.sequence_namespace='CONTROL_BUSINESS_TRANSITION_V1' AND event.payload_digest=sha256(event.payload_cbor))=1;
 IF matched<>1 THEN RAISE EXCEPTION 'PC-AUTH-0002-RUNTIME-DISPOSITION-SIGNED-ADMISSION'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.require_runtime_artifact_disposition_commit()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_runtime_artifact_source_disposition_committed(NEW);
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS runtime_artifact_disposition_commit ON control.runtime_artifact_source_disposition;
CREATE CONSTRAINT TRIGGER runtime_artifact_disposition_commit AFTER INSERT ON control.runtime_artifact_source_disposition
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.require_runtime_artifact_disposition_commit();
REVOKE ALL ON FUNCTION openpc.guard_runtime_artifact_disposition_row(),openpc.assert_runtime_artifact_disposition_receipt(control.audit_occurrence),
 openpc.assert_runtime_artifact_source_disposition_committed(control.runtime_artifact_source_disposition),openpc.require_runtime_artifact_disposition_commit() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_runtime_artifact_disposition_receipt(control.audit_occurrence),
 openpc.assert_runtime_artifact_source_disposition_committed(control.runtime_artifact_source_disposition) TO openpc_control_runtime,openpc_control_worker;



CREATE OR REPLACE FUNCTION openpc.runtime_artifact_retirement_before(source jsonb)
RETURNS text LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
  'domain','pc.evidence.runtime-artifact-before.v1','source',source)),'UTF8')),'hex')
$$;
CREATE OR REPLACE FUNCTION openpc.runtime_artifact_retirement_input_identity(input_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE source record; info jsonb;
BEGIN
 PERFORM openpc.assert_request_context(true);
 SELECT participant_id,privacy_domain_id,runtime_configuration_input_id,module_installation_id,
  module_configuration_generation_id,configuration_digest,resource_bindings,created_at INTO STRICT source
  FROM control.runtime_configuration_input WHERE participant_id=openpc.current_participant_id()
   AND privacy_domain_id=openpc.current_privacy_domain_id() AND runtime_configuration_input_id=input_id;
 info:=openpc.runtime_artifact_input_information(input_id);
 IF info->'bytesMatch' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'RUNTIME-DISPOSITION-ARCHIVE_UNPROVEN'; END IF;
 RETURN jsonb_build_object('participantId',source.participant_id::text,'privacyDomainId',source.privacy_domain_id::text,
  'runtimeConfigurationInputId',input_id::text,'moduleInstallationId',source.module_installation_id::text,
  'moduleConfigurationGenerationId',source.module_configuration_generation_id::text,
  'configurationDigest','sha256:'||encode(source.configuration_digest,'hex'),'configurationBytes',(info->>'byteLength')::integer,
  'resourceBindingsDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(source.resource_bindings),'UTF8')),'hex'),
  'createdAt',to_char(source.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END $$;

CREATE OR REPLACE FUNCTION openpc.runtime_artifact_retirement_selection(policy_id uuid,previous_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p uuid:=openpc.current_participant_id(); d uuid:=openpc.current_privacy_domain_id();
 prior control.deletion_job; retired control.runtime_artifact_retirement; admission control.runtime_artifact_source_disposition;
 denied control.runtime_artifact_source_denial; receipt control.audit_occurrence;
 input_id uuid; next_id uuid; selected jsonb; source jsonb; next_source jsonb; successor jsonb:='null'::jsonb;
 cursor jsonb:='null'::jsonb; expected jsonb; root_digest text;
BEGIN
 PERFORM openpc.lock_runtime_artifact_disposition();
 IF openpc.current_action_intent_id() NOT IN ('ACT-EVIDENCE_DELETIONS_READ_RESOURCE-V1','ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF previous_id IS NOT NULL THEN
  SELECT * INTO STRICT prior FROM control.deletion_job WHERE participant_id=p AND privacy_domain_id=d
   AND deletion_job_id=previous_id AND target_data_class='RUNTIME_ARTIFACT' AND state='SUCCEEDED' AND revision=1;
  SELECT * INTO STRICT retired FROM control.runtime_artifact_retirement WHERE participant_id=p AND privacy_domain_id=d AND deletion_job_id=previous_id;
  PERFORM openpc.assert_runtime_artifact_retirement_committed(retired);
  IF EXISTS(SELECT 1 FROM control.deletion_job WHERE participant_id=p AND privacy_domain_id=d AND previous_deletion_job_id=previous_id
    AND operation_id IS DISTINCT FROM openpc.current_operation_id())
   OR prior.selection->'nextInput'='null'::jsonb THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-STALE_SELECTION'; END IF;
  expected:=prior.selection->'nextInput'; input_id:=(expected->>'runtimeConfigurationInputId')::uuid;
  SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=p AND privacy_domain_id=d
   AND operation_id=prior.operation_id AND aggregate_id=previous_id AND aggregate_type='evidence-deletion';
  cursor:=jsonb_build_object('deletionJobId','urn:openpc:resource:'||previous_id::text,
   'receiptDigest','sha256:'||encode(receipt.receipt_digest,'hex'));
 ELSE
  -- A committed predecessor with a promised successor cannot be bypassed by
  -- opening another chain or changing only the request key.
  IF EXISTS(SELECT 1 FROM control.deletion_job j WHERE j.participant_id=p AND j.privacy_domain_id=d
    AND j.target_data_class='RUNTIME_ARTIFACT' AND j.state='SUCCEEDED' AND j.selection->'nextInput'<>'null'::jsonb
    AND NOT EXISTS(SELECT 1 FROM control.deletion_job n WHERE n.participant_id=p AND n.privacy_domain_id=d AND n.previous_deletion_job_id=j.deletion_job_id))
   THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-STALE_SELECTION'; END IF;
  SELECT runtime_configuration_input_id INTO input_id FROM control.runtime_configuration_input
   WHERE participant_id=p AND privacy_domain_id=d ORDER BY runtime_configuration_input_id LIMIT 1;
 END IF;
 IF input_id IS NULL THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-ALREADY_DELETED'; END IF;
 IF input_id IS DISTINCT FROM (SELECT runtime_configuration_input_id FROM control.runtime_configuration_input
  WHERE participant_id=p AND privacy_domain_id=d ORDER BY runtime_configuration_input_id LIMIT 1)
 THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-STALE_SELECTION'; END IF;
 source:=openpc.runtime_artifact_retirement_input_identity(input_id);
 IF expected IS NOT NULL AND expected IS DISTINCT FROM jsonb_build_object('runtimeConfigurationInputId',input_id::text,
  'configurationDigest',source->>'configurationDigest','beforeDigest',openpc.runtime_artifact_retirement_before(source))
 THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-STALE_SELECTION'; END IF;
 SELECT * INTO admission FROM control.runtime_artifact_source_disposition WHERE participant_id=p AND privacy_domain_id=d
  AND runtime_configuration_input_id=input_id AND configuration_digest=decode(substring(source->>'configurationDigest' from 8),'hex');
 IF NOT FOUND THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-GOVERNED_DISPOSITION_REQUIRED'; END IF;
 PERFORM openpc.assert_runtime_artifact_source_disposition_committed(admission);
 SELECT * INTO denied FROM control.runtime_artifact_source_denial WHERE participant_id=p AND privacy_domain_id=d
  AND disposition_id=admission.disposition_id AND source_owner_id=admission.source_owner_id;
 IF NOT FOUND OR denied.denial_digest IS DISTINCT FROM sha256(denied.signed_denial)
 THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-RUNTIME_CUSTODY_UNPROVEN'; END IF;
 selected:=openpc.runtime_artifact_source_observation(input_id,policy_id);
 root_digest:=selected->>'sourceRootDigest';
 IF selected->>'sourceOwnerId' IS DISTINCT FROM admission.source_owner_id::text
  OR root_digest IS DISTINCT FROM admission.selection->>'sourceRootDigest'
  OR selected->'observation'->'source' IS DISTINCT FROM source
  OR selected->>'archivePendingDigest' IS DISTINCT FROM admission.selection->>'archivePendingDigest'
 THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-RUNTIME_CUSTODY_UNPROVEN'; END IF;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=p AND privacy_domain_id=d
  AND operation_id=admission.operation_id AND aggregate_id=admission.disposition_id AND aggregate_type='runtime-artifact-disposition';
 SELECT runtime_configuration_input_id INTO next_id FROM control.runtime_configuration_input
  WHERE participant_id=p AND privacy_domain_id=d AND runtime_configuration_input_id>input_id ORDER BY runtime_configuration_input_id LIMIT 1;
 IF next_id IS NOT NULL THEN
  next_source:=openpc.runtime_artifact_retirement_input_identity(next_id);
  successor:=jsonb_build_object('runtimeConfigurationInputId',next_id::text,'configurationDigest',next_source->>'configurationDigest',
   'beforeDigest',openpc.runtime_artifact_retirement_before(next_source));
 END IF;
 RETURN selected->'observation'||jsonb_build_object('priorCursor',cursor,'nextInput',successor,'disposition',jsonb_build_object(
  'dispositionId',admission.disposition_id::text,'operationId',admission.operation_id::text,
  'receiptDigest','sha256:'||encode(receipt.receipt_digest,'hex'),'nativeDenialDigest','sha256:'||encode(denied.denial_digest,'hex'),
  'sourceOwnerId',admission.source_owner_id::text,'sourceRootDigest',root_digest));
END $$;

CREATE OR REPLACE FUNCTION openpc.runtime_artifact_retirement_plan(policy_id uuid,previous_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE selection jsonb; blocker text; next_job uuid; prior control.deletion_job; retired control.runtime_artifact_retirement;
BEGIN
 PERFORM openpc.lock_runtime_artifact_disposition();
 IF previous_id IS NOT NULL THEN
  SELECT * INTO STRICT prior FROM control.deletion_job WHERE participant_id=openpc.current_participant_id()
   AND privacy_domain_id=openpc.current_privacy_domain_id() AND deletion_job_id=previous_id AND target_data_class='RUNTIME_ARTIFACT';
  SELECT * INTO STRICT retired FROM control.runtime_artifact_retirement WHERE participant_id=prior.participant_id
   AND privacy_domain_id=prior.privacy_domain_id AND deletion_job_id=prior.deletion_job_id;
  PERFORM openpc.assert_runtime_artifact_retirement_committed(retired);
  SELECT deletion_job_id INTO next_job FROM control.deletion_job WHERE participant_id=prior.participant_id
   AND privacy_domain_id=prior.privacy_domain_id AND previous_deletion_job_id=previous_id;
  IF next_job IS NOT NULL OR prior.selection->'nextInput'='null'::jsonb THEN
   RETURN jsonb_build_object('selection',null,'beforeDigest',null,'eligible',false,'blockers','[]'::jsonb,
    'continuationState',CASE WHEN next_job IS NULL THEN 'COMPLETE' ELSE 'ADVANCED' END,
    'nextDeletionJobId',CASE WHEN next_job IS NULL THEN NULL ELSE 'urn:openpc:resource:'||next_job::text END,'authority','NONE');
  END IF;
 END IF;
 BEGIN
  selection:=openpc.runtime_artifact_retirement_selection(policy_id,previous_id);
 EXCEPTION WHEN no_data_found THEN blocker:='STALE_SELECTION';
 WHEN raise_exception THEN
  blocker:=regexp_replace(SQLERRM,'^RUNTIME-(DISPOSITION|RETIREMENT)-','');
  blocker:=CASE blocker WHEN 'INCOMPLETE_REFERENCES' THEN 'INCOMPLETE_REFERENCE_COVERAGE'
    WHEN 'SOURCE_UNPROVEN' THEN 'SOURCE_REDELIVERY_UNPROVEN' WHEN 'ARCHIVE_UNPROVEN' THEN 'RUNTIME_CUSTODY_UNPROVEN' ELSE blocker END;
  IF blocker NOT IN ('STALE_SELECTION','SELECTED_INPUT','REFERENCES','ACTIVE_HOLD','SINK_QUORUM','RETENTION_NOT_ELAPSED',
   'INCOMPLETE_REFERENCE_COVERAGE','SOURCE_REDELIVERY_UNPROVEN','RUNTIME_CUSTODY_UNPROVEN','GOVERNED_DISPOSITION_REQUIRED','ALREADY_DELETED') THEN RAISE; END IF;
 END;
 RETURN jsonb_build_object('selection',selection,'beforeDigest',CASE WHEN selection IS NULL THEN NULL
  ELSE openpc.runtime_artifact_retirement_before(selection->'source') END,'eligible',selection IS NOT NULL,
  'blockers',CASE WHEN blocker IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(blocker) END,
  'continuationState',CASE WHEN selection IS NULL THEN 'BLOCKED' ELSE 'READY' END,'nextDeletionJobId',null,'authority','NONE');
END $$;
REVOKE ALL ON FUNCTION openpc.runtime_artifact_retirement_before(jsonb),openpc.runtime_artifact_retirement_input_identity(uuid),
 openpc.runtime_artifact_retirement_selection(uuid,uuid),openpc.runtime_artifact_retirement_plan(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.runtime_artifact_retirement_before(jsonb),openpc.runtime_artifact_retirement_input_identity(uuid),
 openpc.runtime_artifact_retirement_selection(uuid,uuid),openpc.runtime_artifact_retirement_plan(uuid,uuid) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.assert_runtime_artifact_retirement_eligible(job control.deletion_job,input control.runtime_configuration_input)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE selected jsonb;
BEGIN
 PERFORM openpc.assert_runtime_artifact_retirement_context();
 IF (job).participant_id IS DISTINCT FROM openpc.current_participant_id()
  OR (job).privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR (input).participant_id IS DISTINCT FROM (job).participant_id OR (input).privacy_domain_id IS DISTINCT FROM (job).privacy_domain_id
  OR (job).operation_id IS DISTINCT FROM openpc.current_operation_id()
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1'
  OR (job).state<>'EXECUTING' OR (job).revision<>0 OR (job).target_database<>'openpc_control'
  OR (job).target_data_class<>'RUNTIME_ARTIFACT' OR (job).external_attempt_state<>'NOT_STARTED'
  OR (input).selected OR (input).configuration_digest IS DISTINCT FROM sha256((input).configuration_cbor)
  OR octet_length((input).configuration_cbor) NOT BETWEEN 1 AND 4194304
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-SOURCE'; END IF;
 selected:=openpc.runtime_artifact_retirement_selection((job).retention_policy_id,(job).previous_deletion_job_id);
 IF selected IS DISTINCT FROM (job).selection
  OR selected->'source'->>'runtimeConfigurationInputId' IS DISTINCT FROM (input).runtime_configuration_input_id::text
  OR selected->'source'->>'configurationDigest' IS DISTINCT FROM 'sha256:'||encode((input).configuration_digest,'hex')
  OR (job).before_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_before(selected->'source')
 THEN RAISE EXCEPTION 'RUNTIME-RETIREMENT-STALE_SELECTION'; END IF;
END $$;

CREATE OR REPLACE FUNCTION openpc.assert_runtime_artifact_retirement_effect(job control.deletion_job,r control.runtime_artifact_retirement)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE admission control.runtime_artifact_source_disposition; denied control.runtime_artifact_source_denial; receipt control.audit_occurrence;
BEGIN
 PERFORM openpc.assert_runtime_artifact_retirement_context();
 IF (job).participant_id IS DISTINCT FROM (r).participant_id OR (job).privacy_domain_id IS DISTINCT FROM (r).privacy_domain_id
  OR (job).deletion_job_id IS DISTINCT FROM (r).deletion_job_id OR (job).state<>'SUCCEEDED' OR (job).revision<>1
  OR (job).target_database<>'openpc_control' OR (job).target_data_class<>'RUNTIME_ARTIFACT'
  OR (job).external_attempt_state<>'NOT_STARTED' OR (job).deleted_count<>1 OR (job).retained_alias_count<>0
  OR (job).before_used_bytes IS DISTINCT FROM (r).configuration_bytes OR (job).deleted_bytes IS DISTINCT FROM (r).configuration_bytes
  OR (job).after_used_bytes IS DISTINCT FROM 0 OR (job).selection->'source' IS DISTINCT FROM openpc.runtime_artifact_retirement_source(r)
  OR (job).before_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_before((job).selection->'source')
  OR (job).after_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_after_digest(r)
  OR (r).retirement_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_digest(r)
  OR EXISTS(SELECT 1 FROM control.runtime_configuration_input WHERE participant_id=(r).participant_id
   AND privacy_domain_id=(r).privacy_domain_id AND (runtime_configuration_input_id=(r).runtime_configuration_input_id
    OR configuration_digest=decode(substring((r).configuration_digest from 8),'hex')))
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-EFFECT'; END IF;
 -- Historical verification binds retained originals, never today's policy,
 -- selected generation, expiry or reference graph.
 SELECT * INTO STRICT admission FROM control.runtime_artifact_source_disposition WHERE participant_id=(r).participant_id
  AND privacy_domain_id=(r).privacy_domain_id AND disposition_id=((job).selection->'disposition'->>'dispositionId')::uuid
  AND runtime_configuration_input_id=(r).runtime_configuration_input_id
  AND configuration_digest=decode(substring((r).configuration_digest from 8),'hex');
 PERFORM openpc.assert_runtime_artifact_source_disposition_committed(admission);
 SELECT * INTO STRICT denied FROM control.runtime_artifact_source_denial WHERE participant_id=admission.participant_id
  AND privacy_domain_id=admission.privacy_domain_id AND disposition_id=admission.disposition_id AND source_owner_id=admission.source_owner_id;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=admission.participant_id
  AND privacy_domain_id=admission.privacy_domain_id AND operation_id=admission.operation_id
  AND aggregate_id=admission.disposition_id AND aggregate_type='runtime-artifact-disposition';
 IF (job).selection->'disposition' IS DISTINCT FROM jsonb_build_object('dispositionId',admission.disposition_id::text,
  'operationId',admission.operation_id::text,'receiptDigest','sha256:'||encode(receipt.receipt_digest,'hex'),
  'nativeDenialDigest','sha256:'||encode(denied.denial_digest,'hex'),'sourceOwnerId',admission.source_owner_id::text,
  'sourceRootDigest',admission.selection->>'sourceRootDigest') OR denied.denial_digest IS DISTINCT FROM sha256(denied.signed_denial)
 THEN RAISE EXCEPTION 'RUNTIME-ARTIFACT-RETIREMENT-EFFECT'; END IF;
END $$;

CREATE OR REPLACE FUNCTION openpc.guard_runtime_artifact_deletion_job(operation text,old_job control.deletion_job,new_job control.deletion_job)
RETURNS control.deletion_job LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE selected jsonb; item control.runtime_artifact_retirement;
BEGIN
 PERFORM openpc.lock_runtime_artifact_disposition();
 IF operation NOT IN ('INSERT','UPDATE') OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_CREATE_RUNTIME_BATCH-V1'
  OR new_job.participant_id IS DISTINCT FROM openpc.current_participant_id() OR new_job.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR new_job.operation_id IS DISTINCT FROM openpc.current_operation_id() OR new_job.target_database<>'openpc_control'
  OR new_job.target_data_class<>'RUNTIME_ARTIFACT' OR new_job.external_attempt_state<>'NOT_STARTED'
  OR new_job.selection->>'version' IS DISTINCT FROM 'OPENPC_RUNTIME_ARTIFACT_DELETION_BATCH_V1'
  OR new_job.stream_id IS DISTINCT FROM new_job.selection->>'streamId' OR new_job.segment_id IS NOT NULL
  OR new_job.protected_object_id IS NOT NULL
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF operation='INSERT' THEN
  new_job.previous_deletion_job_id:=right(new_job.selection->'priorCursor'->>'deletionJobId',36)::uuid;
  selected:=openpc.runtime_artifact_retirement_selection(new_job.retention_policy_id,new_job.previous_deletion_job_id);
  IF selected IS DISTINCT FROM new_job.selection OR new_job.state<>'EXECUTING' OR new_job.revision<>0
   OR new_job.before_digest IS DISTINCT FROM openpc.runtime_artifact_retirement_before(selected->'source')
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  new_job.target_selector_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(
   'domain','pc.evidence.runtime-artifact-selector.v1','source',selected->'source')),'UTF8')),'hex');
  new_job.eligibility_digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(selected),'UTF8')),'hex');
  new_job.before_used_bytes:=(selected->'source'->>'configurationBytes')::integer;new_job.after_used_bytes:=NULL;
  new_job.started_at:=clock_timestamp();new_job.created_at:=new_job.started_at;
 ELSE
  IF old_job.state<>'EXECUTING' OR new_job.state<>'SUCCEEDED' OR old_job.revision<>0 OR new_job.revision<>1
   OR (to_jsonb(new_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at']) IS DISTINCT FROM
    (to_jsonb(old_job)-ARRAY['state','revision','deleted_count','deleted_bytes','after_used_bytes','after_digest','completed_at','updated_at'])
  THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
  SELECT * INTO STRICT item FROM control.runtime_artifact_retirement WHERE participant_id=new_job.participant_id
   AND privacy_domain_id=new_job.privacy_domain_id AND deletion_job_id=new_job.deletion_job_id;
  new_job.deleted_count:=1;new_job.deleted_bytes:=item.configuration_bytes;new_job.after_used_bytes:=0;
  new_job.after_digest:=openpc.runtime_artifact_retirement_after_digest(item);
  PERFORM openpc.assert_runtime_artifact_retirement_effect(new_job,item);
  new_job.completed_at:=clock_timestamp();
 END IF;
 new_job.updated_at:=clock_timestamp();RETURN new_job;
END $$;

GRANT DELETE ON control.runtime_configuration_input TO openpc_control_runtime;
GRANT INSERT ON control.runtime_artifact_retirement TO openpc_control_runtime;
DROP TRIGGER IF EXISTS runtime_artifact_retirement_capture ON control.runtime_configuration_input;
CREATE TRIGGER runtime_artifact_retirement_capture BEFORE DELETE ON control.runtime_configuration_input
 FOR EACH ROW EXECUTE FUNCTION openpc.capture_runtime_artifact_retirement();
REVOKE ALL ON FUNCTION openpc.assert_runtime_artifact_retirement_eligible(control.deletion_job,control.runtime_configuration_input),
 openpc.assert_runtime_artifact_retirement_effect(control.deletion_job,control.runtime_artifact_retirement),
 openpc.guard_runtime_artifact_deletion_job(text,control.deletion_job,control.deletion_job) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_runtime_artifact_retirement_eligible(control.deletion_job,control.runtime_configuration_input),
 openpc.assert_runtime_artifact_retirement_effect(control.deletion_job,control.runtime_artifact_retirement),
 openpc.guard_runtime_artifact_deletion_job(text,control.deletion_job,control.deletion_job),
 openpc.runtime_artifact_retirement_source(control.runtime_artifact_retirement) TO openpc_control_runtime;
-- The installed source role verifies historical tombstones. It never receives
-- physical mutation, current-plan or raw source-byte grants.
GRANT EXECUTE ON FUNCTION openpc.assert_runtime_artifact_retirement_effect(control.deletion_job,control.runtime_artifact_retirement),
 openpc.runtime_artifact_retirement_source(control.runtime_artifact_retirement),openpc.runtime_artifact_retirement_before(jsonb),
 openpc.runtime_artifact_retirement_digest(control.runtime_artifact_retirement),
 openpc.runtime_artifact_retirement_after_digest(control.runtime_artifact_retirement),
 openpc.assert_runtime_artifact_retirement_owner(text),openpc.assert_runtime_artifact_retirement_committed(control.runtime_artifact_retirement),
 openpc.evidence_deletion_operation(jsonb),openpc.evidence_deletion_profile_version(jsonb),
 openpc.evidence_deletion_state_projection(control.deletion_job),
 openpc.assert_evidence_deletion_receipt(control.audit_occurrence) TO openpc_control_worker;


INSERT INTO control.action_intent(action_intent_id,resource_type,operation_class,risk_class,
 maker_checker_required,step_up_required,idempotency_required,existence_disclosure,payload_disclosure,evidence_class)
VALUES ('ACT-EVIDENCE_DELETIONS_ADMIT_STORE_BATCH-V1','evidence-deletions','CREATE','HIGH',true,true,true,'AUTHORIZED_ONLY','REDACTED','STORE_RETIREMENT_ADMISSION'),
 ('ACT-EVIDENCE_DELETIONS_RECONCILE_STORE_BATCH-V1','evidence-deletions','UPDATE','HIGH',false,false,true,'AUTHORIZED_ONLY','REDACTED','STORE_RETIREMENT_RECONCILIATION')
ON CONFLICT DO NOTHING;
DO $$ BEGIN
 IF (SELECT count(*) FROM control.action_intent WHERE
  (action_intent_id,resource_type,operation_class,risk_class,maker_checker_required,step_up_required,
   idempotency_required,existence_disclosure,payload_disclosure,evidence_class) IN (
  ('ACT-EVIDENCE_DELETIONS_ADMIT_STORE_BATCH-V1','evidence-deletions','CREATE','HIGH',true,true,true,'AUTHORIZED_ONLY','REDACTED','STORE_RETIREMENT_ADMISSION'),
  ('ACT-EVIDENCE_DELETIONS_RECONCILE_STORE_BATCH-V1','evidence-deletions','UPDATE','HIGH',false,false,true,'AUTHORIZED_ONLY','REDACTED','STORE_RETIREMENT_RECONCILIATION')))<>2
 THEN RAISE EXCEPTION 'PC-AUTH-0002-STORE-RETIREMENT-ACTION'; END IF;
END $$;

CREATE OR REPLACE FUNCTION openpc.guard_store_retirement_host()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE host jsonb:=convert_from(NEW.host_wire,'UTF8')::jsonb;
BEGIN
 IF host IS DISTINCT FROM jsonb_build_object('environment_id',host->>'environment_id','target_id',host->>'target_id',
   'scope',jsonb_build_object('participant_id',NEW.participant_id::text,'privacy_domain_id',NEW.privacy_domain_id::text),'store',host->>'store')
  OR coalesce(host->>'environment_id','')!~'^[!-~]{1,160}$' OR coalesce(host->>'target_id','')!~'^[!-~]{1,160}$'
  OR coalesce(host->>'store','') NOT IN ('openpc_facts','openpc_candidate_index')
  OR encode(substring(NEW.control_spki from 1 for 27),'hex')<>'3059301306072a8648ce3d020106082a8648ce3d03010703420004'
  OR encode(substring(NEW.target_spki from 1 for 27),'hex')<>'3059301306072a8648ce3d020106082a8648ce3d03010703420004'
  OR NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname=NEW.database_role AND r.rolcanlogin
   AND NOT r.rolsuper AND NOT r.rolbypassrls AND NOT r.rolcreaterole AND pg_has_role(r.oid,'openpc_control_worker','USAGE')
   AND NOT pg_has_role(r.oid,'openpc_control_owner','MEMBER') AND NOT pg_has_role(r.oid,'openpc_control_key_governor','MEMBER'))
  OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal w USING(participant_id,principal_id)
   WHERE c.participant_id=NEW.participant_id AND c.credential_id=NEW.workload_credential_id
    AND c.kind IN ('WORKLOAD_MTLS','WORKLOAD_OIDC') AND c.state='ACTIVE' AND c.credential_epoch=NEW.workload_credential_epoch
    AND w.kind='WORKLOAD' AND w.state='ACTIVE' AND c.valid_from<=clock_timestamp()
    AND (c.valid_until IS NULL OR c.valid_until>clock_timestamp())
    AND c.public_key_digest IS DISTINCT FROM sha256(NEW.control_spki) AND c.public_key_digest IS DISTINCT FROM sha256(NEW.target_spki))
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS store_retirement_host_binding ON control.store_retirement_host;
CREATE TRIGGER store_retirement_host_binding BEFORE INSERT ON control.store_retirement_host FOR EACH ROW EXECUTE FUNCTION openpc.guard_store_retirement_host();

CREATE OR REPLACE FUNCTION openpc.guard_store_retirement_admission()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE attempt jsonb; host jsonb; actual_binding jsonb; policy control.retention_policy;
 previous control.store_retirement_admission; decision_digest bytea; count_decisions integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'DATA-6020-IMMUTABLE-ROW'; END IF;
 PERFORM openpc.assert_request_context(true);
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
  OR current_setting('openpc.operation_id')::uuid IS DISTINCT FROM NEW.operation_id
  OR openpc.current_action_intent_id()<>'ACT-EVIDENCE_DELETIONS_ADMIT_STORE_BATCH-V1'
  OR NOT pg_has_role(current_user,'openpc_control_runtime','USAGE') THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('evidence-lifecycle:'||NEW.participant_id::text,0));
 NEW.admitted_at:=clock_timestamp();
 IF NEW.dispatch_not_after_ms<=floor(extract(epoch from NEW.admitted_at)*1000)
  OR NEW.dispatch_not_after_ms>floor(extract(epoch from NEW.admitted_at)*1000)+60000
  THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 PERFORM openpc.verify_store_retirement_commit(NEW.participant_id,NEW.privacy_domain_id,NEW.host_digest,'SOURCE',
  sha256(NEW.attempt_wire||convert_to(NEW.source_binding_digest,'UTF8')||uuid_send(NEW.operation_id)
   ||uuid_send(NEW.approval_request_id)||int8send(NEW.dispatch_not_after_ms::bigint)),NEW.verification_nonce,NEW.verification_mac);
 attempt:=convert_from(NEW.attempt_wire,'UTF8')::jsonb;
 SELECT convert_from(host_wire,'UTF8')::jsonb INTO STRICT host FROM control.store_retirement_host
  WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND host_digest=NEW.host_digest
   AND valid_from_ms<=floor(extract(epoch from NEW.admitted_at)*1000) AND valid_until_ms>=NEW.dispatch_not_after_ms;
 SELECT * INTO STRICT policy FROM control.retention_policy WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND retention_policy_id=NEW.retention_policy_id AND active_until IS NULL;
 actual_binding:=openpc.store_retirement_source_binding(NEW.retention_policy_id,
  decode(NEW.source_binding->>'selectionWireHex','hex'),NEW.source_binding->'recordRefs');
 IF NEW.source_binding IS DISTINCT FROM actual_binding
  OR NEW.source_binding_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(actual_binding),'UTF8')),'hex')
  OR attempt->'selection' IS DISTINCT FROM convert_from(decode(actual_binding->>'selectionWireHex','hex'),'UTF8')::jsonb
  OR attempt->'scope' IS DISTINCT FROM host->'scope' OR attempt->>'store' IS DISTINCT FROM host->>'store'
  OR attempt->>'business_intent_id' IS DISTINCT FROM NEW.retirement_id::text OR attempt->>'attempt_id' IS DISTINCT FROM NEW.attempt_id::text
  OR attempt->>'selection_digest' IS DISTINCT FROM NEW.selection_digest
  OR NEW.attempt_digest IS DISTINCT FROM encode(sha256(convert_to('["OPENPC_STORE_RETIREMENT_ATTEMPT_V1",','UTF8')||NEW.attempt_wire||convert_to(']','UTF8')),'hex')
  OR NEW.lifecycle_revision::text IS DISTINCT FROM actual_binding->>'lifecycleRevision'
  OR attempt#>>'{governance,lifecycle_revision}' IS DISTINCT FROM NEW.lifecycle_revision::text
  OR attempt#>>'{governance,retention_policy_digest}' IS DISTINCT FROM substring(policy.policy_digest from 8)
  OR attempt#>>'{governance,archive_manifest_digest}' IS DISTINCT FROM actual_binding->>'archiveManifestDigest'
  OR attempt#>>'{governance,archive_acknowledgement_digest}' IS DISTINCT FROM actual_binding->>'archiveAcknowledgementDigest'
  OR attempt#>>'{governance,retention_not_before_ms}' IS DISTINCT FROM actual_binding->>'retentionNotBeforeMs'
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT count(*),decode(min(encode(d.decision_digest,'hex')),'hex') INTO count_decisions,decision_digest
  FROM control.approval_decision_record d JOIN control.approval_request a USING(participant_id,privacy_domain_id,approval_request_id)
  WHERE d.participant_id=NEW.participant_id AND d.privacy_domain_id=NEW.privacy_domain_id AND d.approval_request_id=NEW.approval_request_id
   AND d.decision='APPROVE' AND a.state='APPROVED' AND a.expires_at>NEW.admitted_at
   AND a.maker_principal_id<>d.approver_principal_id AND a.subject_digest=d.candidate_digest
   AND a.subject_version=d.aggregate_version;
 IF count_decisions<>1 OR attempt#>>'{governance,approval_digest}' IS DISTINCT FROM encode(decision_digest,'hex')
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF NEW.previous_attempt_id IS NULL THEN
  IF NEW.retirement_id<>NEW.attempt_id THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 ELSE
  SELECT a.* INTO STRICT previous FROM control.store_retirement_admission a JOIN control.store_retirement_outcome o
    USING(participant_id,privacy_domain_id,attempt_id)
   WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id AND a.attempt_id=NEW.previous_attempt_id
    AND o.state IN ('REJECTED_NO_EFFECT','CANCELLED_NO_EFFECT');
  IF previous.retirement_id<>NEW.retirement_id OR previous.host_digest<>NEW.host_digest OR previous.selection_digest<>NEW.selection_digest
   OR previous.approval_request_id=NEW.approval_request_id THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 END IF;
 -- A fresh idempotency key cannot disguise another unresolved business intent.
 IF EXISTS(SELECT 1 FROM control.store_retirement_admission a LEFT JOIN control.store_retirement_outcome o
   USING(participant_id,privacy_domain_id,attempt_id)
   WHERE a.participant_id=NEW.participant_id AND a.privacy_domain_id=NEW.privacy_domain_id AND a.host_digest=NEW.host_digest
    AND (o.state IS NULL OR o.state='APPLIED') AND EXISTS(SELECT 1
      FROM jsonb_array_elements(convert_from(a.attempt_wire,'UTF8')::jsonb->'selection'->'rows') old_row,
       jsonb_array_elements(attempt->'selection'->'rows') new_row WHERE old_row->>'candidate_id'=new_row->>'candidate_id'))
 THEN RAISE EXCEPTION 'PC-DATA-6007-UNRESOLVED-OR-APPLIED'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS store_retirement_admission_guard ON control.store_retirement_admission;
CREATE TRIGGER store_retirement_admission_guard BEFORE INSERT OR UPDATE OR DELETE ON control.store_retirement_admission
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_store_retirement_admission();



