DROP POLICY IF EXISTS operations_probe_source_read ON control.privacy_domain;
CREATE POLICY operations_probe_source_read ON control.privacy_domain FOR SELECT TO openpc_control_owner USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id) AND openpc.current_action_intent_id()='ACT-POLICY_READ_EFFECTIVE_ACCESS-V1');

