 OR (SELECT count(*) FROM jsonb_object_keys(p))<>6 OR p->>'schema' IS DISTINCT FROM 'pc.notification.delivery-signing.v1'
 OR item.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(p),'UTF8') OR item.preparation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
 OR p->'deliveryPreparation' IS DISTINCT FROM d.preparation OR p->'sourceClaims' IS DISTINCT FROM jsonb_build_object('environmentId',sm->'1','participantId',(sm->'2'->>'bytes')::uuid::text,'privacyDomainId',(sm->'3'->>'bytes')::uuid::text,'receiptId',(sm->'4'->>'bytes')::uuid::text,'operationId',(sm->'5'->>'bytes')::uuid::text,'notificationId',(sm->'6'->>'bytes')::uuid::text,'notificationOccurrenceId',(sm->'7'->>'bytes')::uuid::text,'payloadObjectId',(sm->'8'->>'bytes')::uuid::text,'keyPreparationId',(sm->'9'->>'bytes')::uuid::text,'sourceEventId',(sm->'10'->>'bytes')::uuid::text,'sourceDataDigest','sha256:'||(sm->'11'->>'bytes'),'sourceReceiptDigest','sha256:'||(sm->'12'->>'bytes'),'routingProfileDigest','sha256:'||(sm->'13'->>'bytes'),'workerProfileDigest','sha256:'||(sm->'14'->>'bytes'),'authoritySnapshotDigest','sha256:'||(sm->'15'->>'bytes'),'custodyDigest','sha256:'||(sm->'16'->>'bytes'),'endpointId',(sm->'17'->>'bytes')::uuid::text,'endpointRevision',sm->>'18','templateDigest','sha256:'||(sm->'19'->>'bytes'),'payloadDigest','sha256:'||(sm->'20'->>'bytes'),'encryptedObjectDigest','sha256:'||(sm->'21'->>'bytes'),'keyId','sha256:'||(sm->'22'->>'bytes'),'recordedAtMs',(sm->>'23')::numeric,'signerKeyId','sha256:'||(sm->'24'->>'bytes'),'occurrenceReceiptDigest','sha256:'||(sm->'25'->>'bytes'),'eventId',(sm->'26'->>'bytes')::uuid::text,'sourceId',(sm->'27'->>'bytes')::uuid::text,'sequence',sm->>'28','dataDigest','sha256:'||(sm->'29'->>'bytes'))
 OR p->'trust' IS DISTINCT FROM jsonb_build_object('signer',s.trust-ARRAY['schema','schemaDefinitionDigest','signerKeyId'],'worker',w.installation)
 OR s.worker_installation_digest IS DISTINCT FROM d.worker_installation_digest OR s.trust->>'workerProfileDigest' IS DISTINCT FROM w.signed_profile_digest
 OR s.trust->>'workerIssuerSpkiHex' IS DISTINCT FROM w.installation->'pins'->>'issuerSpkiHex'
 OR s.trust->>'purpose' IS DISTINCT FROM 'pc.cose.notification-delivery-started-receipt.v1' OR s.trust->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY'
 OR w.service_id<>'LS-NOTIFICATION' OR w.subscription_id<>'SUB-NOTIFICATIONDELIVERYREQUESTED-NOTIFICATION-V1'
 OR item.signing_attempt_id IN (d.operation_id,d.attempt_id,d.source_operation_id,(sm->'4'->>'bytes')::uuid)
 OR item.signing_attempt_id::text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
 OR (r->>'payloadHex' ~ '^(?:[0-9a-f]{2})+$') IS DISTINCT FROM true OR length(r->>'payloadHex') NOT BETWEEN 2 AND 131072
 OR r IS DISTINCT FROM jsonb_build_object('schemaVersion',1,'method','SIGN_NOTIFICATION_DELIVERY_STARTED','signerInstallationDigest',s.trust_digest,'providerId',s.trust->>'providerId','purpose',s.trust->>'purpose','secretClass',s.trust->>'secretClass','reference',s.trust->>'secretReference','version',s.trust->>'secretVersion','keyEpoch',s.trust->>'keyEpoch','signerKeyId',s.signer_id,'environmentId',s.trust->>'environmentId','participantId',item.participant_id::text,'privacyDomainId',item.privacy_domain_id::text,'workloadCredentialId',s.trust->>'workloadCredentialId','workloadEpoch',s.trust->>'workloadEpoch','workerInstallationDigest',w.installation_digest,'workerProfileDigest',w.signed_profile_digest,'signingAttemptId',item.signing_attempt_id::text,'operationId',item.operation_id::text,'deliveryAttemptId',d.attempt_id::text,'deliveryPreparationDigest',d.preparation_digest,'payloadHex',r->>'payloadHex')
 OR item.request_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to('pc.notification.receipt-provider-request.v1','UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(r),'UTF8')),'hex')
 OR p->>'requestDigest' IS DISTINCT FROM item.request_digest
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-ORIGINAL'; END IF;
 m:=openpc.business_cbor(decode(r->>'payloadHex','hex'));
 IF m IS DISTINCT FROM jsonb_build_object('0',jsonb_build_object('bytes','16d25d491ab1eeef18d69b6cc55062f2a5d0d83e9e58475252582de0c8dea7d0'),'1',sm->'1','2',sm->'2','3',sm->'3','4',openpc.business_uuid((item.signing_attempt_id::text)::uuid),'5',openpc.business_uuid((item.operation_id::text)::uuid),'6',openpc.business_uuid((d.preparation->'attempt'->>'attemptId')::uuid),'7',sm->'7','8',sm->'8','9',sm->'9','10',openpc.business_uuid((d.source_event_id::text)::uuid),'11',jsonb_build_object('bytes',substring('sha256:'||(sm->'29'->>'bytes') from 8)),'12',jsonb_build_object('bytes',substring(proof.receipt_digest from 8)),'13',sm->'13','14',jsonb_build_object('bytes',substring(w.signed_profile_digest from 8)),'15',jsonb_build_object('bytes',substring(d.preparation->>'authorityDigest' from 8)),'16',sm->'17','17',sm->'18','18',sm->'19','19',sm->'20','20',sm->'21','21',sm->'22','22',jsonb_build_object('bytes',substring(d.preparation->'channel'->>'signedProfileDigest' from 8)),'23',jsonb_build_object('bytes',substring(d.preparation->>'attemptDigest' from 8)),'24',jsonb_build_object('bytes',substring(d.preparation->>'contextDigest' from 8)),'25',to_jsonb((d.attempt_number)::numeric),'26',to_jsonb((d.preparation->'attempt'->>'startedAtMs')::numeric),'27',to_jsonb((d.preparation->'attempt'->>'deadlineAtMs')::numeric),'28',to_jsonb((d.delivery_revision)::numeric),'29',jsonb_build_object('bytes',substring(d.preparation->>'beforeStateDigest' from 8)),'30',jsonb_build_object('bytes',substring(d.preparation->>'plannedAfterStateDigest' from 8)),'31',jsonb_build_object('bytes',substring(s.signer_id from 8)))
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-NATIVE-PAYLOAD'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_signing_current(item control.notification_delivery_signing) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p jsonb:=item.preparation->'deliveryPreparation';d control.notification_delivery%ROWTYPE;
 w control.installed_notification_worker%ROWTYPE;s control.notification_receipt_signer_installation%ROWTYPE;
 i control.installed_notification_channel%ROWTYPE;ep control.notification_endpoint%ROWTYPE;o control.notification_occurrence%ROWTYPE;
 rt control.installed_notification_routing%ROWTYPE;wm jsonb;cm jsonb;actual record;now_ms numeric;lock_name text;before jsonb;
BEGIN
 PERFORM openpc.check_notification_delivery_signing_original(item);
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=p->'source'->'worker'->>'installationDigest';
 SELECT * INTO STRICT s FROM control.notification_receipt_signer_installation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND trust_digest=item.signer_installation_digest;
 SELECT * INTO STRICT o FROM control.notification_occurrence WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=(p->'source'->>'notificationOccurrenceId')::uuid;
 SELECT * INTO STRICT ep FROM control.notification_endpoint WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND endpoint_id=o.endpoint_id FOR SHARE;
 SELECT * INTO STRICT i FROM control.installed_notification_channel WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND credential_ref=o.credential_ref;
 SELECT * INTO STRICT rt FROM control.installed_notification_routing WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND signed_profile_digest=w.routing_profile_digest;
 FOREACH lock_name IN ARRAY ARRAY['evidence-lifecycle:'||item.participant_id::text,'notification-worker:'||item.participant_id::text||':'||item.privacy_domain_id::text,
  'notification-receipt-signer:'||item.participant_id::text||':'||item.privacy_domain_id::text,'notification-installation:'||item.participant_id::text||':'||item.privacy_domain_id::text,
  'notification-routing:'||item.participant_id::text||':'||item.privacy_domain_id::text||':'||rt.profile_id::text] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1
   AND l.mode=CASE WHEN lock_name LIKE 'evidence-lifecycle:%' THEN 'ExclusiveLock' ELSE 'ShareLock' END)
  THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-FENCE'; END IF;
 END LOOP;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 wm:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));cm:=openpc.business_cbor(decode(i.channel_signed->>'payloadHex','hex'));
 IF w.state<>'ACTIVE' OR s.state<>'ACTIVE' OR i.state<>'ACTIVE' OR ep.state<>'ACTIVE' OR rt.state<>'ACTIVE'
 OR now_ms<(p->'attempt'->>'startedAtMs')::numeric OR now_ms>=(p->'attempt'->>'deadlineAtMs')::numeric OR now_ms>=(p->>'authorityValidUntilMs')::numeric
 OR now_ms<(wm->>'6')::numeric OR now_ms>=(wm->>'7')::numeric
 OR now_ms*1000000<(s.trust->>'validFromNs')::numeric OR now_ms*1000000>=(s.trust->>'validUntilNs')::numeric
 OR now_ms<(cm->>'6')::numeric OR now_ms>=(cm->>'7')::numeric
 OR now_ms<(openpc.business_cbor(decode(rt.installation->'signed'->>'payloadHex','hex'))->>'6')::numeric
 OR now_ms>=(openpc.business_cbor(decode(rt.installation->'signed'->>'payloadHex','hex'))->>'7')::numeric
 OR i.credential->>'state'<>'ACTIVE' OR now_ms<(i.credential->>'validFromMs')::numeric OR now_ms>=(i.credential->>'validUntilMs')::numeric
 OR ep.revision IS DISTINCT FROM o.endpoint_revision OR ep.verification_id IS DISTINCT FROM o.verification_id OR ep.credential_ref IS DISTINCT FROM o.credential_ref
 OR ep.channel IS DISTINCT FROM o.channel OR ep.destination_ref IS DISTINCT FROM o.destination_ref OR ep.channel_profile_digest IS DISTINCT FROM o.channel_profile_digest
 OR i.channel_profile_digest IS DISTINCT FROM o.channel_profile_digest OR i.channel IS DISTINCT FROM o.channel OR i.destination_ref IS DISTINCT FROM o.destination_ref
 OR rt.endpoint_id IS DISTINCT FROM o.endpoint_id OR p->'channel' IS DISTINCT FROM jsonb_build_object('claims',jsonb_build_object('environmentId',cm->'1','participantId',(cm->'2'->>'bytes')::uuid::text,'privacyDomainId',(cm->'3'->>'bytes')::uuid::text,'profileId',(cm->'4'->>'bytes')::uuid::text,'revision',cm->>'5','validFromMs',(cm->>'6')::numeric,'validUntilMs',(cm->>'7')::numeric,'transportProfileDigest','sha256:'||(cm->'8'->>'bytes'),'receiptSignerSpki',cm->'9'->>'bytes','issuerKeyId','sha256:'||(cm->'10'->>'bytes')),'transport',i.channel_signed->'transport','signedProfileDigest',i.channel_profile_digest)
 OR NOT EXISTS(SELECT 1 FROM control.notification_endpoint_verification v WHERE v.participant_id=ep.participant_id AND v.privacy_domain_id=ep.privacy_domain_id AND v.verification_id=ep.verification_id
  AND v.endpoint_id=ep.endpoint_id AND v.endpoint_revision=ep.revision AND v.channel=ep.channel AND v.destination_ref=ep.destination_ref AND v.channel_profile_digest=ep.channel_profile_digest AND v.credential_ref=ep.credential_ref)
 OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal a USING(participant_id,principal_id) JOIN control.participant t USING(participant_id) JOIN control.privacy_domain v USING(participant_id)
  WHERE c.participant_id=item.participant_id AND c.credential_id=w.workload_credential_id AND a.principal_id=w.principal_id AND v.privacy_domain_id=item.privacy_domain_id
  AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch::text=p->>'workerEpoch' AND c.audience=w.installation->'pins'->>'workloadId'
  AND 'sha256:'||encode(c.public_key_digest,'hex')=w.installation->'pins'->>'workloadKeyDigest' AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
  AND a.state='ACTIVE' AND a.kind='WORKLOAD' AND t.state='ACTIVE' AND v.state='ACTIVE')
 OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal a USING(participant_id,principal_id) WHERE c.participant_id=item.participant_id AND c.credential_id=i.workload_credential_id
  AND a.principal_id=i.principal_id AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch=i.workload_epoch AND c.audience=i.workload_id
  AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp() AND a.state='ACTIVE' AND a.kind='WORKLOAD')
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-CURRENT'; END IF;
 SELECT * INTO STRICT actual FROM openpc.current_notification_delivery_limit(item.preparation->'sourceClaims'->>'environmentId');
 IF actual.generation_id::text IS DISTINCT FROM p->>'generationId' OR actual.effective_digest IS DISTINCT FROM p->>'effectiveDigest' OR to_jsonb(actual.configured_limit) IS DISTINCT FROM p->'configuredLimit' OR actual.configured_limit<=0
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-GENERATION'; END IF;
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=o.notification_occurrence_id FOR UPDATE;
 before:=jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,
 'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested,'revision',d.revision::text,
 'deliveryRequestEventId',d.delivery_request_event_id::text,'deliveryRequestOperationId',d.delivery_request_operation_id::text,'budgetEnvironmentId',d.budget_environment_id,'budgetGenerationId',d.budget_generation_id::text,
 'budgetEffectiveDigest',d.budget_effective_digest,'budgetConfiguredLimit',d.budget_configured_limit,'budgetWorkerInstallationDigest',d.budget_worker_installation_digest);
 IF p->'before' IS DISTINCT FROM before OR d.cancel_requested OR d.state NOT IN ('PENDING','RETRY_WAIT') OR d.attempt_count>=least(d.attempt_limit,actual.configured_limit,6)
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-STATE'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_delivery_signing() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE o jsonb;payload bytea;cose bytea;
BEGIN
 PERFORM openpc.check_notification_delivery_signing_original(NEW);
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-PREPARED'; END IF;
  PERFORM openpc.check_notification_delivery_signing_current(NEW);RETURN NEW;
 END IF;
 IF to_jsonb(NEW)-ARRAY['state','dispatch_token','dispatched_at_ms','observation','observation_bytes','observation_digest'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','dispatch_token','dispatched_at_ms','observation','observation_bytes','observation_digest']
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-IMMUTABLE'; END IF;
 IF OLD.state='PREPARED' AND NEW.state='DISPATCHED' THEN
  IF NEW.dispatch_token IS NULL OR NEW.dispatched_at_ms<floor(extract(epoch from transaction_timestamp())*1000) OR NEW.dispatched_at_ms>floor(extract(epoch from clock_timestamp())*1000)
  THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-DISPATCH'; END IF;
  PERFORM openpc.check_notification_delivery_signing_current(NEW);RETURN NEW;
 END IF;
 IF OLD.state<>'DISPATCHED' OR NEW.state<>'OBSERVED' OR NEW.dispatch_token IS DISTINCT FROM OLD.dispatch_token OR NEW.dispatched_at_ms IS DISTINCT FROM OLD.dispatched_at_ms
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-ONCE'; END IF;
 o:=NEW.observation;
 IF jsonb_typeof(o) IS DISTINCT FROM 'object' OR o-ARRAY['schemaVersion','providerId','signingAttemptId','requestDigest','recordedAtMs','outcome','reason','coseHex'] IS DISTINCT FROM '{}'::jsonb
 OR (SELECT count(*) FROM jsonb_object_keys(o))<>8 OR o->'schemaVersion' IS DISTINCT FROM '1'::jsonb
 OR o->>'providerId' IS DISTINCT FROM NEW.preparation->'request'->>'providerId' OR o->>'signingAttemptId' IS DISTINCT FROM NEW.signing_attempt_id::text OR o->>'requestDigest' IS DISTINCT FROM NEW.request_digest
 OR NEW.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(o),'UTF8') OR NEW.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(o),'UTF8')),'hex')
 OR jsonb_typeof(o->'recordedAtMs') IS DISTINCT FROM 'number' OR (o->>'recordedAtMs')::numeric NOT BETWEEN 0 AND 9007199254740991 OR trunc((o->>'recordedAtMs')::numeric)<>(o->>'recordedAtMs')::numeric
 THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-OBSERVATION'; END IF;
 IF o->>'outcome'='REJECTED' THEN
  IF o->'coseHex' IS DISTINCT FROM 'null'::jsonb OR (o->>'reason' IN ('REVOKED','EXPIRED','WRONG_SCOPE','INVALID_REQUEST','ATTEMPT_CONFLICT','KEY_UNAVAILABLE')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-REJECTION'; END IF;
 ELSE
  IF o->>'outcome' IS DISTINCT FROM 'SIGNED' OR o->'reason' IS DISTINCT FROM 'null'::jsonb OR (o->>'coseHex' ~ '^(?:[0-9a-f]{2})+$') IS DISTINCT FROM true
  OR length(o->>'coseHex') NOT BETWEEN 130 AND 133120 OR (o->>'recordedAtMs')::numeric<(NEW.preparation->'deliveryPreparation'->'attempt'->>'startedAtMs')::numeric
  OR (o->>'recordedAtMs')::numeric>=(NEW.preparation->'deliveryPreparation'->'attempt'->>'deadlineAtMs')::numeric
  THEN RAISE EXCEPTION 'NOTIFICATION-SIGNING-SIGNATURE'; END IF;
  payload:=decode(NEW.preparation->'request'->>'payloadHex','hex');cose:=decode(o->>'coseHex','hex');
  PERFORM openpc.archive_cose_binding(payload,cose,NEW.preparation->'request'->>'signerKeyId',24021,358);
 END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.deny_notification_delivery_signing_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'NOTIFICATION-SIGNING-IMMUTABLE'; END $$;
DROP TRIGGER IF EXISTS notification_delivery_signing_guard ON control.notification_delivery_signing;
CREATE TRIGGER notification_delivery_signing_guard BEFORE INSERT OR UPDATE ON control.notification_delivery_signing FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_signing();
DROP TRIGGER IF EXISTS notification_delivery_signing_immutable ON control.notification_delivery_signing;
CREATE TRIGGER notification_delivery_signing_immutable BEFORE DELETE OR TRUNCATE ON control.notification_delivery_signing FOR EACH STATEMENT EXECUTE FUNCTION openpc.deny_notification_delivery_signing_mutation();
REVOKE ALL ON FUNCTION openpc.assert_notification_delivery_signing_owner(),openpc.check_notification_delivery_signing_original(control.notification_delivery_signing),openpc.check_notification_delivery_signing_current(control.notification_delivery_signing),openpc.guard_notification_delivery_signing(),openpc.deny_notification_delivery_signing_mutation() FROM PUBLIC;


CREATE OR REPLACE FUNCTION openpc.assert_notification_delivery_start_atomic_guards() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE table_name text; trigger_name text; function_name text;
BEGIN
 FOREACH table_name IN ARRAY ARRAY['notification_delivery_start','notification_delivery_attempt','notification_delivery_dispatch_intent'] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=('control.'||table_name)::regclass AND relrowsecurity AND relforcerowsecurity)
  THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
  trigger_name:=table_name||'_atomic_guard'; function_name:='openpc.guard_'||table_name||'_atomic()';
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('control.'||table_name)::regclass AND tgname=trigger_name AND tgtype=7 AND tgenabled IN ('O','A') AND tgfoid=function_name::regprocedure)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('control.'||table_name)::regclass AND tgname=table_name||'_atomic_immutable' AND tgtype=CASE WHEN table_name='notification_delivery_dispatch_intent' THEN 42 ELSE 58 END AND tgenabled IN ('O','A') AND tgfoid='openpc.deny_notification_delivery_start_atomic_mutation()'::regprocedure)
  OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=('control.'||table_name)::regclass AND tgname=table_name||'_complete' AND tgtype=CASE WHEN table_name='notification_delivery_dispatch_intent' THEN 21 ELSE 5 END AND tgenabled IN ('O','A') AND tgdeferrable AND tginitdeferred AND tgfoid='openpc.guard_notification_delivery_start_complete()'::regprocedure)
  THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_dispatch_intent'::regclass AND tgname='notification_delivery_dispatch_claim_guard' AND tgtype=19 AND tgenabled IN ('O','A') AND tgfoid='openpc.guard_notification_delivery_dispatch_claim()'::regprocedure) THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery'::regclass AND tgname='notification_delivery_start_complete' AND tgtype=17 AND tgenabled IN ('O','A') AND tgdeferrable AND tginitdeferred AND tgfoid='openpc.guard_notification_delivery_start_complete()'::regprocedure)
 THEN RAISE EXCEPTION 'NOTIFICATION-START-OWNER'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.assert_notification_delivery_start_atomic_owner() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_notification_delivery_signing_owner();
 PERFORM openpc.assert_notification_delivery_start_atomic_guards();
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_start_original(item control.notification_delivery_start) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE signing control.notification_delivery_signing%ROWTYPE;p jsonb;t jsonb:=item.transition;m jsonb;expected jsonb;
BEGIN
 IF item.participant_id IS DISTINCT FROM openpc.current_participant_id() OR item.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'NOTIFICATION-START-SCOPE'; END IF;
 SELECT * INTO STRICT signing FROM control.notification_delivery_signing WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=item.operation_id;
 p:=signing.preparation->'deliveryPreparation';m:=openpc.business_cbor(item.receipt_payload);
 IF signing.state<>'OBSERVED' OR signing.observation->>'outcome' IS DISTINCT FROM 'SIGNED'
 OR item.receipt_id IS DISTINCT FROM signing.signing_attempt_id OR item.attempt_id::text IS DISTINCT FROM p->'attempt'->>'attemptId'
 OR item.notification_occurrence_id::text IS DISTINCT FROM p->'source'->>'notificationOccurrenceId' OR item.payload_digest IS DISTINCT FROM p->'attempt'->>'payloadDigest'
 OR item.delivery_revision::text IS DISTINCT FROM p->'before'->>'revision' OR item.source_operation_id::text IS DISTINCT FROM p->>'sourceOperationId'
 OR item.worker_installation_digest IS DISTINCT FROM p->'source'->'worker'->>'installationDigest'
 OR item.receipt_payload IS DISTINCT FROM decode(signing.preparation->'request'->>'payloadHex','hex')
 OR item.cose_sign1 IS DISTINCT FROM decode(signing.observation->>'coseHex','hex')
 OR item.receipt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(item.receipt_payload),'hex')
 OR item.transition_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(t),'UTF8') OR item.transition_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(t),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'NOTIFICATION-START-ORIGINAL'; END IF;
 expected:=jsonb_build_object('schema','pc.notification.delivery-start-transition.v1','sourceOperationId',p->'sourceOperationId',
 'workerInstallation',signing.preparation->'trust'->'worker','workerInstallationDigest',p->'source'->'worker'->'installationDigest','workerAuthorityDigest',p->'authorityDigest',
 'receipt',jsonb_build_object('environmentId',m->'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'receiptId',(m->'4'->>'bytes')::uuid::text,'operationId',(m->'5'->>'bytes')::uuid::text,'attemptId',(m->'6'->>'bytes')::uuid::text,'notificationOccurrenceId',(m->'7'->>'bytes')::uuid::text,'payloadObjectId',(m->'8'->>'bytes')::uuid::text,'keyPreparationId',(m->'9'->>'bytes')::uuid::text,'sourceEventId',(m->'10'->>'bytes')::uuid::text,'sourceDataDigest','sha256:'||(m->'11'->>'bytes'),'sourceReceiptDigest','sha256:'||(m->'12'->>'bytes'),'routingProfileDigest','sha256:'||(m->'13'->>'bytes'),'workerProfileDigest','sha256:'||(m->'14'->>'bytes'),'authoritySnapshotDigest','sha256:'||(m->'15'->>'bytes'),'endpointId',(m->'16'->>'bytes')::uuid::text,'endpointRevision',m->>'17','templateDigest','sha256:'||(m->'18'->>'bytes'),'payloadDigest','sha256:'||(m->'19'->>'bytes'),'encryptedObjectDigest','sha256:'||(m->'20'->>'bytes'),'keyId','sha256:'||(m->'21'->>'bytes'),'signedChannelProfileDigest','sha256:'||(m->'22'->>'bytes'),'attemptDigest','sha256:'||(m->'23'->>'bytes'),'contextDigest','sha256:'||(m->'24'->>'bytes'),'attemptNumber',(m->>'25')::numeric,'startedAtMs',(m->>'26')::numeric,'deadlineAtMs',(m->>'27')::numeric,'deliveryRevision',m->>'28','beforeStateDigest','sha256:'||(m->'29'->>'bytes'),'afterStateDigest','sha256:'||(m->'30'->>'bytes'),'signerKeyId','sha256:'||(m->'31'->>'bytes')),'source',signing.preparation->'sourceClaims','channel',p->'channel','attempt',p->'attempt','context',p->'context',
 'before',(p->'before')-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest'],'after',p->'plannedAfter','configuredLimit',p->'configuredLimit','payloadHex',encode(item.receipt_payload,'hex'),'coseHex',encode(item.cose_sign1,'hex'));
 IF t IS DISTINCT FROM expected THEN RAISE EXCEPTION 'NOTIFICATION-START-TRANSITION'; END IF;
 PERFORM openpc.archive_cose_binding(item.receipt_payload,item.cose_sign1,signing.preparation->'request'->>'signerKeyId',24021,358);
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_delivery_start_atomic() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE signing control.notification_delivery_signing%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_delivery_start_atomic_owner();
 PERFORM openpc.check_notification_delivery_start_original(NEW);
 SELECT * INTO STRICT signing FROM control.notification_delivery_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.operation_id FOR UPDATE;
 PERFORM openpc.check_notification_delivery_signing_current(signing);
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_delivery_attempt_atomic() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE start control.notification_delivery_start%ROWTYPE;p jsonb;
BEGIN
 PERFORM openpc.assert_notification_delivery_start_atomic_owner();
 SELECT * INTO STRICT start FROM control.notification_delivery_start WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.start_operation_id;
 PERFORM openpc.check_notification_delivery_start_original(start);p:=start.transition;
 IF NEW.attempt_id IS DISTINCT FROM start.attempt_id OR NEW.notification_occurrence_id IS DISTINCT FROM start.notification_occurrence_id OR NEW.payload_digest IS DISTINCT FROM start.payload_digest
 OR to_jsonb(NEW.attempt_number) IS DISTINCT FROM p->'attempt'->'attemptNumber' OR to_jsonb(NEW.started_at_ms) IS DISTINCT FROM p->'attempt'->'startedAtMs'
 OR NEW.worker_credential_id::text IS DISTINCT FROM p->'context'->>'authorizationContextId' OR NEW.worker_credential_epoch::numeric IS DISTINCT FROM (p->'context'->>'authorizationContextEpoch')::numeric
 THEN RAISE EXCEPTION 'NOTIFICATION-START-ATTEMPT'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_dispatch_intent_original(item control.notification_delivery_dispatch_intent) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE start control.notification_delivery_start%ROWTYPE;
BEGIN
 SELECT * INTO STRICT start FROM control.notification_delivery_start WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=item.operation_id;
 PERFORM openpc.check_notification_delivery_start_original(start);
 IF item.attempt_id IS DISTINCT FROM start.attempt_id OR item.notification_occurrence_id IS DISTINCT FROM start.notification_occurrence_id OR item.payload_digest IS DISTINCT FROM start.payload_digest
 OR item.delivery_revision IS DISTINCT FROM start.delivery_revision+1 OR item.receipt_digest IS DISTINCT FROM start.receipt_digest
 OR ((item.state='PENDING' AND item.claim_token IS NULL AND item.claimed_at_ms IS NULL)
  OR (item.state='CLAIMED' AND item.claim_token IS NOT NULL AND item.claim_token ~ '^[0-9a-f]{64}$' AND item.claimed_at_ms IS NOT NULL AND item.claimed_at_ms BETWEEN 0 AND 9007199254740991
   AND item.claimed_at_ms >= (start.transition->'attempt'->>'startedAtMs')::numeric AND item.claimed_at_ms < (start.transition->'attempt'->>'deadlineAtMs')::numeric)) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'NOTIFICATION-START-INTENT'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_delivery_dispatch_intent_atomic() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_notification_delivery_start_atomic_owner();
 PERFORM openpc.check_notification_delivery_dispatch_intent_original(NEW);
 IF NEW.state<>'PENDING' THEN RAISE EXCEPTION 'NOTIFICATION-START-INTENT'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_start_projection(before_row control.notification_delivery,after_row control.notification_delivery) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE start control.notification_delivery_start%ROWTYPE;signing control.notification_delivery_signing%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_delivery_start_atomic_owner();
 SELECT * INTO STRICT start FROM control.notification_delivery_start WHERE participant_id=before_row.participant_id AND privacy_domain_id=before_row.privacy_domain_id AND notification_occurrence_id=before_row.notification_occurrence_id AND delivery_revision=before_row.revision;
 PERFORM openpc.check_notification_delivery_start_original(start);
 SELECT * INTO STRICT signing FROM control.notification_delivery_signing WHERE participant_id=start.participant_id AND privacy_domain_id=start.privacy_domain_id AND operation_id=start.operation_id;
 PERFORM openpc.check_notification_delivery_signing_current(signing);
 IF jsonb_build_object('participantId',before_row.participant_id::text,'privacyDomainId',before_row.privacy_domain_id::text,'notificationOccurrenceId',before_row.notification_occurrence_id::text,'payloadDigest',before_row.payload_digest,'state',before_row.state,'attemptCount',before_row.attempt_count,'attemptLimit',before_row.attempt_limit,'nextAttemptAtMs',before_row.next_attempt_at_ms,'lastStartedAtMs',before_row.last_started_at_ms,'cancelRequested',before_row.cancel_requested) IS DISTINCT FROM start.transition->'before' OR jsonb_build_object('participantId',after_row.participant_id::text,'privacyDomainId',after_row.privacy_domain_id::text,'notificationOccurrenceId',after_row.notification_occurrence_id::text,'payloadDigest',after_row.payload_digest,'state',after_row.state,'attemptCount',after_row.attempt_count,'attemptLimit',after_row.attempt_limit,'nextAttemptAtMs',after_row.next_attempt_at_ms,'lastStartedAtMs',after_row.last_started_at_ms,'cancelRequested',after_row.cancel_requested) IS DISTINCT FROM start.transition->'after'
 OR after_row.revision IS DISTINCT FROM before_row.revision+1
 OR to_jsonb(after_row)-ARRAY['state','attempt_count','last_started_at_ms','next_attempt_at_ms','revision'] IS DISTINCT FROM to_jsonb(before_row)-ARRAY['state','attempt_count','last_started_at_ms','next_attempt_at_ms','revision']
 THEN RAISE EXCEPTION 'NOTIFICATION-START-PROJECTION'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_start_complete(operation uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE start control.notification_delivery_start%ROWTYPE;a control.notification_delivery_attempt%ROWTYPE;d control.notification_delivery%ROWTYPE;i control.notification_delivery_dispatch_intent%ROWTYPE;
BEGIN
 -- Deferred checks run after the application restores its original action. All
 -- live admissions ran before mutation; this check grants no fresh authority.
 SELECT * INTO STRICT start FROM control.notification_delivery_start WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND operation_id=operation;
 PERFORM openpc.check_notification_delivery_start_original(start);
 SELECT * INTO STRICT a FROM control.notification_delivery_attempt WHERE participant_id=start.participant_id AND privacy_domain_id=start.privacy_domain_id AND start_operation_id=start.operation_id;
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=start.participant_id AND privacy_domain_id=start.privacy_domain_id AND notification_occurrence_id=start.notification_occurrence_id;
 SELECT * INTO STRICT i FROM control.notification_delivery_dispatch_intent WHERE participant_id=start.participant_id AND privacy_domain_id=start.privacy_domain_id AND operation_id=start.operation_id;
 IF a.attempt_id IS DISTINCT FROM start.attempt_id OR a.notification_occurrence_id IS DISTINCT FROM start.notification_occurrence_id OR a.payload_digest IS DISTINCT FROM start.payload_digest
 OR to_jsonb(a.attempt_number) IS DISTINCT FROM start.transition->'attempt'->'attemptNumber' OR to_jsonb(a.started_at_ms) IS DISTINCT FROM start.transition->'attempt'->'startedAtMs'
 OR a.worker_credential_id::text IS DISTINCT FROM start.transition->'context'->>'authorizationContextId' OR a.worker_credential_epoch::numeric IS DISTINCT FROM (start.transition->'context'->>'authorizationContextEpoch')::numeric
 OR d.revision IS DISTINCT FROM start.delivery_revision+1 OR jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested) IS DISTINCT FROM start.transition->'after'
 OR i.attempt_id IS DISTINCT FROM start.attempt_id OR i.notification_occurrence_id IS DISTINCT FROM start.notification_occurrence_id OR i.payload_digest IS DISTINCT FROM start.payload_digest
 OR i.delivery_revision IS DISTINCT FROM d.revision OR i.receipt_digest IS DISTINCT FROM start.receipt_digest
 THEN RAISE EXCEPTION 'NOTIFICATION-START-INCOMPLETE'; END IF;
 PERFORM openpc.check_notification_delivery_dispatch_intent_original(i);
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_delivery_start_complete() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE operation uuid;
BEGIN
 IF TG_TABLE_NAME='notification_delivery' THEN
  IF NEW.state<>'STARTED' OR OLD.state='STARTED' THEN RETURN NULL; END IF;
  SELECT operation_id INTO STRICT operation FROM control.notification_delivery_start WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND notification_occurrence_id=NEW.notification_occurrence_id AND delivery_revision=OLD.revision;
 ELSIF TG_TABLE_NAME='notification_delivery_attempt' THEN operation:=NEW.start_operation_id;
 ELSE operation:=NEW.operation_id;
 END IF;
 PERFORM openpc.check_notification_delivery_start_complete(operation);RETURN NULL;
END $$;
CREATE OR REPLACE FUNCTION openpc.deny_notification_delivery_start_atomic_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'NOTIFICATION-START-IMMUTABLE'; END $$;

DROP TRIGGER IF EXISTS notification_delivery_start_atomic_guard ON control.notification_delivery_start;
CREATE TRIGGER notification_delivery_start_atomic_guard BEFORE INSERT ON control.notification_delivery_start FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_start_atomic();
DROP TRIGGER IF EXISTS notification_delivery_start_atomic_immutable ON control.notification_delivery_start;
CREATE TRIGGER notification_delivery_start_atomic_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON control.notification_delivery_start FOR EACH STATEMENT EXECUTE FUNCTION openpc.deny_notification_delivery_start_atomic_mutation();
DROP TRIGGER IF EXISTS notification_delivery_start_complete ON control.notification_delivery_start;
CREATE CONSTRAINT TRIGGER notification_delivery_start_complete AFTER INSERT ON control.notification_delivery_start DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_start_complete();

DROP TRIGGER IF EXISTS notification_delivery_attempt_atomic_guard ON control.notification_delivery_attempt;
CREATE TRIGGER notification_delivery_attempt_atomic_guard BEFORE INSERT ON control.notification_delivery_attempt FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_attempt_atomic();
DROP TRIGGER IF EXISTS notification_delivery_attempt_atomic_immutable ON control.notification_delivery_attempt;
CREATE TRIGGER notification_delivery_attempt_atomic_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON control.notification_delivery_attempt FOR EACH STATEMENT EXECUTE FUNCTION openpc.deny_notification_delivery_start_atomic_mutation();
DROP TRIGGER IF EXISTS notification_delivery_attempt_complete ON control.notification_delivery_attempt;
CREATE CONSTRAINT TRIGGER notification_delivery_attempt_complete AFTER INSERT ON control.notification_delivery_attempt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_start_complete();

DROP TRIGGER IF EXISTS notification_delivery_dispatch_intent_atomic_guard ON control.notification_delivery_dispatch_intent;
CREATE TRIGGER notification_delivery_dispatch_intent_atomic_guard BEFORE INSERT ON control.notification_delivery_dispatch_intent FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_dispatch_intent_atomic();
DROP TRIGGER IF EXISTS notification_delivery_dispatch_intent_atomic_immutable ON control.notification_delivery_dispatch_intent;
CREATE TRIGGER notification_delivery_dispatch_intent_atomic_immutable BEFORE DELETE OR TRUNCATE ON control.notification_delivery_dispatch_intent FOR EACH STATEMENT EXECUTE FUNCTION openpc.deny_notification_delivery_start_atomic_mutation();
DROP TRIGGER IF EXISTS notification_delivery_dispatch_intent_complete ON control.notification_delivery_dispatch_intent;
CREATE CONSTRAINT TRIGGER notification_delivery_dispatch_intent_complete AFTER INSERT OR UPDATE ON control.notification_delivery_dispatch_intent DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_start_complete();
DROP TRIGGER IF EXISTS notification_delivery_start_complete ON control.notification_delivery;
CREATE CONSTRAINT TRIGGER notification_delivery_start_complete AFTER UPDATE ON control.notification_delivery DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_start_complete();
REVOKE ALL ON FUNCTION openpc.assert_notification_delivery_start_atomic_guards(),openpc.assert_notification_delivery_start_atomic_owner(),openpc.check_notification_delivery_start_original(control.notification_delivery_start),openpc.guard_notification_delivery_start_atomic(),openpc.guard_notification_delivery_attempt_atomic(),openpc.guard_notification_delivery_dispatch_intent_atomic(),openpc.check_notification_delivery_dispatch_intent_original(control.notification_delivery_dispatch_intent),openpc.check_notification_delivery_start_projection(control.notification_delivery,control.notification_delivery),openpc.check_notification_delivery_start_complete(uuid),openpc.guard_notification_delivery_start_complete(),openpc.deny_notification_delivery_start_atomic_mutation() FROM PUBLIC;


CREATE OR REPLACE FUNCTION openpc.assert_notification_delivery_dispatch_owner() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_notification_delivery_start_atomic_owner();
 IF current_setting('openpc.action_intent_id',true) IS DISTINCT FROM 'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-OWNER'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_dispatch_current(operation uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE item control.notification_delivery_signing%ROWTYPE;start control.notification_delivery_start%ROWTYPE;p jsonb;d control.notification_delivery%ROWTYPE;
 w control.installed_notification_worker%ROWTYPE;
 i control.installed_notification_channel%ROWTYPE;ep control.notification_endpoint%ROWTYPE;o control.notification_occurrence%ROWTYPE;
 rt control.installed_notification_routing%ROWTYPE;wm jsonb;cm jsonb;actual record;now_ms numeric;lock_name text;after_state jsonb;k control.evidence_kms_attempt%ROWTYPE;ki control.evidence_kms_installation%ROWTYPE;status control.evidence_kms_exchange%ROWTYPE;km jsonb;
BEGIN
 PERFORM openpc.assert_notification_delivery_dispatch_owner();
 SELECT * INTO STRICT start FROM control.notification_delivery_start WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND operation_id=operation;
 PERFORM openpc.check_notification_delivery_start_original(start);
 SELECT * INTO STRICT item FROM control.notification_delivery_signing WHERE participant_id=start.participant_id AND privacy_domain_id=start.privacy_domain_id AND operation_id=operation;
 PERFORM openpc.check_notification_delivery_signing_original(item);p:=item.preparation->'deliveryPreparation';
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=p->'source'->'worker'->>'installationDigest';
 SELECT * INTO STRICT o FROM control.notification_occurrence WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=(p->'source'->>'notificationOccurrenceId')::uuid;
 SELECT * INTO STRICT ep FROM control.notification_endpoint WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND endpoint_id=o.endpoint_id FOR SHARE;
 SELECT * INTO STRICT i FROM control.installed_notification_channel WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND credential_ref=o.credential_ref;
 SELECT * INTO STRICT rt FROM control.installed_notification_routing WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND signed_profile_digest=w.routing_profile_digest;
 FOREACH lock_name IN ARRAY ARRAY['evidence-lifecycle:'||item.participant_id::text,'notification-worker:'||item.participant_id::text||':'||item.privacy_domain_id::text,
  'notification-installation:'||item.participant_id::text||':'||item.privacy_domain_id::text,
  'notification-routing:'||item.participant_id::text||':'||item.privacy_domain_id::text||':'||rt.profile_id::text] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1
   AND l.mode=CASE WHEN lock_name LIKE 'evidence-lifecycle:%' THEN 'ExclusiveLock' ELSE 'ShareLock' END)
  THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-FENCE'; END IF;
 END LOOP;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 wm:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));cm:=openpc.business_cbor(decode(i.channel_signed->>'payloadHex','hex'));
 IF w.state<>'ACTIVE' OR i.state<>'ACTIVE' OR ep.state<>'ACTIVE' OR rt.state<>'ACTIVE'
 OR now_ms<(p->'attempt'->>'startedAtMs')::numeric OR now_ms>=(p->'attempt'->>'deadlineAtMs')::numeric OR now_ms>=(p->>'authorityValidUntilMs')::numeric
 OR now_ms<(wm->>'6')::numeric OR now_ms>=(wm->>'7')::numeric
 OR now_ms<(cm->>'6')::numeric OR now_ms>=(cm->>'7')::numeric
 OR now_ms<(openpc.business_cbor(decode(rt.installation->'signed'->>'payloadHex','hex'))->>'6')::numeric
 OR now_ms>=(openpc.business_cbor(decode(rt.installation->'signed'->>'payloadHex','hex'))->>'7')::numeric
 OR i.credential->>'state'<>'ACTIVE' OR now_ms<(i.credential->>'validFromMs')::numeric OR now_ms>=(i.credential->>'validUntilMs')::numeric
 OR ep.revision IS DISTINCT FROM o.endpoint_revision OR ep.verification_id IS DISTINCT FROM o.verification_id OR ep.credential_ref IS DISTINCT FROM o.credential_ref
 OR ep.channel IS DISTINCT FROM o.channel OR ep.destination_ref IS DISTINCT FROM o.destination_ref OR ep.channel_profile_digest IS DISTINCT FROM o.channel_profile_digest
 OR i.channel_profile_digest IS DISTINCT FROM o.channel_profile_digest OR i.channel IS DISTINCT FROM o.channel OR i.destination_ref IS DISTINCT FROM o.destination_ref
 OR rt.endpoint_id IS DISTINCT FROM o.endpoint_id OR p->'channel' IS DISTINCT FROM jsonb_build_object('claims',jsonb_build_object('environmentId',cm->'1','participantId',(cm->'2'->>'bytes')::uuid::text,'privacyDomainId',(cm->'3'->>'bytes')::uuid::text,'profileId',(cm->'4'->>'bytes')::uuid::text,'revision',cm->>'5','validFromMs',(cm->>'6')::numeric,'validUntilMs',(cm->>'7')::numeric,'transportProfileDigest','sha256:'||(cm->'8'->>'bytes'),'receiptSignerSpki',cm->'9'->>'bytes','issuerKeyId','sha256:'||(cm->'10'->>'bytes')),'transport',i.channel_signed->'transport','signedProfileDigest',i.channel_profile_digest)
 OR NOT EXISTS(SELECT 1 FROM control.notification_endpoint_verification v WHERE v.participant_id=ep.participant_id AND v.privacy_domain_id=ep.privacy_domain_id AND v.verification_id=ep.verification_id
  AND v.endpoint_id=ep.endpoint_id AND v.endpoint_revision=ep.revision AND v.channel=ep.channel AND v.destination_ref=ep.destination_ref AND v.channel_profile_digest=ep.channel_profile_digest AND v.credential_ref=ep.credential_ref)
 OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal a USING(participant_id,principal_id) JOIN control.participant t USING(participant_id) JOIN control.privacy_domain v USING(participant_id)
  WHERE c.participant_id=item.participant_id AND c.credential_id=w.workload_credential_id AND a.principal_id=w.principal_id AND v.privacy_domain_id=item.privacy_domain_id
  AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch::text=p->>'workerEpoch' AND c.audience=w.installation->'pins'->>'workloadId'
  AND 'sha256:'||encode(c.public_key_digest,'hex')=w.installation->'pins'->>'workloadKeyDigest' AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp()
  AND a.state='ACTIVE' AND a.kind='WORKLOAD' AND t.state='ACTIVE' AND v.state='ACTIVE')
 OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal a USING(participant_id,principal_id) WHERE c.participant_id=item.participant_id AND c.credential_id=i.workload_credential_id
  AND a.principal_id=i.principal_id AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch=i.workload_epoch AND c.audience=i.workload_id
  AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp() AND a.state='ACTIVE' AND a.kind='WORKLOAD')
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-CURRENT'; END IF;
 SELECT * INTO STRICT k FROM control.evidence_kms_attempt WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND attempt_id=(item.preparation->'sourceClaims'->>'keyPreparationId')::uuid FOR UPDATE;
 SELECT * INTO STRICT ki FROM control.evidence_kms_installation WHERE participant_id=k.participant_id AND privacy_domain_id=k.privacy_domain_id AND installation_digest=k.installation_digest;
 lock_name:='evidence-kms-installation:'||item.participant_id::text||':'||item.privacy_domain_id::text||':'||(ki.pins->>'installationId');
 IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode='ShareLock' AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1)
 OR k.state<>'PROVED' OR ki.state<>'ACTIVE' OR now_ms<(ki.pins->>'validFromMs')::numeric OR now_ms>=(ki.pins->>'validUntilMs')::numeric
 OR ki.installation_digest IS DISTINCT FROM 'sha256:'||(wm->'18'->>'bytes')
 OR NOT EXISTS(SELECT 1 FROM control.notification_key_preparation kp JOIN control.notification_key_ciphertext kc USING(participant_id,privacy_domain_id,preparation_id)
  WHERE kp.participant_id=k.participant_id AND kp.privacy_domain_id=k.privacy_domain_id AND kp.preparation_id=k.attempt_id
  AND kc.key_id=item.preparation->'sourceClaims'->>'keyId' AND kc.encrypted_object_digest=item.preparation->'sourceClaims'->>'encryptedObjectDigest')
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-CUSTODY'; END IF;
 IF EXISTS(SELECT 1 FROM control.evidence_kms_exchange e WHERE e.participant_id=k.participant_id AND e.privacy_domain_id=k.privacy_domain_id AND e.attempt_id=k.attempt_id AND (
  (e.state IN ('PREPARED','DISPATCHED','UNKNOWN') AND NOT EXISTS(SELECT 1 FROM control.evidence_kms_exchange r WHERE r.participant_id=e.participant_id AND r.privacy_domain_id=e.privacy_domain_id AND r.attempt_id=e.attempt_id AND r.kind='READ_ATTEMPT' AND r.state='PROVED'
   AND openpc.evidence_kms_stored_outcome(r.receipt_bytes) IN ('1','2') AND convert_from(r.request_bytes,'UTF8')::jsonb->>'readExchangeId'=e.exchange_id::text AND convert_from(r.request_bytes,'UTF8')::jsonb->>'readRequestDigest'=e.request_digest))
  OR (e.receipt_bytes IS NOT NULL AND openpc.business_cbor(decode(convert_from(e.receipt_bytes,'UTF8')::jsonb->'receipt'->>'payloadHex','hex'))->>'24' IN ('3','4'))))
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-KMS-UNKNOWN'; END IF;
 SELECT * INTO STRICT status FROM control.evidence_kms_exchange WHERE participant_id=k.participant_id AND privacy_domain_id=k.privacy_domain_id AND attempt_id=k.attempt_id AND kind='STATUS' AND state='PROVED' ORDER BY provider_sequence DESC,exchange_id DESC LIMIT 1;
 km:=openpc.business_cbor(decode(convert_from(status.receipt_bytes,'UTF8')::jsonb->'receipt'->>'payloadHex','hex'));
 IF km->>'24' IS DISTINCT FROM '1' OR now_ms<(km->>'28')::numeric OR now_ms>=(km->>'29')::numeric OR now_ms-(km->>'28')::numeric>5000
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-KMS-STALE'; END IF;
 SELECT * INTO STRICT actual FROM openpc.current_notification_delivery_limit(item.preparation->'sourceClaims'->>'environmentId');
 IF actual.generation_id::text IS DISTINCT FROM p->>'generationId' OR actual.effective_digest IS DISTINCT FROM p->>'effectiveDigest' OR to_jsonb(actual.configured_limit) IS DISTINCT FROM p->'configuredLimit' OR actual.configured_limit<=0
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-GENERATION'; END IF;
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=o.notification_occurrence_id FOR UPDATE;
 after_state:=jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,
 'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested);
 IF start.transition->'after' IS DISTINCT FROM after_state OR d.revision IS DISTINCT FROM start.delivery_revision+1
 OR d.cancel_requested OR d.state<>'STARTED' OR d.attempt_count>least(d.attempt_limit,actual.configured_limit,6)
 OR d.delivery_request_event_id::text IS DISTINCT FROM p->'before'->>'deliveryRequestEventId'
 OR d.delivery_request_operation_id IS DISTINCT FROM start.source_operation_id
 OR d.budget_environment_id IS DISTINCT FROM p->'before'->>'budgetEnvironmentId'
 OR d.budget_generation_id::text IS DISTINCT FROM p->'before'->>'budgetGenerationId'
 OR d.budget_effective_digest IS DISTINCT FROM p->'before'->>'budgetEffectiveDigest'
 OR to_jsonb(d.budget_configured_limit) IS DISTINCT FROM p->'before'->'budgetConfiguredLimit'
 OR d.budget_worker_installation_digest IS DISTINCT FROM start.worker_installation_digest
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-STATE'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_delivery_dispatch_claim() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_notification_delivery_dispatch_owner();
 PERFORM openpc.check_notification_delivery_dispatch_intent_original(OLD);
 PERFORM openpc.check_notification_delivery_dispatch_intent_original(NEW);
 IF TG_OP<>'UPDATE' OR OLD.state<>'PENDING' OR NEW.state<>'CLAIMED'
 OR to_jsonb(NEW)-ARRAY['state','claim_token','claimed_at_ms'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','claim_token','claimed_at_ms']
 OR NEW.claim_token IS NULL OR NEW.claimed_at_ms IS NULL
 OR NEW.claimed_at_ms<floor(extract(epoch from transaction_timestamp())*1000) OR NEW.claimed_at_ms>floor(extract(epoch from clock_timestamp())*1000)
 THEN RAISE EXCEPTION 'NOTIFICATION-DISPATCH-ONCE'; END IF;
 PERFORM openpc.check_notification_delivery_dispatch_current(NEW.operation_id);
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_delivery_dispatch_claim_guard ON control.notification_delivery_dispatch_intent;
CREATE TRIGGER notification_delivery_dispatch_claim_guard BEFORE UPDATE ON control.notification_delivery_dispatch_intent FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_dispatch_claim();
REVOKE ALL ON FUNCTION openpc.assert_notification_delivery_dispatch_owner(),openpc.check_notification_delivery_dispatch_current(uuid),openpc.guard_notification_delivery_dispatch_claim() FROM PUBLIC;

GRANT UPDATE ON control.notification_delivery_dispatch_intent TO openpc_control_runtime;
GRANT EXECUTE ON FUNCTION openpc.assert_notification_delivery_dispatch_owner(),openpc.check_notification_delivery_dispatch_current(uuid),openpc.check_notification_delivery_dispatch_intent_original(control.notification_delivery_dispatch_intent) TO openpc_control_runtime;
GRANT EXECUTE ON FUNCTION openpc.assert_notification_delivery_signing_owner(),openpc.check_notification_delivery_signing_original(control.notification_delivery_signing),openpc.check_notification_delivery_signing_current(control.notification_delivery_signing),openpc.assert_notification_delivery_start_atomic_guards(),openpc.assert_notification_delivery_start_atomic_owner(),openpc.check_notification_delivery_start_original(control.notification_delivery_start),openpc.check_notification_delivery_start_projection(control.notification_delivery,control.notification_delivery),openpc.check_notification_delivery_start_complete(uuid) TO openpc_control_runtime;
-- Replace the closed attempt barrier only after every coherent atomic guard is installed.
SELECT openpc.assert_notification_delivery_start_atomic_guards();
DROP TRIGGER IF EXISTS notification_delivery_attempt_closed ON control.notification_delivery_attempt;


ALTER TABLE control.notification_cancellation_signing ENABLE ROW LEVEL SECURITY;
ALTER TABLE control.notification_cancellation_signing FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification_cancellation_signing FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT ON control.notification_cancellation_signing TO openpc_control_runtime;

ALTER TABLE control.notification_delivery_cancellation ENABLE ROW LEVEL SECURITY;
ALTER TABLE control.notification_delivery_cancellation FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification_delivery_cancellation FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader;
GRANT SELECT,INSERT ON control.notification_delivery_cancellation TO openpc_control_runtime;
GRANT UPDATE ON control.notification_cancellation_signing TO openpc_control_runtime;
-- The cause's source outbox is historical proof. Final cancellation still needs
-- its own atomic native publication/custody record before this write is released.
REVOKE INSERT ON control.notification_delivery_cancellation FROM openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.assert_notification_delivery_cancellation_owner() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE lock_name text;
BEGIN
 PERFORM openpc.assert_request_context(true);
 IF current_setting('transaction_isolation')<>'read committed' OR current_setting('row_security')<>'on'
 OR current_setting('session_replication_role')<>'origin' OR NOT pg_has_role(current_user,'openpc_control_runtime','USAGE')
 OR current_setting('openpc.action_intent_id',true) IS DISTINCT FROM 'ACT-EVIDENCE_EXPORT_RECORDS-V1'
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='control.notification_delivery_cancellation'::regclass AND relrowsecurity AND relforcerowsecurity)
 OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='control.notification_cancellation_signing'::regclass AND relrowsecurity AND relforcerowsecurity)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_cancellation_signing'::regclass AND tgname='notification_cancel_signing_guard' AND tgenabled IN ('O','A') AND tgtype=23 AND tgfoid='openpc.guard_notification_cancellation_signing()'::regprocedure)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_cancellation_signing'::regclass AND tgname='notification_cancel_signing_immutable' AND tgenabled IN ('O','A') AND tgtype=42 AND tgfoid='openpc.deny_notification_delivery_cancellation_mutation()'::regprocedure)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_cancellation'::regclass AND tgname='notification_cancellation_insert' AND tgenabled IN ('O','A') AND tgtype=7 AND tgfoid='openpc.guard_notification_delivery_cancellation()'::regprocedure)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_cancellation'::regclass AND tgname='notification_cancellation_immutable' AND tgenabled IN ('O','A') AND tgtype=58 AND tgfoid='openpc.deny_notification_delivery_cancellation_mutation()'::regprocedure)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_cancellation'::regclass AND tgname='notification_cancellation_complete' AND tgenabled IN ('O','A') AND tgtype=5 AND tgdeferrable AND tginitdeferred)
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-OWNER'; END IF;
 FOREACH lock_name IN ARRAY ARRAY['evidence-lifecycle:'||openpc.current_participant_id()::text,
 'notification-worker:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted
   AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
   AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1
   AND l.mode=CASE WHEN lock_name LIKE 'evidence-lifecycle:%' THEN 'ExclusiveLock' ELSE 'ShareLock' END)
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-FENCE'; END IF;
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_cancellation_original(item control.notification_delivery_cancellation) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE t jsonb:=item.transition;r jsonb:=t->'receipt';b jsonb:=t->'before';n jsonb:=t->'after';c jsonb:=t->'cause';
 a control.audit_occurrence%ROWTYPE;authorization_row control.mutation_evidence%ROWTYPE;i control.idempotency_record%ROWTYPE;e control.outbox_event%ROWTYPE;w control.installed_notification_worker%ROWTYPE;
 s control.notification_delivery_start%ROWTYPE;claim control.notification_delivery_dispatch_intent%ROWTYPE;o control.notification_delivery_outcome%ROWTYPE;before_projection jsonb;after_projection jsonb;expected jsonb;
BEGIN
 IF item.participant_id IS DISTINCT FROM openpc.current_participant_id() OR item.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR t->>'schema' IS DISTINCT FROM 'pc.notification.delivery-cancellation-transition.v1'
 OR item.transition_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(t),'UTF8') OR item.transition_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(t),'UTF8')),'hex')
 OR item.receipt_payload IS DISTINCT FROM decode(t->>'payloadHex','hex') OR item.cose_sign1 IS DISTINCT FROM decode(t->>'coseHex','hex')
 OR item.receipt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(item.receipt_payload),'hex')
 OR r->>'operationId' IS DISTINCT FROM item.operation_id::text OR r->>'receiptId' IS DISTINCT FROM item.receipt_id::text
 OR r->>'participantId' IS DISTINCT FROM item.participant_id::text OR r->>'privacyDomainId' IS DISTINCT FROM item.privacy_domain_id::text
 OR r->>'notificationOccurrenceId' IS DISTINCT FROM item.notification_occurrence_id::text OR r->>'payloadDigest' IS DISTINCT FROM item.payload_digest
 OR r->>'deliveryRevision' IS DISTINCT FROM item.delivery_revision::text OR r->>'causeOperationId' IS DISTINCT FROM item.cause_operation_id::text
 OR t->>'sourceOperationId' IS DISTINCT FROM item.source_operation_id::text OR c->>'receiptId' IS DISTINCT FROM item.cause_receipt_id::text
 OR t->'selector'->>'causeOperationId' IS DISTINCT FROM item.cause_operation_id::text
 OR t->'selector'->>'expectedRevision' IS DISTINCT FROM item.delivery_revision::text
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-ORIGINAL'; END IF;
 IF openpc.business_cbor(item.receipt_payload) IS DISTINCT FROM jsonb_build_object('0',openpc.business_bytes(decode('41e381d79d89ea82f47547ed9b1becfa84ef347dd77219f12ecfa950e45269cb','hex')),'1',r->>'environmentId','2',openpc.business_uuid((r->>'participantId')::uuid),'3',openpc.business_uuid((r->>'privacyDomainId')::uuid),'4',openpc.business_uuid((r->>'receiptId')::uuid),'5',openpc.business_uuid((r->>'operationId')::uuid),'6',openpc.business_uuid((r->>'notificationOccurrenceId')::uuid),'7',openpc.business_bytes(decode(substr(r->>'payloadDigest',8),'hex')),'8',openpc.business_uuid((r->>'sourceEventId')::uuid),'9',openpc.business_bytes(decode(substr(r->>'sourceReceiptDigest',8),'hex')),'10',openpc.business_bytes(decode(substr(r->>'workerProfileDigest',8),'hex')),'11',openpc.business_bytes(decode(substr(r->>'routingProfileDigest',8),'hex')),'12',openpc.business_bytes(decode(substr(r->>'authoritySnapshotDigest',8),'hex')),'13',openpc.business_uuid((r->>'endpointId')::uuid),'14',(r->>'endpointRevision')::numeric,'15',openpc.business_uuid((r->>'causeOperationId')::uuid),'16',CASE r->>'causeAction' WHEN 'ACT-NOTIFICATION_ENDPOINTS_UPDATE_RESOURCE-V1' THEN 1 ELSE NULL END,'17',openpc.business_bytes(decode(substr(r->>'causeProfileDigest',8),'hex')),'18',openpc.business_bytes(decode(substr(r->>'causeReceiptDigest',8),'hex')),'19',openpc.business_bytes(decode(substr(r->>'causeBeforeStateDigest',8),'hex')),'20',openpc.business_bytes(decode(substr(r->>'causeAfterStateDigest',8),'hex')),'21',(r->>'causeEndpointRevision')::numeric,'22',(r->>'deliveryRevision')::numeric,'23',openpc.business_bytes(decode(substr(r->>'beforeStateDigest',8),'hex')),'24',openpc.business_bytes(decode(substr(r->>'afterStateDigest',8),'hex')),'25',CASE r->>'beforeDeliveryState' WHEN 'PENDING' THEN 1 WHEN 'RETRY_WAIT' THEN 2 WHEN 'STARTED' THEN 3 WHEN 'AMBIGUOUS' THEN 4 ELSE NULL END,'26',CASE r->>'afterDeliveryState' WHEN 'CANCELLED' THEN 1 WHEN 'STARTED' THEN 2 WHEN 'AMBIGUOUS' THEN 3 ELSE NULL END,'27',(r->>'attemptCount')::numeric,'28',CASE r->>'disposition' WHEN 'CANCELLED_BEFORE_START' THEN 1 WHEN 'PREVENT_LATER_ATTEMPTS' THEN 2 WHEN 'RECONCILE_ORIGINAL' THEN 3 ELSE NULL END,'29',(r->>'recordedAtMs')::numeric,'30',openpc.business_bytes(decode(substr(r->>'signerKeyId',8),'hex')))
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-WIRE'; END IF;
 PERFORM openpc.archive_cose_binding(item.receipt_payload,item.cose_sign1,r->>'signerKeyId',24028,365);
 SELECT * INTO STRICT a FROM control.audit_occurrence WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id
 AND receipt_id=item.cause_receipt_id AND operation_id=item.cause_operation_id;
 SELECT * INTO STRICT i FROM control.idempotency_record WHERE participant_id=a.participant_id AND privacy_domain_id=a.privacy_domain_id AND operation_id=a.operation_id AND idempotency_record_id=a.idempotency_record_id;
 before_projection:=openpc.business_cbor(a.before_state_preimage)->8;after_projection:=openpc.business_cbor(a.after_state_preimage)->8;
 IF a.catalog_operation_id<>'CFG-OP-UPDATE-NOTIFICATION-ENDPOINT' OR a.action_intent_id<>'ACT-NOTIFICATION_ENDPOINTS_UPDATE_RESOURCE-V1'
 OR a.aggregate_type<>'notification-endpoint' OR a.profile_digest<>decode('946fcea402d8a83d11bbc68f962729bbafcab59d70bb9c0184da7441f904ea0d','hex')
 OR a.before_existence<>1 OR a.after_existence<>1 OR a.after_revision<>a.before_revision+1
 OR a.aggregate_id::text IS DISTINCT FROM r->>'endpointId' OR a.before_revision::text IS DISTINCT FROM r->>'endpointRevision'
 OR a.after_revision::text IS DISTINCT FROM r->>'causeEndpointRevision' OR a.environment_id IS DISTINCT FROM r->>'environmentId'
 OR before_projection->>'1'='RETIRED' OR after_projection->>'1' IS DISTINCT FROM (CASE WHEN before_projection->>'1'='QUARANTINED' THEN 'QUARANTINED' ELSE 'DISABLED' END)
 OR after_projection->'7' IS DISTINCT FROM '0'::jsonb OR after_projection ? '8'
 OR i.terminal_state<>'COMMITTED' OR i.action_intent_id<>a.action_intent_id OR i.catalog_operation_id<>a.catalog_operation_id OR i.input_digest<>a.candidate_digest
 OR i.result_payload->>'state' IS DISTINCT FROM 'SUCCEEDED' OR i.result_payload->>'truthState' IS DISTINCT FROM 'SUCCESS' OR i.result_payload->>'operationId' IS DISTINCT FROM a.operation_id::text
 OR a.before_state_digest<>sha256(a.before_state_preimage) OR a.after_state_digest<>sha256(a.after_state_preimage) OR a.pre_commit_authority_digest<>sha256(a.authority_snapshot)
 OR r->>'causeProfileDigest' IS DISTINCT FROM 'sha256:'||encode(a.profile_digest,'hex') OR a.after_revision::text IS DISTINCT FROM r->>'causeEndpointRevision' OR r->>'causeProfileDigest' IS DISTINCT FROM 'sha256:'||encode(a.profile_digest,'hex')
 OR a.before_state_digest<>sha256(a.before_state_preimage) OR a.after_state_digest<>sha256(a.after_state_preimage) OR a.pre_commit_authority_digest<>sha256(a.authority_snapshot)
 OR openpc.business_cbor(a.before_state_preimage)->8->>'1'='RETIRED'
 OR openpc.business_cbor(a.after_state_preimage)->8->>'1' IS DISTINCT FROM (CASE WHEN openpc.business_cbor(a.before_state_preimage)->8->>'1'='QUARANTINED' THEN 'QUARANTINED' ELSE 'DISABLED' END)
 OR openpc.business_cbor(a.after_state_preimage)->8->'7' IS DISTINCT FROM '0'::jsonb OR (openpc.business_cbor(a.after_state_preimage)->8) ? '8'
 OR r->>'causeReceiptDigest' IS DISTINCT FROM 'sha256:'||encode(a.receipt_digest,'hex')
 OR r->>'causeBeforeStateDigest' IS DISTINCT FROM 'sha256:'||encode(a.before_state_digest,'hex') OR r->>'causeAfterStateDigest' IS DISTINCT FROM 'sha256:'||encode(a.after_state_digest,'hex')
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-CAUSE'; END IF;

 SELECT * INTO STRICT authorization_row FROM control.mutation_evidence e WHERE e.participant_id=a.participant_id AND e.privacy_domain_id=a.privacy_domain_id
  AND e.operation_id=a.operation_id AND e.action_intent_id=a.action_intent_id AND e.catalog_operation_id=a.catalog_operation_id AND e.aggregate_id=a.aggregate_id
  AND e.candidate_digest=a.candidate_digest AND e.evidence_digest=sha256(e.evidence_cbor)
  AND e.evidence_role='AUTHORIZATION_INPUT' AND e.evidence_format='IDENTITY_RUNTIME_ASSERTION_3002_2_13';
 IF openpc.business_cbor(a.receipt_cbor)->'20' IS DISTINCT FROM jsonb_build_array(
  jsonb_build_object('0',2,'1',authorization_row.mutation_evidence_id::text,'2',openpc.business_bytes(authorization_row.evidence_digest)),
  openpc.configuration_step_up_receipt_input(a,authorization_row))
 OR t->'cause' IS DISTINCT FROM jsonb_build_object('participantId',a.participant_id::text,'privacyDomainId',a.privacy_domain_id::text,'environmentId',a.environment_id,
  'operationId',a.operation_id::text,'receiptId',a.receipt_id::text,'endpointId',a.aggregate_id::text,'endpointRevision',a.before_revision::text,'successorRevision',a.after_revision::text,
  'profileDigest','sha256:'||encode(a.profile_digest,'hex'),'receiptDigest','sha256:'||encode(a.receipt_digest,'hex'),
  'beforeStateDigest','sha256:'||encode(a.before_state_digest,'hex'),'afterStateDigest','sha256:'||encode(a.after_state_digest,'hex'),'recordedAtMs',floor(a.recorded_at_ns/1000000))
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-CAUSE-AUTHORITY'; END IF;

 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id
 AND event_id=(r->>'sourceEventId')::uuid AND correlation_id=item.source_operation_id AND aggregate_id=item.notification_occurrence_id;
 PERFORM openpc.check_notification_delivery_requested_event(e);
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=item.worker_installation_digest;
 IF w.installation IS DISTINCT FROM t->'workerInstallation' OR w.service_id<>'LS-NOTIFICATION' OR w.subscription_id<>'SUB-NOTIFICATIONDELIVERYREQUESTED-NOTIFICATION-V1'
 OR t->'selector'->'source'->'worker' IS DISTINCT FROM jsonb_build_object('participantId',item.participant_id::text,'privacyDomainId',item.privacy_domain_id::text,'installationDigest',item.worker_installation_digest)
 OR t->'selector'->'source'->>'eventId' IS DISTINCT FROM r->>'sourceEventId'
 OR t->'selector'->'source'->>'notificationOccurrenceId' IS DISTINCT FROM item.notification_occurrence_id::text
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-WORKER'; END IF;
  IF (b->>'state' IN ('PENDING','RETRY_WAIT','STARTED','AMBIGUOUS')) IS DISTINCT FROM true OR b->'cancelRequested' IS DISTINCT FROM 'false'::jsonb
 OR b->>'revision' IS DISTINCT FROM (r->>'deliveryRevision')::numeric::text OR n->>'revision' IS DISTINCT FROM ((r->>'deliveryRevision')::numeric+1)::text
 OR b->>'deliveryRequestOperationId' IS DISTINCT FROM (t->>'sourceOperationId')::uuid::text OR b->>'payloadDigest' IS DISTINCT FROM (r->>'payloadDigest')
 OR b->>'participantId' IS DISTINCT FROM item.participant_id::text OR b->>'privacyDomainId' IS DISTINCT FROM item.privacy_domain_id::text
 OR b->>'notificationOccurrenceId' IS DISTINCT FROM item.notification_occurrence_id::text
 OR n-ARRAY['revision','state','cancelRequested','nextAttemptAtMs'] IS DISTINCT FROM b-ARRAY['revision','state','cancelRequested','nextAttemptAtMs']
 OR n->'cancelRequested' IS DISTINCT FROM 'true'::jsonb OR n->'nextAttemptAtMs' IS DISTINCT FROM 'null'::jsonb
 OR n->>'state' IS DISTINCT FROM (CASE WHEN b->>'state' IN ('PENDING','RETRY_WAIT') THEN 'CANCELLED' ELSE b->>'state' END)
 OR r->>'beforeDeliveryState' IS DISTINCT FROM b->>'state' OR r->>'afterDeliveryState' IS DISTINCT FROM n->>'state' OR r->'attemptCount' IS DISTINCT FROM b->'attemptCount'
 OR r->>'disposition' IS DISTINCT FROM (CASE WHEN b->>'state'='PENDING' THEN 'CANCELLED_BEFORE_START' WHEN b->>'state'='RETRY_WAIT' THEN 'PREVENT_LATER_ATTEMPTS' ELSE 'RECONCILE_ORIGINAL' END)
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-TRANSITION'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',b->>'revision','projection',b-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest']);
 IF r->>'beforeStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-STATE'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',n->>'revision','projection',n-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest']);
 IF r->>'afterStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-STATE'; END IF;
 IF b->>'state'='PENDING' THEN
  IF b->'attemptCount' IS DISTINCT FROM '0'::jsonb OR t->'originalStart' IS DISTINCT FROM 'null'::jsonb OR t->'originalClaim' IS DISTINCT FROM 'null'::jsonb
   OR EXISTS(SELECT 1 FROM control.notification_delivery_attempt WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=item.notification_occurrence_id)
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-LINEAGE'; END IF;
 ELSE
  SELECT * INTO STRICT s FROM control.notification_delivery_start WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=(t->'originalStart'->'receipt'->>'operationId')::uuid;
  PERFORM openpc.check_notification_delivery_start_original(s);
  SELECT * INTO STRICT claim FROM control.notification_delivery_dispatch_intent WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND operation_id=s.operation_id;
  PERFORM openpc.check_notification_delivery_dispatch_intent_original(claim);
  IF t->'originalStart' IS DISTINCT FROM s.transition OR s.notification_occurrence_id<>item.notification_occurrence_id OR s.payload_digest<>(r->>'payloadDigest')
   OR t->'originalClaim' IS DISTINCT FROM jsonb_build_object('state',claim.state,'claimToken',claim.claim_token,'claimedAtMs',claim.claimed_at_ms)
   OR s.transition->'attempt'->'attemptNumber' IS DISTINCT FROM b->'attemptCount' OR s.transition->'attempt'->'startedAtMs' IS DISTINCT FROM b->'lastStartedAtMs'
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-LINEAGE'; END IF;
 END IF;
 IF b->>'state'='RETRY_WAIT' THEN
  SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id
   AND notification_occurrence_id=item.notification_occurrence_id AND start_operation_id=s.operation_id AND attempt_id=s.attempt_id;
  PERFORM openpc.check_notification_outcome_publication_original(o.operation_id);
  IF t->'originalOutcome' IS DISTINCT FROM o.transition OR o.transition->'receipt'->>'outcome' IS DISTINCT FROM 'RETRYABLE_NO_EFFECT'
   OR o.transition->'receipt'->>'afterDeliveryState' IS DISTINCT FROM 'RETRY_WAIT' OR claim.state<>'CLAIMED'
   OR (b->>'revision')::numeric<o.delivery_revision+1 OR (b->>'attemptLimit')::numeric>(o.transition->'receipt'->>'attemptLimit')::numeric
   OR (r->>'recordedAtMs')::numeric<(o.transition->'receipt'->>'recordedAtMs')::numeric
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-RETRY-LINEAGE'; END IF;
  expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',(o.delivery_revision+1)::text,
   'projection',(b-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest'])||jsonb_build_object('attemptLimit',o.transition->'receipt'->'attemptLimit'));
  IF 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') IS DISTINCT FROM o.transition->'receipt'->>'afterStateDigest'
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-RETRY-STATE'; END IF;
 ELSIF t ? 'originalOutcome' THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-UNEXPECTED-OUTCOME'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_delivery_cancellation() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE d control.notification_delivery%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_delivery_cancellation_owner();
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND notification_occurrence_id=NEW.notification_occurrence_id FOR UPDATE;
 IF jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested,'revision',d.revision::text,'deliveryRequestEventId',d.delivery_request_event_id::text,'deliveryRequestOperationId',d.delivery_request_operation_id::text,'budgetEnvironmentId',d.budget_environment_id,'budgetGenerationId',d.budget_generation_id::text,'budgetEffectiveDigest',d.budget_effective_digest,'budgetConfiguredLimit',d.budget_configured_limit,'budgetWorkerInstallationDigest',d.budget_worker_installation_digest) IS DISTINCT FROM NEW.transition->'before' THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-STALE'; END IF;
 PERFORM openpc.check_notification_delivery_cancellation_original(NEW);
 IF to_regprocedure('openpc.check_notification_delivery_cancellation_signer(uuid,text)') IS NULL THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNER-UNBOUND'; END IF;
 EXECUTE 'select openpc.check_notification_delivery_cancellation_signer($1,$2)' USING NEW.operation_id,NEW.transition_digest;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_cancellation_projection(before_row control.notification_delivery,after_row control.notification_delivery) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE c control.notification_delivery_cancellation%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_delivery_cancellation_owner();
 SELECT * INTO STRICT c FROM control.notification_delivery_cancellation WHERE participant_id=before_row.participant_id AND privacy_domain_id=before_row.privacy_domain_id AND notification_occurrence_id=before_row.notification_occurrence_id AND delivery_revision=before_row.revision;
 PERFORM openpc.check_notification_delivery_cancellation_original(c);
 IF jsonb_build_object('participantId',before_row.participant_id::text,'privacyDomainId',before_row.privacy_domain_id::text,'notificationOccurrenceId',before_row.notification_occurrence_id::text,'payloadDigest',before_row.payload_digest,'state',before_row.state,'attemptCount',before_row.attempt_count,'attemptLimit',before_row.attempt_limit,'nextAttemptAtMs',before_row.next_attempt_at_ms,'lastStartedAtMs',before_row.last_started_at_ms,'cancelRequested',before_row.cancel_requested,'revision',before_row.revision::text,'deliveryRequestEventId',before_row.delivery_request_event_id::text,'deliveryRequestOperationId',before_row.delivery_request_operation_id::text,'budgetEnvironmentId',before_row.budget_environment_id,'budgetGenerationId',before_row.budget_generation_id::text,'budgetEffectiveDigest',before_row.budget_effective_digest,'budgetConfiguredLimit',before_row.budget_configured_limit,'budgetWorkerInstallationDigest',before_row.budget_worker_installation_digest) IS DISTINCT FROM c.transition->'before' OR jsonb_build_object('participantId',after_row.participant_id::text,'privacyDomainId',after_row.privacy_domain_id::text,'notificationOccurrenceId',after_row.notification_occurrence_id::text,'payloadDigest',after_row.payload_digest,'state',after_row.state,'attemptCount',after_row.attempt_count,'attemptLimit',after_row.attempt_limit,'nextAttemptAtMs',after_row.next_attempt_at_ms,'lastStartedAtMs',after_row.last_started_at_ms,'cancelRequested',after_row.cancel_requested,'revision',after_row.revision::text,'deliveryRequestEventId',after_row.delivery_request_event_id::text,'deliveryRequestOperationId',after_row.delivery_request_operation_id::text,'budgetEnvironmentId',after_row.budget_environment_id,'budgetGenerationId',after_row.budget_generation_id::text,'budgetEffectiveDigest',after_row.budget_effective_digest,'budgetConfiguredLimit',after_row.budget_configured_limit,'budgetWorkerInstallationDigest',after_row.budget_worker_installation_digest) IS DISTINCT FROM c.transition->'after'
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-PROJECTION'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_cancellation_complete(operation uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE c control.notification_delivery_cancellation%ROWTYPE;d control.notification_delivery%ROWTYPE;
BEGIN
 SELECT * INTO STRICT c FROM control.notification_delivery_cancellation WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND operation_id=operation;
 PERFORM openpc.check_notification_delivery_cancellation_original(c);
 PERFORM openpc.check_notification_delivery_cancellation_signer(c.operation_id,c.transition_digest);
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=c.participant_id AND privacy_domain_id=c.privacy_domain_id AND notification_occurrence_id=c.notification_occurrence_id;
 IF d.revision<c.delivery_revision+1 OR NOT d.cancel_requested OR d.payload_digest<>c.payload_digest
 OR (d.revision=c.delivery_revision+1 AND jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested,'revision',d.revision::text,'deliveryRequestEventId',d.delivery_request_event_id::text,'deliveryRequestOperationId',d.delivery_request_operation_id::text,'budgetEnvironmentId',d.budget_environment_id,'budgetGenerationId',d.budget_generation_id::text,'budgetEffectiveDigest',d.budget_effective_digest,'budgetConfiguredLimit',d.budget_configured_limit,'budgetWorkerInstallationDigest',d.budget_worker_installation_digest) IS DISTINCT FROM c.transition->'after')
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-INCOMPLETE'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_delivery_cancellation_complete() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN PERFORM openpc.check_notification_delivery_cancellation_complete(NEW.operation_id);RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION openpc.deny_notification_delivery_cancellation_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-IMMUTABLE';END $$;
DROP TRIGGER IF EXISTS notification_cancellation_insert ON control.notification_delivery_cancellation;
CREATE TRIGGER notification_cancellation_insert BEFORE INSERT ON control.notification_delivery_cancellation FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_cancellation();
DROP TRIGGER IF EXISTS notification_cancellation_immutable ON control.notification_delivery_cancellation;
CREATE TRIGGER notification_cancellation_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON control.notification_delivery_cancellation FOR EACH STATEMENT EXECUTE FUNCTION openpc.deny_notification_delivery_cancellation_mutation();
DROP TRIGGER IF EXISTS notification_cancellation_complete ON control.notification_delivery_cancellation;
CREATE CONSTRAINT TRIGGER notification_cancellation_complete AFTER INSERT ON control.notification_delivery_cancellation DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_delivery_cancellation_complete();
REVOKE ALL ON FUNCTION openpc.assert_notification_delivery_cancellation_owner(),openpc.check_notification_delivery_cancellation_original(control.notification_delivery_cancellation),openpc.guard_notification_delivery_cancellation(),openpc.check_notification_delivery_cancellation_projection(control.notification_delivery,control.notification_delivery),openpc.check_notification_delivery_cancellation_complete(uuid),openpc.guard_notification_delivery_cancellation_complete(),openpc.deny_notification_delivery_cancellation_mutation() FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.check_notification_cancellation_signing_original(item control.notification_cancellation_signing) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p jsonb:=item.preparation;x jsonb:=p->'input';q jsonb:=p->'request';r jsonb:=x->'receipt';trust jsonb:=p->'trust';
 signer control.notification_receipt_signer_installation%ROWTYPE;w control.installed_notification_worker%ROWTYPE;a control.audit_occurrence%ROWTYPE;
 authorization_row control.mutation_evidence%ROWTYPE;source control.notification_occurrence_observation%ROWTYPE;t jsonb:=x;sm jsonb;wm jsonb;
BEGIN
 IF item.participant_id IS DISTINCT FROM openpc.current_participant_id() OR item.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR item.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(p),'UTF8') OR item.preparation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(p),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-ORIGINAL'; END IF;
 IF p IS DISTINCT FROM jsonb_build_object('input',x,'trust',trust,'request',q)
 OR q-ARRAY['schemaVersion','method','purpose','signerInstallationDigest','providerId','secretClass','reference','version','keyEpoch','signerKeyId','environmentId','participantId','privacyDomainId','workerInstallationDigest','workerProfileDigest','workloadCredentialId','workloadEpoch','signingAttemptId','operationId','causeOperationId','cancellationPreparationDigest','payloadHex'] IS DISTINCT FROM '{}'::jsonb
 OR (SELECT count(*) FROM jsonb_object_keys(q))<>22
 OR x->>'schema' IS DISTINCT FROM 'pc.notification.delivery-cancellation-transition.v1'
 OR q->>'method' IS DISTINCT FROM 'SIGN_NOTIFICATION_DELIVERY_CANCELLATION' OR q->>'purpose' IS DISTINCT FROM 'pc.cose.notification-delivery-cancellation-receipt.v1'
 OR q->'schemaVersion' IS DISTINCT FROM '1'::jsonb OR q->>'operationId' IS DISTINCT FROM item.operation_id::text OR q->>'signingAttemptId' IS DISTINCT FROM item.signing_attempt_id::text
 OR q->>'participantId' IS DISTINCT FROM item.participant_id::text OR q->>'privacyDomainId' IS DISTINCT FROM item.privacy_domain_id::text
 OR q->>'causeOperationId' IS DISTINCT FROM item.cause_operation_id::text OR q->>'signerInstallationDigest' IS DISTINCT FROM item.signer_installation_digest
 OR x->'selector'->'source'->>'notificationOccurrenceId' IS DISTINCT FROM item.notification_occurrence_id::text
 OR q->>'payloadHex' IS DISTINCT FROM x->>'payloadHex' OR q->>'cancellationPreparationDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(x),'UTF8')),'hex')
 OR r->>'operationId' IS DISTINCT FROM item.operation_id::text OR r->>'receiptId' IS DISTINCT FROM item.signing_attempt_id::text
 OR r->>'causeOperationId' IS DISTINCT FROM item.cause_operation_id::text OR r->>'notificationOccurrenceId' IS DISTINCT FROM item.notification_occurrence_id::text
 OR openpc.business_cbor(decode(q->>'payloadHex','hex')) IS DISTINCT FROM jsonb_build_object('0',openpc.business_bytes(decode('41e381d79d89ea82f47547ed9b1becfa84ef347dd77219f12ecfa950e45269cb','hex')),'1',r->>'environmentId','2',openpc.business_uuid((r->>'participantId')::uuid),'3',openpc.business_uuid((r->>'privacyDomainId')::uuid),'4',openpc.business_uuid((r->>'receiptId')::uuid),'5',openpc.business_uuid((r->>'operationId')::uuid),'6',openpc.business_uuid((r->>'notificationOccurrenceId')::uuid),'7',openpc.business_bytes(decode(substr(r->>'payloadDigest',8),'hex')),'8',openpc.business_uuid((r->>'sourceEventId')::uuid),'9',openpc.business_bytes(decode(substr(r->>'sourceReceiptDigest',8),'hex')),'10',openpc.business_bytes(decode(substr(r->>'workerProfileDigest',8),'hex')),'11',openpc.business_bytes(decode(substr(r->>'routingProfileDigest',8),'hex')),'12',openpc.business_bytes(decode(substr(r->>'authoritySnapshotDigest',8),'hex')),'13',openpc.business_uuid((r->>'endpointId')::uuid),'14',(r->>'endpointRevision')::numeric,'15',openpc.business_uuid((r->>'causeOperationId')::uuid),'16',CASE r->>'causeAction' WHEN 'ACT-NOTIFICATION_ENDPOINTS_UPDATE_RESOURCE-V1' THEN 1 ELSE NULL END,'17',openpc.business_bytes(decode(substr(r->>'causeProfileDigest',8),'hex')),'18',openpc.business_bytes(decode(substr(r->>'causeReceiptDigest',8),'hex')),'19',openpc.business_bytes(decode(substr(r->>'causeBeforeStateDigest',8),'hex')),'20',openpc.business_bytes(decode(substr(r->>'causeAfterStateDigest',8),'hex')),'21',(r->>'causeEndpointRevision')::numeric,'22',(r->>'deliveryRevision')::numeric,'23',openpc.business_bytes(decode(substr(r->>'beforeStateDigest',8),'hex')),'24',openpc.business_bytes(decode(substr(r->>'afterStateDigest',8),'hex')),'25',CASE r->>'beforeDeliveryState' WHEN 'PENDING' THEN 1 WHEN 'RETRY_WAIT' THEN 2 WHEN 'STARTED' THEN 3 WHEN 'AMBIGUOUS' THEN 4 ELSE NULL END,'26',CASE r->>'afterDeliveryState' WHEN 'CANCELLED' THEN 1 WHEN 'STARTED' THEN 2 WHEN 'AMBIGUOUS' THEN 3 ELSE NULL END,'27',(r->>'attemptCount')::numeric,'28',CASE r->>'disposition' WHEN 'CANCELLED_BEFORE_START' THEN 1 WHEN 'PREVENT_LATER_ATTEMPTS' THEN 2 WHEN 'RECONCILE_ORIGINAL' THEN 3 ELSE NULL END,'29',(r->>'recordedAtMs')::numeric,'30',openpc.business_bytes(decode(substr(r->>'signerKeyId',8),'hex')))
 OR item.request_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to('pc.notification.cancellation-receipt-provider-request.v1','UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(q),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-BINDING'; END IF;
 SELECT * INTO STRICT signer FROM control.notification_receipt_signer_installation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND trust_digest=item.signer_installation_digest;
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=signer.worker_installation_digest;
 IF trust->'worker' IS DISTINCT FROM w.installation OR x->'workerInstallation' IS DISTINCT FROM w.installation
 OR trust IS DISTINCT FROM jsonb_build_object('worker',w.installation,'signer',signer.trust-ARRAY['schema','schemaDefinitionDigest','signerKeyId'])
 OR trust->'signer' IS DISTINCT FROM signer.trust-ARRAY['schema','schemaDefinitionDigest','signerKeyId']
 OR signer.trust->>'purpose' IS DISTINCT FROM 'pc.cose.notification-delivery-cancellation-receipt.v1'
 OR w.service_id<>'LS-NOTIFICATION' OR w.subscription_id<>'SUB-NOTIFICATIONDELIVERYREQUESTED-NOTIFICATION-V1'
 OR r->>'workerProfileDigest' IS DISTINCT FROM signer.trust->>'workerProfileDigest'
 OR r->>'signerKeyId' IS DISTINCT FROM signer.signer_id OR q->>'signerKeyId' IS DISTINCT FROM signer.signer_id
 OR q->>'reference' IS DISTINCT FROM signer.trust->>'secretReference' OR q->>'version' IS DISTINCT FROM signer.trust->>'secretVersion'
 OR q->>'providerId' IS DISTINCT FROM signer.trust->>'providerId' OR q->>'keyEpoch' IS DISTINCT FROM signer.trust->>'keyEpoch'
 OR q->>'workloadCredentialId' IS DISTINCT FROM signer.trust->>'workloadCredentialId' OR q->>'workloadEpoch' IS DISTINCT FROM signer.trust->>'workloadEpoch'
 OR q->>'workerInstallationDigest' IS DISTINCT FROM signer.worker_installation_digest OR q->>'workerProfileDigest' IS DISTINCT FROM signer.trust->>'workerProfileDigest'
 OR q->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY' OR q->>'environmentId' IS DISTINCT FROM signer.trust->>'environmentId'
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-TRUST'; END IF;
 SELECT * INTO STRICT a FROM control.audit_occurrence WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=item.cause_operation_id;
 IF a.catalog_operation_id<>'CFG-OP-UPDATE-NOTIFICATION-ENDPOINT' OR a.action_intent_id<>'ACT-NOTIFICATION_ENDPOINTS_UPDATE_RESOURCE-V1'
 OR a.aggregate_type<>'notification-endpoint' OR a.environment_id IS DISTINCT FROM r->>'environmentId'
 OR a.profile_digest<>decode('946fcea402d8a83d11bbc68f962729bbafcab59d70bb9c0184da7441f904ea0d','hex') OR a.before_existence<>1 OR a.after_existence<>1 OR a.after_revision<>a.before_revision+1
 OR a.aggregate_id::text IS DISTINCT FROM r->>'endpointId' OR a.before_revision::text IS DISTINCT FROM r->>'endpointRevision'
 OR a.after_revision::text IS DISTINCT FROM r->>'causeEndpointRevision' OR r->>'causeProfileDigest' IS DISTINCT FROM 'sha256:'||encode(a.profile_digest,'hex')
 OR a.before_state_digest<>sha256(a.before_state_preimage) OR a.after_state_digest<>sha256(a.after_state_preimage) OR a.pre_commit_authority_digest<>sha256(a.authority_snapshot)
 OR openpc.business_cbor(a.before_state_preimage)->8->>'1'='RETIRED'
 OR openpc.business_cbor(a.after_state_preimage)->8->>'1' IS DISTINCT FROM (CASE WHEN openpc.business_cbor(a.before_state_preimage)->8->>'1'='QUARANTINED' THEN 'QUARANTINED' ELSE 'DISABLED' END)
 OR openpc.business_cbor(a.after_state_preimage)->8->'7' IS DISTINCT FROM '0'::jsonb OR (openpc.business_cbor(a.after_state_preimage)->8) ? '8'
 OR r->>'causeReceiptDigest' IS DISTINCT FROM 'sha256:'||encode(a.receipt_digest,'hex')
 OR r->>'causeBeforeStateDigest' IS DISTINCT FROM 'sha256:'||encode(a.before_state_digest,'hex') OR r->>'causeAfterStateDigest' IS DISTINCT FROM 'sha256:'||encode(a.after_state_digest,'hex')
 OR NOT EXISTS(SELECT 1 FROM control.idempotency_record i WHERE i.participant_id=a.participant_id AND i.privacy_domain_id=a.privacy_domain_id AND i.operation_id=a.operation_id
  AND i.idempotency_record_id=a.idempotency_record_id AND i.action_intent_id=a.action_intent_id AND i.catalog_operation_id=a.catalog_operation_id AND i.input_digest=a.candidate_digest
  AND i.result_aggregate_version=a.after_revision AND i.result_digest=sha256(convert_to(openpc.signing_canonical_json(i.result_payload),'UTF8'))
  AND i.result_payload->>'operationId'=a.operation_id::text AND i.terminal_state='COMMITTED' AND i.result_payload->>'state'='SUCCEEDED' AND i.result_payload->>'truthState'='SUCCESS')
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-CAUSE'; END IF;

 SELECT * INTO STRICT authorization_row FROM control.mutation_evidence e WHERE e.participant_id=a.participant_id AND e.privacy_domain_id=a.privacy_domain_id
  AND e.operation_id=a.operation_id AND e.action_intent_id=a.action_intent_id AND e.catalog_operation_id=a.catalog_operation_id AND e.aggregate_id=a.aggregate_id
  AND e.candidate_digest=a.candidate_digest AND e.evidence_digest=sha256(e.evidence_cbor)
  AND e.evidence_role='AUTHORIZATION_INPUT' AND e.evidence_format='IDENTITY_RUNTIME_ASSERTION_3002_2_13';
 IF openpc.business_cbor(a.receipt_cbor)->'20' IS DISTINCT FROM jsonb_build_array(
  jsonb_build_object('0',2,'1',authorization_row.mutation_evidence_id::text,'2',openpc.business_bytes(authorization_row.evidence_digest)),
  openpc.configuration_step_up_receipt_input(a,authorization_row))
 OR t->'cause' IS DISTINCT FROM jsonb_build_object('participantId',a.participant_id::text,'privacyDomainId',a.privacy_domain_id::text,'environmentId',a.environment_id,
  'operationId',a.operation_id::text,'receiptId',a.receipt_id::text,'endpointId',a.aggregate_id::text,'endpointRevision',a.before_revision::text,'successorRevision',a.after_revision::text,
  'profileDigest','sha256:'||encode(a.profile_digest,'hex'),'receiptDigest','sha256:'||encode(a.receipt_digest,'hex'),
  'beforeStateDigest','sha256:'||encode(a.before_state_digest,'hex'),'afterStateDigest','sha256:'||encode(a.after_state_digest,'hex'),'recordedAtMs',floor(a.recorded_at_ns/1000000))
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-CAUSE-AUTHORITY'; END IF;

 SELECT * INTO STRICT source FROM control.notification_occurrence_observation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=(x->>'sourceOperationId')::uuid;
 sm:=openpc.business_cbor(source.receipt_payload);wm:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));
 IF x->'sourceClaims' IS DISTINCT FROM jsonb_build_object('environmentId',sm->'1','participantId',(sm->'2'->>'bytes')::uuid::text,'privacyDomainId',(sm->'3'->>'bytes')::uuid::text,'receiptId',(sm->'4'->>'bytes')::uuid::text,'operationId',(sm->'5'->>'bytes')::uuid::text,'notificationId',(sm->'6'->>'bytes')::uuid::text,'notificationOccurrenceId',(sm->'7'->>'bytes')::uuid::text,'payloadObjectId',(sm->'8'->>'bytes')::uuid::text,'keyPreparationId',(sm->'9'->>'bytes')::uuid::text,'sourceEventId',(sm->'10'->>'bytes')::uuid::text,'sourceDataDigest','sha256:'||(sm->'11'->>'bytes'),'sourceReceiptDigest','sha256:'||(sm->'12'->>'bytes'),'routingProfileDigest','sha256:'||(sm->'13'->>'bytes'),'workerProfileDigest','sha256:'||(sm->'14'->>'bytes'),'authoritySnapshotDigest','sha256:'||(sm->'15'->>'bytes'),'custodyDigest','sha256:'||(sm->'16'->>'bytes'),'endpointId',(sm->'17'->>'bytes')::uuid::text,'endpointRevision',sm->>'18','templateDigest','sha256:'||(sm->'19'->>'bytes'),'payloadDigest','sha256:'||(sm->'20'->>'bytes'),'encryptedObjectDigest','sha256:'||(sm->'21'->>'bytes'),'keyId','sha256:'||(sm->'22'->>'bytes'),'recordedAtMs',(sm->>'23')::numeric,'signerKeyId','sha256:'||(sm->'24'->>'bytes'),'occurrenceReceiptDigest','sha256:'||(sm->'25'->>'bytes'),'eventId',(sm->'26'->>'bytes')::uuid::text,'sourceId',(sm->'27'->>'bytes')::uuid::text,'sequence',sm->>'28','dataDigest','sha256:'||(sm->'29'->>'bytes'))
 OR r->>'sourceEventId' IS DISTINCT FROM x->'sourceClaims'->>'eventId' OR r->>'routingProfileDigest' IS DISTINCT FROM x->'sourceClaims'->>'routingProfileDigest'
 OR r->>'endpointId' IS DISTINCT FROM x->'sourceClaims'->>'endpointId' OR r->>'endpointRevision' IS DISTINCT FROM x->'sourceClaims'->>'endpointRevision'
 OR r->>'payloadDigest' IS DISTINCT FROM x->'sourceClaims'->>'payloadDigest' OR r->>'authoritySnapshotDigest' IS DISTINCT FROM x->>'workerAuthorityDigest'
 OR r->>'participantId' IS DISTINCT FROM item.participant_id::text OR r->>'privacyDomainId' IS DISTINCT FROM item.privacy_domain_id::text
 OR r->>'environmentId' IS DISTINCT FROM q->>'environmentId' OR x->'sourceClaims'->>'operationId' IS DISTINCT FROM source.operation_id::text
 OR x->'selector'->>'causeOperationId' IS DISTINCT FROM item.cause_operation_id::text OR x->'selector'->>'expectedRevision' IS DISTINCT FROM r->>'deliveryRevision'
 OR (r->>'recordedAtMs')::numeric<(wm->>'6')::numeric OR (r->>'recordedAtMs')::numeric>=(wm->>'7')::numeric
 OR x->>'sourceReceiptDigest' IS DISTINCT FROM source.receipt_digest OR r->>'sourceReceiptDigest' IS DISTINCT FROM source.receipt_digest
 OR (r->>'recordedAtMs')::numeric*1000000<a.recorded_at_ns OR (r->>'recordedAtMs')::numeric*1000000<(signer.trust->>'validFromNs')::numeric
 OR (r->>'recordedAtMs')::numeric*1000000>=(signer.trust->>'validUntilNs')::numeric
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-SOURCE'; END IF;
 IF item.state<>'PREPARED' AND (item.dispatched_at_ms<(r->>'recordedAtMs')::numeric OR item.dispatched_at_ms*1000000>=(signer.trust->>'validUntilNs')::numeric OR item.dispatched_at_ms>=(wm->>'7')::numeric)
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-TIME'; END IF;
 IF item.state='OBSERVED' THEN
  IF item.observation-ARRAY['schemaVersion','providerId','signingAttemptId','requestDigest','recordedAtMs','outcome','reason','coseHex'] IS DISTINCT FROM '{}'::jsonb
  OR (SELECT count(*) FROM jsonb_object_keys(item.observation))<>8 OR jsonb_typeof(item.observation->'recordedAtMs') IS DISTINCT FROM 'number'
  OR (item.observation->>'recordedAtMs')::numeric NOT BETWEEN 0 AND 9007199254740991 OR trunc((item.observation->>'recordedAtMs')::numeric)<>(item.observation->>'recordedAtMs')::numeric
  OR item.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(item.observation),'UTF8') OR item.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(item.observation),'UTF8')),'hex')
  OR item.observation->>'providerId' IS DISTINCT FROM q->>'providerId' OR item.observation->>'signingAttemptId' IS DISTINCT FROM item.signing_attempt_id::text
  OR item.observation->>'requestDigest' IS DISTINCT FROM item.request_digest OR item.observation->'schemaVersion' IS DISTINCT FROM '1'::jsonb
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-OBSERVATION'; END IF;
  IF item.observation->>'outcome'='SIGNED' THEN
   IF item.observation->'reason' IS DISTINCT FROM 'null'::jsonb OR item.observation->>'coseHex' IS NULL
   OR (item.observation->>'recordedAtMs')::numeric>=(wm->>'7')::numeric
   OR (item.observation->>'recordedAtMs')::numeric<item.dispatched_at_ms OR (item.observation->>'recordedAtMs')::numeric*1000000>=(signer.trust->>'validUntilNs')::numeric
   THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-OBSERVATION'; END IF;
   PERFORM openpc.archive_cose_binding(decode(q->>'payloadHex','hex'),decode(item.observation->>'coseHex','hex'),signer.signer_id,24028,365);
  ELSIF item.observation->>'outcome' IS DISTINCT FROM 'REJECTED' OR item.observation->'coseHex' IS DISTINCT FROM 'null'::jsonb
   OR (item.observation->>'reason' IN ('REVOKED','EXPIRED','WRONG_SCOPE','INVALID_REQUEST','ATTEMPT_CONFLICT','KEY_UNAVAILABLE')) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-OBSERVATION'; END IF;
 END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_cancellation_signing_current(item control.notification_cancellation_signing) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE d control.notification_delivery%ROWTYPE;signer control.notification_receipt_signer_installation%ROWTYPE;now_ms numeric;lock_name text;wm jsonb;
 t jsonb:=item.preparation->'input';r jsonb:=t->'receipt';b jsonb:=t->'before';n jsonb:=t->'after';expected jsonb;
 s control.notification_delivery_start%ROWTYPE;claim control.notification_delivery_dispatch_intent%ROWTYPE;o control.notification_delivery_outcome%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_delivery_cancellation_owner();
 PERFORM openpc.check_notification_cancellation_signing_original(item);
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=item.notification_occurrence_id FOR UPDATE;
 IF jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested,'revision',d.revision::text,'deliveryRequestEventId',d.delivery_request_event_id::text,'deliveryRequestOperationId',d.delivery_request_operation_id::text,'budgetEnvironmentId',d.budget_environment_id,'budgetGenerationId',d.budget_generation_id::text,'budgetEffectiveDigest',d.budget_effective_digest,'budgetConfiguredLimit',d.budget_configured_limit,'budgetWorkerInstallationDigest',d.budget_worker_installation_digest) IS DISTINCT FROM item.preparation->'input'->'before' OR d.cancel_requested OR d.state NOT IN ('PENDING','RETRY_WAIT','STARTED','AMBIGUOUS')
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-STALE'; END IF;
  IF (b->>'state' IN ('PENDING','RETRY_WAIT','STARTED','AMBIGUOUS')) IS DISTINCT FROM true OR b->'cancelRequested' IS DISTINCT FROM 'false'::jsonb
 OR b->>'revision' IS DISTINCT FROM (r->>'deliveryRevision')::numeric::text OR n->>'revision' IS DISTINCT FROM ((r->>'deliveryRevision')::numeric+1)::text
 OR b->>'deliveryRequestOperationId' IS DISTINCT FROM (t->>'sourceOperationId')::uuid::text OR b->>'payloadDigest' IS DISTINCT FROM (r->>'payloadDigest')
 OR b->>'participantId' IS DISTINCT FROM item.participant_id::text OR b->>'privacyDomainId' IS DISTINCT FROM item.privacy_domain_id::text
 OR b->>'notificationOccurrenceId' IS DISTINCT FROM item.notification_occurrence_id::text
 OR n-ARRAY['revision','state','cancelRequested','nextAttemptAtMs'] IS DISTINCT FROM b-ARRAY['revision','state','cancelRequested','nextAttemptAtMs']
 OR n->'cancelRequested' IS DISTINCT FROM 'true'::jsonb OR n->'nextAttemptAtMs' IS DISTINCT FROM 'null'::jsonb
 OR n->>'state' IS DISTINCT FROM (CASE WHEN b->>'state' IN ('PENDING','RETRY_WAIT') THEN 'CANCELLED' ELSE b->>'state' END)
 OR r->>'beforeDeliveryState' IS DISTINCT FROM b->>'state' OR r->>'afterDeliveryState' IS DISTINCT FROM n->>'state' OR r->'attemptCount' IS DISTINCT FROM b->'attemptCount'
 OR r->>'disposition' IS DISTINCT FROM (CASE WHEN b->>'state'='PENDING' THEN 'CANCELLED_BEFORE_START' WHEN b->>'state'='RETRY_WAIT' THEN 'PREVENT_LATER_ATTEMPTS' ELSE 'RECONCILE_ORIGINAL' END)
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-TRANSITION'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',b->>'revision','projection',b-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest']);
 IF r->>'beforeStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-STATE'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',n->>'revision','projection',n-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest']);
 IF r->>'afterStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-STATE'; END IF;
 IF b->>'state'='PENDING' THEN
  IF b->'attemptCount' IS DISTINCT FROM '0'::jsonb OR t->'originalStart' IS DISTINCT FROM 'null'::jsonb OR t->'originalClaim' IS DISTINCT FROM 'null'::jsonb
   OR EXISTS(SELECT 1 FROM control.notification_delivery_attempt WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=item.notification_occurrence_id)
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-LINEAGE'; END IF;
 ELSE
  SELECT * INTO STRICT s FROM control.notification_delivery_start WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=(t->'originalStart'->'receipt'->>'operationId')::uuid;
  PERFORM openpc.check_notification_delivery_start_original(s);
  SELECT * INTO STRICT claim FROM control.notification_delivery_dispatch_intent WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND operation_id=s.operation_id;
  PERFORM openpc.check_notification_delivery_dispatch_intent_original(claim);
  IF t->'originalStart' IS DISTINCT FROM s.transition OR s.notification_occurrence_id<>item.notification_occurrence_id OR s.payload_digest<>(r->>'payloadDigest')
   OR t->'originalClaim' IS DISTINCT FROM jsonb_build_object('state',claim.state,'claimToken',claim.claim_token,'claimedAtMs',claim.claimed_at_ms)
   OR s.transition->'attempt'->'attemptNumber' IS DISTINCT FROM b->'attemptCount' OR s.transition->'attempt'->'startedAtMs' IS DISTINCT FROM b->'lastStartedAtMs'
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-LINEAGE'; END IF;
 END IF;
 IF b->>'state'='RETRY_WAIT' THEN
  SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id
   AND notification_occurrence_id=item.notification_occurrence_id AND start_operation_id=s.operation_id AND attempt_id=s.attempt_id;
  PERFORM openpc.check_notification_outcome_publication_original(o.operation_id);
  IF t->'originalOutcome' IS DISTINCT FROM o.transition OR o.transition->'receipt'->>'outcome' IS DISTINCT FROM 'RETRYABLE_NO_EFFECT'
   OR o.transition->'receipt'->>'afterDeliveryState' IS DISTINCT FROM 'RETRY_WAIT' OR claim.state<>'CLAIMED'
   OR (b->>'revision')::numeric<o.delivery_revision+1 OR (b->>'attemptLimit')::numeric>(o.transition->'receipt'->>'attemptLimit')::numeric
   OR (r->>'recordedAtMs')::numeric<(o.transition->'receipt'->>'recordedAtMs')::numeric
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-RETRY-LINEAGE'; END IF;
  expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',(o.delivery_revision+1)::text,
   'projection',(b-ARRAY['revision','deliveryRequestEventId','deliveryRequestOperationId','budgetEnvironmentId','budgetGenerationId','budgetEffectiveDigest','budgetConfiguredLimit','budgetWorkerInstallationDigest'])||jsonb_build_object('attemptLimit',o.transition->'receipt'->'attemptLimit'));
  IF 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') IS DISTINCT FROM o.transition->'receipt'->>'afterStateDigest'
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-RETRY-STATE'; END IF;
 ELSIF t ? 'originalOutcome' THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-UNEXPECTED-OUTCOME'; END IF;
 IF r->>'recordedAtMs' IS NULL OR r->>'workerProfileDigest' IS NULL THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-BINDING'; END IF;
 lock_name:='notification-receipt-signer:'||item.participant_id::text||':'||item.privacy_domain_id::text;
 IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode='ShareLock'
 AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1)
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-FENCE'; END IF;
 SELECT * INTO STRICT signer FROM control.notification_receipt_signer_installation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND trust_digest=item.signer_installation_digest AND state='ACTIVE';
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 SELECT openpc.business_cbor(decode(installation->'signed'->>'payloadHex','hex')) INTO STRICT wm FROM control.installed_notification_worker
 WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=signer.worker_installation_digest;
 IF now_ms<(wm->>'6')::numeric OR now_ms>=(wm->>'7')::numeric OR now_ms*1000000<(signer.trust->>'validFromNs')::numeric OR now_ms*1000000>=(signer.trust->>'validUntilNs')::numeric
 OR NOT EXISTS(SELECT 1 FROM control.installed_notification_worker w JOIN control.credential c ON c.participant_id=w.participant_id AND c.credential_id=w.workload_credential_id
   JOIN control.principal p ON p.participant_id=c.participant_id AND p.principal_id=c.principal_id
   WHERE w.participant_id=item.participant_id AND w.privacy_domain_id=item.privacy_domain_id AND w.installation_digest=signer.worker_installation_digest AND w.state='ACTIVE'
    AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch::text=signer.trust->>'workloadEpoch'
    AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp() AND p.state='ACTIVE' AND p.kind='WORKLOAD')
 THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-AUTHORITY'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_cancellation_signing() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_notification_delivery_cancellation_owner();
 PERFORM openpc.check_notification_cancellation_signing_original(NEW);
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-INITIAL'; END IF;
  PERFORM openpc.check_notification_cancellation_signing_current(NEW);
 ELSE
  IF to_jsonb(NEW)-ARRAY['state','dispatch_token','dispatched_at_ms','observation','observation_bytes','observation_digest'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','dispatch_token','dispatched_at_ms','observation','observation_bytes','observation_digest']
  THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-IMMUTABLE'; END IF;
  IF OLD.state='PREPARED' AND NEW.state='DISPATCHED' THEN
   PERFORM openpc.check_notification_cancellation_signing_current(NEW);
   IF NEW.dispatched_at_ms IS DISTINCT FROM floor(extract(epoch from statement_timestamp())*1000)
   THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-TIME'; END IF;
  ELSIF OLD.state='DISPATCHED' AND NEW.state='OBSERVED' THEN
   IF NEW.dispatch_token IS DISTINCT FROM OLD.dispatch_token OR NEW.dispatched_at_ms IS DISTINCT FROM OLD.dispatched_at_ms THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-CLAIM'; END IF;
  ELSE RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNING-ONE-SHOT'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_cancellation_signer(operation uuid,transition_digest text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.notification_cancellation_signing%ROWTYPE;actual jsonb;
BEGIN
 SELECT * INTO STRICT s FROM control.notification_cancellation_signing WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND operation_id=operation;
 PERFORM openpc.check_notification_cancellation_signing_original(s);
 IF s.state<>'OBSERVED' OR s.observation->>'outcome' IS DISTINCT FROM 'SIGNED' THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNER-UNBOUND'; END IF;
 actual:=(s.preparation->'input')||jsonb_build_object('coseHex',s.observation->'coseHex');
 IF transition_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(actual),'UTF8')),'hex') THEN RAISE EXCEPTION 'NOTIFICATION-CANCELLATION-SIGNER-ORIGINAL'; END IF;
END $$;
DROP TRIGGER IF EXISTS notification_cancel_signing_guard ON control.notification_cancellation_signing;
CREATE TRIGGER notification_cancel_signing_guard BEFORE INSERT OR UPDATE ON control.notification_cancellation_signing FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_cancellation_signing();
DROP TRIGGER IF EXISTS notification_cancel_signing_immutable ON control.notification_cancellation_signing;
CREATE TRIGGER notification_cancel_signing_immutable BEFORE DELETE OR TRUNCATE ON control.notification_cancellation_signing FOR EACH STATEMENT EXECUTE FUNCTION openpc.deny_notification_delivery_cancellation_mutation();
REVOKE ALL ON FUNCTION openpc.check_notification_cancellation_signing_original(control.notification_cancellation_signing),openpc.check_notification_cancellation_signing_current(control.notification_cancellation_signing),openpc.guard_notification_cancellation_signing(),openpc.check_notification_delivery_cancellation_signer(uuid,text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION openpc.assert_notification_delivery_cancellation_owner(),
 openpc.check_notification_delivery_cancellation_original(control.notification_delivery_cancellation),
 openpc.check_notification_delivery_cancellation_projection(control.notification_delivery,control.notification_delivery),
 openpc.check_notification_delivery_cancellation_complete(uuid),
 openpc.check_notification_cancellation_signing_original(control.notification_cancellation_signing),
 openpc.check_notification_cancellation_signing_current(control.notification_cancellation_signing),
 openpc.check_notification_delivery_cancellation_signer(uuid,text) TO openpc_control_runtime;

