CREATE OR REPLACE FUNCTION openpc.check_notification_outcome_signing_current(item control.notification_delivery_outcome_signing) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE d control.notification_delivery%ROWTYPE;signer control.notification_receipt_signer_installation%ROWTYPE;wm jsonb;now_ms numeric;lock_name text;
BEGIN
 PERFORM openpc.assert_notification_outcome_signing_owner();PERFORM openpc.check_notification_outcome_signing_original(item);
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND notification_occurrence_id=item.notification_occurrence_id FOR UPDATE;
 IF d.revision<>item.delivery_revision OR jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested) IS DISTINCT FROM item.preparation->'preparation'->'input'->'current'->'snapshot'
 OR EXISTS(SELECT 1 FROM control.notification_delivery_observation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND attempt_id=item.attempt_id)
 OR EXISTS(SELECT 1 FROM control.notification_delivery_outcome_signing WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND attempt_id=item.attempt_id AND operation_id<>item.operation_id)
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-STALE'; END IF;
 PERFORM 1 FROM control.notification_delivery_dispatch_intent WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=item.start_operation_id FOR UPDATE;
 lock_name:='notification-receipt-signer:'||item.participant_id::text||':'||item.privacy_domain_id::text;
 IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype='advisory' AND l.granted AND l.mode='ShareLock'
 AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1)
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-FENCE'; END IF;
 SELECT * INTO STRICT signer FROM control.notification_receipt_signer_installation WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND trust_digest=item.signer_installation_digest AND state='ACTIVE';
 SELECT openpc.business_cbor(decode(installation->'signed'->>'payloadHex','hex')) INTO STRICT wm FROM control.installed_notification_worker
 WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=signer.worker_installation_digest;
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF now_ms<(wm->>'6')::numeric OR now_ms>=(wm->>'7')::numeric OR now_ms*1000000<(signer.trust->>'validFromNs')::numeric OR now_ms*1000000>=(signer.trust->>'validUntilNs')::numeric
 OR now_ms<(item.preparation->'preparation'->'metadata'->>'recordedAtMs')::numeric
 OR NOT EXISTS(SELECT 1 FROM control.installed_notification_worker w JOIN control.credential c ON c.participant_id=w.participant_id AND c.credential_id=w.workload_credential_id
  JOIN control.principal p ON p.participant_id=c.participant_id AND p.principal_id=c.principal_id
  WHERE w.participant_id=item.participant_id AND w.privacy_domain_id=item.privacy_domain_id AND w.installation_digest=signer.worker_installation_digest AND w.state='ACTIVE'
  AND c.state='ACTIVE' AND c.kind='WORKLOAD_MTLS' AND c.credential_epoch::text=signer.trust->>'workloadEpoch'
  AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp() AND p.state='ACTIVE' AND p.kind='WORKLOAD')
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-AUTHORITY'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_outcome_signing() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_notification_outcome_signing_owner();PERFORM openpc.check_notification_outcome_signing_original(NEW);
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-INITIAL'; END IF;
  PERFORM openpc.check_notification_outcome_signing_current(NEW);
 ELSE
  IF to_jsonb(NEW)-ARRAY['state','dispatch_token','dispatched_at_ms','observation_bytes','observation_digest'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','dispatch_token','dispatched_at_ms','observation_bytes','observation_digest']
  THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-IMMUTABLE'; END IF;
  IF OLD.state='PREPARED' AND NEW.state='DISPATCHED' THEN
   PERFORM openpc.check_notification_outcome_signing_current(NEW);
   IF NEW.dispatched_at_ms IS DISTINCT FROM floor(extract(epoch from statement_timestamp())*1000) THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-TIME'; END IF;
  ELSIF OLD.state='DISPATCHED' AND NEW.state='OBSERVED' THEN
   IF NEW.dispatch_token IS DISTINCT FROM OLD.dispatch_token OR NEW.dispatched_at_ms IS DISTINCT FROM OLD.dispatched_at_ms THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-CLAIM'; END IF;
  ELSE RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SIGNING-ONE-SHOT'; END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_outcome_signing_guard ON control.notification_delivery_outcome_signing;
CREATE TRIGGER notification_outcome_signing_guard BEFORE INSERT OR UPDATE ON control.notification_delivery_outcome_signing FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_outcome_signing();
DROP TRIGGER IF EXISTS notification_outcome_signing_immutable ON control.notification_delivery_outcome_signing;
CREATE TRIGGER notification_outcome_signing_immutable BEFORE DELETE OR TRUNCATE ON control.notification_delivery_outcome_signing FOR EACH STATEMENT EXECUTE FUNCTION openpc.deny_notification_delivery_outcome_mutation();
REVOKE ALL ON FUNCTION openpc.assert_notification_outcome_signing_owner(),openpc.check_notification_outcome_signing_original(control.notification_delivery_outcome_signing),openpc.check_notification_outcome_signing_current(control.notification_delivery_outcome_signing),openpc.guard_notification_outcome_signing() FROM PUBLIC;

GRANT EXECUTE ON FUNCTION openpc.check_notification_delivery_observation_original(control.notification_delivery_observation),
 openpc.assert_notification_outcome_signing_owner(),
 openpc.check_notification_outcome_signing_original(control.notification_delivery_outcome_signing),
 openpc.check_notification_outcome_signing_current(control.notification_delivery_outcome_signing) TO openpc_control_runtime;
-- Durable signing and final publication have distinct checked owners.
GRANT INSERT,UPDATE ON control.notification_delivery_outcome_signing TO openpc_control_runtime;
DROP TRIGGER IF EXISTS notification_outcome_closed ON control.notification_delivery_outcome_signing;

CREATE OR REPLACE FUNCTION openpc.enforce_work_item_lifecycle()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path = pg_catalog AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.work_item';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."state" <> 'OPEN' OR NEW."row_version" <> 1
       OR NEW."claimed_by_principal_id" IS NOT NULL OR NEW."completed_by_principal_id" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item initial state';
    END IF;
    -- Public remediation creation keeps its business receipt owner. Every
    -- internal remediation insert must instead prove native completion custody;
    -- context chooses the checker, never supplies its authorization.
    IF openpc.current_action_intent_id()='ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
      OR (NEW.kind='REMEDIATION' AND openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-WORK_ITEMS_CREATE_RESOURCE-V1') THEN
      PERFORM openpc.check_notification_completion_remediation_effect(NEW);
    END IF;
    IF current_setting('openpc.action_intent_id',true)='ACT-EVIDENCE_EXPORT_RECORDS-V1' AND NEW.kind='DELIVERY_FAILURE' THEN
      PERFORM openpc.check_notification_delivery_failure_work(NEW);
    END IF;
    RETURN NEW;
  END IF;
  IF row(NEW."work_item_id",NEW."participant_id",NEW."privacy_domain_id",NEW."kind",
         NEW."resource_ref",NEW."created_by_principal_id",NEW."created_at")
     IS DISTINCT FROM
     row(OLD."work_item_id",OLD."participant_id",OLD."privacy_domain_id",OLD."kind",
         OLD."resource_ref",OLD."created_by_principal_id",OLD."created_at") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.work_item identity';
  END IF;
  IF NOT ((OLD."state" = 'OPEN' AND NEW."state" = 'OPEN')
          OR (OLD."state" = 'OPEN' AND NEW."state" = 'CLAIMED')
          OR (OLD."state" = 'CLAIMED' AND NEW."state" = 'COMPLETED')
          OR (OLD."state" IN ('OPEN','CLAIMED') AND NEW."state" = 'CANCELLED')) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6022-INVALID-STATE-TRANSITION', DETAIL = 'control.work_item lifecycle';
  END IF;
  IF NEW."assignee_principal_id" IS DISTINCT FROM OLD."assignee_principal_id"
     AND NOT (OLD."state" = 'OPEN' AND NEW."state" = 'CLAIMED'
              AND OLD."assignee_principal_id" IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6020-IMMUTABLE-ROW', DETAIL = 'control.work_item assignee';
  END IF;
  IF NEW."row_version" <> OLD."row_version" + 1 OR NEW."updated_at" <= OLD."updated_at" THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item revision';
  END IF;
  IF NEW."state" = 'OPEN' AND
     (NEW."claimed_by_principal_id" IS NOT NULL OR NEW."completed_by_principal_id" IS NOT NULL) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item open actor';
  ELSIF NEW."state" = 'CLAIMED' AND
        (NEW."claimed_by_principal_id" IS NULL OR NEW."completed_by_principal_id" IS NOT NULL
         OR NEW."assignee_principal_id" IS DISTINCT FROM NEW."claimed_by_principal_id") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item claim actor';
  ELSIF NEW."state" = 'COMPLETED' AND
        (NEW."claimed_by_principal_id" IS NULL OR NEW."completed_by_principal_id" IS NULL
         OR NEW."completed_by_principal_id" IS DISTINCT FROM NEW."claimed_by_principal_id"
         OR NEW."assignee_principal_id" IS DISTINCT FROM NEW."completed_by_principal_id") THEN
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'DATA-6021-INCOMPLETE-SECURITY-RECORD', DETAIL = 'control.work_item completion actor';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS work_item_lifecycle ON "control"."work_item";
CREATE TRIGGER work_item_lifecycle BEFORE INSERT OR UPDATE OR DELETE ON "control"."work_item"
FOR EACH ROW EXECUTE FUNCTION openpc.enforce_work_item_lifecycle();


CREATE OR REPLACE FUNCTION openpc.assert_notification_outcome_publication_owner() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_notification_outcome_signing_owner();
 PERFORM openpc.assert_notification_outcome_publication_shared_owners();
 IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_outcome'::regclass AND tgname='notification_outcome_publication_complete' AND tgfoid='openpc.guard_notification_outcome_publication_complete()'::regprocedure AND tgenabled IN ('O','A') AND tgtype=5 AND tgdeferrable AND tginitdeferred)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_outcome'::regclass AND tgname='notification_outcome_publication_insert' AND tgfoid='openpc.guard_notification_outcome_publication_insert()'::regprocedure AND tgenabled IN ('O','A') AND tgtype=7)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_delivery_observation'::regclass AND tgname='notification_outcome_observation_insert' AND tgfoid='openpc.guard_notification_outcome_observation_insert()'::regprocedure AND tgenabled IN ('O','A') AND tgtype=7)
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PUBLICATION-OWNER'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_outcome_publication_receipt(item control.notification_delivery_outcome) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.notification_delivery_outcome_signing%ROWTYPE;m jsonb;r jsonb;t jsonb:=item.transition;o jsonb;
BEGIN
 IF item.participant_id IS DISTINCT FROM openpc.current_participant_id() OR item.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id() THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PUBLICATION-SCOPE'; END IF;
 SELECT * INTO STRICT s FROM control.notification_delivery_outcome_signing WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND operation_id=item.operation_id;
 PERFORM openpc.check_notification_outcome_signing_original(s);
 o:=convert_from(s.observation_bytes,'UTF8')::jsonb;m:=openpc.business_cbor(item.receipt_payload);r:=jsonb_build_object('environmentId',m->'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'receiptId',(m->'4'->>'bytes')::uuid::text,'operationId',(m->'5'->>'bytes')::uuid::text,'notificationOccurrenceId',(m->'6'->>'bytes')::uuid::text,'attemptId',(m->'7'->>'bytes')::uuid::text,'startOperationId',(m->'8'->>'bytes')::uuid::text,'startReceiptDigest','sha256:'||(m->'9'->>'bytes'),'dispatchClaimDigest','sha256:'||(m->'10'->>'bytes'),'sourceReceiptDigest','sha256:'||(m->'11'->>'bytes'),'workerProfileDigest','sha256:'||(m->'12'->>'bytes'),'routingProfileDigest','sha256:'||(m->'13'->>'bytes'),'authoritySnapshotDigest','sha256:'||(m->'14'->>'bytes'),'endpointId',(m->'15'->>'bytes')::uuid::text,'endpointRevision',m->>'16','payloadDigest','sha256:'||(m->'17'->>'bytes'),'gatewayReceiptId',(m->'18'->>'bytes')::uuid::text,'gatewayReceiptDigest','sha256:'||(m->'19'->>'bytes'),'gatewayCoseDigest','sha256:'||(m->'20'->>'bytes'),'observationDigest','sha256:'||(m->'21'->>'bytes'),'deliveryRevision',m->>'22','beforeStateDigest','sha256:'||(m->'23'->>'bytes'),'afterStateDigest','sha256:'||(m->'24'->>'bytes'),'outcome',CASE m->>'25' WHEN '1' THEN 'DELIVERED' WHEN '2' THEN 'RETRYABLE_NO_EFFECT' WHEN '3' THEN 'PERMANENT_FAILURE' WHEN '4' THEN 'AMBIGUOUS' ELSE NULL END,'beforeDeliveryState',CASE m->>'26' WHEN '1' THEN 'STARTED' WHEN '2' THEN 'AMBIGUOUS' ELSE NULL END,'afterDeliveryState',CASE m->>'27' WHEN '1' THEN 'DELIVERED' WHEN '2' THEN 'FAILED' WHEN '3' THEN 'AMBIGUOUS' WHEN '4' THEN 'CANCELLED' WHEN '5' THEN 'RETRY_WAIT' ELSE NULL END,'attemptCount',(m->>'28')::numeric,'attemptLimit',(m->>'29')::numeric,'nextAttemptAtMs',(m->>'30')::numeric,'cancelRequested',CASE m->>'31' WHEN '0' THEN 'NO' WHEN '1' THEN 'YES' ELSE NULL END,'observedAtMs',(m->>'32')::numeric,'recordedAtMs',(m->>'33')::numeric,'signerKeyId','sha256:'||(m->'34'->>'bytes'));
 IF s.state IS DISTINCT FROM 'OBSERVED' OR o->>'outcome' IS DISTINCT FROM 'SIGNED'
 OR item.transition_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(t),'UTF8') OR item.transition_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(t),'UTF8')),'hex')
 OR t IS DISTINCT FROM (s.preparation->'preparation')||jsonb_build_object('schema','pc.notification.delivery-outcome-transition.v1','receipt',r,'payloadHex',s.preparation->'request'->>'payloadHex','coseHex',o->>'coseHex')
 OR item.receipt_payload IS DISTINCT FROM decode(s.preparation->'request'->>'payloadHex','hex') OR item.receipt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(item.receipt_payload),'hex')
 OR item.cose_sign1 IS DISTINCT FROM decode(o->>'coseHex','hex') OR item.receipt_id<>s.signing_attempt_id OR item.attempt_id<>s.attempt_id OR item.start_operation_id<>s.start_operation_id
 OR item.notification_occurrence_id<>s.notification_occurrence_id OR item.payload_digest<>s.payload_digest OR item.delivery_revision<>s.delivery_revision
 OR item.signer_installation_digest<>s.signer_installation_digest OR item.worker_installation_digest IS DISTINCT FROM s.preparation->'request'->>'workerInstallationDigest'
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PUBLICATION-RECEIPT'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_completed_event(e control.outbox_event) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE o control.notification_delivery_outcome%ROWTYPE;r jsonb;data jsonb;
BEGIN
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=e.participant_id AND privacy_domain_id=e.privacy_domain_id AND operation_id=e.correlation_id;
 PERFORM openpc.check_notification_outcome_publication_receipt(o);r:=o.transition->'receipt';
 data:=jsonb_build_object('0','urn:openpc:resource:'||o.notification_occurrence_id::text,'1',r->>'afterDeliveryState','2',(r->>'attemptCount')::numeric,'3',openpc.business_bytes(decode(substr(r->>'gatewayCoseDigest',8),'hex')));
 IF (r->>'afterDeliveryState' IN ('DELIVERED','FAILED')) IS DISTINCT FROM true
 OR e.event_id<>o.receipt_id OR e.event_type<>'io.openpc.notification.delivery.completed.v1' OR e.aggregate_type<>'notification-occurrence' OR e.aggregate_id<>o.notification_occurrence_id
 OR e.proof_kind<>'NOTIFICATION_DELIVERY_COMPLETION_REFERENCE' OR e.sequence_namespace<>'NOTIFICATION_DELIVERY_COMPLETED_V1' OR e.business_sequence IS DISTINCT FROM 1
 OR e.aggregate_sequence IS NOT NULL OR e.receipt_id IS NOT NULL OR e.cose_sign1 IS NOT NULL OR e.authority_generation IS NOT NULL OR e.webauthn_assertion_binding_digest IS NOT NULL
 OR e.source IS DISTINCT FROM 'urn:openpc:service:LS-NOTIFICATION' OR e.subject IS DISTINCT FROM 'urn:openpc:resource:'||o.notification_occurrence_id::text
 OR e.data_schema_uri IS DISTINCT FROM 'https://schemas.openpc.local/event-payloads.schema.json#/$defs/NotificationDeliveryCompleted'
 OR e.causation_id::text IS DISTINCT FROM o.transition->'input'->'observation'->'original'->'source'->>'eventId'
 OR extract(epoch from e.occurred_at)*1000 IS DISTINCT FROM (r->>'recordedAtMs')::numeric
 OR e.payload_digest IS DISTINCT FROM sha256(e.payload_cbor) OR openpc.business_cbor(e.payload_cbor) IS DISTINCT FROM data
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PUBLICATION-EVENT'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.notification_failure_initial_projection(o control.notification_delivery_outcome) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE w control.installed_notification_worker%ROWTYPE;
BEGIN
 PERFORM openpc.check_notification_outcome_publication_receipt(o);
 IF o.transition->'receipt'->>'afterDeliveryState' IS DISTINCT FROM 'FAILED' THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-NOT-FAILED'; END IF;
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=o.participant_id AND privacy_domain_id=o.privacy_domain_id AND installation_digest=o.worker_installation_digest;
 RETURN jsonb_build_object('0','DELIVERY_FAILURE','1','OPEN','2','urn:openpc:resource:'||o.notification_occurrence_id::text,'3',openpc.business_bytes(decode(substr(o.receipt_digest,8),'hex')),
 '4',openpc.business_bytes(sha256(convert_to('Notification delivery failed.','UTF8'))),'5',openpc.business_uuid(w.principal_id),'6',0,'8',0,'10',0);
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_failure_work(item control.work_item) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE o control.notification_delivery_outcome%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_outcome_publication_owner();
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND receipt_id=item.work_item_id;
 IF item.row_version<>1 OR openpc.work_item_business_projection(item) IS DISTINCT FROM openpc.notification_failure_initial_projection(o)
 OR (SELECT count(*) FROM control.work_item WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND work_item_id=item.work_item_id)<>0
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-FAILURE-WORK'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_outcome_publication_original(operation uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE o control.notification_delivery_outcome%ROWTYPE;first control.notification_delivery_observation%ROWTYPE;e control.outbox_event%ROWTYPE;w control.work_item%ROWTYPE;a control.audit_occurrence%ROWTYPE;native jsonb;expected jsonb;
BEGIN
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND operation_id=operation;
 PERFORM openpc.check_notification_outcome_publication_receipt(o);
 SELECT * INTO STRICT first FROM control.notification_delivery_observation WHERE participant_id=o.participant_id AND privacy_domain_id=o.privacy_domain_id AND attempt_id=o.attempt_id;
 PERFORM openpc.check_notification_delivery_observation_original(first);native:=o.transition->'input'->'observation'->'observation';
 IF first.operation_id<>o.operation_id OR first.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(native),'UTF8') OR first.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(native),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PUBLICATION-FIRST'; END IF;
 IF o.transition->'receipt'->>'afterDeliveryState' IN ('DELIVERED','FAILED') THEN
  SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=o.participant_id AND privacy_domain_id=o.privacy_domain_id AND sequence_namespace='NOTIFICATION_DELIVERY_COMPLETED_V1' AND aggregate_type='notification-occurrence' AND aggregate_id=o.notification_occurrence_id;
  PERFORM openpc.check_notification_delivery_completed_event(e);
  IF e.correlation_id<>o.operation_id THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PUBLICATION-EVENT'; END IF;
 ELSIF EXISTS(SELECT 1 FROM control.outbox_event WHERE participant_id=o.participant_id AND privacy_domain_id=o.privacy_domain_id AND (event_id=o.receipt_id OR (sequence_namespace='NOTIFICATION_DELIVERY_COMPLETED_V1' AND correlation_id=o.operation_id)))
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-UNEXPECTED-EVENT'; END IF;
 IF o.transition->'receipt'->>'afterDeliveryState'='FAILED' THEN
  SELECT * INTO STRICT w FROM control.work_item WHERE participant_id=o.participant_id AND privacy_domain_id=o.privacy_domain_id AND work_item_id=o.receipt_id;
  IF w.work_item_id<>o.receipt_id THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-WORK-ID'; END IF;
  expected:=openpc.notification_failure_initial_projection(o);
  IF w.row_version=1 THEN
   IF openpc.work_item_business_projection(w) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-WORK-PROJECTION'; END IF;
  ELSE
   -- Later public WorkItem updates retain their first independently admitted
   -- before-state. Do not demand that the current human-owned row stays OPEN.
   SELECT * INTO STRICT a FROM control.audit_occurrence WHERE participant_id=o.participant_id AND privacy_domain_id=o.privacy_domain_id AND aggregate_type='work-item' AND aggregate_id=w.work_item_id AND before_revision=1;
   IF a.before_existence<>1 OR a.before_state_digest<>sha256(a.before_state_preimage) OR a.receipt_digest<>sha256(a.receipt_cbor)
    OR openpc.business_cbor(a.receipt_cbor)->'18' IS DISTINCT FROM jsonb_build_object('0',1,'1',1,'2',openpc.business_bytes(a.before_state_digest))
    OR openpc.business_cbor(a.before_state_preimage)->8 IS DISTINCT FROM expected THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-WORK-PROVENANCE'; END IF;
  END IF;
 ELSIF EXISTS(SELECT 1 FROM control.work_item WHERE participant_id=o.participant_id AND privacy_domain_id=o.privacy_domain_id AND work_item_id=o.receipt_id)
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-UNEXPECTED-WORK'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_delivery_outcome_projection(before_row control.notification_delivery,after_row control.notification_delivery) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE o control.notification_delivery_outcome%ROWTYPE;r jsonb;expected jsonb;digest text;
BEGIN
 PERFORM openpc.assert_notification_outcome_publication_owner();
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=before_row.participant_id AND privacy_domain_id=before_row.privacy_domain_id AND notification_occurrence_id=before_row.notification_occurrence_id AND delivery_revision=before_row.revision;
 PERFORM openpc.check_notification_outcome_publication_receipt(o);r:=o.transition->'receipt';
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',before_row.revision::text,'projection',jsonb_build_object('participantId',before_row.participant_id::text,'privacyDomainId',before_row.privacy_domain_id::text,'notificationOccurrenceId',before_row.notification_occurrence_id::text,'payloadDigest',before_row.payload_digest,'state',before_row.state,'attemptCount',before_row.attempt_count,'attemptLimit',before_row.attempt_limit,'nextAttemptAtMs',before_row.next_attempt_at_ms,'lastStartedAtMs',before_row.last_started_at_ms,'cancelRequested',before_row.cancel_requested));digest:='sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex');
 IF digest IS DISTINCT FROM r->>'beforeStateDigest' OR after_row.revision<>before_row.revision+1
 OR to_jsonb(after_row)-ARRAY['state','attempt_limit','next_attempt_at_ms','revision'] IS DISTINCT FROM to_jsonb(before_row)-ARRAY['state','attempt_limit','next_attempt_at_ms','revision']
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PROJECTION-BEFORE'; END IF;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',after_row.revision::text,'projection',jsonb_build_object('participantId',after_row.participant_id::text,'privacyDomainId',after_row.privacy_domain_id::text,'notificationOccurrenceId',after_row.notification_occurrence_id::text,'payloadDigest',after_row.payload_digest,'state',after_row.state,'attemptCount',after_row.attempt_count,'attemptLimit',after_row.attempt_limit,'nextAttemptAtMs',after_row.next_attempt_at_ms,'lastStartedAtMs',after_row.last_started_at_ms,'cancelRequested',after_row.cancel_requested));
 IF 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') IS DISTINCT FROM r->>'afterStateDigest' THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PROJECTION-AFTER'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_outcome_publication_complete(operation uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE o control.notification_delivery_outcome%ROWTYPE;d control.notification_delivery%ROWTYPE;expected jsonb;
BEGIN
 PERFORM openpc.check_notification_outcome_publication_original(operation);
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND operation_id=operation;
 SELECT * INTO STRICT d FROM control.notification_delivery WHERE participant_id=o.participant_id AND privacy_domain_id=o.privacy_domain_id AND notification_occurrence_id=o.notification_occurrence_id;
 expected:=jsonb_build_object('schema','pc.notification-delivery.state.v1','revision',d.revision::text,'projection',jsonb_build_object('participantId',d.participant_id::text,'privacyDomainId',d.privacy_domain_id::text,'notificationOccurrenceId',d.notification_occurrence_id::text,'payloadDigest',d.payload_digest,'state',d.state,'attemptCount',d.attempt_count,'attemptLimit',d.attempt_limit,'nextAttemptAtMs',d.next_attempt_at_ms,'lastStartedAtMs',d.last_started_at_ms,'cancelRequested',d.cancel_requested));
 IF d.revision<>o.delivery_revision+1 OR 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(expected),'UTF8')),'hex') IS DISTINCT FROM o.transition->'receipt'->>'afterStateDigest' THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PUBLICATION-INCOMPLETE'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_outcome_publication_insert() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.notification_delivery_outcome_signing%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_outcome_publication_owner();PERFORM openpc.check_notification_outcome_publication_receipt(NEW);
 SELECT * INTO STRICT s FROM control.notification_delivery_outcome_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.operation_id;
 PERFORM openpc.check_notification_outcome_signing_current(s);
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_outcome_observation_insert() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE o control.notification_delivery_outcome%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_outcome_publication_owner();PERFORM openpc.check_notification_delivery_observation_original(NEW);
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.operation_id;
 PERFORM openpc.check_notification_outcome_publication_receipt(o);
 IF NEW.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(o.transition->'input'->'observation'->'observation'),'UTF8') THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-PUBLICATION-FIRST'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_outcome_publication_complete() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN PERFORM openpc.check_notification_outcome_publication_complete(NEW.operation_id);RETURN NEW;END $$;
DROP TRIGGER IF EXISTS notification_outcome_publication_insert ON control.notification_delivery_outcome;
CREATE TRIGGER notification_outcome_publication_insert BEFORE INSERT ON control.notification_delivery_outcome FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_outcome_publication_insert();
DROP TRIGGER IF EXISTS notification_outcome_observation_insert ON control.notification_delivery_observation;
CREATE TRIGGER notification_outcome_observation_insert BEFORE INSERT ON control.notification_delivery_observation FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_outcome_observation_insert();
DROP TRIGGER IF EXISTS notification_outcome_publication_complete ON control.notification_delivery_outcome;
CREATE CONSTRAINT TRIGGER notification_outcome_publication_complete AFTER INSERT ON control.notification_delivery_outcome DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_outcome_publication_complete();
REVOKE ALL ON FUNCTION openpc.assert_notification_outcome_publication_owner(),openpc.check_notification_outcome_publication_receipt(control.notification_delivery_outcome),openpc.check_notification_delivery_completed_event(control.outbox_event),openpc.notification_failure_initial_projection(control.notification_delivery_outcome),openpc.check_notification_delivery_failure_work(control.work_item),openpc.check_notification_outcome_publication_original(uuid),openpc.check_notification_delivery_outcome_projection(control.notification_delivery,control.notification_delivery),openpc.check_notification_outcome_publication_complete(uuid),openpc.guard_notification_outcome_publication_insert(),openpc.guard_notification_outcome_observation_insert(),openpc.guard_notification_outcome_publication_complete() FROM PUBLIC;


CREATE OR REPLACE FUNCTION openpc.guard_notification_failure_work_complete() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE operation uuid;
BEGIN
 SELECT operation_id INTO STRICT operation FROM control.notification_delivery_outcome
 WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.work_item_id;
 PERFORM openpc.check_notification_outcome_publication_original(operation);
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_failure_work_complete ON control.work_item;
CREATE CONSTRAINT TRIGGER notification_failure_work_complete AFTER INSERT ON control.work_item
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
 WHEN (NEW.kind='DELIVERY_FAILURE' AND current_setting('openpc.action_intent_id',true)='ACT-EVIDENCE_EXPORT_RECORDS-V1')
 EXECUTE FUNCTION openpc.guard_notification_failure_work_complete();

CREATE OR REPLACE FUNCTION openpc.assert_notification_outcome_publication_shared_owners() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 JOIN pg_trigger t ON t.tgfoid=p.oid
 WHERE n.nspname='openpc' AND p.proname='guard_business_outbox' AND p.pronargs=0
 AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND NOT p.prosecdef
 AND p.prorettype='trigger'::regtype AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog']
 AND p.prosrc='
DECLARE receipt control.audit_occurrence%ROWTYPE; payload jsonb;
BEGIN
 IF NEW.proof_kind=''LEGACY'' THEN RETURN NEW; END IF;
 -- This distinct namespace is fail-closed until the Control export owner installs
 -- its exact receipt/source/outbox checker. It cannot enter command receipt admission.
 IF NEW.proof_kind=''EVIDENCE_EXPORT_COMPLETION_REFERENCE'' THEN
  PERFORM openpc.check_evidence_export_completion_event(NEW);
  RETURN NEW;
 END IF;
 -- A distinct registered family: the owning checker must exist and validate
 -- actual original receipts, source, occurrence, payload references and cursors.
 -- Any missing owner or denial propagates; there is no command-receipt fallback.
 IF NEW.proof_kind=''NOTIFICATION_DELIVERY_REQUEST_REFERENCE'' THEN
  PERFORM openpc.check_notification_delivery_requested_event(NEW);
  RETURN NEW;
 END IF;
 -- Terminal native outcomes have a separate source-owned proof. A request
 -- receipt cannot authorize completion; missing final publication stays closed.
 IF NEW.proof_kind=''NOTIFICATION_DELIVERY_COMPLETION_REFERENCE'' THEN
  PERFORM openpc.check_notification_delivery_completed_event(NEW);
  RETURN NEW;
 END IF;
 IF NEW.proof_kind<>''BUSINESS_RECEIPT_REFERENCE'' THEN RAISE EXCEPTION ''DATA-6021-UNADMITTED-OUTBOX-PROOF''; END IF;
 SELECT * INTO STRICT receipt FROM control.audit_occurrence WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.receipt_id;
 payload:=openpc.business_cbor(NEW.payload_cbor);
 IF receipt.aggregate_type=''signing-key-rotation'' THEN
  PERFORM openpc.check_signing_rotation_event(NEW,receipt);
  RETURN NEW;
 END IF;
 IF NEW.aggregate_type<>receipt.aggregate_type OR NEW.aggregate_id<>receipt.aggregate_id OR
    NEW.payload_digest<>sha256(NEW.payload_cbor) OR NEW.event_type<>''io.openpc.control.command.committed.v1'' OR
    NEW.data_schema_uri<>''https://schemas.openpc.local/event-payloads.schema.json#/$defs/CommandCommitted'' OR
    payload IS DISTINCT FROM jsonb_build_object(''0'',openpc.business_uuid(receipt.operation_id),
      ''1'',''urn:openpc:''||receipt.aggregate_type||'':''||receipt.aggregate_id::text,
      ''2'',receipt.action_intent_id,''3'',openpc.business_bytes(receipt.action_intent_digest)) THEN
   RAISE EXCEPTION ''DATA-6021-OUTBOX-RECEIPT-PAYLOAD''; END IF;
 RETURN NEW;
END '
 AND t.tgrelid='control.outbox_event'::regclass AND t.tgname='business_outbox_payload' AND t.tgtype=7
 AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND t.tgqual IS NULL)
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 JOIN pg_trigger t ON t.tgfoid=p.oid
 WHERE n.nspname='openpc' AND p.proname='enforce_work_item_lifecycle' AND p.pronargs=0
 AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND NOT p.prosecdef
 AND p.prorettype='trigger'::regtype AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog']
 AND p.prosrc='
BEGIN
  IF TG_OP = ''DELETE'' THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6020-IMMUTABLE-ROW'', DETAIL = ''control.work_item'';
  END IF;
  IF TG_OP = ''INSERT'' THEN
    IF NEW."state" <> ''OPEN'' OR NEW."row_version" <> 1
       OR NEW."claimed_by_principal_id" IS NOT NULL OR NEW."completed_by_principal_id" IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6021-INCOMPLETE-SECURITY-RECORD'', DETAIL = ''control.work_item initial state'';
    END IF;
    -- Public remediation creation keeps its business receipt owner. Every
    -- internal remediation insert must instead prove native completion custody;
    -- context chooses the checker, never supplies its authorization.
    IF openpc.current_action_intent_id()=''ACT-POLICY_READ_EFFECTIVE_ACCESS-V1''
      OR (NEW.kind=''REMEDIATION'' AND openpc.current_action_intent_id() IS DISTINCT FROM ''ACT-WORK_ITEMS_CREATE_RESOURCE-V1'') THEN
      PERFORM openpc.check_notification_completion_remediation_effect(NEW);
    END IF;
    IF current_setting(''openpc.action_intent_id'',true)=''ACT-EVIDENCE_EXPORT_RECORDS-V1'' AND NEW.kind=''DELIVERY_FAILURE'' THEN
      PERFORM openpc.check_notification_delivery_failure_work(NEW);
    END IF;
    RETURN NEW;
  END IF;
  IF row(NEW."work_item_id",NEW."participant_id",NEW."privacy_domain_id",NEW."kind",
         NEW."resource_ref",NEW."created_by_principal_id",NEW."created_at")
     IS DISTINCT FROM
     row(OLD."work_item_id",OLD."participant_id",OLD."privacy_domain_id",OLD."kind",
         OLD."resource_ref",OLD."created_by_principal_id",OLD."created_at") THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6020-IMMUTABLE-ROW'', DETAIL = ''control.work_item identity'';
  END IF;
  IF NOT ((OLD."state" = ''OPEN'' AND NEW."state" = ''OPEN'')
          OR (OLD."state" = ''OPEN'' AND NEW."state" = ''CLAIMED'')
          OR (OLD."state" = ''CLAIMED'' AND NEW."state" = ''COMPLETED'')
          OR (OLD."state" IN (''OPEN'',''CLAIMED'') AND NEW."state" = ''CANCELLED'')) THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6022-INVALID-STATE-TRANSITION'', DETAIL = ''control.work_item lifecycle'';
  END IF;
  IF NEW."assignee_principal_id" IS DISTINCT FROM OLD."assignee_principal_id"
     AND NOT (OLD."state" = ''OPEN'' AND NEW."state" = ''CLAIMED''
              AND OLD."assignee_principal_id" IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6020-IMMUTABLE-ROW'', DETAIL = ''control.work_item assignee'';
  END IF;
  IF NEW."row_version" <> OLD."row_version" + 1 OR NEW."updated_at" <= OLD."updated_at" THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6021-INCOMPLETE-SECURITY-RECORD'', DETAIL = ''control.work_item revision'';
  END IF;
  IF NEW."state" = ''OPEN'' AND
     (NEW."claimed_by_principal_id" IS NOT NULL OR NEW."completed_by_principal_id" IS NOT NULL) THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6021-INCOMPLETE-SECURITY-RECORD'', DETAIL = ''control.work_item open actor'';
  ELSIF NEW."state" = ''CLAIMED'' AND
        (NEW."claimed_by_principal_id" IS NULL OR NEW."completed_by_principal_id" IS NOT NULL
         OR NEW."assignee_principal_id" IS DISTINCT FROM NEW."claimed_by_principal_id") THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6021-INCOMPLETE-SECURITY-RECORD'', DETAIL = ''control.work_item claim actor'';
  ELSIF NEW."state" = ''COMPLETED'' AND
        (NEW."claimed_by_principal_id" IS NULL OR NEW."completed_by_principal_id" IS NULL
         OR NEW."completed_by_principal_id" IS DISTINCT FROM NEW."claimed_by_principal_id"
         OR NEW."assignee_principal_id" IS DISTINCT FROM NEW."completed_by_principal_id") THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''DATA-6021-INCOMPLETE-SECURITY-RECORD'', DETAIL = ''control.work_item completion actor'';
  END IF;
  RETURN NEW;
END '
 AND t.tgrelid='control.work_item'::regclass AND t.tgname='work_item_lifecycle' AND t.tgtype=31
 AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND t.tgqual IS NULL)
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 JOIN pg_trigger t ON t.tgfoid=p.oid
 WHERE n.nspname='openpc' AND p.proname='guard_notification_delivery_budget' AND p.pronargs=0
 AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql' AND NOT p.prosecdef
 AND p.prorettype='trigger'::regtype AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=pg_catalog']
 AND p.prosrc='
DECLARE occurrence control.notification_occurrence%ROWTYPE; event control.outbox_event%ROWTYPE;
 proof control.notification_occurrence_observation%ROWTYPE; w control.installed_notification_worker%ROWTYPE;
 installed control.installed_notification_channel%ROWTYPE; ep control.notification_endpoint%ROWTYPE;
 actual record; m jsonb; wm jsonb; cm jsonb; now_ms numeric; lock_name text;
BEGIN
 PERFORM openpc.assert_notification_delivery_budget_owner();
 IF TG_OP=''DELETE'' THEN RAISE EXCEPTION ''NOTIFICATION-DELIVERY-EFFECT-CLOSED''; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id()
 OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION ''PC-AUTH-0005''; END IF;
 -- Restricting an existing request uses its signed historical endpoint cause,
 -- not a still-enabled endpoint or a currently effective send budget.
 IF TG_OP=''UPDATE'' AND NOT OLD.cancel_requested AND NEW.cancel_requested THEN
  PERFORM openpc.check_notification_delivery_cancellation_projection(OLD,NEW);
  RETURN NEW;
 END IF;
 -- Presence selects the immutable outcome family only. Its full checker binds
 -- the actual OLD/NEW rows and current publication authority.
 IF TG_OP=''UPDATE'' AND EXISTS(SELECT 1 FROM control.notification_delivery_outcome o
  WHERE o.participant_id=OLD.participant_id AND o.privacy_domain_id=OLD.privacy_domain_id
   AND o.notification_occurrence_id=OLD.notification_occurrence_id AND o.delivery_revision=OLD.revision) THEN
  PERFORM openpc.check_notification_delivery_outcome_projection(OLD,NEW);
  RETURN NEW;
 END IF;
 -- SQL admission requires the transaction-owned fences held by the real worker
 -- composition. Lock presence is a prerequisite, never a replacement TLS proof.
 FOREACH lock_name IN ARRAY ARRAY[''evidence-lifecycle:''||NEW.participant_id::text,
   ''notification-worker:''||NEW.participant_id::text||'':''||NEW.privacy_domain_id::text,
   ''notification-installation:''||NEW.participant_id::text||'':''||NEW.privacy_domain_id::text] LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_locks l WHERE l.pid=pg_backend_pid() AND l.locktype=''advisory'' AND l.granted
    AND l.database=(SELECT oid FROM pg_database WHERE datname=current_database())
    AND l.classid=((hashtextextended(lock_name,0)>>32)&4294967295)::oid
    AND l.objid=(hashtextextended(lock_name,0)&4294967295)::oid AND l.objsubid=1
    AND l.mode=CASE WHEN lock_name LIKE ''evidence-lifecycle:%'' THEN ''ExclusiveLock'' ELSE ''ShareLock'' END)
  THEN RAISE EXCEPTION ''NOTIFICATION-DELIVERY-BUDGET-FENCE''; END IF;
 END LOOP;
 SELECT * INTO STRICT occurrence FROM control.notification_occurrence WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND notification_occurrence_id=NEW.notification_occurrence_id;
 SELECT * INTO STRICT event FROM control.outbox_event WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.delivery_request_event_id;
 PERFORM openpc.check_notification_delivery_requested_event(event);
 SELECT * INTO STRICT proof FROM control.notification_occurrence_observation WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=NEW.delivery_request_operation_id;
 m:=openpc.business_cbor(proof.receipt_payload);
 IF event.aggregate_id IS DISTINCT FROM NEW.notification_occurrence_id
 OR event.correlation_id IS DISTINCT FROM NEW.delivery_request_operation_id
 OR event.event_id IS DISTINCT FROM NEW.delivery_request_event_id
 OR occurrence.payload_digest IS DISTINCT FROM NEW.payload_digest
 OR m->''7'' IS DISTINCT FROM openpc.business_uuid(NEW.notification_occurrence_id)
 OR m->''26'' IS DISTINCT FROM openpc.business_uuid(NEW.delivery_request_event_id)
 OR m->''5'' IS DISTINCT FROM openpc.business_uuid(NEW.delivery_request_operation_id)
 OR m->>''1'' IS DISTINCT FROM NEW.budget_environment_id
 THEN RAISE EXCEPTION ''NOTIFICATION-DELIVERY-BUDGET-SOURCE''; END IF;
 SELECT * INTO STRICT actual FROM openpc.current_notification_delivery_limit(m->>''1'');
 IF NEW.budget_generation_id IS DISTINCT FROM actual.generation_id
 OR NEW.budget_effective_digest IS DISTINCT FROM actual.effective_digest
 OR NEW.budget_configured_limit IS DISTINCT FROM actual.configured_limit
 THEN RAISE EXCEPTION ''NOTIFICATION-DELIVERY-BUDGET-CONFIGURATION''; END IF;
 SELECT * INTO STRICT w FROM control.installed_notification_worker WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND installation_digest=NEW.budget_worker_installation_digest;
 wm:=openpc.business_cbor(decode(w.installation->''signed''->>''payloadHex'',''hex''));
 now_ms:=floor(extract(epoch from clock_timestamp())*1000);
 IF w.state<>''ACTIVE'' OR w.service_id<>''LS-NOTIFICATION''
 OR w.subscription_id<>''SUB-NOTIFICATIONDELIVERYREQUESTED-NOTIFICATION-V1''
 OR w.installation->''pins''->>''processRole'' IS DISTINCT FROM ''ROLE-NOTIFICATION-WORKER''
 OR w.installation->''pins''->>''environmentId'' IS DISTINCT FROM NEW.budget_environment_id
 OR wm->''17'' IS DISTINCT FROM m->''13''
 OR now_ms<(wm->>''6'')::numeric OR now_ms>=(wm->>''7'')::numeric
 OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal p USING(participant_id,principal_id)
  JOIN control.participant t USING(participant_id) JOIN control.privacy_domain d USING(participant_id)
  WHERE c.participant_id=NEW.participant_id AND d.privacy_domain_id=NEW.privacy_domain_id
   AND c.credential_id=w.workload_credential_id AND p.principal_id=w.principal_id
   AND c.state=''ACTIVE'' AND c.kind=''WORKLOAD_MTLS'' AND p.kind=''WORKLOAD'' AND p.state=''ACTIVE'' AND t.state=''ACTIVE'' AND d.state=''ACTIVE''
   AND c.credential_epoch::text=w.installation->''pins''->>''workloadEpoch''
   AND c.audience=w.installation->''pins''->>''workloadId''
   AND ''sha256:''||encode(c.public_key_digest,''hex'')=w.installation->''pins''->>''workloadKeyDigest''
   AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp())
 THEN RAISE EXCEPTION ''NOTIFICATION-DELIVERY-BUDGET-WORKER''; END IF;
 SELECT * INTO STRICT ep FROM control.notification_endpoint WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND endpoint_id=occurrence.endpoint_id FOR SHARE;
 SELECT * INTO STRICT installed FROM control.installed_notification_channel WHERE participant_id=NEW.participant_id
  AND privacy_domain_id=NEW.privacy_domain_id AND credential_ref=occurrence.credential_ref;
 cm:=openpc.business_cbor(decode(installed.channel_signed->>''payloadHex'',''hex''));
 IF ep.state<>''ACTIVE'' OR ep.revision IS DISTINCT FROM occurrence.endpoint_revision
 OR ep.verification_id IS DISTINCT FROM occurrence.verification_id
 OR ep.credential_ref IS DISTINCT FROM occurrence.credential_ref
 OR ep.channel IS DISTINCT FROM occurrence.channel OR ep.destination_ref IS DISTINCT FROM occurrence.destination_ref
 OR ep.channel_profile_digest IS DISTINCT FROM occurrence.channel_profile_digest
 OR installed.state<>''ACTIVE'' OR installed.channel_profile_digest IS DISTINCT FROM occurrence.channel_profile_digest
 OR installed.channel IS DISTINCT FROM ep.channel OR installed.destination_ref IS DISTINCT FROM ep.destination_ref
 OR installed.credential->>''state'' IS DISTINCT FROM ''ACTIVE''
 OR (installed.credential->>''validFromMs'')::numeric>now_ms OR (installed.credential->>''validUntilMs'')::numeric<=now_ms
 OR cm->>''1'' IS DISTINCT FROM NEW.budget_environment_id
 OR now_ms<(cm->>''6'')::numeric OR now_ms>=(cm->>''7'')::numeric
 OR NOT EXISTS(SELECT 1 FROM control.notification_endpoint_verification v WHERE v.participant_id=ep.participant_id
   AND v.privacy_domain_id=ep.privacy_domain_id AND v.verification_id=ep.verification_id
   AND v.endpoint_id=ep.endpoint_id AND v.endpoint_revision=ep.revision AND v.channel=ep.channel
   AND v.destination_ref=ep.destination_ref AND v.channel_profile_digest=ep.channel_profile_digest AND v.credential_ref=ep.credential_ref)
 OR NOT EXISTS(SELECT 1 FROM control.credential c JOIN control.principal p USING(participant_id,principal_id)
   WHERE c.participant_id=NEW.participant_id AND c.credential_id=installed.workload_credential_id
   AND p.principal_id=installed.principal_id AND p.kind=''WORKLOAD'' AND p.state=''ACTIVE''
   AND c.state=''ACTIVE'' AND c.kind=''WORKLOAD_MTLS'' AND c.credential_epoch=installed.workload_epoch
   AND c.audience=installed.workload_id AND c.valid_from<=clock_timestamp() AND c.valid_until>clock_timestamp())
 THEN RAISE EXCEPTION ''NOTIFICATION-DELIVERY-BUDGET-ENDPOINT''; END IF;
 IF TG_OP=''INSERT'' THEN
  IF NEW.state<>''PENDING'' OR NEW.attempt_count<>0 OR NEW.attempt_limit<>least(actual.configured_limit,6)
   OR NEW.revision<>1 OR NEW.cancel_requested OR NEW.last_started_at_ms IS NOT NULL
   OR NEW.next_attempt_at_ms IS DISTINCT FROM floor(extract(epoch from statement_timestamp())*1000)
  THEN RAISE EXCEPTION ''NOTIFICATION-DELIVERY-BUDGET-INITIAL''; END IF;
 ELSIF NEW.state=''STARTED'' AND OLD.state IN (''PENDING'',''RETRY_WAIT'') THEN
  PERFORM openpc.check_notification_delivery_start_projection(OLD,NEW);
 ELSE
  IF NEW.attempt_limit IS DISTINCT FROM least(OLD.attempt_limit,actual.configured_limit,6)
   OR NEW.attempt_limit>=OLD.attempt_limit OR NEW.revision<>OLD.revision+1
   OR to_jsonb(NEW)-ARRAY[''attempt_limit'',''revision'',''budget_generation_id'',''budget_effective_digest'',''budget_configured_limit'',''budget_worker_installation_digest''] IS DISTINCT FROM
      to_jsonb(OLD)-ARRAY[''attempt_limit'',''revision'',''budget_generation_id'',''budget_effective_digest'',''budget_configured_limit'',''budget_worker_installation_digest'']
  THEN RAISE EXCEPTION ''NOTIFICATION-DELIVERY-BUDGET-ONLY''; END IF;
 END IF;
 RETURN NEW;
END '
 AND t.tgrelid='control.notification_delivery'::regclass AND t.tgname='notification_delivery_budget_guard' AND t.tgtype=31
 AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND t.tgqual IS NULL)
 OR EXISTS(SELECT 1 FROM unnest(ARRAY['notification_delivery_outcome','notification_delivery_observation',
  'notification_delivery','work_item','outbox_event']) expected(name)
  WHERE NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
   JOIN pg_roles r ON r.oid=c.relowner WHERE n.nspname='control' AND c.relname=expected.name
   AND r.rolname='openpc_control_owner' AND c.relkind='r' AND c.relrowsecurity AND c.relforcerowsecurity
   AND NOT c.relispartition AND NOT EXISTS(SELECT 1 FROM pg_inherits i WHERE i.inhrelid=c.oid OR i.inhparent=c.oid)))
 OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='control.outbox_event'::regclass
  AND conname='outbox_proof_kind_ck' AND contype='c' AND convalidated)
 OR NOT EXISTS(SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid
  WHERE i.indrelid='control.outbox_event'::regclass AND c.relname='outbox_notification_completion_sequence_uq'
  AND i.indisunique AND i.indisvalid AND i.indisready AND i.indislive AND i.indnatts=4 AND i.indnkeyatts=4 AND i.indexprs IS NULL
  AND pg_get_expr(i.indpred,i.indrelid)='(sequence_namespace = ''NOTIFICATION_DELIVERY_COMPLETED_V1''::text)'
  AND pg_get_indexdef(i.indexrelid,1,true)='participant_id' AND pg_get_indexdef(i.indexrelid,2,true)='privacy_domain_id'
  AND pg_get_indexdef(i.indexrelid,3,true)='aggregate_id' AND pg_get_indexdef(i.indexrelid,4,true)='business_sequence')
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.work_item'::regclass AND tgname='notification_failure_work_complete'
  AND tgfoid='openpc.guard_notification_failure_work_complete()'::regprocedure AND tgenabled IN ('O','A') AND tgtype=5 AND tgdeferrable AND tginitdeferred)
 THEN RAISE EXCEPTION 'NOTIFICATION-OUTCOME-SHARED-OWNERS'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.guard_notification_failure_work_complete(),openpc.assert_notification_outcome_publication_shared_owners() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_notification_outcome_publication_shared_owners() TO openpc_control_runtime;

GRANT EXECUTE ON FUNCTION openpc.assert_notification_outcome_publication_owner(),
 openpc.check_notification_outcome_publication_receipt(control.notification_delivery_outcome),
 openpc.check_notification_delivery_completed_event(control.outbox_event),
 openpc.notification_failure_initial_projection(control.notification_delivery_outcome),
 openpc.check_notification_delivery_failure_work(control.work_item),
 openpc.check_notification_outcome_publication_original(uuid),
 openpc.check_notification_delivery_outcome_projection(control.notification_delivery,control.notification_delivery),
 openpc.check_notification_outcome_publication_complete(uuid) TO openpc_control_runtime;
-- Only immutable historical dependencies are readable by the existing custody
-- worker. No current signing, publication, claim or result write grant escapes.
GRANT SELECT ON control.notification_delivery_signing,control.notification_delivery_start,
 control.notification_delivery_attempt,control.notification_delivery_dispatch_intent,
 control.notification_delivery_outcome_signing,control.notification_delivery_outcome,
 control.notification_delivery_observation,control.notification_receipt_signer_installation,
 control.installed_notification_worker TO openpc_control_worker;
GRANT EXECUTE ON FUNCTION openpc.check_notification_outcome_publication_original(uuid),
 openpc.check_notification_outcome_publication_receipt(control.notification_delivery_outcome),
 openpc.check_notification_delivery_completed_event(control.outbox_event),
 openpc.notification_failure_initial_projection(control.notification_delivery_outcome),
 openpc.check_notification_outcome_signing_original(control.notification_delivery_outcome_signing),
 openpc.check_notification_delivery_observation_original(control.notification_delivery_observation),
 openpc.check_notification_delivery_start_original(control.notification_delivery_start),
 openpc.check_notification_delivery_dispatch_intent_original(control.notification_delivery_dispatch_intent),
 openpc.work_item_business_projection(control.work_item) TO openpc_control_worker;
SELECT openpc.assert_notification_outcome_publication_shared_owners();
GRANT INSERT ON control.notification_delivery_outcome,control.notification_delivery_observation TO openpc_control_runtime;
DROP TRIGGER IF EXISTS notification_outcome_closed ON control.notification_delivery_outcome;
DROP TRIGGER IF EXISTS notification_outcome_closed ON control.notification_delivery_observation;


CREATE OR REPLACE FUNCTION openpc.guard_notification_completion_disposition_signer_installation() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE t jsonb; w control.installed_notification_completion_worker%ROWTYPE; m jsonb; c control.credential%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 PERFORM openpc.assert_request_context(true);
 IF NOT pg_has_role(current_user,'openpc_control_owner','USAGE')
 OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls))
 OR current_setting('row_security')<>'on' OR current_setting('session_replication_role')<>'origin'
 OR openpc.current_action_intent_id()<>'ACT-POLICY_READ_EFFECTIVE_ACCESS-V1'
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'NOTIFICATION-RECEIPT-SIGNER-IMMUTABLE'; END IF;
 IF NEW.participant_id IS DISTINCT FROM openpc.current_participant_id() OR NEW.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 THEN RAISE EXCEPTION 'PC-AUTH-0005'; END IF;
 -- Direct UPDATE already holds a row lock: fail instead of reversing the fence order.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('notification-completion-disposition-signer:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR to_jsonb(OLD)-'state' IS DISTINCT FROM to_jsonb(NEW)-'state'
  THEN RAISE EXCEPTION 'NOTIFICATION-RECEIPT-SIGNER-IMMUTABLE'; END IF;
  RETURN NEW;
 END IF;
 t:=NEW.trust;
 IF NEW.state<>'ACTIVE' OR jsonb_typeof(t) IS DISTINCT FROM 'object'
 OR t-ARRAY['schema','schemaDefinitionDigest','owner','purpose','environmentId','participantId','privacyDomainId','installationId','workerInstallationDigest','workerProfileDigest','workerIssuerSpkiHex','principalId','workloadCredentialId','workloadEpoch','workloadId','secretClass','secretReference','secretVersion','publicKeySpkiHex','keyEpoch','providerId','providerOrigin','providerTlsSpkiDigest','validFromNs','validUntilNs','installationReference','signerKeyId'] IS DISTINCT FROM '{}'::jsonb
 OR NOT t ?& ARRAY['schema','schemaDefinitionDigest','owner','purpose','environmentId','participantId','privacyDomainId','installationId','workerInstallationDigest','workerProfileDigest','workerIssuerSpkiHex','principalId','workloadCredentialId','workloadEpoch','workloadId','secretClass','secretReference','secretVersion','publicKeySpkiHex','keyEpoch','providerId','providerOrigin','providerTlsSpkiDigest','validFromNs','validUntilNs','installationReference','signerKeyId']
 OR EXISTS(SELECT 1 FROM jsonb_each(t) e WHERE jsonb_typeof(e.value)<>'string' OR e.value#>>'{}'<>btrim(e.value#>>'{}'))
 OR t->>'schema' IS DISTINCT FROM 'pc.notification.completion-disposition-signer-trust.v1'
 OR t->>'purpose' IS DISTINCT FROM 'pc.cose.notification-completion-disposition-receipt.v1' OR t->>'schemaDefinitionDigest' IS DISTINCT FROM 'sha256:b8af9858ca24f16a251e4e27875bded1d2b612a2cebba9cfa9901b43155fca7d'
 OR t->>'owner' IS DISTINCT FROM 'LS-CONTROL-WORK'

 OR t->>'secretClass' IS DISTINCT FROM 'SECRET-SIGNING-KEY'
 OR t->>'participantId' IS DISTINCT FROM NEW.participant_id::text OR t->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text
 OR t->>'installationId' IS DISTINCT FROM NEW.installation_id::text
 OR t->>'workerInstallationDigest' IS DISTINCT FROM NEW.worker_installation_digest
 OR t->>'signerKeyId' IS DISTINCT FROM NEW.signer_id
 OR NEW.trust_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(t),'UTF8')
 OR NEW.trust_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.trust_bytes),'hex')
 OR NOT coalesce(t->>'secretReference' ~ '^secret://[a-z][a-z0-9-]{1,31}/[A-Za-z0-9._/-]{1,192}#[A-Za-z0-9._-]{1,96}$',false)
 OR split_part(t->>'secretReference','#',2) IS DISTINCT FROM t->>'secretVersion' OR lower(t->>'secretVersion') IN ('latest','current')
 OR NOT coalesce(t->>'providerId' ~ '^[a-z][a-z0-9.-]{0,127}$',false)
 OR length(t->>'providerOrigin')>2048 OR NOT coalesce(t->>'providerOrigin' ~ '^https://([a-z0-9][a-z0-9.-]*|\[[0-9a-f:]+\])(:[1-9][0-9]{0,4})?$',false)
 OR NOT coalesce(t->>'providerTlsSpkiDigest' ~ '^sha256:[0-9a-f]{64}$',false)
 OR NOT coalesce(t->>'workerProfileDigest' ~ '^sha256:[0-9a-f]{64}$',false)
 OR NOT coalesce(t->>'publicKeySpkiHex' ~ '^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$',false)
 OR NOT coalesce(t->>'workerIssuerSpkiHex' ~ '^3059301306072a8648ce3d020106082a8648ce3d03010703420004[0-9a-f]{128}$',false)
 OR NEW.signer_id IS DISTINCT FROM 'sha256:'||encode(sha256(decode(t->>'publicKeySpkiHex','hex')),'hex')
 OR NOT coalesce(t->>'keyEpoch' ~ '^[1-9][0-9]{0,19}$',false)
 OR NOT coalesce(t->>'validFromNs' ~ '^(0|[1-9][0-9]{0,19})$',false)
 OR NOT coalesce(t->>'validUntilNs' ~ '^[1-9][0-9]{0,19}$',false)
 OR length(t->>'installationReference') NOT BETWEEN 1 AND 256
 THEN RAISE EXCEPTION 'NOTIFICATION-RECEIPT-SIGNER-TRUST'; END IF;
 IF (t->>'keyEpoch')::numeric>18446744073709551615 OR (t->>'validUntilNs')::numeric>18446744073709551615
 OR (t->>'validFromNs')::numeric>=(t->>'validUntilNs')::numeric
 OR mod((t->>'validFromNs')::numeric,1000000)<>0 OR mod((t->>'validUntilNs')::numeric,1000000)<>0
 OR floor(extract(epoch from clock_timestamp())*1000)*1000000 NOT BETWEEN (t->>'validFromNs')::numeric AND (t->>'validUntilNs')::numeric-1
 THEN RAISE EXCEPTION 'NOTIFICATION-RECEIPT-SIGNER-TIME'; END IF;
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('notification-completion-worker:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT w FROM control.installed_notification_completion_worker WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id
 AND installation_digest=NEW.worker_installation_digest AND state='ACTIVE';
 m:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));
 IF w.service_id<>'LS-CONTROL-WORK' OR w.subscription_id<>'SUB-NOTIFICATIONDELIVERYCOMPLETED-CONTROL_WORK-V1'
 OR w.signed_profile_digest IS DISTINCT FROM t->>'workerProfileDigest'
 OR w.installation->'pins'->>'issuerSpkiHex' IS DISTINCT FROM t->>'workerIssuerSpkiHex'
 OR w.installation->'pins'->>'environmentId' IS DISTINCT FROM t->>'environmentId'
 OR w.installation->'pins'->>'principalId' IS DISTINCT FROM t->>'principalId'
 OR w.installation->'pins'->>'workloadCredentialId' IS DISTINCT FROM t->>'workloadCredentialId'
 OR w.installation->'pins'->>'workloadEpoch' IS DISTINCT FROM t->>'workloadEpoch'
 OR w.installation->'pins'->>'workloadId' IS DISTINCT FROM t->>'workloadId'
 OR floor(extract(epoch from clock_timestamp())*1000) NOT BETWEEN (m->>'6')::numeric AND (m->>'7')::numeric-1
 THEN RAISE EXCEPTION 'NOTIFICATION-RECEIPT-SIGNER-WORKER'; END IF;
 SELECT * INTO STRICT c FROM control.credential WHERE participant_id=NEW.participant_id AND credential_id=w.workload_credential_id AND principal_id=w.principal_id;
 IF c.kind<>'WORKLOAD_MTLS' OR c.state<>'ACTIVE' OR c.credential_epoch::text IS DISTINCT FROM t->>'workloadEpoch'
 OR c.audience IS DISTINCT FROM t->>'workloadId' OR c.valid_from>clock_timestamp() OR c.valid_until<=clock_timestamp() OR c.valid_until IS NULL
 OR NEW.signer_id=t->>'providerTlsSpkiDigest' OR t->>'providerTlsSpkiDigest'='sha256:'||encode(sha256(decode(t->>'workerIssuerSpkiHex','hex')),'hex')
 OR c.public_key_digest=decode(substring(t->>'providerTlsSpkiDigest' from 8),'hex')
 OR c.public_key_digest=decode(substring(NEW.signer_id from 8),'hex')
 OR NEW.signer_id='sha256:'||encode(sha256(decode(t->>'workerIssuerSpkiHex','hex')),'hex')
 THEN RAISE EXCEPTION 'NOTIFICATION-RECEIPT-SIGNER-IDENTITY'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS notification_completion_disposition_signer_installation_guard ON control.notification_completion_disposition_signer_installation;
CREATE TRIGGER notification_completion_disposition_signer_installation_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_completion_disposition_signer_installation
 FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_completion_disposition_signer_installation();
REVOKE ALL ON FUNCTION openpc.guard_notification_completion_disposition_signer_installation() FROM PUBLIC;
CREATE OR REPLACE FUNCTION openpc.guard_notification_completion_disposition_signer_truncate() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
 BEGIN RAISE EXCEPTION 'NOTIFICATION-RECEIPT-SIGNER-IMMUTABLE'; END $$;
DROP TRIGGER IF EXISTS notification_completion_disposition_signer_truncate_guard ON control.notification_completion_disposition_signer_installation;
CREATE TRIGGER notification_completion_disposition_signer_truncate_guard BEFORE TRUNCATE ON control.notification_completion_disposition_signer_installation
 FOR EACH STATEMENT EXECUTE FUNCTION openpc.guard_notification_completion_disposition_signer_truncate();
REVOKE ALL ON FUNCTION openpc.guard_notification_completion_disposition_signer_truncate() FROM PUBLIC;
CREATE OR REPLACE FUNCTION openpc.assert_notification_completion_disposition_signer_owner() RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF current_setting('session_replication_role')<>'origin' OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='control.notification_completion_disposition_signer_installation'::regclass AND relrowsecurity AND relforcerowsecurity)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_completion_disposition_signer_installation'::regclass AND tgname='notification_completion_disposition_signer_installation_guard' AND tgenabled IN ('O','A') AND NOT tgisinternal)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='control.notification_completion_disposition_signer_installation'::regclass AND tgname='notification_completion_disposition_signer_truncate_guard' AND tgenabled IN ('O','A') AND NOT tgisinternal)
 THEN RAISE EXCEPTION 'NOTIFICATION-RECEIPT-SIGNER-OWNER'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.assert_notification_completion_disposition_signer_owner() FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.notification_completion_source_envelope(e control.outbox_event) RETURNS jsonb
LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('participantId',e.participant_id,'privacyDomainId',e.privacy_domain_id,'eventId',e.event_id,'eventType',e.event_type,'aggregateType',e.aggregate_type,'aggregateId',e.aggregate_id,
 'sequence',e.business_sequence::text,'aggregateSequence',e.aggregate_sequence::text,'proofKind',e.proof_kind,'namespace',e.sequence_namespace,'source',e.source,'subject',e.subject,
 'correlationId',e.correlation_id,'causationId',e.causation_id,'dataSchema',e.data_schema_uri,'payloadHex',encode(e.payload_cbor,'hex'),
 'payloadDigest',encode(e.payload_digest,'hex'),'occurredAtUs',floor(extract(epoch from e.occurred_at)*1000000)::text,
 'receiptId',e.receipt_id,'coseHex',encode(e.cose_sign1,'hex'),'authorityGenerationHex',encode(e.authority_generation,'hex'),'webauthnAssertionBindingDigest',encode(e.webauthn_assertion_binding_digest,'hex'));
$$;
CREATE OR REPLACE FUNCTION openpc.check_notification_completion_source_origin(event uuid,receipt_digest text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE e control.outbox_event%ROWTYPE;o control.notification_delivery_outcome%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=e.participant_id AND privacy_domain_id=e.privacy_domain_id AND operation_id=e.correlation_id AND receipt_id=e.event_id;
 PERFORM openpc.check_notification_outcome_publication_receipt(o);
 IF e.proof_kind IS DISTINCT FROM 'NOTIFICATION_DELIVERY_COMPLETION_REFERENCE' OR e.sequence_namespace IS DISTINCT FROM 'NOTIFICATION_DELIVERY_COMPLETED_V1'
 OR e.source IS DISTINCT FROM 'urn:openpc:service:LS-NOTIFICATION' OR e.event_type IS DISTINCT FROM 'io.openpc.notification.delivery.completed.v1'
 OR o.receipt_digest IS DISTINCT FROM receipt_digest OR (o.transition->'receipt'->>'afterDeliveryState' IN ('DELIVERED','FAILED')) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'COMPLETION-SOURCE-ORIGIN'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_completion_validated_source(event uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE e control.outbox_event%ROWTYPE;
BEGIN
 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 PERFORM openpc.check_notification_outcome_publication_original(e.correlation_id);
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_completion_signing_preparation(event uuid,preparation jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.notification_completion_source%ROWTYPE;signer control.notification_completion_disposition_signer_installation%ROWTYPE;w control.installed_notification_completion_worker%ROWTYPE;
 t jsonb:=preparation->'preparation';q jsonb:=preparation->'request';j jsonb;attempts jsonb;last_attempt jsonb;initial_profile jsonb;current_profile jsonb;m jsonb;r jsonb;before_state jsonb;after_state jsonb;expected_work text;expected_work_id text;expected_outcome text;counted integer;n numeric;
BEGIN
 SELECT * INTO STRICT s FROM control.notification_completion_source WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 PERFORM openpc.check_notification_completion_source_origin(event,s.source->'reference'->>'receiptDigest');
 SELECT jsonb_agg(attempt ORDER BY number),count(*) INTO attempts,counted FROM control.notification_completion_attempt WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND event_id=event;
 j:=jsonb_build_object('source',s.source->'reference','initialWorker',s.initial_worker,'effectiveLimit',s.effective_limit,'attempts',attempts);
 last_attempt:=attempts->(counted-1);initial_profile:=openpc.business_cbor(decode(s.initial_worker->'signed'->>'payloadHex','hex'));
 m:=openpc.business_cbor(decode(q->>'payloadHex','hex'));r:=jsonb_build_object('environmentId',m->'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'receiptId',(m->'4'->>'bytes')::uuid::text,'operationId',(m->'5'->>'bytes')::uuid::text,'sourceEventId',(m->'6'->>'bytes')::uuid::text,'sourceEnvelopeDigest','sha256:'||(m->'7'->>'bytes'),'sourceDataDigest','sha256:'||(m->'8'->>'bytes'),'sourcePartitionDigest','sha256:'||(m->'9'->>'bytes'),'producerTrustDigest','sha256:'||(m->'10'->>'bytes'),'sourceReceiptDigest','sha256:'||(m->'11'->>'bytes'),'initialWorkerInstallationDigest','sha256:'||(m->'12'->>'bytes'),'initialWorkerProfileDigest','sha256:'||(m->'13'->>'bytes'),'workerInstallationDigest','sha256:'||(m->'14'->>'bytes'),'workerProfileDigest','sha256:'||(m->'15'->>'bytes'),'authoritySnapshotDigest','sha256:'||(m->'16'->>'bytes'),'attemptChainDigest','sha256:'||(m->'17'->>'bytes'),'attemptCount',(m->>'18')::numeric,'attemptLimit',(m->>'19')::numeric,'initialAttemptLimit',(m->>'20')::numeric,'initialBackoffMs',(m->>'21')::numeric,'maximumBackoffMs',(m->>'22')::numeric,'signerInstallationDigest','sha256:'||(m->'23'->>'bytes'),'disposition',CASE m->>'24' WHEN '1' THEN 'ADMITTED' WHEN '2' THEN 'QUARANTINED' ELSE NULL END,'safeProblem',CASE m->>'25' WHEN '0' THEN 'NONE' WHEN '1' THEN 'PC-OPS-9001' ELSE NULL END,'workItemKind',CASE m->>'26' WHEN '0' THEN 'NONE' WHEN '1' THEN 'DELIVERY_FAILURE' WHEN '2' THEN 'REMEDIATION' ELSE NULL END,'workItemId',(m->'27'->>'bytes')::uuid::text,'beforeStateDigest','sha256:'||(m->'28'->>'bytes'),'afterStateDigest','sha256:'||(m->'29'->>'bytes'),'cursorMode',CASE m->>'30' WHEN '1' THEN 'ADVANCE' WHEN '2' THEN 'HOLD' ELSE NULL END,'recordedAtMs',(m->>'31')::numeric,'signerKeyId','sha256:'||(m->'32'->>'bytes'));
 SELECT * INTO STRICT signer FROM control.notification_completion_disposition_signer_installation WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND trust_digest=q->>'signerInstallationDigest';
 SELECT * INTO STRICT w FROM control.installed_notification_completion_worker WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND installation_digest=signer.worker_installation_digest;
 current_profile:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));
 IF preparation-ARRAY['schema','preparation','request','requestDigest'] IS DISTINCT FROM '{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(preparation))<>4 OR preparation->>'schema' IS DISTINCT FROM 'pc.notification.completion-disposition-signing.v1'
 OR t-ARRAY['journal','workerInstallation','signerInstallation','metadata','disposition','producerOutcome','producerWorkItemId'] IS DISTINCT FROM '{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(t))<>7
 OR t->'journal' IS DISTINCT FROM j OR counted<1 OR counted>(initial_profile->>'17')::integer
 OR m->'0' IS DISTINCT FROM jsonb_build_object('bytes','b8af9858ca24f16a251e4e27875bded1d2b612a2cebba9cfa9901b43155fca7d') OR (SELECT count(*) FROM jsonb_object_keys(m))<>33
 OR r->>'sourceEventId' IS DISTINCT FROM event::text OR r->>'participantId' IS DISTINCT FROM s.participant_id::text OR r->>'privacyDomainId' IS DISTINCT FROM s.privacy_domain_id::text
 OR r->>'initialWorkerInstallationDigest' IS DISTINCT FROM s.initial_worker_installation_digest OR r->>'initialWorkerProfileDigest' IS DISTINCT FROM s.initial_worker->'pins'->>'signedProfileDigest'
 OR r->>'attemptChainDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(j||jsonb_build_object('schema','pc.notification.completion-attempt-chain.v1')),'UTF8')),'hex')
 OR r->'attemptCount' IS DISTINCT FROM to_jsonb(counted) OR r->'attemptLimit' IS DISTINCT FROM to_jsonb(s.effective_limit)
 OR s.effective_limit>(initial_profile->>'17')::numeric OR s.effective_limit>(current_profile->>'17')::numeric
 OR r->'initialAttemptLimit' IS DISTINCT FROM initial_profile->'17' OR r->'initialBackoffMs' IS DISTINCT FROM initial_profile->'18' OR r->'maximumBackoffMs' IS DISTINCT FROM initial_profile->'19'
 OR r->>'sourceEnvelopeDigest' IS DISTINCT FROM s.source->'reference'->>'envelopeDigest'
 OR r->>'sourceDataDigest' IS DISTINCT FROM s.source->'reference'->>'dataDigest'
 OR r->>'sourcePartitionDigest' IS DISTINCT FROM s.source->'reference'->>'partitionDigest'
 OR r->>'producerTrustDigest' IS DISTINCT FROM s.source->'reference'->>'producerTrustDigest'
 OR r->>'sourceReceiptDigest' IS DISTINCT FROM s.source->'reference'->>'receiptDigest'
 OR r->>'receiptId' IS DISTINCT FROM q->>'signingAttemptId' OR r->>'operationId' IS DISTINCT FROM q->>'operationId' OR r->>'receiptId'=r->>'operationId' OR event::text IN (r->>'receiptId',r->>'operationId')
 OR t->'metadata' IS DISTINCT FROM jsonb_build_object('receiptId',r->'receiptId','operationId',r->'operationId','authoritySnapshotDigest',r->'authoritySnapshotDigest','recordedAtMs',r->'recordedAtMs','beforeStateDigest',r->'beforeStateDigest','afterStateDigest',r->'afterStateDigest')
 OR t->>'disposition' IS DISTINCT FROM r->>'disposition' OR (r->>'recordedAtMs')::numeric<(last_attempt->>'finishedAtMs')::numeric
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-JOURNAL'; END IF;
 IF r->>'disposition'='ADMITTED' THEN
  IF last_attempt->>'state' IS DISTINCT FROM 'VALIDATED' OR r->>'safeProblem' IS DISTINCT FROM 'NONE' OR r->>'cursorMode' IS DISTINCT FROM 'ADVANCE' THEN RAISE EXCEPTION 'COMPLETION-SIGNING-ADMITTED'; END IF;
  PERFORM openpc.check_notification_completion_validated_source(event);
  SELECT transition->'receipt'->>'afterDeliveryState' INTO STRICT expected_outcome FROM control.notification_delivery_outcome WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND receipt_id=event;
  expected_work:=CASE expected_outcome WHEN 'FAILED' THEN 'DELIVERY_FAILURE' ELSE 'NONE' END;
  expected_work_id:=CASE expected_outcome WHEN 'FAILED' THEN event::text ELSE r->>'receiptId' END;
  IF t->>'producerOutcome' IS DISTINCT FROM expected_outcome OR t->'producerWorkItemId' IS DISTINCT FROM (CASE expected_outcome WHEN 'FAILED' THEN to_jsonb(event::text) ELSE 'null'::jsonb END) THEN RAISE EXCEPTION 'COMPLETION-SIGNING-PRODUCER'; END IF;
 ELSIF r->>'disposition'='QUARANTINED' THEN
  IF last_attempt->>'state' IS DISTINCT FROM 'FAILED' OR counted<s.effective_limit OR r->>'safeProblem' IS DISTINCT FROM 'PC-OPS-9001' OR r->>'cursorMode' IS DISTINCT FROM 'HOLD' OR t->'producerOutcome' IS DISTINCT FROM 'null'::jsonb OR t->'producerWorkItemId' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'COMPLETION-SIGNING-QUARANTINE'; END IF;
  expected_work:='REMEDIATION';expected_work_id:=r->>'receiptId';
 ELSE RAISE EXCEPTION 'COMPLETION-SIGNING-DISPOSITION';END IF;
 before_state:=jsonb_build_object('schema','pc.notification.completion-disposition-state.v1','journal',j,'disposition',NULL);
 after_state:=before_state||jsonb_build_object('disposition',r->'disposition','receiptId',r->'receiptId','operationId',r->'operationId','workItemKind',expected_work,'workItemId',expected_work_id,'cursorMode',r->'cursorMode');
 IF r->>'workItemKind' IS DISTINCT FROM expected_work OR r->>'workItemId' IS DISTINCT FROM expected_work_id OR r->>'beforeStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(before_state),'UTF8')),'hex') OR r->>'afterStateDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(after_state),'UTF8')),'hex')
 OR q-ARRAY['schemaVersion','method','purpose','signerInstallationDigest','providerId','secretClass','reference','version','keyEpoch','signerKeyId','environmentId','participantId','privacyDomainId','workloadCredentialId','workloadEpoch','workerInstallationDigest','workerProfileDigest','signingAttemptId','operationId','sourceEventId','attemptChainDigest','dispositionPreparationDigest','payloadHex'] IS DISTINCT FROM '{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(q))<>23
 OR q->'schemaVersion' IS DISTINCT FROM '1'::jsonb OR q->>'method' IS DISTINCT FROM 'SIGN_NOTIFICATION_COMPLETION_DISPOSITION' OR q->>'purpose' IS DISTINCT FROM 'pc.cose.notification-completion-disposition-receipt.v1'
 OR q->>'dispositionPreparationDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(t),'UTF8')),'hex') OR preparation->>'requestDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to('pc.notification.completion-disposition-provider-request.v1','UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(q),'UTF8')),'hex')
 OR t->'workerInstallation' IS DISTINCT FROM w.installation OR t->'signerInstallation' IS DISTINCT FROM signer.trust-ARRAY['schema','schemaDefinitionDigest','signerKeyId']
 OR signer.trust->>'purpose' IS DISTINCT FROM 'pc.cose.notification-completion-disposition-receipt.v1' OR signer.trust->>'owner' IS DISTINCT FROM 'LS-CONTROL-WORK'
 OR q->>'environmentId' IS DISTINCT FROM signer.trust->>'environmentId'
 OR q->>'participantId' IS DISTINCT FROM signer.trust->>'participantId'
 OR q->>'privacyDomainId' IS DISTINCT FROM signer.trust->>'privacyDomainId'
 OR q->>'workerInstallationDigest' IS DISTINCT FROM signer.trust->>'workerInstallationDigest'
 OR q->>'workerProfileDigest' IS DISTINCT FROM signer.trust->>'workerProfileDigest'
 OR q->>'signerKeyId' IS DISTINCT FROM signer.trust->>'signerKeyId'
 OR q->>'providerId' IS DISTINCT FROM signer.trust->>'providerId'
 OR q->>'secretClass' IS DISTINCT FROM signer.trust->>'secretClass'
 OR q->>'keyEpoch' IS DISTINCT FROM signer.trust->>'keyEpoch'
 OR q->>'workloadCredentialId' IS DISTINCT FROM signer.trust->>'workloadCredentialId'
 OR q->>'workloadEpoch' IS DISTINCT FROM signer.trust->>'workloadEpoch'
 OR q->>'reference' IS DISTINCT FROM signer.trust->>'secretReference' OR q->>'version' IS DISTINCT FROM signer.trust->>'secretVersion'
 OR r->>'environmentId' IS DISTINCT FROM q->>'environmentId'
 OR r->>'participantId' IS DISTINCT FROM q->>'participantId'
 OR r->>'privacyDomainId' IS DISTINCT FROM q->>'privacyDomainId'
 OR r->>'workerInstallationDigest' IS DISTINCT FROM q->>'workerInstallationDigest'
 OR r->>'workerProfileDigest' IS DISTINCT FROM q->>'workerProfileDigest'
 OR r->>'signerKeyId' IS DISTINCT FROM q->>'signerKeyId'
 OR r->>'signerInstallationDigest' IS DISTINCT FROM q->>'signerInstallationDigest'
 OR r->>'sourceEventId' IS DISTINCT FROM q->>'sourceEventId'
 OR r->>'attemptChainDigest' IS DISTINCT FROM q->>'attemptChainDigest'
 OR w.producer_trust_digest IS DISTINCT FROM r->>'producerTrustDigest'
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-BINDING'; END IF;
 n:=(r->>'recordedAtMs')::numeric;
 IF n<(current_profile->>'6')::numeric OR n>=(current_profile->>'7')::numeric OR n*1000000<(signer.trust->>'validFromNs')::numeric OR n*1000000>=(signer.trust->>'validUntilNs')::numeric THEN RAISE EXCEPTION 'COMPLETION-SIGNING-TIME'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_completion_signing_current(event uuid,preparation jsonb,phase text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.notification_completion_disposition_signer_installation%ROWTYPE;w control.installed_notification_completion_worker%ROWTYPE;c control.credential%ROWTYPE;m jsonb;n numeric;
BEGIN
 IF phase IS NULL OR phase NOT IN ('PREPARE','SIGN_CLAIM') THEN RAISE EXCEPTION 'COMPLETION-SIGNING-PHASE'; END IF;
 PERFORM openpc.check_notification_completion_signing_preparation(event,preparation);
 IF NOT pg_try_advisory_xact_lock_shared(hashtextextended('notification-completion-disposition-signer:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text,0)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT s FROM control.notification_completion_disposition_signer_installation WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND trust_digest=preparation->'request'->>'signerInstallationDigest' AND state='ACTIVE';
 SELECT * INTO STRICT w FROM control.installed_notification_completion_worker WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND installation_digest=s.worker_installation_digest AND state='ACTIVE';
 SELECT * INTO STRICT c FROM control.credential WHERE participant_id=w.participant_id AND credential_id=w.workload_credential_id AND principal_id=w.principal_id;
 m:=openpc.business_cbor(decode(w.installation->'signed'->>'payloadHex','hex'));n:=floor(extract(epoch from clock_timestamp())*1000);
 IF c.state<>'ACTIVE' OR c.kind<>'WORKLOAD_MTLS' OR c.credential_epoch::text IS DISTINCT FROM w.installation->'pins'->>'workloadEpoch' OR c.valid_until IS NULL OR c.valid_from>clock_timestamp() OR c.valid_until<=clock_timestamp()
 OR n<(m->>'6')::numeric OR n>=(m->>'7')::numeric OR n*1000000<(s.trust->>'validFromNs')::numeric OR n*1000000>=(s.trust->>'validUntilNs')::numeric
 OR n<(preparation->'preparation'->'metadata'->>'recordedAtMs')::numeric
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-CURRENT'; END IF;
 PERFORM openpc.check_notification_completion_effect_binding(event,phase,w.installation_digest,preparation->'preparation'->'metadata'->>'authoritySnapshotDigest');
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_completion_signing_observation(event uuid,ob jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.notification_completion_disposition_signing%ROWTYPE;q jsonb;signer control.notification_completion_disposition_signer_installation%ROWTYPE;w jsonb;
BEGIN
 SELECT * INTO STRICT s FROM control.notification_completion_disposition_signing WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 q:=s.preparation->'request';PERFORM openpc.check_notification_completion_signing_preparation(event,s.preparation);
 SELECT * INTO STRICT signer FROM control.notification_completion_disposition_signer_installation WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND trust_digest=s.signer_installation_digest;
 SELECT openpc.business_cbor(decode(installation->'signed'->>'payloadHex','hex')) INTO STRICT w FROM control.installed_notification_completion_worker WHERE participant_id=s.participant_id AND privacy_domain_id=s.privacy_domain_id AND installation_digest=signer.worker_installation_digest;
 IF s.state NOT IN ('DISPATCHED','OBSERVED') OR s.dispatched_at_ms IS NULL
 OR ob-ARRAY['schemaVersion','providerId','signingAttemptId','requestDigest','recordedAtMs','outcome','reason','coseHex'] IS DISTINCT FROM '{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(ob))<>8
 OR ob->'schemaVersion' IS DISTINCT FROM '1'::jsonb OR ob->>'providerId' IS DISTINCT FROM q->>'providerId' OR ob->>'signingAttemptId' IS DISTINCT FROM s.signing_attempt_id::text OR ob->>'requestDigest' IS DISTINCT FROM s.request_digest
 OR (jsonb_typeof(ob->'recordedAtMs')='number' AND (ob->>'recordedAtMs') ~ '^(0|[1-9][0-9]*)$' AND (ob->>'recordedAtMs')::numeric<=9007199254740991) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-OBSERVATION'; END IF;
 IF ob->>'outcome'='SIGNED' THEN
  IF ob->'reason' IS DISTINCT FROM 'null'::jsonb OR (ob->>'recordedAtMs')::numeric<s.dispatched_at_ms OR (ob->>'recordedAtMs')::numeric>=(w->>'7')::numeric OR (ob->>'recordedAtMs')::numeric*1000000>=(signer.trust->>'validUntilNs')::numeric
  THEN RAISE EXCEPTION 'COMPLETION-SIGNING-OBSERVATION-TIME'; END IF;
  PERFORM openpc.archive_cose_binding(decode(q->>'payloadHex','hex'),decode(ob->>'coseHex','hex'),signer.signer_id,24031,368);
 ELSIF ob->>'outcome' IS DISTINCT FROM 'REJECTED' OR ob->'coseHex' IS DISTINCT FROM 'null'::jsonb OR (ob->>'reason' IN ('REVOKED','EXPIRED','WRONG_SCOPE','INVALID_REQUEST','ATTEMPT_CONFLICT','KEY_UNAVAILABLE')) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-OBSERVATION-REJECTION'; END IF;
 IF s.state='OBSERVED' AND s.observation IS DISTINCT FROM ob THEN RAISE EXCEPTION 'COMPLETION-SIGNING-FIRST'; END IF;
END $$;
CREATE OR REPLACE FUNCTION openpc.check_notification_completion_disposition_signed(event uuid,t jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s control.notification_completion_disposition_signing%ROWTYPE;m jsonb;r jsonb;
BEGIN
 SELECT * INTO STRICT s FROM control.notification_completion_disposition_signing WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 PERFORM openpc.check_notification_completion_signing_preparation(event,s.preparation);
 PERFORM openpc.check_notification_completion_signing_observation(event,s.observation);
 m:=openpc.business_cbor(decode(s.preparation->'request'->>'payloadHex','hex'));r:=jsonb_build_object('environmentId',m->'1','participantId',(m->'2'->>'bytes')::uuid::text,'privacyDomainId',(m->'3'->>'bytes')::uuid::text,'receiptId',(m->'4'->>'bytes')::uuid::text,'operationId',(m->'5'->>'bytes')::uuid::text,'sourceEventId',(m->'6'->>'bytes')::uuid::text,'sourceEnvelopeDigest','sha256:'||(m->'7'->>'bytes'),'sourceDataDigest','sha256:'||(m->'8'->>'bytes'),'sourcePartitionDigest','sha256:'||(m->'9'->>'bytes'),'producerTrustDigest','sha256:'||(m->'10'->>'bytes'),'sourceReceiptDigest','sha256:'||(m->'11'->>'bytes'),'initialWorkerInstallationDigest','sha256:'||(m->'12'->>'bytes'),'initialWorkerProfileDigest','sha256:'||(m->'13'->>'bytes'),'workerInstallationDigest','sha256:'||(m->'14'->>'bytes'),'workerProfileDigest','sha256:'||(m->'15'->>'bytes'),'authoritySnapshotDigest','sha256:'||(m->'16'->>'bytes'),'attemptChainDigest','sha256:'||(m->'17'->>'bytes'),'attemptCount',(m->>'18')::numeric,'attemptLimit',(m->>'19')::numeric,'initialAttemptLimit',(m->>'20')::numeric,'initialBackoffMs',(m->>'21')::numeric,'maximumBackoffMs',(m->>'22')::numeric,'signerInstallationDigest','sha256:'||(m->'23'->>'bytes'),'disposition',CASE m->>'24' WHEN '1' THEN 'ADMITTED' WHEN '2' THEN 'QUARANTINED' ELSE NULL END,'safeProblem',CASE m->>'25' WHEN '0' THEN 'NONE' WHEN '1' THEN 'PC-OPS-9001' ELSE NULL END,'workItemKind',CASE m->>'26' WHEN '0' THEN 'NONE' WHEN '1' THEN 'DELIVERY_FAILURE' WHEN '2' THEN 'REMEDIATION' ELSE NULL END,'workItemId',(m->'27'->>'bytes')::uuid::text,'beforeStateDigest','sha256:'||(m->'28'->>'bytes'),'afterStateDigest','sha256:'||(m->'29'->>'bytes'),'cursorMode',CASE m->>'30' WHEN '1' THEN 'ADVANCE' WHEN '2' THEN 'HOLD' ELSE NULL END,'recordedAtMs',(m->>'31')::numeric,'signerKeyId','sha256:'||(m->'32'->>'bytes'));
 IF s.state IS DISTINCT FROM 'OBSERVED' OR s.observation->>'outcome' IS DISTINCT FROM 'SIGNED'
 OR t IS DISTINCT FROM jsonb_build_object('schema','pc.notification.completion-disposition.v1','input',s.preparation->'preparation','receipt',r,'payloadHex',s.preparation->'request'->>'payloadHex','coseHex',s.observation->>'coseHex')
 THEN RAISE EXCEPTION 'COMPLETION-DISPOSITION-SIGNED'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.notification_completion_source_envelope(control.outbox_event) FROM PUBLIC;
REVOKE ALL ON FUNCTION openpc.check_notification_completion_source_origin(uuid,text) FROM PUBLIC;
REVOKE ALL ON FUNCTION openpc.check_notification_completion_validated_source(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION openpc.check_notification_completion_signing_preparation(uuid,jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION openpc.check_notification_completion_signing_current(uuid,jsonb,text) FROM PUBLIC;
REVOKE ALL ON FUNCTION openpc.check_notification_completion_signing_observation(uuid,jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION openpc.check_notification_completion_disposition_signed(uuid,jsonb) FROM PUBLIC;
CREATE OR REPLACE FUNCTION openpc.check_notification_completion_effect_binding(event uuid,phase text,installation text,authority text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE admitted record;
BEGIN
 IF event IS NULL OR phase IS NULL OR phase NOT IN ('SOURCE','CLAIM','LIMIT','FINISH','PREPARE','SIGN_CLAIM','OBSERVE','PUBLISH')
 OR (installation ~ '^sha256:[0-9a-f]{64}$') IS DISTINCT FROM true
 OR (authority ~ '^sha256:[0-9a-f]{64}$') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'COMPLETION-EFFECT-BINDING'; END IF;
 -- STRICT proves cardinality. The native owner verifies MAC, exact login,
 -- backend/transaction/event/phase, live identity and current installed worker.
 SELECT * INTO STRICT admitted FROM openpc.notification_completion_phase_binding(event,phase);
 IF admitted.installation_digest IS DISTINCT FROM installation OR admitted.authority_digest IS DISTINCT FROM authority
 THEN RAISE EXCEPTION 'COMPLETION-EFFECT-BINDING'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.check_notification_completion_effect_binding(uuid,text,text,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_phase_source(event uuid,phase text) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE binding record; current_worker control.installed_notification_completion_worker%ROWTYPE;
 original control.notification_delivery_outcome%ROWTYPE;producer control.installed_notification_worker%ROWTYPE;producer_profile jsonb;
BEGIN
 SELECT * INTO STRICT binding FROM openpc.notification_completion_phase_binding(event,phase);
 SELECT * INTO STRICT current_worker FROM control.installed_notification_completion_worker WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND installation_digest=binding.installation_digest AND state='ACTIVE';
 SELECT * INTO STRICT original FROM control.notification_delivery_outcome WHERE participant_id=current_worker.participant_id
  AND privacy_domain_id=current_worker.privacy_domain_id AND receipt_id=event;
 PERFORM openpc.check_notification_completion_source_origin(event,original.receipt_digest);
 SELECT * INTO STRICT producer FROM control.installed_notification_worker WHERE participant_id=original.participant_id
  AND privacy_domain_id=original.privacy_domain_id AND installation_digest=original.worker_installation_digest;
 producer_profile:=openpc.business_cbor(decode(producer.installation->'signed'->>'payloadHex','hex'));
 IF producer_profile->'16' IS DISTINCT FROM openpc.business_bytes(decode(substr(current_worker.producer_trust_digest,8),'hex'))
 OR current_worker.installation->'pins'->>'environmentId' IS DISTINCT FROM producer.installation->'pins'->>'environmentId'
 OR original.transition->'receipt'->>'environmentId' IS DISTINCT FROM current_worker.installation->'pins'->>'environmentId'
 THEN RAISE EXCEPTION 'COMPLETION-PHASE-PRODUCER'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.check_notification_completion_phase_source(uuid,text) FROM PUBLIC;

-- Immediate admission only: the native owner cryptographically verified these
-- exact bytes under privileged installed trust, then MAC-bound them to this
-- actual TLS transaction/event/phase. Neither framing nor phase identity suffices.
CREATE OR REPLACE FUNCTION openpc.check_notification_completion_receipt_admission(event uuid,phase text,observation jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE verified jsonb;expected jsonb;q jsonb;
 s control.notification_completion_disposition_signing%ROWTYPE;
 signer control.notification_completion_disposition_signer_installation%ROWTYPE;
 worker control.installed_notification_completion_worker%ROWTYPE;
BEGIN
 IF event IS NULL OR phase IS NULL OR phase NOT IN ('OBSERVE','PUBLISH') OR observation IS NULL
 THEN RAISE EXCEPTION 'COMPLETION-RECEIPT-ADMISSION'; END IF;
 verified:=openpc.notification_completion_verified_receipt(event,phase);
 SELECT * INTO STRICT s FROM control.notification_completion_disposition_signing WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 q:=s.preparation->'request';
 SELECT * INTO STRICT signer FROM control.notification_completion_disposition_signer_installation WHERE participant_id=s.participant_id
  AND privacy_domain_id=s.privacy_domain_id AND trust_digest=s.signer_installation_digest;
 SELECT * INTO STRICT worker FROM control.installed_notification_completion_worker WHERE participant_id=s.participant_id
  AND privacy_domain_id=s.privacy_domain_id AND installation_digest=signer.worker_installation_digest;
 IF verified IS NULL OR s.state NOT IN ('DISPATCHED','OBSERVED') OR observation->>'outcome' IS DISTINCT FROM 'SIGNED'
 OR (phase='PUBLISH' AND s.state IS DISTINCT FROM 'OBSERVED')
 OR (s.state='OBSERVED' AND observation IS DISTINCT FROM s.observation)
 OR s.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(s.preparation),'UTF8')
 OR s.preparation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(s.preparation_bytes),'hex')
 OR s.request_digest IS DISTINCT FROM s.preparation->>'requestDigest'
 OR s.request_digest IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to('pc.notification.completion-disposition-provider-request.v1','UTF8')||decode('00','hex')||convert_to(openpc.signing_canonical_json(q),'UTF8')),'hex')
 OR q->>'signerInstallationDigest' IS DISTINCT FROM signer.trust_digest
 OR q->>'signerKeyId' IS DISTINCT FROM signer.trust->>'signerKeyId'
 OR q->>'workerInstallationDigest' IS DISTINCT FROM worker.installation_digest
 OR q->>'environmentId' IS DISTINCT FROM worker.installation->'pins'->>'environmentId'
 OR q->>'dispositionPreparationDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(s.preparation->'preparation'),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'COMPLETION-RECEIPT-ADMISSION'; END IF;
 expected:=jsonb_build_object(
  'schema','pc.notification.completion-verified-receipt.v1',
  'purpose','pc.cose.notification-completion-disposition-receipt.v1',
  'requestDigest',s.request_digest,
  'preparationDigest',q->>'dispositionPreparationDigest',
  'payloadDigest','sha256:'||encode(sha256(decode(q->>'payloadHex','hex')),'hex'),
  'coseDigest','sha256:'||encode(sha256(decode(observation->>'coseHex','hex')),'hex'),
  'observationDigest','sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(observation),'UTF8')),'hex'),
  'signerInstallationDigest',signer.trust_digest,'signerKeyId',signer.trust->>'signerKeyId',
  'originalWorkerInstallationDigest',worker.installation_digest,
  'producerTrustDigest',worker.producer_trust_digest,'environmentId',worker.installation->'pins'->>'environmentId');
 IF verified IS DISTINCT FROM expected THEN RAISE EXCEPTION 'COMPLETION-RECEIPT-ADMISSION'; END IF;
END $$;
REVOKE ALL ON FUNCTION openpc.check_notification_completion_receipt_admission(uuid,text,jsonb) FROM PUBLIC;


CREATE OR REPLACE FUNCTION openpc.notification_completion_remediation_projection(item control.notification_completion_disposition) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE r jsonb:=item.transition->'receipt';w control.installed_notification_completion_worker%ROWTYPE;
BEGIN
 IF item.participant_id IS DISTINCT FROM openpc.current_participant_id() OR item.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR item.disposition IS DISTINCT FROM 'QUARANTINED' OR r->>'workItemKind' IS DISTINCT FROM 'REMEDIATION'
 OR r->>'workItemId' IS DISTINCT FROM item.receipt_id::text OR r->>'sourceEventId' IS DISTINCT FROM item.event_id::text
 THEN RAISE EXCEPTION 'COMPLETION-REMEDIATION-BINDING'; END IF;
 SELECT * INTO STRICT w FROM control.installed_notification_completion_worker
 WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=r->>'workerInstallationDigest';
 RETURN jsonb_build_object('0','REMEDIATION','1','OPEN','2','urn:openpc:resource:'||item.event_id::text,
 '3',openpc.business_bytes(sha256(item.receipt_payload)),
 '4',openpc.business_bytes(sha256(convert_to('Notification completion could not be processed.','UTF8'))),
 '5',openpc.business_uuid(w.principal_id),'6',0,'8',0,'10',0);
END $$;

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_disposition_structure(event uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE d control.notification_completion_disposition%ROWTYPE;s control.notification_completion_source%ROWTYPE;
 signing control.notification_completion_disposition_signing%ROWTYPE;e control.outbox_event%ROWTYPE;
 inbox control.notification_source_inbox%ROWTYPE;cursor_row control.notification_source_cursor%ROWTYPE;
 work control.work_item%ROWTYPE;history control.audit_occurrence%ROWTYPE;r jsonb;expected jsonb;partition_key text;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 SELECT * INTO STRICT d FROM control.notification_completion_disposition WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 SELECT * INTO STRICT s FROM control.notification_completion_source WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 SELECT * INTO STRICT signing FROM control.notification_completion_disposition_signing WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 -- Existing checker binds original producer outbox, immutable attempt chain,
 -- canonical receipt claims and observed COSE framing. It is NOT crypto proof.
 PERFORM openpc.check_notification_completion_disposition_signed(event,d.transition);
 r:=d.transition->'receipt';partition_key:='urn:openpc:resource:'||e.aggregate_id::text;
 IF d.transition_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(d.transition),'UTF8')
 OR d.transition_digest IS DISTINCT FROM 'sha256:'||encode(sha256(d.transition_bytes),'hex')
 OR d.receipt_payload IS DISTINCT FROM decode(d.transition->>'payloadHex','hex') OR d.cose_sign1 IS DISTINCT FROM decode(d.transition->>'coseHex','hex')
 OR r->>'participantId' IS DISTINCT FROM d.participant_id::text OR r->>'privacyDomainId' IS DISTINCT FROM d.privacy_domain_id::text
 OR r->>'sourceEventId' IS DISTINCT FROM event::text OR r->>'receiptId' IS DISTINCT FROM d.receipt_id::text OR r->>'operationId' IS DISTINCT FROM d.operation_id::text
 OR r->>'disposition' IS DISTINCT FROM d.disposition OR signing.state IS DISTINCT FROM 'OBSERVED'
 OR signing.operation_id IS DISTINCT FROM d.operation_id OR signing.signing_attempt_id IS DISTINCT FROM d.receipt_id
 OR signing.observation->>'outcome' IS DISTINCT FROM 'SIGNED' OR signing.observation->>'coseHex' IS DISTINCT FROM encode(d.cose_sign1,'hex')
 OR signing.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(signing.preparation),'UTF8')
 OR signing.preparation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(signing.preparation_bytes),'hex')
 OR signing.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(signing.observation),'UTF8')
 OR signing.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(signing.observation_bytes),'hex')
 OR s.source_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(s.source),'UTF8')
 OR s.source_digest IS DISTINCT FROM 'sha256:'||encode(sha256(s.source_bytes),'hex')
 OR s.source->'envelope' IS DISTINCT FROM openpc.notification_completion_source_envelope(e)
 OR s.original_selector IS DISTINCT FROM s.source->'originalSelector'
 OR e.business_sequence IS DISTINCT FROM 1 OR e.aggregate_type IS DISTINCT FROM 'notification-occurrence'
 OR e.source IS DISTINCT FROM 'urn:openpc:service:LS-NOTIFICATION'
 THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-STRUCTURE'; END IF;
 SELECT * INTO STRICT inbox FROM control.notification_source_inbox WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
 AND subscription_id='SUB-NOTIFICATIONDELIVERYCOMPLETED-CONTROL_WORK-V1' AND event_id=event;
 IF inbox.source IS DISTINCT FROM e.source OR inbox.partition IS DISTINCT FROM partition_key OR inbox.source_sequence IS DISTINCT FROM e.business_sequence
 OR inbox.data_digest IS DISTINCT FROM s.source->'reference'->>'dataDigest' OR inbox.data_digest IS DISTINCT FROM r->>'sourceDataDigest'
 OR inbox.envelope IS DISTINCT FROM convert_to(openpc.signing_canonical_json(s.source->'envelope'),'UTF8')
 OR inbox.envelope_digest IS DISTINCT FROM 'sha256:'||encode(sha256(inbox.envelope),'hex') OR inbox.envelope_digest IS DISTINCT FROM r->>'sourceEnvelopeDigest'
 OR inbox.admission_operation_id IS DISTINCT FROM d.operation_id OR inbox.state IS DISTINCT FROM d.disposition
 OR inbox.safe_problem_code IS DISTINCT FROM (CASE d.disposition WHEN 'QUARANTINED' THEN 'PC-OPS-9001' ELSE NULL END)
 THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-INBOX'; END IF;
 IF d.disposition='ADMITTED' THEN
  IF r->>'cursorMode' IS DISTINCT FROM 'ADVANCE' OR r->>'safeProblem' IS DISTINCT FROM 'NONE'
  THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-ADMITTED'; END IF;
  -- This authentic producer's publication checker preserves an existing failure
  -- WorkItem through its original human transition history; never reset it OPEN.
  PERFORM openpc.check_notification_completion_validated_source(event);
  SELECT * INTO STRICT cursor_row FROM control.notification_source_cursor WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
   AND subscription_id=inbox.subscription_id AND source=inbox.source AND partition=inbox.partition;
  IF cursor_row.last_sequence IS DISTINCT FROM inbox.source_sequence OR cursor_row.last_event_id IS DISTINCT FROM event
   OR cursor_row.last_data_digest IS DISTINCT FROM inbox.data_digest OR cursor_row.revision<1
  THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-CURSOR'; END IF;
  IF EXISTS(SELECT 1 FROM control.work_item WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND work_item_id=d.receipt_id)
  THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-UNEXPECTED-WORK'; END IF;
 ELSIF d.disposition='QUARANTINED' THEN
  IF r->>'cursorMode' IS DISTINCT FROM 'HOLD' OR r->>'safeProblem' IS DISTINCT FROM 'PC-OPS-9001'
  THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-QUARANTINE'; END IF;
  -- HOLD permits an absent cursor or its untouched empty initial position.
  IF EXISTS(SELECT 1 FROM control.notification_source_cursor WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
   AND subscription_id=inbox.subscription_id AND source=inbox.source AND partition=inbox.partition
   AND (last_sequence<>0 OR last_event_id IS NOT NULL OR last_data_digest IS NOT NULL OR revision<>1))
  THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-CURSOR-HOLD'; END IF;
  SELECT * INTO STRICT work FROM control.work_item WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND work_item_id=d.receipt_id;
  expected:=openpc.notification_completion_remediation_projection(d);
  IF work.row_version=1 THEN
   IF openpc.work_item_business_projection(work) IS DISTINCT FROM expected THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-REMEDIATION'; END IF;
  ELSE
   SELECT * INTO STRICT history FROM control.audit_occurrence WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
    AND aggregate_type='work-item' AND aggregate_id=work.work_item_id AND before_revision=1;
   IF history.before_existence<>1 OR history.before_state_digest IS DISTINCT FROM sha256(history.before_state_preimage)
    OR history.receipt_digest IS DISTINCT FROM sha256(history.receipt_cbor)
    OR openpc.business_cbor(history.receipt_cbor)->'18' IS DISTINCT FROM jsonb_build_object('0',1,'1',1,'2',openpc.business_bytes(history.before_state_digest))
    OR openpc.business_cbor(history.before_state_preimage)->8 IS DISTINCT FROM expected
   THEN RAISE EXCEPTION 'COMPLETION-ORIGINAL-REMEDIATION-HISTORY'; END IF;
  END IF;
 ELSE RAISE EXCEPTION 'COMPLETION-ORIGINAL-DISPOSITION'; END IF;
END $$;
-- This readback never creates or renews authority. Shared-owner registration
-- must enforce the immediate exact-byte receipt guards and immutable originals.
-- Current phase rows are intentionally absent after the native callback returns.
CREATE OR REPLACE FUNCTION openpc.check_notification_completion_disposition_original(event uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.check_notification_completion_disposition_structure(event);
END $$;
REVOKE ALL ON FUNCTION openpc.check_notification_completion_disposition_original(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION openpc.notification_completion_remediation_projection(control.notification_completion_disposition),
 openpc.check_notification_completion_disposition_structure(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.guard_notification_completion_source() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE p jsonb; m jsonb;e control.outbox_event%ROWTYPE;o control.notification_delivery_outcome%ROWTYPE;start_signer text;expected_selector jsonb;current_limit numeric;binding record;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'COMPLETION-SOURCE-IMMUTABLE'; END IF;
 PERFORM openpc.require_notification_completion_disposition_authority(NEW.event_id,CASE WHEN TG_OP='INSERT' THEN 'CLAIM' ELSE 'LIMIT' END);
 PERFORM openpc.check_notification_completion_phase_source(NEW.event_id,CASE WHEN TG_OP='INSERT' THEN 'CLAIM' ELSE 'LIMIT' END);
 SELECT * INTO STRICT binding FROM openpc.notification_completion_phase_binding(NEW.event_id,CASE WHEN TG_OP='INSERT' THEN 'CLAIM' ELSE 'LIMIT' END);
 IF TG_OP='INSERT' AND NEW.initial_worker_installation_digest IS DISTINCT FROM binding.installation_digest THEN RAISE EXCEPTION 'COMPLETION-SOURCE-WORKER'; END IF;
 IF TG_OP='UPDATE' THEN
  SELECT (openpc.business_cbor(decode(installation->'signed'->>'payloadHex','hex'))->>'17')::numeric INTO STRICT current_limit FROM control.installed_notification_completion_worker WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND state='ACTIVE' AND installation_digest=binding.installation_digest;
  IF to_jsonb(OLD)-'effective_limit' IS DISTINCT FROM to_jsonb(NEW)-'effective_limit' OR NEW.effective_limit IS DISTINCT FROM least(OLD.effective_limit,current_limit) OR NEW.effective_limit<1
   OR EXISTS(SELECT 1 FROM control.notification_completion_disposition_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id)
  THEN RAISE EXCEPTION 'COMPLETION-BUDGET-IMMUTABLE'; END IF;
  RETURN NEW;
 END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('notification-completion-source:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text||':'||NEW.event_id::text,0)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 p:=NEW.source->'reference';
 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.event_id AND operation_id=e.correlation_id;
 SELECT signer_installation_digest INTO STRICT start_signer FROM control.notification_delivery_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=o.start_operation_id;
 expected_selector:=jsonb_build_object('operationId',o.operation_id::text,'signerInstallationDigest',o.signer_installation_digest,
  'worker',jsonb_build_object('participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,'installationDigest',o.worker_installation_digest),
  'original',jsonb_build_object('operationId',o.start_operation_id::text,'signerInstallationDigest',start_signer,
   'source',jsonb_build_object('notificationOccurrenceId',o.notification_occurrence_id::text,'eventId',o.transition->'input'->'observation'->'original'->'source'->>'eventId',
    'worker',jsonb_build_object('participantId',NEW.participant_id::text,'privacyDomainId',NEW.privacy_domain_id::text,'installationDigest',o.transition->'input'->'observation'->'original'->>'workerInstallationDigest'))));
 IF NEW.source->'envelope' IS DISTINCT FROM openpc.notification_completion_source_envelope(e) OR NEW.original_selector IS DISTINCT FROM expected_selector
 OR p->>'dataDigest' IS DISTINCT FROM 'sha256:'||encode(e.payload_digest,'hex') OR p->>'receiptDigest' IS DISTINCT FROM o.receipt_digest
 OR p->>'partitionDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object('source','urn:openpc:service:LS-NOTIFICATION','notificationOccurrenceId',o.notification_occurrence_id::text)),'UTF8')),'hex')
 THEN RAISE EXCEPTION 'COMPLETION-SOURCE-ORIGINAL'; END IF;
 IF NEW.source_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(NEW.source),'UTF8')
 OR NEW.source_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.source_bytes),'hex')
 OR p->>'participantId' IS DISTINCT FROM NEW.participant_id::text OR p->>'privacyDomainId' IS DISTINCT FROM NEW.privacy_domain_id::text OR p->>'eventId' IS DISTINCT FROM NEW.event_id::text
 OR NEW.source->'originalSelector' IS DISTINCT FROM NEW.original_selector
 OR p->>'envelopeDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.source->'envelope'),'UTF8')),'hex')
 OR NOT EXISTS(SELECT 1 FROM control.installed_notification_completion_worker w WHERE w.participant_id=NEW.participant_id AND w.privacy_domain_id=NEW.privacy_domain_id AND w.installation_digest=NEW.initial_worker_installation_digest AND w.installation=NEW.initial_worker AND w.state='ACTIVE')
 THEN RAISE EXCEPTION 'COMPLETION-SOURCE-BINDING'; END IF;
 m:=openpc.business_cbor(decode(NEW.initial_worker->'signed'->>'payloadHex','hex'));
 IF NEW.effective_limit IS DISTINCT FROM (m->>'17')::numeric
 OR p->>'producerTrustDigest' IS DISTINCT FROM NEW.initial_worker->'pins'->>'producerTrustDigest'
 OR NOT EXISTS(SELECT 1 FROM control.installed_notification_worker producer WHERE producer.participant_id=o.participant_id AND producer.privacy_domain_id=o.privacy_domain_id AND producer.installation_digest=o.worker_installation_digest AND openpc.business_cbor(decode(producer.installation->'signed'->>'payloadHex','hex'))->'16' IS NOT DISTINCT FROM openpc.business_bytes(decode(substr(p->>'producerTrustDigest',8),'hex')))
 THEN RAISE EXCEPTION 'COMPLETION-SOURCE-PROFILE'; END IF;
 PERFORM openpc.check_notification_completion_source_origin(NEW.event_id,p->>'receiptDigest');
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_completion_attempt() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE a jsonb;p jsonb;s control.notification_completion_source%ROWTYPE;previous control.notification_completion_attempt%ROWTYPE;n numeric;delay numeric;counted numeric;source_valid boolean;failure text;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-IMMUTABLE'; END IF;
 PERFORM openpc.require_notification_completion_disposition_authority(NEW.event_id,CASE WHEN TG_OP='INSERT' THEN 'CLAIM' ELSE 'FINISH' END);
 PERFORM openpc.check_notification_completion_phase_source(NEW.event_id,CASE WHEN TG_OP='INSERT' THEN 'CLAIM' ELSE 'FINISH' END);
 IF NOT pg_try_advisory_xact_lock(hashtextextended('notification-completion-source:'||NEW.participant_id::text||':'||NEW.privacy_domain_id::text||':'||NEW.event_id::text,0)) THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 IF EXISTS(SELECT 1 FROM control.notification_completion_disposition_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id) THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-SEALED'; END IF;
 a:=NEW.attempt;n:=floor(extract(epoch from clock_timestamp())*1000);
 IF a-ARRAY['attemptId','number','workerInstallationDigest','authorityDigest','claimedAtMs','leaseUntilMs','state','finishedAtMs','nextAttemptAtMs'] IS DISTINCT FROM '{}'::jsonb
 OR NOT a ?& ARRAY['attemptId','number','workerInstallationDigest','authorityDigest','claimedAtMs','leaseUntilMs','state','finishedAtMs','nextAttemptAtMs']
 OR a->>'attemptId' IS DISTINCT FROM NEW.attempt_id::text OR a->'number' IS DISTINCT FROM to_jsonb(NEW.number)
 OR NEW.attempt_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(a),'UTF8') OR NEW.attempt_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.attempt_bytes),'hex')
 OR (a->>'authorityDigest' ~ '^sha256:[0-9a-f]{64}$') IS DISTINCT FROM true
 OR (a->>'workerInstallationDigest' ~ '^sha256:[0-9a-f]{64}$') IS DISTINCT FROM true
 OR (jsonb_typeof(a->'claimedAtMs')='number' AND (a->>'claimedAtMs') ~ '^(0|[1-9][0-9]*)$') IS DISTINCT FROM true
 OR (jsonb_typeof(a->'leaseUntilMs')='number' AND (a->>'leaseUntilMs') ~ '^(0|[1-9][0-9]*)$') IS DISTINCT FROM true
 OR (a->>'leaseUntilMs')::numeric<=(a->>'claimedAtMs')::numeric OR (a->>'leaseUntilMs')::numeric>(a->>'claimedAtMs')::numeric+30000
 THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-BINDING'; END IF;
 SELECT * INTO STRICT s FROM control.notification_completion_source WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 p:=openpc.business_cbor(decode(s.initial_worker->'signed'->>'payloadHex','hex'));
 IF TG_OP='INSERT' THEN
  PERFORM openpc.check_notification_completion_effect_binding(NEW.event_id,'CLAIM',a->>'workerInstallationDigest',a->>'authorityDigest');
  SELECT count(*) INTO counted FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
  IF NEW.number<>counted+1 OR NEW.number>s.effective_limit OR a->>'state' IS DISTINCT FROM 'LEASED' OR a->'finishedAtMs' IS DISTINCT FROM 'null'::jsonb OR a->'nextAttemptAtMs' IS DISTINCT FROM 'null'::jsonb
   OR (a->>'claimedAtMs')::numeric>n OR (a->>'leaseUntilMs')::numeric<=n
  THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-ADMISSION'; END IF;
  IF NEW.number=1 THEN
   IF a->>'workerInstallationDigest' IS DISTINCT FROM s.initial_worker_installation_digest THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-FIRST'; END IF;
  ELSE
   SELECT * INTO STRICT previous FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id AND number=NEW.number-1;
   IF previous.attempt->>'state' NOT IN ('FAILED','RELEASED') OR (a->>'claimedAtMs')::numeric<(previous.attempt->>'nextAttemptAtMs')::numeric THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-BACKOFF'; END IF;
  END IF;
 ELSE
  IF to_jsonb(OLD)-ARRAY['attempt','attempt_bytes','attempt_digest'] IS DISTINCT FROM to_jsonb(NEW)-ARRAY['attempt','attempt_bytes','attempt_digest']
   OR OLD.attempt-ARRAY['state','finishedAtMs','nextAttemptAtMs'] IS DISTINCT FROM a-ARRAY['state','finishedAtMs','nextAttemptAtMs'] OR OLD.attempt->>'state' IS DISTINCT FROM 'LEASED'
   OR a->>'state' NOT IN ('VALIDATED','FAILED','RELEASED') OR (jsonb_typeof(a->'finishedAtMs')='number' AND (a->>'finishedAtMs') ~ '^(0|[1-9][0-9]*)$') IS DISTINCT FROM true
   OR (a->>'finishedAtMs')::numeric<(a->>'claimedAtMs')::numeric OR (a->>'finishedAtMs')::numeric>n
  THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-TRANSITION'; END IF;
  IF n<(OLD.attempt->>'leaseUntilMs')::numeric THEN
   PERFORM openpc.check_notification_completion_effect_binding(NEW.event_id,'FINISH',OLD.attempt->>'workerInstallationDigest',OLD.attempt->>'authorityDigest');
  END IF;
  IF a->>'state'='VALIDATED' THEN
   IF a->'nextAttemptAtMs' IS DISTINCT FROM 'null'::jsonb OR n>=(a->>'leaseUntilMs')::numeric OR (a->>'finishedAtMs')::numeric>=(a->>'leaseUntilMs')::numeric THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-EXPIRED'; END IF;
   PERFORM openpc.check_notification_completion_validated_source(NEW.event_id);
  ELSE
   IF a->>'state'='FAILED' AND (a->>'finishedAtMs')::numeric<(a->>'leaseUntilMs')::numeric THEN
    source_valid:=true;
    BEGIN
     PERFORM openpc.check_notification_completion_validated_source(NEW.event_id);
    EXCEPTION WHEN SQLSTATE 'P0001' THEN
     GET STACKED DIAGNOSTICS failure=MESSAGE_TEXT;
     IF failure NOT LIKE 'NOTIFICATION-OUTCOME-PUBLICATION-%' THEN RAISE; END IF;
     source_valid:=false;
    END;
    IF source_valid THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-FALSE-FAILURE'; END IF;
   END IF;
   delay:=least((p->>'19')::numeric,(p->>'18')::numeric*power(2,least(NEW.number-1,52)));
   IF a->'nextAttemptAtMs' IS DISTINCT FROM to_jsonb((a->>'finishedAtMs')::numeric+delay) THEN RAISE EXCEPTION 'COMPLETION-ATTEMPT-RETRY'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_completion_signing() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE phase text;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'COMPLETION-SIGNING-IMMUTABLE'; END IF;
 phase:=CASE WHEN TG_OP='INSERT' THEN 'PREPARE' WHEN NEW.state='DISPATCHED' THEN 'SIGN_CLAIM' ELSE 'OBSERVE' END;
 PERFORM openpc.require_notification_completion_disposition_authority(NEW.event_id,phase);
 PERFORM openpc.check_notification_completion_phase_source(NEW.event_id,phase);
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'PREPARED' THEN RAISE EXCEPTION 'COMPLETION-SIGNING-INITIAL'; END IF;
  PERFORM openpc.check_notification_completion_signing_current(NEW.event_id,NEW.preparation,phase);
 ELSE
  IF to_jsonb(OLD)-ARRAY['state','dispatch_token','dispatched_at_ms','observation','observation_bytes','observation_digest'] IS DISTINCT FROM to_jsonb(NEW)-ARRAY['state','dispatch_token','dispatched_at_ms','observation','observation_bytes','observation_digest']
   OR NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED') OR (OLD.state='DISPATCHED' AND NEW.state='OBSERVED' AND NEW.dispatch_token=OLD.dispatch_token AND NEW.dispatched_at_ms=OLD.dispatched_at_ms))
  THEN RAISE EXCEPTION 'COMPLETION-SIGNING-TRANSITION'; END IF;
  IF NEW.state='DISPATCHED' THEN
   PERFORM openpc.check_notification_completion_signing_current(NEW.event_id,NEW.preparation,phase);
   IF NEW.dispatched_at_ms IS DISTINCT FROM floor(extract(epoch from clock_timestamp())*1000) AND (NEW.dispatched_at_ms>(extract(epoch from clock_timestamp())*1000) OR NEW.dispatched_at_ms<(NEW.preparation->'preparation'->'metadata'->>'recordedAtMs')::numeric) THEN RAISE EXCEPTION 'COMPLETION-SIGNING-DISPATCH-TIME'; END IF;
  END IF;
  IF NEW.state='OBSERVED' THEN
   IF NEW.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(NEW.observation),'UTF8')
    OR NEW.observation_digest IS DISTINCT FROM 'sha256:'||encode(sha256(NEW.observation_bytes),'hex') THEN RAISE EXCEPTION 'COMPLETION-SIGNING-OBSERVATION'; END IF;
   PERFORM openpc.check_notification_completion_signing_observation(NEW.event_id,NEW.observation);
   IF NEW.observation->>'outcome'='SIGNED' THEN
    PERFORM openpc.check_notification_completion_receipt_admission(NEW.event_id,'OBSERVE',NEW.observation);
   END IF;
  END IF;
 END IF;
 IF NEW.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(NEW.preparation),'UTF8') OR NEW.request_digest IS DISTINCT FROM NEW.preparation->>'requestDigest'
 OR NEW.operation_id::text IS DISTINCT FROM NEW.preparation->'request'->>'operationId' OR NEW.signing_attempt_id::text IS DISTINCT FROM NEW.preparation->'request'->>'signingAttemptId'
 OR NEW.signer_installation_digest IS DISTINCT FROM NEW.preparation->'request'->>'signerInstallationDigest' OR NEW.event_id::text IS DISTINCT FROM NEW.preparation->'request'->>'sourceEventId'
 THEN RAISE EXCEPTION 'COMPLETION-SIGNING-BINDING'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.guard_notification_completion_disposition() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'COMPLETION-DISPOSITION-IMMUTABLE'; END IF;
 PERFORM openpc.require_notification_completion_disposition_authority(NEW.event_id,'PUBLISH');
 PERFORM openpc.check_notification_completion_phase_source(NEW.event_id,'PUBLISH');
 IF NEW.transition_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(NEW.transition),'UTF8')
 OR NEW.transition->'receipt'->>'sourceEventId' IS DISTINCT FROM NEW.event_id::text
 OR NEW.transition->'receipt'->>'operationId' IS DISTINCT FROM NEW.operation_id::text OR NEW.transition->'receipt'->>'receiptId' IS DISTINCT FROM NEW.receipt_id::text
 OR NEW.transition->'receipt'->>'disposition' IS DISTINCT FROM NEW.disposition
 OR NEW.receipt_payload IS DISTINCT FROM decode(NEW.transition->>'payloadHex','hex') OR NEW.cose_sign1 IS DISTINCT FROM decode(NEW.transition->>'coseHex','hex')
 THEN RAISE EXCEPTION 'COMPLETION-DISPOSITION-BINDING'; END IF;
 PERFORM openpc.check_notification_completion_disposition_signed(NEW.event_id,NEW.transition);
 PERFORM openpc.check_notification_completion_receipt_admission(NEW.event_id,'PUBLISH',
  (SELECT observation FROM control.notification_completion_disposition_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id));
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.complete_notification_completion_disposition() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN PERFORM openpc.check_notification_completion_disposition_original(NEW.event_id);RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION openpc.complete_notification_completion_source() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE c integer;first_attempt jsonb;
BEGIN
 SELECT count(*) INTO c FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 SELECT attempt INTO STRICT first_attempt FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id AND number=1;
 IF c<1 OR first_attempt->>'workerInstallationDigest' IS DISTINCT FROM NEW.initial_worker_installation_digest THEN RAISE EXCEPTION 'COMPLETION-SOURCE-FIRST-ATTEMPT'; END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION openpc.reject_notification_completion_truncate() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN RAISE EXCEPTION 'COMPLETION-DISPOSITION-IMMUTABLE';END $$;

DROP TRIGGER IF EXISTS notification_completion_source_guard ON control.notification_completion_source;
CREATE TRIGGER notification_completion_source_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_completion_source FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_completion_source();
DROP TRIGGER IF EXISTS notification_completion_source_truncate ON control.notification_completion_source;
CREATE TRIGGER notification_completion_source_truncate BEFORE TRUNCATE ON control.notification_completion_source FOR EACH STATEMENT EXECUTE FUNCTION openpc.reject_notification_completion_truncate();
REVOKE ALL ON FUNCTION openpc.guard_notification_completion_source() FROM PUBLIC;

DROP TRIGGER IF EXISTS notification_completion_attempt_guard ON control.notification_completion_attempt;
CREATE TRIGGER notification_completion_attempt_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_completion_attempt FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_completion_attempt();
DROP TRIGGER IF EXISTS notification_completion_attempt_truncate ON control.notification_completion_attempt;
CREATE TRIGGER notification_completion_attempt_truncate BEFORE TRUNCATE ON control.notification_completion_attempt FOR EACH STATEMENT EXECUTE FUNCTION openpc.reject_notification_completion_truncate();
REVOKE ALL ON FUNCTION openpc.guard_notification_completion_attempt() FROM PUBLIC;

DROP TRIGGER IF EXISTS notification_completion_disposition_signing_guard ON control.notification_completion_disposition_signing;
CREATE TRIGGER notification_completion_disposition_signing_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_completion_disposition_signing FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_completion_signing();
DROP TRIGGER IF EXISTS notification_completion_disposition_signing_truncate ON control.notification_completion_disposition_signing;
CREATE TRIGGER notification_completion_disposition_signing_truncate BEFORE TRUNCATE ON control.notification_completion_disposition_signing FOR EACH STATEMENT EXECUTE FUNCTION openpc.reject_notification_completion_truncate();
REVOKE ALL ON FUNCTION openpc.guard_notification_completion_signing() FROM PUBLIC;

DROP TRIGGER IF EXISTS notification_completion_disposition_guard ON control.notification_completion_disposition;
CREATE TRIGGER notification_completion_disposition_guard BEFORE INSERT OR UPDATE OR DELETE ON control.notification_completion_disposition FOR EACH ROW EXECUTE FUNCTION openpc.guard_notification_completion_disposition();
DROP TRIGGER IF EXISTS notification_completion_disposition_truncate ON control.notification_completion_disposition;
CREATE TRIGGER notification_completion_disposition_truncate BEFORE TRUNCATE ON control.notification_completion_disposition FOR EACH STATEMENT EXECUTE FUNCTION openpc.reject_notification_completion_truncate();
REVOKE ALL ON FUNCTION openpc.guard_notification_completion_disposition() FROM PUBLIC;

DROP TRIGGER IF EXISTS notification_completion_source_first ON control.notification_completion_source;
CREATE CONSTRAINT TRIGGER notification_completion_source_first AFTER INSERT ON control.notification_completion_source DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.complete_notification_completion_source();
REVOKE ALL ON FUNCTION openpc.complete_notification_completion_source() FROM PUBLIC;
DROP TRIGGER IF EXISTS notification_completion_disposition_complete ON control.notification_completion_disposition;
CREATE CONSTRAINT TRIGGER notification_completion_disposition_complete AFTER INSERT ON control.notification_completion_disposition DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION openpc.complete_notification_completion_disposition();
REVOKE ALL ON FUNCTION openpc.complete_notification_completion_disposition() FROM PUBLIC;
REVOKE ALL ON FUNCTION openpc.reject_notification_completion_truncate() FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.publish_notification_completion_disposition_effects(event uuid) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE d control.notification_completion_disposition%ROWTYPE;
 signing control.notification_completion_disposition_signing%ROWTYPE;
 s control.notification_completion_source%ROWTYPE;e control.outbox_event%ROWTYPE;
 inbox control.notification_source_inbox%ROWTYPE;cursor_row control.notification_source_cursor%ROWTYPE;
 worker control.installed_notification_completion_worker%ROWTYPE;
 has_inbox boolean;has_cursor boolean;partition_key text;envelope_bytes bytea;problem text;
 subscription constant text:='SUB-NOTIFICATIONDELIVERYCOMPLETED-CONTROL_WORK-V1';
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF event IS NULL THEN RAISE EXCEPTION 'COMPLETION-PUBLICATION-EVENT'; END IF;
 -- Same source fence as preparation, observation, publication and recovery.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('notification-completion-source:'||openpc.current_participant_id()::text||':'||openpc.current_privacy_domain_id()::text||':'||event::text,0))
 THEN RAISE EXCEPTION 'PC-DATA-6007'; END IF;
 SELECT * INTO STRICT d FROM control.notification_completion_disposition WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 SELECT * INTO STRICT signing FROM control.notification_completion_disposition_signing WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 -- Consume actual current TLS/event/phase admission and the exact canonical
 -- cryptographically verified observation before either replay or mutation.
 PERFORM openpc.check_notification_completion_phase_source(event,'PUBLISH');
 PERFORM openpc.check_notification_completion_receipt_admission(event,'PUBLISH',signing.observation);
 PERFORM openpc.check_notification_completion_disposition_signed(event,d.transition);
 SELECT * INTO STRICT s FROM control.notification_completion_source WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 partition_key:='urn:openpc:resource:'||e.aggregate_id::text;
 envelope_bytes:=convert_to(openpc.signing_canonical_json(s.source->'envelope'),'UTF8');
 problem:=CASE d.disposition WHEN 'QUARANTINED' THEN 'PC-OPS-9001' ELSE NULL END;
 IF d.disposition NOT IN ('ADMITTED','QUARANTINED')
 OR d.transition_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(d.transition),'UTF8')
 OR d.transition_digest IS DISTINCT FROM 'sha256:'||encode(sha256(d.transition_bytes),'hex')
 OR d.receipt_payload IS DISTINCT FROM decode(signing.preparation->'request'->>'payloadHex','hex')
 OR d.cose_sign1 IS DISTINCT FROM decode(signing.observation->>'coseHex','hex')
 OR d.operation_id IS DISTINCT FROM signing.operation_id OR d.receipt_id IS DISTINCT FROM signing.signing_attempt_id
 OR d.disposition IS DISTINCT FROM d.transition->'receipt'->>'disposition'
 OR s.source_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(s.source),'UTF8')
 OR s.source_digest IS DISTINCT FROM 'sha256:'||encode(sha256(s.source_bytes),'hex')
 OR s.original_selector IS DISTINCT FROM s.source->'originalSelector'
 OR s.source->'envelope' IS DISTINCT FROM openpc.notification_completion_source_envelope(e)
 OR s.source->'reference'->>'envelopeDigest' IS DISTINCT FROM 'sha256:'||encode(sha256(envelope_bytes),'hex')
 OR s.source->'reference'->>'dataDigest' IS DISTINCT FROM 'sha256:'||encode(e.payload_digest,'hex')
 OR e.source IS DISTINCT FROM 'urn:openpc:service:LS-NOTIFICATION' OR e.aggregate_type IS DISTINCT FROM 'notification-occurrence' OR e.business_sequence IS DISTINCT FROM 1
 THEN RAISE EXCEPTION 'COMPLETION-PUBLICATION-ORIGINAL'; END IF;
 SELECT * INTO inbox FROM control.notification_source_inbox WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
  AND subscription_id=subscription AND event_id=event FOR UPDATE;
 has_inbox:=FOUND;
 IF has_inbox THEN
  IF inbox.source IS DISTINCT FROM e.source OR inbox.partition IS DISTINCT FROM partition_key OR inbox.source_sequence IS DISTINCT FROM e.business_sequence
  OR inbox.data_digest IS DISTINCT FROM s.source->'reference'->>'dataDigest'
  OR inbox.envelope IS DISTINCT FROM envelope_bytes OR inbox.envelope_digest IS DISTINCT FROM s.source->'reference'->>'envelopeDigest'
  THEN RAISE EXCEPTION 'COMPLETION-PUBLICATION-INBOX'; END IF;
  IF inbox.state IN ('ADMITTED','QUARANTINED') THEN
   -- A terminal inbox is a replay only when every original effect still binds.
   -- Never repair a partial publication, reset human work, or advance twice.
   PERFORM openpc.check_notification_completion_disposition_original(event);
   PERFORM openpc.check_notification_completion_receipt_admission(event,'PUBLISH',signing.observation);
   RETURN;
  END IF;
  IF inbox.state IS DISTINCT FROM 'PENDING' OR inbox.admission_operation_id IS NOT NULL OR inbox.safe_problem_code IS NOT NULL
  THEN RAISE EXCEPTION 'COMPLETION-PUBLICATION-INBOX'; END IF;
 END IF;
 SELECT * INTO cursor_row FROM control.notification_source_cursor WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
  AND subscription_id=subscription AND source=e.source AND partition=partition_key FOR UPDATE;
 has_cursor:=FOUND;
 IF has_cursor AND (cursor_row.last_sequence IS DISTINCT FROM 0 OR cursor_row.last_event_id IS NOT NULL OR cursor_row.last_data_digest IS NOT NULL OR cursor_row.revision IS DISTINCT FROM 1)
 THEN RAISE EXCEPTION 'COMPLETION-PUBLICATION-CURSOR'; END IF;
 IF EXISTS(SELECT 1 FROM control.work_item WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND work_item_id=d.receipt_id)
 THEN RAISE EXCEPTION 'COMPLETION-PUBLICATION-PARTIAL-WORK'; END IF;
 IF d.disposition='ADMITTED' THEN
  PERFORM openpc.check_notification_completion_validated_source(event);
 ELSE
  -- Historical creator belongs to the immutable original receipt. The current
  -- publisher's independent authority cannot rewrite that recorded identity.
  PERFORM openpc.notification_completion_remediation_projection(d);
  SELECT * INTO STRICT worker FROM control.installed_notification_completion_worker WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
   AND installation_digest=d.transition->'receipt'->>'workerInstallationDigest';
 END IF;
 IF has_inbox THEN
  UPDATE control.notification_source_inbox SET state=d.disposition,safe_problem_code=problem,admission_operation_id=d.operation_id
   WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND subscription_id=subscription AND event_id=event AND state='PENDING';
  IF NOT FOUND THEN RAISE EXCEPTION 'COMPLETION-PUBLICATION-INBOX'; END IF;
 ELSE
  INSERT INTO control.notification_source_inbox(participant_id,privacy_domain_id,subscription_id,event_id,source,partition,source_sequence,data_digest,envelope_digest,envelope,state,safe_problem_code,admission_operation_id)
   VALUES(d.participant_id,d.privacy_domain_id,subscription,event,e.source,partition_key,e.business_sequence,s.source->'reference'->>'dataDigest',s.source->'reference'->>'envelopeDigest',envelope_bytes,d.disposition,problem,d.operation_id);
 END IF;
 IF d.disposition='ADMITTED' THEN
  IF has_cursor THEN
   UPDATE control.notification_source_cursor SET last_sequence=e.business_sequence,last_event_id=event,last_data_digest=s.source->'reference'->>'dataDigest',revision=revision+1
    WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND subscription_id=subscription AND source=e.source AND partition=partition_key
     AND last_sequence=0 AND last_event_id IS NULL AND last_data_digest IS NULL AND revision=1;
   IF NOT FOUND THEN RAISE EXCEPTION 'COMPLETION-PUBLICATION-CURSOR'; END IF;
  ELSE
   INSERT INTO control.notification_source_cursor(participant_id,privacy_domain_id,subscription_id,source,partition,last_sequence,last_event_id,last_data_digest,revision)
    VALUES(d.participant_id,d.privacy_domain_id,subscription,e.source,partition_key,e.business_sequence,event,s.source->'reference'->>'dataDigest',1);
  END IF;
 ELSE
  -- HOLD performs no cursor mutation. Minimized remediation is the only new
  -- WorkItem; an ADMITTED producer failure WorkItem is never modified here.
  INSERT INTO control.work_item(work_item_id,participant_id,privacy_domain_id,kind,state,resource_ref,payload_digest,reason,created_by_principal_id,assignee_principal_id,claimed_by_principal_id,completed_by_principal_id,row_version)
   VALUES(d.receipt_id,d.participant_id,d.privacy_domain_id,'REMEDIATION','OPEN','urn:openpc:resource:'||event::text,sha256(d.receipt_payload),
    'Notification completion could not be processed.',worker.principal_id,NULL,NULL,NULL,1);
 END IF;
 -- Any failed completeness/currentness check propagates, rolling back every
 -- effect of this SQL statement. The caller preserves UNKNOWN on commit doubt
 -- and reconciles the original signing intent; this leaf never calls a signer.
 PERFORM openpc.check_notification_completion_disposition_original(event);
 PERFORM openpc.check_notification_completion_receipt_admission(event,'PUBLISH',signing.observation);
END $$;
REVOKE ALL ON FUNCTION openpc.publish_notification_completion_disposition_effects(uuid) FROM PUBLIC;

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_shared_publication(event uuid) RETURNS control.notification_completion_disposition
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE d control.notification_completion_disposition%ROWTYPE;s control.notification_completion_disposition_signing%ROWTYPE;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 SELECT * INTO STRICT d FROM control.notification_completion_disposition WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 SELECT * INTO STRICT s FROM control.notification_completion_disposition_signing WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 PERFORM openpc.check_notification_completion_phase_source(event,'PUBLISH');
 PERFORM openpc.check_notification_completion_receipt_admission(event,'PUBLISH',s.observation);
 PERFORM openpc.check_notification_completion_disposition_signed(event,d.transition);
 RETURN d;
END $$;

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_inbox_effect(item control.notification_source_inbox,previous control.notification_source_inbox) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE d control.notification_completion_disposition%ROWTYPE;s control.notification_completion_source%ROWTYPE;e control.outbox_event%ROWTYPE;
BEGIN
 d:=openpc.check_notification_completion_shared_publication(item.event_id);
 SELECT * INTO STRICT s FROM control.notification_completion_source WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id;
 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=d.event_id;
 IF item.participant_id IS DISTINCT FROM d.participant_id OR item.privacy_domain_id IS DISTINCT FROM d.privacy_domain_id
 OR item.subscription_id IS DISTINCT FROM 'SUB-NOTIFICATIONDELIVERYCOMPLETED-CONTROL_WORK-V1'
 OR item.source IS DISTINCT FROM e.source OR item.partition IS DISTINCT FROM 'urn:openpc:resource:'||e.aggregate_id::text
 OR item.source_sequence IS DISTINCT FROM e.business_sequence OR item.data_digest IS DISTINCT FROM s.source->'reference'->>'dataDigest'
 OR item.envelope_digest IS DISTINCT FROM s.source->'reference'->>'envelopeDigest'
 OR item.envelope IS DISTINCT FROM convert_to(openpc.signing_canonical_json(s.source->'envelope'),'UTF8')
 THEN RAISE EXCEPTION 'COMPLETION-SHARED-INBOX-BINDING'; END IF;
 IF previous.participant_id IS NOT NULL THEN
  -- Generated operation columns are computed after BEFORE triggers. They are
  -- independently fixed by their expressions and operation-specific FKs.
  IF previous.state IS DISTINCT FROM 'PENDING' OR previous.admission_operation_id IS NOT NULL OR previous.safe_problem_code IS NOT NULL
   OR to_jsonb(previous)-ARRAY['state','safe_problem_code','admission_operation_id','occurrence_admission_operation_id','completion_admission_operation_id']
    IS DISTINCT FROM to_jsonb(item)-ARRAY['state','safe_problem_code','admission_operation_id','occurrence_admission_operation_id','completion_admission_operation_id']
   OR item.state IS DISTINCT FROM d.disposition
  THEN RAISE EXCEPTION 'COMPLETION-SHARED-INBOX-TRANSITION'; END IF;
 END IF;
 IF item.state='PENDING' THEN
  IF item.admission_operation_id IS NOT NULL OR item.safe_problem_code IS NOT NULL THEN RAISE EXCEPTION 'COMPLETION-SHARED-INBOX-PENDING'; END IF;
 ELSE
  IF item.state IS DISTINCT FROM d.disposition OR item.admission_operation_id IS DISTINCT FROM d.operation_id
   OR item.safe_problem_code IS DISTINCT FROM (CASE d.disposition WHEN 'QUARANTINED' THEN 'PC-OPS-9001' ELSE NULL END)
  THEN RAISE EXCEPTION 'COMPLETION-SHARED-INBOX-RESULT'; END IF;
 END IF;
END $$;

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_cursor_effect(item control.notification_source_cursor,previous control.notification_source_cursor) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE d control.notification_completion_disposition%ROWTYPE;i control.notification_source_inbox%ROWTYPE;
BEGIN
 d:=openpc.check_notification_completion_shared_publication(item.last_event_id);
 SELECT * INTO STRICT i FROM control.notification_source_inbox WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
  AND event_id=d.event_id AND subscription_id='SUB-NOTIFICATIONDELIVERYCOMPLETED-CONTROL_WORK-V1';
 IF d.disposition IS DISTINCT FROM 'ADMITTED' OR i.state IS DISTINCT FROM 'ADMITTED' OR i.admission_operation_id IS DISTINCT FROM d.operation_id
 OR item.participant_id IS DISTINCT FROM d.participant_id OR item.privacy_domain_id IS DISTINCT FROM d.privacy_domain_id
 OR item.subscription_id IS DISTINCT FROM i.subscription_id OR item.source IS DISTINCT FROM i.source OR item.partition IS DISTINCT FROM i.partition
 OR item.last_sequence IS DISTINCT FROM i.source_sequence OR item.last_data_digest IS DISTINCT FROM i.data_digest
 THEN RAISE EXCEPTION 'COMPLETION-SHARED-CURSOR-BINDING'; END IF;
 IF previous.participant_id IS NULL THEN
  IF item.revision IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'COMPLETION-SHARED-CURSOR-INITIAL'; END IF;
 ELSE
  IF previous.last_sequence IS DISTINCT FROM 0 OR previous.last_event_id IS NOT NULL OR previous.last_data_digest IS NOT NULL OR previous.revision IS DISTINCT FROM 1
  OR item.revision IS DISTINCT FROM 2
  OR to_jsonb(previous)-ARRAY['last_sequence','last_event_id','last_data_digest','revision'] IS DISTINCT FROM to_jsonb(item)-ARRAY['last_sequence','last_event_id','last_data_digest','revision']
  THEN RAISE EXCEPTION 'COMPLETION-SHARED-CURSOR-TRANSITION'; END IF;
 END IF;
END $$;

CREATE OR REPLACE FUNCTION openpc.check_notification_completion_remediation_effect(item control.work_item) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE event uuid;d control.notification_completion_disposition%ROWTYPE;
BEGIN
 SELECT event_id INTO STRICT event FROM control.notification_completion_disposition WHERE participant_id=openpc.current_participant_id()
  AND privacy_domain_id=openpc.current_privacy_domain_id() AND receipt_id=item.work_item_id;
 d:=openpc.check_notification_completion_shared_publication(event);
 IF item.participant_id IS DISTINCT FROM d.participant_id OR item.privacy_domain_id IS DISTINCT FROM d.privacy_domain_id
 OR item.row_version IS DISTINCT FROM 1 OR openpc.work_item_business_projection(item) IS DISTINCT FROM openpc.notification_completion_remediation_projection(d)
 THEN RAISE EXCEPTION 'COMPLETION-SHARED-REMEDIATION'; END IF;
END $$;

CREATE OR REPLACE FUNCTION openpc.complete_notification_completion_remediation() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE event uuid;
BEGIN
 SELECT event_id INTO STRICT event FROM control.notification_completion_disposition WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.work_item_id;
 PERFORM openpc.check_notification_completion_disposition_original(event);
 RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS notification_completion_remediation_complete ON control.work_item;
CREATE CONSTRAINT TRIGGER notification_completion_remediation_complete AFTER INSERT ON control.work_item
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
 WHEN (openpc.current_action_intent_id()='ACT-POLICY_READ_EFFECTIVE_ACCESS-V1' OR (NEW.kind='REMEDIATION' AND openpc.current_action_intent_id() IS DISTINCT FROM 'ACT-WORK_ITEMS_CREATE_RESOURCE-V1'))
 EXECUTE FUNCTION openpc.complete_notification_completion_remediation();

ALTER TABLE control.notification_completion_disposition_signer_installation FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification_completion_disposition_signer_installation FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader,openpc_control_platform_runtime;
GRANT SELECT ON control.notification_completion_disposition_signer_installation TO openpc_control_runtime;
ALTER TABLE control.notification_completion_source FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification_completion_source FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader,openpc_control_platform_runtime;
GRANT SELECT ON control.notification_completion_source TO openpc_control_runtime;
ALTER TABLE control.notification_completion_attempt FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification_completion_attempt FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader,openpc_control_platform_runtime;
GRANT SELECT ON control.notification_completion_attempt TO openpc_control_runtime;
ALTER TABLE control.notification_completion_disposition_signing FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification_completion_disposition_signing FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader,openpc_control_platform_runtime;
GRANT SELECT ON control.notification_completion_disposition_signing TO openpc_control_runtime;
ALTER TABLE control.notification_completion_disposition FORCE ROW LEVEL SECURITY;
REVOKE ALL ON control.notification_completion_disposition FROM PUBLIC,openpc_control_runtime,openpc_control_worker,openpc_control_reader,openpc_control_platform_runtime;
GRANT SELECT ON control.notification_completion_disposition TO openpc_control_runtime;
GRANT INSERT,UPDATE ON control.notification_completion_disposition_signer_installation TO openpc_control_owner;
DROP POLICY IF EXISTS notification_completion_signer_installer ON control.notification_completion_disposition_signer_installation;
CREATE POLICY notification_completion_signer_installer ON control.notification_completion_disposition_signer_installation TO openpc_control_owner
 USING(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id))
 WITH CHECK(openpc.matches_participant(participant_id) AND openpc.matches_privacy(privacy_domain_id));
GRANT INSERT ON control.notification_completion_source,control.notification_completion_attempt,control.notification_completion_disposition_signing,control.notification_completion_disposition TO openpc_control_runtime;
GRANT UPDATE(effective_limit) ON control.notification_completion_source TO openpc_control_runtime;
GRANT UPDATE(attempt,attempt_bytes,attempt_digest) ON control.notification_completion_attempt TO openpc_control_runtime;
GRANT UPDATE(state,dispatch_token,dispatched_at_ms,observation,observation_bytes,observation_digest) ON control.notification_completion_disposition_signing TO openpc_control_runtime;
GRANT UPDATE(state,safe_problem_code,admission_operation_id) ON control.notification_source_inbox TO openpc_control_runtime;
GRANT UPDATE(last_sequence,last_event_id,last_data_digest,revision) ON control.notification_source_cursor TO openpc_control_runtime;
REVOKE ALL ON FUNCTION openpc.guard_notification_completion_disposition_signer_installation(),openpc.guard_notification_completion_disposition_signer_truncate(),openpc.assert_notification_completion_disposition_signer_owner(),openpc.notification_completion_source_envelope(control.outbox_event),openpc.check_notification_completion_source_origin(uuid,text),openpc.check_notification_completion_validated_source(uuid),openpc.check_notification_completion_signing_preparation(uuid,jsonb),openpc.check_notification_completion_signing_current(uuid,jsonb,text),openpc.check_notification_completion_signing_observation(uuid,jsonb),openpc.check_notification_completion_disposition_signed(uuid,jsonb),openpc.check_notification_completion_effect_binding(uuid,text,text,text),openpc.check_notification_completion_phase_source(uuid,text),openpc.check_notification_completion_receipt_admission(uuid,text,jsonb),openpc.notification_completion_remediation_projection(control.notification_completion_disposition),openpc.check_notification_completion_disposition_structure(uuid),openpc.check_notification_completion_disposition_original(uuid),openpc.guard_notification_completion_source(),openpc.guard_notification_completion_attempt(),openpc.guard_notification_completion_signing(),openpc.guard_notification_completion_disposition(),openpc.complete_notification_completion_disposition(),openpc.complete_notification_completion_source(),openpc.reject_notification_completion_truncate(),openpc.publish_notification_completion_disposition_effects(uuid),openpc.check_notification_completion_shared_publication(uuid),openpc.check_notification_completion_inbox_effect(control.notification_source_inbox,control.notification_source_inbox),openpc.check_notification_completion_cursor_effect(control.notification_source_cursor,control.notification_source_cursor),openpc.check_notification_completion_remediation_effect(control.work_item),openpc.complete_notification_completion_remediation() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION openpc.assert_notification_completion_disposition_signer_owner(),openpc.notification_completion_source_envelope(control.outbox_event),openpc.check_notification_completion_source_origin(uuid,text),openpc.check_notification_completion_validated_source(uuid),openpc.check_notification_completion_signing_preparation(uuid,jsonb),openpc.check_notification_completion_signing_current(uuid,jsonb,text),openpc.check_notification_completion_signing_observation(uuid,jsonb),openpc.check_notification_completion_disposition_signed(uuid,jsonb),openpc.check_notification_completion_effect_binding(uuid,text,text,text),openpc.check_notification_completion_phase_source(uuid,text),openpc.check_notification_completion_receipt_admission(uuid,text,jsonb),openpc.notification_completion_remediation_projection(control.notification_completion_disposition),openpc.check_notification_completion_disposition_structure(uuid),openpc.check_notification_completion_disposition_original(uuid),openpc.publish_notification_completion_disposition_effects(uuid),openpc.check_notification_completion_shared_publication(uuid),openpc.check_notification_completion_inbox_effect(control.notification_source_inbox,control.notification_source_inbox),openpc.check_notification_completion_cursor_effect(control.notification_source_cursor,control.notification_source_cursor),openpc.check_notification_completion_remediation_effect(control.work_item) TO openpc_control_runtime;

CREATE OR REPLACE FUNCTION openpc.assert_notification_completion_disposition_shared_owner() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 IF current_setting('row_security')<>'on' OR current_setting('session_replication_role')<>'origin'
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid=to_regprocedure('openpc.guard_notification_completion_disposition_signer_installation()') AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql'
 AND NOT p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND NOT p.proretset AND p.prokind='f' AND p.provariadic=0 AND p.pronargdefaults=0
 AND p.proargnames IS NOT DISTINCT FROM NULL::text[]
