  ''signerInstallationDigest'',signer.trust_digest,''signerKeyId'',signer.trust->>''signerKeyId'',
  ''originalWorkerInstallationDigest'',worker.installation_digest,
  ''producerTrustDigest'',worker.producer_trust_digest,''environmentId'',worker.installation->''pins''->>''environmentId'');
 IF verified IS DISTINCT FROM expected THEN RAISE EXCEPTION ''COMPLETION-RECEIPT-ADMISSION''; END IF;
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid=to_regprocedure('openpc.notification_completion_remediation_projection(control.notification_completion_disposition)') AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql'
 AND NOT p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND NOT p.proretset AND p.prokind='f' AND p.provariadic=0 AND p.pronargdefaults=0
 AND p.proargnames IS NOT DISTINCT FROM ARRAY['item']::text[]
 AND p.provolatile='v' AND p.prorettype='jsonb'::regtype
 AND p.proconfig=ARRAY['search_path=pg_catalog'] AND p.prosrc='
DECLARE r jsonb:=item.transition->''receipt'';w control.installed_notification_completion_worker%ROWTYPE;
BEGIN
 IF item.participant_id IS DISTINCT FROM openpc.current_participant_id() OR item.privacy_domain_id IS DISTINCT FROM openpc.current_privacy_domain_id()
 OR item.disposition IS DISTINCT FROM ''QUARANTINED'' OR r->>''workItemKind'' IS DISTINCT FROM ''REMEDIATION''
 OR r->>''workItemId'' IS DISTINCT FROM item.receipt_id::text OR r->>''sourceEventId'' IS DISTINCT FROM item.event_id::text
 THEN RAISE EXCEPTION ''COMPLETION-REMEDIATION-BINDING''; END IF;
 SELECT * INTO STRICT w FROM control.installed_notification_completion_worker
 WHERE participant_id=item.participant_id AND privacy_domain_id=item.privacy_domain_id AND installation_digest=r->>''workerInstallationDigest'';
 RETURN jsonb_build_object(''0'',''REMEDIATION'',''1'',''OPEN'',''2'',''urn:openpc:resource:''||item.event_id::text,
 ''3'',openpc.business_bytes(sha256(item.receipt_payload)),
 ''4'',openpc.business_bytes(sha256(convert_to(''Notification completion could not be processed.'',''UTF8''))),
 ''5'',openpc.business_uuid(w.principal_id),''6'',0,''8'',0,''10'',0);
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid=to_regprocedure('openpc.check_notification_completion_disposition_structure(uuid)') AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql'
 AND NOT p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND NOT p.proretset AND p.prokind='f' AND p.provariadic=0 AND p.pronargdefaults=0
 AND p.proargnames IS NOT DISTINCT FROM ARRAY['event']::text[]
 AND p.provolatile='v' AND p.prorettype='void'::regtype
 AND p.proconfig=ARRAY['search_path=pg_catalog'] AND p.prosrc='
DECLARE d control.notification_completion_disposition%ROWTYPE;s control.notification_completion_source%ROWTYPE;
 signing control.notification_completion_disposition_signing%ROWTYPE;e control.outbox_event%ROWTYPE;
 inbox control.notification_source_inbox%ROWTYPE;cursor_row control.notification_source_cursor%ROWTYPE;
 work control.work_item%ROWTYPE;history control.audit_occurrence%ROWTYPE;r jsonb;expected jsonb;partition_key text;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 SELECT * INTO STRICT d FROM control.notification_completion_disposition WHERE participant_id=openpc.current_participant_id() AND privacy_domain_id=openpc.current_privacy_domain_id() AND event_id=event;
 SELECT * INTO STRICT s FROM control.notification_completion_source WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 SELECT * INTO STRICT signing FROM control.notification_completion_disposition_signing WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND event_id=event;
 -- Existing checker binds original producer outbox, immutable attempt chain,
 -- canonical receipt claims and observed COSE framing. It is NOT crypto proof.
 PERFORM openpc.check_notification_completion_disposition_signed(event,d.transition);
 r:=d.transition->''receipt'';partition_key:=''urn:openpc:resource:''||e.aggregate_id::text;
 IF d.transition_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(d.transition),''UTF8'')
 OR d.transition_digest IS DISTINCT FROM ''sha256:''||encode(sha256(d.transition_bytes),''hex'')
 OR d.receipt_payload IS DISTINCT FROM decode(d.transition->>''payloadHex'',''hex'') OR d.cose_sign1 IS DISTINCT FROM decode(d.transition->>''coseHex'',''hex'')
 OR r->>''participantId'' IS DISTINCT FROM d.participant_id::text OR r->>''privacyDomainId'' IS DISTINCT FROM d.privacy_domain_id::text
 OR r->>''sourceEventId'' IS DISTINCT FROM event::text OR r->>''receiptId'' IS DISTINCT FROM d.receipt_id::text OR r->>''operationId'' IS DISTINCT FROM d.operation_id::text
 OR r->>''disposition'' IS DISTINCT FROM d.disposition OR signing.state IS DISTINCT FROM ''OBSERVED''
 OR signing.operation_id IS DISTINCT FROM d.operation_id OR signing.signing_attempt_id IS DISTINCT FROM d.receipt_id
 OR signing.observation->>''outcome'' IS DISTINCT FROM ''SIGNED'' OR signing.observation->>''coseHex'' IS DISTINCT FROM encode(d.cose_sign1,''hex'')
 OR signing.preparation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(signing.preparation),''UTF8'')
 OR signing.preparation_digest IS DISTINCT FROM ''sha256:''||encode(sha256(signing.preparation_bytes),''hex'')
 OR signing.observation_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(signing.observation),''UTF8'')
 OR signing.observation_digest IS DISTINCT FROM ''sha256:''||encode(sha256(signing.observation_bytes),''hex'')
 OR s.source_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(s.source),''UTF8'')
 OR s.source_digest IS DISTINCT FROM ''sha256:''||encode(sha256(s.source_bytes),''hex'')
 OR s.source->''envelope'' IS DISTINCT FROM openpc.notification_completion_source_envelope(e)
 OR s.original_selector IS DISTINCT FROM s.source->''originalSelector''
 OR e.business_sequence IS DISTINCT FROM 1 OR e.aggregate_type IS DISTINCT FROM ''notification-occurrence''
 OR e.source IS DISTINCT FROM ''urn:openpc:service:LS-NOTIFICATION''
 THEN RAISE EXCEPTION ''COMPLETION-ORIGINAL-STRUCTURE''; END IF;
 SELECT * INTO STRICT inbox FROM control.notification_source_inbox WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
 AND subscription_id=''SUB-NOTIFICATIONDELIVERYCOMPLETED-CONTROL_WORK-V1'' AND event_id=event;
 IF inbox.source IS DISTINCT FROM e.source OR inbox.partition IS DISTINCT FROM partition_key OR inbox.source_sequence IS DISTINCT FROM e.business_sequence
 OR inbox.data_digest IS DISTINCT FROM s.source->''reference''->>''dataDigest'' OR inbox.data_digest IS DISTINCT FROM r->>''sourceDataDigest''
 OR inbox.envelope IS DISTINCT FROM convert_to(openpc.signing_canonical_json(s.source->''envelope''),''UTF8'')
 OR inbox.envelope_digest IS DISTINCT FROM ''sha256:''||encode(sha256(inbox.envelope),''hex'') OR inbox.envelope_digest IS DISTINCT FROM r->>''sourceEnvelopeDigest''
 OR inbox.admission_operation_id IS DISTINCT FROM d.operation_id OR inbox.state IS DISTINCT FROM d.disposition
 OR inbox.safe_problem_code IS DISTINCT FROM (CASE d.disposition WHEN ''QUARANTINED'' THEN ''PC-OPS-9001'' ELSE NULL END)
 THEN RAISE EXCEPTION ''COMPLETION-ORIGINAL-INBOX''; END IF;
 IF d.disposition=''ADMITTED'' THEN
  IF r->>''cursorMode'' IS DISTINCT FROM ''ADVANCE'' OR r->>''safeProblem'' IS DISTINCT FROM ''NONE''
  THEN RAISE EXCEPTION ''COMPLETION-ORIGINAL-ADMITTED''; END IF;
  -- This authentic producer''s publication checker preserves an existing failure
  -- WorkItem through its original human transition history; never reset it OPEN.
  PERFORM openpc.check_notification_completion_validated_source(event);
  SELECT * INTO STRICT cursor_row FROM control.notification_source_cursor WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
   AND subscription_id=inbox.subscription_id AND source=inbox.source AND partition=inbox.partition;
  IF cursor_row.last_sequence IS DISTINCT FROM inbox.source_sequence OR cursor_row.last_event_id IS DISTINCT FROM event
   OR cursor_row.last_data_digest IS DISTINCT FROM inbox.data_digest OR cursor_row.revision<1
  THEN RAISE EXCEPTION ''COMPLETION-ORIGINAL-CURSOR''; END IF;
  IF EXISTS(SELECT 1 FROM control.work_item WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND work_item_id=d.receipt_id)
  THEN RAISE EXCEPTION ''COMPLETION-ORIGINAL-UNEXPECTED-WORK''; END IF;
 ELSIF d.disposition=''QUARANTINED'' THEN
  IF r->>''cursorMode'' IS DISTINCT FROM ''HOLD'' OR r->>''safeProblem'' IS DISTINCT FROM ''PC-OPS-9001''
  THEN RAISE EXCEPTION ''COMPLETION-ORIGINAL-QUARANTINE''; END IF;
  -- HOLD permits an absent cursor or its untouched empty initial position.
  IF EXISTS(SELECT 1 FROM control.notification_source_cursor WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
   AND subscription_id=inbox.subscription_id AND source=inbox.source AND partition=inbox.partition
   AND (last_sequence<>0 OR last_event_id IS NOT NULL OR last_data_digest IS NOT NULL OR revision<>1))
  THEN RAISE EXCEPTION ''COMPLETION-ORIGINAL-CURSOR-HOLD''; END IF;
  SELECT * INTO STRICT work FROM control.work_item WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id AND work_item_id=d.receipt_id;
  expected:=openpc.notification_completion_remediation_projection(d);
  IF work.row_version=1 THEN
   IF openpc.work_item_business_projection(work) IS DISTINCT FROM expected THEN RAISE EXCEPTION ''COMPLETION-ORIGINAL-REMEDIATION''; END IF;
  ELSE
   SELECT * INTO STRICT history FROM control.audit_occurrence WHERE participant_id=d.participant_id AND privacy_domain_id=d.privacy_domain_id
    AND aggregate_type=''work-item'' AND aggregate_id=work.work_item_id AND before_revision=1;
   IF history.before_existence<>1 OR history.before_state_digest IS DISTINCT FROM sha256(history.before_state_preimage)
    OR history.receipt_digest IS DISTINCT FROM sha256(history.receipt_cbor)
    OR openpc.business_cbor(history.receipt_cbor)->''18'' IS DISTINCT FROM jsonb_build_object(''0'',1,''1'',1,''2'',openpc.business_bytes(history.before_state_digest))
    OR openpc.business_cbor(history.before_state_preimage)->8 IS DISTINCT FROM expected
   THEN RAISE EXCEPTION ''COMPLETION-ORIGINAL-REMEDIATION-HISTORY''; END IF;
  END IF;
 ELSE RAISE EXCEPTION ''COMPLETION-ORIGINAL-DISPOSITION''; END IF;
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid=to_regprocedure('openpc.check_notification_completion_disposition_original(uuid)') AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql'
 AND NOT p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND NOT p.proretset AND p.prokind='f' AND p.provariadic=0 AND p.pronargdefaults=0
 AND p.proargnames IS NOT DISTINCT FROM ARRAY['event']::text[]
 AND p.provolatile='v' AND p.prorettype='void'::regtype
 AND p.proconfig=ARRAY['search_path=pg_catalog'] AND p.prosrc='
BEGIN
 PERFORM openpc.check_notification_completion_disposition_structure(event);
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid=to_regprocedure('openpc.guard_notification_completion_source()') AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql'
 AND NOT p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND NOT p.proretset AND p.prokind='f' AND p.provariadic=0 AND p.pronargdefaults=0
 AND p.proargnames IS NOT DISTINCT FROM NULL::text[]
 AND p.provolatile='v' AND p.prorettype='trigger'::regtype
 AND p.proconfig=ARRAY['search_path=pg_catalog'] AND p.prosrc='
DECLARE p jsonb; m jsonb;e control.outbox_event%ROWTYPE;o control.notification_delivery_outcome%ROWTYPE;start_signer text;expected_selector jsonb;current_limit numeric;binding record;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF TG_OP=''DELETE'' THEN RAISE EXCEPTION ''COMPLETION-SOURCE-IMMUTABLE''; END IF;
 PERFORM openpc.require_notification_completion_disposition_authority(NEW.event_id,CASE WHEN TG_OP=''INSERT'' THEN ''CLAIM'' ELSE ''LIMIT'' END);
 PERFORM openpc.check_notification_completion_phase_source(NEW.event_id,CASE WHEN TG_OP=''INSERT'' THEN ''CLAIM'' ELSE ''LIMIT'' END);
 SELECT * INTO STRICT binding FROM openpc.notification_completion_phase_binding(NEW.event_id,CASE WHEN TG_OP=''INSERT'' THEN ''CLAIM'' ELSE ''LIMIT'' END);
 IF TG_OP=''INSERT'' AND NEW.initial_worker_installation_digest IS DISTINCT FROM binding.installation_digest THEN RAISE EXCEPTION ''COMPLETION-SOURCE-WORKER''; END IF;
 IF TG_OP=''UPDATE'' THEN
  SELECT (openpc.business_cbor(decode(installation->''signed''->>''payloadHex'',''hex''))->>''17'')::numeric INTO STRICT current_limit FROM control.installed_notification_completion_worker WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND state=''ACTIVE'' AND installation_digest=binding.installation_digest;
  IF to_jsonb(OLD)-''effective_limit'' IS DISTINCT FROM to_jsonb(NEW)-''effective_limit'' OR NEW.effective_limit IS DISTINCT FROM least(OLD.effective_limit,current_limit) OR NEW.effective_limit<1
   OR EXISTS(SELECT 1 FROM control.notification_completion_disposition_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id)
  THEN RAISE EXCEPTION ''COMPLETION-BUDGET-IMMUTABLE''; END IF;
  RETURN NEW;
 END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended(''notification-completion-source:''||NEW.participant_id::text||'':''||NEW.privacy_domain_id::text||'':''||NEW.event_id::text,0)) THEN RAISE EXCEPTION ''PC-DATA-6007''; END IF;
 p:=NEW.source->''reference'';
 SELECT * INTO STRICT e FROM control.outbox_event WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 SELECT * INTO STRICT o FROM control.notification_delivery_outcome WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND receipt_id=NEW.event_id AND operation_id=e.correlation_id;
 SELECT signer_installation_digest INTO STRICT start_signer FROM control.notification_delivery_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND operation_id=o.start_operation_id;
 expected_selector:=jsonb_build_object(''operationId'',o.operation_id::text,''signerInstallationDigest'',o.signer_installation_digest,
  ''worker'',jsonb_build_object(''participantId'',NEW.participant_id::text,''privacyDomainId'',NEW.privacy_domain_id::text,''installationDigest'',o.worker_installation_digest),
  ''original'',jsonb_build_object(''operationId'',o.start_operation_id::text,''signerInstallationDigest'',start_signer,
   ''source'',jsonb_build_object(''notificationOccurrenceId'',o.notification_occurrence_id::text,''eventId'',o.transition->''input''->''observation''->''original''->''source''->>''eventId'',
    ''worker'',jsonb_build_object(''participantId'',NEW.participant_id::text,''privacyDomainId'',NEW.privacy_domain_id::text,''installationDigest'',o.transition->''input''->''observation''->''original''->>''workerInstallationDigest''))));
 IF NEW.source->''envelope'' IS DISTINCT FROM openpc.notification_completion_source_envelope(e) OR NEW.original_selector IS DISTINCT FROM expected_selector
 OR p->>''dataDigest'' IS DISTINCT FROM ''sha256:''||encode(e.payload_digest,''hex'') OR p->>''receiptDigest'' IS DISTINCT FROM o.receipt_digest
 OR p->>''partitionDigest'' IS DISTINCT FROM ''sha256:''||encode(sha256(convert_to(openpc.signing_canonical_json(jsonb_build_object(''source'',''urn:openpc:service:LS-NOTIFICATION'',''notificationOccurrenceId'',o.notification_occurrence_id::text)),''UTF8'')),''hex'')
 THEN RAISE EXCEPTION ''COMPLETION-SOURCE-ORIGINAL''; END IF;
 IF NEW.source_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(NEW.source),''UTF8'')
 OR NEW.source_digest IS DISTINCT FROM ''sha256:''||encode(sha256(NEW.source_bytes),''hex'')
 OR p->>''participantId'' IS DISTINCT FROM NEW.participant_id::text OR p->>''privacyDomainId'' IS DISTINCT FROM NEW.privacy_domain_id::text OR p->>''eventId'' IS DISTINCT FROM NEW.event_id::text
 OR NEW.source->''originalSelector'' IS DISTINCT FROM NEW.original_selector
 OR p->>''envelopeDigest'' IS DISTINCT FROM ''sha256:''||encode(sha256(convert_to(openpc.signing_canonical_json(NEW.source->''envelope''),''UTF8'')),''hex'')
 OR NOT EXISTS(SELECT 1 FROM control.installed_notification_completion_worker w WHERE w.participant_id=NEW.participant_id AND w.privacy_domain_id=NEW.privacy_domain_id AND w.installation_digest=NEW.initial_worker_installation_digest AND w.installation=NEW.initial_worker AND w.state=''ACTIVE'')
 THEN RAISE EXCEPTION ''COMPLETION-SOURCE-BINDING''; END IF;
 m:=openpc.business_cbor(decode(NEW.initial_worker->''signed''->>''payloadHex'',''hex''));
 IF NEW.effective_limit IS DISTINCT FROM (m->>''17'')::numeric
 OR p->>''producerTrustDigest'' IS DISTINCT FROM NEW.initial_worker->''pins''->>''producerTrustDigest''
 OR NOT EXISTS(SELECT 1 FROM control.installed_notification_worker producer WHERE producer.participant_id=o.participant_id AND producer.privacy_domain_id=o.privacy_domain_id AND producer.installation_digest=o.worker_installation_digest AND openpc.business_cbor(decode(producer.installation->''signed''->>''payloadHex'',''hex''))->''16'' IS NOT DISTINCT FROM openpc.business_bytes(decode(substr(p->>''producerTrustDigest'',8),''hex'')))
 THEN RAISE EXCEPTION ''COMPLETION-SOURCE-PROFILE''; END IF;
 PERFORM openpc.check_notification_completion_source_origin(NEW.event_id,p->>''receiptDigest'');
 RETURN NEW;
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid=to_regprocedure('openpc.guard_notification_completion_attempt()') AND r.rolname='openpc_control_owner' AND l.lanname='plpgsql'
 AND NOT p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND NOT p.proretset AND p.prokind='f' AND p.provariadic=0 AND p.pronargdefaults=0
 AND p.proargnames IS NOT DISTINCT FROM NULL::text[]
 AND p.provolatile='v' AND p.prorettype='trigger'::regtype
 AND p.proconfig=ARRAY['search_path=pg_catalog'] AND p.prosrc='
DECLARE a jsonb;p jsonb;s control.notification_completion_source%ROWTYPE;previous control.notification_completion_attempt%ROWTYPE;n numeric;delay numeric;counted numeric;source_valid boolean;failure text;
BEGIN
 PERFORM openpc.assert_notification_completion_disposition_shared_owner();
 IF TG_OP=''DELETE'' THEN RAISE EXCEPTION ''COMPLETION-ATTEMPT-IMMUTABLE''; END IF;
 PERFORM openpc.require_notification_completion_disposition_authority(NEW.event_id,CASE WHEN TG_OP=''INSERT'' THEN ''CLAIM'' ELSE ''FINISH'' END);
 PERFORM openpc.check_notification_completion_phase_source(NEW.event_id,CASE WHEN TG_OP=''INSERT'' THEN ''CLAIM'' ELSE ''FINISH'' END);
 IF NOT pg_try_advisory_xact_lock(hashtextextended(''notification-completion-source:''||NEW.participant_id::text||'':''||NEW.privacy_domain_id::text||'':''||NEW.event_id::text,0)) THEN RAISE EXCEPTION ''PC-DATA-6007''; END IF;
 IF EXISTS(SELECT 1 FROM control.notification_completion_disposition_signing WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id) THEN RAISE EXCEPTION ''COMPLETION-ATTEMPT-SEALED''; END IF;
 a:=NEW.attempt;n:=floor(extract(epoch from clock_timestamp())*1000);
 IF a-ARRAY[''attemptId'',''number'',''workerInstallationDigest'',''authorityDigest'',''claimedAtMs'',''leaseUntilMs'',''state'',''finishedAtMs'',''nextAttemptAtMs''] IS DISTINCT FROM ''{}''::jsonb
 OR NOT a ?& ARRAY[''attemptId'',''number'',''workerInstallationDigest'',''authorityDigest'',''claimedAtMs'',''leaseUntilMs'',''state'',''finishedAtMs'',''nextAttemptAtMs'']
 OR a->>''attemptId'' IS DISTINCT FROM NEW.attempt_id::text OR a->''number'' IS DISTINCT FROM to_jsonb(NEW.number)
 OR NEW.attempt_bytes IS DISTINCT FROM convert_to(openpc.signing_canonical_json(a),''UTF8'') OR NEW.attempt_digest IS DISTINCT FROM ''sha256:''||encode(sha256(NEW.attempt_bytes),''hex'')
 OR (a->>''authorityDigest'' ~ ''^sha256:[0-9a-f]{64}$'') IS DISTINCT FROM true
 OR (a->>''workerInstallationDigest'' ~ ''^sha256:[0-9a-f]{64}$'') IS DISTINCT FROM true
 OR (jsonb_typeof(a->''claimedAtMs'')=''number'' AND (a->>''claimedAtMs'') ~ ''^(0|[1-9][0-9]*)$'') IS DISTINCT FROM true
 OR (jsonb_typeof(a->''leaseUntilMs'')=''number'' AND (a->>''leaseUntilMs'') ~ ''^(0|[1-9][0-9]*)$'') IS DISTINCT FROM true
 OR (a->>''leaseUntilMs'')::numeric<=(a->>''claimedAtMs'')::numeric OR (a->>''leaseUntilMs'')::numeric>(a->>''claimedAtMs'')::numeric+30000
 THEN RAISE EXCEPTION ''COMPLETION-ATTEMPT-BINDING''; END IF;
 SELECT * INTO STRICT s FROM control.notification_completion_source WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
 p:=openpc.business_cbor(decode(s.initial_worker->''signed''->>''payloadHex'',''hex''));
 IF TG_OP=''INSERT'' THEN
  PERFORM openpc.check_notification_completion_effect_binding(NEW.event_id,''CLAIM'',a->>''workerInstallationDigest'',a->>''authorityDigest'');
  SELECT count(*) INTO counted FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id;
  IF NEW.number<>counted+1 OR NEW.number>s.effective_limit OR a->>''state'' IS DISTINCT FROM ''LEASED'' OR a->''finishedAtMs'' IS DISTINCT FROM ''null''::jsonb OR a->''nextAttemptAtMs'' IS DISTINCT FROM ''null''::jsonb
   OR (a->>''claimedAtMs'')::numeric>n OR (a->>''leaseUntilMs'')::numeric<=n
  THEN RAISE EXCEPTION ''COMPLETION-ATTEMPT-ADMISSION''; END IF;
  IF NEW.number=1 THEN
   IF a->>''workerInstallationDigest'' IS DISTINCT FROM s.initial_worker_installation_digest THEN RAISE EXCEPTION ''COMPLETION-ATTEMPT-FIRST''; END IF;
  ELSE
   SELECT * INTO STRICT previous FROM control.notification_completion_attempt WHERE participant_id=NEW.participant_id AND privacy_domain_id=NEW.privacy_domain_id AND event_id=NEW.event_id AND number=NEW.number-1;
   IF previous.attempt->>''state'' NOT IN (''FAILED'',''RELEASED'') OR (a->>''claimedAtMs'')::numeric<(previous.attempt->>''nextAttemptAtMs'')::numeric THEN RAISE EXCEPTION ''COMPLETION-ATTEMPT-BACKOFF''; END IF;
  END IF;
 ELSE
  IF to_jsonb(OLD)-ARRAY[''attempt'',''attempt_bytes'',''attempt_digest''] IS DISTINCT FROM to_jsonb(NEW)-ARRAY[''attempt'',''attempt_bytes'',''attempt_digest'']
   OR OLD.attempt-ARRAY[''state'',''finishedAtMs'',''nextAttemptAtMs''] IS DISTINCT FROM a-ARRAY[''state'',''finishedAtMs'',''nextAttemptAtMs''] OR OLD.attempt->>''state'' IS DISTINCT FROM ''LEASED''
   OR a->>''state'' NOT IN (''VALIDATED'',''FAILED'',''RELEASED'') OR (jsonb_typeof(a->''finishedAtMs'')=''number'' AND (a->>''finishedAtMs'') ~ ''^(0|[1-9][0-9]*)$'') IS DISTINCT FROM true
   OR (a->>''finishedAtMs'')::numeric<(a->>''claimedAtMs'')::numeric OR (a->>''finishedAtMs'')::numeric>n
  THEN RAISE EXCEPTION ''COMPLETION-ATTEMPT-TRANSITION''; END IF;
  IF n<(OLD.attempt->>''leaseUntilMs'')::numeric THEN
   PERFORM openpc.check_notification_completion_effect_binding(NEW.event_id,''FINISH'',OLD.attempt->>''workerInstallationDigest'',OLD.attempt->>''authorityDigest'');
  END IF;
  IF a->>''state''=''VALIDATED'' THEN
   IF a->''nextAttemptAtMs'' IS DISTINCT FROM ''null''::jsonb OR n>=(a->>''leaseUntilMs'')::numeric OR (a->>''finishedAtMs'')::numeric>=(a->>''leaseUntilMs'')::numeric THEN RAISE EXCEPTION ''COMPLETION-ATTEMPT-EXPIRED''; END IF;
