 THEN RAISE EXCEPTION ''NOTIFICATION-COMPLETION-NATIVE-OWNER''; END IF;
END ')
 OR NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid='control.notification_completion_disposition_signer_installation'::regclass
 AND t.tgname='notification_completion_disposition_signer_installation_guard' AND t.tgfoid=to_regprocedure('openpc.guard_notification_completion_disposition_signer_installation()') AND t.tgtype=31
 AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND octet_length(t.tgargs)=0 AND t.tgattr=''::int2vector
 AND t.tgdeferrable=false AND t.tginitdeferred=false
 AND t.tgqual IS NULL)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid='control.notification_completion_source'::regclass
 AND t.tgname='notification_completion_source_guard' AND t.tgfoid=to_regprocedure('openpc.guard_notification_completion_source()') AND t.tgtype=31
 AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND octet_length(t.tgargs)=0 AND t.tgattr=''::int2vector
 AND t.tgdeferrable=false AND t.tginitdeferred=false
 AND t.tgqual IS NULL)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid='control.notification_completion_attempt'::regclass
 AND t.tgname='notification_completion_attempt_guard' AND t.tgfoid=to_regprocedure('openpc.guard_notification_completion_attempt()') AND t.tgtype=31
 AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND octet_length(t.tgargs)=0 AND t.tgattr=''::int2vector
 AND t.tgdeferrable=false AND t.tginitdeferred=false
 AND t.tgqual IS NULL)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid='control.notification_completion_disposition_signing'::regclass
 AND t.tgname='notification_completion_disposition_signing_guard' AND t.tgfoid=to_regprocedure('openpc.guard_notification_completion_signing()') AND t.tgtype=31
 AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND octet_length(t.tgargs)=0 AND t.tgattr=''::int2vector
 AND t.tgdeferrable=false AND t.tginitdeferred=false
 AND t.tgqual IS NULL)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid='control.notification_completion_disposition'::regclass
 AND t.tgname='notification_completion_disposition_guard' AND t.tgfoid=to_regprocedure('openpc.guard_notification_completion_disposition()') AND t.tgtype=31
 AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND octet_length(t.tgargs)=0 AND t.tgattr=''::int2vector
 AND t.tgdeferrable=false AND t.tginitdeferred=false
 AND t.tgqual IS NULL)
