 OR EXISTS(SELECT 1 FROM unnest(ARRAY['notification_completion_disposition_signer_installation','notification_completion_source','notification_completion_attempt','notification_completion_disposition_signing','notification_completion_disposition']::text[]) n(name),unnest(ARRAY['openpc_control_runtime','openpc_control_worker','openpc_control_reader','openpc_control_platform_runtime']::text[]) r(name)
